//! The type checker.
//!
//! Walks eery function body of every language file, inferring a type for
//! each expression and recording side tables the backend consults:
//!
//! * `expr_ty`: the logical type of each expression (after flow narrowing).
//! * `repr_ty`: for narrowed identifier uses, the *declared* type — the
//!   physical representation the variable is stored in.
//! * `coerce`: expressions that must be wrapped/re-wrapped into a union
//!   representation at a boundary (let/assign/return/argument/branch value).
//! * `is_tests`: how an `is` check (or `when` branch) lowers against a
//!   union representation (which sealed arms to test / null checks).
//! * `call_fn`: resolved fn targets for call sites (type-based overloads).
//!
//! The checker is deliberately lenient: anything it cannot type becomes
//! `Ty::Unknown`, which is compatible with everything and never produces
//! cascading errors. Hard errors are reserved for union/`when` misuse,
//! shadowing, widening assignments, and unresolvable overloads.

use std::collections::{HashMap, HashSet};

use salvo_syntax::ast::{self, *};
use salvo_syntax::diag::IntoMessage;
use salvo_syntax::messages::{self, Message};
use salvo_syntax::Span;

use crate::diag::FileDiagnostic;
use crate::place::{Place, Step};
use crate::program::{Program, Symbols};
use crate::decl_id::DeclId;
use crate::resolve::{DefSite, ModuleScope, Resolution};
use crate::source::ModulePath;
use crate::types::{is_subtype, FnId, FnParamContract, Qual, QualEffect, Ty};

/// [node-id] A fact's key: the declaration the node is in and the node's id
/// within it. Identity is `(decl, node)` alone; the file and the span ride
/// along as the node's origin, for a reader that places the fact (the
/// language server, `salvo facts`, a diagnostic) — they take no part in `==`
/// or `Hash`, so a key does not move when code above its declaration does.
#[derive(Clone, Copy)]
pub struct Key {
    pub decl: DeclId,
    pub node: crate::decl_id::NodeId,
    file: u32,
    /// [node-origin] The node's span.
    pub span: Span,
}

impl Key {
    pub fn new(decl: DeclId, node: crate::decl_id::NodeId, file: usize, span: Span) -> Key {
        Key { decl, node, file: file as u32, span }
    }

    /// The file the node is in.
    pub fn file(&self) -> usize {
        self.file as usize
    }

    /// What the `n` of [`Key::synthetic`] is for the `to_str` call an
    /// interpolated value implies; a predicate check's `qualifies` call is
    /// its qualifier's index (below it).
    pub const INTERP_TEXT: u32 = 63;

    /// [iter-for] The `n` of the `iter` call a `for` over a source names
    /// (`for x in c` is `next(iter(c))`), at the subject's node.
    pub const FOR_ITER: u32 = 62;

    /// [iter-for] The `n` of the `next` call a `for` names, at the subject's
    /// node: `next(c)` for an iterator, `next(iter(c))`'s for a source.
    pub const FOR_NEXT: u32 = 61;

    /// [node-id] The `n`th node the checker makes at this one, which no
    /// tree holds (a `qualifies` call an `is` test implies, the `to_str`
    /// call an interpolated value does): a key of the same declaration no
    /// written node has, recorded in the fact that needs it or derived from
    /// the node's own key by both sides alike, so nothing recomputes it
    /// differently.
    pub fn synthetic(self, n: u32) -> Key {
        debug_assert!(n < 64 && self.node.0 < (1 << 25), "[node-id] synthetic key out of range");
        Key { node: crate::decl_id::NodeId(0x8000_0000 | (self.node.0 << 6) | n), ..self }
    }
}

impl PartialEq for Key {
    fn eq(&self, other: &Self) -> bool {
        self.decl == other.decl && self.node == other.node
    }
}
impl Eq for Key {}
impl std::hash::Hash for Key {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        self.decl.hash(state);
        self.node.hash(state);
    }
}
/// By declaration, then node: the same in every run, and consistent with
/// `==` (the origin takes no part).
impl Ord for Key {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        (self.decl, self.node).cmp(&(other.decl, other.node))
    }
}
impl PartialOrd for Key {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}

/// Printed as its origin, `(file, span)`.
impl std::fmt::Debug for Key {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "({}, {:?})", self.file, self.span)
    }
}

impl crate::decl_id::DeclIndex {
    /// [node-id] The key of the node `span` holds — in its own file
    /// [node-file], else in `file`. A span no numbered node holds (made after numbering, or by `Span::to`) has no
    /// key: in a debug build that is a panic, the bug being whoever keyed
    /// it; otherwise it falls back to the file's own id and the span's
    /// start, as good a key as the span was.
    pub fn key(&self, file: usize, span: Span, hint: &std::cell::Cell<usize>) -> Key {
        // [node-file] A node keys in its own file, whichever file asks: a
        // copy of another file's node included (the file given is the
        // fallback for a tree no program tagged).
        let file = self.file_of(span).unwrap_or(file);
        match self.node_key(file, span, hint) {
            Some((decl, node)) => Key::new(decl, node, file, span),
            None => {
                debug_assert!(false, "[node-id] no numbered node holds {span:?} in file {file}");
                let decl = self.file_id(file).unwrap_or_else(|| DeclId::generated(&ModulePath(Vec::new()), &["<unnumbered>"]));
                Key::new(decl, crate::decl_id::NodeId(u32::MAX - span.start), file, span)
            }
        }
    }
}

/// [std-cache] The reusable result of checking the standard library on its
/// own, for the language server (ROADMAP §5 step 3). std occupies the leading
/// `std_files` indices of a merged program (loaded first, in sorted order), so
/// a project check can **skip** those files' bodies and read std's facts from
/// here instead — sound because every exported std fn has a total deduction
/// clause [deduce-std-explicit], which makes std's checked output a pure
/// function of std's own sources (the invariance audit, COMPLETED.md's
/// 2026-10-10 std-cache entry).
///
/// It wraps a whole `Checked` — the result of checking a **std-only** program,
/// in which every row *is* a std row — rather than a hand-picked subset. That
/// is the structural guarantee (user decision 2026-10-10, A2): the cache is a
/// real `Checked`, produced by the one real checker, so every std fact a
/// project check or a whole-program pass (`deadlock::check`) might read is
/// present and identical to a full check, with nothing to keep in sync and no
/// per-table proof of what some consumer happens to read.
#[derive(Default)]
pub struct StdCache {
    /// How many leading files of a merged program this std occupies (the skip
    /// boundary): file index `< std_files` is std, `>=` is project/dependency.
    pub std_files: usize,
    /// The std-only check. Its keys use indices `0..std_files`, which are the
    /// same leading indices std takes in the merged program (std loads first,
    /// sorted), so they transfer without remapping in the common case the
    /// language server gates on (no std shadow, project not `std = true`).
    checked: Checked,
    /// [lsp-std-front] The modules the check ran over, kept alive: the
    /// address-keyed rows above (`written_types`) are keyed by their nodes'
    /// addresses, which no other allocation can take while the cache holds
    /// them.
    modules: Vec<std::sync::Arc<Module>>,
}

impl Checked {
    /// [node-id] The key of the node `span` holds in file `file`, for a
    /// reader holding a node.
    pub fn key_at(&self, file: usize, span: Span) -> Key {
        self.decls.key(file, span, &std::cell::Cell::new(0))
    }
}

impl StdCache {
    /// Wraps the `Checked` of a std-only program (every row a std row):
    /// `checked` is `check_program` over `program`, resolved and collected
    /// as `resolution` and `symbols`.
    pub fn new<'p>(program: &'p Program, resolution: &Resolution<'p>, symbols: &Symbols<'p>, checked: Checked) -> Self {
        let _ = (resolution, symbols);
        StdCache {
            std_files: program.files.len(),
            checked,
            modules: program.modules.clone(),
        }
    }

    /// [lsp-std-front] Whether `program`'s std files hold the very modules
    /// the cache was checked over (a language server's std front). Without
    /// it, std's address-keyed rows (`written_types`) are keyed by other
    /// nodes than the program's, so what reads std's rows — emission — must
    /// not use the cache (`std_front::check_over`).
    pub fn shares_modules(&self, program: &Program) -> bool {
        self.modules.len() <= program.modules.len()
            && self.modules.iter().zip(&program.modules).all(|(a, b)| std::sync::Arc::ptr_eq(a, b))
    }

    /// Seeds a fresh round's `Checked` with std's rows: the round starts from
    /// a clone of the std-only check and project checking adds project-keyed
    /// rows on top. std rows are therefore exactly what the real checker
    /// produced, never recomputed. Project checking only writes rows at
    /// project file indices (`>= std_files`), so it never overwrites a std row.
    fn seeded(&self) -> Checked {
        self.checked.clone()
    }

    /// std's `param_mutations` rows (all of them — the cache's `Checked` is
    /// std-only), for seeding the round accumulator.
    fn std_param_mutations(&self) -> impl Iterator<Item = (&DeclId, &HashSet<String>)> {
        self.checked.param_mutations.iter()
    }

    /// std's contracts, for the contracts known before the first walk
    /// [deduce-default].
    pub(crate) fn std_deductions(&self) -> impl Iterator<Item = (&DeclId, &Vec<crate::deduce::ParamDeduction>)> {
        self.checked.deductions.iter()
    }

    /// std's parking handlers, for seeding the round accumulator that
    /// `deadlock::check` reads.
    fn std_parking_handlers(&self) -> impl Iterator<Item = &String> {
        self.checked.parking_handlers.iter()
    }
}

/// [effect-dispatch] An effect-member call, resolved.
#[derive(Clone, Debug, PartialEq)]
pub struct MemberCall {
    /// The effect's symbol key.
    pub effect: String,
    /// The member's index among the effect's `fns`.
    pub index: usize,
}

/// [fn-overload-rank] One candidate of an overload set as a possible
/// *lead*: the source of the expected types its arguments are checked
/// against. Carries the candidate's own generic names and the substitution
/// the arguments typed so far have determined
/// [call-generic-progressive].
/// [fn-rename] One `rename fn` in force: the new name, the overload it
/// means, and the name that overload no longer answers to.
struct RenameBinding<'p> {
    new_name: String,
    target: String,
    entry: crate::resolve::FnEntry<'p>,
    /// Where it was written, for the "already named" diagnostic.
    span: Span,
}

/// [fn-overload-rank] One candidate that *fits* a call: the declaration, the
/// bindings and coercion targets its match produced, and everything the
/// selection needs — the ranking view of its parameters, and the rung of the
/// visibility ladder it came in on [fn-overload-scope].
#[derive(Clone)]
struct Viable<'p> {
    key: Option<DeclId>,
    decl: &'p FnDecl,
    subst: HashMap<String, Ty>,
    /// (argument index, substituted parameter type) — what an argument is
    /// checked and *coerced* against once this candidate wins.
    pairings: Vec<(usize, Ty)>,
    rank: crate::types::RankedCandidate,
    /// The declaring module, rendered — for `@module` matching and for the
    /// diagnostics.
    module: String,
    /// [comptime-hygiene] Whether it is only visible as a stamped body's
    /// fallback to its template's file.
    template: bool,
    /// [effect-member-overload] The effect whose member this is, for a member
    /// candidate (`key` is then `None`): members and fns are one set
    /// (PIPELINE.md B3.5).
    effect: Option<&'p EffectDecl>,
}

/// [fn-overload] [effect-member-overload] A candidate for a call by name: a
/// declared fn, or a member of an effect, ranked as **one set** by one rule
/// (R10 P4, PIPELINE.md B3.5): members compete with fns, and with each other
/// across effects.
#[derive(Clone)]
enum CallCand<'p> {
    Fn(crate::resolve::FnEntry<'p>),
    Member {
        effect: &'p EffectDecl,
        decl: &'p FnDecl,
        /// The one visible instance of the effect, when there is one: its type
        /// arguments are the effect's generics at this call. With several, the
        /// arguments choose after selection [effect-disambiguation].
        instance: Option<Ty>,
    },
    /// [actor-self-send] [actor-mixed-handler] A member of the enclosing
    /// handler itself — the target of a self-send, a servant send or a member
    /// mint (PIPELINE.md B3.7). Its handler's generics are the context's,
    /// not the call's to infer.
    Own { handler: &'p ast::HandlerDecl, decl: &'p FnDecl },
}

impl<'p> CallCand<'p> {
    fn decl(&self) -> &'p FnDecl {
        match self {
            CallCand::Fn(e) => e.decl,
            CallCand::Member { decl, .. } | CallCand::Own { decl, .. } => decl,
        }
    }

    fn key(&self) -> Option<DeclId> {
        match self {
            CallCand::Fn(e) => Some(e.key),
            CallCand::Member { .. } | CallCand::Own { .. } => None,
        }
    }

    fn effect(&self) -> Option<&'p EffectDecl> {
        match self {
            CallCand::Fn(_) | CallCand::Own { .. } => None,
            CallCand::Member { effect, .. } => Some(effect),
        }
    }

    /// [fn-overload-scope] A member leads a call on the footing of the
    /// module's own fns: neither types the other's lambdas by scope.
    fn rung(&self) -> crate::resolve::Rung {
        match self {
            CallCand::Fn(e) => e.rung,
            CallCand::Member { .. } | CallCand::Own { .. } => crate::resolve::Rung::Own,
        }
    }

    /// Where it comes from, as diagnostics and the `name@…` remedy name it: a
    /// fn's module, a member's effect, a handler's own member's handler.
    fn origin(&self) -> String {
        match self {
            CallCand::Fn(e) => e.module.to_string(),
            CallCand::Member { effect, .. } => effect.name.name.clone(),
            CallCand::Own { handler, .. } => handler.name.name.clone(),
        }
    }

    fn is_template(&self) -> bool {
        matches!(self, CallCand::Fn(e) if e.rung == crate::resolve::Rung::Template)
    }

    /// The type variables the call infers: the fn's generics, or a member's
    /// with its effect's.
    fn generic_names(&self) -> HashSet<String> {
        let mut out: HashSet<String> = self.decl().generics.iter().map(|g| g.name.clone()).collect();
        if let CallCand::Member { effect, .. } = self {
            out.extend(effect.generics.iter().map(|g| g.name.clone()));
        }
        out
    }
}

/// What an `@` on a call or a fn value selects.
///
/// [fn-overload-at] `size@core.list(xs)` names a **module**: only its overloads
/// compete. [fn-attached] `cmp@Person(a, b)` names a **type**: only the fns
/// `@`-scoped to it compete — the same token doing the same job one rung down,
/// which is why the canonical's declaration spelling *is* its disambiguation
/// spelling (user decision 2026-09-21).
///
/// The two are told apart by casing ([name-casing]: a module path is lowercase,
/// a type is capitalized) at the point where the name is resolved, since
/// `@Person` and `@Fs` are the same shape — an effect selector [effect-at] is
/// the third sibling, and one name cannot be both an effect and a type in one
/// scope.
#[derive(Clone, Copy)]
enum Selector<'p> {
    Module(&'p [ast::Ident]),
    Type(&'p ast::Ident),
    /// [effect-at] `m@E(x)`: that effect's members alone compete.
    Effect(&'p EffectDecl),
}

impl<'p> Selector<'p> {
    /// How it reads back in a diagnostic.
    fn render(self) -> String {
        match self {
            Selector::Module(path) => path
                .iter()
                .map(|p| p.name.as_str())
                .collect::<Vec<_>>()
                .join("."),
            Selector::Type(t) => t.name.clone(),
            Selector::Effect(e) => e.name.name.clone(),
        }
    }

    /// [doc-module] The span a module selector covers, from its first segment
    /// to its last — the range the module hover answers on.
    fn module_span(self) -> Option<Span> {
        match self {
            Selector::Module(path) => {
                let first = path.first()?;
                let last = path.last()?;
                // [node-id] Keyed as its first segment's node.
                Some(Span { end: last.span.end, ..first.span })
            }
            Selector::Type(_) | Selector::Effect(_) => None,
        }
    }
}

struct LeadCandidate {
    /// Index into the call's candidate list.
    index: usize,
    /// The declared (un-substituted) parameter patterns, per argument slot,
    /// as the ranking compares them [fn-overload-rank].
    rank: crate::types::RankedCandidate,
    generics: HashSet<String>,
    subst: HashMap<String, Ty>,
    /// [fn-overload-scope] Which rung it came in on: the lead is picked from
    /// the most specific rung, like the winner.
    rung: crate::resolve::Rung,
}

/// [op-safe-nav] What the IR builder needs to lower `base?.link`.
#[derive(Clone, Debug)]
pub struct SafeNavInfo {
    /// The subject's **first arm** — the type the link is checked against and
    /// the narrowed receiver reads at. (For a `T?` this is `T`.)
    pub inner: Ty,
    /// The arms the pick leaves behind (every arm but the first), which pass
    /// through into the result unchanged. Empty only when the subject is a
    /// bare... it never is: `?.` requires ≥2 arms. For a `T?` this is `None`.
    pub rest: Ty,
    /// The link's own result already appears among the result arms (it is
    /// optional, or its type equals a pass-through arm), so the builder must
    /// not wrap/duplicate it — the `Option<Option<T>>` guard, generalized to
    /// arm collapse [type-union-arm-identity].
    pub already_opt: bool,
    /// The subject is exactly `T | None` (first arm the value, rest just
    /// `None`): the builder keeps the canonical `None`/`Else` + `Present`
    /// shape so a backend reconstructs a native optional chain
    /// [kt-safe-nav] [rs-safe-nav]. A general union takes the rewrap shape.
    pub optional: bool,
}

/// How an `is` check (or `when` branch check) lowers at runtime against the
/// subject's *declared* representation.
#[derive(Clone, Debug)]
pub struct UnionTest {
    /// Number of non-`None` arms in the declared union (wrapper size).
    /// `1` means the nullable `T?` representation (no wrapper).
    pub size: usize,
    /// Indices (into the declared union's non-`None` arms) this check
    /// matches. Empty together with `match_none` means a null test.
    pub arms: Vec<usize>,
    /// Whether the declared union has a `None` arm (Kotlin `?` suffix).
    pub nullable: bool,
    /// True for `is None` checks (lowered to `== null`).
    pub match_none: bool,
    /// [type-literal] Value conditions on runtime arms whose declared arms
    /// were only partly matched — literals that collapsed into one arm
    /// [type-union-arm-identity]: `(arm, negate, literals)` means the value on that
    /// arm must equal one of `literals` (or, `negate`d, none of them). An arm
    /// in `arms` with no entry matches whole. `size` and `arms` are already
    /// the *runtime* union's; `size` 1 with no `None` arm means there is no
    /// wrapper at all and only the value is tested.
    pub values: Vec<(usize, bool, Vec<salvo_syntax::ast::TypeLit>)>,
}

/// [op-elvis] How a positional pick (`?:`, `??:`, `:?`, …) lowers against the
/// subject's declared union: which arms are the **picked** side, expressed as
/// indices into the subject's non-`None` value arms plus whether the `None`
/// arm itself is picked. The emitters build a test for the picked side and
/// route the rest to `rhs`.
#[derive(Clone, Debug)]
pub struct PickTest {
    /// Number of non-`None` arms in the subject's declared union.
    pub size: usize,
    /// Indices (into the non-`None` value arms) the pick keeps.
    pub value_arms: Vec<usize>,
    /// Whether the subject's `None` arm is on the picked side.
    pub picks_none: bool,
    /// Whether the subject has a `None` arm at all.
    pub nullable: bool,
}

/// [iter-protocol] [iter-for] What a `for` over an **iterator** needs from the
/// checker beyond the calls it names: which arm of `next`'s result carries an
/// element, and how the loop holds the iterator. The calls themselves — the
/// `next` that advances it and, for a source, the `iter` that mints it — are
/// ordinary call facts (`call_fn`, `implicit_args`, `local_calls`,
/// `member_calls`, …) at `Key::FOR_NEXT` and `Key::FOR_ITER` of the subject's
/// node.
#[derive(Clone, Debug)]
pub struct PassDriver {
    /// Index of the `Emitted` arm among the result's non-`None` arms
    /// [type-union-arm-identity] — positional over the *declared* type, so
    /// `Finished | Emitted T` is as valid as the usual order. Unused when
    /// `origin` is set: a hidden machine reports absence directly.
    pub emitted_arm: usize,
    /// Number of non-`None` arms, i.e. the union wrapper size. Unused when
    /// `origin` is set.
    pub arms: usize,
    /// [iter-fn] The resolved `next` is a **`yield fn`**: the subject
    /// is an *origin* struct, so the loop constructs the hidden state machine
    /// from it and drives that. `next` is the `yield fn`'s key — what the
    /// emitters name the machine after and read the handler order from — and
    /// the subject is *not* consumed, since a fresh machine is minted per
    /// loop.
    pub origin: bool,
    /// [iter-drive-in-place] The subject is a **place the enclosing fn keeps**
    /// — a `Mut` parameter its deduction list hands back, or a projection of one
    /// — so the loop advances the pass *where it lives* instead of taking it
    /// over: the position it reaches is what the caller sees next, and the
    /// release stays the caller's (a `close` here would be their
    /// use-after-close).
    ///
    /// Without this the two backends disagreed on the same program: Rust bound
    /// the subject into a local (a clone, since the parameter is a `&mut`), so
    /// the caller's pass never advanced, while Kotlin aliased it and the caller
    /// saw the new position [backend-parity].
    pub in_place: bool,
    /// [iter-mint] The type of the iterator `iter` **mints**, when the
    /// subject is a source rather than an iterator itself (`for x in bag`,
    /// which is `next(iter(bag))`): the loop calls `iter` once, before it, and
    /// drives the result. `None` when the subject *is* the iterator — and the
    /// containers a backend walks natively (a list, an array, a `Str`) record
    /// no driver at all [iter-for-native].
    pub mint: Option<Ty>,
    /// [iter-step-call] The subject is a **step call** — `for i in next(p)`,
    /// `for i in step(a, b)` — whose result is `Emitted T | Finished`: the
    /// loop re-invokes the call itself each turn until `Finished`, with its
    /// arguments (all places or literals, checked) evaluated as written. The
    /// call node carries the callee; nothing is recorded at `Key::FOR_NEXT`.
    pub step_call: bool,
}

/// A representation change the emitter must apply to an expression.
#[derive(Clone, Debug)]
pub enum Coercion {
    /// Wrap a plain value into arm `arm` (index into non-`None` arms) of
    /// the `target` union.
    ///
    /// `inner` is a representation change applied to the value *first*, and
    /// exists for one shape: a qualified union group arm `Q (A | B)` reached
    /// by a value whose qualifier list flattened (`emitted(ok("x"))`
    /// [qual-group]). Such a value is physically a bare `A`, so it must be
    /// wrapped into the inner union before the outer one.
    WrapUnion {
        target: Ty,
        arm: usize,
        inner: Option<Box<Coercion>>,
    },
    /// Re-wrap a value between two union representations (matching arms by
    /// type equality; unmatched source arms are unreachable at runtime).
    Rewrap { from: Ty, to: Ty },
    /// Wrap a bare value into an optional (`T?`-style) representation
    /// [type-nullable]. Backends whose optionals are physical wrap
    /// (`Some(...)` in Rust); backends with transparent nullability
    /// (Kotlin) treat this as a no-op.
    WrapOption { target: Ty },
    /// [type-none-unit] The `None` **value** stands in a slot whose type is
    /// the bare `None` type, so its representation is the target's *unit*
    /// value rather than an absent optional (Rust `()`, Kotlin `Unit`).
    ///
    /// `None` is spelled the same in both roles — the absent arm of a `T?`,
    /// and the sole value of the `None` type — and the two lower
    /// differently, so the choice cannot be made from the expression alone.
    /// It is made here, where the slot is known: a generic argument slot the
    /// call inferred as `None` (`ok(None)` for an `Ok None | Err E` result,
    /// `emitted(None)` for a sequence of optionals) is the shape that needs
    /// it, and emitting the optional there is target code that does not
    /// compile.
    NoneUnit,
    /// [str-drop-mut] A `Mut` qualifier is dropped here: the value is used
    /// where the plain type is required. Every other qualifier erases, so
    /// widening is free — but `Mut` is the one qualifier a backend may
    /// render as a *different type* [type-canbe-mut], and where it does
    /// (Kotlin's `Mut Str` = `StringBuilder`, which is not a `String`) the
    /// drop is a real conversion. `from` is the qualified type being
    /// dropped, so the backend can decide from its base; a backend where
    /// `Mut` erases (Rust, and Kotlin's `MutableList`) renders nothing.
    ///
    /// `then` carries the representation change that would have been
    /// recorded here anyway (a union wrap, say), because one expression has
    /// one coercion slot and both have to happen — the drop first, since
    /// the wrap is about the *plain* type.
    DropMut {
        from: Ty,
        then: Option<Box<Coercion>>,
    },
    /// [proj-opt-slot] A union with borrowed arms (`proj Mut A | B`, an
    /// optional handle) read where an owned union is expected — a kept
    /// position, which only reads: each arm of `from` is read as the arm of
    /// `to` it lands on ([`crate::types::read_arm_map`]). What an arm does
    /// is the pair: a handle read as its element (`ref Mut A` → `Mut A`), a
    /// borrow read as the value (`proj Mut A` → `A`, a `Mut` drop on the
    /// way), an owned arm lent. A backend with references builds the
    /// borrowed rendering of `to` from it; one without may ignore all but
    /// the `Mut` drops.
    BorrowAs { from: Ty, to: Ty },
}

/// The effect whose operation is non-resumptive [throw]. Declared in std
/// (`lib/std/throw.sv`, module `throw`), known by name to the compiler: it has no
/// handler
/// — `try` delimits it — and it is not threaded as an effect parameter.
pub const THROW_EFFECT: &str = "Throw";

/// [iter-fn] The name prefix of the pass type an **origin** mints at a
/// call site (user decision 2026-09-09). Not writable in Salvo source, so the
/// machine stays unnameable while being an ordinary inferred type argument; the
/// emitters name the generated machine identically, which is how a mint at an
/// argument and a `for` over the same origin agree.
pub const ORIGIN_PASS_PREFIX: &str = "__Pass_";
/// The value arm of a `try` outcome, from `std.core.result` [throw-try].
pub const OK_QUALIFIER: &str = "Ok";
/// The message arm of a `try` outcome, from module `throw` [throw-try].
pub const THROWN_QUALIFIER: &str = "Thrown";
/// [actor-spawn-expr] The handle a `spawn` produces, from `std.core.actor`:
/// known by name to the compiler because its type argument is an **effect**,
/// which is the one sanctioned exception to [effect-not-data] (user decision
/// 2026-09-15).
pub const ADDR_TYPE: &str = "Addr";
/// [actor-replyto] The linear one-shot answer token, from `std.core.actor`.
pub const REPLY_TYPE: &str = "Reply";
/// [actor-mailbox] The std struct a handler's `mailbox { … }` slot builds,
/// from `std.core.actor`: the slot is that struct's literal with the type elided.
pub const MAILBOX_TYPE: &str = "Mailbox";

/// [actor-spawn-expr] The thread pool a spawn names in its `on` clause,
/// from `std.core.actor`.
pub const POOL_TYPE: &str = "Pool";

/// [waitfor-dedicated] The provenance qualifier `thread()` mints, from
/// `std.core.actor`: a pool of one thread, which the `on` clause consumes, and
/// the only placement a `[waitfor]`-carrying handler may be spawned onto.
pub const DEDICATED_QUALIFIER: &str = "Dedicated";

/// [actor-spawn-expr] The effect an `Addr<E>` serves, or `None` for anything
/// that is not an addr. What `use addr`, a dot-call through an addr, and a spawn's
/// `use` clause all ask.
fn addr_effect(ty: &Ty) -> Option<Ty> {
    match ty.strip_quals() {
        Ty::Named { name, args } if name == ADDR_TYPE && args.len() == 1 => Some(args[0].clone()),
        _ => None,
    }
}

/// [fn-member-call] What a receiver has under the name of a dot call.
enum DotMember {
    /// A send member of the `eff[E]` (`Addr<E>`) receiver; carries E.
    Send(Ty),
    /// A visible field of a struct receiver; carries the field's type.
    Field(Ty),
}

/// One site that may throw [throw]: the `throw` operation itself, or a
/// call to a fn declaring `[Throw<M>]` that propagates one.
#[derive(Clone, Debug)]
pub struct ThrowSite {
    /// True for `throw(message)` itself; false for a call that merely
    /// propagates a throw performed further down.
    pub performs: bool,
    /// The message type at this site.
    pub message: Ty,
    /// Where the throw lands: `Some(span)` is the enclosing `try`
    /// expression's span (the innermost one [throw-try-innermost]); `None` means
    /// it propagates out of the enclosing fn, which therefore declares
    /// `[Throw<M>]`.
    pub delimiter: Option<Span>,
    /// The message type at the *landing* site: the delimiter's computed
    /// `M`, or the fn's declared one. Equal to `message` unless the target
    /// is a union of several message types (user decision 2026-09-04).
    pub target: Ty,
    /// The arm of `target` to wrap the message into, when `target` is a
    /// wrapper union. `None` when no wrapping is needed.
    pub arm: Option<usize>,
}

/// [effect-handle] One entry of the checker's effect environment: the
/// instance, whether it is a *declared* availability (a signature's or a fn
/// value's) rather than a lexical `use` binding, and whether it is spread
/// over many instances. Every entry is a handle; nothing here decides what
/// may be captured.
#[derive(Clone, Debug)]
struct EffectAvail {
    ty: Ty,
    declared: bool,
    /// [effect-any] The binding is spread over many instances (a `use` of
    /// a handler `of any E`, or a `[any E]` declaration): it satisfies a
    /// `[any E]` requirement only.
    any: bool,
}

/// [effect-alias] [effect-prereq] Where an entry of an expanded effect list
/// came from: written, a member of an alias written there, or implied by an
/// effect's prerequisites.
#[derive(Clone, Debug, PartialEq)]
enum EffectOrigin {
    Written,
    /// A member of the alias named (the outermost, as written).
    Alias(String),
    /// A prerequisite of the effect named.
    Prereq(String),
}

/// [effect-alias] [effect-prereq] One effect of a list as the program means
/// it: aliases flattened, prerequisites added (PIPELINE.md R6).
#[derive(Clone, Debug)]
struct ListedEffect {
    ty: Ty,
    any: bool,
    /// The written entry it came from.
    span: Span,
    origin: EffectOrigin,
}

/// [qual-depend] One qualifier of a predicate `is` check, with the places
/// filling its value slots: `k is KeyOf(m)` carries `name: "KeyOf"`,
/// `args: [m]`. The emitters append the places to the `qualifies` call.
#[derive(Clone, Debug, PartialEq)]
pub struct PredicateCheck {
    pub name: String,
    pub args: Vec<PredicateArg>,
    /// [qual-depend] [col-idx] Where the `qualifies` call's **implicit**
    /// arguments are recorded (`Checked::implicit_args`), when it has any:
    /// `Idx`'s `?size` is resolved at the container the test names. A
    /// synthetic key at the first value argument, one per qualifier
    /// (`Key::synthetic`) [node-id].
    pub implicits_at: Option<Key>,
}

/// [qual-depend] A place handed to a dependent `qualifies`: the source
/// spelling, plus whether its type is a Copy scalar (the Rust emitter
/// passes those by value, everything else by `&`).
#[derive(Clone, Debug, PartialEq)]
pub struct PredicateArg {
    pub path: String,
    pub copy: bool,
}

/// [actor-route-stub] The std qualifier marking a protocol member's key parameter.
const ROUTE_KEY_QUALIFIER: &str = "Key";

/// The checker's output.
#[derive(Clone, Default)]
pub struct Checked {
    /// [decl-id] Where every declaration of the checked program is: what a
    /// reader of the `DeclId`-keyed tables below asks for a key's file.
    pub decls: std::sync::Arc<crate::decl_id::DeclIndex>,
    pub expr_ty: HashMap<Key, Ty>,
    /// [op-arm-eq] An equality whose one side is a union and whose other side
    /// is a value matching exactly one of its arms, keyed by the comparison's
    /// span. The checker proved which arm, and the IR lowers it to
    /// `subject is arm && arm == value` — so `x == -1L` on a `Long?` means
    /// "present and equal to -1", a `None` (or any other arm) comparing
    /// unequal (user decision 2026-10-12). `==` is the recorded form; `!=`
    /// negates it.
    pub arm_compares: HashMap<Key, ArmCompare>,
    /// [op-promote] Operator operands widened by numeric promotion, keyed
    /// by the operand expression's span, mapped to the promoted type
    /// (`Int + Long` promotes the `Int` side to `Long`; `Float`/`Double`
    /// likewise). Read by backends whose target has no native mixed-width
    /// operators (Rust inserts `as` casts; Kotlin's own operator set
    /// already covers the mixes and ignores this).
    pub promotions: HashMap<Key, Ty>,
    /// Declared (physical) type for identifier uses whose logical type was
    /// narrowed by flow analysis.
    pub repr_ty: HashMap<Key, Ty>,
    pub coerce: HashMap<Key, Coercion>,
    /// Keyed by the span of the `is` expression or the `when` branch.
    pub is_tests: HashMap<Key, UnionTest>,
    /// [op-safe-nav] A `base?.link`, keyed by the `SafeNav` expression's span:
    /// what the IR builder needs to lower it to a short-circuiting
    /// `Switch`/`Branch` over the receiver. The checker typed the link on
    /// the **non-`None`** receiver (recorded as `inner`); `already_opt` says
    /// the link's own result is already optional, so the builder must not
    /// wrap it a second time (the old `?.` produced `Option<Option<T>>`
    /// otherwise).
    pub safe_navs: HashMap<Key, SafeNavInfo>,
    /// [when-exhaustive] `when` expressions (keyed by the `when`'s span)
    /// the checker proved cover every runtime arm of their union subject
    /// without a written `else`. The IR builder reads this to give such a
    /// `when` an explicit unreachable fallthrough arm, so that "the
    /// fallthrough is dead" is a fact in the IR rather than something each
    /// backend re-derives from the arm set.
    pub when_exhaustive: HashSet<Key>,
    /// [lsp-completion] [when-exhaustive] For each `when` with a subject (keyed
    /// by its span) whose arms could all be matched against the subject: the
    /// union arms no branch covers yet, spelled as an `is` check writes them
    /// (`Str`, `None`, `"a"`, `Ok Int`). Empty when the `when` is exhaustive.
    /// What the language server offers as the arms still to write.
    pub when_arms: HashMap<Key, Vec<String>>,
    /// Predicate-qualifier `is` checks on non-union subjects, keyed by the
    /// span of the `is` expression: the qualifier names whose `qualifies`
    /// functions must be called (conjunction), each with the places filling
    /// its value slots [qual-depend] — `k is KeyOf(m)` lowers to
    /// `KeyOf.qualifies(k, m)`.
    pub predicate_tests: HashMap<Key, Vec<PredicateCheck>>,
    /// [qual-whynot] `Q.member(args)` — a call to a qualifier's own fn
    /// (`InRange.qualifies(n, 1, 65535)`): the qualifier, the member, and the
    /// base its `of` names (which declaration of an overloaded qualifier).
    pub qual_member_calls: HashMap<Key, (String, String, Option<String>)>,
    /// Field accesses whose type is refined by a predicate-qualifier field
    /// override, keyed by the field expression span: the overridden type
    /// (the backend casts + asserts).
    pub field_casts: HashMap<Key, Ty>,
    /// Resolved fn declaration for call sites (keyed by call span).
    pub call_fn: HashMap<Key, DeclId>,
    /// [iter-protocol] How a `for` loop drives a **pass**, keyed by the span
    /// of its *subject*. Present only when the subject has a `next`, rather
    /// than being an array or a value with an `iter`. There is
    /// no call node in the AST for the emitters to look at (the driving loop
    /// is synthesized), so the overload *and* the arm identity have to be
    /// handed over here — the alternative, each emitter re-deriving the arm
    /// index from the declaration, is exactly the checker/emitter
    /// disagreement the invariants forbid.
    pub for_drivers: HashMap<Key, PassDriver>,
    /// [qual-refn] Every qualifier refinement that applies, keyed by the
    /// file a call is written in and the overload it resolves to.
    /// Scope-dependent by design: opting into a qualifier opts into what
    /// it knows, so the same callee refines differently in two files. Read
    /// by the call-site contract loop, by deduction inference, and by the
    /// language server's merged documentation [qual-refn-docs].
    pub refinements: crate::refine::Refinements,
    /// Concrete effect instance registered by each `use` statement (keyed
    /// by the statement span), with handler generics inferred from the
    /// constructor arguments (e.g. `Random<Int>` for
    /// `use CyclicRandom([1,2,3])`).
    /// [effect-handler-multi] Several entries when the handler wears several
    /// faces: a `use` binds every effect it implements, in declaration order.
    pub use_effects: HashMap<Key, Vec<Ty>>,
    /// [actor-route-stub] `use any group` sites, mapped to the protocol they route
    /// (its type key): the IR derives one `__Route_X` per routed protocol and
    /// constructs it where the program wrote the `use`.
    pub route_uses: HashMap<Key, String>,
    /// [actor-route-stub] Per actor effect (by key), each send member's
    /// `Key`-marked parameter, by member name: what the derived route
    /// hashes. Recorded at the effect, since lowering erases `Key`.
    pub route_keys: HashMap<String, HashMap<String, String>>,
    /// [actor-replyto] [effect-handle] The handlers whose members **mint** a
    /// continuation (`replyto`), by handler key: they write their parked-continuation
    /// table, which makes them stateful for the handle's purposes
    /// (`salvo_core::handler_is_stateful`) even with no declared state.
    pub parking_handlers: std::collections::HashSet<String>,
    /// [actor-protocol-hash] Every actor effect's canonical protocol hash
    /// (`crate::wire::protocol_hash`), by effect name. Computed once here so
    /// both emitters carry the same constants and the handshake (step ④)
    /// compares what the compiler computed rather than what a runtime hashed.
    pub protocol_hashes: std::collections::BTreeMap<String, String>,
    /// Effect instances resolved for a `use`d handler's *dependencies*
    /// [effect-handler-deps], in the handler's declaration order (keyed by
    /// the `use` statement span). Only present when the handler declares
    /// dependencies. Nothing consumes it since the surface became an effect
    /// list on the declaration (2026-09-14): both emitters derive the list
    /// from the declaration and resolve each entry through their own
    /// environment. Kept because it is the only record of the *resolved
    /// instance* — which is what a generic dependency would need, and both
    /// backends refuse those today.
    pub use_deps: HashMap<Key, Vec<Ty>>,
    /// [effect-with-clause] Which written `with` item satisfied which declared
    /// dependency of a `use`, in the handler's declaration order (keyed by
    /// the `use` statement span): `Some(i)` for the clause item at written
    /// index `i`, `None` for a dependency resolved from the scope. Present
    /// only when the clause supplied at least one — a partial clause is the
    /// rule (user decision 2026-09-20), so both cases coexist in one list.
    /// Parallel to the `use_deps` entry for the same span.
    pub use_with_items: HashMap<Key, Vec<Option<usize>>>,
    /// [actor-spawn-expr] The effect instance each `spawn` expression's child
    /// serves, keyed by the spawn's span — which is also the type of its
    /// value, an `Addr<E>`. The emitters' entry point for building an actor
    /// class.
    /// [effect-handler-multi] Several entries when the handler wears several
    /// faces, in declaration order — which is also the order of the addrs the
    /// spawn's tuple answers.
    pub spawn_effects: HashMap<Key, Vec<Ty>>,
    /// [actor-spawn-expr] The effect instances a spawn's `with` clause
    /// supplies for the child's dependencies, in the handler's declaration
    /// order (keyed by the spawn's span). Absent when the handler declares
    /// none. The clause items themselves stay in the AST; this records what
    /// each *resolved to*, which is what the child's construction needs.
    pub spawn_deps: HashMap<Key, Vec<Ty>>,
    /// [actor-spawn-expr] **Which clause item satisfied which declared
    /// dependency**: one index into the spawn's written `use` clause per
    /// declared dependency, in the *handler's declaration* order (keyed by
    /// the spawn's span). The two orders differ routinely — the declaration
    /// order fixes the child's provider fields and carrier arguments, the
    /// written order is what the program says — and `check_spawn` is where
    /// the matching happens, so recording it here is what keeps both
    /// emitters from re-deriving it (and from disagreeing about it).
    /// Parallel to `spawn_deps`: same length, same order.
    /// [actor-spawn-inherit] `None` marks a dependency **synthesized from the
    /// spawning scope** rather than written (user decision 2026-09-20): the
    /// emitters then supply the scope's handle where a written item would
    /// have been constructed.
    pub spawn_dep_items: HashMap<Key, Vec<Option<usize>>>,
    /// [actor-replyto] The enclosing handler's member each `replyto`
    /// delivers to, keyed by the `replyto` span. The name, because that is
    /// what identifies a continuation target; an overloaded send member is
    /// not expressible yet and will need the index instead.
    pub replyto_members: HashMap<Key, String>,
    /// [actor-mixed-handler] Façade sends: a call inside a mixed handler's
    /// sync member that names one of the handler's own `send fn` members —
    /// bare, or spelled `k@self(…)` — mapped to that member's name. The
    /// emitters lower each to an enqueue on the façade value's addr. (The
    /// same call inside a **send** member is a self-send and lives in
    /// `self_sends`: the servant enqueues on its own mailbox.)
    pub facade_sends: HashMap<Key, String>,
    /// [actor-deadlock-cycle] Handlers whose members contain a `waitfor`
    /// expression, with the site: since SH-5(d) (user decision 2026-09-19)
    /// occupancy is **inferred**, not declared, and this is the graph's
    /// input where the deleted `[waitfor]` declaration used to be.
    pub waitfor_sites: Vec<(String, Key)>,
    /// [actor-deadlock-cycle] Handler constructions inside handlers: the
    /// owner (the handler whose members will run the constructed one
    /// inline), the constructed handler's name, and the site. What lets the
    /// graph propagate "may wait" through bindings — a handler that binds a
    /// waiting handler waits, which the deleted capability's propagation
    /// used to spell.
    pub handler_constructs: Vec<(String, String, Key)>,
    /// [task-mint] The free `send fn` each *task* mint targets, keyed by the
    /// `replyto` span: a [`DeclId`] rather than a name, because a task target is
    /// resolved through the scope ladder and the emitters need the declaration
    /// the checker picked, not a name to re-resolve.
    pub replyto_tasks: HashMap<Key, DeclId>,
    /// [task-effects] The effect instances a **task mint** inherits from the
    /// minting scope, keyed by the `replyto` span and in the target's declared
    /// order — so the emitters pass one argument per entry, in the order the
    /// target's parameters expect them.
    ///
    /// Resolved here rather than in the emitters for the reason
    /// `spawn_dep_items` is: the scope ladder and the shareability rule are the
    /// checker's, and a backend re-deriving them would be a second
    /// implementation of [effect-handle].
    pub task_mint_effects: HashMap<Key, Vec<Ty>>,
    /// [actor-use-addr] The effect each `use addr` statement binds, keyed by
    /// the statement's span: the emitters generate a forwarding stub over
    /// the addr rather than constructing a handler.
    pub use_addrs: HashMap<Key, Ty>,
    /// [effect-eff-handle] `use <tuple-handle>`: the per-element effects when a
    /// `use` binds a *tuple* of single handles (`use e` where `e:
    /// (eff[A], eff[B])`). The IR binds one effect per tuple element, in
    /// order — `use e.0; use e.1` — so this carries the whole flat set.
    pub use_addr_tuples: HashMap<Key, Vec<Ty>>,
    /// [effect-eff-handle] `e[A, B]` projection: the effects projected out, in order,
    /// at the projection's span. The IR picks the matching handles out of the
    /// base (a single handle or a tuple of them) into the result.
    pub project_effects: HashMap<Key, Vec<Ty>>,
    /// [effect-eff-handle] `eff[a, b]` / `eff[*]` merge: the effects of the result
    /// handle, in order. The IR picks the carrying handle for each — from the
    /// merged items (`eff[a, b]`) or from the scope (`eff[*]`).
    pub merge_effects: HashMap<Key, Vec<Ty>>,
    /// [actor-use-addr] Dot-calls that are **sends to an actor** rather than
    /// dispatches through a handler in scope, keyed by the call span and
    /// mapped to the effect instance the addr serves. The emitters need the
    /// distinction: the same written call is a method call on a handler in one
    /// case and an enqueue on a mailbox in the other.
    pub addr_calls: HashMap<Key, Ty>,
    /// [actor-self-send] `self.k(args)` sites, keyed by the call span and
    /// mapped to the member's name: a message to the actor the enclosing
    /// member belongs to. Distinct from `addr_calls` because there is no addr to
    /// read — the target is "this actor", which each backend spells its own
    /// way (an enqueue on the running activation's own mailbox, or, under a
    /// synchronous binding, an ordinary member call).
    pub self_sends: HashMap<Key, String>,
    /// [linear-container] Reads that **move a linear value**, keyed by the
    /// read's span: the emitters must hand the value over rather than copy
    /// it. Rust's narrowed-read path clones by default (`x.as_ref()
    /// .unwrap().clone()`), which duplicates an obligation — harmless for a
    /// handle type that happens to be `Clone`, impossible for one that is not
    /// (a reply token), and wrong either way.
    pub linear_moves: HashSet<Key>,
    /// [flow-use-after-move] Reads of a bare identifier that **move the whole
    /// variable** through `fate_move` — a literal store, a `...` spread, a
    /// `use` or spawn constructor argument, a `break`/`return`/`throw`
    /// value, a send, a driven pass — keyed by the identifier's span (as
    /// `linear_moves` is). The IR reads them `consume: true`, so the flow
    /// pass sees the move and the Rust emitter moves rather than clones
    /// (the checker has consumed the variable: nothing reads it again).
    pub moved_reads: HashSet<Key>,
    /// [flow-use-after-move] The checker's moves the IR's emission does not
    /// make, for the flow pass (`moved` on the IR node): an identifier a
    /// call's contract consumes (keyed by the identifier — a fn value, which
    /// `param_mode` lends whatever the contract, or a `once` value passed
    /// on), a projection whose move took its root wholly (keyed by the
    /// projection [fate-partial-move]), and a call of a `once` local
    /// (keyed by the call [fn-once]).
    pub flow_moves: HashSet<Key>,
    /// [fate-poison] Every mutation event on a root (a `Mut` call
    /// argument, an assignment through a projection, a mutation through a
    /// handle), keyed by the span the checker gave it — the call, the
    /// assignment statement, the iterated subject — for the IR flow pass.
    pub fate_mutations: HashMap<Key, Vec<FlowMutation>>,
    /// [fate-move-mode] Every link-carrying binding, for the IR's decision
    /// of its mode: keyed by the bound name's span (a `let`, a pattern
    /// name, a `for`/`is`/`when` binding) or an assignment's target, its
    /// own span (`stamp`), every link the walk
    /// gave it (each stamped by the binding that made it: a copy of an
    /// ancestor's link carries the ancestor's), whether it *may* take
    /// ownership (`may_take_ownership`, judged where the binding is: a
    /// typing and scope fact), and the `for` loops whose binding is one of
    /// its roots (taking ownership of one makes the loop iterate by value).
    pub bind_facts: HashMap<Key, BindFact>,
    /// [fate-move-mode] [fate-derived-readonly] Every move or mutation of a
    /// fate-linked (derived) variable, by the use's span (the identifier;
    /// a mutating call; an assignment statement): the variable, the action,
    /// and the message the IR reports when its binding stays borrow-mode.
    pub derived_uses: HashMap<Key, Vec<DerivedUse>>,
    /// [deduce-field] The bindings a mutation event at a span may leave as
    /// *virtual places* (`ir::Decision::virtual_binds`): those its contents rule
    /// spares, and those a fields-declaring call leaves linked at a field
    /// path. The IR keeps the ones its flow says are still live there.
    pub virtual_candidates: HashMap<Key, Vec<VirtualCandidate>>,
    /// [fate-move-mode] The `for` loops (by iterable span) data was moved
    /// out of through a projection of the loop binding: they iterate by
    /// value, whatever any binding's mode.
    pub by_value_loops: HashSet<Key>,
    /// [linear-state] Reads of a handler **state field** that *move* the
    /// value out (LC-4's allowance: a container of obligations being drained),
    /// keyed by the read's span. Rust cannot move out of a field behind
    /// `&mut self`, so the emitter renders these as `std::mem::take` — which
    /// is the semantics too, since the checker requires the member to put
    /// something back before it returns.
    pub state_takes: HashSet<Key>,
    /// [actor-deadlock-cycle] Gated mints (`replyto!`) inside a handler's
    /// continuation is outstanding the actor serves *nothing else*, so
    /// every gate is a wait-for edge's tail — which is why the graph is
    /// keyed on these and not on `replyto`, whose continuation leaves the
    /// mailbox open.
    pub actor_gates: Vec<(String, Key)>,
    /// [actor-deadlock-cycle] Sends from inside a handler's members to a
    /// actor of another protocol: `(handler name, target effect name, the
    /// call's site)`. Recorded for dot-calls through an `Addr`; sends
    /// reached through the handler's *declared dependencies* are read off
    /// the declaration instead, and a `k@self(…)` is not here at all — a
    /// self-send waits for no other actor.
    pub actor_sends: Vec<(String, String, Key)>,
    /// [task-mint] The same for a **free `send fn`**'s body: `(the send fn's
    /// name, the target effect, the site)`. A task belongs to no handler, so
    /// its sends are attributed to whoever *mints* it — which is what
    /// `task_mints` records.
    pub task_sends: Vec<(String, String, Key)>,
    /// [task-mint] Who mints which task: `(the minter, the target `send fn`)`,
    /// where the minter is the enclosing handler's name or — for a task that
    /// mints another task — the enclosing free `send fn`'s. Whole-program and
    /// conservative, exactly as coarse as the type-level graph already is
    /// (FC-6: a real cycle class would otherwise go unreported). With the
    /// mint's `replyto` span, so a row belongs to the file it was written in
    /// [lsp-check-cache].
    pub task_mints: Vec<(String, String, Key)>,
    /// The concrete effect instance an effect-member call dispatches
    /// through (keyed by the call span), after generic disambiguation.
    pub effect_calls: HashMap<Key, Ty>,
    /// [effect-member-overload] Which **overload** of an effect member a call
    /// resolved to: the member's index in its effect's declaration order,
    /// keyed by the call span. Recorded only where the effect declares the
    /// name more than once (`close(InStream)` / `close(OutStream)`), because
    /// that is exactly where the emitters' name-keyed lookup cannot answer —
    /// they name an overloaded member positionally
    /// (`salvo_core::effect_member_name`).
    pub effect_member_calls: HashMap<Key, usize>,
    /// [effect-dispatch] Every call the checker resolved to an effect member,
    /// keyed by the call span: the effect (by its symbol key) and the
    /// member's index in its declaration order. A call is a member dispatch
    /// exactly when it is here; the emitters no longer ask the scope-blind
    /// `Symbols::effect_of_fn`.
    pub member_calls: HashMap<Key, MemberCall>,
    /// [fn-uniform] Calls written `base.f(args)` that the checker read as
    /// `f(base, args)`, keyed by the call span. The emitters normalize
    /// exactly these; they no longer ask whether `f` could be a fn or a
    /// member.
    pub dot_calls: HashSet<Key>,
    /// [fn-member-call] Calls written `base.f(args)` or `(base.f)(args)` that
    /// call through a fn-typed **field** `f` of a struct `base`, keyed by the
    /// call span: the IR reads the field and calls its value.
    pub field_calls: HashSet<Key>,
    /// [ir-nodes] Every written type the checker lowered, keyed by the
    /// **address of the AST node** (`written_type_key`): what a declaration's
    /// parameters, fields and results *are*, so the IR builder copies the
    /// checker's answer rather than lowering again. Generic parameters appear
    /// as `Ty::Var`. The key is the node, not `(file, span)`, because a
    /// foreign declaration's types are lowered under the *referencing* file,
    /// where their spans collide with that file's own (found 2026-10-06:
    /// `add_node() -> Long` read as `Bool`).
    pub written_types: HashMap<usize, Ty>,
    /// [call-resolve] Call sites whose callee resolved to a **fn-typed
    /// local** (a parameter or `let`) rather than to a declaration, keyed
    /// by the call span.
    ///
    /// The emitters need this because their own first question — "is this
    /// name an effect member?" — is asked of a *program-wide* map
    /// (`Symbols::effect_of_fn`), which knows nothing of scopes or locals,
    /// while the checker resolves a local first. Without the record, a
    /// program declaring `effect Sink { fn keep(...) }` made std's
    /// `filter(it, keep: (T) -> Bool)` emit an effect dispatch for its own
    /// parameter, reported as "no handler for effect `Sink`" from inside
    /// `core/seq.sv` — the checker and the emitters disagreeing about what
    /// a call *is*.
    pub local_calls: HashSet<Key>,
    /// [implicit-same-name] A local call through one of several implicits of
    /// one name: the [`ImplicitParam::local`] it went through.
    pub local_call_names: HashMap<Key, String>,
    /// Concrete effect instances threaded as leading handler arguments for
    /// a call to a fn that declares effect dependencies (keyed by the call
    /// span, in the callee's declaration order).
    pub call_effects: HashMap<Key, Vec<Ty>>,
    /// The lowered declared effect list of each fn [effect-fn-deps], in
    /// declaration order (duplicates and unresolved entries dropped) —
    /// the primary source for the emitters' effect-parameter
    /// environments, keyed by checker types rather than type renderings.
    pub fn_effects: HashMap<DeclId, Vec<Ty>>,
    /// [effect-alias] [effect-prereq] The same for **every** fn the checker
    /// lowered — handler and qualifier members included, which are not keyed
    /// by their `DeclId` — by the fn's name span, without a member's inherited
    /// handler dependencies: the expanded list (aliases flattened,
    /// prerequisites added) the IR and the language server read instead of
    /// the written one (PIPELINE.md R6).
    pub decl_effects: HashMap<Key, Vec<Ty>>,
    /// [effect-handler-deps] [effect-prereq] Each handler's dependencies, by
    /// handler key: written ones with aliases flattened, then the
    /// prerequisites of its faces, each with the span it came from.
    pub handler_deps: HashMap<String, Vec<(Ty, Span)>>,
    /// [effect-prereq] Each effect's direct prerequisites, by effect key,
    /// aliases flattened, its own generics unsubstituted.
    pub effect_prereqs: HashMap<String, Vec<Ty>>,
    /// [lsp-completion] The effects available inside each fn/handler-member
    /// body — the fully expanded set (declared effects, their transitive
    /// prerequisites, and a handler member's inherited handler dependencies)
    /// keyed by the file and the span of the body. The language server reads
    /// this to decide which effect *members* to offer at a cursor: a member
    /// is callable only when its owning effect is available here. One entry
    /// per body with a non-empty effect set.
    pub fn_body_effects: Vec<(usize, Span, Vec<Ty>)>,
    /// [call-type-args] The type arguments a generic call resolved to, in
    /// the callee's declaration order (keyed by the call span). Inferred
    /// from the arguments, an explicit type-argument list, or the expected
    /// type. The backends' intrinsic lowerings render these
    /// [backend-intrinsic].
    pub call_type_args: HashMap<Key, Vec<Ty>>,
    /// [fn-effects] The effect values a lambda takes as leading
    /// parameters, in order (keyed by the lambda expression's span): the
    /// declared set of the fn type it was checked against, or the set
    /// inferred from its body. Both emitters thread these *into* the
    /// closure instead of capturing them.
    pub lambda_effects: HashMap<Key, Vec<Ty>>,
    /// [fn-value] The implicits a function passed **by name** fills in turn,
    /// at the name's span — the same `nested` an implicit filled by that
    /// function records (`ImplicitArg::Resolved`), since the two are one
    /// rule [fn-value]. Absent for a function with none.
    pub fn_value_implicits: HashMap<Key, Vec<ImplicitArg>>,
    /// [qual-lift] The type a `^` check widens its subject to, keyed by the
    /// check's span (a `^` expression, or a `^` branch head in a `when`).
    /// Present only when the check *peels a wrapper arm*, which is when the
    /// emitters must materialize the peel: they bind the widened value to a
    /// shadowing local for the branch, so reads and any nested `when` see it
    /// at this type.
    pub widen_targets: HashMap<Key, Ty>,
    /// [op-elvis] The **unpicked** arms at each positional pick — the type `_`
    /// reads as on the right-hand side, tags and all. Keyed by the operator's
    /// span.
    pub pick_left: HashMap<Key, Ty>,
    /// [op-elvis] The **picked** type at each `?:` — the subject's arms the run of
    /// `?`s selected (a sub-union, by `[type-rewrap]`). Keyed by the operator's
    /// span; the emitters read it to know what the left branch yields.
    pub elvis_picks: HashMap<Key, Ty>,
    /// [op-elvis] How a positional pick lowers at runtime, keyed by the
    /// operator's span: which of the subject's arms are the *picked* side.
    pub elvis_tests: HashMap<Key, PickTest>,
    /// [op-elvis] [type-rewrap] When a pick's result **widens** past its picked arms
    /// (`Int? ?: "none"` is `Int | Str`), the coercion that lifts the picked
    /// value into the join, keyed by the operator's span. The emitters wrap
    /// the picked value (only); the right side carries its own coercion at
    /// its own span.
    pub elvis_widen: HashMap<Key, Coercion>,
    /// Calls that may throw [throw], keyed by the call span: the `throw`
    /// operation itself and every call whose callee declares `[Throw<M>]`.
    /// The emitters need each one because the control transfer is *their*
    /// job: a Rust `ControlFlow::Break` (or a labelled-block break), a
    /// Kotlin `throw`.
    pub may_throw: HashMap<Key, ThrowSite>,
    /// Per-fn deduction facts [deduce-infer]: for each parameter, whether
    /// a call gives the value back to the caller and which of its declared
    /// qualifiers are still known afterwards. Written lists are stored as
    /// validated; unwritten lists are inferred from the body. The Rust
    /// backend's ownership/borrow contract (Kotlin ignores them).
    pub deductions: HashMap<DeclId, Vec<crate::deduce::ParamDeduction>>,
    /// Fn-name references [fn-ref-table]: the span of a fn *name* — at
    /// its declaration, as a call-site callee, or a fn-by-name use —
    /// mapped to the declaration it resolves to. Drives the LSP's
    /// signature hover.
    pub fn_refs: HashMap<Key, DeclId>,
    /// Non-fn name references [lsp-definition]: the span of a type,
    /// struct, effect, handler, qualifier, type-alias, or effect-member
    /// name mapped to where its declaration's identifier is written.
    /// Drives go-to-definition for everything `fn_refs` does not cover.
    pub def_refs: HashMap<Key, DefSite>,
    /// [lsp-completion] Every local binding — parameter, `let`, `is`/`when`
    /// binding, `for` binder — declared in each file, keyed by file index,
    /// with its declaration span and the span of the fn body it belongs to.
    /// The language server offers the ones visible at the cursor (in the
    /// enclosing fn, declared before it) as completions. Presentation-only,
    /// like `fate_reads`.
    pub local_decls: HashMap<usize, Vec<LocalDecl>>,
    /// [type-identity] [name-table] The key every written type reference
    /// resolves to, where it is not the written name (a clash or an alias):
    /// what an emitter rendering a written type reads. By the reference's
    /// copy key [node-file] (`resolve::CopyKey`), which the reference and
    /// every copy of it share.
    pub type_ref_span_keys: HashMap<crate::resolve::CopyKey, String>,
    /// [type-identity] [name-table] The key of the handler a value-position
    /// name means where it is written (`use H()`, `spawn H()`, a `with`
    /// item), by the name's copy key [node-file], where it is not the name
    /// itself (a handler named like another module's type or handler, 0c
    /// item 13): how the IR names the handler it constructs. Derived from
    /// `Resolution::names`.
    pub value_span_keys: HashMap<crate::resolve::CopyKey, String>,
    /// Field accesses [lsp-definition]: the span of the field *name* in
    /// `base.field` mapped to where the field's declaration is written.
    /// Drives go-to-definition and doc hover on fields [doc-comment].
    pub field_refs: HashMap<Key, DefSite>,
    /// [doc-module] Module references [fn-overload-at] [mod-suffix]: the span
    /// of a written `@module` selector (`size@list`, `describe@main`), mapped
    /// to the **full path** of the one module it resolved to. Drives the
    /// module hover; a selector that matched no module or two is not
    /// recorded (it has its own diagnostic).
    pub module_refs: HashMap<Key, ModulePath>,
    /// Reads of fate-linked (derived) variables [fate-link], keyed by the
    /// identifier span: the roots the variable shares fate with, and
    /// where each link was bound. Presentation-only: tooling renders the
    /// variable's type with a bare `proj` compiler qualifier and
    /// serves the parameters (roots, binding sites) as on-request detail
    /// (user decision 2026-09-02, progressive disclosure).
    pub fate_reads: HashMap<Key, Vec<FateRead>>,
    /// [interp-union] An interpolated **union**: how each of its runtime arms
    /// (in arm order) reaches text. The emitters call the arm's own `to_str`
    /// on the arm the value is.
    pub interp_union: HashMap<Key, Vec<ArmText>>,
    /// [proj-anywhere] Derived-return calls whose borrowed argument is a
    /// *temporary*: usable within the statement, but binding, returning or
    /// storing the view is an error (it would outlive what it borrows).
    pub temp_views: HashSet<Key>,
    /// [proj-infer] Calls whose result *holds borrows* of some arguments
    /// (a fn returning a struct with `proj` fields), keyed by the call span:
    /// the indices of the lent arguments (dot-notation receivers are
    /// argument 0). The checker links the result to them, held; the Rust
    /// backend ties the result's lifetime to those parameters.
    pub lending_calls: HashMap<Key, Vec<usize>>,
    /// [proj-infer] Per fn, the parameters its result holds borrows of
    /// (declared with `[p: proj]` or inferred from the body). Read by the
    /// Rust backend to name the lifetime on lent parameters and the return.
    pub fn_lends: HashMap<DeclId, Vec<usize>>,
    /// [ref-handle] Bind events of **mutable element handles** (P-9, user
    /// decision 2026-09-24: mode is inferred per binding): a `let` binding a
    /// `proj Mut` value that some downstream use mutates. The Rust backend
    /// renders such a binding as a captured-index path handle rather than a
    /// `&` borrow, so the mutation reaches the container's storage.
    pub handle_muts: HashSet<Key>,
    /// [deduce-syntax] [ref-handle] Per fn, the parameters its body
    /// mutates — directly, or through a handle into them (a generic
    /// container is lent mutably exactly when a handle into it is written).
    pub param_mutations: HashMap<DeclId, HashSet<String>>,
    /// Projection expressions in *moved* positions whose provenance
    /// roots were consumed [fate-move-mode]: the Rust backend may render
    /// the place directly (a partial move) instead of cloning.
    pub moved_projections: HashSet<Key>,
    /// [platform-check] What crosses from host to Salvo and needs checking
    /// (ABI D7): keyed by a platform fn's name span (its result), an
    /// effect member's name span (its result, for a platform-handled effect),
    /// or a `Reply<T>` parameter's name span (the value the host sends).
    pub boundary_checks: HashMap<Key, crate::abi::BoundaryCheck>,
    /// [platform-factory] The factories of each union a host builds (the ABI decisions
    /// D5): keyed by a type alias's name span (a named union reached from a
    /// platform signature), a platform fn's or platform-handled member's name
    /// span (its result), or a `Reply<T>` parameter's name span.
    pub factories: HashMap<Key, crate::abi::Factories>,
    /// [platform-factory] What every module's platform signatures reach.
    pub platform_closure_all: std::collections::BTreeSet<String>,
    /// The captured outer locals of each lambda [fate-lambda], keyed by
    /// the lambda expression's span (for tooling and future emission
    /// refinements; both emitters currently capture lexically, which is
    /// an alias on both backends).
    pub lambda_captures: HashMap<Key, Vec<LambdaCapture>>,
    /// Calls to fns with a derived return (`proj(param)`
    /// [proj-readonly-return]), keyed by the call span: the index of the
    /// argument the result borrows. The checker links the result to that
    /// argument; the Rust backend renders the result as a borrow.
    pub derived_calls: HashMap<Key, Vec<usize>>,
    /// [fate-elem-distinct] Calls taking **two mutable element handles of one
    /// container, proven apart** by a live `NotSame` claim, keyed by the
    /// call span: the two parameter indices. The Rust backend renders the
    /// pair through `salvo_pair_mut` (one `split_at_mut`, two `&mut`)
    /// [rs-elem-mut]; an unproven pair never lands here — it is refused at
    /// the call.
    pub distinct_pairs: HashMap<Key, (usize, usize)>,
    /// [rs-loc] Derived-return calls whose **result is used
    /// mutably** — passed to a `Mut` position or assigned through — keyed
    /// by the call span. The Rust backend renders such a call against the
    /// callee's demand-emitted `__mut` variant (mode-specialized lending,
    /// step ③ of the group-borrowing ladder); Kotlin needs nothing.
    pub mut_lend_calls: HashSet<Key>,
    /// Calls *through fn-typed values* [fn-contract], keyed by the call
    /// span: the effective per-argument contract (post-default), for the
    /// Rust backend's argument rendering.
    pub fn_value_calls: HashMap<Key, Vec<FnParamContract>>,
    /// Lambdas checked against a *contracted* fn type [fn-contract],
    /// keyed by the lambda span: the contract, for the Rust backend's
    /// parameter-binding modes.
    pub lambda_contracts: HashMap<Key, Vec<FnParamContract>>,
    /// The implicit parameters of each fn, expanded [implicit-param]
    /// [implicit-group]: the written `?name: FnType` ones in order, then each
    /// `?Group<T>` spread's members in declaration order. This is the single
    /// ordered list both sides render — the callee's trailing parameters and
    /// the caller's trailing arguments — so neither emitter needs to know
    /// that groups exist.
    pub implicit_params: HashMap<DeclId, Vec<ImplicitParam>>,
    /// [deduce-reapply] The claims a fn's deduction clause says it
    /// **establishes** (`=> list: +Heap<T>(?cmp) Mut`), by (fn, parameter), each
    /// already lowered in the callee's generic scope — so a call site only has to
    /// substitute its type arguments and the identity that filled the binder,
    /// then add the qualifier to the caller's variable. Lowered here rather than
    /// at the call site because the callee's generics are in scope here and not
    /// there, exactly as for `implicit_params`.
    pub established_quals: HashMap<(DeclId, String), Vec<Qual>>,
    /// [cmp-carry] What each **carried identity** resolves to: the declaration
    /// behind the `by_age` in a `SortedSet<Person>(by_age)`, keyed by the
    /// identity and the type it orders.
    ///
    /// A backend needs the *declaration* — to name the fn its generated marker
    /// calls — and resolution is the checker's job, not a thing an emitter should
    /// redo and possibly disagree about. Recorded where such a type is written,
    /// which is the only place a named identity can enter.
    ///
    /// Keyed by the file it is written in as well [lsp-check-cache]: a name
    /// resolves in its file's scope, and a table shared by every file made
    /// the first file to write an identity the only one whose `fn_refs` and
    /// diagnostics recorded it, so a file's rows depended on which files
    /// were walked before it.
    pub carried_identities: HashMap<(usize, FnId, Ty), DeclId>,
    /// What fills each implicit parameter at a call [implicit-resolve],
    /// keyed by the call span, in the callee's declared order.
    pub implicit_args: HashMap<Key, Vec<ImplicitArg>>,
    /// The type arguments a `use` gives its handler
    /// [effect-handler-generics], in the handler's declaration order: from
    /// the written list (`use Plain<Int>()`) and from what the constructor
    /// arguments bind. The emitters need them because a generic handler has
    /// to be constructed *at* a type, and neither target can infer one from
    /// an empty argument list.
    pub use_handler_args: HashMap<Key, Vec<Ty>>,
    /// The implicit parameters of each *effect member* [implicit-param]:
    /// members are not keyed by their `DeclId`, so they are keyed by the span of the member's
    /// name. The emitters read this where they render the member — the
    /// interface or trait method, every handler's implementation of it, and
    /// the host skeleton — since an implicit is part of the member's
    /// signature like any other parameter.
    pub implicit_members: HashMap<Key, Vec<ImplicitParam>>,
    /// [effect-member-overload] [effect-at] An effect's member written as a
    /// value, `m@E` at a fn-typed position (R10 D3: the remedy an ambiguous
    /// implicit names), keyed by the member name's span: always an
    /// [`ImplicitArg::Member`], which the IR lowers to a closure over the
    /// instance, as for a member that fills an implicit.
    pub member_values: HashMap<Key, ImplicitArg>,
    /// Type errors, structured for CLI/LSP consumption [diag-structured].
    pub errors: Vec<FileDiagnostic>,
}

/// Why an implicit parameter could not be resolved [implicit-resolve]. The
/// distinction *is* the diagnostic: "nothing of that name" and "declared,
/// but its contract does not fit" need different words, and the second
/// difference is invisible in a printed type.
enum ImplicitMiss {
    /// No fn of that name is visible.
    Unknown,
    /// One is, and here is why it does not fit.
    NearMiss(String),
    /// Several fit and none is more specific [fn-overload-ambiguous]: the
    /// candidates, as shown in the diagnostic.
    Ambiguous(Vec<(String, String)>),
    /// [implicit-recursive] One was chosen, and its own implicits cannot be
    /// filled: the chain down to the position that failed, and why.
    Unfilled(Unfilled),
}

/// [implicit-recursive] Why the candidate chosen for a position could not be
/// completed: the positions its resolution opened below the reported one,
/// outermost first (each an implicit's name and wanted fn type), down to the
/// one that failed, and how that one failed. Structured rather than worded
/// per level, so the message names the two ends once and lists the types
/// between them, however deep the chain went.
struct Unfilled {
    links: Vec<(String, Ty)>,
    why: UnfilledWhy,
}

enum UnfilledWhy {
    /// Nothing fits the last position: no fn of the name (`None`), or the
    /// best near miss.
    NoFit(Option<String>),
    /// Several fit the last position and none is more specific.
    Ambiguous(Vec<(String, String)>),
    /// The last position's candidate needs implicits of its own past the
    /// depth cap: the candidate's name.
    Depth(String),
    /// The last position's candidate needs itself: its name.
    Cycle(String),
    /// Another refusal while filling, as it was worded.
    Other(String),
}

/// [op-equality] [op-order] A comparison operator being resolved as the call
/// it names (`a == b` is `eq(a, b)`, `a < b` is `cmp(a, b) < 0`, O1): the
/// call's diagnostics are worded for the operator.
#[derive(Clone, Debug)]
struct OperatorSite {
    /// The operator as written (`==`, `<`, …).
    sym: &'static str,
    /// The function it names (`eq`, `cmp`).
    member: &'static str,
    /// The operand types the call is resolved at.
    lhs: Ty,
    rhs: Ty,
    /// What the refusal of a missing function suggests ([`Checker::compare_remedy`]).
    remedy: String,
}

impl OperatorSite {
    /// The call's diagnostic, said of the operator: a missing function names
    /// the operator and the remedy, anything else is prefixed with what the
    /// operator is.
    fn reword(&self, msg: String) -> String {
        let OperatorSite { sym, member, lhs, rhs, remedy } = self;
        let on = if lhs.strip_quals() == rhs.strip_quals() { format!("`{lhs}`") } else { format!("`{lhs}` and `{rhs}`") };
        let call = format!("no matching overload for `{member}({lhs}, {rhs})`");
        match msg.strip_prefix(&call) {
            Some(rest) => format!(
                "no `{member}` for `{sym}` on {on}: `{sym}` is `{member}({lhs}, {rhs})`, and no `{member}` in \
                 scope takes `({lhs}, {rhs})`{rest}{remedy}"
            ),
            None => format!("`{sym}` on {on} is `{member}({lhs}, {rhs})`: {msg}"),
        }
    }
}

/// [iter-for] A `for` header being resolved as the calls it names (`for x
/// in c` is `next(c)` for an iterator, `next(iter(c))` for a source, O1): the
/// call has no node of its own, so its facts go to a synthetic key of the
/// subject's (`at`, the `for`'s span, is what the call is resolved at, and
/// `Checker::key` answers `key` for it), its diagnostics land on the subject
/// (`loc`) and are said of the `for`.
#[derive(Clone, Debug)]
struct ForSite {
    at: Span,
    key: Key,
    loc: Span,
    /// The call as the `for` names it (`next(Bag)`, `next(iter(Bag))`).
    call: String,
    subject: Ty,
    /// [interp-to-str] The site is an interpolated part, whose call is
    /// `to_str(part)` (PIPELINE.md §II.10 P4), not a `for`.
    interp: bool,
}

impl ForSite {
    fn reword(&self, msg: String) -> String {
        // An interpolated part's call says only where it is: the message
        // names `to_str` and the type itself.
        if self.interp {
            return format!("in this interpolation: {msg}");
        }
        format!("`for` over `{}` is `{}`: {msg}", self.subject, self.call)
    }
}

/// [op-arm-eq] An equality `union == value` the checker reduced to an arm
/// test plus a comparison of that arm. The IR lowers it to
/// `subject is <test> && (subject-narrowed-to-arm) == value`.
#[derive(Clone, Debug)]
pub struct ArmCompare {
    /// The union-typed operand to test, as the arm test that selects the
    /// matching arm (the IR turns it into an `ArmTest`).
    pub test: UnionTest,
    /// The type of the arm the value matches (what the narrowed subject reads
    /// as, and the type the inner `==` compares at).
    pub arm_ty: Ty,
    /// True when the **left** operand is the union (and the right is the
    /// value); false when they are swapped (`value == union`).
    pub subject_is_lhs: bool,
}

/// `a`, `a and b`, `a, b and c` — for a diagnostic that lists names.
fn join_and(items: &[String]) -> String {
    match items {
        [] => String::new(),
        [one] => one.clone(),
        [head @ .., last] => format!("{} and {last}", head.join(", ")),
    }
}

/// One implicit parameter of a fn [implicit-param], after group expansion.
#[derive(Clone, Debug, PartialEq)]
pub struct ImplicitParam {
    /// The name that resolution, forwarding and a call-site override all
    /// key on — a member's own name, with no group qualifier: dropping the
    /// binder is what lets an inner fn declare `?add` directly, or reach the
    /// same parameter through a different grouping (user decision
    /// 2026-09-05).
    pub name: String,
    /// The fn type it must be filled with, as declared (generics
    /// unsubstituted).
    pub ty: Ty,
    /// Where it was written: the parameter, or the `?Group<T>` spread.
    pub span: Span,
    /// [proj-anywhere] Which union arms of the member's *written* return
    /// type carry `proj` — a borrow the lowered `Ty` no longer shows. `Next`'s
    /// `next` has `[0]`: `Emitted (proj(it) T) | Finished`. A backend
    /// that distinguishes borrows from values (Rust) renders those arms as
    /// references. Empty for a non-union return or a plain implicit.
    pub borrowed_arms: Vec<usize>,
    /// [cmp-binder] The **slot** this parameter came from, when it came from one:
    /// `?cmp: cmp2` is named `cmp2` here and remembers that it fills a `cmp`.
    /// That is what makes an alias honest — two orderings in one scope are an
    /// ambiguity for `<` whatever they are called, so the operator has to ask
    /// what a parameter *is*, not what it is called (user decision 2026-09-22).
    pub slot: Option<String>,
    /// [cmp-binder] True when the signature carries this name as a **binder**
    /// (`Heap(?cmp)`) — whether the parameter was written (`?cmp: (T, T) ->
    /// Int`, whose resolution the result type then publishes) or captured from
    /// the argument types. What fills it is then the identity the types carry,
    /// before any resolution by name: that is the whole point of putting the
    /// ordering in the type.
    pub binder: bool,
    /// [implicit-with] The index of the **fill-together component** this
    /// parameter belongs to, `None` when nothing binds it. A `with` entry —
    /// on the fn (`=> eq with hash`) or on a group it spreads
    /// (`fns Hashed<T> => eq with hash`) — puts its members in one
    /// component, and a call must fill every member of a component from the
    /// *same source* (user decision 2026-09-26). Symmetric and transitive, so
    /// the components are the connected classes of the declared pairs.
    pub bound: Option<usize>,
    /// [implicit-same-name] The name the body binds it under and a backend
    /// declares it as: [`name`](Self::name), except for the second and later
    /// of **one name at different types** (`?to_str: (K) -> Str, ?to_str: (V)
    /// -> Str`, legal since 2026-09-28), which are `to_str__1`, … — a call in
    /// the body picks among them by argument types.
    pub local: String,
}

/// [interp-union] How one arm of an interpolated union reaches text.
#[derive(Clone, Debug, PartialEq)]
pub enum ArmText {
    /// A scalar or `Str`, which the target renders natively.
    Native,
    /// An implicit `to_str` of the enclosing fn (its local's name).
    Own(String),
    /// A `to_str` in scope, with the implicits it needs filled.
    Fn { key: DeclId, implicits: Vec<ImplicitArg> },
}

/// What a call site puts in an implicit parameter [implicit-resolve].
#[derive(Clone, Debug, PartialEq)]
pub enum ImplicitArg {
    /// The caller wrote `name = value`: the value is in the call's `named`
    /// list, and the emitters render it like any argument. The arity comes
    /// along because a backend may have to adapt a bare fn name into a
    /// closure, and only the parameter's type knows how many arguments it
    /// takes.
    Given { name: String, arity: usize },
    /// Forwarded from an implicit parameter of the enclosing fn, which has
    /// the same name and a matching type [implicit-forward]. Inside generic
    /// code this is the only possibility, since nothing about an opaque `T`
    /// is knowable [call-resolve].
    Forwarded { name: String },
    /// Resolved to a declared fn, by name and type [implicit-resolve].
    Resolved {
        name: String,
        key: DeclId,
        /// [implicit-recursive] The implicits of the resolved fn itself,
        /// filled in turn (`eq` for `List<T>` needs an `eq` for `T`); empty
        /// for a fn with none. One level per nesting, depth-capped.
        nested: Vec<ImplicitArg>,
        /// [copy-implicit] The fn type the position wanted, with the call's
        /// type arguments substituted — the *concrete* type a shape-lowered
        /// intrinsic (`copy`) needs to render itself as a value.
        want: Ty,
    },
    /// [iter-fn] The position wants a pass's `next` and the argument
    /// was an **origin**, so the pass is the hidden machine minted at that
    /// argument (user decision 2026-09-09). There is no declared fn to name:
    /// the emitters wrap the machine's own advance into the protocol's two
    /// arms, using `next_fn` — the `yield fn`'s key — for the machine's name
    /// and its effect order, exactly as a `for` over the origin does.
    OriginNext { name: String, next_fn: DeclId },
    /// [effect-member-overload] [implicit-resolve] An available effect's
    /// member, passed as a value (R10 D3): a closure over the instance it
    /// dispatches through, so it carries its handler and asks the position
    /// for no effect. `effect` is the effect's symbol key and `index` the
    /// member's among its `fns`, as [`MemberCall`] names them; `instance` the
    /// effect instance in scope; `nested` the member's own implicits
    /// [implicit-recursive]; `want` the fn type the position wanted.
    Member { name: String, effect: String, index: usize, instance: Ty, nested: Vec<ImplicitArg>, want: Ty },
}

/// [lsp-completion] One local binding declared in a file, for completion: its
/// name, its type as declared, the span of its own declaration, and the span
/// of the enclosing fn body (so the language server offers it only inside that
/// fn, and only after its declaration). A parameter's "fn body" span is the
/// body too, so parameters are offered throughout the body.
#[derive(Clone, Debug, PartialEq)]
pub struct LocalDecl {
    pub name: String,
    pub ty: Ty,
    pub span: Span,
    pub fn_body: Span,
    /// [lsp-completion] A binding in scope for the **whole** body regardless
    /// of where it is written — a parameter, or a handler/`iter fn` state
    /// field (a `state {}` block may sit after the member that uses it). An
    /// ordinary `let`/`is`/`for` binding is `false`: it is only in scope
    /// after its declaration, so the completion filter requires the cursor to
    /// be past it.
    pub always_in_scope: bool,
}
/// One fate link of a derived variable, exposed for tooling [fate-link]:
/// the root variable's name and the binding that created the link, by its
/// node [node-id] (its span the binding's origin).
#[derive(Clone, Debug, PartialEq)]
pub struct FateRead {
    pub root: String,
    pub bind: Key,
    /// [fate-field-disjoint] The projection the value was taken from,
    /// rendered (`.name`, or empty for the whole variable). `None` when the
    /// derivation is not a plain projection chain. Tooling appends it to
    /// `root` so the hover names the storage actually shared — since L5,
    /// "shares fate with `p`" would overstate a link to `p.name` alone.
    pub path: Option<String>,
}

/// [fate-poison] One fate link of a **borrow-mode** binding, for the IR
/// flow pass [flow-use-after-move]: the root variable (by name — the IR's
/// local), the projection of it the value came from (`None` the
/// conservative unknown [fate-field-disjoint]), and whether the derivation
/// reaches through a destroyability boundary [deduce-field] (what decides
/// whether a contents mutation spares it).
#[derive(Clone, Debug, PartialEq)]
pub struct FlowLink {
    pub root: String,
    pub path: Option<Vec<Step>>,
    pub crosses: bool,
    /// [fate-move-mode] The binding that made the link (a descendant's copy
    /// of an ancestor's link carries the ancestor's), by its node: what the
    /// IR flow pass and its `Decision` know a binding by [node-id].
    pub stamp: Key,
}

/// [fate-move-mode] One link-carrying binding (`Checked::bind_facts`).
#[derive(Clone, Debug, PartialEq)]
pub struct BindFact {
    /// [node-id] The binding, by its node.
    pub stamp: Key,
    pub links: Vec<FlowLink>,
    pub eligible: bool,
    /// The `for` loops its roots are bound by, by their iterables' nodes.
    pub origins: Vec<Key>,
}

/// [fate-move-mode] A move or mutation of a derived variable
/// (`Checked::derived_uses`).
#[derive(Clone, Debug, PartialEq)]
pub struct DerivedUse {
    pub name: String,
    pub action: String,
    /// [fate-derived-readonly] The S1 error, should the binding stay
    /// borrow-mode.
    pub message: Message,
    /// The bindings (by stamp) the variable's own links were made by, as the
    /// walk holds them there: the use is the S1 error unless one of them may
    /// take ownership.
    pub own: Vec<Key>,
}

/// [deduce-field] A binding a mutation event may leave as a virtual place
/// (`Checked::virtual_candidates`): its stamp, the place, the variable that
/// holds the link, and whether that variable must still be live there
/// (`survivor`: a fields-declaring call's) or not (a contents spare's).
#[derive(Clone, Debug, PartialEq)]
pub struct VirtualCandidate {
    /// [node-id] The binding, by its node.
    pub stamp: Key,
    pub place: String,
    pub var: String,
    pub survivor: bool,
}

/// [fate-poison] One mutation event on a root, for the IR flow pass: what
/// the checker's `record_mutation` was told. The pass poisons every
/// value linked to `root` at an overlapping path [fate-field-disjoint],
/// except the acting handle (`exempt` [ref-handle]), a handle to the
/// mutated thing itself under a contents mutation (`contents_only`
/// [deduce-field]), and the handles a live `NotSame` claim proves apart
/// (`spared` [fate-elem-distinct], a typing fact the checker settles).
#[derive(Clone, Debug, PartialEq)]
pub struct FlowMutation {
    pub root: String,
    pub path: Option<Vec<Step>>,
    pub contents_only: bool,
    pub exempt: Option<String>,
    pub spared: Vec<String>,
}

/// One captured variable of a lambda [fate-lambda]: the outer local the
/// body mentions, and whether the capture *consumed* it (the body
/// mutates it, so the closure took ownership at creation).
#[derive(Clone, Debug, PartialEq)]
pub struct LambdaCapture {
    pub name: String,
    pub consumed: bool,
    /// [fate-move-mode] The captured value is transitively **mutable**, so
    /// whether the closure holds a snapshot or an alias is observable.
    pub mutable: bool,
    /// The closure **writes** through this capture — including handing it to
    /// a `Mut` parameter. True even for a value whose type is not itself
    /// mutable (`let i = 0` reassigned inside the lambda), which is why it
    /// is a flag of its own rather than implied by `mutable`.
    pub mutated: bool,
}

impl Checked {
    /// [type-identity] [name-table] The key of the handler a value-position
    /// name means where it is written, or the name.
    pub fn value_key<'a>(&'a self, id: &'a Ident) -> &'a str {
        crate::resolve::ident_copy_key(id)
            .and_then(|at| self.value_span_keys.get(&at))
            .map(|k| k.as_str())
            .unwrap_or(&id.name)
    }

    pub fn written_key<'a>(&'a self, r: &'a TypeRef) -> &'a str {
        if self.type_ref_span_keys.is_empty() {
            return &r.name.name;
        }
        crate::resolve::copy_key(r)
            .and_then(|at| self.type_ref_span_keys.get(&at))
            .map(|k| k.as_str())
            .unwrap_or(&r.name.name)
    }

    pub fn ty_of(&self, file: usize, span: Span) -> Option<&Ty> {
        self.expr_ty.get(&self.key_at(file, span))
    }

    /// [unify-checker] The call-cluster facts at one call span, gathered in
    /// one lookup: which kind of call this resolved to and its modifiers. The
    /// IR builder reads this instead of consulting a dozen span-keyed tables
    /// at every call node (COMPLETED.md's unify-checker entry, the call cluster). A borrowing
    /// view over the underlying tables for now; the storage behind it is being
    /// unified into one `HashMap<Key, CallFacts>` without re-touching the
    /// builder. Every field is independently `None`/absent — a given call sets
    /// exactly the ones that describe it.
    pub fn call_info(&self, key: Key) -> CallInfo<'_> {
        CallInfo {
            may_throw: self.may_throw.get(&key),
            addr_call: self.addr_calls.get(&key),
            self_send: self.self_sends.get(&key),
            facade_send: self.facade_sends.get(&key),
            dot_call: self.dot_calls.contains(&key),
            field_call: self.field_calls.contains(&key),
            member_call: self.member_calls.get(&key),
            effect_call: self.effect_calls.get(&key),
            local_call: self.local_calls.contains(&key),
            local_call_name: self.local_call_names.get(&key),
            call_fn: self.call_fn.get(&key),
            call_effects: self.call_effects.get(&key),
            call_type_args: self.call_type_args.get(&key),
            implicit_args: self.implicit_args.get(&key),
            fn_value_call: self.fn_value_calls.get(&key),
            moved_projection: self.moved_projections.contains(&key),
        }
    }

    /// [unify-checker] The `use`-statement facts at one span, in one lookup
    /// (COMPLETED.md's unify-checker entry, the use cluster): the faces to bind, whether it is a
    /// `use addr`, and the dependency wiring. (`route_uses`/`use_handler_args`
    /// are read in the handler-construction helper at a different span, so they
    /// stay direct.)
    pub fn use_info(&self, key: Key) -> UseInfo<'_> {
        UseInfo {
            use_effects: self.use_effects.get(&key),
            use_addr: self.use_addrs.get(&key),
            use_addr_tuple: self.use_addr_tuples.get(&key),
            use_deps: self.use_deps.get(&key),
            use_with_items: self.use_with_items.get(&key),
        }
    }

    /// [unify-checker] The spawn/reply-mint facts at one span, in one lookup
    /// (COMPLETED.md's unify-checker entry): a `spawn`'s deps/effects, and a `replyto` that mints
    /// a task (vs a member).
    pub fn spawn_info(&self, key: Key) -> SpawnInfo<'_> {
        SpawnInfo {
            spawn_deps: self.spawn_deps.get(&key),
            spawn_dep_items: self.spawn_dep_items.get(&key),
            spawn_effects: self.spawn_effects.get(&key),
            replyto_task: self.replyto_tasks.get(&key),
            task_mint_effects: self.task_mint_effects.get(&key),
            replyto_member: self.replyto_members.get(&key),
        }
    }

    /// [unify-checker] The positional-pick / elvis facts at one span, in one
    /// lookup (COMPLETED.md's unify-checker entry): the runtime test, and the
    /// picked and left arm types.
    pub fn pick_info(&self, key: Key) -> PickInfo<'_> {
        PickInfo {
            elvis_test: self.elvis_tests.get(&key),
            elvis_pick: self.elvis_picks.get(&key),
            pick_left: self.pick_left.get(&key),
        }
    }

    /// [unify-checker] string-interpolation rendering facts at one span, in
    /// one lookup (COMPLETED.md's unify-checker entry).
    pub fn interp_info(&self, key: Key) -> InterpInfo<'_> {
        InterpInfo { union: self.interp_union.get(&key) }
    }
}

/// [unify-checker] positional-`pick` / elvis facts at one span (COMPLETED.md's unify-checker entry).
pub struct PickInfo<'c> {
    pub elvis_test: Option<&'c PickTest>,
    pub elvis_pick: Option<&'c Ty>,
    pub pick_left: Option<&'c Ty>,
}

/// [unify-checker] string-interpolation rendering facts at one span
/// (COMPLETED.md's unify-checker entry): a union's per-arm dispatch. Any other
/// part is the call `to_str(part)`, whose facts are the call's, at the part's
/// `Key::INTERP_TEXT` (PIPELINE.md B3.2).
pub struct InterpInfo<'c> {
    pub union: Option<&'c Vec<ArmText>>,
}

/// [unify-checker] `use`-statement facts at one span (COMPLETED.md's unify-checker entry).
pub struct UseInfo<'c> {
    pub use_effects: Option<&'c Vec<Ty>>,
    pub use_addr: Option<&'c Ty>,
    pub use_addr_tuple: Option<&'c Vec<Ty>>,
    pub use_deps: Option<&'c Vec<Ty>>,
    pub use_with_items: Option<&'c Vec<Option<usize>>>,
}

/// [unify-checker] spawn / reply-mint facts at one span (COMPLETED.md's unify-checker entry).
pub struct SpawnInfo<'c> {
    pub spawn_deps: Option<&'c Vec<Ty>>,
    pub spawn_dep_items: Option<&'c Vec<Option<usize>>>,
    pub spawn_effects: Option<&'c Vec<Ty>>,
    pub replyto_task: Option<&'c DeclId>,
    pub task_mint_effects: Option<&'c Vec<Ty>>,
    pub replyto_member: Option<&'c String>,
}

/// [unify-checker] The call-cluster facts at one call span (COMPLETED.md's unify-checker entry).
/// A read-only view the IR builder assembles once per call node; the fields
/// are borrows from the checker's tables. The discriminating facts
/// (`may_throw`/`addr_call`/`member_call`/`local_call`/`call_fn`/…) are
/// mutually exclusive in practice — a call is one kind — with the rest as
/// modifiers (effects, type args, implicit args, consume contract).
pub struct CallInfo<'c> {
    pub may_throw: Option<&'c ThrowSite>,
    pub addr_call: Option<&'c Ty>,
    pub self_send: Option<&'c String>,
    pub facade_send: Option<&'c String>,
    pub dot_call: bool,
    /// [fn-member-call] A call through a fn-typed field of the receiver.
    pub field_call: bool,
    pub member_call: Option<&'c MemberCall>,
    pub effect_call: Option<&'c Ty>,
    pub local_call: bool,
    pub local_call_name: Option<&'c String>,
    pub call_fn: Option<&'c DeclId>,
    pub call_effects: Option<&'c Vec<Ty>>,
    pub call_type_args: Option<&'c Vec<Ty>>,
    pub implicit_args: Option<&'c Vec<ImplicitArg>>,
    pub fn_value_call: Option<&'c Vec<FnParamContract>>,
    pub moved_projection: bool,
}

/// [platform-fn-value] [runtime-kept-fn] Whether platform fn `f` keeps its
/// fn-typed parameter `p` past the call: its clause consumes it (`=> !p`).
/// In std's runtime that is a kept closure; anywhere else the argument must
/// be a named top-level fn. One predicate, so the checker and the emitters
/// agree on which parameters are kept.
pub fn platform_keeps_param(f: &ast::FnDecl, p: &ast::Param) -> bool {
    f.platform
        && f.deductions.iter().flatten().any(|d| {
            d.param_name().is_some_and(|n| n.name == p.name.name) && matches!(d.kind, ast::DeductionKind::Moved)
        })
}

/// The join of the narrowed types of a local on the paths that fall
/// through: agreeing states win; `Never` on any path is `Never`; otherwise
/// only the qualifiers every path keeps survive.
fn join_narrowed(states: &[&Ty]) -> Ty {
    if states.iter().all(|t| **t == *states[0]) {
        states[0].clone()
    } else if states.iter().any(|t| matches!(t, Ty::Never)) {
        Ty::Never
    } else {
        // Keep only qualifiers every path preserves.
        let mut common: HashSet<String> = states[0].quals().iter().map(|q| q.name.clone()).collect();
        for t in &states[1..] {
            let names: HashSet<String> = t.quals().iter().map(|q| q.name.clone()).collect();
            common.retain(|q| names.contains(q));
        }
        let removed: HashSet<String> =
            states[0].quals().iter().map(|q| q.name.clone()).filter(|q| !common.contains(q)).collect();
        states[0].clone().remove_quals(&removed)
    }
}

/// Checks the whole program (resolution must come from the same program).
///
/// Every contract is a function of its signature, known before any body
/// [deduce-default], so every body is walked once against them
/// [deduce-fixpoint]; the deductions then check each body against its
/// contract.
pub fn check_program<'p>(
    program: &'p Program,
    resolution: &Resolution<'p>,
    symbols: &Symbols<'p>,
) -> Checked {
    let mut out = check_program_walk(program, resolution, symbols, None, None);
    crate::literal::lower_tables(&mut out);
    check_std_deductions_total(program, &mut out);
    unmangle_scoped_locals(&mut out);
    out
}

/// [comptime-scope] Diagnostics in the author's terms: a local a scoped
/// comptime body renamed (`k__c3`) is named as written (`k`), wherever the
/// message came from.
fn unmangle_scoped_locals(out: &mut Checked) {
    for d in &mut out.errors {
        if let std::borrow::Cow::Owned(m) = crate::comptime::unmangle_message(&d.message) {
            d.message = m;
        }
    }
}

/// [std-cache] Checks a project reusing a `StdCache`: std's leading files are
/// not re-checked — their contracts are seeded from the cache and their
/// bodies are skipped in both the per-file walk and the deduction fixpoint
/// (ROADMAP §5 step 3). For the language server, where the same std is
/// checked against edit after edit. The caller is responsible for the
/// fallback (A4): use this only when the program's leading `cache.std_files`
/// files really are that std — no std shadow, project not itself `std = true`.
///
/// The result's std rows are exactly the cache's (seeded, not recomputed), so
/// it is identical to `check_program` on the project rows, which is all the
/// language server consumes. `check_std_deductions_total` is **not** run (std
/// is not being developed here, and its bodies were not walked).
pub fn check_project<'p>(
    program: &'p Program,
    resolution: &Resolution<'p>,
    symbols: &Symbols<'p>,
    cache: &StdCache,
) -> Checked {
    let mut out = check_program_walk(program, resolution, symbols, Some(cache), None);
    crate::literal::lower_tables(&mut out);
    unmangle_scoped_locals(&mut out);
    out
}

/// [lsp-check-cache] [`check_project`], reusing `check_cache`'s rows for
/// every file whose module is the one they were checked from, when no
/// interface has changed (`CheckCache::plan`): those files are not walked.
/// The result is what `check_project` gives; the cache is left holding every
/// project file's rows for the next check. For the language server, which
/// checks one program edit after edit.
pub fn check_project_cached<'p>(
    program: &'p Program,
    resolution: &Resolution<'p>,
    symbols: &Symbols<'p>,
    cache: &StdCache,
    check_cache: &mut crate::check_cache::CheckCache,
) -> Checked {
    let mut out = check_program_walk(program, resolution, symbols, Some(cache), Some(check_cache));
    crate::literal::lower_tables(&mut out);
    unmangle_scoped_locals(&mut out);
    out
}

/// [deduce-std-explicit] In a `std = true` tree, every exported bodied `fn`
/// must carry a **total** deduction clause: a plain entry for every
/// non-implicit parameter whose contract a caller could change (Copy scalars
/// excepted — their keep-all is invariant [copy-scalar-free]). The reason is
/// the std front-half cache (ROADMAP §5 step 3): a written entry is a fixed
/// point of inference [deduce-syntax], so once every exported std fn pins
/// every such parameter, std's checked contracts stop depending on the
/// project that uses it, and the cache is sound. An *unmentioned* parameter is
/// still inferred — so a merely-present clause (`=> []`, or one that lists some
/// parameters) is not enough; the clause must be total.
///
/// Fires only on `is_std && is_shadow` — a std tree **on disk**, which is what
/// `mark_std_tree` sets for a `std = true` manifest. The embedded std a normal
/// project carries is `is_std && !is_shadow`: the user cannot edit it, and once
/// std ships fully annotated it satisfies the rule anyway, so it is never
/// flagged.
///
/// Runs after the fixpoint, where `out.deductions` is the final inferred
/// contract — which is also what the diagnostic suggests as the fix, so the
/// clause to write is exactly the one the body already implies.
fn check_std_deductions_total(program: &Program, out: &mut Checked) {
    for (file_idx, (file, ast)) in program.files.iter().zip(&program.modules).enumerate() {
        if !(file.is_std && file.is_shadow) {
            continue;
        }
        for (item_idx, item) in ast.items.iter().enumerate() {
            let Item::Fn(f) = item else { continue };
            // Only exported, bodied, ordinary fns: a signature (intrinsic,
            // effect member) declares its contract already, a private fn is
            // not part of the public surface the cache keys on, and a
            // generated fn (`stamped`, `iter`) is not hand-written.
            if !f.exported || f.body.is_none() || f.intrinsic || f.is_iter || f.stamped.is_some() {
                continue;
            }
            // The parameters a total clause must mention: non-implicit, and
            // not a Copy scalar (whose keep-all cannot be changed by any
            // caller, so leaving it out is sound) [copy-scalar-free].
            let needed: Vec<&str> = f
                .params
                .iter()
                .filter(|p| !p.implicit && !is_copy_scalar_param(p))
                .map(|p| p.name.name.as_str())
                .collect();
            if needed.is_empty() {
                continue;
            }
            // Which of those the written clause already names with a plain
            // entry (a projection/`with`/`preserve`/result entry is extra, not
            // a parameter's own keptness entry — so it does not count).
            let mentioned: HashSet<&str> = f
                .deductions
                .iter()
                .flatten()
                .filter_map(|d| d.param_name())
                .map(|n| n.name.as_str())
                .collect();
            let missing: Vec<&str> = needed
                .iter()
                .copied()
                .filter(|n| !mentioned.contains(n))
                .collect();
            if missing.is_empty() {
                continue;
            }
            // Suggest the total clause the inferred contract implies: the fix
            // is correct by construction, since it is what the body produces.
            let key = out.decls.fn_at(file_idx, item_idx);
            let suggestion = out
                .deductions
                .get(&key)
                .map(|ded| total_deduction_clause(f, ded))
                .filter(|s| !s.is_empty());
            let fix = match suggestion {
                Some(clause) => format!(" — its inferred contract is `=> {clause}`"),
                None => String::new(),
            };
            out.errors.push(FileDiagnostic::error(
                file_idx,
                f.name.span,
                messages::deduce_std_explicit_uncovered_params(
                    &f.name.name,
                    &missing.iter().map(|n| format!("`{n}`")).collect::<Vec<_>>().join(", "),
                    &(if missing.len() == 1 { "is" } else { "are" }),
                    &fix,
                ),
            ));
        }
    }
}

/// [proj-local] Whether a type is itself a borrow at its top level: a `proj`
/// or `ref` value, or a union with such an arm (`proj Str?`). A Copy scalar's
/// `proj` erases, so it never is.
fn holds_top_borrow(t: &Ty) -> bool {
    let top = |t: &Ty| t.quals().iter().any(|q| crate::types::is_proj_name(&q.name));
    match t.strip_quals() {
        Ty::Union(arms) => top(t) || arms.iter().any(top),
        _ => top(t),
    }
}

/// [copy-scalar-free] A parameter typed as a bare Copy scalar (`Int`, `Long`,
/// `Float`, `Double`, `Bool`, `Char`, `Byte`, no qualifiers, no arguments):
/// its deduction is keep-all and no caller can change it, so a total clause
/// need not mention it.
fn is_copy_scalar_param(p: &ast::Param) -> bool {
    salvo_syntax::is_copy_scalar_type(&p.ty)
}

/// [deduce-std-explicit] The **total** deduction clause an inferred contract
/// implies: a plain entry for every non-implicit, non-scalar parameter —
/// `!p` moved, `p: ...` for a qualifier effect, bare `p` for keep-all (which
/// the hover omits but a total clause states, so inference treats it as
/// fixed) — plus a trailing `proj(...)` for inferred lends not already shown
/// on the return type. The order follows the parameter list.
fn total_deduction_clause(f: &ast::FnDecl, deductions: &[crate::deduce::ParamDeduction]) -> String {
    use crate::types::QualEffect;
    let by_name: HashMap<&str, &crate::deduce::ParamDeduction> =
        deductions.iter().map(|d| (d.param.as_str(), d)).collect();
    // Lends already shown as `-> T holds proj(p)` are not repeated.
    let opaque: HashSet<&str> = f
        .deductions
        .iter()
        .flatten()
        .filter(|d| matches!(d.target, ast::DeductionTarget::Opaque))
        .filter_map(|d| d.proj_sources())
        .flatten()
        .map(|i| i.name.as_str())
        .collect();
    let mut entries: Vec<String> = Vec::new();
    for p in &f.params {
        if p.implicit || is_copy_scalar_param(p) {
            continue;
        }
        let name = p.name.name.as_str();
        match by_name.get(name) {
            None => entries.push(name.to_string()),
            Some(d) if !d.kept => entries.push(format!("!{name}")),
            Some(d) => match &d.effect {
                QualEffect::KeepAll => entries.push(name.to_string()),
                QualEffect::Exhaustive(keep) if keep.is_empty() => {
                    entries.push(format!("{name}: None"))
                }
                QualEffect::Exhaustive(keep) => {
                    entries.push(format!("{name}: {}", keep.join(" ")))
                }
                QualEffect::Remove(dropped) => entries.push(format!(
                    "{name}: {}",
                    dropped
                        .iter()
                        .map(|q| format!("-{q}"))
                        .collect::<Vec<_>>()
                        .join(" ")
                )),
            },
        }
    }
    let lent: Vec<&str> = f
        .params
        .iter()
        .filter_map(|p| by_name.get(p.name.name.as_str()))
        .filter(|d| d.lent && !opaque.contains(d.param.as_str()))
        .map(|d| d.param.as_str())
        .collect();
    if !lent.is_empty() {
        entries.push(format!("proj({})", lent.join(", ")));
    }
    entries.join(", ")
}

/// [deduce-fixpoint] One walk over every body, then the deductions. Nothing
/// the walk learns feeds back into another walk: a binding's mode is decided
/// at its first moving use, inside the walk [fate-move-mode].
fn check_program_walk<'p>(
    program: &'p Program,
    resolution: &Resolution<'p>,
    symbols: &Symbols<'p>,
    cache: Option<&StdCache>,
    check_cache: Option<&mut crate::check_cache::CheckCache>,
) -> Checked {
    // [deduce-syntax] Parameters whose data the body mutates, published for
    // the backends' pass modes (`param_mode`); they never feed back into
    // checking.
    let mut mutations: HashMap<DeclId, HashSet<String>> = HashMap::new();
    // [actor-replyto] Handlers whose members mint a self-targeted
    // continuation, read off each handler's own text before anything is
    // walked (PIPELINE.md 4.5), so the `use` refusal it drives is right in
    // the first walk.
    let syntactic = syntactic_parking_handlers(program, symbols);
    let mut parking: HashSet<String> = syntactic.clone();

    // [std-cache] std is not walked, so the facts that also surface as `out`
    // tables are seeded with std's cached rows, or the final
    // `out.param_mutations = mutations` would drop them and
    // `parking_handlers` would lose std's parking handlers (which
    // `deadlock::check` reads).
    if let Some(cache) = cache {
        mutations.extend(
            cache
                .std_param_mutations()
                .map(|(k, v)| (*k, v.clone())),
        );
        parking.extend(cache.std_parking_handlers().cloned());
    }

    // [qual-refn] Refinements are resolved and validated once: they depend
    // on declarations and per-file visibility only, not on anything a
    // checking walk produces. The walk replays their diagnostics and reads
    // their table, so the two sides of a refinement — what it means
    // at a call site and what it means for a contract — cannot come from
    // different data.
    let t = crate::timing::phase("check: refinements");
    let refinements = crate::refine::collect(program, resolution);
    drop(t);
    // [deduce-default] Every fn's contract is a function of its signature
    // (user decision 2026-10-11), so it is known before any body is walked
    // (PIPELINE.md step 2): the first walk is a real one.
    let t = crate::timing::phase("check: contracts");
    let contracts = crate::deduce::contracts(program, &resolution.decls, cache);
    drop(t);

    let ctx = WalkCtx {
        program,
        resolution,
        symbols,
        inferred: &contracts,
        refinements: &refinements,
        cache,
    };
    let t = crate::timing::phase("check: walk");
    let mut out = check_once(&ctx, &mut mutations, &mut parking, check_cache.map(|c| (c, &syntactic)));
    drop(t);
    // [deduce-default] Each fn's contract against its body, and the
    // contracts themselves into the table every consumer reads.
    let t = crate::timing::phase("check: deduce");
    crate::deduce::infer(program, symbols, &mut out, cache.map(|c| c.std_files));
    drop(t);
    out.param_mutations = mutations;
    out
}

/// [actor-replyto] The handlers whose members mint a continuation into the
/// handler itself — `replyto k(…)` naming one of its own members, or
/// `self@Face` naming one of its faces — read off each handler's text
/// (PIPELINE.md 4.5), by handler key [type-identity]: by written name, a
/// parking `Srv` of one module refused the `use` of another module's `Srv`
/// that does not park (found 2026-10-29, PIPELINE.md C1). The walk resolves
/// the same names and refuses a wrong one, so this over-approximates only for
/// a program already in error.
fn syntactic_parking_handlers(program: &Program, symbols: &Symbols<'_>) -> HashSet<String> {
    use salvo_syntax::visit::{self as v, Visitor};
    struct Find<'h> {
        h: &'h ast::HandlerDecl,
        parks: bool,
    }
    impl Visitor for Find<'_> {
        fn visit_expr(&mut self, e: &Expr) {
            match e {
                Expr::ReplyTo { member, .. } if self.h.fns.iter().any(|f| f.name.name == member.name) => {
                    self.parks = true;
                }
                Expr::SelfAddr { face, .. }
                    if self.h.of.iter().any(|of| matches!(of, ast::Type::Named { base, .. } if base.name.name == face.name.name)) =>
                {
                    self.parks = true;
                }
                _ => {}
            }
            // The walk descends on its own: a hook that walked again would
            // recurse forever.
        }
    }
    let mut out = HashSet::new();
    for module in &program.modules {
        for item in &module.items {
            let Item::Handler(h) = item else { continue };
            let mut find = Find { h, parks: false };
            for f in h.fns.iter().chain(h.init.iter()) {
                if let Some(body) = &f.body {
                    v::walk_block(&mut find, body);
                }
            }
            if find.parks {
                out.insert(symbols.key_or(h, &h.name.name).to_string());
            }
        }
    }
    out
}


/// The program inputs the walk reads; `inferred` carries the contracts
/// [deduce-default].
struct WalkCtx<'a, 'p> {
    program: &'p Program,
    resolution: &'a Resolution<'p>,
    symbols: &'a Symbols<'p>,
    inferred: &'a HashMap<DeclId, Vec<crate::deduce::ParamDeduction>>,
    refinements: &'a crate::refine::Refinements,
    cache: Option<&'a StdCache>,
}

/// Every non-std file's interfaces, then every non-std body, each walked
/// once [decl-interface-pass] (std's facts come from the cache when there is
/// one).
fn check_once<'p>(
    ctx: &WalkCtx<'_, 'p>,
    param_mutations: &mut HashMap<DeclId, HashSet<String>>,
    parking_handlers: &mut HashSet<String>,
    check_cache: Option<(&mut crate::check_cache::CheckCache, &HashSet<String>)>,
) -> Checked {
    let WalkCtx { program, resolution, symbols, refinements, cache, .. } = *ctx;
    // [std-cache] Start from std's rows when caching (so project call sites
    // and whole-program passes read std facts without std being re-checked);
    // the std files themselves are skipped below. The whole-program tables
    // reset just below (`type_ref_span_keys` …) are recomputed over the merged
    // program — cheap, no body walk — so overwriting std's copies of them is
    // correct.
    let t = crate::timing::phase("  check: seed");
    let mut out = match cache {
        Some(cache) => cache.seeded(),
        None => Checked::default(),
    };
    // [decl-id] This program's declarations (a seed's are std's alone).
    out.decls = resolution.decls.clone();
    drop(t);
    let t = crate::timing::phase("  check: written keys");
    match cache.filter(|c| c.shares_modules(program)) {
        // [lsp-std-front] std's modules are the cache's own, so the seed's
        // keys are std's references' keys at these very addresses (a std
        // reference resolves in a std scope, and std's declarations keep
        // their keys in front of any project's): only the project's are
        // computed, and merged into std's by-span entries as gathering
        // them together would.
        // [node-file] A project file's tag is no std file's, so its keys
        // join std's without meeting them.
        Some(c) => {
            let mut part = crate::resolve::SpanKeys::new();
            crate::resolve::span_keys_from(program, resolution, symbols, c.std_files, &mut part);
            out.type_ref_span_keys.extend(crate::resolve::span_keys_final(part));
        }
        None => {
            out.type_ref_span_keys = crate::resolve::written_keys_by_span(program, resolution, symbols);
        }
    }
    symbols.seed_ref_keys(&out.type_ref_span_keys);
    drop(t);
    let t = crate::timing::phase("  check: value keys");
    out.value_span_keys = crate::resolve::value_keys(resolution, symbols);
    drop(t);
    let t = crate::timing::phase("  check: protocol hashes");
    out.errors.extend(resolution.errors.iter().cloned());
    // [actor-protocol-hash] One hash per actor effect, over its canonical form.
    for (name, effect) in &symbols.effects {
        if effect.is_actor {
            let canonical = crate::wire::protocol_canonical(symbols, effect);
            out.protocol_hashes
                .insert(name.to_string(), crate::wire::protocol_hash(&canonical));
        }
    }
    // [qual-refn] Refinement validation reads no body; its diagnostics are
    // replayed here so they land with everything else.
    out.errors.extend(refinements.errors.iter().cloned());
    out.refinements = refinements.clone();
    drop(t);
    let t = crate::timing::phase("  check: platform closure");
    out.platform_closure_all = crate::abi::platform_closure_all(program, symbols);
    drop(t);
    let first = cache.map_or(0, |c| c.std_files);
    let files: Vec<usize> = (first..program.files.len()).collect();
    let mut ifaces: Vec<FileIface<'p>> = (0..program.files.len()).map(|_| FileIface::default()).collect();
    // [lsp-check-cache] Which files' rows stand in for their walks.
    let t = crate::timing::phase("  check: cache plan");
    let (check_cache, syntactic) = match check_cache {
        Some((c, syntactic)) => (Some(c), Some(syntactic)),
        None => (None, None),
    };
    let mut check_cache = check_cache;
    // [lsp-check-cache] One file is walked whatever the cache holds, so a
    // single-file program pays for nothing it could use: no plan, no record.
    if files.len() < 2 {
        if let Some(c) = check_cache.take() {
            c.skip(&files);
        }
    }
    let cached: HashSet<usize> = match (&mut check_cache, syntactic) {
        (Some(c), Some(syntactic)) => c.plan(program, first, syntactic),
        _ => HashSet::new(),
    };
    drop(t);
    let mut steps = Steps {
        cache: check_cache.as_deref(),
        cached,
        record: check_cache.is_some(),
        walked: HashMap::new(),
        inserting: std::time::Duration::ZERO,
    };
    walk_interfaces(ctx, &files, &mut out, param_mutations, parking_handlers, &mut ifaces, &mut steps);
    walk_bodies(ctx, &files, &mut out, param_mutations, parking_handlers, &mut ifaces, &mut steps);
    crate::timing::report("  check: cache insert", steps.inserting);
    let mut walked: Vec<(usize, [crate::check_cache::StepRows; 3])> = steps.walked.into_iter().collect();
    walked.sort_by_key(|(f, _)| *f);
    if let (Some(c), Some(syntactic)) = (check_cache, syntactic) {
        let _t = crate::timing::phase("  check: cache record");
        let walked_files: Vec<usize> = walked.iter().map(|(f, _)| *f).collect();
        let owners = crate::partition::Owners::new(program, symbols, &out.decls, &walked_files, false);
        c.record(program, first, syntactic, &out, param_mutations, walked, &owners);
    }
    program_checks(program, symbols, &mut out, parking_handlers);
    out
}

/// [lsp-check-cache] How the walks treat each file under a `CheckCache`:
/// the cached files' rows are inserted where their walks would run, and what
/// every walked file's steps did is recorded.
struct Steps<'c> {
    cache: Option<&'c crate::check_cache::CheckCache>,
    cached: HashSet<usize>,
    record: bool,
    walked: HashMap<usize, [crate::check_cache::StepRows; 3]>,
    /// The time spent inserting cached rows, for `check: cache insert`.
    inserting: std::time::Duration,
}

impl Steps<'_> {
    /// The rows standing in for file [f]'s walks, when it is cached.
    fn cached(&self, f: usize) -> Option<&crate::check_cache::FileRows> {
        if !self.cached.contains(&f) {
            return None;
        }
        self.cache.and_then(|c| c.rows(f))
    }

    /// Stands in for step [step] of a cached file [f]: its keyed rows with
    /// the first step, and what each step appended.
    fn insert(
        &mut self,
        f: usize,
        step: usize,
        out: &mut Checked,
        param_mutations: &mut HashMap<DeclId, HashSet<String>>,
        parking_handlers: &mut HashSet<String>,
    ) -> bool {
        let Some(rows) = self.cached(f) else { return false };
        let started = std::time::Instant::now();
        if step == crate::check_cache::FACTS {
            out.insert_rows(&rows.rows);
            param_mutations.extend(rows.rows.param_mutations.iter().map(|(k, v)| (*k, v.clone())));
        }
        rows.steps[step].apply(out, parking_handlers);
        self.inserting += started.elapsed();
        true
    }

    /// Records what step [step] of walked file [f] did.
    fn note(&mut self, f: usize, step: usize, marks: crate::check_cache::StepMarks, out: &Checked, logs: (Vec<(usize, Ty, bool)>, Vec<String>)) {
        if self.record {
            self.walked.entry(f).or_default()[step] = marks.take(out, logs.0, logs.1);
        }
    }
}

/// [decl-interface-pass] The checker over one file, for one pass. Every pass gets
/// a fresh one; what a later pass needs from an earlier one goes through
/// `FileIface` (`take_iface` / `put_iface`).
fn file_checker<'r, 'p>(
    ctx: &WalkCtx<'r, 'p>,
    file_idx: usize,
    pass: Pass,
    out: &'r mut Checked,
    param_mutations: &'r mut HashMap<DeclId, HashSet<String>>,
    parking_handlers: &'r mut HashSet<String>,
) -> Checker<'p, 'r> {
    let file = &ctx.program.files[file_idx];
    let mut checker = Checker::new(
        file_idx,
        file.is_std,
        &ctx.program.files,
        &ctx.resolution.scopes[file_idx],
        ctx.resolution,
        ctx.symbols,
        ctx.inferred,
        ctx.refinements,
        out,
        param_mutations,
        parking_handlers,
    );
    checker.pass = pass;
    checker.runtime_files = ctx
        .program
        .files
        .iter()
        .map(|f| f.is_std && f.module.is_std_internal())
        .collect();
    checker
}

/// [decl-interface-pass] 02-resolve-03-interfaces: every declaration's
/// interface, checked with its diagnostics before any body is walked, from
/// the declaration's own text and other interfaces only. Two steps over the
/// program: first the signature facts other interfaces read out of tables
/// (implicit parameters, established claims, effect lists:
/// `check_signature_facts`), then everything else in every header
/// (`check_module` with `Pass::Interface`, and the platform boundary). Each
/// file's records go to its body pass in `ifaces`.
#[allow(clippy::too_many_arguments)]
fn walk_interfaces<'p>(
    ctx: &WalkCtx<'_, 'p>,
    files: &[usize],
    out: &mut Checked,
    param_mutations: &mut HashMap<DeclId, HashSet<String>>,
    parking_handlers: &mut HashSet<String>,
    ifaces: &mut [FileIface<'p>],
    steps: &mut Steps<'_>,
) {
    use crate::check_cache::{StepMarks, FACTS, HEADERS};
    let _t = crate::timing::phase("  check: interfaces");
    let facts = crate::timing::phase("    interfaces: facts");
    for &file_idx in files {
        if steps.insert(file_idx, FACTS, out, param_mutations, parking_handlers) {
            continue;
        }
        let marks = StepMarks::of(out);
        let mut checker = file_checker(ctx, file_idx, Pass::Interface, out, param_mutations, parking_handlers);
        checker.record = steps.record;
        checker.put_iface(std::mem::take(&mut ifaces[file_idx]));
        checker.check_signature_facts(&ctx.program.modules[file_idx]);
        let logs = checker.take_logs();
        ifaces[file_idx] = checker.take_iface();
        steps.note(file_idx, FACTS, marks, out, logs);
    }
    drop(facts);
    let _headers = crate::timing::phase("    interfaces: headers");
    for &file_idx in files {
        if steps.insert(file_idx, HEADERS, out, param_mutations, parking_handlers) {
            continue;
        }
        let ast = &ctx.program.modules[file_idx];
        let marks = StepMarks::of(out);
        let mut checker = file_checker(ctx, file_idx, Pass::Interface, out, param_mutations, parking_handlers);
        checker.record = steps.record;
        checker.put_iface(std::mem::take(&mut ifaces[file_idx]));
        checker.check_module(ast);
        // [platform-check] The values the host hands back, planned from
        // signatures.
        checker.check_platform_boundary(ast);
        // [handler-state-infer] A minter checked with the interfaces made bindings.
        checker.finish_fate();
        let logs = checker.take_logs();
        ifaces[file_idx] = checker.take_iface();
        steps.note(file_idx, HEADERS, marks, out, logs);
    }
}

/// 02-resolve-05-bodies: the bodies of [files], each walked once, reading
/// the interfaces `walk_interfaces` recorded [decl-interface-pass].
#[allow(clippy::too_many_arguments)]
fn walk_bodies<'p>(
    ctx: &WalkCtx<'_, 'p>,
    files: &[usize],
    out: &mut Checked,
    param_mutations: &mut HashMap<DeclId, HashSet<String>>,
    parking_handlers: &mut HashSet<String>,
    ifaces: &mut [FileIface<'p>],
    steps: &mut Steps<'_>,
) {
    use crate::check_cache::{StepMarks, BODIES};
    let _t = crate::timing::phase("  check: bodies");
    for &file_idx in files {
        if steps.insert(file_idx, BODIES, out, param_mutations, parking_handlers) {
            continue;
        }
        let ast = &ctx.program.modules[file_idx];
        let marks = StepMarks::of(out);
        let mut checker = file_checker(ctx, file_idx, Pass::Body, out, param_mutations, parking_handlers);
        checker.record = steps.record;
        checker.put_iface(std::mem::take(&mut ifaces[file_idx]));
        checker.check_module(ast);
        checker.finish_fate();
        let logs = checker.take_logs();
        drop(checker);
        steps.note(file_idx, BODIES, marks, out, logs);
    }
}

/// The whole-program checks, after every body: they read what the walk
/// recorded.
fn program_checks(program: &Program, symbols: &Symbols<'_>, out: &mut Checked, parking_handlers: &HashSet<String>) {
    let _t = crate::timing::phase("  check: program checks");
    check_intrinsic_is_std_only(program, out);
    check_module_uses(program, out);
    check_runtime_layers(program, out);
    // [actor-deadlock-cycle] The static deadlock baseline, over the whole
    // program: a cycle of waiting actors is an error, a cycle of blocking
    // sends a warning. Last, because it reads what this walk recorded
    // (`actor_gates`, `actor_sends`).
    out.parking_handlers = parking_handlers.clone();
    crate::deadlock::check(program, symbols, out);
}

/// [platform-intrinsic-std-only] `intrinsic` marks a declaration the *compiler*
/// implements, so only the standard library may write it (user decision
/// 2026-09-05: a customer has no business declaring `intrinsic` if the
/// compiler does not already declare it).
///
/// The parser cannot enforce this — it sees one file's tokens and knows
/// nothing about where the file came from — so the rule lives here, where
/// `SourceFile::is_std` is at hand. It is not a cosmetic restriction: the
/// backends dispatch intrinsics from a table keyed by *name*
/// [backend-intrinsic], so an intrinsic the compiler does not know has no
/// lowering anywhere. The error names the one interop path customer code
/// does have.
/// [mod-use] A module-level `use` is the runtime module's privilege (user
/// decision 2026-10-02, runtime E4): anywhere else it would be hidden
/// state by another name.
fn check_module_uses(program: &Program, out: &mut Checked) {
    for (file_idx, (file, ast)) in program.files.iter().zip(&program.modules).enumerate() {
        let runtime = file.is_std && file.module.is_std_internal();
        if runtime {
            continue;
        }
        for u in &ast.uses {
            out.errors.push(crate::diag::FileDiagnostic::error(
                file_idx,
                u.span,
                messages::mod_use_module_level(),
            ));
        }
    }
}

/// [runtime-layers] The runtime's core (`lib/std/runtime.sv`, module `std.runtime`)
/// implements the actor forms, and its services (`std.runtime.*`, the deadline
/// wheel) are actors built on it: the core importing a service would let the
/// scheduler depend on something that depends on the scheduler. Refused at
/// the import.
fn check_runtime_layers(program: &Program, out: &mut Checked) {
    for (file_idx, (file, ast)) in program.files.iter().zip(&program.modules).enumerate() {
        let core = file.is_std && file.module == crate::ModulePath::std(&[crate::resolve::STD_INTERNAL]);
        if !core {
            continue;
        }
        for item in &ast.items {
            let Item::Import(import) = item else { continue };
            let path: Vec<&str> = import.path.iter().map(|p| p.name.as_str()).collect();
            if path.len() >= 3
                && path[0] == crate::STD_ROOT
                && path[1] == crate::resolve::STD_INTERNAL
                && path[2].starts_with(|c: char| c.is_lowercase())
            {
                out.errors.push(crate::diag::FileDiagnostic::error(
                    file_idx,
                    import.span,
                    messages::runtime_layers_core_imports_service(&path[..3].join(".")),
                ));
            }
        }
    }
}

fn check_intrinsic_is_std_only(program: &Program, out: &mut Checked) {
    for (file_idx, (file, ast)) in program.files.iter().zip(&program.modules).enumerate() {
        if file.is_std {
            continue;
        }
        for item in &ast.items {
            let (kind, name, span) = match item {
                Item::Fn(f) if f.intrinsic => ("fn", &f.name.name, f.name.span),
                Item::Type(t) if t.intrinsic => ("type", &t.name.name, t.name.span),
                Item::Handler(h) if h.intrinsic => ("handler", &h.name.name, h.name.span),
                Item::Qualifier(q) if q.intrinsic => ("qualifier", &q.name.name, q.name.span),
                _ => continue,
            };
            out.errors.push(crate::diag::FileDiagnostic::error(
                file_idx,
                span,
                messages::platform_intrinsic_std_only_outside_std(&kind, &name),
            ));
        }
    }
}

/// [platform-check] Whether a written type borrows (`proj` or `ref`)
/// anywhere.
fn ast_mentions_proj(ty: &ast::Type) -> bool {
    match ty {
        ast::Type::Named { qualifiers, base } => {
            qualifiers.iter().any(|q| crate::types::is_proj_name(&q.name.name)) || base.args.iter().any(ast_mentions_proj)
        }
        ast::Type::QualifiedGroup { qualifiers, base, .. } => {
            qualifiers.iter().any(|q| crate::types::is_proj_name(&q.name.name)) || ast_mentions_proj(base)
        }
        ast::Type::Union { arms, .. } | ast::Type::Tuple { elems: arms, .. } => arms.iter().any(ast_mentions_proj),
        ast::Type::Array { elem, .. } | ast::Type::Nullable { inner: elem, .. } => ast_mentions_proj(elem),
        _ => false,
    }
}

/// [effect-member-unique] A member name is unique **within its effect**.
/// Across effects the name may recur ([effect-member-overload], user
#[derive(Clone)]
struct LocalVar {
    declared: Ty,
    narrowed: Ty,
    /// Unique id of this binding (stable across scopes; names can recur
    /// in sibling scopes) [fate-link].
    id: u32,
    /// Fate links [fate-link]: the variables this one was bound from (a
    /// bare identifier or projection), flattened transitively. A linked
    /// (derived) variable is read-only in S1 [fate-derived-readonly] and
    /// is poisoned when a root is mutated or moved [fate-poison].
    links: Vec<FateLink>,
    /// Whether this variable is a parameter (or handler state field) of
    /// the enclosing fn: a parameter root is *owned* for move-mode
    /// bindings only when the fn's effective contract moves it
    /// [fate-move-mode]; locals are always owned.
    is_param: bool,
    /// For `for`-loop bindings: the span of the iterable expression.
    /// When a move-mode binding takes ownership through such a root, the
    /// loop iterates by value, keyed by this span [fate-move-mode]
    /// (`BindFact::origins`, `Checked::by_value_loops`).
    for_origin: Option<Span>,
    /// Where the variable was declared (for linear-obligation
    /// diagnostics [linear-obligation]).
    decl_span: Span,
    /// A lambda parameter whose fn-type contract *keeps* it
    /// [fn-contract]: the value belongs to the caller — read-only-ish
    /// (mutation is type-gated by `Mut`), never consumable.
    lambda_kept: bool,
    /// A handler *state* field [effect-handler]: it outlives every member
    /// call, so assigning a value into it is a **store** — the handler
    /// takes ownership, exactly as a struct literal does
    /// [effect-state-store]. Ordinary locals link instead [fate-link].
    is_handler_state: bool,
    /// [qual-lift] While a `^` check holds, the *physical* view of this
    /// variable: the arm test peeled a wrapper, so reads and any further
    /// narrowing compose on the inner value rather than on the storage.
    /// `None` outside a widening branch (`declared` is then the view). The
    /// emitters materialize the peel as a branch-local temporary.
    widened: Option<Ty>,
    /// Narrowed *projections* out of this variable [flow-place]: flow
    /// facts about `h.field`, keyed by the projection path. The
    /// variable's own narrowing stays in `narrowed`; keeping the
    /// projections here is what makes an event on the root — mutation,
    /// reassignment, a move — invalidate every fact below it, and what
    /// keeps `snapshot_narrows`/`restore_narrows`/`merge_fallthrough` the
    /// single source of truth for flow state.
    place_narrows: Vec<PlaceNarrow>,
    /// [var-unused] Whether the variable has been *read*. Assignment is
    /// not a read: `let x = 1` followed only by `x = 2` never uses the
    /// value. Checked when the scope closes; a `_` prefix opts out.
    used: bool,
}

/// One narrowed projection place [flow-place]: the path out of the
/// variable, the type reads of that place have while the fact holds, and
/// the *declared* (physical) type the storage keeps — narrowing never
/// re-wraps storage, so reads unwrap from `declared` to `narrowed` and
/// both the checker (`repr_ty`) and the emitters need it.
#[derive(Clone, PartialEq)]
struct PlaceNarrow {
    path: Vec<Step>,
    narrowed: Ty,
    declared: Ty,
}

/// One fate link [fate-link]: the derived variable was bound from (a
/// projection of) the root variable at `bind_span`.
#[derive(Clone, Debug, PartialEq)]
struct FateLink {
    root_id: u32,
    root_name: String,
    bind_span: Span,
    /// [fate-field-disjoint] **Which projection of the root** the derived
    /// value came from, as the path out of it: `let n = p.name` links with
    /// `[.name]`, `let q = p` with `[]` (the whole variable). `None` when
    /// the derivation is not a plain projection chain (a `!` unwrap, say) —
    /// conservative: an unknown path overlaps every event.
    ///
    /// An event poisons this link only when the two paths *overlap*
    /// ([`Place::overlaps`], the substrate P1 built), so mutating `p.tags`
    /// leaves a value derived from `p.name` alone.
    path: Option<Vec<Step>>,
    /// The link passes through a derived-return call [proj-readonly-return]:
    /// the value is *physically borrowed*, so move-mode can never take
    /// ownership through it [fate-move-mode].
    borrowed: bool,
    /// [proj-infer] The borrow is *held by fields*: the variable is an owned
    /// object of its own (a struct with `proj` fields — a pass over a list)
    /// whose fields project the root, rather than the root's data itself.
    /// Such a variable may be mutated (its own fields are its own) and moved
    /// (the object travels, the borrow with it); what it may not do is
    /// outlive the root. `false` for a wholesale projection (`get(xs, i)`,
    /// a `for` element of a view), which *is* the root's data
    /// [proj-readonly].
    held: bool,
    /// [deduce-field] Whether the derivation reaches **through a
    /// destroyability boundary** — an element of a container, a union
    /// arm's payload — rather than staying on inline storage (a field
    /// chain, a whole-variable alias). Rung ⑤ v2: a *contents* mutation of
    /// a field (`=> h.tags: Mut`) spares a derivation that does **not**
    /// cross (a handle to the container itself, whose identity survives)
    /// and still kills one that does (an element, whose storage may be
    /// gone).
    ///
    /// **Conservative by default (`true`)**, and deliberately not inferred
    /// from the path steps: `first(h.tags)` records path `[.tags]` with the
    /// element-crossing nowhere in it, so only derivations the analysis can
    /// *see* are inline — a pure field chain or alias of a place — get
    /// `false`.
    crosses: bool,
    /// [fate-elem-distinct] The **identity of the minting index** of an element
    /// handle: the id of the bound handle itself, stamped when it is
    /// declared [ref-notsame]. Two handle links into the same root at the
    /// same path whose identities are proven apart by a live `NotSame`
    /// claim name disjoint storage, so mutation through one spares the
    /// other from poison. Erased (eagerly, at the event) when the handle
    /// is rebound. `None` for every other
    /// derivation: may-alias, today's conservative rule
    /// [fate-field-disjoint].
    elem_idx: Option<u32>,
}

impl FateLink {
    /// [fate-field-disjoint] Whether an event on `event_path` reaches this
    /// link. Either path unknown is conservative (they overlap): a
    /// derivation the analysis cannot spell must not be given precision it
    /// has not earned.
    fn overlaps_event(&self, event_path: Option<&[Step]>) -> bool {
        let (Some(link), Some(event)) = (self.path.as_deref(), event_path) else {
            return true;
        };
        // Same root by construction (the caller matched `root_id`), so the
        // paths alone decide.
        let as_place = |path: &[Step]| Place {
            root: String::new(),
            path: path.to_vec(),
        };
        as_place(link).overlaps(&as_place(event))
    }
}

/// Flow state of one local: narrowed type plus fate links [fate-link], and
/// the narrowed projections out of it [flow-place].
#[derive(Clone, PartialEq)]
struct VarState {
    narrowed: Ty,
    links: Vec<FateLink>,
    place_narrows: Vec<PlaceNarrow>,
}


/// Flow state of every local, per scope frame [deduce-consume].
type NarrowSnapshot = Vec<HashMap<String, VarState>>;

/// An `is`/`when`/`for` binding to declare in a branch scope: name, type,
/// the fate links inherited from the subject [fate-link], and — for
/// `for`-loop bindings — the span of the iterable expression
/// [fate-move-mode].
type Binding = (Ident, Ty, Vec<FateLink>, Option<Span>);

/// [decl-interface-pass] Which half of each declaration a checking walk does
/// (PIPELINE.md §2, 02-resolve-03-interfaces). Every file's interfaces are
/// checked, with their diagnostics, before any body: `Interface` runs over
/// each file twice (signature facts, then the rest of every header), and
/// `Body` over each file once, reading what `Interface` recorded.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Pass {
    Interface,
    Body,
}

impl Pass {
    fn interface(self) -> bool {
        self == Pass::Interface
    }
    fn body(self) -> bool {
        self == Pass::Body
    }
}

/// [decl-interface-pass] A fn's signature facts that other declarations'
/// interfaces read, recorded first for every fn of the program
/// (`check_signature_facts`): its implicit parameters [implicit-param], and
/// its own effect list [fn-effects] (`check_effect_list`).
#[derive(Clone)]
struct SigFacts {
    implicits: Vec<ImplicitParam>,
    effects: Vec<EffectAvail>,
    can_use: bool,
    can_spawn: bool,
}

/// [decl-interface-pass] A fn's interface as its body walk reads it: what
/// `check_fn` used to compute in its first lines, recorded by the interface
/// pass and installed by the body pass.
#[derive(Clone)]
struct FnSig {
    implicits: Vec<ImplicitParam>,
    /// The effect environment the body starts with: the fn's own list, plus
    /// the dependencies a handler member inherits [effect-handler-deps].
    effects: Vec<EffectAvail>,
    can_use: bool,
    can_spawn: bool,
    derived_return: Option<String>,
    preserve: HashMap<String, Vec<String>>,
    derived_sources: Vec<String>,
    lends_declared: bool,
    lends: Vec<String>,
    proj_arms: Vec<String>,
    linear_generics: HashSet<String>,
    /// What the body's returns are checked against: the written return
    /// type with established claims stripped [deduce-reapply]; `None` for a
    /// bodiless fn.
    ret_ty: Ty,
}

/// [decl-interface-pass] A handler's header, as its members' bodies read it.
#[derive(Clone)]
struct HandlerSig {
    of_tys: Vec<Ty>,
    deps: Vec<EffectAvail>,
    spawns: bool,
    mixed: bool,
}

/// [decl-interface-pass] What the interface pass hands one file's body pass:
/// the per-declaration records (keyed by declaration address, stable for
/// one program), the module's renames, and the file's once-per-file
/// diagnostic memories, so a mistake the header reported is not reported
/// again by a body that meets it.
#[derive(Default)]
struct FileIface<'p> {
    facts: HashMap<usize, SigFacts>,
    fns: HashMap<usize, FnSig>,
    handlers: HashMap<usize, HandlerSig>,
    renames: Vec<RenameBinding<'p>>,
    reported_ineligible_keys: HashSet<String>,
    /// [cmp-carry] Written identities already refused as ambiguous: a
    /// written type is lowered at every use, and one mistake is one
    /// diagnostic.
    reported_identities: HashSet<(usize, Span)>,
    warned_spare_lends: HashSet<(usize, Span)>,
    lends_memo: HashMap<usize, Vec<usize>>,
}

struct Checker<'p, 'r> {
    /// [decl-interface-pass] Which half of each declaration this walk checks.
    pass: Pass,
    /// [decl-interface-pass] The file's interface records: written by the
    /// interface pass, read by the body pass.
    iface: FileIface<'p>,
    scope: &'r ModuleScope<'p>,
    /// The whole-program resolution (for import suggestions on
    /// unresolved names [diag-import-suggest]).
    resolution: &'r Resolution<'p>,
    /// The signature contracts, enforced at call sites for
    /// fns without a written list [deduce-consume], from their signatures
    /// (`deduce::contracts`), known before any body is walked.
    inferred: &'r HashMap<DeclId, Vec<crate::deduce::ParamDeduction>>,
    /// [qual-refn] Refinements applying per (file, callee), resolved once
    /// for the whole program.
    refinements: &'r crate::refine::Refinements,
    symbols: &'r Symbols<'p>,
    file_idx: usize,
    /// Every source file, for which module a declaration's file is
    /// [struct-opaque].
    files: &'p [crate::source::SourceFile],
    out: &'r mut Checked,
    /// Lexical scope stack of local variables (params + lets + bindings).
    locals: Vec<HashMap<String, LocalVar>>,
    /// [col-key-eligible] Types already reported as ineligible keys in this
    /// file, so one mistake produces one diagnostic even when both a written
    /// annotation and the call it types arrive at the same type.
    reported_ineligible_keys: HashSet<String>,
    /// [cmp-carry] Written identities already refused as ambiguous: a written
    /// type is lowered at every use, and one mistake is one diagnostic.
    reported_identities: HashSet<(usize, Span)>,
    /// Generic type parameters currently in scope.
    generics: HashSet<String>,
    /// Return type of the function being checked.
    ret_ty: Ty,
    /// Names of qualifiers declared in the file currently being checked
    /// (constructive-qualifier constructors must live in this file).
    own_qualifiers: HashSet<String>,
    /// Effect instances available to the code being checked: the current
    /// fn's declared effect dependencies plus `use`d handlers. Entries
    /// added by `use` are truncated at block boundaries.
    effect_env: Vec<EffectAvail>,
    /// [fn-param-default] The fixed-parameter names of the call currently
    /// resolving its implicits, so a named argument that fills an ordinary
    /// defaulted parameter is not mistaken for an unknown implicit. Set
    /// around `resolve_implicits`, empty elsewhere.
    call_fixed_params: HashSet<String>,
    /// [effect-handler-deps] The effects declared by the handler whose
    /// members are being checked (`handler H [E1, E2] of E`), empty
    /// elsewhere. A member may use them exactly as if it had declared them,
    /// which it may not ([effect-member-no-effects]).
    handler_deps: Vec<EffectAvail>,
    /// [mod-use] The effects the module's own `use H()` lines bind: in scope
    /// in every function of the module, never declared by one.
    module_avails: Vec<EffectAvail>,
    /// [runtime-kept-fn] Per file: whether it belongs to std's runtime.
    runtime_files: Vec<bool>,
    /// [effect-handler-deps] The effect implemented by the handler whose
    /// members are being checked, so a member calling *its own* effect can be
    /// told what is actually wrong: self-dispatch is not a feature yet, and
    /// neither remedy the general "no handler" diagnostic names is available
    /// inside a member.
    /// [effect-handler-multi] The effects the handler being checked
    /// implements, in declaration order — empty outside a handler. Several is
    /// the multi-face case, and every rule that used to read "the effect this
    /// handler implements" now reads "any of them".
    handler_ofs: Vec<Ty>,
    /// [actor-replyto] The handler whose members are being checked, so a
    /// `replyto k(...)` can find `k`: a continuation targets a member of the
    /// *enclosing* handler, which is what makes the form legal only inside
    /// one.
    own_handler: Option<&'p ast::HandlerDecl>,
    /// [actor-spawn-effect] Whether the handler whose members are being
    /// checked declared `spawn` among its dependencies. Its members inherit
    /// the capability, exactly as they inherit its effects.
    handler_spawns: bool,
    /// [task-mint] The **free `send fn`** whose body is being checked, if any:
    /// what its sends and its own mints are attributed to.
    own_task: Option<String>,
    /// [actor-mixed-handler] The handler whose **sync member** is being checked,
    /// when that handler is mixed (plain faces + `send fn` members, SH-1):
    /// the member is the façade, running on the caller's thread over the
    /// façade value. What it changes: bare calls to the handler's own send
    /// members resolve as sends to the servant, state fields are out of
    /// scope (`confined_state` carries their names for the diagnostic),
    /// handler dependencies are invisible (they live in the servant), and a
    /// `waitfor` needs no capability (SH-5(d)'s down payment — the façade
    /// does not run on the spawned thread at all).
    facade_handler: Option<&'p ast::HandlerDecl>,
    /// [actor-mixed-handler] The state field names confined to the servant while a
    /// façade member is checked — consulted by the unresolved-name path, so
    /// touching one is the confinement diagnostic rather than an "unknown
    /// variable".
    confined_state: Vec<String>,
    /// [linear-defer] [actor-mixed-handler] The `Reply`-typed parameters of the
    /// **mixed send member** being checked, each with whether its clause
    /// declares `defer`. `Some` only in that context: it is the rung-4
    /// contract point — an escape of an undeclared reply is refused there,
    /// and nowhere else is the declaration required.
    servant_reply_params: Option<Vec<(String, bool)>>,
    /// Whether the current fn declared the special `use` effect.
    can_use: bool,
    /// [expr-placeholder] The type `_` reads as, when a construct has bound one — a
    /// qualifier pick's unpicked arm [pick]. `None` elsewhere, which is what
    /// keeps a stray `_` an error.
    placeholder_ty: Option<Ty>,
    /// [expr-pipe] Set when a `_` placeholder is read while checking a pipe's
    /// right side, so `check_pipe` can refuse a right side that ignores the
    /// piped value. Reset around each pipe right side.
    placeholder_read: bool,
    /// [actor-spawn-effect] Whether the current fn (or the handler whose
    /// member it is) declared the `spawn` capability — the gate a `spawn`
    /// expression checks.
    can_spawn: bool,
    /// Enclosing loops of the code being checked; `break`/`continue`
    /// statements record their value contributions into the innermost
    /// entry [loop-while-value]. Lambda bodies are a barrier.
    loop_stack: Vec<LoopCtx>,
    /// [iter-fn] Origins whose `for` loops are currently open: the
    /// root variable's name and the span to blame. A hidden machine reads
    /// its origin *across suspensions*, so a write while the loop runs has
    /// two defensible meanings — the machine's own copy, or the caller's
    /// object — and the two backends each pick one. Refused rather than
    /// sided with [backend-parity], which is also what keeps a value
    /// *derived* from the origin valid for the whole drive.
    driven_origins: Vec<(String, Span)>,
    /// [deduce-field] Mutation paths of the current fn's **parameters**, as
    /// recorded while its body is checked: the raw material for validating
    /// a written field entry (`=> h.tags: Mut` must cover every mutation
    /// the body performs on `h`) and, next, for inferring one. `None` is an
    /// unknown path — conservative, so it covers nothing.
    own_mut_paths: Vec<(String, Option<Vec<Step>>, bool)>,
    /// Fresh-id counter for local bindings [fate-link], per declaration
    /// [node-id].
    next_var_id: u32,
    /// [node-id] The declaration the last key was in (`DeclIndex::key`).
    key_hint: std::cell::Cell<usize>,
    /// [fate-poison] [fate-move-mode] Every binding's links by the fate key
    /// `record_fate_bind` is given (the bound name or an assignment's
    /// target), with the binding's span: written into `Checked::bind_facts`
    /// when the file's walk ends (`finish_fate`).
    fate_log: HashMap<Span, (Span, Vec<FateLink>)>,
    /// [fate-move-mode] Per fate key, whether any encounter of the binding
    /// may take ownership, and the `for` loops its roots are bound by
    /// (`Checked::bind_facts`).
    fate_meta: HashMap<Span, (bool, Vec<Span>)>,
    /// [deduce-syntax] Parameters whose data the body mutates — recorded
    /// for *every* fn (written lists included), since the written-list
    /// validation needs them.
    param_mutations: &'r mut HashMap<DeclId, HashSet<String>>,
    /// [actor-replyto] Handlers whose member bodies mint a **self**-targeted
    /// continuation, read off each handler's text before the walk
    /// (`syntactic_parking_handlers`), since a `use` may be checked before
    /// the handler it names.
    ///
    /// The refusal is [actor-replyto]'s: parking is the one thing only a
    /// actor can do, so a parking handler may only be `spawn`ed. Using the
    /// checker's own traversal to find the mints — rather than a tenth
    /// exhaustive expression walker — is what keeps this complete as the
    /// grammar grows.
    parking_handlers: &'r mut HashSet<String>,
    /// The fn currently being checked, when it is a top-level `fn` item
    /// (member fns have no key).
    own_fn: Option<DeclId>,
    /// [lsp-completion] The body span of the fn whose body is being checked,
    /// recorded with every local it declares so the language server can offer
    /// the locals visible at a cursor inside that body. `None` outside a body.
    cur_fn_body: Option<Span>,
    /// [comptime-fields] Inside a `comptime struct`/`comptime type` declaration:
    /// its fields may name the other compile-time types.
    in_comptime_decl: bool,
    /// [generic-arity] Suppresses the generic-argument-count check in
    /// `lower_base_ref` while validating a struct **literal's** own written
    /// type (`check_struct_lit`'s `self.validate_type(t)`/`self.lower_type(t)`
    /// calls): a literal may omit its arguments and infer them from its
    /// field values [struct-literal-arg], which a bare type-position
    /// reference (a field declaration, a parameter) cannot — there are no
    /// values there to infer from, so that case is still checked.
    in_struct_lit_ty: bool,
    /// [mod-namespace] The enclosing namespace of the `type` alias currently
    /// being validated, derived from its own flattened name (`Arg.Type` ->
    /// `Some("Arg")`; an un-namespaced alias -> `None`). Lets the
    /// leading-dot shorthand (`.Int`) resolve inside the alias's own
    /// union-arm list against its *own* namespace — the one case
    /// `resolve_dot_ref`'s `expected`-type mechanism cannot reach, since
    /// there is no outer expression context here, only the declaration
    /// naming itself (user decision 2026-10-19).
    own_alias_namespace: Option<String>,
    /// [col-key-eligible] [cmp-carry] Set while a `let` annotation with an
    /// initializer is validated: the annotation is a **pattern** whose
    /// unwritten slots the value fills, so a keyed container in it is held to
    /// the intrinsic key bar only — whether the identity exists is the
    /// initializer's business (its constructor resolves it, or says why not).
    let_pattern: bool,
    /// [cmp-carry] The fn names more than one non-std module of the program
    /// declares (unattached): an identity of one prints `name@module`, the
    /// spelling that says which.
    fn_name_clash: HashSet<String>,
    /// [comptime-instantiate] [node-origin] The stamp of the fn being checked, when
    /// it was produced by a `by` site or expanded in place: its expansions say
    /// where a diagnostic at a copied node lands (`render_origin`) — the
    /// field or arm the copy was for, prefixed with what was being stamped.
    own_stamp: Option<&'p ast::Stamp>,
    /// [comptime-copy-warn] Warnings raised inside the current fn's copies,
    /// redirected and held until the fn is done, so each is reported once
    /// (`flush_copy_warnings`).
    copy_warnings: Vec<(Span, Option<&'static str>, String)>,
    /// [comptime-copy-warn] Per written declaration in an expanded-in-place
    /// fn's copies: how many copies declared it, and how many left it unused
    /// (with the message). Reported only when every copy left it unused.
    copy_decls: HashMap<(u32, u32), usize>,
    copy_unused: HashMap<(u32, u32), (usize, Option<&'static str>, String)>,
    /// [fn-overload-return] Where the value of the next call checked is
    /// going, for choosing among overloads that differ only in their return
    /// type, when that position has no expected type of its own to pass: the
    /// operand of `!`, the subject of `?:`, the tail of a value `if`/`when`
    /// branch. Taken (and cleared) by the first call checked, so it never
    /// reaches a nested one, and never used for coercion.
    select_hint: Option<Ty>,
    /// [fn-overload-return] The expected type of a value `if`/`when`, handed
    /// to the branch block about to be checked for its tail (R-3).
    tail_hint: Option<Ty>,
    /// [fn-overload-return] The expected type of the value `if`/`when` being
    /// checked, which each of its branch blocks receives as `tail_hint`.
    value_expected: Option<Ty>,
    /// The current fn's effective deduction contract (its signature's
    /// [deduce-default]): decides whether a parameter root is *owned* (moved
    /// by the contract) for move-mode bindings [fate-move-mode].
    own_contract: Option<Vec<crate::deduce::ParamDeduction>>,
    /// [type-literal] Every plain literal expression checked, by span: what a
    /// coercion consults when an argument typed without an expected type (so
    /// as its base) lands in a slot listing the literal.
    lit_spans: HashMap<Key, TypeLit>,
    /// [linear-group] The parameter name of the designated `close` currently
    /// being checked, if this fn is one: its obligation is discharged by
    /// being closed.
    /// [linear-group] The linear types the *current fn* may `discard`: it
    /// is a **discharger** of each — declared in the same file as the type,
    /// consuming a parameter of it (user decision 2026-09-12; replaces the
    /// designated-`close` exemption). Inside the fn the obligation still
    /// owes until terminated on every path — `discard` or a forward into
    /// another consuming fn.
    own_discharges: std::collections::HashSet<String>,
    /// Whether the current fn has a *written* deduction list: written
    /// contracts never gain claims — a kept parameter stays kept and
    /// derived moves stay errors [fate-derived-readonly].
    /// [deduce-syntax] The parameters the current fn's clause *mentions*
    /// (plain entries): their contract is written, fixed; every other
    /// parameter's is inferred.
    own_written: Vec<String>,
    /// Enclosing lambdas of the code being checked [fate-lambda]: the
    /// scope-frame boundary of each (locals below it are *captures*)
    /// plus the captures recorded so far. Innermost last.
    lambda_ctx: Vec<LambdaCtx>,
    /// Fate links carried by lambda *values* [fate-lambda]: a lambda is
    /// derived from the transitively-mutable variables it reads (keyed
    /// by the lambda expression's span, this file only).
    lambda_links: HashMap<Span, Vec<FateLink>>,
    /// [var-unused] Whether this file is part of the embedded std: an
    /// unused-variable warning there is the compiler's own business, not
    /// the user's, so std is exempt.
    is_std: bool,
    /// Type parameters of the current fn that opted into linearity with
    /// `<T canbe linear>` [linear-generics]: `T`-typed values are treated
    /// as linear in the body, and callers may instantiate them with
    /// linear types.
    own_linear_generics: HashSet<String>,
    /// The current fn's derived-return parameter
    /// (`-> proj(p) T` [proj-readonly-return]): every returned
    /// value must be derived from `p`, and the return is a *borrow*, not
    /// a move.
    own_derived_return: Option<String>,
    /// [deduce-conditional] The enclosing fn's qualifier-conditional response
    /// clause, if any — checked proof-only at each `return true`.
    own_response: Option<Vec<ast::ConditionalResponse>>,
    /// [qual-preserve] The enclosing fn's own `preserve` promises, per
    /// parameter — checked against every `Mut` use of the parameter in the
    /// body (the call must itself preserve the claim).
    own_preserve: HashMap<String, Vec<String>>,
    /// [ref-handle] Locals of the fn being checked bound from a *reader*
    /// call (a result with no `ref` arm): a borrow that forgot its position,
    /// which a mint may not return as a handle.
    reader_bound: HashMap<String, String>,
    /// [proj-anywhere] Every source of the fn's wholesale `proj` return
    /// (`proj(a, b) T`): a returned value may derive from any of them.
    own_derived_sources: Vec<String>,
    /// [proj-anywhere] When the return type is a union, the *qualifier
    /// names* of the arms that carry `proj` (`Emitted` for
    /// `Emitted (proj(p) T) | Finished`). A returned value whose
    /// constructor builds one of these arms must be derived from the
    /// source; a value into any other arm is an ordinary move. Empty when
    /// the whole return type is the borrow (the pre-2b shape).
    own_proj_arms: Vec<String>,
    /// [proj-infer] Memo for `lends::lends_of`, keyed by declaration address.
    lends_memo: HashMap<usize, Vec<usize>>,
    /// [proj-infer] The current fn's lent parameter *names*: what a returned
    /// held view may be rooted in.
    own_lends: Vec<String>,
    /// [proj-infer] The current fn wrote `[p: proj]` entries.
    own_lends_declared: bool,
    /// [proj-anywhere] The span of a constructor call whose result is being
    /// returned into a `proj` arm: its argument is *lent* into the arm, not
    /// moved (the caller receives a borrow of it), so the call contract's
    /// consumption is suppressed for exactly that call.
    lending_ctor: Option<Span>,
    /// The implicit parameters of the fn being checked [implicit-forward]:
    /// what an inner call can have forwarded to it. Matching is by name and
    /// type, not by how they were declared, so a group spread here can fill
    /// an individually-declared `?add` there and the other way round.
    own_implicits: Vec<ImplicitParam>,
    /// [implicit-resolve-body] Argument types of a call that fell through an
    /// implicit to the fns of its name, consumed by `resolve_named_call`.
    pending_arg_tys: Option<Vec<Ty>>,
    /// [op-equality] [op-order] The comparison operator whose call is being
    /// resolved: what its diagnostics are worded for, so an error at `a == b`
    /// names the operator (`no `eq` for `==` on `Foo``), and what keeps the
    /// call from recording a fn reference at the operator's span.
    operator_site: Option<OperatorSite>,
    /// [iter-for] The `for` header whose `next`/`iter` call is being resolved.
    for_site: Option<ForSite>,
    /// [iter-for] The pending call's arguments are typed and have no
    /// expressions of their own (`pending_arg_tys` with the `for`'s subject
    /// as a stand-in): selection, implicits and records run, and what a call
    /// does to its argument places does not — a `for` has its own rules
    /// for what driving does to its subject [iter-drive-in-place] [proj-type].
    pending_typed_only: bool,
    /// [fn-overload-at] The `@module` selectors (by the span of the written
    /// path) at calls whose bare name something other than the declared fns
    /// would take: a local or parameter of the name, a handler's own `send
    /// fn`, an effect member. The "`@` not needed" warning is not given
    /// there — without the selector the call would go elsewhere.
    at_needed: HashSet<Span>,
    /// [implicit-recursive] The nested fill of the fn `resolve_implicit_fn_at`
    /// just chose, taken by its caller.
    last_nested: Vec<ImplicitArg>,
    /// [implicit-recursive] How many resolutions are open: the depth cap (8).
    resolve_depth: usize,
    /// [implicit-recursive] The (fn, wanted type) pairs being resolved, for
    /// the cycle refusal.
    resolve_chain: Vec<(usize, String)>,
    /// [implicit-recursive] Why a position inside a nested fill failed, for
    /// the `try_nested` that opened it.
    nested_miss: Option<Unfilled>,
    /// [comptime-generic] `resolve_implicit_fn_at` is answering for a call
    /// (an interpolation part), which fills the found fn's own
    /// implicits, rather than for a fn value, which cannot yet.
    resolve_as_call: bool,
    /// [implicit-infer] Selection asked by inference: an ambiguity among
    /// positions with unknown parts is an ambiguity (it teaches nothing),
    /// not [type-unknown-lenient]'s first pick.
    strict_select: bool,
    /// [implicit-infer] How deep inference's selections nest (a candidate's
    /// [implicit-fit] probe infers its own implicits): capped.
    infer_depth: u8,
    /// [implicit-infer] While inference selects: the implicit's pattern and
    /// the callee's variables it still mentions, read off each candidate.
    infer_open: Option<(Ty, HashSet<String>)>,
    /// [fn-rename] Renames in force, outermost first: a module-level one for
    /// the whole file, then one per `rename fn` statement, dropped when its
    /// block ends. Each takes an overload *out* of its own name and gives it
    /// the new one, so both directions read this table.
    renames: Vec<RenameBinding<'p>>,
    /// [proj-infer-fn-type] Spans already warned about a spare lend. A fn
    /// type's contract is lowered once per *mention* — a signature, an
    /// instantiation, a substitution — so the warning needs a memory or it
    /// arrives several times for one clause.
    warned_spare_lends: HashSet<(usize, Span)>,
    /// Enclosing `try` delimiters [throw-try], innermost last: each collects the
    /// message types of the throws performed in its body.
    try_stack: Vec<TryCtx>,
    /// [fn-effects] Effect instances used inside each enclosing lambda
    /// body, innermost last: an un-annotated lambda's effect set is
    /// *inferred* from what its body performs.
    effect_uses: Vec<Vec<Ty>>,
    /// [lsp-check-cache] Whether this walk records what a cached check needs
    /// to stand in for it: `written_log` and `parking_log`.
    record: bool,
    /// [lsp-check-cache] Every `written_types` row this walk wrote, in
    /// order, by address, with the row and whether it was written only if
    /// absent (the declared shape at a use, `lower_type_subst`): what a cached
    /// check writes for this file at this step.
    written_log: Vec<(usize, Ty, bool)>,
    /// [lsp-check-cache] Every handler this walk added to
    /// `parking_handlers`, already there or not.
    parking_log: Vec<String>,
}

/// One enclosing `try` delimiter while its body is checked [throw-try].
struct TryCtx {
    /// `locals.len()` at entry: a throw leaves every frame above this
    /// one, which is the floor for the linear-obligation check
    /// [linear-obligation].
    entry_depth: usize,
    /// The sites that throw into this delimiter, in first-seen order:
    /// their span and message type. The outcome's `Thrown M` is the union
    /// of those types (user decision 2026-09-04), which is only known once
    /// the body is checked — so each site's wrap is filled in afterwards.
    sites: Vec<(Span, Ty)>,
}

/// One enclosing lambda during body checking [fate-lambda].
struct LambdaCtx {
    /// `locals.len()` at lambda entry: frames below this index belong to
    /// the enclosing scope, so variables in them are captures.
    boundary: usize,
    /// Captured variables recorded so far (deduplicated by id).
    captures: Vec<CaptureInfo>,
}

struct CaptureInfo {
    name: String,
    var_id: u32,
    /// The captured value is transitively mutable [fate-move-mode].
    mutable: bool,
    /// The body mutates the capture: the closure takes ownership at
    /// creation [fate-lambda].
    mutated: bool,
    /// The body *consumes* the capture: legal, but the lambda becomes
    /// `once` — callable at most once [fn-once].
    moved: bool,
}

/// A flow narrowing to apply in a branch [flow-place]: the place, the type
/// it holds there, and the physical (declared) type its storage keeps.
#[derive(Clone)]
struct Narrow {
    place: Place,
    narrowed: Ty,
    declared: Ty,
}

/// Narrowing facts derived from a condition.
#[derive(Default, Clone)]
struct CondInfo {
    /// Place narrowings that hold when the condition is true.
    then_narrows: Vec<Narrow>,
    /// Narrowings that hold when the condition is false.
    else_narrows: Vec<Narrow>,
    /// `is T name` bindings introduced in the true branch.
    bindings: Vec<Binding>,
}

impl<'p, 'r> Checker<'p, 'r> {
    /// [decl-interface-pass] Step one of the interface pass: every fn's signature
    /// facts (`sig_facts`: implicit parameters, established claims, effect
    /// list) and every effect member's implicits, with their diagnostics.
    /// Run over the whole program before any other interface check, because
    /// those read them out of tables: a call site, a keyed type's identity,
    /// or a fn value reading a callee not reached yet saw a fn with no
    /// implicits, no claims or no effects — a [backend-never-wrong]
    /// violation decided by nothing but declaration order, within a file or
    /// across them (found 2026-09-22 and 2026-10-20).
    ///
    /// Mirrors the generic scopes and the stamp scopes the rest of the walk
    /// enters, since `?cmp: (T, T) -> Int` must lower to a variable rather
    /// than a nominal `T`, and mirrors which declarations have a `DeclId` key
    /// (only a top-level fn does; the rest key by their name span).
    fn check_signature_facts(&mut self, module: &'p Module) {
        // [deduce-reapply] The same-file rule for `+Q` reads this.
        self.own_qualifiers = module
            .items
            .iter()
            .filter_map(|item| match item {
                Item::Qualifier(q) => Some(q.name.name.clone()),
                _ => None,
            })
            .collect();
        for (item_idx, item) in module.items.iter().enumerate() {
            match item {
                Item::Fn(f) => {
                    self.own_fn = Some(self.resolution.decls.fn_at(self.file_idx, item_idx));
                    self.own_stamp = f.stamped.as_ref();
                    let saved_scope = self.scope;
                    if let Some(&i) = self.resolution.fn_stamp_scope.get(&(f as *const FnDecl as usize)) {
                        self.scope = &self.resolution.stamp_scopes[i];
                    }
                    let saved = self.enter_generics(&f.generics);
                    self.record_sig_facts(f);
                    self.generics = saved;
                    self.flush_copy_warnings();
                    self.scope = saved_scope;
                    self.own_stamp = None;
                    self.own_fn = None;
                }
                Item::Qualifier(q) => {
                    let saved = self.enter_generics(&q.generics);
                    for f in &q.fns {
                        let inner = self.enter_generics(&f.generics);
                        self.record_sig_facts(f);
                        self.generics = inner;
                    }
                    self.generics = saved;
                }
                Item::Effect(e) => {
                    let saved = self.enter_generics(&e.generics);
                    for f in &e.fns {
                        let inner = self.enter_generics(&f.generics);
                        self.effect_member_implicits(f);
                        self.generics = inner;
                    }
                    self.generics = saved;
                }
                Item::Handler(h) => {
                    let saved = self.enter_generics(&h.generics);
                    for f in h.fns.iter().chain(h.init.iter()) {
                        let inner = self.enter_generics(&f.generics);
                        self.record_sig_facts(f);
                        self.generics = inner;
                    }
                    self.generics = saved;
                }
                _ => {}
            }
        }
    }

    fn record_sig_facts(&mut self, f: &'p FnDecl) {
        let facts = self.sig_facts(f);
        self.iface.facts.insert(f as *const FnDecl as usize, facts);
    }

    /// [implicit-param] An effect member is an ordinary signature, so it may
    /// declare implicit parameters. They belong to the member's signature —
    /// the interface method takes them, every handler's implementation takes
    /// them, and the call site fills them — so the expansion is recorded
    /// here, keyed by the member's name (a member is not keyed by its `DeclId`).
    fn effect_member_implicits(&mut self, f: &'p FnDecl) {
        let implicits = self.collect_implicits(f);
        if !implicits.is_empty() {
            self.out
                .implicit_members
                .insert(self.key(f.name.span), implicits);
        }
    }

    /// [lsp-check-cache] What this walk recorded for a cached check.
    fn take_logs(&mut self) -> (Vec<(usize, Ty, bool)>, Vec<String>) {
        (std::mem::take(&mut self.written_log), std::mem::take(&mut self.parking_log))
    }

    /// [decl-interface-pass] Hands this file's interface records on to the next
    /// pass over it, with the once-per-file diagnostic memories.
    fn take_iface(&mut self) -> FileIface<'p> {
        let mut iface = std::mem::take(&mut self.iface);
        iface.renames = std::mem::take(&mut self.renames);
        iface.reported_ineligible_keys = std::mem::take(&mut self.reported_ineligible_keys);
        iface.reported_identities = std::mem::take(&mut self.reported_identities);
        iface.warned_spare_lends = std::mem::take(&mut self.warned_spare_lends);
        iface.lends_memo = std::mem::take(&mut self.lends_memo);
        iface
    }

    /// [decl-interface-pass] The other half of `take_iface`.
    fn put_iface(&mut self, mut iface: FileIface<'p>) {
        self.renames = std::mem::take(&mut iface.renames);
        self.reported_ineligible_keys = std::mem::take(&mut iface.reported_ineligible_keys);
        self.reported_identities = std::mem::take(&mut iface.reported_identities);
        self.warned_spare_lends = std::mem::take(&mut iface.warned_spare_lends);
        self.lends_memo = std::mem::take(&mut iface.lends_memo);
        self.iface = iface;
    }
}

impl<'p, 'r> Checker<'p, 'r> {
    /// One file's checker. Every field that is not a borrow from outside
    /// starts empty, so the walks over the program — the interface pass's
    /// two and the body pass [decl-interface-pass] — differ only in their `pass`
    /// and in the records they are handed (`put_iface`).
    #[allow(clippy::too_many_arguments)]
    fn new(
        file_idx: usize,
        is_std: bool,
        files: &'p [crate::source::SourceFile],
        scope: &'r ModuleScope<'p>,
        resolution: &'r Resolution<'p>,
        symbols: &'r Symbols<'p>,
        inferred: &'r HashMap<DeclId, Vec<crate::deduce::ParamDeduction>>,
        refinements: &'r crate::refine::Refinements,
        out: &'r mut Checked,
            param_mutations: &'r mut HashMap<DeclId, HashSet<String>>,
            parking_handlers: &'r mut HashSet<String>,
    ) -> Checker<'p, 'r> {
        Checker {
            pass: Pass::Interface,
            iface: FileIface::default(),
            reported_ineligible_keys: HashSet::new(),
            reported_identities: HashSet::new(),
            scope,
            resolution,
            symbols,
            inferred,
            refinements,
            file_idx,
            files,
            out,
            locals: Vec::new(),
            generics: HashSet::new(),
            ret_ty: Ty::none(),
            own_qualifiers: HashSet::new(),
            effect_env: Vec::new(),
            call_fixed_params: HashSet::new(),
            handler_deps: Vec::new(),
            module_avails: Vec::new(),
            runtime_files: Vec::new(),
            handler_ofs: Vec::new(),
            own_handler: None,
            handler_spawns: false,
            facade_handler: None,
            confined_state: Vec::new(),
            servant_reply_params: None,
            own_task: None,
            can_use: false,
            placeholder_ty: None,
            placeholder_read: false,
            can_spawn: false,
            loop_stack: Vec::new(),
            driven_origins: Vec::new(),
            own_mut_paths: Vec::new(),
            next_var_id: 0,
            key_hint: std::cell::Cell::new(0),
            fate_log: HashMap::new(),
            fate_meta: HashMap::new(),
            parking_handlers,
            param_mutations,
            own_fn: None,
            cur_fn_body: None,
            in_comptime_decl: false,
            in_struct_lit_ty: false,
            own_alias_namespace: None,
            let_pattern: false,
            fn_name_clash: fn_name_clash(files, resolution),
            own_stamp: None,
            copy_warnings: Vec::new(),
            copy_decls: HashMap::new(),
            copy_unused: HashMap::new(),
            select_hint: None,
            tail_hint: None,
            value_expected: None,
            own_contract: None,
            lit_spans: HashMap::new(),
            own_discharges: std::collections::HashSet::new(),
            own_written: Vec::new(),
            lambda_ctx: Vec::new(),
            lambda_links: HashMap::new(),
            is_std,
            own_linear_generics: HashSet::new(),
            own_derived_return: None,
            own_response: None,
            own_preserve: HashMap::new(),
            reader_bound: HashMap::new(),
            own_derived_sources: Vec::new(),
            lends_memo: HashMap::new(),
            own_lends: Vec::new(),
            own_lends_declared: false,
            own_proj_arms: Vec::new(),
            lending_ctor: None,
            own_implicits: Vec::new(),
            pending_arg_tys: None,
            operator_site: None,
            for_site: None,
            pending_typed_only: false,
            at_needed: HashSet::new(),
            last_nested: Vec::new(),
            resolve_depth: 0,
            resolve_chain: Vec::new(),
            nested_miss: None,
            resolve_as_call: false,
            strict_select: false,
            infer_depth: 0,
            infer_open: None,
            renames: Vec::new(),
            warned_spare_lends: HashSet::new(),
            try_stack: Vec::new(),
            effect_uses: Vec::new(),
            record: false,
            written_log: Vec::new(),
            parking_log: Vec::new(),
        }
    }
}

impl<'p, 'r> Checker<'p, 'r> {
    /// [node-id] The key of the node `span` holds, in this file.
    fn key(&self, span: Span) -> Key {
        if let Some(site) = &self.for_site {
            if site.at == span && site.at.node == span.node {
                return site.key;
            }
        }
        self.out.decls.key(self.file_idx, span, &self.key_hint)
    }

    /// An error, reported only when [report] (a check shared by the files of
    /// a module, reported in the one it is written in).
    fn error_if(&mut self, report: bool, span: Span, msg: impl IntoMessage) {
        if report {
            self.error(span, msg);
        }
    }

    /// An error at `span`. [diag-id] However the text is reworded on the way
    /// (an operator's or a `for`'s wording, a copy's origin), the id is the
    /// message's.
    fn error(&mut self, span: Span, msg: impl IntoMessage) {
        let (id, msg) = msg.into_message();
        let msg: String = match &self.operator_site {
            Some(site) => site.reword(msg),
            None => msg,
        };
        let (span, msg) = match &self.for_site {
            Some(site) => (if site.at == span { site.loc } else { span }, site.reword(msg)),
            None => (span, msg),
        };
        let (span, msg, decl) = self.render_origin(span, msg);
        self.out
            .errors
            .push(FileDiagnostic::error(self.file_idx, span, (id, msg)).in_decl(decl));
    }

    /// [node-origin] [comptime-instantiate] A diagnostic at a node a stamp copied
    /// lands where its origin says (`crate::origin::render`): on the field or
    /// arm the failing copy was for (or on the `by` site), prefixed with the
    /// compfn, its scope and the type — so a missing `cmp` for a `Double`
    /// field reads "in `cmp` from `auto` for `Point.y: Double`: …" at the
    /// field declaration — and is attributed to the stamped fn. A written
    /// span stays.
    fn render_origin(&self, span: Span, msg: String) -> (Span, String, Option<DeclId>) {
        match self.own_stamp {
            Some(stamp) if span.is_expanded() => {
                let (at, msg) = crate::origin::render(stamp, span, msg);
                (at, msg, self.own_fn)
            }
            _ => (span, msg, None),
        }
    }

    /// Reports without rejecting: the program still compiles, but
    /// something the author wrote is not doing what it looks like
    /// [qual-refn].
    fn warn(&mut self, span: Span, msg: impl IntoMessage) {
        let (id, msg) = msg.into_message();
        // [comptime-copy-warn] A warning inside a comptime copy lands where
        // an error there would (it kept the copy's span, past the end of the
        // file, before 2026-10-20), and is held so a warning every copy
        // raises alike is reported once.
        if self.own_stamp.is_some() && span.is_expanded() {
            let (at, msg, _) = self.render_origin(span, msg);
            self.copy_warnings.push((at, id, msg));
            return;
        }
        self.out
            .errors
            .push(FileDiagnostic::warning(self.file_idx, span, (id, msg)));
    }

    /// [comptime-copy-warn] Where a span in a copy of an **expanded-in-place**
    /// fn was written, when it was: the written construct every copy of it
    /// stands for. `None` outside a copy, or in a stamp (whose template is
    /// another declaration's).
    fn in_place_written(&self, span: Span) -> Option<Span> {
        crate::origin::written(self.own_stamp?, span).map(|(at, _)| at)
    }

    /// [comptime-copy-warn] Reports the warnings the fn's copies raised, once
    /// each: an unused local only if no copy used it (as an unused pattern
    /// binder already is), anything else once per written place and text.
    fn flush_copy_warnings(&mut self) {
        let mut unused: Vec<((u32, u32), (usize, Option<&'static str>, String))> =
            self.copy_unused.drain().collect();
        unused.sort_by_key(|(k, _)| *k);
        for ((start, end), (count, id, msg)) in unused {
            let declared = self.copy_decls.get(&(start, end)).copied().unwrap_or(0);
            if count >= declared {
                self.out
                    .errors
                    .push(FileDiagnostic::warning(self.file_idx, Span::new(start, end), (id, msg)));
            }
        }
        self.copy_decls.clear();
        let mut seen: HashSet<(u32, u32, String)> = HashSet::new();
        for (at, id, msg) in std::mem::take(&mut self.copy_warnings) {
            if seen.insert((at.start, at.end, msg.clone())) {
                self.out.errors.push(FileDiagnostic::warning(self.file_idx, at, (id, msg)));
            }
        }
    }

    /// An unresolved-name error carrying import suggestions: modules
    /// elsewhere in the program that declare `name`
    /// [diag-import-suggest].
    ///
    /// [mod-export] And, where the name exists but is private, the reason —
    /// appended to the message rather than offered as a help line, because it
    /// is not something the *calling* file can fix by adding an import. This is
    /// the one funnel every unresolved-name diagnostic goes through, which is
    /// why the note is attached here and not at each site.
    fn error_unresolved(&mut self, span: Span, msg: impl IntoMessage, name: &str) {
        let imports = self.resolution.import_candidates(name);
        // [diag-id] The notes below add to the text; the id is the message's.
        let (id, mut msg) = msg.into_message();
        // The note is about a name that is *nowhere* usable here. A name that is
        // in scope under another kind — a qualifier written where a type belongs
        // — has a different problem, and telling it about exports would send the
        // reader to the wrong file.
        if imports.is_empty() && !self.scope.declares_name(name) {
            if let Some(note) = self.resolution.export_note(name) {
                msg.push_str(&note);
            }
        }
        // [actor-private-send] A bare call to a private send member of the
        // enclosing handler: it is a message, not a function, so the fix is
        // the selector.
        if let Some(h) = self.own_handler {
            if h.fns.iter().any(|f| f.is_send && f.name.name == name) {
                msg.push_str(&format!(
                    " — `{name}` is a send member of `{}`, so it is sent, not called: \
                     `{name}@self(…)`",
                    h.name.name
                ));
            }
        }
        // [node-origin] At a copied node, where its origin says.
        let (span, msg, decl) = self.render_origin(span, msg);
        self.out
            .errors
            .push(FileDiagnostic::error(self.file_idx, span, (id, msg)).with_imports(imports).in_decl(decl));
    }

    // ================= module / function traversal =================

    /// One fn item of a module: the per-declaration context (its key, its
    /// effective contract, whether it discharges a linear type, what its sends
    /// are attributed to), then the body. Called by `check_module` for every
    /// fn.
    fn check_fn_item(&mut self, item_idx: usize, f: &'p FnDecl) {
        // The declaration's own name is a fn reference
        // [fn-ref-table].
        let key = self.resolution.decls.fn_at(self.file_idx, item_idx);
        let (iface, body) = (self.pass.interface(), self.pass == self.body_pass_of(f));
        if iface {
            self.out.fn_refs.insert(self.key(f.name.span), key);
        }
        // [fate-move-mode] The fn's own effective contract
        // decides whether a parameter root is owned.
        self.own_fn = Some(key);
        self.own_stamp = f.stamped.as_ref();
        // [comptime-hygiene] A body stamped from another module's template is
        // checked where the site sees what the template's author saw too:
        // a name the site cannot resolve falls back to the template's file,
        // private declarations included.
        let saved_scope = self.scope;
        if let Some(&i) = self.resolution.fn_stamp_scope.get(&(f as *const FnDecl as usize)) {
            self.scope = &self.resolution.stamp_scopes[i];
        }
        // [comptime-root-visible] A type an expanded-in-place comptime fn
        // names as a root (`Pt` in `[for field in Pt.fields]`) is a type
        // name written here, and is visible here or an error — the
        // expansion looked it up program-wide, before resolution. Recorded
        // for go-to-definition like any type reference.
        if let (true, Some(stamp)) = (body, &f.stamped) {
            for root in &stamp.roots {
                let r = ast::TypeRef {
                    name: root.clone(),
                    args: Vec::new(),
                    value_args: Vec::new(),
                    from: Vec::new(),
                    at: None,
                    binder: false,
                    established: false,
                    alias: None,
                    span: root.span,
                };
                self.require_name(&r, false);
                self.record_def_ref(root.span, &root.name);
            }
        }
        self.own_written = f
            .deductions
            .as_ref()
            .map(|l| {
                l.iter()
                    .filter_map(|d| d.param_name().map(|n| n.name.clone()))
                    .collect()
            })
            .unwrap_or_default();
        self.own_contract = self.effective_contract(Some(key), f);
        // [linear-group] Is this fn a **discharger**? For each
        // consumed parameter whose type is a linear struct
        // declared in this same file, `discard` becomes legal
        // in this body (user decision 2026-09-12).
        if body {
            self.own_discharges = f
                .params
                .iter()
                .filter_map(|p| {
                    let written = match &p.ty {
                        ast::Type::Named { base, .. } => base,
                        _ => return None,
                    };
                    let key = self.written_key_of(written);
                    let base = &written.name.name;
                    if !self.linear_capable(&key) {
                        return None;
                    }
                    if self.scope.struct_files.get(base.as_str()).copied()
                        != Some(self.file_idx)
                    {
                        return None;
                    }
                    let consumed = self
                        .own_contract
                        .as_ref()
                        .is_some_and(|c| {
                            c.iter().any(|d| d.param == p.name.name && !d.kept)
                        });
                    // [type-identity] By key: `discard` compares the value's type.
                    consumed.then_some(key)
                })
                .collect();
        }
        // [actor-free-send-fn] The send kind's refusal list, at the
        // declaration where the author is deciding.
        if iface {
            self.check_free_send_fn(f);
        }
        // [task-mint] What this body's sends are attributed to in
        // the deadlock graph.
        self.own_task = (body && f.is_send).then(|| f.name.name.clone());
        self.check_fn(f, &[], &[]);
        self.flush_copy_warnings();
        self.scope = saved_scope;
        self.own_task = None;
        self.own_fn = None;
        self.own_stamp = None;
        self.own_discharges.clear();
        self.own_written.clear();
        self.own_contract = None;
    }

    /// A handler declaration, in the half `self.pass` names [decl-interface-pass]:
    /// its header (faces, dependencies, parameters, state field types, the
    /// mailbox's presence, conformance, each member's signature) in the
    /// interface pass, which records a `HandlerSig`; its expressions (the
    /// constructor parameters' defaults, the mailbox slot, the state
    /// initializers) and its members' bodies in the body pass.
    fn check_handler(&mut self, h: &'p ast::HandlerDecl) {
        // [node-id] Variable ids are per declaration (`check_fn_body`).
        self.next_var_id = 0;
        let saved = self.enter_generics(&h.generics);
        let (iface, body) = (self.pass.interface(), self.pass.body());
        let addr = h as *const ast::HandlerDecl as usize;
        let sig = if iface {
            let sig = self.handler_interface(h);
            self.iface.handlers.insert(addr, sig.clone());
            sig
        } else {
            match self.iface.handlers.get(&addr) {
                Some(sig) => sig.clone(),
                None => panic!(
                    "[decl-interface-pass] handler `{}` reached the body pass with no interface",
                    h.name.name
                ),
            }
        };
        let HandlerSig { of_tys, deps: handler_deps, spawns, mixed } = sig;
        // [fn-param-default] A constructor parameter's default is
        // checked exactly as a fn parameter's is: once, here,
        // against the parameter's type, with no effects
        // available and only the *earlier* parameters in scope.
        // It is lowered fresh at each construction that omits it
        // (`Lower::construct_handler`). An expression, checked in a
        // frame of locals: the body pass's.
        if body && h.params.iter().any(|p| p.default.is_some()) {
            let saved_env = std::mem::take(&mut self.effect_env);
            for (i, p) in h.params.iter().enumerate() {
                let Some(default) = &p.default else { continue };
                let frame = self.read_only_frame(&h.params[..i]);
                self.locals.push(frame);
                let expected = self.lower_type(&p.ty).strip_spread();
                self.check_default(default, &expected);
                self.locals.pop();
            }
            self.effect_env = saved_env;
        }
        let saved_deps =
            std::mem::replace(&mut self.handler_deps, handler_deps);
        let saved_spawns = std::mem::replace(&mut self.handler_spawns, spawns);
        let saved_own_handler = std::mem::replace(&mut self.own_handler, Some(h));
        let saved_of = std::mem::replace(&mut self.handler_ofs, of_tys.clone());
        // [actor-mailbox] The actor settings slot, before the
        // state fields: it is the one part of a handler that is
        // computed *before* any state exists. Its presence is the
        // header's, its expression the body pass's.
        self.check_mailbox_slot(h, &of_tys);
        if iface {
            self.check_handler_names(h);
        }
        for field in &h.state {
            if iface {
                if let Some(t) = &field.ty {
                    self.validate_type(t);
                }
                if field.canbe_mut {
                    self.error(field.span, messages::struct_field_canbe_mut_handler_state());
                }
                self.check_proj_field(&h.name.name, field);
                self.check_linear_field(&h.name.name, field);
            }
            // A state field's initializer is checked against its
            // declared type, exactly like a struct field's
            // default [effect-handler]: it runs in `new()` with
            // no locals in scope. (Until 2026-09-04 it was not
            // checked at all, so `held: Mut List<Int> = "no"`
            // was accepted and the emitters never saw the
            // expression's types.)
            //
            // [handler-state-infer] With no annotation (`name = value`)
            // the field's type *is* the initializer's, inferred
            // exactly as a `let x = value` is — and recorded at
            // the field-name span for the IR to read back (the
            // channel `waitfor` uses). An annotation may be wider
            // than the value, so the written type is checked as a
            // supertype, as a `let x: T = value` is. A handler's
            // state is its own, so the inferred type is read by its
            // members' bodies only: the body pass's.
            if let (true, Some(default)) = (body, &field.default) {
                // [handler-state] An initialiser may read the constructor's
                // parameters: the state is built from them, once, at construction.
                let frame = self.read_only_frame(&h.params);
                self.locals.push(frame);
                match &field.ty {
                    Some(t) => {
                        let expected = self.lower_type(t);
                        self.check_default(default, &expected);
                    }
                    None => {
                        let got = self.check_expr(default, None);
                        // Record the inferred field type where the
                        // member-body frame and the IR read it.
                        self.out
                            .expr_ty
                            .insert(self.key(field.name.span), got);
                    }
                }
                self.locals.pop();
            }
        }
        // [handler-init] The `init` block is checked as one more
        // member — a parameterless private send member the
        // runtime sends first — and a written member of the same
        // name would collide with its message variant.
        if let (true, Some(init)) = (iface, &h.init) {
            if mixed {
                self.error(init.name.span, messages::actor_mixed_handler_init_block(&h.name.name));
            }
            if let Some(clash) = h.fns.iter().find(|f| f.name.name == init.name.name) {
                self.error(
                    clash.name.span,
                    messages::handler_init_member_named_init(&h.name.name),
                );
            }
        }
        for f in h.fns.iter().chain(h.init.iter()) {
            if iface {
                self.reject_member_effects(f, "handler member functions");
                // [actor-send-fn] A handler's `send fn` answers
                // nothing, exactly as the effect's declaration does.
                self.check_send_member(f);
                // [actor-mixed-handler] [actor-private-send] A send member
                // no face declares — every one of a mixed handler's,
                // an actor handler's private ones — carries the free
                // send fn's obligations, because no effect
                // declaration mirrors it: a written, all-consumed
                // clause, no `Mut`, no generics, sendable payloads.
                let private = f.is_send
                    && (mixed
                        || crate::handler_member_faces(&self.handler_faces(h), f).is_empty());
                if private {
                    self.check_local_send_member(h, f);
                }
            }
            // [linear-defer] The rung-4 contract point: while
            // a mixed send member's body is checked, its reply
            // parameters and their declared deferrals are what
            // the escape hooks consult.
            let saved_replies = std::mem::replace(
                &mut self.servant_reply_params,
                (f.is_send && mixed).then(|| {
                    f.params
                        .iter()
                        .filter(|p| !p.implicit)
                        .filter(|p| {
                            matches!(
                                &p.ty,
                                ast::Type::Named { base, .. }
                                    if base.name.name == REPLY_TYPE
                            )
                        })
                        .map(|p| {
                            let deferred = f.deductions.iter().flatten().any(|d| {
                                matches!(d.kind, ast::DeductionKind::Deferred)
                                    && d.param_name()
                                        .is_some_and(|n| n.name == p.name.name)
                            });
                            (p.name.name.clone(), deferred)
                        })
                        .collect()
                }),
            );
            // [actor-mixed-handler] A sync member of a mixed handler is
            // the façade: it runs on the caller's thread over the
            // façade value, so it sees the constructor parameters
            // and its own arguments — not the state (confined to
            // the servant), not the handler's dependencies (they
            // live in the servant) — and its `waitfor` needs no
            // capability (SH-5(d)'s down payment: the façade does
            // not run on the spawned thread, so there is no
            // placement to check).
            let facade = mixed && !f.is_send;
            let saved_facade =
                std::mem::replace(&mut self.facade_handler, facade.then_some(h));
            let saved_confined = std::mem::replace(
                &mut self.confined_state,
                if facade {
                    h.state.iter().map(|s| s.name.name.clone()).collect()
                } else {
                    Vec::new()
                },
            );
            let saved_facade_deps = if facade {
                std::mem::take(&mut self.handler_deps)
            } else {
                Vec::new()
            };
            let member_state: &[ast::FieldDecl] =
                if facade { &[] } else { &h.state };
            // [linear-group] [linear-discard] A handler member
            // implementing a **consuming** effect member is a
            // discharge context: discharger status attaches to
            // the *member declaration*, so every handler's body
            // for it may terminate the obligation with `discard`
            // — wherever the handler lives, including a test
            // double in another module (user decision
            // 2026-09-14, entailed by stream ops being members).
            let context = self.member_discharge_context(h, f);
            let saved_discharges =
                std::mem::replace(&mut self.own_discharges, context);
            // [fate-move-mode] A member's clause is written, and
            // it is the member's own contract: a parameter it
            // consumes is owned here, so a binding taken from it
            // (`let {body} = input`) is move-mode exactly as in a
            // fn. Without this every derived binding in a member
            // stayed read-only and a consumed parameter could
            // only be handed on whole (found 2026-09-30 writing
            // `MemS3.put_object`).
            let contract = self.effective_contract(None, f);
            let saved_contract = std::mem::replace(&mut self.own_contract, contract);
            let saved_written = std::mem::replace(
                &mut self.own_written,
                f.deductions
                    .iter()
                    .flatten()
                    .filter_map(|d| d.param_name().map(|n| n.name.clone()))
                    .collect(),
            );
            self.check_fn(f, &h.params, member_state);
            self.own_contract = saved_contract;
            self.own_written = saved_written;
            self.own_discharges = saved_discharges;
            self.servant_reply_params = saved_replies;
            self.facade_handler = saved_facade;
            self.confined_state = saved_confined;
            if facade {
                self.handler_deps = saved_facade_deps;
            }
        }
        self.handler_deps = saved_deps;
        self.handler_spawns = saved_spawns;
        self.own_handler = saved_own_handler;
        self.handler_ofs = saved_of;
        self.generics = saved;
    }

    /// [decl-interface-pass] A handler's header: its faces, constructor
    /// parameters, conformance and dependency list, with the generics in
    /// scope.
    fn handler_interface(&mut self, h: &'p ast::HandlerDecl) -> HandlerSig {
        // [platform-handler] A host implementation of an ordinary
        // effect: bodyless, dependency-free, non-generic.
        self.check_platform_handler(h);
        // [copy-implicit] A handler constructor may take implicit
        // parameters (lifted 2026-09-11): the `use` site is where
        // the handler's type arguments are known, so it resolves
        // them exactly as a call resolves a fn's. The case that
        // forced it: a generic handler that must `copy` a `T` —
        // `?copy: (v: T) -> T` is filled at `use Cyclic([1, 2])`
        // with the copy of `Int`, which the Kotlin backend can
        // lower where a bare `copy` of `T` it cannot [kt-copy].
        for p in &h.params {
            if p.implicit && !matches!(p.ty, ast::Type::Fn { .. }) {
                self.error(p.span, messages::implicit_param_handler_not_fn_type());
            }
        }
        let of_tys: Vec<Ty> =
            h.of.iter().map(|t| self.lower_type(t)).collect();
        // [effect-handler-multi] One face per effect, and the list
        // is a set: naming an effect twice would make `spawn`
        // answer the same addr twice and say nothing new.
        for (i, (written, ty)) in h.of.iter().zip(&of_tys).enumerate() {
            if of_tys[..i].contains(ty) {
                self.error(
                    written.span(),
                    messages::effect_handler_multi_face_twice(&h.name.name, &ty),
                );
            }
        }
        // [effect-handler-multi] Every implemented effect must be
        // of the **same kind**. A handler with both an `actor
        // effect` and a plain one is refused: a handler is bound
        // one way or the other, and the construct whose plain
        // members run on the caller's thread while its send
        // members run on the actor's is the mixed handler
        // [actor-mixed-handler] — classified by shape, all faces plain.
        let kinds: Vec<(&ast::Type, bool)> = h
            .of
            .iter()
            .zip(&of_tys)
            .filter_map(|(written, ty)| {
                let Ty::Named { name, .. } = ty.strip_quals() else {
                    return None;
                };
                let effect = self.symbols.effects.get(name.as_str())?;
                Some((written, effect.is_actor))
            })
            .collect();
        if let Some((_, first)) = kinds.first().copied() {
            for (written, is_actor) in &kinds[1..] {
                if *is_actor != first {
                    let (async_kind, sync_kind) = if *is_actor {
                        ("this one", "the first")
                    } else {
                        ("the first", "this one")
                    };
                    self.error(
                        written.span(),
                        messages::actor_mixed_handler_two_kinds(
                            &h.name.name,
                            &async_kind,
                            &sync_kind,
                        ),
                    );
                }
            }
        }
        // [effect-handler-multi] A **bodyless** handler wears one
        // face: an `intrinsic handler`'s members are the backend's
        // and a `platform handler`'s are the host's, and each is one
        // implementation of one generated interface — so a second
        // face has nobody to implement it.
        if (h.intrinsic || h.platform) && h.of.len() > 1 {
            let kind = if h.intrinsic {
                "intrinsic"
            } else {
                "platform"
            };
            self.error(
                h.of[1].span(),
                messages::effect_handler_multi_bodyless_faces(&kind, &h.name.name),
            );
        }
        // [throw] There is no handler for throwing: the
        // delimiter is `try`, and a handler would have to
        // *resume* the operation, which `Never` forbids.
        for (written, of_ty) in h.of.iter().zip(&of_tys) {
            if matches!(
                of_ty.strip_quals(),
                Ty::Named { name, .. } if name == THROW_EFFECT
            ) {
                self.error(written.span(), messages::throw_no_handlers(&THROW_EFFECT));
            }
        }
        for p in &h.params {
            // [effect-handler-deps] Dependencies are declared in
            // the handler's own effect list now (user decision
            // 2026-09-14), so a constructor parameter is always
            // ordinary data — and an effect-typed one is the
            // plain [effect-not-data] error, with no exception
            // left anywhere in the language.
            self.validate_type(&p.ty);
        }
        // [effect-handler-multi] Conformance, face by face: every
        // member of every implemented effect needs an
        // implementation here, and a member that implements two
        // faces at once has to be *one* signature — which is what
        // "legal when overloading distinguishes them, or when one
        // method implements both" means when it is checked.
        self.check_handler_conformance(h);
        let dep_list = self.handler_dep_list(h);
        self.out.handler_deps.insert(
            self.symbols.key_or(h, &h.name.name).to_string(),
            dep_list.iter().map(|e| (e.ty.clone(), e.span)).collect(),
        );
        let deps: Vec<EffectAvail> = dep_list
            .into_iter()
            .map(|e| EffectAvail { ty: e.ty, declared: true, any: e.any })
            .collect();
        // [actor-spawn-effect] [actor-replyto] The handler its
        // members belong to: `spawn` in its dependency list is a
        // capability they inherit, and `replyto` resolves its
        // target member against this declaration.
        let spawns = h
            .effects
            .iter()
            .flatten()
            .any(|e| matches!(e, EffectRef::Spawn(_)));
        // [actor-mixed-handler] Plain faces + `send fn` members: the
        // mixed handler (SH-1, user decision 2026-09-19). The
        // send members and the state form the servant; the sync
        // members form the façade.
        let mixed = self.handler_is_mixed(h);
        HandlerSig { of_tys, deps, spawns, mixed }
    }


    /// [handler-state-name] [name-bare] A handler's names (user decision
    /// 2026-10-20, R4). Its constructor parameters and state fields are one
    /// namespace, and a member's parameters reuse neither: a member body
    /// reads all three by bare name, so a clash would be a shadow, which the
    /// language refuses ([var-no-shadow] covers the members' locals). And its
    /// state is named by the handler unless written `state Name { … }`, which
    /// it must be when the handler shares its name with a type.
    fn check_handler_names(&mut self, h: &'p ast::HandlerDecl) {
        for field in &h.state {
            if let Some(p) = h.params.iter().find(|p| p.name.name == field.name.name) {
                self.error(
                    field.name.span,
                    messages::name_bare_state_param_clash(
                        &field.name.name,
                        &h.name.name,
                        &p.name.name,
                    ),
                );
            }
        }
        for f in h.fns.iter().chain(h.init.iter()) {
            for p in f.params.iter().filter(|p| !p.implicit) {
                let clash = if h.params.iter().any(|c| c.name.name == p.name.name) {
                    Some("constructor parameter")
                } else if h.state.iter().any(|s| s.name.name == p.name.name) {
                    Some("state field")
                } else {
                    None
                };
                if let Some(what) = clash {
                    self.error(
                        p.name.span,
                        messages::name_bare_param_clash(
                            &p.name.name,
                            &f.name.name,
                            &h.name.name,
                            &what,
                        ),
                    );
                }
            }
        }
        if h.state.is_empty() && h.state_name.is_none() {
            return;
        }
        let is_type = |name: &str| {
            self.scope.structs.contains_key(name)
                || self.scope.effects.contains_key(name)
                || self.scope.type_aliases.contains_key(name)
                || self.scope.opaque_types.contains_key(name)
                || self.scope.qualifiers.contains_key(name)
        };
        match &h.state_name {
            None if is_type(&h.name.name) => self.error(
                h.name.span,
                messages::handler_state_name_default_clash(&h.name.name),
            ),
            Some(n) if is_type(&n.name) || self.scope.handlers.get(n.name.as_str()).is_some_and(|o| !std::ptr::eq(*o, h)) => self.error(
                n.span,
                messages::handler_state_name_declared_clash(&h.name.name, &n.name),
            ),
            _ => {}
        }
    }

    /// [platform-check] Plans the checks of every value this module's platform
    /// surface receives from the host: a platform fn's result, and for an
    /// effect some platform handler implements, each member's result and
    /// each `Reply<T>` parameter's `T`. Refuses what cannot be checked or
    /// trusted, and warns where a check walks a collection (D10 C3).
    fn check_platform_boundary(&mut self, module: &'p Module) {
        // [type-identity] By key: a handler's `of` names the effect as its own
        // file resolves it, and two modules may declare an effect of one name.
        let platform_handled = |key: &str, symbols: &Symbols<'p>, out: &Checked| {
            symbols.handlers.values().any(|h| {
                h.platform
                    && matches!(h.of.first(), Some(ast::Type::Named { base, .. }) if out.written_key(base) == key)
            })
        };
        for item in &module.items {
            match item {
                Item::Fn(f) if f.platform => {
                    if let Some(rt) = &f.return_type {
                        // [platform-check] D10 C5: a result borrowed from a
                        // parameter would need host lifetimes.
                        // [platform-value-type] std's own collections answer a
                        // borrow of the one parameter they name (`get -> (proj(list)
                        // T)?`): std's privilege (user decision 2026-10-04).
                        if ast_mentions_proj(rt) && !self.is_std {
                            self.error(
                                f.name.span,
                                messages::platform_check_borrowed_return(&f.name.name),
                            );
                        }
                        // Under the fn's own generics: the lowered type is
                        // also what the IR reads for the declaration.
                        let saved = self.enter_generics(&f.generics);
                        let ty = self.lower_type(rt);
                        self.generics = saved;
                        let what = format!("`platform fn {}`'s result", f.name.name);
                        self.plan_boundary(&ty, &what, f.name.span, f.name.span);
                        self.plan_factories(&ty, f.name.span);
                    }
                }
                Item::Type(t) if t.alias.is_some() && self.out.platform_closure_all.contains(self.symbols.key_or(t, &t.name.name)) => {
                    if t.generics.is_empty() {
                        let ty = self.lower_type(t.alias.as_ref().unwrap());
                        self.plan_factories(&ty, t.name.span);
                    }
                }
                Item::Effect(e) if platform_handled(self.symbols.key_or(e, &e.name.name), self.symbols, self.out) => {
                    for f in &e.fns {
                        if let Some(rt) = &f.return_type {
                            let saved = self.enter_generics(&e.generics);
                            let inner = self.enter_generics(&f.generics);
                            let ty = self.lower_type(rt);
                            let _ = inner;
                            self.generics = saved;
                            let what = format!("`{}.{}`'s result", e.name.name, f.name.name);
                            self.plan_boundary(&ty, &what, f.name.span, f.name.span);
                            self.plan_factories(&ty, f.name.span);
                        }
                        for p in &f.params {
                            let ty = self.lower_type(&p.ty);
                            if let Ty::Named { name, args } = ty.strip_quals() {
                                if name == "Reply" && args.len() == 1 {
                                    let what = format!(
                                        "what the host sends on `{}.{}`'s `{}`",
                                        e.name.name, f.name.name, p.name.name
                                    );
                                    let inner = args[0].clone();
                                    self.plan_boundary(&inner, &what, p.name.span, p.name.span);
                                    self.plan_factories(&inner, p.name.span);
                                }
                            }
                        }
                    }
                }
                _ => {}
            }
        }
    }

    /// [platform-factory] The factories of `ty` when it is a runtime union of two
    /// or more value arms (ABI D5), recorded under `key`: one per arm, named
    /// by `abi::factory_name`; a base's literals share one checked factory; a
    /// name two arms would share gets none.
    fn plan_factories(&mut self, ty: &Ty, key: Span) {
        use crate::abi::{BoundaryCheck, Factories, Factory};
        let Ty::Union(arms) = ty.strip_quals() else { return };
        let values: Vec<&Ty> = arms.iter().filter(|a| !a.is_none_ty()).collect();
        let nullable = values.len() < arms.len();
        let groups = crate::literal::runtime_groups(&values);
        if groups.len() < 2 {
            return;
        }
        let mut made: Vec<Factory> = Vec::new();
        for (i, group) in groups.iter().enumerate() {
            let lits: Vec<salvo_syntax::ast::TypeLit> = group
                .iter()
                .filter_map(|g| crate::literal::arm_lit(values[*g]).cloned())
                .collect();
            let joiner = group.iter().find(|g| crate::literal::arm_lit(values[**g]).is_none()).map(|g| values[*g]);
            let (name, param, check) = match joiner {
                Some(j) if lits.is_empty() => (crate::abi::factory_name(j), crate::literal::collapse_ty(j), None),
                // A base's literals and its open arm (`| Other Str`): one
                // factory of the base, unchecked since any value is admitted.
                Some(j) => (
                    Some(crate::abi::snake(lits[0].base())),
                    crate::literal::collapse_ty(j).strip_quals().clone(),
                    None,
                ),
                None => (
                    Some(crate::abi::snake(lits[0].base())),
                    Ty::named(lits[0].base()),
                    Some(BoundaryCheck::OneOf(lits.clone())),
                ),
            };
            if let Some(name) = name {
                made.push(Factory { name, arm: i, param, check });
            }
        }
        let mut dropped: Vec<String> = Vec::new();
        for f in &made {
            if made.iter().filter(|g| g.name == f.name).count() > 1 && !dropped.contains(&f.name) {
                dropped.push(f.name.clone());
            }
        }
        made.retain(|f| !dropped.contains(&f.name));
        let union = crate::literal::collapse_ty(ty.strip_quals());
        self.out.factories.insert(
            self.key(key),
            Factories { arity: groups.len(), nullable, union, arms: made, dropped },
        );
    }

    /// [platform-check] Whether every identity a keyed collection type names —
    /// written (`SortedSet<Str>(by_len)`) or filled by name (`Set<Person>`
    /// takes Person's `hash`) — is canonical: an intrinsic, the host's own
    /// operation, or one `by auto` stamped, which lowers to the same
    /// structural comparison [cmp-auto].
    fn keyed_canonically(&mut self, name: &str, args: &[Ty]) -> bool {
        let type_args: Vec<Ty> = args.iter().filter(|a| !matches!(a, Ty::FnName(_))).cloned().collect();
        let written: Vec<FnId> = args
            .iter()
            .filter_map(|a| match a {
                Ty::FnName(id) => Some(id.clone()),
                _ => None,
            })
            .collect();
        let Some(subject) = type_args.first().cloned() else { return true };
        let slots = self.type_fn_slots(name);
        for (at, slot) in slots.iter().enumerate() {
            let key = match written.get(at) {
                Some(id) => self.out.carried_identities.get(&(self.file_idx, id.clone(), subject.clone())).copied(),
                None => {
                    let Some(want) = self.type_slot_ty(name, &type_args, at) else { continue };
                    self.resolve_implicit_fn_at(&slot.name, None, &want).ok().map(|(k, _)| k)
                }
            };
            // [platform-check] Only an **intrinsic** identity is the host's
            // own (`hashCode`/`==`, `Hash`/`PartialEq`), which is what host
            // code builds a set or map with (`canonical_map`); a stamped
            // `hash` folds fields its own way (ROADMAP §0j step 7).
            let Some(decl) = key.and_then(|k| self.fn_decl_by_key(k)) else { continue };
            if !decl.intrinsic {
                return false;
            }
        }
        true
    }

    /// [platform-check] Plans one crossing, records it under `key`, and warns
    /// at `span` when it walks a collection.
    fn plan_boundary(&mut self, ty: &Ty, what: &str, key: Span, span: Span) {
        let mut visiting = Vec::new();
        let Some(plan) = self.boundary_plan(ty, what, span, &mut visiting) else {
            return;
        };
        if plan.walks() {
            self.warn(span, messages::platform_check_element_cost(&what, &ty));
        }
        let at = self.key(key);
        self.out.boundary_checks.insert(at, plan);
    }

    /// [platform-check] The check a value of `ty` needs when the host hands it
    /// to Salvo, over the runtime shape: `None` when the host type already
    /// says everything.
    fn boundary_plan(
        &mut self,
        ty: &Ty,
        what: &str,
        span: Span,
        visiting: &mut Vec<(String, bool)>,
    ) -> Option<crate::abi::BoundaryCheck> {
        use crate::abi::BoundaryCheck as C;
        match ty {
            Ty::Qualified { quals, base } => {
                let mut checked = Vec::new();
                for q in quals {
                    if q.effect || q.name == "Mut" {
                        continue;
                    }
                    let Some(decl) = self.qualifier_for(q.name.as_str(), Some(base)) else {
                        continue;
                    };
                    if decl.subject == QualSubject::Provenance {
                        continue; // [platform-check] trusted (D7)
                    }
                    let qualifies = decl.fns.iter().find(|f| f.name.name == "qualifies");
                    match qualifies {
                        Some(f) if f.effects.as_ref().is_some_and(|e| !e.is_empty())
                            || !decl.value_slots.is_empty()
                            || !decl.fn_slots.is_empty() =>
                        {
                            self.error(
                                span,
                                messages::platform_check_unchecked_claim(&what, &q.name),
                            );
                        }
                        Some(_) => match self.symbols.qualifier_module(decl) {
                            Some(m) => checked.push((q.name.clone(), m.clone())),
                            None => {}
                        },
                        None if self.own_qualifiers.contains(&q.name) => {} // trusted (D7)
                        None => self.error(
                            span,
                            messages::platform_check_foreign_constructive(&what, &q.name),
                        ),
                    }
                }
                let inner = self.boundary_plan(base, what, span, visiting);
                if checked.is_empty() {
                    inner
                } else {
                    Some(C::Qualifies {
                        quals: checked,
                        ty: crate::literal::collapse_ty(base),
                        inner: inner.map(Box::new),
                    })
                }
            }
            Ty::Union(arms) => {
                let values: Vec<&Ty> = arms.iter().filter(|a| !a.is_none_ty()).collect();
                let has_none = values.len() < arms.len();
                let groups = crate::literal::runtime_groups(&values);
                let mut plans = Vec::new();
                let mut runtime_tys = Vec::new();
                for group in &groups {
                    // The runtime arm's type: the joiner's, or the literals' base.
                    let rt = group
                        .iter()
                        .find(|i| crate::literal::arm_lit(values[**i]).is_none())
                        .map(|i| crate::literal::collapse_ty(values[*i]))
                        .unwrap_or_else(|| crate::literal::collapse_ty(values[group[0]]));
                    runtime_tys.push(rt);
                    let lits: Vec<salvo_syntax::ast::TypeLit> = group
                        .iter()
                        .filter_map(|i| crate::literal::arm_lit(values[*i]).cloned())
                        .collect();
                    let joiner = group.iter().find(|i| crate::literal::arm_lit(values[**i]).is_none());
                    let plan = match joiner {
                        // An open arm (`"A" | Other Str`): anything of the base
                        // is admitted, so only its own claims are checked.
                        Some(j) => {
                            let arm = values[*j].clone();
                            self.boundary_plan(&arm, what, span, visiting)
                        }
                        None if !lits.is_empty() => Some(C::OneOf(lits)),
                        None => None,
                    };
                    plans.push(plan);
                }
                let inner = if groups.len() == 1 {
                    plans.pop().flatten()
                } else {
                    let arity = groups.len();
                    let arms: Vec<(usize, Ty, C)> = plans
                        .into_iter()
                        .enumerate()
                        .filter_map(|(i, p)| p.map(|p| (i, runtime_tys[i].clone(), p)))
                        .collect();
                    (!arms.is_empty()).then_some(C::Union { arity, arms })
                };
                match inner {
                    Some(c) if has_none => Some(C::Nullable(Box::new(c))),
                    other => other,
                }
            }
            Ty::Lit(l) => Some(C::OneOf(vec![l.clone()])),
            Ty::Tuple(elems) => {
                let arity = elems.len();
                let mut out = Vec::new();
                for (i, e) in elems.iter().enumerate() {
                    if let Some(c) = self.boundary_plan(e, what, span, visiting) {
                        out.push((i, c));
                    }
                }
                (!out.is_empty()).then_some(C::Tuple { arity, elems: out })
            }
            Ty::Array(e) => self.boundary_plan(e, what, span, visiting).map(|c| C::Elems(Box::new(c))),
            Ty::Named { name, args } if matches!(name.as_str(), "Set" | "SortedSet" | "Map" | "SortedMap")
                && !self.keyed_canonically(name, args) =>
            {
                // [platform-check] D10 C2: the host cannot build a container
                // keyed by a Salvo identity — its own types carry no slot for
                // the functions — so it is refused rather than trusted.
                self.error(span, messages::platform_check_custom_key(&what, &ty));
                None
            }
            Ty::Named { name, args } => match name.as_str() {
                "List" if args.len() == 1 => {
                    let elem = args[0].clone();
                    self.boundary_plan(&elem, what, span, visiting).map(|c| C::Elems(Box::new(c)))
                }
                // [platform-check] A set or map is the host type std's host
                // files define, so only its elements or entries can need a
                // check (ROADMAP §0j step 7: the shape checks went with the
                // JVM's own collections).
                "Set" | "SortedSet" if args.len() == 1 => {
                    let elem = args[0].clone();
                    self.boundary_plan(&elem, what, span, visiting).map(|c| C::Elems(Box::new(c)))
                }
                "Map" | "SortedMap" if args.len() >= 2 => {
                    let (k, v) = (args[0].clone(), args[1].clone());
                    let kc = self.boundary_plan(&k, what, span, visiting);
                    let vc = self.boundary_plan(&v, what, span, visiting);
                    (kc.is_some() || vc.is_some()).then(|| C::Entries(kc.map(Box::new), vc.map(Box::new)))
                }
                _ => {
                    let decl: &'p StructDecl = self.symbols.structs.get(name.as_str()).copied()?;
                    if let Some(seen) = visiting.iter_mut().find(|(n, _)| n == name) {
                        // Only a field that itself needs a check makes this a
                        // problem (reported below); a plain recursive struct
                        // passes through.
                        seen.1 = true;
                        return None;
                    }
                    visiting.push((name.clone(), false));
                    let mut fields = Vec::new();
                    for field in &decl.fields {
                        let Some(fty) = self.declared_field_ty(ty, &field.name.name) else { continue };
                        if let Some(c) = self.boundary_plan(&fty, what, span, visiting) {
                            fields.push((field.name.name.clone(), c));
                        }
                    }
                    let recursed = visiting.pop().is_some_and(|(_, r)| r);
                    if recursed && !fields.is_empty() {
                        self.error(span, messages::platform_check_recursive_type(&what, &name));
                    }
                    (!fields.is_empty()).then(|| C::Struct { name: name.clone(), fields })
                }
            },
            _ => None,
        }
    }

    /// [fn-overload-return] Overloads with identical parameter types are told
    /// apart by their return types alone, so two return types one of which is
    /// a subtype of the other are refused (R-2, user decision 2026-10-20): an
    /// expected `Int?` would fit both `-> Int` and `-> Int?`, and the pair
    /// reads as a mistake.
    fn check_return_overloads(&mut self, module: &'p Module) {
        let mut groups: Vec<((String, Vec<String>), Vec<&'p FnDecl>)> = Vec::new();
        for item in &module.items {
            let Item::Fn(f) = item else { continue };
            let generics: Vec<&str> = f.generics.iter().map(|g| g.name.as_str()).collect();
            let key = (f.name.name.clone(), crate::refine::param_type_signature(&f.params, &generics));
            match groups.iter_mut().find(|(k, _)| *k == key) {
                Some((_, fns)) => fns.push(f),
                None => groups.push((key, vec![f])),
            }
        }
        for (_, fns) in groups.into_iter().filter(|(_, fns)| fns.len() > 1) {
            let rets: Vec<Ty> = fns
                .iter()
                .map(|f| {
                    let saved = self.enter_generics(&f.generics);
                    let t = f.return_type.as_ref().map(|t| self.lower_type(t)).unwrap_or_else(Ty::none);
                    self.generics = saved;
                    t
                })
                .collect();
            for j in 1..fns.len() {
                for i in 0..j {
                    let (a, b) = (&rets[i], &rets[j]);
                    if a == b || a.is_unknown() || b.is_unknown() {
                        continue;
                    }
                    if is_subtype(a, b) || is_subtype(b, a) {
                        self.error(
                            fns[j].name.span,
                            messages::fn_overload_return_overlap(
                                &fns[j].name.name,
                                &a,
                                &b,
                                &(if is_subtype(a, b) { b } else { a }),
                            ),
                        );
                        break;
                    }
                }
            }
        }
    }

    fn check_module(&mut self, module: &'p Module) {
        let (iface, body) = (self.pass.interface(), self.pass.body());
        if iface {
            self.check_return_overloads(module);
        }
        // [mod-use] The module's own bindings, checked as a `use` in a body
        // with nothing else in scope (no locals, no effects), so what they
        // construct can depend on nothing the module's functions could see.
        // A body's work: they are `use` statements, and only this file's
        // bodies read the availabilities they make.
        if body && !module.uses.is_empty() {
            let saved_env = std::mem::take(&mut self.effect_env);
            let saved_can_use = std::mem::replace(&mut self.can_use, true);
            // A module binding may spawn (`use H() on thread()`): the runtime
            // starts its own service actors, which is its privilege.
            let saved_can_spawn = std::mem::replace(&mut self.can_spawn, true);
            self.locals.push(HashMap::new());
            for u in &module.uses {
                self.check_use(&u.handler, &[], false, u.span);
            }
            self.locals.pop();
            self.can_use = saved_can_use;
            self.can_spawn = saved_can_spawn;
            self.module_avails = std::mem::replace(&mut self.effect_env, saved_env);
        }
        // [name-camel] Names the Kotlin backend would spell alike are an
        // error on every backend (user decision 2026-10-01, ABI D6).
        if iface {
            for (span, msg) in crate::case::module_clashes(module) {
                self.error(span, msg);
            }
            self.check_doc_tags(module);
            self.check_scalar_moves(module);
            // [fn-rename] Module-level renames are in force for the whole
            // module, in every file of it — order-independent, like every
            // other module-level declaration. Each is validated, and its new
            // name recorded as a reference, in the file it is written in;
            // every file takes the bindings, handed to its body pass
            // (`put_iface`). Reported from every file, a mistake in one
            // rename showed in the others at its own file's positions, and a
            // file's rows held another file's spans (found 2026-10-20, by
            // the check cache's differential [lsp-check-cache]).
            for decl in self.scope.renames.clone() {
                let own = module.items.iter().any(|i| matches!(i, Item::Rename(r) if std::ptr::eq(r, decl)));
                self.declare_rename(decl, own);
            }
        }
        self.own_qualifiers = module
            .items
            .iter()
            .filter_map(|item| match item {
                Item::Qualifier(q) => Some(q.name.name.clone()),
                _ => None,
            })
            .collect();
        for (item_idx, item) in module.items.iter().enumerate() {
            match item {
                Item::Fn(f) => {
                    // [platform-fn] The host writes one concrete function
                    // that performs no Salvo effect: no generics, no
                    // implicits, no effect list beyond `[]`.
                    if iface && f.platform {
                        // [platform-generic] Type parameters are allowed
                        // (runtime E1): opaque to the host, which may only
                        // store, move and hand one back.
                        let why = if f.params.iter().any(|p| p.implicit) {
                            Some("may not take implicit parameters: the host has nothing to resolve them from")
                        } else if f.effects.as_ref().is_some_and(|e| !e.is_empty()) {
                            Some("may not declare effects: its body is host code, which performs no Salvo effect")
                        } else {
                            None
                        };
                        if let Some(why) = why {
                            self.error(
                                f.name.span,
                                messages::platform_fn_not_allowed(&f.name.name, &why),
                            );
                        }
                    }
                    // [platform-fn] Two platform fns may not overload each
                    // other (user decision 2026-10-01, ABI D5): each has a
                    // namespace of its own at the boundary. One may share its
                    // name with ordinary fns.
                    if iface && f.platform {
                        let first = module.items.iter().position(|i| {
                            matches!(i, Item::Fn(g) if g.platform && g.name.name == f.name.name)
                        });
                        if first.is_some_and(|i| i != item_idx) {
                            self.error(
                                f.name.span,
                                messages::platform_fn_overloaded(&f.name.name),
                            );
                        }
                    }
                    self.check_fn_item(item_idx, f)
                }
                // [implicit-group] A group's members are signatures for
                // *parameters*, validated as declaration sites like an
                // effect's. No body.
                Item::Fns(g) if iface => {
                    let saved = self.enter_generics(&g.generics);
                    for f in &g.fns {
                        self.reject_implicits(f, "a `fns` group member");
                        if f.body.is_some() {
                            self.error(
                                f.name.span,
                                messages::implicit_group_member_body(&g.name.name, &f.name.name),
                            );
                        }
                        let inner = self.enter_generics(&f.generics);
                        for p in &f.params {
                            self.validate_type(&p.ty);
                        }
                        if let Some(rt) = &f.return_type {
                            self.validate_type(rt);
                        }
                        self.generics = inner;
                    }
                    self.generics = saved;
                }
                Item::Handler(h) => self.check_handler(h),
                // [effect-alias] Its own list: only named effects, and it closes.
                Item::EffectAlias(a) if iface => self.check_effect_alias(a),
                // An effect is all header: its members have no bodies.
                Item::Effect(e) if iface => {
                    self.check_effect_prereqs(e);
                    self.check_route_keys(e);
                    self.check_effect_member_signatures(e);
                    // [actor-effect-kind] The kind's own rules: what an
                    // `actor effect` may declare, and that `send fn` needs one.
                    self.check_effect_kind(e);
                    let saved = self.enter_generics(&e.generics);
                    for f in &e.fns {
                        self.reject_member_effects(f, "effect member functions");
                        self.require_explicit_member(f);
                        self.require_full_clause(f, "an effect member");
                        // Member signatures are declaration sites like any
                        // other, but no body is checked, so validate them
                        // here [name-resolve].
                        let inner = self.enter_generics(&f.generics);
                        for p in &f.params {
                            self.validate_type(&p.ty);
                        }
                        // [implicit-param] The member's implicits went with
                        // the signature facts (`check_signature_facts`).
                        if let Some(rt) = &f.return_type {
                            self.validate_type(rt);
                        }
                        self.generics = inner;
                    }
                    self.generics = saved;
                }
                Item::Qualifier(q) => {
                    let saved = self.enter_generics(&q.generics);
                    if iface {
                        // [comptime-qualifier] A comptime qualifier's subject is a
                        // `std.core.comptime` type, the one ordinary position one may
                        // be named in.
                        self.in_comptime_decl = q.comptime;
                        self.check_fn_slots(&q.name.name, &q.fn_slots, &q.generics);
                        // [qual-depend] One kind of slot per qualifier for now:
                        // nothing in std or the design's catalog mixes an
                        // identity slot with a value slot, and the positional
                        // reading of a mixed block is undecided.
                        if !q.fn_slots.is_empty() && !q.value_slots.is_empty() {
                            self.error(q.name.span, messages::qual_depend_mixed_slots());
                        }
                        for v in &q.value_slots {
                            self.validate_type(&v.ty);
                        }
                        self.check_qualifier_decl(q);
                        self.in_comptime_decl = false;
                    }
                    for f in &q.fns {
                        self.check_fn(f, &[], &[]);
                    }
                    self.generics = saved;
                }
                Item::Struct(s) => {
                    let saved = self.enter_generics(&s.generics);
                    self.in_comptime_decl = s.comptime;
                    if iface {
                        self.check_annotations(&s.annotations, "Struct");
                        for field in &s.fields {
                            self.check_annotations(&field.annotations, "Field");
                        }
                        self.check_fn_slots(&s.name.name, &s.fn_slots, &s.generics);
                        self.validate_auto_quals(&s.auto_qualifiers);
                        self.check_obligations(s);
                        self.check_struct_cycle(s);
                    }
                    for field in &s.fields {
                        // [handler-state-infer] A generated iterator struct's state
                        // field may be inferred (`ty` is `None`); its type is
                        // determined by the minter's struct-literal entry and
                        // recorded there, so there is no written type to
                        // validate or check an initializer against here. (A
                        // user struct's field always writes its type — the
                        // parser only admits the inferred form in a `state { }`
                        // block.)
                        let Some(written) = &field.ty else { continue };
                        if iface {
                            self.validate_type(written);
                            self.check_canbe_mut_field(s, field);
                            // [proj-field] Any struct may hold a borrow through a
                            // `proj` field; it is then a *view*, tied to whatever
                            // its literal stored there [proj-infer].
                            self.check_proj_field(&s.name.name, field);
                            self.check_linear_field(&s.name.name, field);
                        }
                        // [fn-param-default] A field's default is an
                        // expression, checked as a body is: the body pass's.
                        if let (true, Some(default)) = (body, &field.default) {
                            let expected = self.lower_type(written);
                            self.locals.push(HashMap::new());
                            self.check_default(default, &expected);
                            self.locals.pop();
                        }
                    }
                    self.in_comptime_decl = false;
                    self.generics = saved;
                }
                // A `type` is all header.
                Item::Type(t) if iface => {
                    let saved = self.enter_generics(&t.generics);
                    self.in_comptime_decl = t.comptime;
                    self.check_fn_slots(&t.name.name, &t.fn_slots, &t.generics);
                    self.validate_auto_quals(&t.auto_qualifiers);
                    if let Some(alias) = &t.alias {
                        // [mod-namespace] A leading-dot arm in the alias's own
                        // union-arm list (`type Type = .Int | .Str` inside
                        // `namespace Arg`) resolves against *this*
                        // declaration's own enclosing namespace — the one
                        // the flattened name's prefix names — not an outer
                        // expected type, since there is none here.
                        self.own_alias_namespace = t.name.name.rsplit_once('.').map(|(ns, _)| ns.to_string());
                        self.validate_type(alias);
                        self.own_alias_namespace = None;
                    }
                    // [linear-group] The opaque form of the legal-death
                    // rule, checked where the modifier is written.
                    self.check_linear_opaque(t);
                    if t.platform {
                        self.check_platform_type(t);
                    }
                    // [group-obligation] [obligation-by] A `type` declaration's
                    // clause, checked as a struct's is.
                    self.check_obligation_list(&t.name, &t.generics, &t.obligations, t.obligations.len(), t.intrinsic);
                    self.in_comptime_decl = false;
                    self.generics = saved;
                }
                _ => {}
            }
        }
    }

    /// [group-obligation] `struct X<G> : Group<Args> …` — every obligation
    /// names a visible `fns` group with the right arity, and every
    /// member of that group must be satisfied by a visible fn overload with
    /// `Self` bound to this declaration [group-self]. Checked *here*, at
    /// the struct, so a misspelled or missing member surfaces where the
    /// promise is written instead of as a puzzling failure at a use site.
    ///
    /// Satisfaction is by **types, positionally** — parameter types and the
    /// return type equal up to a bijective renaming of type variables. The
    /// member's parameter *names* belong to the group and are not required
    /// of the implementation (unlike [qual-refn-match], which names an
    /// overload someone already declared). Effects are deliberately not
    /// compared: the group declares none and each implementation declares
    /// its own.
    fn check_obligations(&mut self, s: &'p ast::StructDecl) {
        // [linear-group] A `linear struct` — and a conditional container
        // (`canbe linear` reaching a field [linear-generics]) — must have a
        // legal death: at least one fn in the *same file* consuming a
        // parameter of this type (user decision 2026-09-12 — the discharge
        // set is same-file consumption, not a designated member). Round
        // two, so inferred contracts count.
        let conditional = s.generic_canbe.iter().any(|(id, q)| {
            q.name.name == "linear"
                && s.fields.iter().any(|f| f.ty.as_ref().is_some_and(|t| type_mentions_generic(t, &id.name)))
        });
        if s.linear || conditional {
            let set = self.discharge_set(self.symbols.key_or(s, &s.name.name));
            if set.is_empty() {
                let what = if s.linear {
                    format!("linear struct `{}`", s.name.name)
                } else {
                    format!(
                        "conditionally linear struct `{}` (`canbe linear` reaches a field)",
                        s.name.name
                    )
                };
                self.error(
                    s.name.span,
                    messages::linear_obligation_no_discharger(&what, &s.name.name),
                );
            }
        }
        self.check_obligation_list(&s.name, &s.generics, &s.obligations, s.obligations.len(), false);
    }

    /// [group-obligation] The obligation clause of any type declaration — a
    /// struct's, or a `type`'s (comptime round 2, R-1: a named union opts in
    /// with the same clause). Each member of each group must be satisfied by
    /// a visible fn, `self` standing for the declaring type.
    fn check_obligation_list(
        &mut self,
        name: &'p ast::Ident,
        generics: &'p [ast::Ident],
        obligations: &'p [ast::Obligation],
        _count: usize,
        intrinsic: bool,
    ) {
        let scope = self.scope;
        for (i, entry) in obligations.iter().enumerate() {
            let ob = &entry.group;
            // [obligation-by] `by` stamps a generated body over a type's
            // fields or a union's arms; an `intrinsic type` has neither —
            // its implementation is always a hand-written `intrinsic fn` —
            // so there is nothing to stamp. Reject it here with the real
            // reason, rather than letting the comptime pass silently skip
            // the clause and the member search then fail with a misleading
            // "no visible `{member}` matches". The bare obligation (no
            // `by`) is still checked below: it is a promise that the
            // hand-written `intrinsic fn`s exist, exactly like a struct's
            // bare `: Ordered<self>`.
            if intrinsic {
                if let Some(by) = &entry.by {
                    self.error(
                        ob.span,
                        messages::obligation_by_intrinsic_type(&by.text(), &ob.name.name),
                    );
                    continue;
                }
            }
            // [obligation-by] `by` stamps the members for the type it is
            // written on, so the argument has to be `self` [group-self]. The
            // expansion refuses this too; this is the check for a clause the
            // expansion skipped (an unknown group).
            if entry.by.is_some() && !ob.args.iter().all(is_self_ref) {
                self.error(
                    ob.span,
                    messages::obligation_by_not_self(
                        &ob.name.name,
                        &entry.by.as_ref().map(|b| b.text()).unwrap_or_default(),
                    ),
                );
                continue;
            }
            // [linear-group] The pre-2026-09-12 spelling, caught before the
            // unknown-group error would puzzle: linearity is a declaration
            // modifier now.
            if ob.name.name == "Linear" {
                self.error(ob.span, messages::linear_group_linear_obligation());
                continue;
            }
            // The same group twice is a mistake, not an emphasis.
            if obligations[..i]
                .iter()
                .any(|p| p.group.name.name == ob.name.name)
            {
                self.error(ob.span, messages::group_obligation_duplicate(&ob.name.name));
                continue;
            }
            // [lsp-definition] The group name in an obligation clause
            // (`: Linear<self>`) points at the group's declaration, so hover
            // and go-to-definition reach it like any other reference.
            self.record_written_def(ob);
            let meaning = self.named(ob);
            let Some(group) = meaning.group else {
                // A name that exists as something else is a position
                // mistake, not a missing declaration: say which.
                let hint = if names_type(&ob.name.name, &meaning) {
                    format!(
                        " (`{}` is a type; an obligation names a `fns` group)",
                        ob.name.name
                    )
                } else if names_qualifier(&ob.name.name, &meaning) {
                    format!(
                        " (`{}` is a qualifier — `canbe` grants qualifiers, `:` \
                         declares obligations)",
                        ob.name.name
                    )
                } else {
                    String::new()
                };
                let name = ob.name.name.clone();
                self.error_unresolved(
                    ob.span,
                    messages::group_obligation_unknown_group(&name, &hint),
                    &name,
                );
                continue;
            };
            // [group-self] `self` in an obligation's argument list is the
            // declaring type. It is written where a type argument goes rather
            // than inside the group, which is what keeps the group ordinary:
            // its members mention only their own parameters, so the very same
            // group also spreads as `?Group<...>` implicits [implicit-group].
            // Lowered as a written type would be, so a `type` alias's `self`
            // is the union it names — which is what a fulfilment's parameter
            // lowers to as well.
            let self_ty = {
                let written = ast::Type::Named {
                    qualifiers: vec![],
                    base: ast::TypeRef {
                        name: name.clone(),
                        args: generics
                            .iter()
                            .map(|g| ast::Type::Named {
                                qualifiers: vec![],
                                base: ast::TypeRef {
                                    name: g.clone(),
                                    args: vec![],
                                    value_args: vec![],
                                    from: vec![],
                                    at: None,
                                    binder: false,
                                    established: false,
                                    alias: None,
                                    span: g.span,
                                },
                            })
                            .collect(),
                        value_args: vec![],
                        from: vec![],
                        at: None,
                        binder: false,
                        established: false,
                        alias: None,
                        span: name.span,
                    },
                };
                // Not recorded in `written_types`: the node is this
                // temporary's, and its address another's once it is gone.
                self.lower_type_subst(&written, &HashMap::new(), 0)
            };
            for a in &ob.args {
                if !is_self_ref(a) {
                    self.validate_type(a);
                }
            }
            let args: Vec<Ty> = ob
                .args
                .iter()
                .map(|a| {
                    if is_self_ref(a) {
                        self_ty.clone()
                    } else {
                        self.lower_type(a)
                    }
                })
                .collect();
            if args.len() != group.generics.len() {
                self.error(
                    ob.span,
                    messages::group_obligation_type_arg_count(
                        &group.name.name,
                        &group.generics.len(),
                        &args.len(),
                    ),
                );
                continue;
            }
            let subst: HashMap<String, Ty> = group
                .generics
                .iter()
                .map(|p| p.name.clone())
                .zip(args)
                .collect();
            let bound: HashSet<String> = group.generics.iter().map(|p| p.name.clone()).collect();
            // [iter-group] `: Iter<self, It, T>` beside `: Next<self, T>` gives
            // `for x in s` two answers — drive `s`, or mint from it — so the
            // pair is refused; a type is a source or an iterator struct.
            if group.name.name == "Iter"
                && obligations.iter().any(|p| p.group.name.name == "Next")
            {
                self.error(
                    ob.span,
                    messages::iter_group_source_and_iterator(&name.name, &ob.name.name),
                );
                continue;
            }
            for member in &group.fns {
                let outer = self.enter_generics(&group.generics);
                let member_ty = self.member_fn_ty(member);
                self.generics = outer;
                let expected = substitute_vars(&member_ty, &subst, &bound);
                // [iter-yield-proj] Which borrowness this member's filler must
                // deliver: a `proj` on an argument the member's return
                // mentions (`Next<self, proj T>`'s `next`). Checked only on a
                // member over `self` — `Iter`'s `next` is over the iterator
                // struct, whose own `: Next` obligation answers it.
                let self_generic = group
                    .generics
                    .iter()
                    .zip(&ob.args)
                    .find(|(_, a)| matches!(a, ast::Type::Named { qualifiers, base } if qualifiers.is_empty() && base.name.name == "self"))
                    .map(|(g, _)| g.name.clone());
                let (over_self, ob_proj) = match &member_ty {
                    Ty::Fn { params, ret, .. } => (
                        self_generic
                            .as_ref()
                            .is_some_and(|g| params.iter().any(|p| ty_mentions_var(p, g))),
                        group
                            .generics
                            .iter()
                            .zip(&ob.args)
                            .any(|(g, a)| first_proj_span(a).is_some() && ty_mentions_var(ret, &g.name)),
                    ),
                    _ => (false, false),
                };
                let mut found = false;
                if let Some(entries) = scope.fns.get(member.name.name.as_str()) {
                    for e in entries {
                        // [fn-rename] A renamed overload answers to its new
                        // name only, here as at a call (B1 census D9).
                        if self.renamed_away(&member.name.name, e.key) {
                            continue;
                        }
                        let inner = self.enter_generics(&e.decl.generics);
                        let candidate = self.member_fn_ty(e.decl);
                        self.generics = inner;
                        let mut fwd = HashMap::new();
                        let mut rev = HashMap::new();
                        // [iter-yield-proj] A member not over `self` (`Iter`'s
                        // `next`) reads its element's borrowness off the
                        // iterator struct's own `: Next`, so a walking
                        // iterator's `Emitted (proj(p) T)` fills `Emitted T`.
                        let (expected_m, candidate) = if over_self {
                            (expected.clone(), candidate)
                        } else {
                            (strip_ret_arm_proj(&expected), strip_ret_arm_proj(&candidate))
                        };
                        if tys_match_renamed(&expected_m, &candidate, &mut fwd, &mut rev) {
                            // [iter-yield-proj] `proj` strips from types, so the
                            // shapes match either way; the *borrowness* has to
                            // agree separately. An obligation at `proj T`
                            // promises borrowed elements, which the member's
                            // written return must deliver — and vice versa:
                            // a `next` emitting `proj` under a plain
                            // `Next<self, T>` would hand a borrow to callers
                            // expecting to own it.
                            let member_proj = e
                                .decl
                                .return_type
                                .as_ref()
                                .is_some_and(|t| !proj_arm_indices(t).is_empty());
                            if over_self && ob_proj != member_proj {
                                self.error(
                                    ob.span,
                                    if ob_proj {
                                        messages::iter_yield_proj_owned_element(
                                            &name.name,
                                            &ob.name.name,
                                            &member.name.name,
                                        )
                                    } else {
                                        messages::iter_yield_proj_undeclared_borrow(
                                            &name.name,
                                            &member.name.name,
                                            &ob.name.name,
                                        )
                                    },
                                );
                            }
                            found = true;
                            break;
                        }
                    }
                }
                if !found {
                    let Ty::Fn { params, ret, .. } = &expected else {
                        continue;
                    };
                    let shown: Vec<String> = params.iter().map(|p| p.to_string()).collect();
                    self.error(
                        ob.span,
                        messages::group_obligation_no_member(
                            &name.name,
                            &ob.name.name,
                            &member.name.name,
                            &shown.join(", "),
                            &ret,
                        ),
                    );
                }
            }
        }
    }

    /// [qual-canbe-optin] A `canbe` clause names one of the compiler's
    /// permission/obligation qualifiers; user qualifiers are applied in
    /// types, not granted by opt-in.
    ///
    /// `once` joined the list 2026-09-07 (user decision) so a hand-written
    /// **pass** — a type with a `next` [iter-protocol] — can say that
    /// driving it uses it up. Opting in is the author's call for the same
    /// reason `Linear` is declared rather than applied [linear-group]: an
    /// obligation should not attach to someone's type on the strength of a
    /// method name.
    fn validate_auto_quals(&mut self, quals: &[TypeRef]) {
        for q in quals {
            if matches!(q.name.name.as_str(), "Mut" | "once") {
                continue;
            }
            // [obligation-by] `canbe hashed` / `canbe ordered` are **gone** (user
            // decision 2026-09-21): a type is hashable or orderable exactly when
            // a `hash`/`cmp` for it exists, so the opt-in became the
            // implementation — one token where the type wants the structural one.
            if matches!(q.name.name.as_str(), "hashed" | "ordered") {
                let group = if q.name.name == "hashed" {
                    "Hashed"
                } else {
                    "Ordered"
                };
                self.error(
                    q.span,
                    messages::obligation_by_canbe_hashed(
                        &q.name.name,
                        &group,
                        &(if q.name.name == "hashed" { "hash" } else { "cmp" }),
                    ),
                );
                continue;
            }
            // [linear-group] `canbe` grants a *qualifier*; linearity is an
            // **obligation**, and declaring it means supplying the `close`
            // that discharges it. The two were spelled alike until R4; now
            // `canbe` means only "may be qualified thus".
            if q.name.name == "linear" {
                self.error(q.span, messages::linear_group_canbe_linear());
                continue;
            }
            self.error(q.span, messages::qual_canbe_optin_unknown(&q.name.name));
        }
    }

    /// [decl-explicit] Nothing the compiler cannot see may be inferred: a
    /// fn with no body states its effects, deductions, and return type
    /// explicitly (user decision 2026-09-03). Inference from an absent
    /// body is a *guess*, and the most permissive one — which is how
    /// std's `add` came to keep an element the list had taken ownership
    /// of. Effect members are the same case with one exception: they may
    /// not declare effects at all [effect-member-no-effects].
    fn require_explicit_decl(&mut self, f: &FnDecl) {
        if f.body.is_some() {
            return;
        }
        if !f.intrinsic {
            return;
        }
        self.require_explicit(f, "intrinsic fn", true);
    }

    /// [effect-member-unique] [effect-member-overload] A member name may recur
    /// **within** its effect only as an *overload*: the parameter lists must
    /// differ, exactly as for top-level fns [fn-overload] (§5.10.2 sub-question
    /// A, user decision 2026-09-14 — phase 4's `Fs` declares `close(InStream)`
    /// and `close(OutStream)`, and `position` twice). Two members with the same
    /// name *and* the same parameter types are the old duplicate error.
    ///
    /// Across effects the name may recur freely ([effect-member-overload], user
    /// decision 2026-09-14, lifting the 2026-09-05 program-wide ban): a call
    /// disambiguates by which effect has a handler in scope, or explicitly
    /// with `member@Effect(…)` [effect-at] — the syntax whose absence was the
    /// original ban's reason.
    ///
    /// Signatures are compared as *lowered* types rather than as written text,
    /// so two spellings of one type (an alias, a differently-written generic
    /// argument) are the duplicate they are. Reported at the **second**
    /// declaration, so the diagnostic is deterministic and fires exactly once
    /// per collision.
    fn check_effect_member_signatures(&mut self, e: &'p EffectDecl) {
        // Lowered fixed-parameter lists, in declaration order. Under the
        // effect's generics as well as the member's: lowered without them, an
        // effect's `M` read as a type named `M`, and that lowering is what the
        // IR reads for the written type (`Checked::written_types`) when no
        // later lowering overwrote it (found 2026-10-20, when the interface
        // pass changed which lowering came last).
        let mut seen: Vec<(&str, Vec<Ty>)> = Vec::new();
        let outer = self.enter_generics(&e.generics);
        for f in &e.fns {
            self.check_send_member(f);
            let inner = self.enter_generics(&f.generics);
            let params: Vec<Ty> = f
                .params
                .iter()
                .filter(|p| !p.implicit)
                .map(|p| self.lower_type(&p.ty))
                .collect();
            self.generics = inner;
            if seen
                .iter()
                .any(|(name, ps)| *name == f.name.name.as_str() && *ps == params)
            {
                self.error(
                    f.name.span,
                    messages::effect_member_unique_duplicate(&e.name.name, &f.name.name),
                );
            }
            seen.push((f.name.name.as_str(), params));
        }
        self.generics = outer;
    }

    /// [actor-send-fn] What a `send fn` may declare. A send member is a
    /// *message*: sending it enqueues an invocation and returns immediately,
    /// so there is no value to answer with — a reply travels as a `Reply<T>`
    /// parameter the sender mints with `replyto`. A written return type is
    /// therefore an error naming that shape, rather than a silently ignored
    /// annotation. (The later call-member sugar goes the other way: a `-> T`
    /// member desugars *into* a send member with a trailing token, so the
    /// two spellings must not both mean something here.)
    /// [actor-effect-kind] The effect-level kind rules (user decision
    /// 2026-09-15, EU-5). The kind is declared, not diagnosed: an author
    /// choosing between `effect` and `actor effect` is choosing whether the
    /// protocol crosses threads, and everything that cannot cross is refused
    /// **here**, where the choice is being made, rather than at some later
    /// binding.
    ///
    /// Two directions:
    /// * `send fn` needs an `actor effect` — a message has nowhere to go in a
    ///   synchronous protocol.
    /// * inside an `actor effect`, a member may not **keep** a parameter, take
    ///   a `Mut` one, return a `proj` view, or carry a **non-sendable** payload
    ///   [actor-sendable]. Each is a borrow or a share that a seam cannot
    ///   carry.
    fn check_effect_kind(&mut self, e: &'p EffectDecl) {
        let saved = self.enter_generics(&e.generics);
        for f in &e.fns {
            if f.is_send && !e.is_actor {
                self.error(
                    f.name.span,
                    messages::actor_send_fn_plain_effect(&f.name.name, &e.name.name),
                );
            }
            if e.is_actor {
                self.check_actor_member(e, f);
            }
        }
        self.generics = saved;
    }

    /// [actor-effect-kind] [actor-sendable] One member of an `actor effect`,
    /// against the refusal list. The diagnostics name the *law* rather than the
    /// symptom ("a `Mut` parameter in an `actor effect`"), because the remedy
    /// is a design decision — send a copy, or make the protocol synchronous.
    fn check_actor_member(&mut self, e: &'p EffectDecl, f: &'p FnDecl) {
        let inner = self.enter_generics(&f.generics);
        // A kept parameter is a borrow that outlives the call, which a
        // message cannot carry: the payload crosses the seam and the sender
        // gives it up.
        for d in f.deductions.iter().flatten() {
            // Every entry but `Moved`/`Deferred` keeps the parameter: a bare
            // `=> p`, an exhaustive or subtractive qualifier list, or a
            // projection. A deferral consumes too — what differs is what the
            // body may do with the obligation [linear-defer].
            if matches!(
                d.kind,
                ast::DeductionKind::Moved | ast::DeductionKind::Deferred
            ) {
                continue;
            }
            let Some(name) = d.param_name() else { continue };
            // [copy-scalar-free] Keeping a Copy scalar is moving it: a copy.
            if f.params.iter().any(|p| p.name.name == name.name && salvo_syntax::is_copy_scalar_type(&p.ty)) {
                continue;
            }
            self.error(
                d.span,
                messages::actor_sendable_kept_payload(&f.name.name, &e.name.name, &name.name),
            );
        }
        for p in f.params.iter().filter(|p| !p.implicit) {
            // A `Mut` parameter is an exclusive borrow of the caller's value.
            if let ast::Type::Named { qualifiers, .. } = &p.ty {
                if let Some(q) = qualifiers.iter().find(|q| q.name.name == "Mut") {
                    self.error(
                        q.span,
                        messages::actor_sendable_mut_payload(&f.name.name, &e.name.name),
                    );
                }
            }
            // [actor-sendable] C-4(a)'s structural rule, at the declaration.
            let ty = self.lower_type(&p.ty);
            if let Some(why) = self.unsendable_reason(&ty) {
                self.error(
                    p.ty.span(),
                    messages::actor_sendable_unsendable_payload(
                        &f.name.name,
                        &e.name.name,
                        &ty,
                        &why,
                    ),
                );
            }
        }
        // A `proj` return is a borrow of something the actor owns.
        if let Some(rt) = &f.return_type {
            if let Some(span) = first_proj_span(rt) {
                self.error(
                    span,
                    messages::actor_sendable_borrowed_return(
                        &f.name.name,
                        &e.name.name,
                        &(if first_ref_span(rt) == Some(span) { "a `ref` handle" } else { "a `proj` view" }),
                    ),
                );
            }
        }
        self.generics = inner;
    }

    /// [actor-sendable] Why a value of this type may not cross a seam **as a
    /// message or a task capture**, or `None` when it may (user decision
    /// 2026-09-15, C-4(a) as the structural rule). Two kinds of contents are
    /// refused, both because the *other* side could never own what it
    /// received:
    ///
    /// * a **function-typed** field or component — a message payload of fn
    ///   type has no wire and no enum rendering yet (C-4(c) is the recorded
    ///   growth point for when sent closures become real);
    /// * a **`proj` view** — a borrow of a value the sender still owns.
    fn unsendable_reason(&self, ty: &Ty) -> Option<&'static str> {
        if self.ty_holds_fn(ty, 0) {
            return Some("it holds a function value, which is shared rather than owned");
        }
        self.unshareable_reason(ty)
    }

    /// [effect-handle] [actor-sendable] Why a **handler's** constructor
    /// parameter or state field may not sit behind a handle, or `None` when
    /// it may. A function value is fine here (user decision 2026-09-28): a
    /// Salvo lambda captures by value, and both backends store a handler's
    /// callback in a form that crosses threads (`Box<dyn FnMut + Send>` /
    /// `Arc<dyn Fn + Send + Sync>` on Rust [rs-fn-field]). What stays refused
    /// is a `proj` view — a borrow of a value the scope still owns.
    fn unshareable_reason(&self, ty: &Ty) -> Option<&'static str> {
        if self.ty_holds_proj(ty) {
            return Some("it holds a `proj` view, which borrows the sender's value");
        }
        None
    }

    /// [actor-sendable] Whether a (lowered) type is, or transitively holds, a
    /// function value. Structural like `ty_holds_proj`, with the same depth
    /// guard against a recursive struct.
    fn ty_holds_fn(&self, ty: &Ty, depth: usize) -> bool {
        if depth > 8 {
            return false;
        }
        match ty.strip_quals() {
            Ty::Fn { .. } => true,
            Ty::Union(arms) | Ty::Tuple(arms) => {
                arms.iter().any(|a| self.ty_holds_fn(a, depth + 1))
            }
            Ty::Array(elem) => self.ty_holds_fn(elem, depth + 1),
            Ty::Named { name, args } => {
                if args.iter().any(|a| self.ty_holds_fn(a, depth + 1)) {
                    return true;
                }
                let Some(decl) = self.symbols.structs.get(name.as_str()) else {
                    return false;
                };
                // A field's *written* type is enough: a fn type is syntactic
                // (`(T) -> U`), so no lowering is needed to recognise one, and
                // a named field type recurses through the same map.
                let fields: Vec<&ast::Type> = decl.fields.iter().filter_map(|f| f.ty.as_ref()).collect();
                fields.iter().any(|t| self.ast_type_holds_fn(t, depth + 1))
            }
            _ => false,
        }
    }

    /// [actor-sendable] The written-type half of `ty_holds_fn`: a struct
    /// field's declared type, without lowering it (a fn type is syntactic, and
    /// lowering here would need the declaring scope's generics).
    fn ast_type_holds_fn(&self, ty: &ast::Type, depth: usize) -> bool {
        if depth > 8 {
            return false;
        }
        match ty {
            ast::Type::Literal { .. } => false,
            ast::Type::Fn { .. } => true,
            ast::Type::Union { arms, .. } => arms.iter().any(|a| self.ast_type_holds_fn(a, depth + 1)),
            ast::Type::Tuple { elems, .. } => {
                elems.iter().any(|e| self.ast_type_holds_fn(e, depth + 1))
            }
            ast::Type::Array { elem, .. } => self.ast_type_holds_fn(elem, depth + 1),
            ast::Type::Nullable { inner, .. } => self.ast_type_holds_fn(inner, depth + 1),
            ast::Type::Spread { inner, .. } => self.ast_type_holds_fn(inner, depth + 1),
            ast::Type::QualifiedGroup { base, .. } => self.ast_type_holds_fn(base, depth + 1),
            ast::Type::Named { base, .. } => {
                if base.args.iter().any(|a| self.ast_type_holds_fn(a, depth + 1)) {
                    return true;
                }
                match self.named(base).structure {
                    Some(decl) => decl
                        .fields
                        .iter()
                        .any(|f| f.ty.as_ref().is_some_and(|t| self.ast_type_holds_fn(t, depth + 1))),
                    None => false,
                }
            }
        }
    }

    /// [actor-free-send-fn] A **free `send fn`** — the send kind extended to a
    /// function (user decision 2026-09-17, FC-1(a)). It runs by being
    /// *scheduled*, never called: a `replyto` targets it [task-mint], its
    /// answer arrives as its trailing parameter, and it answers nothing.
    ///
    /// Every rule here is inherited rather than invented — it is
    /// [actor-effect-kind]'s refusal list, applied to a declaration that has
    /// no effect to belong to: no return type, no kept parameter (the payload
    /// crosses a thread boundary, so it is always consumed), no `Mut`
    /// parameter, no `proj` return, and every parameter sendable
    /// [actor-sendable]. The diagnostics name the law, because the remedy is a
    /// design decision.
    ///
    /// **First-pass cut**: no effects but `[waitfor]`. A task body runs
    /// detached from the scope that minted it, so there is nothing there to
    /// supply a handler — capturing the minting scope's handlers would send
    /// values the sender still owns, which [actor-sendable] exists to refuse.
    /// An `Addr` capture is the way to reach an actor, and it needs no effect
    /// declaration [actor-use-addr]. Lifting this for *actor-backed* effects
    /// (whose provider is an addr stub, and so sendable) is the recorded
    /// growth point.
    fn check_free_send_fn(&mut self, f: &'p FnDecl) {
        if !f.is_send {
            return;
        }
        self.check_send_member(f);
        // A generic target would need its type arguments at the mint, which
        // carries only captures; and a generic parameter tells [actor-sendable]
        // nothing, so the refusal list could not be checked here either. The
        // first pass refuses it rather than checking it at every mint.
        if let Some(g) = f.generics.first() {
            self.error(f.name.span, messages::actor_free_send_fn_generic(&f.name.name, &g.name));
        }
        let inner = self.enter_generics(&f.generics);
        for d in f.deductions.iter().flatten() {
            // [linear-defer] A deferral consumes too.
            if matches!(
                d.kind,
                ast::DeductionKind::Moved | ast::DeductionKind::Deferred
            ) {
                continue;
            }
            let Some(name) = d.param_name() else { continue };
            // [copy-scalar-free] Keeping a Copy scalar is moving it: a copy.
            if f.params.iter().any(|p| p.name.name == name.name && salvo_syntax::is_copy_scalar_type(&p.ty)) {
                continue;
            }
            self.error(d.span, messages::actor_free_send_fn_kept_param(&f.name.name, &name.name));
        }
        for p in f.params.iter().filter(|p| !p.implicit) {
            if let ast::Type::Named { qualifiers, .. } = &p.ty {
                if let Some(q) = qualifiers.iter().find(|q| q.name.name == "Mut") {
                    self.error(q.span, messages::actor_free_send_fn_mut_param(&f.name.name));
                }
            }
            let ty = self.lower_type(&p.ty);
            if let Some(why) = self.unsendable_reason(&ty) {
                self.error(
                    p.ty.span(),
                    messages::actor_free_send_fn_unsendable_param(&f.name.name, &ty, &why),
                );
            }
        }
        if let Some(rt) = &f.return_type {
            if let Some(span) = first_proj_span(rt) {
                self.error(span, messages::actor_free_send_fn_borrowed_return(&f.name.name));
            }
        }
        // [task-effects] An ordinary effect is **inherited from the frame that
        // mints** (user decision 2026-09-26): the restriction here was written
        // when there were no thread-shareable handlers, and there are now — a
        // shareable binding yields an owned handle that crosses the seam, which
        // is exactly what `spawn` inheritance carries into a child
        // [actor-spawn-inherit]. The mint site resolves it and says so when the scope
        // has nothing to give.
        //
        // Two forms still cannot be: `[use]`/`[spawn]` are capabilities of the
        // *frame* (a task has no scope to register a handler in and nothing
        // would see it).
        for eff in f.effects.iter().flatten() {
            let (span, why) = match eff {
                EffectRef::Use(sp) => (
                    *sp,
                    "`use` registers handlers for the rest of a scope, and a scheduled body \
                     has no scope anything else can see"
                        .to_string(),
                ),
                EffectRef::Spawn(sp) => (
                    *sp,
                    "`spawn` places work on a pool from the frame that has one, and a \
                     scheduled body is already that work"
                        .to_string(),
                ),
                // Inherited at the mint.
                EffectRef::Effect(_) | EffectRef::AnyEffect(_) => continue,
            };
            self.error(span, messages::actor_free_send_fn_effect(&f.name.name, &eff, &why));
        }
        self.generics = inner;
    }

    fn check_send_member(&mut self, f: &'p FnDecl) {
        if !f.is_send {
            return;
        }
        if let Some(ret) = &f.return_type {
            self.error(ret.span(), messages::actor_send_fn_return_type(&f.name.name));
        }
    }

    /// [platform-handler] The restrictions a `platform handler` carries, all
    /// of them consequences of the implementation being a class the *build*
    /// supplies rather than Salvo code (FS-1 resolved as O-M2, user decision
    /// 2026-09-14).
    ///
    /// The effect is an ordinary Salvo one and only this *handler* is the
    /// host's, so it registers with `use` like any other [platform-tree].
    /// [platform-type] What a platform type may declare: no type parameters
    /// yet (generic platform types are a later step, runtime E1), no
    /// slots, no obligations (it has no fields to stamp over, and its
    /// comparisons are platform fns), and `canbe Mut` only when linear — with
    /// copies sharing one host object, a `Mut` permission on a copyable
    /// handle would not mean what it means for a struct.
    fn check_platform_type(&mut self, t: &'p ast::TypeDecl) {
        let name = &t.name.name;
        // [platform-slots] Identity slots (`Set<T>(?hash, ?eq)`) are allowed
        // (user decision 2026-10-04): they are part of the type, as on any
        // type declaration, and the identity a value carries is the host's
        // to keep. A linear handle has no use for one.
        if !t.fn_slots.is_empty() && t.linear {
            self.error(t.name.span, messages::platform_slots_no_slots(&name));
        }
        // [platform-iterable] `: Iter<self, It, T>` is the one obligation a
        // platform type may take (checked as any type's is): it names the
        // Salvo pass, which `iterable` then promises the host's loop agrees
        // with. Anything else has no fields to stamp over, and comparisons
        // are `platform fn`s.
        if let Some(o) = t
            .obligations
            .iter()
            .find(|o| o.group.name.name != "Iter" || o.by.is_some())
        {
            self.error(o.group.span, messages::platform_type_obligation(&name));
        }
        if t.iterable && !t.obligations.iter().any(|o| o.group.name.name == "Iter") {
            self.error(t.name.span, messages::platform_iterable_no_iter(&name));
        }
        if t.threadsafe && t.linear {
            self.error(t.name.span, messages::platform_type_threadsafe_linear(&name));
        }
        // [platform-value-type] A copyable platform type that `canbe Mut` is a
        // *value*: its copy is the host's own copy, never a shared object, so
        // `Mut` means what it means for a struct (user decision 2026-10-04,
        // ROADMAP 0.7). Sharing a mutable host object across threads would
        // need the opposite promise, so `threadsafe` refuses it.
        for q in &t.auto_qualifiers {
            if q.name.name == "Mut" && t.threadsafe {
                self.error(q.span, messages::platform_value_type_threadsafe_mut(&name));
            }
        }
    }

    fn check_platform_handler(&mut self, h: &'p ast::HandlerDecl) {
        if !h.platform {
            return;
        }
        // [platform-handler] Its members are the host's: a member written with
        // a Salvo body is refused, and so is Salvo state — the implementation
        // class owns its fields (user decision 2026-10-01, ABI D8).
        if let Some(f) = h.fns.iter().find(|f| f.body.is_some()) {
            self.error(f.name.span, messages::platform_handler_body(&h.name.name));
        }
        if let Some(field) = h.state.first() {
            self.error(field.name.span, messages::platform_handler_state(&h.name.name));
        }
        // Dependencies would have to be supplied *to host code*, which
        // cannot perform a Salvo effect: the host reaches the outside world
        // directly, which is why it is host code.
        if h.effects.as_ref().is_some_and(|e| !e.is_empty()) {
            self.error(h.name.span, messages::platform_handler_dependencies(&h.name.name));
        }
        // [ref-handle] A `ref` return is a path into the caller's container,
        // which host code has no way to answer (user decision 2026-10-10).
        // The handler may restate its members or leave them to the effect.
        let effect = match h.of.first() {
            Some(ast::Type::Named { base, .. }) => self.symbols.effects.get(self.out.written_key(base)).copied(),
            _ => None,
        };
        for f in effect.map(|e| e.fns.as_slice()).unwrap_or_default() {
            if f.return_type.as_ref().and_then(first_ref_span).is_some() {
                let span = h.fns.iter().find(|g| g.name.name == f.name.name).and_then(|g| g.return_type.as_ref()).and_then(first_ref_span).unwrap_or(h.name.span);
                self.error(
                    span,
                    messages::ref_handle_platform_handler(&h.name.name, &f.name.name),
                );
            }
        }
        // Generic-free: the host writes one concrete class, and there is no instance per type argument to
        // construct at a `use` site [backend-never-wrong].
        if !h.generics.is_empty() {
            self.error(h.name.span, messages::platform_handler_generic(&h.name.name));
        }
    }

    /// [decl-explicit] The effect-member form: return type and deductions
    /// are required, effects are forbidden [effect-member-no-effects].
    fn require_explicit_member(&mut self, f: &FnDecl) {
        // [effect-member-none] An effect member's absent return type is
        // `None`, as a fn's is (user decision 2026-10-04): the clause and the
        // parameters still say everything else.
        self.require_explicit(f, "effect member", false);
    }

    fn require_explicit(&mut self, f: &FnDecl, kind: &str, want_effects: bool) {
        let name = &f.name.name;
        // [actor-send-fn] A `send fn` answers nothing — the reply, if there
        // is one, is a `Reply<T>` parameter — so there is no return type to
        // require, and writing one is its own error (`check_send_member`).
        if f.return_type.is_none() && !f.is_send && kind != "effect member" {
            self.error(f.name.span, messages::decl_body_return_type(&kind, &name));
        }
        if want_effects && f.effects.is_none() {
            self.error(f.name.span, messages::decl_body_effect_list(&kind, &name));
        }
        // The deduction clause: per parameter, in `require_full_clause`
        // [deduce-syntax] — a declaration with nothing to deduce (only Copy
        // scalars, variadics, implicits) needs no clause at all.
    }

    /// Checks one function body. `extra_params`/`state` provide handler
    /// constructor parameters and state fields as in-scope variables.
    // ================= implicit parameters [implicit-param] =================

    /// Why a fn value does not fit a fn-typed position, in the words a
    /// printed type cannot supply.
    ///
    /// `Ty`'s Display shows parameters, effects and the result, but **not the
    /// contract** — what a call does to each argument — so two types that
    /// differ only there render identically, and the bare mismatch reads
    /// "expects `(Int, Int) -> Int`, found `(Int, Int) -> Int`". This names
    /// the argument, the direction, and what to write instead. Returns
    /// `None` when the printed types already differ, which is when they are
    /// explanation enough.
    fn fn_fit_reason(&self, want: &Ty, got: &Ty, got_name: &str) -> Option<String> {
        let (
            Ty::Fn {
                params: wp,
                contract: wc,
                effects: we,
                ..
            },
            Ty::Fn {
                params: gp,
                contract: gc,
                effects: ge,
                ..
            },
        ) = (want.strip_quals(), got.strip_quals())
        else {
            return None;
        };
        // [fn-kept-borrow] A consumed parameter handed a borrow.
        if let Some(h) = consumed_borrow_hint(got, want, &format!("`{got_name}`")) {
            return Some(h);
        }
        if wp.len() != gp.len() || want.to_string() != got.to_string() {
            return None; // the printed types differ; they speak for themselves
        }
        // [fn-effects] A value may perform *fewer* effects than the position
        // allows, never more.
        let extra: Vec<String> = ge
            .iter()
            .filter(|e| !we.contains(e))
            .map(|e| e.to_string())
            .collect();
        if !extra.is_empty() {
            return Some(format!(
                "`{got_name}` performs `[{}]`, which this position does not \
                 declare — a fn type without an effect list performs nothing, \
                 and a call site cannot supply what it was never told about",
                extra.join(", ")
            ));
        }
        // [fn-contract] Expected kept ⇒ supplied must keep. The reverse
        // direction is fine, so only this way round is worth explaining.
        let at = |c: &Option<Vec<FnParamContract>>, i: usize| -> (bool, bool, Option<String>) {
            match c {
                None => (true, false, None),
                Some(list) => list
                    .get(i)
                    .map(|e| (e.kept, e.mutable, e.name.clone()))
                    .unwrap_or((true, false, None)),
            }
        };
        for i in 0..wp.len() {
            let (w_kept, w_mut, w_name) = at(wc, i);
            let (g_kept, g_mut, g_name) = at(gc, i);
            let which = g_name
                .or(w_name)
                .map(|n| format!("`{n}`"))
                .unwrap_or_else(|| format!("argument {}", i + 1));
            if w_kept && !g_kept {
                return Some(format!(
                    "`{got_name}` *consumes* {which} while this position keeps it: \
                     the types match, the contracts do not. Either give \
                     `{got_name}` a deduction clause that gives it back \
                     (`=> {}`), or declare the position as consuming \
                     (`=>[param] !{}` on the enclosing declaration)",
                    which.trim_matches('`'),
                    which.trim_matches('`')
                ));
            }
            if g_mut && !w_mut && w_kept {
                return Some(format!(
                    "`{got_name}` mutates {which}, which this position does not \
                     permit: a `Mut` argument has to be declared where the \
                     function is *taken*, not only where it is written"
                ));
            }
        }
        None
    }

    /// [implicit-fn-only] Implicit parameters are declared on fns. Anywhere
    /// else there is no call site that could resolve them: an effect member
    /// is reached through a handler, a group member is a signature for a
    /// parameter, and a lambda's type has no room for one.
    fn reject_implicits(&mut self, f: &'p FnDecl, what: &str) {
        for p in f.params.iter().filter(|p| p.implicit) {
            self.error(p.span, messages::implicit_fn_only_implicit_param(&what));
        }
        for g in &f.implicit_groups {
            self.error(g.span, messages::implicit_fn_only_group_spread(&what));
        }
    }

    /// The implicit parameters of a fn, in the order both sides render them:
    /// the written `?name: FnType` ones first, then each `?Group<T>` spread's
    /// members in declaration order [implicit-group].
    ///
    /// A group has no binder (user decision 2026-09-05): its members become
    /// implicit parameters in their own right, so an inner fn can declare
    /// `?add` directly, or reach the same parameter through a different
    /// grouping, and a call site overrides one by its own name.
    fn expand_implicits(&mut self, f: &'p FnDecl) -> Vec<ImplicitParam> {
        let out = self.collect_implicits(f);
        match self.own_fn {
            Some(key) => {
                self.out.implicit_params.insert(key, out.clone());
            }
            // A *member* — a handler's implementation of an effect member —
            // is not keyed by its `DeclId`, so it is keyed by its own name span, exactly
            // as the effect member it implements is [implicit-param].
            None if !out.is_empty() => {
                self.out
                    .implicit_members
                    .insert(self.key(f.name.span), out.clone());
            }
            None => {}
        }
        out
    }

    /// The expansion itself, without recording it: shared by fns and by
    /// effect members, which are not keyed by their `DeclId`.
    ///
    /// Must be called with the declaration's generics in scope — for a member
    /// that means the effect's generics as well as its own, or the types
    /// would not lower to variables.
    fn collect_implicits(&mut self, f: &'p FnDecl) -> Vec<ImplicitParam> {
        let mut out: Vec<ImplicitParam> = Vec::new();
        for p in f.params.iter().filter(|p| p.implicit) {
            let ty = self.lower_type(&p.ty);
            // [implicit-param] Only a *function* can be resolved by name and
            // type: the name is a fn name, and what fills it is a fn value.
            if !matches!(ty.strip_quals(), Ty::Fn { .. }) && !ty.is_unknown() {
                self.error(p.span, messages::implicit_param_not_fn_type(&p.name.name, &ty));
                continue;
            }
            out.push(ImplicitParam {
                name: p.name.name.clone(),
                ty,
                span: p.span,
                borrowed_arms: match &p.ty {
                    ast::Type::Fn { ret, .. } => proj_arm_indices(ret),
                    _ => Vec::new(),
                },
                // [cmp-carry] Set below, once the signature's binders are
                // known: a written `?cmp` *is* the binding when the types
                // carry `?cmp`.
                binder: false,
                slot: None,
                bound: None,
                local: p.name.name.clone(),
            });
        }
        for g in &f.implicit_groups {
            let Some(group) = self.named(g).group else {
                self.error(g.span, messages::implicit_group_unknown_group(&g.name.name));
                continue;
            };
            // The spread's type arguments bind the group's generics. Written
            // types, so they are validated like any other declaration site —
            // which is also what reports `self` here, since only an obligation
            // binds it [group-self].
            for a in &g.args {
                self.validate_type(a);
            }
            let args: Vec<Ty> = g.args.iter().map(|a| self.lower_type(a)).collect();
            if args.len() != group.generics.len() {
                self.error(
                    g.span,
                    messages::implicit_group_type_arg_count(
                        &group.name.name,
                        &group.generics.len(),
                        &args.len(),
                    ),
                );
                continue;
            }
            let subst: HashMap<String, Ty> = group
                .generics
                .iter()
                .map(|p| p.name.clone())
                .zip(args)
                .collect();
            let group_generics: HashSet<String> =
                group.generics.iter().map(|p| p.name.clone()).collect();
            for member in &group.fns {
                let saved = self.enter_generics(&group.generics);
                let ty = self.member_fn_ty(member);
                self.generics = saved;
                let ty = substitute_vars(&ty, &subst, &group_generics);
                // [iter-yield-proj] `?Next<It, proj T>`: a `proj` on a spread
                // argument marks the arms of the member's return that mention
                // that generic as borrows — the caller requires a pass that
                // *walks* data. The member's own return may mark arms too.
                let mut borrowed_arms = member
                    .return_type
                    .as_ref()
                    .map(proj_arm_indices)
                    .unwrap_or_default();
                for (gi, arg) in g.args.iter().enumerate() {
                    if first_proj_span(arg).is_none() {
                        continue;
                    }
                    let Some(generic) = group.generics.get(gi) else {
                        continue;
                    };
                    if let Some(ast::Type::Union { arms, .. }) = member.return_type.as_ref() {
                        for (i, arm) in arms.iter().enumerate() {
                            if type_mentions_generic(arm, &generic.name)
                                && !borrowed_arms.contains(&i)
                            {
                                borrowed_arms.push(i);
                            }
                        }
                    }
                }
                borrowed_arms.sort_unstable();
                out.push(ImplicitParam {
                    name: member.name.name.clone(),
                    ty,
                    span: g.span,
                    borrowed_arms,
                    binder: false,
                    slot: None,
                    bound: None,
                    local: member.name.name.clone(),
                });
            }
        }
        // [cmp-binder] The **binders** this signature captures. All `?name`
        // occurrences in one signature are one binding (the ordering round's decision
        // 11): bound by an explicit implicit parameter when one is declared
        // — `empty_heap<T>(?cmp: (T, T) -> Int) -> Mut List<T> as Heap(?cmp)`,
        // where resolution fills it and the return type publishes what it
        // chose — and otherwise **captured** from the argument types, as
        // `heap_push`'s is. Its fn type is never written at the fn: the slot
        // it fills states it, which is why this reads the slot rather than
        // the signature.
        let mut captured: Vec<(String, Ty, Span, Option<String>)> = Vec::new();
        for p in f.params.iter().filter(|p| !p.implicit) {
            let ty = self.lower_type(&p.ty);
            self.collect_binder_slots(&ty, p.span, &mut captured);
        }
        if let Some(rt) = &f.return_type {
            let ty = self.lower_type(rt);
            self.collect_binder_slots(&ty, rt.span(), &mut captured);
        }
        // [qual-ctor-fn] `-> Mut List<T> as Heap(?cmp)`: the claim a
        // constructor mints carries the identity too.
        if let Some(cref) = &f.constructs {
            let base = f
                .return_type
                .as_ref()
                .map(|rt| self.lower_type(rt))
                .unwrap_or_else(Ty::none);
            let empty = HashMap::new();
            let quals = self.lower_quals(std::slice::from_ref(cref), &empty, 0);
            let claimed = base.qualify(quals);
            self.collect_binder_slots(&claimed, cref.span, &mut captured);
        }
        // [deduce-reapply] `=> list: +Heap<T>(?cmp) Mut`: a claim this fn
        // **establishes** names its identity there and nowhere else, so the
        // deduction clause is a binder occurrence like a parameter type is —
        // without this the call site had nothing to substitute and the claim
        // reached the caller reading `Heap<Int>(?cmp)`, an identity naming the
        // callee's own binder.
        for d in f.deductions.iter().flatten() {
            let ast::DeductionKind::Exhaustive { reapplied, .. } = &d.kind else {
                continue;
            };
            let Some(param_name) = d.param_name() else { continue };
            let Some(param) = f
                .params
                .iter()
                .find(|p| p.name.name == param_name.name)
            else {
                continue;
            };
            let base = self.lower_type(&param.ty);
            for q in reapplied {
                let empty = HashMap::new();
                let quals = self.lower_quals(std::slice::from_ref(q), &empty, 0);
                let claimed = base.clone().qualify(quals);
                self.collect_binder_slots(&claimed, q.span, &mut captured);
            }
        }
        for (name, ty, span, slot) in captured {
            // An explicitly declared implicit of the same name *is* the
            // binding — the binder and the parameter are one thing, and what
            // resolution puts in it is what the result type publishes.
            // [implicit-same-name] …of the same name *and type*: one of
            // another type is a second implicit of that name.
            if let Some(written) = out.iter_mut().find(|o| o.name == name && same_fn_shape(&o.ty, &ty)) {
                written.binder = true;
                if written.slot.is_none() {
                    written.slot = slot;
                }
                continue;
            }
            out.push(ImplicitParam {
                local: name.clone(),
                name,
                ty,
                span,
                borrowed_arms: Vec::new(),
                binder: true,
                slot,
                bound: None,
            });
        }
        // [obligation-by] [implicit-group] Two spreads asking for the **same
        // position** ask for one parameter, not two: `?Eq<T>` beside
        // `?Hashed<T>` brings one `eq`, since `Hashed` carries the `eq` its
        // `hash` is confirmed by (user decision 2026-09-22). Merging is by name
        // *and* type — it is one function position, named once, so filling it
        // twice would be filling the same thing twice.
        //
        // A name clash at *different* types stays an error: with no binder
        // nothing tells those two apart, and [var-no-shadow] would refuse them
        // in the body anyway. The remedy is to write the ones that clash
        // individually under distinct names.
        // [implicit-same-name] A clash at *different* types is two parameters
        // (user decision 2026-09-28): `?to_str: (K) -> Str, ?to_str: (V) ->
        // Str`. The second and later are bound as `to_str__1`, …, and a call
        // in the body picks among them by its arguments.
        let mut merged: Vec<ImplicitParam> = Vec::with_capacity(out.len());
        for mut p in out {
            if let Some(kept) = merged.iter_mut().find(|q| q.name == p.name && same_fn_shape(&q.ty, &p.ty)) {
                // One position, so one parameter. A binder anywhere makes
                // the merged position a binder [cmp-binder].
                kept.binder = kept.binder || p.binder;
                continue;
            }
            let n = merged.iter().filter(|q| q.name == p.name).count();
            if n > 0 {
                p.local = format!("{}__{n}", p.name);
            }
            merged.push(p);
        }
        self.bind_implicits_together(f, &mut merged);
        merged
    }

    /// [implicit-with] Assigns the **fill-together components**: the connected
    /// classes of every `with` pair this signature is subject to (user decision
    /// 2026-09-26).
    ///
    /// Two sources, unioned — a function may *add* pairs and never remove them:
    ///
    ///  * the fn's own clause (`=> eq with hash`), and
    ///  * the clause of every `fns` group it **spreads**, because spreading a
    ///    group opts into its deductions along with its members. Declaring the
    ///    same functions *individually* is therefore how a signature takes them
    ///    unbound, which is what makes "never remove" cost nothing.
    ///
    /// Symmetric, so a pair is one undirected edge; transitive by the check, so
    /// the components are what matters rather than the pairs. A name that is not
    /// an implicit parameter of this signature is reported where it is written.
    fn bind_implicits_together(&mut self, f: &'p FnDecl, implicits: &mut [ImplicitParam]) {
        let mut edges: Vec<(&Ident, &Ident)> = Vec::new();
        let collect = |list: &'p [ast::Deduction], edges: &mut Vec<(&'p Ident, &'p Ident)>| {
            for d in list {
                let ast::DeductionKind::With { others } = &d.kind else {
                    continue;
                };
                let ast::DeductionTarget::Param { name, .. } = &d.target else {
                    continue;
                };
                // A chain is one component, so consecutive links are enough.
                let mut left = name;
                for right in others {
                    edges.push((left, right));
                    left = right;
                }
            }
        };
        if let Some(own) = &f.deductions {
            collect(own, &mut edges);
        }
        for g in &f.implicit_groups {
            if let Some(group) = self.named(g).group {
                collect(&group.deductions, &mut edges);
            }
        }
        if edges.is_empty() {
            return;
        }
        // Union-find over the parameter names, by index into `implicits`.
        let mut parent: Vec<usize> = (0..implicits.len()).collect();
        fn find(parent: &mut Vec<usize>, mut i: usize) -> usize {
            while parent[i] != i {
                parent[i] = parent[parent[i]];
                i = parent[i];
            }
            i
        }
        let mut joined = false;
        for (a, b) in edges {
            let ia = implicits.iter().position(|p| p.name == a.name);
            let ib = implicits.iter().position(|p| p.name == b.name);
            match (ia, ib) {
                (Some(ia), Some(ib)) => {
                    let (ra, rb) = (find(&mut parent, ia), find(&mut parent, ib));
                    if ra != rb {
                        parent[rb] = ra;
                    }
                    joined = true;
                }
                _ => {
                    // The clause names something this signature does not have.
                    // Reported where it is written, naming the side that is
                    // missing — a `with` over ordinary parameters is a mistake
                    // too, since only an implicit is *filled*.
                    let missing = if ia.is_none() { &a.name } else { &b.name };
                    let span = if ia.is_none() { a.span } else { b.span };
                    self.error(span, messages::implicit_with_not_implicit(&missing));
                }
            }
        }
        if !joined {
            return;
        }
        // Number the components that actually hold more than one member: a
        // singleton binds nothing.
        let mut ids: HashMap<usize, usize> = HashMap::new();
        let mut sizes: HashMap<usize, usize> = HashMap::new();
        for i in 0..implicits.len() {
            let root = find(&mut parent, i);
            *sizes.entry(root).or_insert(0) += 1;
        }
        for i in 0..implicits.len() {
            let root = find(&mut parent, i);
            if sizes.get(&root).copied().unwrap_or(0) < 2 {
                continue;
            }
            let next = ids.len();
            let id = *ids.entry(root).or_insert(next);
            implicits[i].bound = Some(id);
        }
    }

    /// The fn type a *declared* fn has as a value: parameters, result,
    /// effects, and the **contract** — what a call does to each argument
    /// [fn-contract]. Resolution needs the contract, because a fn that
    /// consumes an argument cannot fill a position that keeps it, and that
    /// difference does not show in a printed type.
    /// [implicit-group] The implicit parameters a fn's spread groups add,
    /// which its written list does not show: as a *value* the fn takes them
    /// like a written `?eq: …`, so it fits no position that does not pass
    /// them.
    fn group_member_params(&self, key: DeclId, decl: &FnDecl) -> Vec<Ty> {
        if decl.implicit_groups.is_empty() {
            return Vec::new();
        }
        let written: HashSet<&str> =
            decl.params.iter().filter(|p| p.implicit).map(|p| p.name.name.as_str()).collect();
        self.out
            .implicit_params
            .get(&key)
            .map(|imps| {
                imps.iter()
                    .filter(|i| !written.contains(i.name.as_str()))
                    .map(|i| i.ty.clone())
                    .collect()
            })
            .unwrap_or_default()
    }

    /// [fn-value] A declared function's own type as a value, every parameter
    /// included (written implicits and a spread group's members too), its
    /// return as a call sees it — the claim a constructor gains (`-> +Valid
    /// Range`), through [`Self::fn_return_ty`] — its contract and its effects. What a position
    /// makes of it is [`Self::fn_value_at`].
    fn fn_value_ty(&mut self, key: DeclId, decl: &'p FnDecl) -> Ty {
        let saved = self.enter_generics(&decl.generics);
        let mut params: Vec<Ty> = decl.params.iter().map(|p| self.lower_type(&p.ty)).collect();
        let ret = self.fn_return_ty(decl);
        self.generics = saved;
        // [implicit-group] A spread group's members are implicit parameters
        // the written list does not show; as a value the fn takes them like a
        // written `?eq: …`, so it fits no position that does not pass them.
        if !self.resolve_as_call {
            params.extend(self.group_member_params(key, decl));
        }
        let facts: Option<Vec<crate::deduce::ParamDeduction>> =
            self.effective_contract(Some(key), decl);
        let contract = facts.map(|facts| {
            decl.params
                .iter()
                .zip(&params)
                .map(|(p, pty)| {
                    let entry = facts.iter().find(|d| d.param == p.name.name);
                    FnParamContract {
                        name: Some(p.name.name.clone()),
                        kept: entry.map(|d| d.kept).unwrap_or(true),
                        effect: entry
                            .map(|d| d.effect.clone())
                            .unwrap_or(QualEffect::KeepAll),
                        mutable: pty.quals().iter().any(|q| q.name == "Mut"),
                        lent: entry.is_some_and(|d| d.lent),
                    }
                })
                .collect()
        });
        let effects = self.out.fn_effects.get(&key).cloned().unwrap_or_default();
        Ty::Fn {
            params,
            ret: Box::new(ret),
            contract,
            effects,
        }
    }

    /// [fn-value] A declared function as a value **at the fn type `want`**:
    /// one rule for a function passed by name and for one filling an
    /// implicit, which differ only in how the candidate is selected (user
    /// decision 2026-10-20: "implicits should just be lambdas which are
    /// automatically selected"). Before, the two built the value's type
    /// separately and disagreed — an implicit lost the claim its candidate's
    /// return gains, so `validate(o) -> +Valid Range` did not fill
    /// `?validate: (o: Range) -> Valid Range`, while passing it by name did;
    /// and a function with implicits of its own could fill an implicit but
    /// not be passed by name.
    ///
    /// The value's shape is the function's explicit parameters, with its own
    /// implicits filled in turn [implicit-recursive]; failing that, every
    /// parameter, for a position that passes the implicits itself. Its
    /// generics bind from `want`, and the contract has to fit as well as the
    /// types [fn-contract]. The fit is [`Self::fn_value_fit`], which is what
    /// selection compares; the fill happens here, for the one selected. A
    /// miss is ranked for the diagnostic: 2 for the wrong number of
    /// parameters, 1 for types that do not match, 0 for what a printed type
    /// cannot show (a contract, an implicit that cannot be filled).
    fn fn_value_at(&mut self, key: DeclId, decl: &'p FnDecl, want: &Ty) -> Result<FnValueAt, (u8, String)> {
        let fit = self.fn_value_fit(key, decl, want)?;
        let mut nested = Vec::new();
        if fit.fills && !self.resolve_as_call {
            nested = self
                .try_nested(key, decl, &fit.binding, &fit.generics, want)
                .map_err(|u| (0, Self::unfilled_text(&decl.name.name, want, &u, false)))?;
        }
        Ok(FnValueAt { ty: fit.ty, nested, binding: fit.binding })
    }

    /// [fn-value] [implicit-resolve] Whether a declared function **fits** the
    /// fn type `want` — by its type and its contract alone, its own implicits
    /// *not* filled: a candidate is chosen without regard to them, exactly as
    /// a call's are (user decision 2026-10-14), and only the winner's are
    /// filled [implicit-recursive]. Misses ranked as [`Self::fn_value_at`]'s.
    fn fn_value_fit(&mut self, key: DeclId, decl: &'p FnDecl, want: &Ty) -> Result<FnFit, (u8, String)> {
        if !matches!(want.strip_quals(), Ty::Fn { .. }) {
            return Err((2, format!("the position for `{}` is not a function type", decl.name.name)));
        }
        let full = self.fn_value_ty(key, decl);
        let generics: HashSet<String> = decl.generics.iter().map(|g| g.name.clone()).collect();
        self.value_fit(decl, full, generics, want)
    }

    /// [fn-value] [effect-member-overload] [`Self::fn_value_fit`] for an
    /// available effect's member (R10 D3): its signature with the instance's
    /// type arguments in place of the effect's generics, fitted by the same
    /// rule. The value it makes carries the instance, so the position's
    /// effects are not asked of it.
    fn member_value_fit(&mut self, m: &MemberCand<'p>, want: &Ty) -> Result<FnFit, (u8, String)> {
        if !matches!(want.strip_quals(), Ty::Fn { .. }) {
            return Err((2, format!("the position for `{}` is not a function type", m.decl.name.name)));
        }
        let (full, _) = self.member_value_ty(m);
        let generics: HashSet<String> = m.decl.generics.iter().map(|g| g.name.clone()).collect();
        self.value_fit(m.decl, full, generics, want)
    }

    /// [effect-member-overload] A member's type as a value at its instance —
    /// every parameter, its written contract — and its implicit parameters,
    /// both with the effect's generics bound by the instance's arguments.
    fn member_value_ty(&mut self, m: &MemberCand<'p>) -> (Ty, Vec<ImplicitParam>) {
        let saved = self.enter_generics(&m.effect.generics);
        self.enter_generics(&m.decl.generics);
        let full = self.member_fn_ty(m.decl);
        let before = self.out.errors.len();
        let implicits = self.collect_implicits(m.decl);
        self.out.errors.truncate(before);
        self.generics = saved;
        let (bind, names) = Self::instance_binding(m);
        let implicits: Vec<ImplicitParam> = implicits
            .into_iter()
            .map(|mut i| {
                i.ty = substitute_known(&i.ty, &bind, &names);
                i
            })
            .collect();
        let mut full = substitute_known(&full, &bind, &names);
        // [implicit-group] A spread group's members, past the written list,
        // as `fn_value_ty` appends them for a fn.
        let written = m.decl.params.iter().filter(|p| p.implicit).count();
        if let Ty::Fn { params, .. } = &mut full {
            params.extend(implicits.iter().skip(written).map(|i| i.ty.clone()));
        }
        (full, implicits)
    }

    /// The effect's generics bound by a member candidate's instance.
    fn instance_binding(m: &MemberCand<'p>) -> (HashMap<String, Ty>, HashSet<String>) {
        let names: HashSet<String> = m.effect.generics.iter().map(|g| g.name.clone()).collect();
        let bind: HashMap<String, Ty> = match &m.instance {
            Ty::Named { args, .. } => m.effect.generics.iter().map(|g| g.name.clone()).zip(args.iter().cloned()).collect(),
            _ => HashMap::new(),
        };
        (bind, names)
    }

    /// The fit itself, of a declaration whose value type is `full`.
    fn value_fit(&mut self, decl: &'p FnDecl, full: Ty, generics: HashSet<String>, want: &Ty) -> Result<FnFit, (u8, String)> {
        let name = decl.name.name.clone();
        let Ty::Fn { params: want_params, ret: want_ret, .. } = want.strip_quals().clone() else {
            return Err((2, format!("the position for `{name}` is not a function type")));
        };
        let Ty::Fn { params: all, ret, contract, effects } = full.clone() else {
            return Err((2, format!("`{name}` is not a function")));
        };
        // The explicit shape: written implicits and a spread group's members
        // are dropped (`fn_value_ty` appends the members after the written
        // list, so everything past it goes).
        let keep: Vec<usize> = decl.params.iter().enumerate().filter(|(_, p)| !p.implicit).map(|(i, _)| i).collect();
        let has_imps = keep.len() < all.len();
        let explicit = Ty::Fn {
            params: keep.iter().map(|&i| all[i].clone()).collect(),
            ret: ret.clone(),
            contract: contract.clone().map(|c| keep.iter().filter_map(|&i| c.get(i).cloned()).collect()),
            effects: effects.clone(),
        };
        let shapes: Vec<(Ty, bool)> = if has_imps { vec![(explicit, true), (full, false)] } else { vec![(full, false)] };
        let mut best: Option<(u8, String)> = None;
        let miss = |rank: u8, reason: String, best: &mut Option<(u8, String)>| {
            if best.as_ref().is_none_or(|(r, _)| rank < *r) {
                *best = Some((rank, reason));
            }
        };
        for (shape, fills) in shapes {
            let Ty::Fn { params: have, ret: have_ret, .. } = &shape else { continue };
            if have.len() != want_params.len() {
                miss(
                    2,
                    format!("the `{name}` in scope takes {} argument(s), but the position needs {}", have.len(), want_params.len()),
                    &mut best,
                );
                continue;
            }
            // The candidate's own generics bind from the position, so a
            // universal `fn cmp<T>(a: T, b: T) -> Int` is compared as
            // instantiated.
            let mut binding: HashMap<String, Ty> = HashMap::new();
            let matched = have.iter().zip(&want_params).all(|(h, w)| unify(h, w, &mut binding)) && unify(have_ret, &want_ret, &mut binding);
            if !matched {
                miss(1, format!("the `{name}` in scope is `{shape}`, and the position needs `{want}`"), &mut best);
                continue;
            }
            let candidate = if generics.is_empty() { shape.clone() } else { substitute_vars(&shape, &binding, &generics) };
            // [implicit-infer] Fitted for inference, the callee's open
            // variables are what the candidate makes of them: read off it,
            // then the fit is checked at the position they make (R10 D22).
            let open_want = match &self.infer_open {
                Some((pattern, vars)) => match infer_read_back(pattern, &candidate, &HashMap::new()) {
                    Some(learned) => Some(substitute_vars(pattern, &learned, vars)),
                    None => {
                        miss(1, format!("the `{name}` in scope is `{candidate}`, and the position needs `{want}`"), &mut best);
                        continue;
                    }
                },
                None => None,
            };
            let want = open_want.as_ref().unwrap_or(want);
            if !fn_value_fits(&candidate, want) {
                let reason = self
                    .fn_fit_reason(want, &candidate, &name)
                    .unwrap_or_else(|| format!("the `{name}` in scope is `{candidate}`, and the position needs `{want}`"));
                miss(0, reason, &mut best);
                continue;
            }
            return Ok(FnFit {
                ty: candidate,
                binding,
                generics,
                fills,
                passes_own: has_imps && !fills,
                patterns: have.clone(),
                variadic: decl.params.iter().any(|p| p.variadic),
            });
        }
        Err(best.unwrap_or_else(|| (2, format!("`{name}` does not fit `{want}`"))))
    }

    /// The fn type of a `fns` group member (or any bodiless signature),
    /// as a value of that type would have.
    fn member_fn_ty(&mut self, member: &'p FnDecl) -> Ty {
        let params: Vec<Ty> = member
            .params
            .iter()
            .map(|p| self.lower_type(&p.ty))
            .collect();
        let ret = member
            .return_type
            .as_ref()
            .map(|t| self.lower_type(t))
            .unwrap_or_else(Ty::none);
        // [fn-contract] [implicit-group] The member's own deduction list is
        // its contract, exactly as a declared fn's is. Without
        // it every parameter read as kept-and-immutable, so a member
        // declared `fn next(it: Mut It) -> [it: Mut] …` could not be filled
        // by any implementation — the supplied fn mutates, the position
        // (silently) did not permit it. That is `fns Next`'s shape, so
        // the whole composition rendering depended on this.
        let facts: Option<Vec<crate::deduce::ParamDeduction>> = member
            .deductions
            .as_ref()
            .map(|list| crate::deduce::from_written(member, list, &HashSet::new(), |_, _| {}));
        // [proj-infer-fn-type] [iter-group] A member whose return is
        // **opaque** — a type parameter of the group that no parameter
        // mentions, like `Iter`'s `iter(collection: C) -> Mut It`, which
        // stands for whichever iterator struct the filler mints and may hold
        // a borrow of the source — lends every kept parameter, as a written fn
        // type with an opaque return does. Without it `?Iter<C, It, T>`'s
        // `iter` rendered a `FnMut(&C) -> It` with no lifetime tying the two,
        // and rustc refused the fill.
        let opaque_ret = match ret.strip_quals() {
            Ty::Var(g) => self.generics.contains(g) && !params.iter().any(|p| ty_mentions_var(p, g)),
            _ => false,
        };
        let contract = if facts.is_some() || opaque_ret {
            let facts = facts.unwrap_or_default();
            Some(
                member
                    .params
                    .iter()
                    .zip(&params)
                    .map(|(p, pty)| {
                        let entry = facts.iter().find(|d| d.param == p.name.name);
                        let kept = entry.map(|d| d.kept).unwrap_or(true);
                        FnParamContract {
                            name: Some(p.name.name.clone()),
                            kept,
                            effect: entry
                                .map(|d| d.effect.clone())
                                .unwrap_or(QualEffect::KeepAll),
                            mutable: pty.quals().iter().any(|q| q.name == "Mut"),
                            lent: entry.is_some_and(|d| d.lent) || (opaque_ret && kept),
                        }
                    })
                    .collect(),
            )
        } else {
            None
        };
        Ty::Fn {
            params,
            ret: Box::new(ret),
            contract,
            effects: Vec::new(),
        }
    }

    /// Fills a call's implicit parameters [implicit-resolve], in order:
    ///
    /// 1. `name = value` written at the call site [implicit-override];
    /// 2. an implicit parameter of the *enclosing* fn with the same name and
    ///    a matching type — forwarding, which is the only possibility inside
    ///    generic code, where nothing about an opaque `T` is knowable
    ///    [implicit-forward] [call-resolve];
    /// 3. a declared fn of that name whose signature matches the required
    ///    type — the same overload query the language already runs, only
    ///    against a type instead of an argument list [fn-overload];
    /// 4. otherwise an error naming both remedies.
    fn resolve_implicits(
        &mut self,
        decl: &'p FnDecl,
        key: Option<DeclId>,
        subst: &mut HashMap<String, Ty>,
        callee_generics: &HashSet<String>,
        named: &'p [ast::NamedArg],
        span: Span,
    ) {
        let Some(key) = key else { return };
        let implicits = self
            .out
            .implicit_params
            .get(&key)
            .cloned()
            .unwrap_or_default();
        self.fill_implicits(
            &implicits,
            &decl.name.name,
            subst,
            callee_generics,
            named,
            span,
        );
    }

    /// Fills a known list of implicit parameters at one call site — the
    /// shared half of [implicit-resolve], used for both a fn and an effect
    /// member, which is an ordinary signature that happens to be dispatched
    /// through a handler.
    fn fill_implicits(
        &mut self,
        implicits: &[ImplicitParam],
        callee: &str,
        subst: &mut HashMap<String, Ty>,
        callee_generics: &HashSet<String>,
        named: &'p [ast::NamedArg],
        span: Span,
    ) {
        let at = self.key(span);
        self.fill_implicits_keyed(implicits, callee, subst, callee_generics, named, span, at);
    }

    /// [`Checker::fill_implicits`], recorded at `at`.
    #[allow(clippy::too_many_arguments)]
    fn fill_implicits_keyed(
        &mut self,
        implicits: &[ImplicitParam],
        callee: &str,
        subst: &mut HashMap<String, Ty>,
        callee_generics: &HashSet<String>,
        named: &'p [ast::NamedArg],
        span: Span,
        at: Key,
    ) {
        if let Some(filled) = self.fill_implicit_list(implicits, callee, subst, callee_generics, named, span) {
            self.out.implicit_args.insert(at, filled);
        }
    }

    /// [implicit-resolve] The filling itself: one [`ImplicitArg`] per
    /// parameter, or `None` after a refusal that was reported. A nested fill
    /// [implicit-recursive] is this with no named arguments.
    fn fill_implicit_list(
        &mut self,
        implicits: &[ImplicitParam],
        callee: &str,
        subst: &mut HashMap<String, Ty>,
        callee_generics: &HashSet<String>,
        named: &'p [ast::NamedArg],
        span: Span,
    ) -> Option<Vec<ImplicitArg>> {
        if implicits.is_empty() {
            for arg in named {
                // [fn-param-default] A name that fills an ordinary defaulted
                // parameter is this call's, handled on the fn path — not an
                // unknown implicit.
                if self.call_fixed_params.contains(&arg.name.name) {
                    continue;
                }
                self.error(
                    arg.span,
                    messages::implicit_override_no_implicit(&callee, &arg.name.name),
                );
            }
            return Some(Vec::new());
        }
        let mut filled: Vec<ImplicitArg> = Vec::new();
        // [implicit-same-name] A bare `name = f` cannot say which of two
        // implicits of one name it fills; the typed override spelling
        // (`to_str: (V) -> Str = f`, decided 2026-09-28) is not built yet.
        for arg in named {
            if implicits.iter().filter(|p| p.name == arg.name.name).count() > 1 {
                self.error(
                    arg.span,
                    messages::implicit_same_name_override(&callee, &arg.name.name),
                );
                return None;
            }
        }
        // [implicit-with] Where each **bound** parameter's value came from, for
        // the one-source check below.
        let mut sources: Vec<(usize, &str, &'static str)> = Vec::new();
        for imp in implicits {
            // The type as this call needs it, with the callee's type
            // arguments substituted in.
            let want = substitute_vars(&imp.ty, subst, callee_generics);
            let Some((arg, identity)) =
                self.fill_one_implicit(imp, callee, &want, named, subst, span)
            else {
                continue;
            };
            if let Some(component) = imp.bound {
                sources.push((
                    component,
                    imp.name.as_str(),
                    match &arg {
                        ImplicitArg::Given { .. } => "written here",
                        ImplicitArg::Forwarded { .. } => "forwarded from this function",
                        ImplicitArg::Resolved { .. } | ImplicitArg::OriginNext { .. } | ImplicitArg::Member { .. } => {
                            "resolved by name"
                        }
                    },
                ));
            }
            let filled_arg = arg.clone();
            // [cmp-binder] What filled a **binder** becomes part of the call's
            // type: `empty_heap(…)` answers `Heap(cmp@Person) Mut List<Person>`
            // because the identity resolution chose is substituted into the
            // result. A binder already bound — captured from an argument — keeps
            // what it was bound to.
            if imp.binder {
                let key = FnId::subst_key(&imp.name);
                if let (false, Some(id)) = (subst.contains_key(&key), identity.clone()) {
                    subst.insert(key, Ty::FnName(id));
                }
                // [cmp-carry] A **container** keyed by what filled the binder
                // needs the declaration behind the name, not only the name: the
                // Rust backend generates a marker that calls it, and the Kotlin
                // one a closure. A written type records this already
                // (`record_carried_identities`); a slot filled by resolution —
                // which is how every keyed constructor fills it since the
                // capability landed (2026-09-25) — is recorded here.
                if let (Some(id), Some(Ty::Fn { params, .. })) =
                    (identity, Some(want.strip_quals().clone()))
                {
                    if let Some(subject) = params.first() {
                        let ckey = (self.file_idx, id.clone(), subject.strip_quals().clone());
                        match &filled_arg {
                            ImplicitArg::Resolved { key: fkey, .. } => {
                                self.out.carried_identities.entry(ckey).or_insert(*fkey);
                            }
                            // [cmp-carry] A slot **written at the call site**
                            // (`Mut Set(eq = same_age)`) carries its identity
                            // exactly as a resolved one does: the name published
                            // into the binder is a declaration, and a container
                            // needs the declaration behind it. Without this the
                            // written slot reached neither backend — Kotlin
                            // silently dropped it and Rust could not name it
                            // (fixed 2026-09-26, user decision: **honour a mixed
                            // fill**; a group is a convenience, not a contract).
                            ImplicitArg::Given { .. } => {
                                if let Ok((fkey, _)) = self.resolve_identity(&id, &want) {
                                    self.out.carried_identities.entry(ckey).or_insert(fkey);
                                }
                            }
                            _ => {}
                        }
                    }
                }
            }
            filled.push(arg);
        }
        // A named argument matching no implicit parameter is a mistake, not
        // a silent no-op — unless it fills an ordinary defaulted parameter
        // of this call [fn-param-default].
        for arg in named {
            if !implicits.iter().any(|p| p.name == arg.name.name)
                && !self.call_fixed_params.contains(&arg.name.name)
            {
                self.error(
                    arg.span,
                    messages::implicit_override_no_implicit(&callee, &arg.name.name),
                );
            }
        }
        // [implicit-with] **One source per component** (user decision
        // 2026-09-26): the members of a fill-together component are one
        // decision, so they arrive all written, all forwarded, or all resolved.
        // Mixing them is how an unchecked pair gets built — a hash a caller
        // chose beside an equality resolution found, with nothing saying the two
        // agree — and the fix is always to *write them out*, which is why the
        // diagnostic says so.
        let mut components: Vec<usize> = sources.iter().map(|(c, _, _)| *c).collect();
        components.sort_unstable();
        components.dedup();
        for component in components {
            let members: Vec<(&str, &'static str)> = sources
                .iter()
                .filter(|(c, _, _)| *c == component)
                .map(|(_, name, src)| (*name, *src))
                .collect();
            let mut kinds: Vec<&'static str> = members.iter().map(|(_, s)| *s).collect();
            kinds.sort_unstable();
            kinds.dedup();
            if kinds.len() < 2 {
                continue;
            }
            let shown: Vec<String> = members
                .iter()
                .map(|(name, src)| format!("`{name}` is {src}"))
                .collect();
            let names: Vec<String> = members.iter().map(|(n, _)| format!("{n} = …")).collect();
            let all: Vec<String> = members.iter().map(|(n, _)| format!("`{n}`")).collect();
            // The remedy is **writing them out**, except where one member is a
            // capability this function was handed: a container's identity has to
            // be a name a type can carry [cmp-carry], and an implicit parameter
            // is not one — so there the fix is to hold the whole pair and let
            // every member forward.
            let forwarded: Vec<&str> = members
                .iter()
                .filter(|(_, src)| *src == "forwarded from this function")
                .map(|(n, _)| *n)
                .collect();
            let remedy = if forwarded.is_empty() {
                format!(
                    "Write them out at the call (`{callee}(…, {})`), so the \
                     agreement between them is stated rather than assembled",
                    names.join(", ")
                )
            } else {
                format!(
                    "Either declare the rest of them too, so every one is \
                     forwarded from here — which is what spreading the whole \
                     group does — or write them all out at the call \
                     (`{callee}(…, {})`); {} cannot be written out, being a \
                     capability this function was handed rather than a name",
                    names.join(", "),
                    join_and(
                        &forwarded
                            .iter()
                            .map(|n| format!("`{n}`"))
                            .collect::<Vec<_>>()
                    )
                )
            };
            self.error(
                span,
                messages::implicit_with_different_places(
                    &join_and(&all),
                    &callee,
                    &shown.join(" and "),
                    &remedy,
                ),
            );
        }
        Some(filled)
    }

    /// One implicit parameter, filled [implicit-resolve] — `None` when
    /// nothing fits, which is reported here.
    /// [implicit-fit] The first implicit of fn [key] that nothing at this
    /// call could fill — no named argument, no forwarded implicit, no visible
    /// fn of that name and type — rendered `?name: type`; `None` when all
    /// can be. Reports nothing.
    fn unfillable_implicit(
        &mut self,
        key: DeclId,
        generics: &[ast::Ident],
        subst: &HashMap<String, Ty>,
        named: &'p [ast::NamedArg],
    ) -> Option<String> {
        let implicits = self.out.implicit_params.get(&key).cloned().unwrap_or_default();
        let callee_generics: HashSet<String> = generics.iter().map(|g| g.name.clone()).collect();
        // What the implicits themselves determine first, as the call does
        // [implicit-infer]: `T` from `next`'s answer.
        let mut subst = subst.clone();
        self.extend_subst_from_implicits(Some(key), &callee_generics, &mut subst, named);
        self.unfillable_named(&implicits, &callee_generics, &subst, named)
    }

    /// [implicit-fit] [`Self::unfillable_implicit`] over a known list, its
    /// type variables bound as far as `subst` says: an effect member's (R10
    /// D3), whose implicits are not keyed by a `DeclId`.
    fn unfillable_in(&mut self, implicits: &[ImplicitParam], callee_generics: &HashSet<String>, subst: &HashMap<String, Ty>) -> Option<String> {
        self.unfillable_named(implicits, callee_generics, subst, &[])
    }

    fn unfillable_named(
        &mut self,
        implicits: &[ImplicitParam],
        callee_generics: &HashSet<String>,
        subst: &HashMap<String, Ty>,
        named: &[ast::NamedArg],
    ) -> Option<String> {
        for imp in implicits {
            if imp.binder || named.iter().any(|a| a.name.name == imp.name) {
                continue;
            }
            let want = substitute_vars(&imp.ty, subst, callee_generics);
            // The same substitution the fill below uses, so the probe answers
            // what the fill would.
            if ty_mentions_vars(&want, callee_generics) {
                continue;
            }
            if self.own_implicits.iter().any(|p| p.name == imp.name) {
                continue;
            }
            if !self.some_fn_accepts(&imp.name, &want) {
                return Some(format!("?{}: {want}", imp.name));
            }
        }
        None
    }

    /// [implicit-fit] Whether some visible fn named [name] takes the
    /// parameters of the fn type [want] — by shape only: its answer may not be
    /// known yet at ranking, and an answer that does not fit is reported by
    /// the fill as before.
    fn some_fn_accepts(&mut self, name: &str, want: &Ty) -> bool {
        let Ty::Fn { params: want_params, .. } = want.strip_quals() else {
            return true;
        };
        let want_params = want_params.clone();
        for entry in self.overloads_of(name) {
            let decl = entry.decl;
            let fixed: Vec<&ast::Param> = decl.params.iter().filter(|p| !p.implicit).collect();
            if fixed.len() != want_params.len() {
                continue;
            }
            let saved = self.enter_generics(&decl.generics);
            let have: Vec<Ty> = fixed.iter().map(|p| self.lower_type(&p.ty)).collect();
            self.generics = saved;
            let mut binding: HashMap<String, Ty> = HashMap::new();
            if have.iter().zip(&want_params).all(|(h, w)| unify(h, w, &mut binding)) {
                return true;
            }
        }
        // [effect-member-overload] An available effect's member fills an
        // implicit position too (R10 D3), so it answers this probe as well.
        for m in self.available_members(name) {
            let (full, _) = self.member_value_ty(&m);
            let Ty::Fn { params, .. } = full else { continue };
            let fixed: Vec<&Ty> = m.decl.params.iter().zip(&params).filter(|(p, _)| !p.implicit).map(|(_, t)| t).collect();
            if fixed.len() != want_params.len() {
                continue;
            }
            let mut binding: HashMap<String, Ty> = HashMap::new();
            if fixed.iter().zip(&want_params).all(|(h, w)| unify(h, w, &mut binding)) {
                return true;
            }
        }
        false
    }

    /// [implicit-same-name] Among the enclosing fn's own implicits named
    /// `name` that `fits` accepts, the most specific, ranked like overloads
    /// by their parameter types [fn-overload-rank] (R10 D21): `Ok(None)` when
    /// none fits, `Err` with the tied ones' types when no single one is most
    /// specific.
    fn pick_own_implicit(&self, name: &str, fits: &dyn Fn(&ImplicitParam) -> bool) -> Result<Option<ImplicitParam>, Vec<Ty>> {
        self.pick_own_implicit_by(&|p: &ImplicitParam| p.name == name, fits)
    }

    /// [`Checker::pick_own_implicit`] among the implicits `named` accepts:
    /// a comparison operator asks by name or by the slot a binder alias fills
    /// [cmp-binder].
    fn pick_own_implicit_by(
        &self,
        named: &dyn Fn(&ImplicitParam) -> bool,
        fits: &dyn Fn(&ImplicitParam) -> bool,
    ) -> Result<Option<ImplicitParam>, Vec<Ty>> {
        let fitting: Vec<&ImplicitParam> = self.own_implicits.iter().filter(|p| named(p) && fits(p)).collect();
        match fitting.len() {
            0 => return Ok(None),
            1 => return Ok(Some(fitting[0].clone())),
            _ => {}
        }
        let ranks: Vec<crate::types::RankedCandidate> = fitting
            .iter()
            .map(|p| crate::types::RankedCandidate {
                patterns: match p.ty.strip_quals() {
                    Ty::Fn { params, .. } => params.clone(),
                    _ => Vec::new(),
                },
                variadic: false,
            })
            .collect();
        match crate::types::most_specific(&ranks) {
            Some(i) => Ok(Some(fitting[i].clone())),
            None => Err(fitting.iter().map(|p| p.ty.clone()).collect()),
        }
    }

    /// [implicit-same-name] Two of the enclosing fn's implicits of `name`
    /// fit and neither is more specific (R10 D21): the ordinary ambiguity.
    fn own_implicit_tie(&mut self, name: &str, tied: &[Ty], span: Span) {
        let shown: Vec<String> = tied.iter().map(|t| format!("`{t}`")).collect();
        self.error(span, messages::implicit_same_name_ambiguous(&name, &shown.join(" and ")));
    }

    /// [effect-member-overload] [effect-available] The members named `name`
    /// of every effect with an instance available here, one candidate per
    /// member and instance (R10 D3: an effect's members are functions in the
    /// declaring fn's scope, so they fill implicit positions as fns do). A
    /// `send` member is not a value [actor-free-send-fn], and the throw effect has
    /// no handler to carry.
    fn available_members(&self, name: &str) -> Vec<MemberCand<'p>> {
        let mut out: Vec<MemberCand<'p>> = Vec::new();
        for instance in self.visible_effects() {
            let Ty::Named { name: key, .. } = &instance else { continue };
            let Some(effect) = self.symbols.effects.get(key.as_str()).copied() else { continue };
            if effect.name.name == THROW_EFFECT {
                continue;
            }
            for (index, f) in effect.fns.iter().enumerate() {
                if f.name.name != name || f.is_send || self.shape_refused(f) {
                    continue;
                }
                if out.iter().any(|m| std::ptr::eq(m.decl, f) && m.instance == instance) {
                    continue;
                }
                out.push(MemberCand { effect, decl: f, index, instance: instance.clone() });
            }
        }
        out
    }

    /// [implicit-resolve] The candidates for an implicit position named
    /// `name`: the visible fns of the name [fn-rename], and — unless the
    /// position is a binder, whose fill is an identity a type carries and so
    /// a top-level fn [cmp-carry] — the available effects' members of it
    /// (R10 D3).
    fn implicit_candidates(&self, name: &str, members: bool) -> Vec<ValueCand<'p>> {
        let mut out: Vec<ValueCand<'p>> = self.overloads_of(name).into_iter().map(ValueCand::Fn).collect();
        if members {
            out.extend(self.available_members(name).into_iter().map(ValueCand::Member));
        }
        out
    }

    /// [implicit-resolve] An implicit position filled by name at the call
    /// site — the call's rule over the visible fns and the available
    /// effects' members as one set (R10 D3) — and, for the winner only, its
    /// own implicits [implicit-recursive].
    fn resolve_implicit_value(&mut self, name: &str, want: &Ty, members: bool) -> Result<Filled<'p>, ImplicitMiss> {
        if !members || self.available_members(name).is_empty() {
            return self.resolve_implicit_fn_at(name, None, want).map(|(k, id)| Filled::Fn(k, id));
        }
        if !matches!(want.strip_quals(), Ty::Fn { .. }) {
            return Err(ImplicitMiss::Unknown);
        }
        let entries = self.implicit_candidates(name, true);
        let (cand, fit) = self.select_fn_value(name, entries, want)?;
        match cand {
            ValueCand::Fn(entry) => {
                let identity = self.identity_of(entry.key, entry.decl);
                let mut nested = Vec::new();
                if fit.fills && !self.resolve_as_call {
                    match self.try_nested(entry.key, entry.decl, &fit.binding, &fit.generics, want) {
                        Ok(n) => nested = n,
                        Err(reason) => return Err(ImplicitMiss::Unfilled(reason)),
                    }
                }
                self.last_nested = nested;
                Ok(Filled::Fn(entry.key, identity))
            }
            ValueCand::Member(m) => {
                let mut nested = Vec::new();
                if fit.fills {
                    let (_, implicits) = self.member_value_ty(&m);
                    let (mut binding, mut generics) = Self::instance_binding(&m);
                    binding.extend(fit.binding.clone());
                    generics.extend(fit.generics.iter().cloned());
                    match self.try_nested_list(m.decl, &implicits, &binding, &generics, want) {
                        Ok(n) => nested = n,
                        Err(reason) => return Err(ImplicitMiss::Unfilled(reason)),
                    }
                }
                Ok(Filled::Member(m, nested))
            }
        }
    }

    fn fill_one_implicit(
        &mut self,
        imp: &ImplicitParam,
        callee: &str,
        want: &Ty,
        named: &'p [ast::NamedArg],
        subst: &HashMap<String, Ty>,
        span: Span,
    ) -> Option<(ImplicitArg, Option<FnId>)> {
        let want = want.clone();
        {
            // 0. [cmp-binder] The identity the argument *types* carry. A binder
            // bound by unification is the answer before any resolution by
            // name: what the structure was built with, not what happens to be
            // visible at this call site — which is the hazard
            // [implicit-resolve]'s locality would otherwise leave open.
            if imp.binder {
                if let Some(Ty::FnName(id)) = subst.get(&FnId::subst_key(&imp.name)).cloned() {
                    match &id {
                        // The caller's own binder, forwarded [implicit-forward].
                        FnId::Binder(b) => {
                            // [implicit-same-name] The most specific of the
                            // name whose type fits (R10 D21), else the one there is.
                            let fits = |p: &ImplicitParam| is_subtype(&p.ty, &want) || p.ty.is_unknown() || want.is_unknown();
                            let own = match self.pick_own_implicit(b, &fits) {
                                Ok(Some(own)) => Some(own),
                                Ok(None) => self.own_implicits.iter().find(|p| p.name == *b).cloned(),
                                Err(tied) => {
                                    self.own_implicit_tie(b, &tied, span);
                                    return None;
                                }
                            };
                            if let Some(own) = own {
                                // [cmp-carry-override] Written as well, it must
                                // be the binder itself: any other value is one
                                // this call cannot show agrees with it.
                                if let Some(arg) = named.iter().find(|a| a.name.name == imp.name) {
                                    self.check_expr(&arg.value, Some(&want));
                                    let same = matches!(&arg.value, Expr::Ident(v) if v.name == own.local);
                                    if !same {
                                        self.error(
                                            arg.span,
                                            messages::cmp_carry_override_disagrees(&callee, &imp.name, &own.local),
                                        );
                                    }
                                }
                                return Some((ImplicitArg::Forwarded { name: own.local.clone() }, None));
                            }
                        }
                        FnId::Named { .. } => {
                            match self.resolve_identity(&id, &want) {
                                Ok((key, _)) => {
                                    // [cmp-carry-override] (user decision open,
                                    // PIPELINE §II.10) A value written for a
                                    // binder the arguments already carry is
                                    // checked like any override, and must
                                    // name the same declaration: the
                                    // structure was built with the carried
                                    // one, so another would silently break
                                    // its invariants.
                                    let nested = std::mem::take(&mut self.last_nested);
                                    if let Some(arg) = named.iter().find(|a| a.name.name == imp.name) {
                                        self.check_expr(&arg.value, Some(&want));
                                        let at = match &arg.value {
                                            Expr::Ident(v) if self.lookup(&v.name).is_none() => Some(v.span),
                                            // `cmp@Person`: a type's attached fn
                                            // [fn-attached] (a member records none).
                                            Expr::Scoped { base: None, name, .. } | Expr::EffectScoped { base: None, name, .. } => Some(name.span),
                                            _ => None,
                                        };
                                        let written = at.and_then(|s| self.out.fn_refs.get(&self.key(s)).copied());
                                        if written != Some(key) {
                                            self.error(
                                                arg.span,
                                                messages::cmp_carry_override_disagrees(&callee, &imp.name, &id),
                                            );
                                        }
                                    }
                                    return Some((
                                        ImplicitArg::Resolved {
                                            name: imp.name.clone(),
                                            key,
                                            // [implicit-recursive] Its own implicits
                                            // are filled where it is used.
                                            nested,
                                            want: want.clone(),
                                        },
                                        None,
                                    ))
                                }
                                Err(_) => {
                                    self.error(
                                        span,
                                        messages::cmp_carry_carried_mismatch(
                                            &callee,
                                            &imp.name,
                                            &id,
                                            &want,
                                        ),
                                    );
                                    return None;
                                }
                            }
                        }
                    }
                }
            }
            // 1. Written at the call site.
            if let Some(arg) = named.iter().find(|a| a.name.name == imp.name) {
                let got = self.check_expr(&arg.value, Some(&want));
                // The fit resolution uses [implicit-resolve]: a fn reading a
                // borrow of a parameter fits a position passing it, as when
                // the same fn is found by name ([fn-kept-borrow]: the
                // backends adapt the convention) — and nothing else is
                // relaxed: a difference a backend renders (`Mut`) still does
                // not fit [fn-erased-variance].
                let fits = |got: &Ty, want: &Ty| {
                    let read = match got.strip_quals() {
                        Ty::Fn { params, ret, contract, effects } => Ty::Fn {
                            params: params
                                .iter()
                                .map(|p| {
                                    let proj = p.quals().iter().any(|q| crate::types::is_proj_name(&q.name));
                                    if proj && !matches!(p.strip_quals(), Ty::Union(_)) {
                                        p.clone().remove_quals(&crate::types::proj_names())
                                    } else {
                                        p.clone()
                                    }
                                })
                                .collect(),
                            ret: ret.clone(),
                            contract: contract.clone(),
                            effects: effects.clone(),
                        },
                        other => other.clone(),
                    };
                    is_subtype(got, want) || is_subtype(&read, want)
                };
                if !got.is_unknown() && !fits(&got, &want) {
                    let shown = match &arg.value {
                        Expr::Ident(id) => id.name.clone(),
                        _ => "the value given".to_string(),
                    };
                    let detail = match self.fn_fit_reason(&want, &got, &shown) {
                        Some(reason) => reason,
                        None => format!("expects `{want}`, found `{got}`"),
                    };
                    self.error(
                        arg.span,
                        messages::implicit_override_does_not_fit(&imp.name, &detail),
                    );
                }
                // [cmp-carry] A binder filled by hand publishes what was
                // named — and only a *name* can be published, which is where
                // the static-identity rule bites at a call site.
                let identity = if imp.binder {
                    self.written_value_identity(&arg.value)
                } else {
                    None
                };
                return Some((
                    ImplicitArg::Given {
                        name: imp.name.clone(),
                        arity: match want.strip_quals() {
                            Ty::Fn { params, .. } => params.len(),
                            _ => 0,
                        },
                    },
                    identity,
                ));
            }
            // 2. Forwarded from the enclosing fn's own implicits.
            // [implicit-same-name] Among several of the name that fit, the
            // most specific, ranked like overloads (R10 D21); forwarded by
            // its local name.
            let fits = |p: &ImplicitParam| is_subtype(&p.ty, &want) || p.ty.is_unknown() || want.is_unknown();
            match self.pick_own_implicit(&imp.name, &fits) {
                Ok(Some(own)) => {
                    return Some((
                        ImplicitArg::Forwarded {
                            name: own.local.clone(),
                        },
                        // The enclosing fn's own binding, whatever it is:
                        // inside generic code the identity is a name only its
                        // caller knows [implicit-forward].
                        Some(FnId::Binder(imp.name.clone())),
                    ));
                }
                Ok(None) => {}
                Err(tied) => {
                    self.own_implicit_tie(&imp.name, &tied, span);
                    return None;
                }
            }
            // 3. Resolved by name and type among the visible fns and — unless
            // the position is a binder, whose fill is an identity only a
            // top-level fn has [cmp-carry] — the available effects' members
            // (R10 D3).
            let found = match self.resolve_implicit_value(&imp.name, &want, !imp.binder) {
                Ok(Filled::Member(m, nested)) => {
                    // [fn-effects] The value calls through the instance: a use of it.
                    self.note_effect_use(&m.instance);
                    return Some((
                        ImplicitArg::Member {
                            name: imp.name.clone(),
                            effect: self.symbols.key_or(m.effect, &m.effect.name.name).to_string(),
                            index: m.index,
                            instance: m.instance.clone(),
                            nested,
                            want: want.clone(),
                        },
                        None,
                    ));
                }
                Ok(Filled::Fn(k, id)) => Ok((k, id)),
                Err(e) => Err(e),
            };
            match found {
                Ok((found, identity)) => {
                    // [actor-group] [net-noremote] The position wanted a
                    // `() -> Protocol<E>` and std's `protocol<E>` intrinsic
                    // fills it: `E` is concrete here, and this is where a
                    // protocol that cannot cross a node boundary is refused
                    // — the crossing site, now that `actor_group` is an
                    // ordinary fn whose own body never sees `E`.
                    if self
                        .fn_decl_by_key(found)
                        .is_some_and(|d| d.intrinsic && d.name.name == "protocol")
                    {
                        if let Ty::Fn { ret, .. } = want.strip_quals() {
                            if let Ty::Named { name: pn, args } = ret.strip_quals() {
                                if pn == "Protocol" {
                                    if let Some(Ty::Named { name: effect, .. }) =
                                        args.first().map(|a| a.strip_quals())
                                    {
                                        let effect = effect.clone();
                                        self.refuse_noremote_protocol(&effect, callee, span);
                                    }
                                }
                            }
                        }
                    }
                    return Some((
                        ImplicitArg::Resolved {
                            name: imp.name.clone(),
                            key: found,
                            nested: std::mem::take(&mut self.last_nested),
                            want: want.clone(),
                        },
                        Some(identity),
                    ))
                }
                Err(why) => {
                    // [col-key-eligible] [type-unknown-lenient] A keyed
                    // container's key refused as such already (`Set(1.5)`:
                    // "`Double` cannot be a key") is one mistake: its missing
                    // `hash`/`eq`/`cmp` is not a second one.
                    if matches!(imp.name.as_str(), "hash" | "eq" | "cmp") {
                        if let Ty::Fn { params, .. } = want.strip_quals() {
                            if params
                                .first()
                                .is_some_and(|p| self.reported_ineligible_keys.contains(&format!("{}", p.strip_quals())))
                            {
                                return None;
                            }
                        }
                    }
                    let remedy = format!(
                        "declare a matching `fn {}`, or pass one here with `{} = ...`",
                        imp.name, imp.name
                    );
                    let callee_name = callee;
                    // [implicit-recursive] Inside a nested fill the failure is
                    // the opening `try_nested`'s to report, as one more link of
                    // its chain: recorded here, and the error below only marks
                    // that the fill failed.
                    if self.resolve_depth > 0 {
                        let link = (imp.name.clone(), want.clone());
                        let one = |why| Unfilled { links: vec![link.clone()], why };
                        // The first failure of the fill is the one reported.
                        let miss = match why {
                            ImplicitMiss::Unknown => one(UnfilledWhy::NoFit(None)),
                            ImplicitMiss::NearMiss(r) => one(UnfilledWhy::NoFit(Some(r))),
                            ImplicitMiss::Ambiguous(c) => one(UnfilledWhy::Ambiguous(c)),
                            ImplicitMiss::Unfilled(u) => {
                                let mut links = vec![link.clone()];
                                links.extend(u.links);
                                Unfilled { links, why: u.why }
                            }
                        };
                        self.nested_miss.get_or_insert(miss);
                        self.error(
                            span,
                            messages::implicit_recursive_nested_unfilled(&imp.name, &want),
                        );
                        return None;
                    }
                    match why {
                        // Nothing of that name at all: the remedy is the message.
                        ImplicitMiss::Unknown => self.error(
                            span,
                            messages::implicit_resolve_none(&imp.name, &callee_name, &want, &remedy),
                        ),
                        // Declared, but it does not fit — say why, since the
                        // printed types may look identical.
                        ImplicitMiss::NearMiss(reason) => self.error(
                            span,
                            messages::implicit_resolve_no_fit(
                                &imp.name,
                                &want,
                                &callee_name,
                                &reason,
                            ),
                        ),
                        // [fn-overload-ambiguous] The candidates, and the remedies
                        // an implicit has: the override naming the place, or a
                        // rename.
                        ImplicitMiss::Ambiguous(cands) => {
                            let text = Self::implicit_ambiguity(
                                &imp.name,
                                &cands,
                                Some(&format!("`{} = {}@{{m}}`", imp.name, imp.name)),
                            );
                            self.error(
                                span,
                                messages::fn_overload_ambiguous_implicit(
                                    &imp.name,
                                    &callee_name,
                                    &want,
                                    &text,
                                ),
                            )
                        }
                        // [implicit-recursive] The winner's own implicits cannot be
                        // filled: the two ends of the chain and the types between,
                        // and no other candidate stands in.
                        ImplicitMiss::Unfilled(u) => {
                            let text = Self::unfilled_text(&imp.name, &want, &u, true);
                            self.error(
                                span,
                                messages::implicit_recursive_incomplete(
                                    &imp.name,
                                    &want,
                                    &callee_name,
                                    &text,
                                ),
                            )
                        }
                    }
                }
            }
        }
        None
    }

    /// [implicit-recursive] Fills the implicits of the candidate chosen for a
    /// position, each in turn and by the same rules, with the candidate's
    /// generics bound as the fit bound them. `Err` carries the first refusal,
    /// worded as the chain, and leaves no diagnostic behind: the caller
    /// reports it as the chosen candidate's failure, since no other candidate
    /// stands in (user decision 2026-10-14).
    fn try_nested(
        &mut self,
        key: DeclId,
        decl: &'p FnDecl,
        binding: &HashMap<String, Ty>,
        generics: &HashSet<String>,
        want: &Ty,
    ) -> Result<Vec<ImplicitArg>, Unfilled> {
        let implicits = self.out.implicit_params.get(&key).cloned().unwrap_or_default();
        self.try_nested_list(decl, &implicits, binding, generics, want)
    }

    /// [implicit-recursive] [`Self::try_nested`] over a known list: a fn's,
    /// or an effect member's (R10 D3), whose implicits are not keyed by a
    /// `DeclId`.
    fn try_nested_list(
        &mut self,
        decl: &'p FnDecl,
        implicits: &[ImplicitParam],
        binding: &HashMap<String, Ty>,
        generics: &HashSet<String>,
        want: &Ty,
    ) -> Result<Vec<ImplicitArg>, Unfilled> {
        if implicits.is_empty() {
            return Ok(Vec::new());
        }
        let key = decl as *const FnDecl as usize;
        let shown = format!("{want}");
        if self.resolve_depth >= 8 {
            return Err(Unfilled { links: Vec::new(), why: UnfilledWhy::Depth(decl.name.name.clone()) });
        }
        if self.resolve_chain.iter().any(|(k, w)| *k == key && *w == shown) {
            return Err(Unfilled { links: Vec::new(), why: UnfilledWhy::Cycle(decl.name.name.clone()) });
        }
        self.resolve_depth += 1;
        self.resolve_chain.push((key, shown.clone()));
        let before = self.out.errors.len();
        let saved_miss = self.nested_miss.take();
        let mut subst = binding.clone();
        let filled = self.fill_implicit_list(implicits, &decl.name.name, &mut subst, generics, &[], Span::new(0, 0));
        self.resolve_chain.pop();
        self.resolve_depth -= 1;
        let miss = std::mem::replace(&mut self.nested_miss, saved_miss);
        if self.out.errors.len() > before {
            let first = self.out.errors[before].message.clone();
            self.out.errors.truncate(before);
            return Err(miss.unwrap_or(Unfilled { links: Vec::new(), why: UnfilledWhy::Other(first) }));
        }
        filled.ok_or_else(|| Unfilled { links: Vec::new(), why: UnfilledWhy::Other(format!("`{}` for `{shown}` could not be filled", decl.name.name)) })
    }

    /// [implicit-recursive] The explanation of a position whose chosen
    /// candidate could not be completed (`name` at `want`, the reported
    /// one): the failure at the far end of the chain, the wanted types
    /// between — compact, and elided in the middle past four — and the
    /// remedy (`pass`: the position is an implicit, which `name = …` can
    /// fill by hand). Bounded by a few types however deep the chain went.
    fn unfilled_text(name: &str, want: &Ty, u: &Unfilled, pass: bool) -> String {
        // A link's wanted type, compact: what the fn is asked to take.
        let compact = |n: &str, t: &Ty| -> String {
            let inner = match t.strip_quals() {
                Ty::Fn { params, .. } if params.len() == 1 => format!("{}", params[0]),
                Ty::Fn { params, .. } if !params.is_empty() => {
                    format!("({})", params.iter().map(|p| format!("{p}")).collect::<Vec<_>>().join(", "))
                }
                other => format!("{other}"),
            };
            if n == name { format!("`{inner}`") } else { format!("`?{n}: {inner}`") }
        };
        let (last_name, last_want) = u.links.last().map(|(n, t)| (n.as_str(), t)).unwrap_or((name, want));
        let at = format!("`?{last_name}: {last_want}`");
        let failure = match &u.why {
            UnfilledWhy::NoFit(None) => format!("it needs {at}, and no `{last_name}` is in scope"),
            UnfilledWhy::NoFit(Some(r)) => format!("it needs {at}, and no `{last_name}` fits ({r})"),
            UnfilledWhy::Ambiguous(c) => format!("it needs {at}, where {}", Self::implicit_ambiguity(last_name, c, None)),
            UnfilledWhy::Depth(d) => format!("it nests more than 8 levels deep (the `{d}` for {at} needs implicits of its own)"),
            UnfilledWhy::Cycle(d) => format!("the `{d}` for {at} needs itself, a cycle"),
            UnfilledWhy::Other(m) => format!("at {at}, {m}"),
        };
        let mut links: Vec<String> = vec![compact(name, want)];
        links.extend(u.links.iter().map(|(n, t)| compact(n, t)));
        let chain = if links.len() < 3 {
            String::new()
        } else if links.len() <= 4 {
            format!("; chain: {}", links.join(" → "))
        } else {
            let n = links.len();
            format!("; chain: {} → {} → … {} more … → {}", links[0], links[1], n - 3, links[n - 1])
        };
        let remedy = match (&u.why, pass) {
            (UnfilledWhy::NoFit(None), true) => format!("; declare a matching `fn {last_name}`, or pass `{name} = …` explicitly"),
            (UnfilledWhy::NoFit(None), false) => format!("; declare a matching `fn {last_name}`"),
            (_, true) => format!("; pass `{name} = …` explicitly"),
            (_, false) => String::new(),
        };
        format!("{failure}{chain}{remedy}")
    }

    fn resolve_implicit_fn_at(
        &mut self,
        name: &str,
        at: Option<&str>,
        want: &Ty,
    ) -> Result<(DeclId, FnId), ImplicitMiss> {
        self.resolve_implicit_fn_in(name, at, None, want)
    }

    /// [cmp-carry] [cmp-binder] The declaration an **identity** names, at the
    /// position's fn type: looked up in its declaring module rather than by
    /// what the reading file can see, so a value built with `a`'s `my_hash`
    /// is operated on with `a`'s, whatever this file imports.
    fn resolve_identity(&mut self, id: &FnId, want: &Ty) -> Result<(DeclId, FnId), ImplicitMiss> {
        match id {
            FnId::Named { name, at, module, .. } => {
                let (name, at, module) = (name.clone(), at.clone(), module.clone());
                self.resolve_implicit_fn_in(&name, at.as_deref(), module.as_deref(), want)
            }
            FnId::Binder(_) => Err(ImplicitMiss::Unknown),
        }
    }

    /// [cmp-carry] An identity of the declaration behind `key`: its name, its
    /// `@`-scoping when it is attached [fn-attached], and its declaring module.
    fn identity_of(&self, key: DeclId, decl: &FnDecl) -> FnId {
        let at = self.attached_to(key, decl);
        let file = self.files.get(self.resolution.decls.file(key));
        let module = file.map(|f| f.module.to_string());
        let qualify = at.is_none()
            && file.is_some_and(|f| !f.is_std)
            && self.fn_name_clash.contains(decl.name.name.as_str());
        FnId::Named { name: decl.name.name.clone(), at, module, qualify }
    }

    /// [cmp-carry] The overloads of `name` its declaring `module` itself
    /// declares, seen from one of the module's own files.
    fn module_overloads(&self, name: &str, module: &str) -> Vec<crate::resolve::FnEntry<'p>> {
        let Some(file) = self.files.iter().position(|f| f.module.to_string() == module) else {
            return Vec::new();
        };
        self.resolution.scopes[file]
            .fns
            .get(name)
            .map(|es| es.iter().copied().filter(|e| e.module.to_string() == module).collect())
            .unwrap_or_default()
    }

    /// [implicit-resolve] The fn a name resolves to at a required fn type —
    /// **the rule a call follows** (user decision 2026-10-14), with the
    /// wanted fn type in place of an argument list. Every visible overload
    /// competes: each is fitted by the type (parameters contravariant, result
    /// covariant, contract included) without its own implicits filled, a
    /// candidate whose implicit nothing could fill drops out as at a call
    /// [implicit-fit], and the most specific signature wins
    /// [fn-overload-rank]; no single winner is an ambiguity naming the
    /// candidates [fn-overload-ambiguous]. Then — and only for the winner —
    /// its own implicits are filled, by this same rule [implicit-recursive]: a
    /// failure there is an error naming the chain, never a fallback to another
    /// candidate.
    ///
    /// `at` restricts the candidates to one selector — a type (`cmp@Person`,
    /// an `@`-scoped canonical [fn-attached]) or a module (`@core.list`
    /// [fn-overload-at]) — which is what makes an identity a type carries
    /// resolve to the fn it names and no other [cmp-carry]. The identity that
    /// comes back is the *declaration's own*: its `@`-scoping when it has one,
    /// and its bare name otherwise.
    fn resolve_implicit_fn_in(
        &mut self,
        name: &str,
        at: Option<&str>,
        module: Option<&str>,
        want: &Ty,
    ) -> Result<(DeclId, FnId), ImplicitMiss> {
        if !matches!(want.strip_quals(), Ty::Fn { .. }) {
            return Err(ImplicitMiss::Unknown);
        }
        // [fn-rename] Only the overloads that still answer to this name —
        // or, for an identity, the ones its declaring module declares.
        let pool = match module {
            Some(m) => self.module_overloads(name, m),
            None => self.overloads_of(name),
        };
        let entries: Vec<crate::resolve::FnEntry<'p>> = pool
            .into_iter()
            .filter(|e| match at {
                None => true,
                Some(sel) => {
                    self.attached_to(e.key, e.decl).as_deref() == Some(sel)
                        || ModulePath::text_matches_suffix(&e.module.to_string(), sel)
                }
            })
            .collect();
        if entries.is_empty() {
            return Err(ImplicitMiss::Unknown);
        }
        let (cand, fit) = self.select_fn_value(name, entries.into_iter().map(ValueCand::Fn).collect(), want)?;
        let ValueCand::Fn(entry) = cand else { return Err(ImplicitMiss::Unknown) };
        // [cmp-carry] The identity of the declaration itself, which is what a
        // result type publishes: `@`-scoped when it is, and the bare name
        // otherwise — a bare name means "the `cmp` of that name visible where
        // the type is used", which is [implicit-resolve]'s locality.
        let identity = self.identity_of(entry.key, entry.decl);
        // [implicit-recursive] Only now the winner's own implicits, by the
        // same rule; failing that is the error, not another candidate.
        let mut nested = Vec::new();
        if fit.fills && !self.resolve_as_call {
            match self.try_nested(entry.key, entry.decl, &fit.binding, &fit.generics, want) {
                Ok(n) => nested = n,
                Err(reason) => return Err(ImplicitMiss::Unfilled(reason)),
            }
        }
        self.last_nested = nested;
        Ok((entry.key, identity))
    }

    /// [fn-value-select] [implicit-resolve] [fn-overload-scope] **The**
    /// selection of a declared function at a fn type — a call's rule, with
    /// the wanted fn type in place of an argument list. It serves an implicit
    /// position (whatever its selector, see [`Self::resolve_implicit_fn_in`])
    /// and a function passed by name ([`Self::fn_value_by_name`], after its
    /// `@` selector): every candidate in `entries` competes, whatever rung
    /// brought it into scope; each is fitted by the type (parameters
    /// contravariant, result covariant, contract included) without its own
    /// implicits filled; a stamped body's template fns only when nothing else
    /// fits [comptime-hygiene]; among several, a candidate whose implicit
    /// nothing could fill drops out [implicit-fit]; the most specific
    /// signature wins [fn-overload-rank], and no single winner is
    /// [`ImplicitMiss::Ambiguous`] [fn-overload-ambiguous]. Nothing fitting is
    /// `NearMiss` with the best explanation, or `Unknown`. Never `Unfilled`:
    /// the winner's own implicits are the caller's to fill. Emits no
    /// diagnostic.
    fn select_fn_value(
        &mut self,
        name: &str,
        entries: Vec<ValueCand<'p>>,
        want: &Ty,
    ) -> Result<(ValueCand<'p>, FnFit), ImplicitMiss> {
        // The best explanation of a candidate that did not fit, for the
        // diagnostic when nothing does. Ranked, because the *interesting*
        // near-miss is the one a printed type cannot show: a candidate whose
        // shape matches and whose contract does not (rank 0) explains far
        // more than an unrelated overload of the same name (rank 2).
        let mut near: Option<(u8, String)> = None;
        let note = |rank: u8, reason: String, near: &mut Option<(u8, String)>| {
            if near.as_ref().is_none_or(|(r, _)| rank < *r) {
                *near = Some((rank, reason));
            }
        };
        // 1. Every visible overload that fits the position by its type
        // [fn-value]. One declaration is one candidate [fn-overload-scope]: a
        // fn reachable both as an implicitly available name and as a member of
        // this file's own module is one function, not an ambiguity. An
        // available effect's member competes beside them (R10 D3).
        let mut hits: Vec<(ValueCand<'p>, FnFit)> = Vec::new();
        for cand in entries {
            if hits.iter().any(|(c, _)| c.same(&cand)) {
                continue;
            }
            let fit = match &cand {
                ValueCand::Fn(e) => self.fn_value_fit(e.key, e.decl, want),
                ValueCand::Member(m) => self.member_value_fit(m, want),
            };
            match fit {
                Ok(fit) => hits.push((cand, fit)),
                Err((rank, reason)) => note(rank, reason, &mut near),
            }
        }
        // [comptime-hygiene] A stamped body's fallback, as at a call: the
        // template's own fns compete only when nothing the stamping site sees
        // fits.
        if hits.iter().any(|(c, _)| !c.is_template()) {
            hits.retain(|(c, _)| !c.is_template());
        }
        // 2. [implicit-fit] Among several, a candidate whose own implicit
        // nothing here could fill — by shape, as at a call — does not fit.
        if hits.len() > 1 {
            let mut unfillable: Option<String> = None;
            let mut kept = Vec::with_capacity(hits.len());
            for (cand, fit) in hits.drain(..) {
                let missing = if fit.passes_own {
                    None
                } else {
                    match &cand {
                        // [implicit-infer] Inference's probe asks the shape of
                        // what is known, without inferring again: one level.
                        ValueCand::Fn(e) if self.strict_select => {
                            let implicits = self.out.implicit_params.get(&e.key).cloned().unwrap_or_default();
                            self.unfillable_in(&implicits, &fit.generics, &fit.binding)
                        }
                        ValueCand::Fn(e) => self.unfillable_implicit(e.key, &e.decl.generics, &fit.binding, &[]),
                        ValueCand::Member(m) => {
                            let (_, implicits) = self.member_value_ty(m);
                            let generics: HashSet<String> = m.decl.generics.iter().map(|g| g.name.clone()).collect();
                            self.unfillable_in(&implicits, &generics, &fit.binding)
                        }
                    }
                };
                match missing {
                    Some(m) => {
                        unfillable.get_or_insert_with(|| {
                            format!(
                                "the `{name}` from `{}` that fits by type needs `{m}`, which nothing in \
                                 scope fills",
                                cand.origin()
                            )
                        });
                    }
                    None => kept.push((cand, fit)),
                }
            }
            if kept.is_empty() {
                return Err(ImplicitMiss::NearMiss(unfillable.unwrap_or_default()));
            }
            hits = kept;
        }
        if hits.is_empty() {
            return Err(match near {
                Some((_, reason)) => ImplicitMiss::NearMiss(reason),
                None => ImplicitMiss::Unknown,
            });
        }
        // [implicit-infer] Inference's probe with a parameter still unknown:
        // specificity cannot decide for an argument not yet known, so only a
        // single fitting candidate teaches ("ambiguity is accepted as the
        // price").
        if self.strict_select && hits.len() > 1 {
            if let Ty::Fn { params, .. } = want.strip_quals() {
                if params.iter().any(ty_mentions_unknown) {
                    let all: Vec<usize> = (0..hits.len()).collect();
                    return Err(ImplicitMiss::Ambiguous(self.shown_candidates(name, &hits, &all)));
                }
            }
        }
        // 3. The most specific signature [fn-overload-rank]. Candidates whose
        // declared parameter types are identical are one alternative
        // [fn-overload-return]; each already fits the position's result, so
        // two in one alternative are the return type failing to decide.
        let mut classes: Vec<(Vec<String>, Vec<usize>)> = Vec::new();
        for (i, (cand, fit)) in hits.iter().enumerate() {
            let decl = cand.decl();
            let generics: Vec<&str> = decl.generics.iter().map(|g| g.name.as_str()).collect();
            let params: Vec<ast::Param> = if fit.passes_own {
                decl.params.clone()
            } else {
                decl.params.iter().filter(|p| !p.implicit).cloned().collect()
            };
            let sig = crate::refine::param_type_signature(&params, &generics);
            match classes.iter_mut().find(|(s, _)| *s == sig) {
                Some((_, members)) => members.push(i),
                None => classes.push((sig, vec![i])),
            }
        }
        let ranks: Vec<crate::types::RankedCandidate> = classes
            .iter()
            .map(|(_, c)| crate::types::RankedCandidate {
                patterns: hits[c[0]].1.patterns.clone(),
                variadic: hits[c[0]].1.variadic,
            })
            .collect();
        let winner = match crate::types::most_specific(&ranks) {
            Some(ci) if classes[ci].1.len() == 1 => classes[ci].1[0],
            Some(ci) => return Err(ImplicitMiss::Ambiguous(self.shown_candidates(name, &hits, &classes[ci].1))),
            None => {
                // [type-unknown-lenient] One mistake, one diagnostic.
                if ty_mentions_unknown(want) && !self.strict_select {
                    0
                } else {
                    let all: Vec<usize> = (0..hits.len()).collect();
                    return Err(ImplicitMiss::Ambiguous(self.shown_candidates(name, &hits, &all)));
                }
            }
        };
        Ok(hits.swap_remove(winner))
    }

    /// [fn-overload-ambiguous] The candidates an implicit position could not
    /// choose among, as a diagnostic shows them: `` `name(Params)` from `module` ``
    /// (from the effect, for a member).
    fn shown_candidates(
        &self,
        name: &str,
        hits: &[(ValueCand<'p>, FnFit)],
        which: &[usize],
    ) -> Vec<(String, String)> {
        let mut shown: Vec<(String, String)> = which
            .iter()
            .map(|&i| {
                let (cand, fit) = &hits[i];
                let ps: Vec<String> = fit.patterns.iter().map(|p| p.to_string()).collect();
                let origin = cand.origin();
                (format!("`{name}({})` from `{origin}`", ps.join(", ")), origin)
            })
            .collect();
        shown.sort();
        shown.dedup();
        shown
    }

    /// [fn-overload-ambiguous] [implicit-resolve] How an implicit position no
    /// candidate wins is reported: the candidates, then the remedies an
    /// implicit has — the written override naming the place (`name =
    /// name@module`, where the position can be written: `site_override`), or
    /// `rename fn`.
    fn implicit_ambiguity(name: &str, cands: &[(String, String)], site_override: Option<&str>) -> String {
        let shown: Vec<&str> = cands.iter().map(|(s, _)| s.as_str()).collect();
        let mut modules: Vec<&str> = cands.iter().map(|(_, m)| m.as_str()).collect();
        modules.sort();
        modules.dedup();
        let pick = match site_override {
            Some(form) if modules.len() > 1 => {
                let forms: Vec<String> = modules.iter().map(|m| form.replace("{m}", m)).collect();
                format!("Name the one you mean — {} — or give", forms.join(" or "))
            }
            _ => "Give".to_string(),
        };
        format!(
            "{} all fit and none is more specific. {pick} one its own name with \
             `rename fn <new> = {name}(...)`",
            shown.join(", "),
        )
    }

    /// [cmp-binder] The identity of a value written for an implicit parameter
    /// (`cmp = my_cmp`, `cmp = cmp@Person`), when it has one. A lambda or a
    /// local does not: it has no name a type could carry, and where the
    /// signature carries the binder that is an error rather than a silent
    /// loss of the claim.
    fn written_value_identity(&mut self, value: &Expr) -> Option<FnId> {
        // [cmp-carry] The declaration the value was resolved to (`check_expr`
        // recorded it), so the identity names it and not merely its spelling.
        let resolved = |this: &Self, span: Span| {
            let key = *this.out.fn_refs.get(&this.key(span))?;
            Some(this.identity_of(key, this.fn_decl_by_key(key)?))
        };
        match value {
            Expr::Ident(id) if self.lookup(&id.name).is_none() => {
                Some(resolved(self, id.span).unwrap_or_else(|| FnId::named(id.name.clone())))
            }
            Expr::Scoped {
                base: None,
                name,
                module,
                ..
            } => Some(resolved(self, name.span).unwrap_or_else(|| FnId::Named {
                name: name.name.clone(),
                at: Some(
                    module
                        .iter()
                        .map(|m| m.name.as_str())
                        .collect::<Vec<_>>()
                        .join("."),
                ),
                module: None,
                qualify: false,
            })),
            Expr::EffectScoped {
                base: None,
                name,
                effect,
                ..
            } => Some(FnId::Named {
                name: name.name.clone(),
                at: Some(effect.name.clone()),
                module: None,
                qualify: false,
            }),
            other => {
                self.error(other.span(), messages::cmp_carry_no_identity());
                None
            }
        }
    }

    /// [effect-member-overload] [fn-value] An available effect's member that
    /// won a fn-typed position (R10 D3): a closure over its instance
    /// (`Checked::member_values`, lowered as an implicit filled by a member
    /// is), with its own implicits filled where it is used
    /// [implicit-recursive]. `name@Effect` and a bare name both arrive here.
    fn member_as_value(&mut self, name: &str, name_span: Span, m: MemberCand<'p>, fit: FnFit, want: &Ty) -> Ty {
        self.record_def_ref(name_span, name);
        let mut nested = Vec::new();
        if fit.fills {
            let (_, implicits) = self.member_value_ty(&m);
            let (mut binding, mut generics) = Self::instance_binding(&m);
            binding.extend(fit.binding.clone());
            generics.extend(fit.generics.iter().cloned());
            match self.try_nested_list(m.decl, &implicits, &binding, &generics, want) {
                Ok(n) => nested = n,
                Err(u) => {
                    let text = Self::unfilled_text(name, want, &u, false);
                    self.error(name_span, messages::effect_at_value_incomplete(&name, &m.effect.name.name, &want, &text));
                    return Ty::Unknown;
                }
            }
        }
        self.note_effect_use(&m.instance);
        let arg = ImplicitArg::Member {
            name: name.to_string(),
            effect: self.symbols.key_or(m.effect, &m.effect.name.name).to_string(),
            index: m.index,
            instance: m.instance.clone(),
            nested,
            want: want.clone(),
        };
        self.out.member_values.insert(self.key(name_span), arg);
        fit.ty
    }

    /// [fn-value-select] A function passed **by name** (`apply(describe, x)`),
    /// with an optional `@module` (or `@Type`) selector. Selection is a
    /// call's [fn-overload-scope]: `@` first, then every visible overload
    /// competes at the **expected fn type** in place of an argument list
    /// ([`Self::select_fn_value`], shared with implicit resolution) — the
    /// most specific signature wins, whatever rung brought it into scope, and
    /// no single winner is an ambiguity naming `name@module` and `rename`
    /// (user decisions 2026-09-07 and 2026-10-14; until 2026-10-14 the most
    /// specific rung with a candidate won first, so `apply(tag, 1)` took a
    /// module's `tag<T>` where `tag(1)` ranks an imported `tag(Int)` above it).
    ///
    /// With no expected fn type there is nothing to fit, so a single
    /// candidate is taken and an overloaded name is an error naming the two
    /// remedies — an annotation, or `rename`.
    fn fn_value_by_name(
        &mut self,
        name: &str,
        name_span: Span,
        at: Option<Selector<'p>>,
        expected: Option<&Ty>,
    ) -> Ty {
        let entries: Vec<crate::resolve::FnEntry<'p>> = self.overloads_of(name);
        // [effect-member-overload] [fn-value-select] An available effect's
        // members of the name compete with the fns at a fn-typed position
        // (R10 D3, PIPELINE.md B3.6), as `name@Effect` does; a `@module` or
        // `@Type` selector names declarations, which a member never is.
        let want: Option<Ty> = expected.filter(|t| matches!(t.strip_quals(), Ty::Fn { .. })).cloned();
        let members: Vec<MemberCand<'p>> = if at.is_none() { self.available_members(name) } else { Vec::new() };
        if entries.is_empty() {
            let Some(first) = members.first() else {
                return Ty::Unknown;
            };
            if want.is_none() {
                // Detached from a position, a member names no instance's
                // closure, as `name@Effect` does not [effect-at].
                let effect = first.effect.name.name.clone();
                self.error(name_span, messages::fn_value_select_member_not_expected(&name, &effect));
                return Ty::Unknown;
            }
        }
        // [actor-free-send-fn] A send-kind function is not a value: it runs by being
        // scheduled, and a fn value runs by being called — there is no
        // position a `send fn` could fill. (A mint is not a value use: it
        // names the target, and the name never becomes a `Ty::Fn`.)
        if !entries.is_empty() && members.is_empty() && entries.iter().all(|e| e.decl.is_send) {
            self.error(name_span, messages::actor_free_send_fn_not_a_value(&name));
            return Ty::Unknown;
        }
        // `@module` (or `@Type`) first, exactly as in a call.
        let mut pool: Vec<crate::resolve::FnEntry<'p>> = entries;
        if let Some(sel) = at {
            let wanted = sel.render();
            let named: Vec<crate::resolve::FnEntry<'p>> = pool
                .iter()
                .copied()
                .filter(|e| match sel {
                    Selector::Module(_) => {
                        ModulePath::text_matches_suffix(&e.module.to_string(), &wanted)
                    }
                    // [fn-attached] `cmp@Person` as a *value*, which is what
                    // `cmp = cmp@Person` writes [implicit-override]: the
                    // candidates are the fns `@`-scoped to that type. Value
                    // position is where this selector differs from
                    // [effect-at]'s, which is a call form only — it follows the
                    // *module* precedent (`describe@main`) instead.
                    Selector::Type(_) => {
                        self.attached_to(e.key, e.decl).as_deref() == Some(wanted.as_str())
                    }
                    // A member is not a declaration a value names this way.
                    Selector::Effect(_) => false,
                })
                .collect();
            // [mod-suffix] A suffix fitting two modules is refused, as at a call.
            if matches!(sel, Selector::Module(_)) {
                let mut modules: Vec<String> = named.iter().map(|e| e.module.to_string()).collect();
                modules.sort();
                modules.dedup();
                if modules.len() > 1 {
                    self.error(
                        name_span,
                        messages::fn_overload_at_ambiguous_suffix(
                            &wanted,
                            &modules.iter().map(|m| format!("`{m}`")).collect::<Vec<_>>().join(" and "),
                        ),
                    );
                    return Ty::Unknown;
                }
                // [doc-module] The one module the selector named, for hover.
                if let (Some(module), Some(at_span)) = (modules.first(), sel.module_span()) {
                    self.out.module_refs.insert(self.key(at_span), ModulePath::parse(module));
                }
            }
            if named.is_empty() {
                self.error(
                    name_span,
                    match sel {
                        Selector::Module(_) => messages::fn_overload_at_no_fn_in_module(&name, &wanted),
                        Selector::Type(_) | Selector::Effect(_) => messages::fn_attached_no_fn_on_type(&name, &wanted),
                    },
                );
                return Ty::Unknown;
            }
            pool = named;
        }
        // [fn-overload-scope] One declaration is one candidate, however many
        // ways it is visible.
        let mut seen: HashSet<DeclId> = HashSet::new();
        pool.retain(|e| seen.insert(e.key));
        if let (Some(w), false) = (want.as_ref(), members.is_empty()) {
            let cands: Vec<ValueCand<'p>> = pool
                .iter()
                .copied()
                .map(ValueCand::Fn)
                .chain(members.iter().cloned().map(ValueCand::Member))
                .collect();
            match self.select_fn_value(name, cands, w) {
                Ok((ValueCand::Member(m), fit)) => return self.member_as_value(name, name_span, m, fit, w),
                // The fn won: the rest is a fn's, below.
                Ok((ValueCand::Fn(entry), _)) => pool = vec![entry],
                Err(ImplicitMiss::Ambiguous(cands)) => {
                    self.error(
                        name_span,
                        messages::fn_value_select_ambiguous(
                            &name,
                            &w,
                            &Self::implicit_ambiguity(name, &cands, Some(&format!("`{name}@{{m}}`"))),
                        ),
                    );
                    return Ty::Unknown;
                }
                // Nothing fits: with fns, their diagnostic below names each
                // one's reason; with members alone, the nearest miss.
                Err(miss) if pool.is_empty() => {
                    let effect = members[0].effect.name.name.clone();
                    let msg = match miss {
                        ImplicitMiss::NearMiss(reason) => messages::effect_at_value_near_miss(&name, &effect, &w, &reason).into_message(),
                        _ => messages::effect_at_value_no_fit(&name, &effect, &w).into_message(),
                    };
                    self.error(name_span, msg);
                    return Ty::Unknown;
                }
                Err(_) => {}
            }
        }
        let chosen = self.choose_by_name(name, &pool, expected);
        let entry = match chosen {
            Ok(entry) => entry,
            Err(message) => {
                self.error(name_span, message);
                return Ty::Unknown;
            }
        };
        // [fn-ref-table]
        self.out.fn_refs.insert(self.key(name_span), entry.key);
        let decl = entry.decl;
        // [fn-effects] A named fn passed by value performs exactly the
        // effects it declares (inherited entries included) — its callers
        // supply them.
        let effects = self.out.fn_effects.get(&entry.key).cloned().unwrap_or_default();
        // [fn-effects] What the *use site* expects the value to accept: a
        // pure fn passed where effects are expected must still take (and
        // ignore) them, so the emitters adapt against the expectation, not
        // the declaration.
        let taken = match expected.map(|t| t.strip_quals()) {
            Some(Ty::Fn {
                effects: exp_effects,
                ..
            }) => exp_effects.clone(),
            _ => effects.clone(),
        };
        self.out.lambda_effects.insert(self.key(name_span), taken);
        // [fn-value] At an expected fn type, the value is what the shared
        // rule makes of the declaration there — generics instantiated, its
        // own implicits filled — exactly as an implicit filled by it would
        // be. With none, or where it does not fit (the mismatch is reported
        // where the value is used), it is the declaration's own type.
        let fitted = match want.as_ref() {
            Some(w) => match self.fn_value_at(entry.key, decl, w) {
                Ok(v) => Some(v),
                // [implicit-recursive] It fits, and its own implicits cannot be
                // filled: the chain is the error, as for an implicit.
                Err((_, reason)) if self.fn_value_fit(entry.key, decl, w).is_ok() => {
                    self.error(
                        name_span,
                        messages::implicit_recursive_value_incomplete(&name, &w, &reason),
                    );
                    return Ty::Unknown;
                }
                Err(_) => None,
            },
            None => None,
        };
        let Some(value) = fitted else {
            return self.fn_value_ty(entry.key, decl);
        };
        if !value.nested.is_empty() {
            self.out.fn_value_implicits.insert(self.key(name_span), value.nested);
        }
        // [linear-generics] The instantiation ban applies here as at any
        // call: an unopted generic cannot bind a linear type.
        let opted: HashSet<&str> = decl
            .generic_canbe
            .iter()
            .filter(|(_, q)| q.name.name == "linear")
            .map(|(id, _)| id.name.as_str())
            .collect();
        for g in &decl.generics {
            if opted.contains(g.name.as_str()) {
                continue;
            }
            if let Some(bound) = value.binding.get(&g.name) {
                if self.ty_own_linear(bound) {
                    self.error(
                        name_span,
                        messages::linear_generics_fn_value(&g.name, &name, &bound),
                    );
                    break;
                }
            }
        }
        value.ty
    }

    /// [fn-value-select] Which of `pool` (the visible overloads of `name`,
    /// after the `@` selector) a function passed by name is: the one there
    /// is; at an expected fn type, the call's selection
    /// ([`Self::select_fn_value`]); with no expected fn type and several, an
    /// error — there is nothing to select by. `Err` is the diagnostic.
    fn choose_by_name(
        &mut self,
        name: &str,
        pool: &[crate::resolve::FnEntry<'p>],
        expected: Option<&Ty>,
    ) -> Result<crate::resolve::FnEntry<'p>, Message> {
        if pool.len() == 1 {
            return Ok(pool[0]);
        }
        let Some(want) = expected.filter(|t| matches!(t.strip_quals(), Ty::Fn { .. })) else {
            let mut shown: Vec<String> = pool.iter().map(|e| format!("`{}`", self.fn_value_ty(e.key, e.decl))).collect();
            shown.sort();
            shown.dedup();
            return Err(messages::fn_value_select_overloaded(&name, &shown.join(", ")));
        };
        match self.select_fn_value(name, pool.iter().copied().map(ValueCand::Fn).collect(), want) {
            Ok((ValueCand::Fn(entry), _)) => Ok(entry),
            // Only fns are passed here.
            Ok((ValueCand::Member(_), _)) => unreachable!("choose_by_name is given fns only"),
            Err(ImplicitMiss::Ambiguous(cands)) => Err(messages::fn_value_select_ambiguous(
                &name,
                &want,
                &Self::implicit_ambiguity(name, &cands, Some(&format!("`{name}@{{m}}`"))),
            )),
            Err(_) => {
                // None of them fits — which is a *mismatch*, not an
                // ambiguity, and the reason is worth naming: a contract
                // difference does not show in a printed type [fn-contract].
                let mut shown: Vec<String> = pool
                    .iter()
                    .map(|e| {
                        let ty = self.fn_value_ty(e.key, e.decl);
                        match self.fn_value_fit(e.key, e.decl, want) {
                            Err((_, reason)) => format!("`{ty}` ({reason})"),
                            Ok(_) => format!("`{ty}`"),
                        }
                    })
                    .collect();
                shown.sort();
                shown.dedup();
                Err(messages::fn_value_select_no_fit(&name, &want, &shown.join("; ")))
            }
        }
    }

    /// [fn-rename] Brings a `rename fn` into force: resolves the overload it
    /// names, checks the new name is free, and records the binding.
    ///
    /// The overload is matched by parameter names and types, positionally for
    /// type parameters — the same match a `refn` uses [qual-refn-match], so a
    /// std rename surfaces as a diagnostic here rather than as a rename that
    /// silently stops applying.
    ///
    /// [lsp-check-cache] `own`: the rename is written in this file. One
    /// written in another file of the module binds here too, but is checked
    /// and referenced only in its own file, where its spans are.
    fn declare_rename(&mut self, decl: &'p ast::RenameDecl, own: bool) {
        // The rename's own type parameters are in scope for its parameter
        // list, exactly as a `refn`'s are [qual-refn-match].
        if own {
            let saved = self.enter_generics(&decl.generics);
            for p in &decl.params {
                self.validate_type(&p.ty);
            }
            self.generics = saved;
        }
        let new_name = decl.name.name.as_str();
        // The new name must be free: a rename exists to remove an ambiguity,
        // so adding one to an existing name would defeat it.
        if self.scope.fns.contains_key(new_name) {
            self.error_if(
                own,
                decl.name.span,
                messages::fn_rename_name_is_fn(&new_name, &decl.target.name),
            );
            return;
        }
        if self.scope.effect_members.contains_key(new_name) {
            self.error_if(own, decl.name.span, messages::fn_rename_name_is_member(&new_name));
            return;
        }
        if let Some(prev) = self.renames.iter().find(|r| r.new_name == new_name) {
            let prev_span = prev.span;
            self.error_if(
                own,
                decl.name.span,
                messages::fn_rename_name_taken(&new_name, &prev_span.start, &prev_span.end),
            );
            return;
        }
        let saved = self.enter_generics(&decl.generics);
        let matched = crate::refine::match_overload(
            self.scope,
            &decl.target.name,
            &decl.generics,
            &decl.params,
        );
        self.generics = saved;
        match matched {
            Ok(entry) => {
                // [lsp-definition] The new name points at the declaration it
                // renames, so go-to-definition works through it.
                if own {
                    self.out.fn_refs.insert(self.key(decl.name.span), entry.key);
                }
                self.renames.push(RenameBinding {
                    new_name: new_name.to_string(),
                    target: decl.target.name.clone(),
                    entry,
                    span: decl.span,
                });
            }
            Err(shapes) if shapes.is_empty() => self.error_if(
                own,
                decl.target.span,
                messages::fn_rename_no_target(&decl.target.name),
            ),
            Err(shapes) => self.error_if(
                own,
                decl.target.span,
                messages::fn_rename_no_overload(&decl.target.name, &shapes.join(", ")),
            ),
        }
    }

    /// [fn-rename] The overload a *renamed* name means, if `name` is one.
    fn renamed(&self, name: &str) -> Option<crate::resolve::FnEntry<'p>> {
        self.renames
            .iter()
            .rev()
            .find(|r| r.new_name == name)
            .map(|r| r.entry)
    }

    /// [fn-rename] Whether this overload has been renamed away from `name` —
    /// "*only* the new name is valid for that variant".
    fn renamed_away(&self, name: &str, key: DeclId) -> bool {
        self.renames
            .iter()
            .any(|r| r.target == name && r.entry.key == key)
    }

    /// [fn-rename] The overloads of `name` that still answer to it, in scope
    /// order — the candidate set every resolution path starts from.
    fn overloads_of(&self, name: &str) -> Vec<crate::resolve::FnEntry<'p>> {
        if let Some(entry) = self.renamed(name) {
            return vec![entry];
        }
        self.scope
            .fns
            .get(name)
            .map(|entries| {
                entries
                    .iter()
                    .copied()
                    .filter(|e| !self.renamed_away(name, e.key))
                    .collect()
            })
            .unwrap_or_default()
    }

    /// [fn-attached] Whether a capitalized name in scope is a **type** — a
    /// struct, an `intrinsic type` or an alias — which is what tells a
    /// `name@Thing` selector apart from [effect-at]'s.
    fn names_a_type(&self, name: &str) -> bool {
        self.scope.structs.contains_key(name)
            || self.scope.opaque_types.contains_key(name)
            || self.scope.type_aliases.contains_key(name)
    }

    /// [fn-rename] Whether anything answers to this name — a declared
    /// overload that has not been renamed away, or a rename itself.
    fn has_callable(&self, name: &str) -> bool {
        !self.overloads_of(name).is_empty()
    }

    /// [op-unique-shape] Whether resolution refused this declaration for its
    /// placement: a candidate nowhere, so its uses add nothing to its refusal
    /// (ROADMAP 0ag). The scopes' fns and members already leave it out; this
    /// is for the members a body reaches through its effect list.
    fn shape_refused(&self, f: &FnDecl) -> bool {
        !self.resolution.refused_shapes.is_empty() && self.resolution.refused_shapes.contains(&(f as *const FnDecl as usize))
    }

    /// [effect-alias] [effect-prereq] The effect members answering to
    /// `name` here: those this file's scope sees, plus the members of every
    /// effect *available* in the current body. An effect reaches a body
    /// through an alias or as a prerequisite without being imported, and
    /// its members are callable all the same — the effect list, not the
    /// import list, is what makes an instance available [effect-available].
    fn effect_members_here(&self, name: &str) -> Option<Vec<(&'p ast::EffectDecl, &'p FnDecl)>> {
        let mut out: Vec<(&'p ast::EffectDecl, &'p FnDecl)> =
            self.scope.effect_members.get(name).cloned().unwrap_or_default();
        for t in &self.effect_env {
            let Ty::Named { name: key, .. } = &t.ty else { continue };
            let Some(e) = self.symbols.effects.get(key.as_str()).copied() else { continue };
            for f in e.fns.iter().filter(|f| f.name.name == name && !self.shape_refused(f)) {
                if !out.iter().any(|(oe, of)| std::ptr::eq(*oe, e) && std::ptr::eq(*of, f)) {
                    out.push((e, f));
                }
            }
        }
        (!out.is_empty()).then_some(out)
    }

    /// [fn-overload-scope] [fn-overload-rank] [fn-overload-ambiguous] Picks
    /// the winner among the candidates that fit a call — the one rule the
    /// whole language routes through (user decisions 2026-09-07):
    ///
    /// 1. **`@module` first.** A call that names a module means that
    ///    module's overloads and no others; naming a module with no fitting
    ///    overload is an error rather than a silent fallback.
    /// 2. **Every fitting candidate competes**, whatever rung it arrived on
    ///    [fn-overload-scope] (user decision 2026-09-26): scope says what is
    ///    visible, never which one a call means.
    /// 3. **The most specific *signature*.** A partial order
    ///    [fn-overload-rank]: no single most specific candidate is an
    ///    ambiguity error naming the remedies, never a pick.
    ///
    /// An implicit position is chosen by the same rule, with the wanted fn
    /// type in place of the arguments (`resolve_implicit_fn_in`, user decision
    /// 2026-10-14).
    fn select_overload(
        &mut self,
        name: &str,
        viable: &[Viable<'p>],
        arg_tys: &[Ty],
        at: Option<Selector<'p>>,
        expected: Option<&Ty>,
        span: Span,
    ) -> Option<usize> {
        let shown_args = || -> String {
            arg_tys
                .iter()
                .map(|t| t.to_string())
                .collect::<Vec<_>>()
                .join(", ")
        };
        // 1. `@module` / `@Type`: only the selected overloads compete.
        let mut pool: Vec<usize> = (0..viable.len()).collect();
        if let Some(sel) = at {
            let wanted = sel.render();
            let selected: Vec<usize> = pool
                .iter()
                .copied()
                .filter(|&i| match sel {
                    Selector::Module(_) => {
                        ModulePath::text_matches_suffix(&viable[i].module, &wanted)
                    }
                    // [fn-attached] Only the canonicals of that type.
                    Selector::Type(_) => viable[i]
                        .key
                        .is_some_and(|k| {
                            self.attached_to(k, viable[i].decl).as_deref()
                                == Some(wanted.as_str())
                        }),
                    // [effect-at] Only that effect's members.
                    Selector::Effect(e) => viable[i].effect.is_some_and(|ve| std::ptr::eq(ve, e)),
                })
                .collect();
            // [mod-suffix] A suffix that fits two modules is refused rather than
            // guessed: `size@list` with a `std.core.list` and a `shop.list` both
            // declaring `size` names both.
            if matches!(sel, Selector::Module(_)) {
                let mut modules: Vec<&str> = selected.iter().map(|&i| viable[i].module.as_str()).collect();
                modules.sort();
                modules.dedup();
                if modules.len() > 1 {
                    self.error(
                        span,
                        messages::fn_overload_at_ambiguous_suffix(
                            &wanted,
                            &modules.iter().map(|m| format!("`{m}`")).collect::<Vec<_>>().join(" and "),
                        ),
                    );
                    return None;
                }
                // [doc-module] The one module the selector named, for hover.
                if let (Some(module), Some(at_span)) = (modules.first(), sel.module_span()) {
                    self.out.module_refs.insert(self.key(at_span), ModulePath::parse(module));
                }
            }
            if selected.is_empty() {
                match sel {
                    Selector::Module(_) => {
                        let mut modules: Vec<String> =
                            viable.iter().map(|v| v.module.clone()).collect();
                        modules.sort();
                        modules.dedup();
                        self.error(
                            span,
                            messages::fn_overload_at_no_overload_in_module(
                                &name,
                                &shown_args(),
                                &wanted,
                                &modules.join(", "),
                            ),
                        );
                    }
                    Selector::Type(_) => self.error(
                        span,
                        messages::fn_attached_no_fit_on_type(&name, &wanted, &shown_args()),
                    ),
                    Selector::Effect(_) => self.error(span, messages::effect_at_no_member(&wanted, &name)),
                }
                return None;
            }
            pool = selected;
        }
        // [fn-attached] What stood here — "an ambiguity around a canonical is
        // always an error, where [fn-overload-scope] would let `Own` beat
        // `Import` in silence" — was the first installment of "no silent scope
        // winners", and the whole rule landed 2026-09-26: every ambiguity is
        // refused below, so the carve-out is redundant. Its diagnostic named the
        // *type* a candidate was attached to, which two same-named types could
        // not tell apart anyway; the general one names modules.
        // One *declaration* is one candidate, however many routes reach it: a
        // fn can arrive both as an implicitly available name and as a member of
        // the file's own module (std's `test` in an annex, `std.core.list` inside
        // `std.core.list`), which is two entries for one function. Deduping here is
        // what makes step 2's "no single winner is an error" mean what it says —
        // it compares *alternatives*, and these are not.
        Self::dedupe_by_declaration(&mut pool, viable);
        // [comptime-hygiene] A stamped body's fallback: the template's own
        // fns compete only when nothing the stamping site sees fits, so a
        // site name never meets the template's in an ambiguity it did not
        // write.
        if pool.iter().any(|&i| !viable[i].template) {
            pool.retain(|&i| !viable[i].template);
        }
        // [fn-overload-return] Candidates whose parameter types are identical
        // are one alternative for the ranking (parameters cannot tell them
        // apart); the return type chooses within it below.
        let classes = Self::param_classes(&pool, viable);
        // 2. The most specific *signature*, across every rung: **scope no
        // longer breaks a tie** (user decision 2026-09-26 — "when faced with an
        // ambiguity, refuse to choose and let the user choose instead"). Until
        // then the nearest scope won and a discarded, more specific signature
        // was only a warning, so which `add` a call meant depended on a rule
        // the reader had to know std's surface to predict.
        let ranks: Vec<crate::types::RankedCandidate> =
            classes.iter().map(|c| viable[c[0]].rank.clone()).collect();
        let winner = match crate::types::most_specific(&ranks) {
            Some(ci) if classes[ci].len() == 1 => classes[ci][0],
            Some(ci) => {
                let class = classes[ci].clone();
                match self.pick_by_return(name, &class, viable, arg_tys, expected, span) {
                    Ok(w) => w,
                    Err(true) => return None,
                    // [fn-overload-return] Several modules' overloads that the
                    // expected type cannot separate: the ordinary ambiguity,
                    // whose remedy is naming the place.
                    Err(false) => {
                        self.report_ambiguity(name, &class, viable, arg_tys, span);
                        return None;
                    }
                }
            }
            None => {
                let all: Vec<usize> = classes.iter().flatten().copied().collect();
                if arg_tys.iter().any(ty_mentions_unknown) {
                    return Some(all[0]);
                }
                self.report_ambiguity(name, &all, viable, arg_tys, span);
                return None;
            }
        };
        // [fn-overload-at] A selector that changed nothing is noise, and noise
        // in a disambiguation spelling is worse than noise: a reader takes it as
        // evidence that something here is ambiguous. Warned, not refused — it is
        // still a correct program, and the remedy is deleting three characters.
        // It echoes the selector as written: `@core.list` is a suffix of
        // `std.core.list` [mod-suffix], and the reader looks for what they wrote.
        if let Some(Selector::Module(written)) = at {
            if !at.and_then(|s| s.module_span()).is_some_and(|s| self.at_needed.contains(&s))
                && self
                    .unqualified_winner(viable)
                    .is_some_and(|un| std::ptr::eq(viable[un].decl, viable[winner].decl))
            {
                let written = written.iter().map(|i| i.name.as_str()).collect::<Vec<_>>().join(".");
                self.warn(
                    span,
                    messages::fn_overload_at_not_needed(&written, &name, &shown_args()),
                );
            }
        }
        Some(winner)
    }

    /// [fn-overload-ambiguous] Reports a call no rule could settle among
    /// `pool` (indices into `viable`), naming the candidates and the remedy.
    fn report_ambiguity(&mut self, name: &str, pool: &[usize], viable: &[Viable<'p>], arg_tys: &[Ty], span: Span) {
        let shown_args = || -> String {
            arg_tys
                .iter()
                .map(|t| t.to_string())
                .collect::<Vec<_>>()
                .join(", ")
        };
        let mut shown: Vec<String> = pool
            .iter()
            .map(|&i| {
                format!(
                    "{} from `{}`",
                    Self::render_signature(name, &viable[i]),
                    viable[i].module
                )
            })
            .collect();
        shown.sort();
        shown.dedup();
        let mut places: Vec<String> =
            pool.iter().map(|&i| viable[i].module.clone()).collect();
        places.sort();
        places.dedup();
        // Several places, one name: naming the place is the remedy.
        // One place with several unrankable overloads: only a name of
        // its own can separate them.
        // [effect-member-overload] A member has no `rename fn`: the selector
        // naming its effect is the way to it.
        let member = pool.iter().any(|&i| viable[i].effect.is_some());
        let remedy = if places.len() > 1 {
            let forms: Vec<String> = places
                .iter()
                .map(|m| format!("`{name}@{m}(...)`"))
                .collect();
            if member {
                format!("Name the one you mean — {} — or narrow an argument", forms.join(" or "))
            } else {
                format!(
                    "Name the one you mean — {} — or narrow an argument, or give \
                     one its own name with `rename fn <new> = {name}(...)`",
                    forms.join(" or ")
                )
            }
        } else if member {
            "Narrow an argument".to_string()
        } else {
            format!(
                "Narrow an argument, or give one overload its own name with \
                 `rename fn <new> = {name}(...)`"
            )
        };
        self.error(
            span,
            messages::fn_overload_ambiguous_call(&name, &shown_args(), &shown.join(", "), &remedy),
        );
    }

    /// [fn-overload-return] The pool grouped by **identical declared
    /// parameter types** (the declaration-side identity, `param_type_signature`),
    /// in pool order: each group is one alternative for the ranking.
    fn param_classes(pool: &[usize], viable: &[Viable<'p>]) -> Vec<Vec<usize>> {
        let mut classes: Vec<(Vec<String>, Vec<usize>)> = Vec::new();
        for &i in pool {
            let d = viable[i].decl;
            let effect_generics = viable[i].effect.map(|e| e.generics.as_slice()).unwrap_or_default();
            let generics: Vec<&str> = d.generics.iter().chain(effect_generics).map(|g| g.name.as_str()).collect();
            let sig = crate::refine::param_type_signature(&d.params, &generics);
            match classes.iter_mut().find(|(s, _)| *s == sig) {
                Some((_, members)) => members.push(i),
                None => classes.push((sig, vec![i])),
            }
        }
        classes.into_iter().map(|(_, m)| m).collect()
    }

    /// [fn-overload-return] A candidate's return type at this call: lowered
    /// under its generics, with what the arguments bound substituted.
    fn candidate_return(&mut self, v: &Viable<'p>) -> Ty {
        let saved = self.enter_generics(&v.decl.generics);
        if let Some(e) = v.effect {
            self.enter_generics(&e.generics);
        }
        let ret = v.decl.return_type.as_ref().map(|t| self.lower_type(t)).unwrap_or_else(Ty::none);
        self.generics = saved;
        let mut generics: HashSet<String> = v.decl.generics.iter().map(|g| g.name.clone()).collect();
        if let Some(e) = v.effect {
            generics.extend(e.generics.iter().map(|g| g.name.clone()));
        }
        substitute_vars(&ret, &v.subst, &generics)
    }

    /// [fn-overload-return] Chooses among overloads whose parameter types are
    /// identical by **where the value goes** (R-1 (a), user decision
    /// 2026-10-20): the one whose return type fits the expected type, if
    /// exactly one does. With no expected type, or one that fits none or
    /// several, the call is ambiguous and says how to say which — never a pick.
    fn pick_by_return(
        &mut self,
        name: &str,
        class: &[usize],
        viable: &[Viable<'p>],
        arg_tys: &[Ty],
        expected: Option<&Ty>,
        span: Span,
    ) -> Result<usize, bool> {
        let rets: Vec<Ty> = class.iter().map(|&i| self.candidate_return(&viable[i])).collect();
        let exp = expected.filter(|e| !e.is_unknown() && !matches!(e, Ty::Never));
        if let Some(e) = exp {
            let fits: Vec<usize> = class
                .iter()
                .zip(&rets)
                .filter(|(_, r)| is_subtype(r, e))
                .map(|(i, _)| *i)
                .collect();
            if fits.len() == 1 {
                return Ok(fits[0]);
            }
        }
        // [type-unknown-lenient] One mistake, one diagnostic.
        if arg_tys.iter().any(ty_mentions_unknown) || expected.is_some_and(ty_mentions_unknown) {
            return Ok(class[0]);
        }
        // Overloads from several places that the result cannot separate:
        // naming the place is the remedy, as for any cross-module ambiguity.
        let mut modules: Vec<&str> = class.iter().map(|&i| viable[i].module.as_str()).collect();
        modules.sort();
        modules.dedup();
        if modules.len() > 1 {
            return Err(false);
        }
        let shown_args: Vec<String> = arg_tys.iter().map(|t| t.to_string()).collect();
        let shown_rets: Vec<String> = rets.iter().map(|r| format!("`{r}`")).collect();
        let why = match exp {
            None => "nothing here says which result is wanted".to_string(),
            Some(e) => {
                let n = rets.iter().filter(|r| is_subtype(r, e)).count();
                if n == 0 {
                    format!("none of them is a `{e}`, which is what is expected here")
                } else {
                    format!("more than one of them is a `{e}`, which is what is expected here")
                }
            }
        };
        self.error(
            span,
            messages::fn_overload_return_ambiguous(
                &name,
                &shown_args.join(", "),
                &shown_rets.join(", "),
                &why,
                &rets.first().map(|r| r.to_string()).unwrap_or_default(),
            ),
        );
        Err(true)
    }

    /// One *declaration* is one candidate: drops the duplicate entries two
    /// routes to the same function produce.
    fn dedupe_by_declaration(pool: &mut Vec<usize>, viable: &[Viable<'p>]) {
        let mut seen: Vec<(Option<DeclId>, *const FnDecl)> = Vec::new();
        pool.retain(|&i| {
            let id = (viable[i].key, viable[i].decl as *const FnDecl);
            if seen.contains(&id) {
                false
            } else {
                seen.push(id);
                true
            }
        });
    }

    /// [fn-overload-at] Which candidate a call *without* a selector would pick,
    /// computed silently — the question "did the written selector change
    /// anything?" needs the answer, and asking it must not report anything.
    /// It ranks the declared fns only; what shadows them at a bare call (a
    /// local, a `send fn`, an effect member) is `at_needed`'s.
    fn unqualified_winner(&self, viable: &[Viable<'p>]) -> Option<usize> {
        let mut pool: Vec<usize> = (0..viable.len()).collect();
        Self::dedupe_by_declaration(&mut pool, viable);
        // [fn-overload-return] A class of return-type overloads has no winner
        // without the expected type, so a selector there is never "noise".
        let classes = Self::param_classes(&pool, viable);
        let ranks: Vec<crate::types::RankedCandidate> =
            classes.iter().map(|c| viable[c[0]].rank.clone()).collect();
        crate::types::most_specific(&ranks).and_then(|i| (classes[i].len() == 1).then(|| classes[i][0]))
    }

    /// [fn-attached] The type a function is **declared on**, by either route:
    /// written inside the struct's body (the AST carries it, set when the fn was
    /// hoisted) or the file's fulfilment of one of the struct's obligations
    /// (resolution worked that out, since the import rule needs it).
    fn attached_to(&self, key: DeclId, decl: &FnDecl) -> Option<String> {
        decl.scoped_to
            .as_ref()
            .map(|t| t.name.clone())
            .or_else(|| self.resolution.attached.get(&key).cloned())
    }

    /// How a candidate reads in a diagnostic: `name(ParamTy, ParamTy)`, from
    /// the *declared* patterns, since those are what the ranking compared.
    fn render_signature(name: &str, v: &Viable<'p>) -> String {
        let ps: Vec<String> = v.rank.patterns.iter().map(|p| p.to_string()).collect();
        // [fn-overload-return] The return type is part of what tells two
        // candidates apart, so it is shown when written.
        match &v.decl.return_type {
            Some(r) => format!("`{name}({}) -> {r}`", ps.join(", ")),
            None => format!("`{name}({})`", ps.join(", ")),
        }
    }

    /// [proj-type] [fn-overload-rank] Whether an argument of type `arg` fits
    /// a parameter whose (substituted) type is `param`.
    ///
    /// One predicate, shared by fn-overload selection and by the
    /// member-versus-fn ranking [effect-available], because a call routed to
    /// one path by a *different* fit test than that path applies is a call
    /// that reports "no overload" for something that fits. A kept,
    /// non-`Mut` position reads its argument, so a top-level projection fits
    /// it; a consumed or `Mut` position needs the owned value.
    fn arg_fits_param(&self, arg: &Ty, param: &Ty, kept: bool) -> bool {
        is_subtype(arg, param)
            || (kept
                && arg.is_proj()
                && is_subtype(&arg.strip_top_proj(), param)
                // [ref-handle] A `Mut` position needs mutation permission,
                // which a projection has exactly when it is a `ref(c)`
                // handle that carries `Mut` — a mutable element handle
                // (`get` over `List<Mut T>`, which now returns `ref(list)
                // Mut T`). A plain `proj` carrying `Mut` is not a handle
                // and never fits a `Mut` position; a read-only projection
                // (of either flavour) still fits a kept non-`Mut` position
                // (P-3's lift, user decisions 2026-09-24; the narrowing of
                // [proj-readonly]; [ref-handle] for the `ref`-only split).
                && (!Self::carries_mut(param) || (arg.is_ref() && Self::carries_mut(arg))))
            // [proj-opt-slot] A union with borrowed arms — `(proj T)?`, an
            // optional handle, `proj A | B` — fits a kept owned union
            // position **arm by arm**: each value arm is read as the
            // parameter's arm it lands on, by the rule above, and `None`
            // is `None` (user decisions 2026-10-10).
            || (kept && self.union_borrow_fits(arg, param))
            // `proj T` with `T` bound to an owned union (`copy`'s): the
            // borrow reads each value arm.
            || (kept && param.is_proj() && Self::union_proj_fits(arg, param))
    }

    fn union_proj_fits(arg: &Ty, param: &Ty) -> bool {
        let projs: Vec<crate::types::Qual> = param.quals().iter().filter(|q| crate::types::is_proj_name(&q.name)).cloned().collect();
        let Ty::Union(parms) = param.strip_top_proj() else {
            return false;
        };
        let spread = Ty::Union(parms.into_iter().map(|p| if p.is_none_ty() { p } else { p.qualify(projs.clone()) }).collect());
        matches!(arg, Ty::Union(_)) && is_subtype(arg, &spread)
    }

    fn union_borrow_fits(&self, arg: &Ty, param: &Ty) -> bool {
        let arg = crate::types::spread_union_quals(arg);
        let param = crate::types::spread_union_quals(param);
        let (Ty::Union(arms), Ty::Union(parms)) = (&arg, &param) else {
            return false;
        };
        if !arms.iter().any(|a| a.is_proj()) || parms.iter().any(|p| p.is_proj()) {
            return false;
        }
        // A type variable binds to the argument's own arm, borrow included;
        // one inside an arm (`Box<A> | Int`) is left to unification, which
        // reads the borrow as part of the type.
        if parms.iter().any(crate::types::mentions_var) {
            return false;
        }
        if crate::types::read_arm_map(&arg, &param).is_none() {
            return false;
        }
        arms.iter().all(|a| {
            if a.is_none_ty() {
                return parms.iter().any(|p| p.is_none_ty());
            }
            parms.iter().filter(|p| !p.is_none_ty()).any(|p| self.arg_fits_param(a, p, true))
        })
    }

    /// [fn-param-default] Whether a call's shape can fill a candidate's fixed
    /// parameters: `n_pos` positional arguments fill the leading params,
    /// `named` names fill params by name, and any parameter left over must
    /// have a default. A variadic candidate has no ceiling. Returns `false`
    /// when there are too many positional args, a parameter is left unfilled
    /// with no default, a named argument names no fixed parameter, or a
    /// positional and a named argument collide on one parameter.
    ///
    /// Named arguments that match no fixed parameter are *not* rejected here
    /// (they may be implicit-parameter overrides, resolved separately): this
    /// only rules a candidate out when a name collides with a positionally
    /// filled parameter, which is unambiguously wrong.
    fn call_shape_fits(fixed: &[&Param], has_variadic: bool, n_pos: usize, named: &[ast::NamedArg]) -> bool {
        if !has_variadic && n_pos > fixed.len() {
            return false;
        }
        for (i, p) in fixed.iter().enumerate() {
            let by_pos = i < n_pos;
            let by_name = named.iter().any(|a| a.name.name == p.name.name);
            if by_pos && by_name {
                return false; // filled twice
            }
            if !by_pos && !by_name && p.default.is_none() {
                return false; // left unfilled, no default
            }
        }
        true
    }

    /// [fn-overload-rank] The pool of candidates that may *lead* a
    /// call — provide the expected types its arguments are checked against.
    ///
    /// A single candidate always leads, variadic or not (its fixed
    /// parameters are the patterns). With several, only the fixed-arity
    /// candidates that could take this call at all enter the pool: a
    /// variadic candidate's patterns are per-argument rather than
    /// per-parameter, so it would need the argument types it is supposed to
    /// help produce.
    fn lead_pool(
        &mut self,
        candidates: &[CallCand<'p>],
        arity: usize,
        type_args: &'p [ast::Type],
    ) -> Vec<LeadCandidate> {
        let mut pool: Vec<LeadCandidate> = Vec::new();
        for (i, cand) in candidates.iter().enumerate() {
            let decl = cand.decl();
            let fixed: Vec<&Param> = decl
                .params
                .iter()
                .filter(|p| !p.variadic && !p.implicit)
                .collect();
            if candidates.len() > 1
                && (decl.params.iter().any(|p| p.variadic)
                    || arity > fixed.len()
                    || !fixed.iter().skip(arity).all(|p| p.default.is_some()))
            {
                continue;
            }
            let saved = self.enter_cand_generics(cand);
            let patterns: Vec<Ty> = fixed.iter().map(|p| self.lower_type(&p.ty)).collect();
            self.generics = saved;
            // Explicit type arguments pin the substitution from the start, and
            // a member's instance its effect's generics.
            let subst = self.cand_seed(cand, type_args);
            pool.push(LeadCandidate {
                index: i,
                rank: crate::types::RankedCandidate {
                    patterns,
                    variadic: false,
                },
                rung: cand.rung(),
                generics: cand.generic_names(),
                subst,
            });
        }
        pool
    }

    /// [effect-member-generics] Enters a candidate's type variables for
    /// lowering its signature: a member's effect's generics as well as its
    /// own. Answers what to restore.
    fn enter_cand_generics(&mut self, cand: &CallCand<'p>) -> HashSet<String> {
        let saved = self.enter_generics(&cand.decl().generics);
        if let Some(e) = cand.effect() {
            self.enter_generics(&e.generics);
        }
        if let CallCand::Own { handler, .. } = cand {
            self.enter_generics(&handler.generics);
        }
        saved
    }

    /// [call-type-args] [effect-disambiguation] What a candidate's
    /// substitution starts from: a fn's explicit type arguments pin its
    /// generics; a member's pin its **effect's** (they name the instance,
    /// `next_random@Random<Int>()`), and with none written the one visible
    /// instance does.
    fn cand_seed(&mut self, cand: &CallCand<'p>, type_args: &'p [ast::Type]) -> HashMap<String, Ty> {
        let targs: Vec<Ty> = type_args.iter().map(|t| self.lower_type(t)).collect();
        match cand {
            CallCand::Fn(e) => e.decl.generics.iter().map(|g| g.name.clone()).zip(targs).collect(),
            CallCand::Own { decl, .. } => decl.generics.iter().map(|g| g.name.clone()).zip(targs).collect(),
            CallCand::Member { effect, instance, .. } => {
                if !targs.is_empty() {
                    return effect.generics.iter().map(|g| g.name.clone()).zip(targs).collect();
                }
                match instance {
                    Some(Ty::Named { args, .. }) => effect.generics.iter().map(|g| g.name.clone()).zip(args.iter().cloned()).collect(),
                    _ => HashMap::new(),
                }
            }
        }
    }

    /// [effect-member-overload] A member of `effect` as a call candidate,
    /// with the effect's instance when exactly one is visible.
    fn member_cand(&self, effect: &'p EffectDecl, decl: &'p FnDecl) -> CallCand<'p> {
        let key = self.symbols.key_or(effect, &effect.name.name);
        let instances: Vec<Ty> = self
            .visible_effects()
            .into_iter()
            .filter(|t| matches!(t, Ty::Named { name, .. } if *name == key))
            .collect();
        let instance = match instances.as_slice() {
            [one] => Some(one.clone()),
            _ => None,
        };
        CallCand::Member { effect, decl, instance }
    }

    /// [fn-overload-rank] Which pool entry leads: the only one, or the
    /// one whose parameter patterns dominate every other's on the
    /// specificity axis. `None` when none dominates — expected types from an
    /// arbitrary candidate really would be a bias, so the arguments keep the
    /// untyped probe.
    fn dominant_lead(pool: &[LeadCandidate]) -> Option<usize> {
        if pool.is_empty() {
            return None;
        }
        // [fn-overload-scope] The most specific rung first, exactly as the
        // winner is chosen — otherwise a `std.core` candidate would be typing
        // the arguments of a call that resolves in this module.
        let top = pool.iter().map(|c| c.rung).max()?;
        let at_top: Vec<usize> = (0..pool.len()).filter(|&i| pool[i].rung == top).collect();
        if at_top.len() == 1 {
            return Some(at_top[0]);
        }
        // [fn-overload-return] Overloads whose parameters are identical type
        // the arguments identically: one of them leads for all.
        let mut distinct: Vec<usize> = Vec::new();
        for &i in &at_top {
            if !distinct.iter().any(|&d| pool[d].rank.patterns == pool[i].rank.patterns) {
                distinct.push(i);
            }
        }
        if distinct.len() == 1 {
            return Some(distinct[0]);
        }
        let ranks: Vec<crate::types::RankedCandidate> =
            distinct.iter().map(|&i| pool[i].rank.clone()).collect();
        crate::types::most_specific(&ranks).map(|i| distinct[i])
    }

    /// [type-lit-adopt] The numeric type an unsuffixed literal argument may adopt
    /// at position `i` of a call, read off the candidate pool.
    ///
    /// Deliberately conservative, because adoption must not silently re-rank
    /// an overload set [fn-overload-rank]:
    ///
    /// * a candidate whose parameter there is exactly the literal's own type
    ///   (`Int` for an integer literal, `Double` for a float one) blocks
    ///   adoption — that candidate already matches, and it should keep
    ///   winning;
    /// * otherwise the candidates must name exactly *one* numeric type
    ///   between them, which is then the adopted one. Two different numeric
    ///   parameters at one position leave the literal alone rather than
    ///   guessing which overload was meant.
    ///
    /// Non-numeric and generic patterns are ignored: they neither block
    /// adoption nor supply a target, so `twice(9)` over
    /// `twice(Long)`/`twice(Str)` adopts `Long`.
    fn adoptable_numeric_param(
        pool: &[LeadCandidate],
        i: usize,
        float_lit: bool,
    ) -> Option<Ty> {
        let own = if float_lit { "Double" } else { "Int" };
        let mut found: Option<&str> = None;
        for candidate in pool {
            let Some(pattern) = candidate.rank.patterns.get(i) else {
                continue;
            };
            let Some(name) = numeric_expectation(pattern) else {
                continue;
            };
            if name == own {
                return None;
            }
            match found {
                None => found = Some(name),
                Some(seen) if seen == name => {}
                Some(_) => return None,
            }
        }
        found.map(Ty::named)
    }

    /// [implicit-infer] Extends a call's progressive substitution with what
    /// its callee's **implicit parameters** determine (user design 2026-09-06,
    /// built with S-Seq).
    ///
    /// `fns Next<It, T> { fn next(it: Mut It) -> [it: Mut] Emitted T |
    /// Finished }` is how Salvo says "anything iterable": `map<It, T, U>(it:
    /// Mut It, f: (T) -> U, ?Next<It, T>)` binds `It` from its first
    /// argument, and `T` is determined by *which `next` fills the implicit* —
    /// resolving it at `(Mut ListNext<Int>) -> Emitted T | Finished` finds
    /// std's `next(Mut ListNext<T'>)` and reads `T = Int` back off it.
    /// Without this step the lambda would be
    /// typed against an unbound `T`, and `U` would be undeterminable
    /// [call-type-args] — the generic half of a sequence function would only
    /// ever work with a written type-argument list.
    ///
    /// Two-sided, which is why it cannot reuse `resolve_implicit_fn`: the
    /// candidate's own generics bind from the *known* part of the pattern,
    /// and then the caller's variables bind from the instantiated candidate.
    /// Anything ambiguous or absent is left alone: [implicit-resolve] reports
    /// it at the end of the call, and one mistake gets one diagnostic.
    fn extend_subst_from_implicits(
        &mut self,
        key: Option<DeclId>,
        callee_generics: &HashSet<String>,
        progressive: &mut HashMap<String, Ty>,
        named: &[ast::NamedArg],
    ) {
        let Some(key) = key else { return };
        let implicits = match self.out.implicit_params.get(&key) {
            Some(list) if !list.is_empty() => list.clone(),
            _ => return,
        };
        // [implicit-infer] Repeated until it stops learning, because one
        // implicit can determine another's type: `?iter: (c: C) -> Mut It`
        // teaches `It`, which is what makes the `?Next<It, T>` beside it
        // resolvable at all (user decision 2026-09-10). Declaration order is
        // therefore not a constraint on the author, and the cap is the number of
        // implicits — each round has to bind at least one variable to continue.
        for _ in 0..=implicits.len() {
            let before = progressive.len();
            self.learn_from_implicits_once(&implicits, callee_generics, progressive, named);
            if progressive.len() == before {
                break;
            }
        }
    }

    /// One sweep of [implicit-infer]: each implicit that still mentions an
    /// unbound variable of the callee is resolved against what is known, and
    /// what that determines is read back.
    fn learn_from_implicits_once(
        &mut self,
        implicits: &[ImplicitParam],
        callee_generics: &HashSet<String>,
        progressive: &mut HashMap<String, Ty>,
        named: &[ast::NamedArg],
    ) {
        for imp in implicits {
            // The implicit's type as far as this call knows it, with the
            // *unknown* parts left as variables (`substitute_vars` would
            // erase them to `Unknown`, and then there would be nothing to
            // bind).
            let pattern = substitute_known(&imp.ty, progressive, callee_generics);
            if !ty_mentions_vars(&pattern, callee_generics) {
                continue; // nothing left to learn from this one
            }
            if !matches!(pattern.strip_quals(), Ty::Fn { .. }) {
                continue;
            }
            // [implicit-infer] An implicit written at the call site teaches
            // through what was written (`iter = mint_b` binds `It` from
            // `mint_b`, not from the `iter` in scope, ROADMAP §2d item 9c); a
            // written value that is not a fn name teaches nothing here.
            let mut selected: Option<String> = None;
            let lookup = match named.iter().find(|a| a.name.name == imp.name) {
                Some(a) => match &a.value {
                    Expr::Ident(id) => id.name.clone(),
                    // `iter = iter@main` teaches as `iter = iter` does, among
                    // the fns the selector names [fn-overload-at]
                    // [fn-attached] (found by the round trip, PIPELINE B4:
                    // the written-out form inferred less than the original).
                    Expr::Scoped { base: None, name, module, .. } => {
                        selected = Some(module.iter().map(|m| m.name.as_str()).collect::<Vec<_>>().join("."));
                        name.name.clone()
                    }
                    // `cmp@Person`, parsed as an effect selector; a member
                    // teaches nothing here, so only an attached fn can.
                    Expr::EffectScoped { base: None, name, effect, .. } => {
                        selected = Some(effect.name.clone());
                        name.name.clone()
                    }
                    _ => continue,
                },
                None => imp.name.clone(),
            };
            // [implicit-infer] **Selection, then read the variables off the
            // winner** (R10 D22): the call's rule at the position as far as it
            // is known, the callee's unbound variables standing for anything,
            // so the most specific candidate teaches — `f(x: Int) -> Str`
            // beside `f<T>(x: T) -> Str` fills `?f: (x: Int) -> B` and binds
            // `B = Str` — where the old matcher wanted exactly one candidate
            // to fit and skipped any with implicits of its own. A written name
            // is fns only, and a binder's fill an identity [cmp-carry]; an
            // available effect's member teaches as it fills (R10 D3).
            // Ambiguous or absent teaches nothing.
            let written = lookup != imp.name || selected.is_some();
            let entries: Vec<ValueCand<'p>> = if written {
                let mut fns = self.overloads_of(&lookup);
                if let Some(wanted) = &selected {
                    // [name-casing] A lowercase selector is a module, a
                    // capitalized one a type, as where the value is checked.
                    let is_type = wanted.chars().next().is_some_and(|c| c.is_uppercase());
                    fns.retain(|e| {
                        if is_type {
                            self.attached_to(e.key, e.decl).as_deref() == Some(wanted.as_str())
                        } else {
                            ModulePath::text_matches_suffix(&e.module.to_string(), wanted)
                        }
                    });
                }
                fns.into_iter().map(ValueCand::Fn).collect()
            } else {
                self.implicit_candidates(&lookup, !imp.binder)
            };
            if entries.is_empty() || self.infer_depth >= 4 {
                continue;
            }
            let probe = substitute_vars(&imp.ty, progressive, callee_generics);
            self.infer_depth += 1;
            let strict = std::mem::replace(&mut self.strict_select, true);
            let open = self.infer_open.replace((pattern.clone(), callee_generics.clone()));
            let errors = self.out.errors.len();
            let picked = self.select_fn_value(&lookup, entries, &probe);
            self.out.errors.truncate(errors);
            self.strict_select = strict;
            self.infer_open = open;
            self.infer_depth -= 1;
            let Ok((_, fit)) = picked else { continue };
            // Our own variables, read back off the instantiated winner.
            if let Some(extended) = infer_read_back(&pattern, &fit.ty, progressive) {
                *progressive = extended;
            }
        }
    }

    /// [handler-state] A frame of read-only locals for [params] — the
    /// constructor parameters a state initialiser may read.
    fn read_only_frame(&mut self, params: &'p [Param]) -> HashMap<String, LocalVar> {
        let mut frame = HashMap::new();
        for p in params {
            let ty = self.lower_type(&p.ty);
            let id = self.next_var_id;
            self.next_var_id += 1;
            frame.insert(
                p.name.name.clone(),
                LocalVar {
                    declared: ty.clone(),
                    narrowed: ty,
                    id,
                    links: Vec::new(),
                    is_param: true,
                    for_origin: None,
                    decl_span: p.name.span,
                    lambda_kept: true,
                    is_handler_state: false,
                    widened: None,
                    place_narrows: Vec::new(),
                    used: true,
                },
            );
        }
        frame
    }

    /// A fn, a qualifier fn or a handler member, in the half `self.pass`
    /// names [decl-interface-pass]: the interface pass checks the signature and
    /// records it (`FnSig`); the body pass installs that record and walks the
    /// body, re-deriving and re-reporting nothing about the signature. (The
    /// one body walked with the interfaces is an inferring `iter fn`
    /// minter's: `body_pass_of`.)
    fn check_fn(&mut self, f: &'p FnDecl, extra_params: &'p [Param], state: &'p [FieldDecl]) {
        let saved_generics = self.enter_generics(&f.generics);
        let addr = f as *const FnDecl as usize;
        let sig = if self.pass.interface() {
            let sig = self.fn_interface(f, extra_params);
            self.iface.fns.insert(addr, sig.clone());
            sig
        } else {
            match self.iface.fns.get(&addr) {
                Some(sig) => sig.clone(),
                None => panic!(
                    "[decl-interface-pass] `{}` reached the body pass with no interface",
                    f.name.name
                ),
            }
        };
        if self.pass != self.body_pass_of(f) {
            self.generics = saved_generics;
            return;
        }
        self.install_sig(f, &sig);
        let Some(body) = &f.body else {
            self.generics = saved_generics;
            return;
        };
        // [proj-infer] A written lend list against what the body visibly
        // lends: a check that reads the body, so it is the body's, though
        // it reports at the clause.
        self.check_written_lends_against_body(f, body);
        self.check_fn_body(f, body, extra_params, state, sig, saved_generics);
    }

    /// [decl-interface-pass] [handler-state-infer] The pass that walks `f`'s body: the
    /// body pass, except for the generated minter of an `iter fn` whose
    /// state infers a field's type (`at = 0`). That minter's body is the
    /// state initializers, and the types they give are the iterator
    /// struct's fields, which other declarations read
    /// (`declared_field_ty`): an interface, so the minter is checked, body
    /// and all, with the interfaces (PIPELINE.md 4.6, R5 option b). Read
    /// off a body walk, a fn declared above the `iter fn` saw the field as
    /// `Unknown`, and `return c.at` from a `-> Str` passed (found
    /// 2026-10-20).
    fn body_pass_of(&self, f: &FnDecl) -> Pass {
        let Some(state) = &f.iter_state_name else { return Pass::Body };
        let Some(body) = &f.body else { return Pass::Body };
        let [ast::Stmt::Expr(Expr::Return { value: Some(value), .. })] = body.stmts.as_slice() else {
            return Pass::Body;
        };
        let Expr::StructLit { ty: Some(ast::Type::Named { base, .. }), .. } = value.as_ref() else {
            return Pass::Body;
        };
        let infers = base.name.name == state.name
            && self
                .scope
                .structs
                .get(state.name.as_str())
                .is_some_and(|s| s.fields.iter().any(|field| field.ty.is_none()));
        if infers {
            Pass::Interface
        } else {
            Pass::Body
        }
    }

    /// [decl-interface-pass] Puts a fn's recorded interface where its body walk
    /// reads it.
    fn install_sig(&mut self, f: &'p FnDecl, sig: &FnSig) {
        self.own_derived_return = sig.derived_return.clone();
        self.own_response = f.response.clone();
        self.own_preserve = sig.preserve.clone();
        self.reader_bound.clear();
        self.own_derived_sources = sig.derived_sources.clone();
        self.own_lends_declared = sig.lends_declared;
        self.own_lends = sig.lends.clone();
        self.own_proj_arms = sig.proj_arms.clone();
        self.own_linear_generics = sig.linear_generics.clone();
    }

    /// [decl-interface-pass] Records a fn's signature facts that other
    /// declarations' interfaces read (02-resolve-03, step one): its implicit
    /// parameters, the claims it establishes, and its effect list.
    fn sig_facts(&mut self, f: &'p FnDecl) -> SigFacts {
        // [implicit-param] [implicit-group] Expanded and validated before
        // anything else needs them: the body sees each as a local of fn
        // type, and every call site reads the same list.
        let implicits = self.expand_implicits(f);
        // [deduce-reapply] `=> p: +Q Mut` — the claims this fn establishes.
        self.check_reapplied_deductions(f);
        // Validate the declared effect list (unknown effects, duplicates)
        // and build the fn's effect environment.
        let (effects, can_use, can_spawn) = self.check_effect_list(f);
        // [fn-effects] The fn's own list, expanded: a fn named as a *value*
        // builds its `Ty::Fn` from this table, whichever body names it
        // first (PIPELINE.md step 7).
        let tys: Vec<Ty> = effects.iter().map(|a| a.ty.clone()).collect();
        self.out.decl_effects.insert(self.key(f.name.span), tys.clone());
        if let Some(key) = self.own_fn {
            self.out.fn_effects.insert(key, tys);
        }
        SigFacts { implicits, effects, can_use, can_spawn }
    }

    /// [decl-interface-pass] The signature half of `check_fn`: every check of the
    /// fn's header, with the fn's generics in scope. Reads the fn's text and
    /// other declarations' interfaces, never a body.
    fn fn_interface(&mut self, f: &'p FnDecl, extra_params: &'p [Param]) -> FnSig {
        self.require_explicit_decl(f);
        if f.body.is_none() {
            // A plain fn with no body is already an error (it is written
            // `platform fn`, [platform-fn]); the clause still needs every
            // parameter, and is about "a fn with no body".
            let what = if f.platform {
                "a `platform fn`"
            } else if f.intrinsic {
                "an `intrinsic fn`"
            } else {
                "a fn with no body"
            };
            self.require_full_clause(f, what);
        }
        for p in &f.params {
            self.validate_type(&p.ty);
            // [proj-readonly] A parameter written with a *top-level*
            // `proj Mut` is self-contradictory, caught here at the
            // declaration (user decision 2026-09-12): the `proj` promises
            // to accept borrowed values, but the `Mut` makes this a `Mut`
            // position, which a `proj` value never satisfies — so every
            // projection argument would be refused, and the body could
            // never use the permission either (the parameter is a
            // projection to it). Nested occurrences (`Mut List<proj Mut
            // Str>`) stay legal: there the `Mut` belongs to the element
            // type a view really holds.
            if let Some(mut_ref) = top_level_proj_mut(&p.ty) {
                self.error(mut_ref.span, messages::proj_readonly_proj_mut_param(&p.name.name));
            }
        }
        // [implicit-param] [deduce-reapply] [fn-effects] The facts step one
        // recorded for every fn (`check_signature_facts`).
        let addr = f as *const FnDecl as usize;
        let facts = match self.iface.facts.get(&addr) {
            Some(facts) => facts.clone(),
            None => panic!(
                "[decl-interface-pass] `{}` reached the interface check with no signature facts",
                f.name.name
            ),
        };
        let SigFacts { implicits, effects: mut fn_effects, can_use, mut can_spawn } = facts;
        if let Some(rt) = &f.return_type {
            self.validate_type(rt);
        }
        // [fn-type-named] Rule (c): a type-named fn must return a value whose
        // type has the named base AND at least the named qualifiers (extra
        // qualifiers allowed). Checked with the fn's generics in scope.
        if f.type_name.is_some() {
            self.check_type_named_fn(f);
        }
        if f.constructs.is_some() {
            self.check_constructor_sig(f);
        }
        // [proj-readonly-return] `-> proj(p) T`: `p` must be a
        // parameter and must be *kept* — a moved parameter's data needs
        // no annotation (the callee owns it), and a borrow of a moved
        // value could not outlive the call.
        let derived_return = f.derived_return.as_ref().map(|id| id.name.clone());
        // [deduce-conditional] Validate a qualifier-conditional response: each
        // subject must be a *kept* parameter (a moved one tells the caller
        // nothing afterwards), and the qualifier must be in scope and apply.
        if let Some(responses) = &f.response {
            for r in responses {
                let Some(p) = f.params.iter().find(|p| p.name.name == r.subject.name) else {
                    self.error(
                        r.span,
                        messages::deduce_conditional_not_a_param(&r.subject.name, &f.name.name),
                    );
                    continue;
                };
                // Kept unless a written deduction moves it (`=> !p` / `p:
                // Never` / `p: None`-less move).
                let moved = f.deductions.iter().flatten().any(|d| {
                    d.param_name().is_some_and(|n| n.name == r.subject.name)
                        && matches!(
                            d.kind,
                            ast::DeductionKind::Moved | ast::DeductionKind::Deferred
                        )
                });
                if moved {
                    self.error(
                        r.span,
                        messages::deduce_conditional_moved(&r.subject.name, &f.name.name),
                    );
                }
                if self.qualifier_named(r.qual.name.name.as_str()).is_none() {
                    self.error(
                        r.qual.span,
                        messages::deduce_conditional_unknown_qualifier(&r.qual.name.name),
                    );
                } else {
                    let subj = self.lower_type(&p.ty);
                    if let Some(decl) = self.qualifier_for(r.qual.name.name.as_str(), Some(&subj)) {
                        if !self.qual_applies(decl, subj.strip_quals()) {
                            self.error(
                                r.qual.span,
                                messages::deduce_conditional_not_applicable(
                                    &r.qual.name.name,
                                    &subj,
                                ),
                            );
                        }
                    }
                }
            }
        }
        // [qual-preserve] The fn's own preserve entries: recorded for the
        // body walk, and validated — the entry needs a body to check
        // against (a bodiless declaration is what refinements are for), a
        // parameter of this fn, and a dependent qualifier.
        let mut preserve: HashMap<String, Vec<String>> = HashMap::new();
        for d in f.deductions.iter().flatten() {
            let (Some(name), ast::DeductionKind::Preserve(quals)) = (d.param_name(), &d.kind)
            else {
                continue;
            };
            if f.body.is_none() {
                self.error(d.span, messages::qual_refn_bodiless_preserve());
                continue;
            }
            if !f.params.iter().any(|p| p.name.name == name.name) {
                self.error(d.span, messages::qual_preserve_not_a_param(&name.name));
                continue;
            }
            let mut names: Vec<String> = Vec::new();
            for q in quals {
                let dependent = self
                    .scope
                    .qualifiers
                    .get(q.name.name.as_str())
                    .is_some_and(|ds| ds.iter().any(|d| !d.value_slots.is_empty()));
                if !dependent {
                    self.error(q.span, messages::qual_depend_preserve_not_dependent(&q.name.name));
                    continue;
                }
                names.push(q.name.name.clone());
            }
            if !names.is_empty() {
                preserve.insert(name.name.clone(), names);
            }
        }
        let derived_sources: Vec<String> = f
            .return_type
            .as_ref()
            .and_then(|rt| proj_refs(rt).into_iter().find(|r| !r.from.is_empty()))
            .map(|r| r.from.iter().map(|i| i.name.clone()).collect())
            .unwrap_or_default();
        // [proj-infer] What this fn's result holds borrows of: declared with
        // `holds proj(p)`, else every kept non-Copy parameter — from the
        // signature alone (PIPELINE.md 4.2). A written list is checked against
        // what the body visibly lends (`check_written_lends_against_body`, in
        // the body pass); the default covers every kept parameter by
        // construction.
        let lends_declared = crate::lends::declared_lends(f).is_some();
        let lends: Vec<String>;
        {
            let lent = self.infer_lends(f);
            lends = lent
                .iter()
                .filter_map(|&i| f.params.get(i).map(|p| p.name.name.clone()))
                .collect();
            if let Some(key) = self.fn_key_of_decl(f) {
                self.out.fn_lends.insert(key, lent.clone());
            }
            if let Some(list) = &f.deductions {
                // A parameter both consumed (`!p`) and named as a projection
                // source: a borrow needs the caller to keep the value.
                let moved: Vec<String> = list
                    .iter()
                    .filter(|d| matches!(d.kind, ast::DeductionKind::Moved))
                    .filter_map(|d| d.param_name().map(|n| n.name.clone()))
                    .collect();
                for d in list.iter() {
                    if let Some(sources) = d.proj_sources() {
                        for src in sources.iter().filter(|s| moved.contains(&s.name)) {
                            self.error(
                                src.span,
                                messages::proj_infer_consumed_and_projected(&src.name),
                            );
                        }
                    }
                }
            }
        }
        let proj_arms = f
            .return_type
            .as_ref()
            .map(proj_arm_qualifiers)
            .unwrap_or_default();
        // [proj-anywhere] Every *wholesale* `proj` in the return type — on the
        // result, an arm, a tuple element — must say what it borrows from:
        // without `[from: p]` there is nothing to link the result to, and the
        // caller could not know which argument it depends on. A `proj` inside
        // a type argument (`List<proj T>`) is a borrow the result *holds*:
        // it names no source, the lend does [proj-infer]. Parameters may write
        // a bare `proj` (it names the *kind* of value expected, not a source).
        if let Some(rt) = &f.return_type {
            let held: Vec<Span> = proj_refs_in_type_args(rt).iter().map(|r| r.span).collect();
            for r in proj_refs(rt) {
                let is_held = held.contains(&r.span);
                if is_held {
                    if let Some(from) = r.from.first() {
                        self.error(from.span, messages::proj_infer_element_no_source());
                    }
                    continue;
                }
                if r.from.is_empty() {
                    self.error(r.span, messages::proj_infer_return_no_source());
                }
                for from in &r.from {
                    let is_param = f.params.iter().any(|p| p.name.name == from.name)
                        || extra_params.iter().any(|p| p.name.name == from.name);
                    if !is_param {
                        self.error(
                            from.span,
                            messages::proj_infer_not_a_param(&r.name.name, &from.name),
                        );
                    }
                }
            }
        }
        // [ref-anchor] A `ref(c)` parameter names another parameter as its
        // container.
        for p in &f.params {
            let quals = match &p.ty {
                ast::Type::Named { qualifiers, .. } | ast::Type::QualifiedGroup { qualifiers, .. } => qualifiers,
                _ => continue,
            };
            for r in quals.iter().filter(|q| q.name.name == "ref") {
                for from in &r.from {
                    let ok = from.name != p.name.name
                        && (f.params.iter().any(|q| q.name.name == from.name)
                            || extra_params.iter().any(|q| q.name.name == from.name));
                    if !ok {
                        self.error(from.span, messages::ref_anchor_not_a_param(&from.name));
                    }
                }
            }
        }
        if let Some(id) = &f.derived_return {
            let is_param = f.params.iter().any(|p| p.name.name == id.name)
                || extra_params.iter().any(|p| p.name.name == id.name);
            // A source that names no parameter was reported by the
            // per-occurrence loop above; only the kept rule is left here.
            if is_param {
                let kept = match &f.deductions {
                    Some(list) => crate::deduce::from_written(f, list, &HashSet::new(), |_, _| {})
                        .iter()
                        .find(|d| d.param == id.name)
                        .is_some_and(|d| d.kept),
                    None => self
                        .own_contract
                        .as_ref()
                        .and_then(|c| c.iter().find(|d| d.param == id.name))
                        .is_some_and(|d| d.kept),
                };
                if !kept {
                    self.error(id.span, messages::proj_infer_moved_source(&id.name));
                }
            }
        }
        // [linear-generics] Type-parameter opt-ins: `<T canbe linear>`
        // treats `T`-typed values as linear in this body and admits
        // linear instantiation at call sites. Only `Linear` is
        // supported in a type-parameter `with` clause.
        let linear_generics: HashSet<String> = f
            .generic_canbe
            .iter()
            .filter(|(_, q)| q.name.name == "linear")
            .map(|(id, _)| id.name.clone())
            .collect();
        for (_, q) in &f.generic_canbe {
            if q.name.name != "linear" {
                self.error(q.span, messages::linear_generics_with_clause(&q.name.name));
            }
        }
        // [actor-spawn-effect] A handler member inherits its handler's
        // dependency list, and `[spawn]` is part of that list — a supervisor
        // spawns its children from a member body.
        can_spawn = can_spawn || self.handler_spawns;
        // [throw-not-main] The entry point has nowhere to throw *to*: Rust
        // cannot express a `main` returning `ControlFlow` and Kotlin would
        // die on an uncaught signal, so the delimiter must be inside.
        if f.name.name == "main" && self.own_fn.is_some() {
            if let Some(span) = f
                .effects
                .iter()
                .flatten()
                .filter_map(|e| match e {
                    EffectRef::Effect(r) | EffectRef::AnyEffect(r)
                        if r.name.name == THROW_EFFECT =>
                    {
                        Some(r.span)
                    }
                    _ => None,
                })
                .next()
            {
                self.error(span, messages::throw_not_main_declared(&THROW_EFFECT));
            }
        }
        // [effect-handler-deps] A handler member body may use the effects
        // its handler declares in its effect list, exactly as if the member
        // had declared them — which it may not
        // ([effect-member-no-effects]): the dependency belongs to the
        // implementation, so it is declared once on the handler. (The
        // fn's own list went to `decl_effects`/`fn_effects` with its
        // signature facts; a top-level fn inherits no dependencies.)
        for dep in &self.handler_deps {
            if !fn_effects.iter().any(|a| a.ty == dep.ty) {
                fn_effects.push(dep.clone());
            }
        }
        // Inside a qualifier constructor (`-> T as Qual`) return points
        // produce plain `T` values; the qualifier is applied by construction
        // (callers see `Qual T`). Only a body has return points.
        let mut ret_ty = Ty::none();
        if f.body.is_some() {
            ret_ty = f
                .return_type
                .as_ref()
                .map(|t| self.lower_type(t))
                .unwrap_or_else(Ty::none);
            // [deduce-reapply] `+Q` inside the return type marks a claim this
            // fn **establishes**: callers see it (`fn_return_ty` lowers the
            // written type as-is), the body's returns are checked *without*
            // it — trusted, so only in the qualifier's own file, the same
            // gate a constructor's head `+Q` answers to.
            let established: Vec<(String, Span)> = f
                .return_type
                .as_ref()
                .map(|rt| established_quals(rt))
                .unwrap_or_default();
            if !established.is_empty() {
                let mut strip: HashSet<String> = HashSet::new();
                for (name, span) in &established {
                    if !self.own_qualifiers.contains(name.as_str()) {
                        self.error(*span, messages::deduce_reapply_other_file(&name));
                    }
                    strip.insert(name.clone());
                }
                ret_ty = match ret_ty {
                    Ty::Union(arms) => Ty::union_of(
                        arms.into_iter().map(|a| a.remove_quals(&strip)).collect(),
                    ),
                    other => other.remove_quals(&strip),
                };
            }
        }
        FnSig {
            implicits,
            effects: fn_effects,
            can_use,
            can_spawn,
            derived_return,
            preserve,
            derived_sources,
            lends_declared,
            lends,
            proj_arms,
            linear_generics,
            ret_ty,
        }
    }

    /// [proj-infer] A written lend list must cover every lend the body
    /// visibly performs. Reads the body (syntactically, `lends::infer_from_body`),
    /// so it runs in the body pass; the fn's lends themselves are the
    /// signature's (`fn_interface`).
    fn check_written_lends_against_body(&mut self, f: &'p FnDecl, body: &'p Block) {
        let Some(declared) = crate::lends::declared_lends(f) else { return };
        let scope_fns = &self.scope.fns;
        let lookup = |name: &str| -> Vec<&'p FnDecl> {
            scope_fns
                .get(name)
                .map(|v| v.iter().map(|e| e.decl).collect())
                .unwrap_or_default()
        };
        let mut env = crate::lends::LendsEnv {
            structs: &self.scope.structs,
            fns: &lookup,
            memo: &mut self.lends_memo,
        };
        let inferred: Option<Vec<usize>> = crate::lends::infer_from_body(f, body, &mut env)
            .map(|set| {
                let mut v: Vec<usize> = set.into_iter().collect();
                v.sort_unstable();
                v
            });
        let Some(inferred) = inferred else { return };
        // Declared must cover inferred: a lend the body visibly performs
        // cannot go unwritten. The reverse is allowed — a generic body
        // (`add(out, x)` with `x` an element of an opaque pass) lends
        // through opacity the analysis cannot see, and the written entry is
        // how it says so.
        if inferred.iter().any(|i| !declared.contains(i)) {
            let show = |v: &[usize]| -> String {
                let names: Vec<String> = v
                    .iter()
                    .filter_map(|&i| f.params.get(i).map(|p| p.name.name.clone()))
                    .collect();
                if names.is_empty() {
                    "nothing".to_string()
                } else {
                    format!("`{}`", names.join("`, `"))
                }
            };
            let span = f
                .deductions
                .as_ref()
                .and_then(|l| {
                    l.iter()
                        .find(|d| d.proj_sources().is_some())
                        .map(|d| d.span)
                })
                .unwrap_or(f.name.span);
            self.error(
                span,
                messages::proj_infer_lends_disagree(&show(&declared), &show(&inferred)),
            );
        }
    }

    /// The body half of `check_fn`: the parameter frame, the body walk, and
    /// what is checked against the walk (declared field mutations, a missing
    /// return). Every signature fact comes from `sig` [decl-interface-pass].
    fn check_fn_body(
        &mut self,
        f: &'p FnDecl,
        body: &'p Block,
        extra_params: &'p [Param],
        state: &'p [FieldDecl],
        sig: FnSig,
        saved_generics: HashSet<String>,
    ) {
        let FnSig { implicits, effects: fn_effects, can_use, can_spawn, ret_ty, .. } = sig;
        // [node-id] Variable ids are per declaration: what a body's facts
        // carry of them (`FateLink::elem_idx`, `distinct_pairs`) does not
        // move when another declaration of the file changes.
        self.next_var_id = 0;
        // [lsp-completion] Record locals of this body (params below, `let`/
        // binding locals in `declare_var`) against the body span.
        self.cur_fn_body = Some(body.span);
        // [lsp-completion] Record the effects available in this body — the
        // expanded set just assembled (declared + prerequisites + any
        // inherited handler dependencies) — so completion can offer the
        // members of effects in scope. File comes from the body span's owner,
        // which is the fn being checked.
        if let Some(key) = self.own_fn {
            let tys: Vec<Ty> = fn_effects.iter().map(|a| a.ty.clone()).collect();
            if !tys.is_empty() {
                self.out.fn_body_effects.push((self.resolution.decls.file(key), body.span, tys));
            }
        }
        // [mod-use] The module's bindings sit outermost, so a function's own
        // declaration of the same effect shadows them.
        let mut env = self.module_avails.clone();
        env.extend(fn_effects);
        let saved_env = std::mem::replace(&mut self.effect_env, env);
        let saved_can_use = std::mem::replace(&mut self.can_use, can_use);
        let saved_can_spawn = std::mem::replace(&mut self.can_spawn, can_spawn);
        // [implicit-forward] What this body can forward to the calls it makes.
        let saved_implicits = std::mem::replace(&mut self.own_implicits, implicits.clone());
        self.ret_ty = ret_ty;

        let mut top = HashMap::new();
        for p in extra_params.iter().chain(&f.params) {
            // [type-union-spread] The body sees a `...T` arm as plain `T`: the
            // spread marker is a call-site matching fact only.
            let ty = self.lower_type(&p.ty).strip_spread();
            // Parameter names hover like the variables they are
            // [doc-hover-narrowed].
            self.out
                .expr_ty
                .entry(self.key(p.name.span))
                .or_insert_with(|| ty.clone());
            // [lsp-completion] A parameter is a local offered throughout the
            // body. Implicits (`?cmp`) are the fn's own machinery, not names a
            // caller writes, so they are left out.
            if !p.implicit {
                self.record_local_decl_scoped(&p.name, ty.clone(), true);
            }
            let id = self.next_var_id;
            self.next_var_id += 1;
            // [implicit-same-name] A second implicit of one name is bound
            // under its own local name.
            let bound_as = if p.implicit {
                implicits
                    .iter()
                    .find(|i| i.name == p.name.name && spans_overlap(i.span, p.span))
                    .map(|i| i.local.clone())
                    .unwrap_or_else(|| p.name.name.clone())
            } else {
                p.name.name.clone()
            };
            top.insert(
                bound_as,
                LocalVar {
                    declared: ty.clone(),
                    narrowed: ty,
                    id,
                    links: Vec::new(),
                    is_param: true,
                    for_origin: None,
                    decl_span: p.name.span,
                    lambda_kept: false,
                    is_handler_state: false,
                    widened: None,
                    place_narrows: Vec::new(),
                    used: false,
                },
            );
        }
        // [implicit-group] A group's members are not in `f.params`, so they
        // are declared here. Kept, never consumable: an implicit belongs to
        // whoever supplied it, exactly like a kept fn-typed parameter.
        for imp in &implicits {
            if top.contains_key(&imp.local) {
                continue; // a written `?name: FnType` is already a param
            }
            let id = self.next_var_id;
            self.next_var_id += 1;
            top.insert(
                imp.local.clone(),
                LocalVar {
                    declared: imp.ty.clone(),
                    narrowed: imp.ty.clone(),
                    id,
                    links: Vec::new(),
                    is_param: true,
                    for_origin: None,
                    decl_span: imp.span,
                    lambda_kept: true,
                    is_handler_state: false,
                    widened: None,
                    place_narrows: Vec::new(),
                    used: false,
                },
            );
        }
        for field in state {
            // [handler-state-infer] The field's type: the written annotation, or the
            // type the checker inferred from the initializer (recorded at the
            // field-name span by the handler-state check).
            let ty = match &field.ty {
                Some(t) => self.lower_type(t),
                None => self
                    .out
                    .expr_ty
                    .get(&self.key(field.name.span))
                    .cloned()
                    .unwrap_or(Ty::Unknown),
            };
            self.out
                .expr_ty
                .entry(self.key(field.name.span))
                .or_insert_with(|| ty.clone());
            // [lsp-completion] A handler's (or `iter fn`'s) state field is a
            // local offered throughout the member body — the same as a
            // parameter — so a member referencing `notice_by_id` gets it
            // suggested (the two TODOs in salvo-noticeboard's disk.sv). It is
            // `always_in_scope` because a `state {}` block may be written
            // *after* the member that uses it.
            self.record_local_decl_scoped(&field.name, ty.clone(), true);
            let id = self.next_var_id;
            self.next_var_id += 1;
            top.insert(
                field.name.name.clone(),
                LocalVar {
                    declared: ty.clone(),
                    narrowed: ty,
                    id,
                    links: Vec::new(),
                    is_param: true,
                    for_origin: None,
                    decl_span: field.name.span,
                    lambda_kept: false,
                    is_handler_state: true,
                    widened: None,
                    place_narrows: Vec::new(),
                    used: false,
                },
            );
        }
        // [fn-param-default] Check each default value against its parameter's
        // type, with only the *earlier* parameters in scope (an argument is
        // computed left to right, so a default may read a parameter before
        // it but not after) and no effects available — so an effectful
        // default is rejected here, since it would silently colour every
        // caller that omits the argument. Checked once at the declaration;
        // the value is substituted fresh at each omitting call site, with an
        // earlier parameter it reads bound once (`Lower::args_for`) so no
        // ownership question depends on the parameter's type here.
        if f.params.iter().any(|p| p.default.is_some()) {
            let saved_env = std::mem::take(&mut self.effect_env);
            let mut scope: HashMap<String, LocalVar> = HashMap::new();
            self.locals.push(HashMap::new());
            for p in &f.params {
                if let Some(default) = &p.default {
                    *self.locals.last_mut().unwrap() = scope.clone();
                    let expected = self.lower_type(&p.ty).strip_spread();
                    self.check_default(default, &expected);
                }
                // The parameter joins the scope its own default could not see,
                // so a later parameter's default may read it.
                if let Some(lv) = top.get(&p.name.name) {
                    scope.insert(p.name.name.clone(), lv.clone());
                }
            }
            self.locals.pop();
            self.effect_env = saved_env;
        }
        self.locals.push(top);
        // [qual-depend] A parameter's declared dependent claim names
        // sibling parameters, and they are all in scope now: fill the
        // claim's fate roots, so inside the body the claim is *live* —
        // consumed by claim-demanding overloads and stripped by mutation
        // or reassignment of the depended-on value — exactly as an
        // `is`-established one. (The signature callers match against
        // stays a root-free template; this rooting is the body's view.
        // Gap found building the C family, 2026-09-24: `fn f(es: List<T>,
        // i: Idx(es) Int)` could not use the total `get` on its own
        // parameters.)
        self.root_declared_claims();
        let saved_mut_paths = std::mem::take(&mut self.own_mut_paths);
        self.check_block_value(body);
        // [deduce-field] A written field entry is a promise about *where*
        // this body mutates, and the caller's precision rests on it: every
        // mutation the body performed must be covered by a declared path,
        // or the narrowing would be a lie (2026-09-25).
        self.check_declared_mut_fields(f);
        self.own_mut_paths = saved_mut_paths;
        // [linear-state] A handler member must leave its state whole, and a
        // linear obligation must not leak: both are the IR's (`ir::flow`,
        // `ir::check`) [ir-analyze].
        self.locals.pop();
        // [fn-must-return] A fn with a non-`None` return type must return
        // on every path. Next-based iterator fns are exempt: their body
        // produces elements, not a return value.
        if !self.ret_ty.is_none_ty()
            && !matches!(self.ret_ty, Ty::Unknown)
            && !self.block_returns(body)
        {
            self.error(
                f.name.span,
                messages::fn_must_return_missing_return(&f.name.name, &self.ret_ty),
            );
        }
        self.effect_env = saved_env;
        self.can_use = saved_can_use;
        self.can_spawn = saved_can_spawn;
        self.own_implicits = saved_implicits;
        self.generics = saved_generics;
        self.cur_fn_body = None;
    }

    /// [fn-param-const] **A parameter cannot be assigned** (user decision
    /// 2026-09-25): parameters are constant bindings — the reading a future
    /// `const` will extend to struct fields, for scalars and non-scalars
    /// alike, so the rule is the same shape everywhere. A handler's *state*
    /// field is not a parameter in this sense and stays assignable.
    ///
    /// Before this the construct was accepted and then refused by the target
    /// compilers — Kotlin because parameters are `val`, and Rust for any
    /// borrowed one — a checker/emitter disagreement rather than a feature
    /// (ROADMAP's defect, filed 2026-09-25).
    fn reject_param_assignment(&mut self, name: &str, span: Span, how: &str) -> bool {
        let is_param = self
            .lookup(name)
            .is_some_and(|v| v.is_param && !v.is_handler_state && !v.lambda_kept);
        if !is_param {
            return false;
        }
        self.error(span, messages::fn_param_const_assigned(&how, &name));
        true
    }

    /// [deduce-field] Checks a written field-granular mutation entry
    /// against the body: each parameter with such entries may only be
    /// mutated at-or-below one of them. A mutation of the whole parameter
    /// (a call taking it as `Mut` without narrowing), a mutation of
    /// another field, or an unknown path is an error naming the remedy —
    /// without this the narrowing at call sites would be unfounded.
    fn check_declared_mut_fields(&mut self, f: &'p FnDecl) {
        if f.deductions.is_none() {
            return;
        }
        let mut reports: Vec<(Span, Message)> = Vec::new();
        for p in f.params.iter().filter(|p| !p.implicit) {
            let Some(declared) = Self::declared_mut_paths(f, &p.name.name) else {
                continue;
            };
            if declared.iter().any(|(d, _)| d.is_empty()) {
                continue; // `=> h: Mut` — anywhere, nothing to check.
            }
            let shown = |path: &[Step]| -> String {
                let mut out = p.name.name.clone();
                for s in path {
                    out.push_str(&s.to_string());
                }
                out
            };
            for (name, path, _) in self.own_mut_paths.clone() {
                if name != p.name.name {
                    continue;
                }
                let covered = match &path {
                    Some(actual) => declared
                        .iter()
                        .any(|(d, _)| actual.len() >= d.len() && actual[..d.len()] == d[..]),
                    None => false,
                };
                if covered {
                    continue;
                }
                let did = match &path {
                    Some(actual) if actual.is_empty() => {
                        format!("`{}` as a whole", p.name.name)
                    }
                    Some(actual) => format!("`{}`", shown(actual)),
                    None => format!("`{}` at a path it cannot spell", p.name.name),
                };
                let promised: Vec<String> = declared
                    .iter()
                    .map(|(d, _)| format!("`{}`", shown(d)))
                    .collect();
                reports.push((
                    p.name.span,
                    messages::deduce_field_unpromised_mutation(
                        &promised.join(", "),
                        &p.name.name,
                        &did,
                    ),
                ));
                break;
            }
        }
        for (span, msg) in reports {
            self.error(span, msg);
        }
    }

    /// [qual-depend] Roots the dependent claims declared on the current
    /// frame's parameters: every root-free `ValueRef` in a declared type
    /// resolves its written path against the sibling parameters. Two-pass
    /// (collect, then write) over the top frame.
    fn root_declared_claims(&mut self) {
        let Some(frame) = self.locals.last() else { return };
        // name -> ultimate roots, for path-base resolution.
        let roots_of: HashMap<String, Vec<u32>> = frame
            .iter()
            .map(|(name, var)| {
                let mut roots: Vec<u32> = var.links.iter().map(|l| l.root_id).collect();
                roots.sort_unstable();
                roots.dedup();
                if roots.is_empty() {
                    roots.push(var.id);
                }
                (name.clone(), roots)
            })
            .collect();
        fn fill(ty: &Ty, roots_of: &HashMap<String, Vec<u32>>) -> Ty {
            match ty {
                Ty::ValueRef { path, roots } if roots.is_empty() => {
                    let base = path.split('.').next().unwrap_or(path);
                    match roots_of.get(base) {
                        Some(r) => Ty::ValueRef {
                            path: path.clone(),
                            roots: r.clone(),
                        },
                        None => ty.clone(),
                    }
                }
                Ty::Qualified { quals, base } => Ty::Qualified {
                    quals: quals
                        .iter()
                        .map(|q| Qual {
                            effect: q.effect,
                            name: q.name.clone(),
                            args: q.args.iter().map(|a| fill(a, roots_of)).collect(),
                        })
                        .collect(),
                    base: Box::new(fill(base, roots_of)),
                },
                Ty::Named { name, args } => Ty::Named {
                    name: name.clone(),
                    args: args.iter().map(|a| fill(a, roots_of)).collect(),
                },
                Ty::Union(arms) => Ty::Union(arms.iter().map(|a| fill(a, roots_of)).collect()),
                Ty::Tuple(elems) => Ty::Tuple(elems.iter().map(|e| fill(e, roots_of)).collect()),
                Ty::Array(elem) => Ty::Array(Box::new(fill(elem, roots_of))),
                other => other.clone(),
            }
        }
        let updates: Vec<(String, Ty, Ty)> = frame
            .iter()
            .filter(|(_, var)| Self::ty_has_value_ref(&var.declared))
            .map(|(name, var)| {
                (
                    name.clone(),
                    fill(&var.declared, &roots_of),
                    fill(&var.narrowed, &roots_of),
                )
            })
            .collect();
        let Some(frame) = self.locals.last_mut() else { return };
        for (name, declared, narrowed) in updates {
            if let Some(var) = frame.get_mut(&name) {
                var.declared = declared;
                var.narrowed = narrowed;
            }
        }
    }

    // ================= effects =================

    /// Validates a fn's declared effect list and lowers it into the
    /// starting effect environment [effect-fn-deps] [effect-no-dup].
    /// Returns `(env, can_use, can_spawn, can_wait)`.
    fn check_effect_list(&mut self, f: &'p FnDecl) -> (Vec<EffectAvail>, bool, bool) {
        let mut env: Vec<EffectAvail> = Vec::new();
        let mut can_use = false;
        let mut can_spawn = false;
        // [fn-effects] A fn-typed parameter's effects are the enclosing fn's
        // too (user decision 2026-09-04): the only reason to take `f` is to
        // call it, and calling it needs those effects here — so they are
        // *inherited* rather than repeated in the written list. Callers
        // supply them like any declared effect. **Only where no list is
        // written** (user decision 2026-10-20): a written list, `[]`
        // included, is the whole set, so a body that handles a parameter's
        // effect itself (`try` around `f(n)`, `use` before it) can say so.
        //
        // Transitional (ROADMAP §2b): an inherited availability arrives as
        // the value's effect parameter, which the emitters do not mint a
        // handle from yet — so it is marked inline (`local`) here, which
        // refuses its capture until step ② makes it a handle.
        if f.effects.is_none() {
            for p in &f.params {
                for ty in self.inherited_fn_effects(&p.ty) {
                    if !env.iter().any(|a| a.ty == ty) {
                        env.push(EffectAvail { ty, declared: true, any: false });
                    }
                }
            }
        }
        for eff in f.effects.iter().flatten() {
            match eff {
                EffectRef::Use(_) => can_use = true,
                // [actor-spawn-effect] The actor-creation capability. It
                // names no effect type, so there is nothing to lower and
                // nothing to thread; what it does is open the *gate* a
                // `spawn` expression checks [actor-spawn-expr].
                EffectRef::Spawn(_) => can_spawn = true,
                _ => {}
            }
        }
        // [effect-handle] A named effect: an availability every binding of
        // which is a handle. [effect-alias] [effect-prereq] Aliases and
        // prerequisites are expanded here, the one place a fn's list is
        // lowered (PIPELINE.md R6).
        let mut written: Vec<Ty> = Vec::new();
        for e in self.expand_effect_refs(f.effects.as_deref().unwrap_or(&[]), true) {
            if e.origin == EffectOrigin::Written {
                if written.contains(&e.ty) {
                    self.error(e.span, messages::effect_no_dup_duplicate(&e.ty));
                    continue;
                }
                written.push(e.ty.clone());
            }
            // [effect-any] `any E` declares the weak availability: this body
            // may call `E` and callees declaring `[any E]`, never a callee
            // that assumes one instance.
            if !env.iter().any(|a| a.ty == e.ty) {
                env.push(EffectAvail { ty: e.ty, declared: true, any: e.any });
            }
        }
        (env, can_use, can_spawn)
    }

    /// [actor-mailbox] The `mailbox { capacity: … }` slot on a handler (user
    /// decision 2026-09-16). Three rules, and each one is why the slot is
    /// better placed here than at every spawn:
    ///
    /// * **required** on a handler of an `actor effect` — the queue depth has
    ///   no default, exactly as it had none at the spawn site, but now it is
    ///   stated once by the author who knows the protocol's traffic;
    /// * **refused** on a handler of a plain effect, where there is no queue to
    ///   bound (a synchronous handler's members run on the caller's thread);
    /// * its field expressions see **constructor parameters only**. The value
    ///   is wanted before the actor exists — the scheduler needs the bound at
    ///   spawn time, ahead of any state initialiser — so state fields are not
    ///   in scope, and an effect cannot be performed to compute it. Consuming
    ///   one of those parameters is refused by [effect-state-store] already
    ///   (the handler stores what it was built with), so there is no rule here
    ///   for it.
    ///
    /// The braces are a `Mailbox` struct literal with the type elided, so the
    /// field names, their types, a missing one and an unknown one are all the
    /// ordinary struct diagnostics.
    fn check_mailbox_slot(&mut self, h: &'p ast::HandlerDecl, of: &[Ty]) {
        // [effect-handler-multi] One mailbox serves every face: the effects a
        // handler implements are all of one kind, so *any* of them answers
        // whether there is a queue at all.
        let is_actor = of.iter().any(|of| match of.strip_quals() {
            Ty::Named { name, .. } => self
                .symbols
                .effects
                .get(name.as_str())
                .is_some_and(|e| e.is_actor),
            _ => false,
        });
        // [actor-mixed-handler] A mixed handler's servant has a mailbox too: its
        // handler-local `send fn` members are delivered through one, so the
        // requirement keys on "has send members" as much as on the faces'
        // kind.
        let has_queue = is_actor || h.fns.iter().any(|f| f.is_send);
        // [decl-interface-pass] Whether there is a slot is the header's question;
        // the slot's expression is checked in a frame of locals, the body
        // pass's.
        let (iface, body) = (self.pass.interface(), self.pass.body());
        match (&h.mailbox, has_queue) {
            (None, true) if iface => {
                self.error(
                    h.name.span,
                    messages::actor_mailbox_no_capacity(
                        &h.name.name,
                        &(if is_actor {
                            "it handles an actor effect"
                            } else {
                            "its `send fn` members are delivered through one"
                            }),
                    ),
                );
            }
            (Some(mailbox), false) if iface => {
                self.error(
                    mailbox.span(),
                    messages::actor_mailbox_nothing_to_enqueue(&h.name.name),
                );
            }
            (Some(mailbox), true) if body => {
                // Constructor parameters only: the bound is computed when the
                // handler is built, before any state exists.
                let mut top: HashMap<String, LocalVar> = HashMap::new();
                for p in &h.params {
                    let ty = self.lower_type(&p.ty);
                    let id = self.next_var_id;
                    self.next_var_id += 1;
                    top.insert(
                        p.name.name.clone(),
                        LocalVar {
                            declared: ty.clone(),
                            narrowed: ty,
                            id,
                            links: Vec::new(),
                            is_param: true,
                            for_origin: None,
                            decl_span: p.name.span,
                            lambda_kept: false,
                            is_handler_state: false,
                            widened: None,
                            place_narrows: Vec::new(),
                            used: true,
                        },
                    );
                }
                self.locals.push(top);
                let expected = Ty::named(MAILBOX_TYPE);
                let got = self.check_expr(mailbox, Some(&expected));
                if !got.is_unknown() && !is_subtype(&got, &expected) {
                    self.error(mailbox.span(), messages::actor_mailbox_slot_type(&expected, &got));
                }
                self.locals.pop();
                // Consuming a constructor parameter here needs no rule of its
                // own: [effect-state-store] already refuses it, because the
                // handler stores what it was built with — and its message names
                // `copy`, which is the remedy here too.
            }
            _ => {}
        }
    }

    /// [effect-alias] An alias names effects (or aliases), and its expansion
    /// must close: a cycle is reported here, at the declaration.
    fn check_effect_alias(&mut self, a: &'p ast::EffectAliasDecl) {
        for m in &a.effects {
            match m {
                EffectRef::Use(span) | EffectRef::Spawn(span) => self.error(
                    *span,
                    messages::effect_alias_capability(),
                ),
                EffectRef::AnyEffect(r) => self.error(r.span, messages::effect_alias_any()),
                EffectRef::Effect(r) => {
                    let mut stack = vec![a.name.name.clone()];
                    let mut sink = Vec::new();
                    self.expand_effect_entry(r, false, r.span, EffectOrigin::Alias(a.name.name.clone()), &mut stack, &mut sink);
                }
            }
        }
    }

    /// [effect-prereq] An effect's prerequisites, checked where they are
    /// written: named plain effects (or aliases of them), visible to whoever
    /// may name the effect, closing without a cycle. Records the list for the
    /// IR (`Checked::effect_prereqs`).
    fn check_effect_prereqs(&mut self, e: &'p ast::EffectDecl) {
        if e.prereqs.is_empty() {
            return;
        }
        let name = e.name.name.as_str();
        if e.is_actor {
            self.error(e.name.span, messages::effect_prereq_actor_effect(&name));
            return;
        }
        let saved = self.enter_generics(&e.generics);
        let mut listed: Vec<Ty> = Vec::new();
        for p in &e.prereqs {
            let r = match p {
                EffectRef::Use(span) | EffectRef::Spawn(span) => {
                    self.error(*span, messages::effect_prereq_capability());
                    continue;
                }
                EffectRef::AnyEffect(r) => {
                    self.error(r.span, messages::effect_prereq_any());
                    continue;
                }
                EffectRef::Effect(r) => r,
            };
            let pname = r.name.name.as_str();
            let m = self.named(r);
            if m.effect.is_none() && m.effect_alias.is_none() {
                self.error(r.span, messages::effect_prereq_unknown(&pname, &name));
                continue;
            }
            for m in self.expand_effect_refs(std::slice::from_ref(p), false) {
                let target = match m.ty.strip_quals() {
                    Ty::Named { name, .. } => self.symbols.effects.get(name.as_str()).copied(),
                    _ => None,
                };
                if let Some(t) = target {
                    if t.is_actor {
                        self.error(r.span, messages::effect_prereq_actor_prereq(&t.name.name));
                    }
                    if e.exported && !t.exported {
                        self.error(
                            r.span,
                            messages::effect_prereq_not_exported(&name, &t.name.name),
                        );
                    }
                }
                if !listed.contains(&m.ty) {
                    listed.push(m.ty);
                }
            }
        }
        self.generics = saved;
        let key = self.symbols.key_or(e, name).to_string();
        // A cycle: the effect implies itself.
        let mut seen: Vec<String> = vec![key.clone()];
        let mut chain: Vec<String> = vec![name.to_string()];
        if self.prereq_cycle(&key, &mut seen, &mut chain) {
            self.error(
                e.name.span,
                messages::effect_prereq_cycle(
                    &chain.iter().map(|n| format!("`{n}`")).collect::<Vec<_>>().join(" → "),
                ),
            );
        }
        self.out.effect_prereqs.insert(key, listed);
    }

    /// [effect-prereq] Whether following prerequisites from effect [key]
    /// comes back to the first effect of [seen]; [chain] is the path, by name.
    fn prereq_cycle(&mut self, key: &str, seen: &mut Vec<String>, chain: &mut Vec<String>) -> bool {
        let ty = Ty::Named { name: key.to_string(), args: Vec::new() };
        for (implied, _) in self.prerequisites_of(&ty) {
            let Ty::Named { name, .. } = implied.strip_quals() else { continue };
            let plain = crate::typekey::plain(name).to_string();
            if *name == seen[0] {
                chain.push(plain);
                return true;
            }
            if seen.contains(name) {
                continue;
            }
            seen.push(name.clone());
            chain.push(plain);
            if self.prereq_cycle(&name.clone(), seen, chain) {
                return true;
            }
            chain.pop();
        }
        false
    }

    /// [effect-alias] [effect-prereq] An effect list as the program means it
    /// (PIPELINE.md R6, replacing the AST rewrites that ran before
    /// resolution): every alias replaced by its members, resolved in the
    /// alias's own file, and — with [prereqs] — every effect's prerequisites
    /// added, resolved in the effect's own file with its type arguments
    /// substituted. Written entries are kept as written, duplicates included
    /// (the caller reports those); an alias member or a prerequisite already
    /// present is dropped. `use`/`spawn` entries are the caller's.
    fn expand_effect_refs(&mut self, list: &[EffectRef], prereqs: bool) -> Vec<ListedEffect> {
        let mut out = Vec::new();
        for eff in list {
            let (r, any) = match eff {
                EffectRef::Effect(r) => (r, false),
                EffectRef::AnyEffect(r) => (r, true),
                _ => continue,
            };
            self.expand_effect_entry(r, any, r.span, EffectOrigin::Written, &mut Vec::new(), &mut out);
        }
        if prereqs {
            self.add_prerequisites(&mut out);
        }
        out
    }

    /// [effect-alias] One entry: an effect, or an alias whose members are
    /// expanded in turn (a cycle is reported at [site]).
    fn expand_effect_entry(
        &mut self,
        r: &TypeRef,
        any: bool,
        site: Span,
        origin: EffectOrigin,
        stack: &mut Vec<String>,
        out: &mut Vec<ListedEffect>,
    ) {
        let name = r.name.name.as_str();
        if let Some((alias, _)) = self.named(r).effect_alias {
            if any {
                self.error(r.span, messages::effect_alias_any_alias(&name));
                return;
            }
            if stack.iter().any(|s| s == name) {
                let mut chain = stack.clone();
                chain.push(name.to_string());
                self.error(site, messages::effect_alias_cycle(&chain[0], &chain.join(" -> ")));
                return;
            }
            stack.push(name.to_string());
            let outer = match &origin {
                EffectOrigin::Alias(a) => a.clone(),
                _ => name.to_string(),
            };
            for m in &alias.effects {
                // `use`/`spawn`/`any` in an alias are refused at its declaration.
                if let EffectRef::Effect(mr) = m {
                    self.expand_effect_entry(mr, false, site, EffectOrigin::Alias(outer.clone()), stack, out);
                }
            }
            stack.pop();
            return;
        }
        let Some(ty) = self.lower_effect_ref(r) else { return };
        if origin != EffectOrigin::Written && out.iter().any(|e| e.ty == ty) {
            return;
        }
        out.push(ListedEffect { ty, any, span: site, origin });
    }

    /// [effect-prereq] Adds, transitively, what the listed effects imply.
    fn add_prerequisites(&mut self, out: &mut Vec<ListedEffect>) {
        let mut i = 0;
        // A generic prerequisite can grow without end (`Log<T> [Log<List<T>>]`);
        // the cap keeps that a finite list rather than a hang.
        while i < out.len() && out.len() < 64 {
            let (ty, span) = (out[i].ty.clone(), out[i].span);
            i += 1;
            for (implied, by) in self.prerequisites_of(&ty) {
                if !out.iter().any(|e| e.ty == implied) {
                    out.push(ListedEffect { ty: implied, any: false, span, origin: EffectOrigin::Prereq(by) });
                }
            }
        }
    }

    /// [effect-prereq] The direct prerequisites of one effect instance,
    /// resolved where the effect is declared, its generics substituted by the
    /// instance's arguments (`Log<T> [Sink<T>]` at `Log<Str>` is `Sink<Str>`),
    /// each with the effect's name. Diagnostics about the list are the
    /// declaration's, so none are reported here.
    fn prerequisites_of(&mut self, ty: &Ty) -> Vec<(Ty, String)> {
        let Ty::Named { name, args } = ty.strip_quals() else { return Vec::new() };
        let Some(decl) = self.symbols.effects.get(name.as_str()).copied() else { return Vec::new() };
        if decl.prereqs.is_empty() {
            return Vec::new();
        }
        let subst: HashMap<String, Ty> =
            decl.generics.iter().map(|g| g.name.clone()).zip(args.iter().cloned()).collect();
        let mark = self.out.errors.len();
        let saved = self.enter_generics(&decl.generics);
        let mut found: Vec<Ty> = Vec::new();
        for p in &decl.prereqs {
            let EffectRef::Effect(r) = p else { continue };
            let m = self.named(r);
            if m.effect_alias.is_some() {
                let mut members = Vec::new();
                self.expand_effect_entry(r, false, r.span, EffectOrigin::Written, &mut Vec::new(), &mut members);
                found.extend(members.into_iter().map(|m| m.ty));
            } else if m.effect.is_some() {
                found.push(self.lower_base_ref(r, &subst, 0));
            }
        }
        self.generics = saved;
        self.out.errors.truncate(mark);
        found.into_iter().map(|t| (t, decl.name.name.clone())).collect()
    }

    /// [effect-alias] [effect-prereq] `expand_effect_refs` reporting nothing:
    /// for a list another declaration wrote, whose diagnostics are its own.
    fn expand_effect_refs_quiet(&mut self, list: &[EffectRef], prereqs: bool) -> Vec<ListedEffect> {
        let mark = self.out.errors.len();
        let out = self.expand_effect_refs(list, prereqs);
        self.out.errors.truncate(mark);
        out
    }

    /// Lowers one named entry of an effect list, validating that it refers
    /// to a declared effect with the right number of type arguments.
    fn lower_effect_ref(&mut self, r: &TypeRef) -> Option<Ty> {
        let name = r.name.name.as_str();
        let Some(effect) = self.named(r).effect else {
            self.error_unresolved(r.span, messages::name_resolve_unknown_effect(&name), name);
            return None;
        };
        if r.args.len() != effect.generics.len() {
            self.error(
                r.span,
                messages::name_resolve_effect_type_arg_count(
                    &name,
                    &effect.generics.len(),
                    &r.args.len(),
                ),
            );
        }
        let empty = HashMap::new();
        Some(self.lower_base_ref(r, &empty, 0))
    }

    /// Rejects declared effect dependencies on effect/handler member fns
    /// [effect-member-no-effects]: dispatch call sites go through the
    /// handler instance and cannot thread extra handler arguments.
    fn reject_member_effects(&mut self, f: &'p FnDecl, what: &str) {
        for eff in f.effects.iter().flatten() {
            let span = match eff {
                EffectRef::Use(s) => *s,
                EffectRef::Spawn(s) => *s,
                EffectRef::Effect(r) | EffectRef::AnyEffect(r) => r.span,
            };
            self.error(span, messages::effect_member_no_effects_declared(&what));
        }
    }

    /// [actor-route-stub] A send member's `Key`-marked parameter is what a route
    /// over the protocol hashes, so a member marks at most one — refused at
    /// the effect's declaration whether or not anything routes it (user
    /// decision R7). The marks are recorded by member, since lowering erases
    /// the qualifier [qual-erasure].
    fn check_route_keys(&mut self, e: &'p ast::EffectDecl) {
        let mut keys: HashMap<String, String> = HashMap::new();
        for f in e.fns.iter().filter(|f| f.is_send) {
            let marked: Vec<&Param> = f
                .params
                .iter()
                .filter(|p| matches!(&p.ty, ast::Type::Named { qualifiers, .. } if qualifiers.iter().any(|q| self.is_route_key(q))))
                .collect();
            if marked.len() > 1 {
                self.error(
                    f.name.span,
                    messages::actor_route_stub_several_keys(
                        &e.name.name,
                        &f.name.name,
                        &marked.len(),
                    ),
                );
            }
            if let Some(p) = marked.first() {
                keys.insert(f.name.name.clone(), p.name.name.clone());
            }
        }
        if !keys.is_empty() {
            self.out.route_keys.insert(self.symbols.key_or(e, &e.name.name).to_string(), keys);
        }
    }

    /// [actor-route-stub] `use any group` (user decision R7, replacing `use
    /// route_any(group)`): `group` is a group handle, `eff[ActorGroup<X>]`
    /// for a non-generic actor effect `X`, and the statement binds `any X` —
    /// each send to whichever member the `RouteSelector<X>` in scope picks.
    /// The route itself is derived per routed protocol in the IR
    /// (`ir::build::actors`), so all the checker records is the protocol
    /// (`route_uses`), the selector it depends on (`use_deps`) and the face.
    fn check_use_any(&mut self, group: &'p Expr, span: Span) {
        let ty = self.check_expr(group, None);
        let effect = match addr_effect(&ty) {
            Some(Ty::Named { name, args }) if crate::typekey::plain(&name) == "ActorGroup" && args.len() == 1 => {
                match &args[0] {
                    Ty::Named { name, args }
                        if args.is_empty()
                            && self.symbols.effects.get(name.as_str()).is_some_and(|e| e.is_actor && e.fns.iter().any(|f| f.is_send)) =>
                    {
                        Some(args_free(name))
                    }
                    _ => None,
                }
            }
            _ => None,
        };
        fn args_free(name: &str) -> Ty {
            Ty::Named { name: name.to_string(), args: Vec::new() }
        }
        let Some(effect) = effect else {
            if !ty.is_unknown() {
                self.error(group.span(), messages::actor_route_stub_not_a_group(&ty));
            }
            return;
        };
        // The route keeps the handle: it reads the group's view on every send.
        self.fate_move(group, "store", group.span());
        let Ty::Named { name: effect_key, .. } = &effect else { unreachable!() };
        let shown = crate::typekey::plain(effect_key).to_string();
        // Its one dependency: the policy that picks the member.
        let selector = self.visible_avail().into_iter().find(|a| {
            matches!(a.ty.strip_quals(), Ty::Named { name, args }
                if crate::typekey::plain(name) == "RouteSelector" && args.len() == 1 && args[0] == effect)
        });
        let Some(selector) = selector else {
            self.error(span, messages::actor_route_stub_no_selector(&shown));
            // The route is refused, but it still says what it binds: the calls
            // after it are not a second mistake [type-unknown-lenient].
            self.effect_env.push(EffectAvail { ty: effect, declared: false, any: true });
            return;
        };
        self.out.route_uses.insert(self.key(span), effect_key.clone());
        self.out.use_deps.insert(self.key(span), vec![selector.ty]);
        self.out.use_effects.insert(self.key(span), vec![effect.clone()]);
        // [effect-any] A route promises no order: it binds the weak face.
        self.effect_env.push(EffectAvail { ty: effect, declared: false, any: true });
    }

    /// Checks a `use Handler(...)` statement [effect-use]: resolves the
    /// handler, types its constructor arguments (inferring the handler's
    /// generics from them), and registers the concrete effect instance in
    /// the current scope. A registration may **shadow** an earlier one for
    /// the same instance — innermost wins [effect-use-no-dup] — which is what makes
    /// interception writable [effect-intercept].
    fn check_use(
        &mut self,
        handler: &'p Expr,
        with_items: &'p [Expr],
        any: bool,
        span: Span,
    ) {
        if any {
            self.check_use_any(handler, span);
            return;
        }
        // [actor-use-addr] `use H(args) on POOL` — the sugar (SH-7, user
        // decision 2026-09-19): the parser wrapped the construction in a
        // spawn expression, so checking the expression *is* the spawn, and
        // binding its addr is exactly `use addr`. A multi-face handler
        // answers a tuple, which one binding cannot split — spawn it and
        // bind the faces yourself.
        if let Expr::Spawn { .. } = handler {
            // [effect-with-clause] The parser gave the clause to the spawn itself
            // (the instance is the child's), so nothing is left here.
            let ty = self.check_expr(handler, None);
            if matches!(ty, Ty::Tuple(_)) {
                self.error(span, messages::actor_use_addr_several_faces());
                return;
            }
            let Some(effect) = addr_effect(&ty) else {
                return;
            };
            self.out.use_addrs.insert(self.key(span), effect.clone());
            self.out
                .use_effects
                .insert(self.key(span), vec![effect.clone()]);
            self.effect_env.push(EffectAvail {
                ty: effect,
                declared: false,
                any: false,
            });
            return;
        }
        // [actor-use-addr] `use addr` binds an effect to a forwarding stub over
        // an `Addr` instead of constructing a handler: first-pass surface, and
        // no new syntax — which means telling the two apart is this
        // statement's job.
        if let Expr::Ident(id) = handler {
            if !self.scope.handlers.contains_key(id.name.as_str()) && self.lookup(&id.name).is_some()
            {
                // [effect-with-clause] A handle is a finished instance: its
                // dependencies were supplied where it was built.
                for item in with_items {
                    self.error(item.span(), messages::effect_with_clause_on_handle());
                    self.check_expr(item, None);
                }
                self.check_use_addr(handler, span);
                return;
            }
        }
        let construction = self.handler_construction(handler, "use");
        let Some((id, args, written_type_args, named)) = construction else {
            return;
        };
        let Some((concrete, deps)) =
            self.check_handler_construction(id, args, written_type_args, named, "use", span)
        else {
            return;
        };
        // [actor-replyto] A handler whose members mint a self-targeted
        // continuation may only be **spawned** (user decision 2026-09-15).
        // Bound with `use`, its member bodies run inline on the caller's
        // thread: the mint would target a member of a *local* instance, which
        // has no mailbox for the answer to arrive on and no dispatcher to run
        // it — so the continuation would silently never run. Parking is the
        // one thing only an actor can do, so this costs nothing real.
        //
        // The gate is syntactic per *handler* rather than per member, because
        // effects propagate: a fn declaring `[E]` may call any member, so a
        // `use` site cannot know which ones this scope will reach.
        //
        // [actor-mixed-handler] A mixed handler is spawn-only for the structural
        // reason below whether or not it parks, so its refusal speaks alone.
        let used = self.scope.handlers.get(id.name.as_str()).copied();
        let mixed = used.is_some_and(|h| self.handler_is_mixed(h));
        // [type-identity] The handler this file's name means, by key.
        let parks = used.is_some_and(|h| self.parking_handlers.contains(self.symbols.key_or(h, &h.name.name)));
        if !mixed && parks {
            self.error(span, messages::actor_replyto_use_bound(&id.name));
        }
        // [actor-mixed-handler] The same reasoning, structural: a mixed handler's
        // sync members send to the servant and wait for its answers, so
        // bound with `use` they would send toward an instance with no
        // mailbox and no dispatcher. Spawn-only, refused where the binding
        // is chosen.
        if mixed {
            self.error(span, messages::actor_mixed_handler_use_bound(&id.name));
        }
        // [actor-deadlock-cycle] A construction inside a handler's member
        // runs the constructed handler's members inline, so "may wait"
        // propagates through it — the record the graph's fixpoint reads.
        if let Some(h) = self.own_handler {
            self.out.handler_constructs.push((
                h.name.name.clone(),
                id.name.clone(),
                self.key(span),
            ));
        }
        let _ = mixed;
        self.finish_use(id, concrete, deps, with_items, span);
    }

    /// [effect-with-clause] One item of a `use`'s `with` clause: the effect
    /// instance it supplies. A handler *name or construction* is a **private
    /// instance** — built here, owned by the handler being registered,
    /// unshared with the scope (user decision 2026-09-20) — and an `Addr`
    /// is an existing handle. The same two shapes a spawn's clause takes,
    /// and the same two `use` itself binds, which is what makes a dependency
    /// swappable between a private handler and a shared one without
    /// touching the handler that depends on it.
    fn check_with_item(&mut self, item: &'p Expr) -> Option<Ty> {
        let is_handler = match item {
            Expr::Ident(id) => self.scope.handlers.contains_key(id.name.as_str()),
            Expr::Call { callee, .. } => match callee.as_ref() {
                Expr::Ident(id) => self.scope.handlers.contains_key(id.name.as_str()),
                _ => false,
            },
            _ => false,
        };
        if !is_handler {
            let ty = self.check_expr(item, None);
            return match addr_effect(&ty) {
                Some(effect) => Some(effect),
                None if ty.is_unknown() => None,
                None => {
                    self.error(item.span(), messages::effect_with_clause_not_a_handler(&ty));
                    None
                }
            };
        }
        let (id, args, type_args, named) = self.handler_construction(item, "with")?;
        let (effects, deps) =
            self.check_handler_construction(id, args, type_args, named, "with", item.span())?;
        let effect = effects.first().cloned().unwrap_or(Ty::Unknown);
        // [effect-handler-multi] A multi-face handler in the clause would
        // supply two dependencies from one private instance, and the clause
        // builds one instance per item — so the shape has nowhere to put the
        // second face. Bind it with its own `use` and name the addr.
        if effects.len() > 1 {
            let faces: Vec<String> = effects.iter().map(|e| e.to_string()).collect();
            self.error(
                item.span(),
                messages::effect_with_clause_several_faces(&id.name, &faces.join(", ")),
            );
        }
        // A private instance's *own* dependencies would have to resolve
        // somewhere, and the clause is not a scope: refused where written.
        for dep in &deps {
            let dep = &dep.ty;
            self.error(item.span(), messages::effect_with_clause_has_dependencies(&id.name, &dep));
        }
        Some(effect)
    }

    /// [actor-spawn-inherit] A declared dependency the `with` clause did not
    /// cover, resolved from the **spawning scope** (user decision
    /// 2026-09-20): the availability is captured as an owned handle and
    /// crosses the seam with the child, which is sound because every binding
    /// is a handle [effect-handle]. Answers the resolved instance, or `None`
    /// after reporting why it could not be synthesized.
    ///
    /// Two refusals, each named: an **ambiguity** between compatible
    /// instances (a guess is not the checker's to make), and **nothing in
    /// scope** (naming both remedies).
    fn synthesized_spawn_dep(
        &mut self,
        want: &Ty,
        visible: &[EffectAvail],
        id: &'p Ident,
        span: Span,
    ) -> Option<Ty> {
        let exact = visible.iter().find(|c| c.ty == *want).cloned();
        let found = match exact {
            Some(avail) => Some(avail),
            None => {
                let compatible: Vec<&EffectAvail> = visible
                    .iter()
                    .filter(|c| unify(want, &c.ty, &mut HashMap::new()))
                    .collect();
                match compatible.len() {
                    1 => Some(compatible[0].clone()),
                    0 => None,
                    _ => {
                        self.error(
                            span,
                            messages::actor_spawn_inherit_ambiguous_dep(
                                &id.name,
                                &want,
                                &compatible
                                    .iter()
                                    .map(|c| c.ty.to_string())
                                    .collect::<Vec<_>>()
                                    .join(", "),
                            ),
                        );
                        return None;
                    }
                }
            }
        };
        let Some(avail) = found else {
            self.error(span, messages::actor_spawn_inherit_missing_dep(&id.name, &want));
            return None;
        };
        Some(avail.ty)
    }

    /// [actor-use-addr] `use addr` — bind the effect an actor serves in this
    /// scope, so its members are callable unqualified *and* can travel down
    /// through ordinary effect lists (`fn drive() [Roll]`). The addr is not
    /// consumed: an addr is freely copyable, and a send to a dead actor is a
    /// no-op, so binding one takes nothing away from the holder.
    fn check_use_addr(&mut self, addr: &'p Expr, span: Span) {
        let ty = self.check_expr(addr, None);
        // [effect-eff-handle] `use <tuple>`: a value of tuple type whose elements are
        // all single handles (`e: (eff[A], eff[B])`) binds every effect in it,
        // in order — `use e.0; use e.1`. A nested tuple flattens the same way.
        if let Ty::Tuple(_) = ty.strip_quals() {
            let mut effects: Vec<Ty> = Vec::new();
            if self.collect_handle_tuple(&ty, &mut effects) && !effects.is_empty() {
                for effect in &effects {
                    self.effect_env.push(EffectAvail { ty: effect.clone(), declared: false, any: false });
                }
                self.out.use_addr_tuples.insert(self.key(span), effects.clone());
                self.out.use_effects.insert(self.key(span), effects);
                return;
            }
            // A tuple that is not all handles is not a thing `use` can bind.
            self.error(span, messages::actor_use_addr_tuple(&ty));
            return;
        }
        let Some(effect) = addr_effect(&ty) else {
            if !ty.is_unknown() {
                self.error(span, messages::actor_use_addr_not_a_handle(&ty));
            }
            return;
        };
        // [actor-effect-kind] Binding an addr binds an actor's protocol —
        // or, since SH-3 [actor-monitor-handler], a shared monitor of a plain
        // effect: both kinds are handles a `use` puts in scope, and no call
        // site learns the difference.
        self.out.use_addrs.insert(self.key(span), effect.clone());
        self.out
            .use_effects
            .insert(self.key(span), vec![effect.clone()]);
        self.effect_env.push(EffectAvail {
            ty: effect,
            declared: false,
            any: false,
        });
    }

    /// [effect-eff-handle] Flatten a tuple of single handles into its effect set,
    /// recursing through nested tuples. Returns false if any leaf is not a
    /// single-effect handle (then `use` of it is not meaningful).
    fn collect_handle_tuple(&self, ty: &Ty, out: &mut Vec<Ty>) -> bool {
        match ty.strip_quals() {
            Ty::Tuple(elems) => elems.iter().all(|e| self.collect_handle_tuple(e, out)),
            other => match addr_effect(other) {
                Some(effect) => {
                    out.push(effect);
                    true
                }
                None => false,
            },
        }
    }

    /// The written shape of a handler construction — a name, or a name with
    /// constructor arguments — shared by `use` and `spawn`, since only those
    /// two may write one ([handler-not-value] means it is not an expression).
    fn handler_construction(
        &mut self,
        handler: &'p Expr,
        form: &str,
    ) -> Option<(&'p Ident, &'p [Expr], &'p [ast::Type], &'p [ast::NamedArg])> {
        match handler {
            Expr::Ident(id) => Some((id, &[], &[], &[])),
            Expr::Call {
                callee,
                args,
                type_args,
                named,
                ..
            } => match callee.as_ref() {
                Expr::Ident(id) => Some((id, args.as_slice(), type_args.as_slice(), named.as_slice())),
                _ => {
                    let span = handler.span();
                    self.error(span, messages::handler_not_value_construction(&form));
                    self.check_expr(handler, None);
                    None
                }
            },
            _ => {
                let span = handler.span();
                self.error(span, messages::handler_not_value_construction(&form));
                self.check_expr(handler, None);
                None
            }
        }
    }

    /// Checks a handler *construction*: resolves the handler, types its
    /// constructor arguments (inferring its generics from them and from any
    /// written type arguments), consumes what it stores, and fills the
    /// constructor's implicits. Answers the concrete effect instance it
    /// implements — one per declared face [effect-handler-multi], in
    /// declaration order — and its **dependencies, already substituted**:
    /// everything both `use` and `spawn` need before they part ways over
    /// *where* those dependencies come from.
    fn check_handler_construction(
        &mut self,
        id: &'p Ident,
        args: &'p [Expr],
        written_type_args: &'p [ast::Type],
        named: &'p [ast::NamedArg],
        form: &str,
        span: Span,
    ) -> Option<(Vec<Ty>, Vec<EffectAvail>)> {
        let Some(decl) = self.scope.handlers.get(id.name.as_str()).copied() else {
            self.error_unresolved(
                id.span,
                messages::name_resolve_unknown_handler(&id.name, &form),
                &id.name,
            );
            for a in args {
                self.check_expr(a, None);
            }
            return None;
        };
        let saved = self.enter_generics(&decl.generics);
        // [effect-handler-deps] Split the constructor parameters: those of
        // effect type are *dependencies* the compiler supplies from the
        // enclosing scope, and are not written at the `use` site; every
        // constructor parameter is therefore ordinary data.
        let deps: Vec<EffectAvail> = self.handler_dep_effects(decl);
        let value_params: Vec<&Param> = decl.params.iter().filter(|p| !p.implicit).collect();
        let param_tys: Vec<Ty> = value_params
            .iter()
            .map(|p| self.lower_type(&p.ty))
            .collect();
        let of_tys: Vec<Ty> = decl.of.iter().map(|t| self.lower_type(t)).collect();
        self.generics = saved;
        // [lsp-definition] the handler name points at its declaration.
        self.record_def_ref(id.span, &id.name);

        let has_variadic = value_params.iter().any(|p| p.variadic);
        // [fn-param-default] Which constructor parameter each written value
        // fills, as `(parameter index, value)`: the positional arguments in
        // order, then each `name = value` naming a value parameter — the
        // same matching a fn call does before implicit resolution
        // (`call_fixed_params`). A name matching an implicit parameter is an
        // override [implicit-override], left to `fill_implicits`; any other
        // name is refused there, or here when there is no implicit to hand
        // it to.
        let mut given: Vec<(usize, &'p Expr)> = args.iter().enumerate().collect();
        let mut by_name = vec![false; value_params.len()];
        let has_implicits = decl.params.iter().any(|p| p.implicit);
        for a in named {
            let Some(i) = value_params.iter().position(|p| p.name.name == a.name.name) else {
                if !has_implicits {
                    self.error(
                        a.span,
                        messages::implicit_override_no_implicit(&id.name, &a.name.name),
                    );
                    self.check_expr(&a.value, None);
                }
                continue;
            };
            let p = value_params[i];
            if p.default.is_none() {
                self.error(a.span, messages::fn_param_default_named_without_default(&a.name.name));
            }
            let refused = if has_variadic {
                Some(messages::fn_param_default_variadic_named(&id.name))
            } else if i < args.len() {
                Some(messages::fn_param_default_named_and_positional(&a.name.name))
            } else if by_name[i] {
                Some(messages::fn_param_default_named_twice(&a.name.name))
            } else {
                None
            };
            match refused {
                Some(msg) => {
                    self.error(a.span, msg);
                    self.check_expr(&a.value, None);
                }
                None => {
                    by_name[i] = true;
                    given.push((i, &a.value));
                }
            }
        }
        if !has_variadic {
            let too_many = args.len() > value_params.len();
            let missing: Vec<String> = value_params
                .iter()
                .enumerate()
                .filter(|(i, p)| *i >= args.len() && !by_name[*i] && p.default.is_none())
                .map(|(_, p)| format!("`{}`", p.name.name))
                .collect();
            if too_many || !missing.is_empty() {
                let dep_note = if deps.is_empty() {
                    String::new()
                } else {
                    format!(
                        " (its {} effect dependenc{} come from the enclosing scope)",
                        deps.len(),
                        if deps.len() == 1 { "y" } else { "ies" }
                    )
                };
                let msg = if !value_params.iter().any(|p| p.default.is_some()) {
                    messages::fn_param_default_handler_arg_count(
                        &id.name,
                        &value_params.len(),
                        &args.len(),
                        &dep_note,
                    )
                } else if too_many {
                    messages::fn_param_default_handler_too_many(
                        &id.name,
                        &value_params.len(),
                        &args.len(),
                        &dep_note,
                    )
                } else {
                    messages::fn_param_default_handler_missing(
                        &id.name,
                        &missing.join(", "),
                        &(if missing.len() == 1 { "s" } else { "ve" }),
                        &dep_note,
                    )
                };
                self.error(span, msg);
            }
        }
        // A lambda argument takes its parameter types from the constructor
        // parameter's fn type, as a call's argument does — unless that type
        // is still open in the handler's own generics.
        let own_generics: HashSet<String> = decl.generics.iter().map(|g| g.name.clone()).collect();
        let arg_tys: Vec<Ty> = given
            .iter()
            .map(|&(i, a)| {
                let expected = param_tys
                    .get(i)
                    .filter(|t| matches!(a, Expr::Lambda { .. }) && !ty_mentions_vars(t, &own_generics));
                self.check_expr(a, expected)
            })
            .collect();
        // A handler-constructor argument is stored in the handler for the
        // rest of the scope: passing a bare identifier moves it
        // [deduce-consume].
        for &(_, a) in &given {
            self.fate_move(a, "store", a.span());
        }
        let mut subst: HashMap<String, Ty> = HashMap::new();
        // [effect-handler-generics] A `use` may write the handler's type
        // arguments (`use Plain<Int>()`), and for a handler with no
        // constructor argument to infer from, that is the *only* thing that
        // can bind them — so they are read first, and a constructor argument
        // that disagrees is the error rather than the winner.
        if !written_type_args.is_empty() {
            if written_type_args.len() != decl.generics.len() {
                self.error(
                    id.span,
                    messages::effect_handler_generics_type_arg_count(
                        &id.name,
                        &decl.generics.len(),
                        &written_type_args.len(),
                    ),
                );
            }
            for (g, ta) in decl.generics.iter().zip(written_type_args) {
                let lowered = self.lower_type(ta);
                subst.insert(g.name.clone(), lowered);
            }
        }
        for (&(i, _), a) in given.iter().zip(&arg_tys) {
            let Some(p) = param_tys.get(i) else { continue };
            let mut from_args: HashMap<String, Ty> = HashMap::new();
            unify(p, a, &mut from_args);
            for (name, ty) in from_args {
                match subst.get(&name) {
                    Some(written) if !ty.is_unknown() && !is_subtype(&ty, written) => {
                        self.error(
                            span,
                            messages::effect_handler_generics_conflict(
                                &id.name,
                                &name,
                                &written,
                                &ty,
                            ),
                        );
                    }
                    Some(_) => {}
                    None => {
                        subst.insert(name, ty);
                    }
                }
            }
        }
        let generic_set: HashSet<String> = decl.generics.iter().map(|g| g.name.clone()).collect();
        // The handler's own type arguments, in declaration order, for the
        // emitters: a generic handler has to be *constructed* at a type
        // (`Plain<Int>()`, `Plain::<i32>::new()`), which neither target can
        // infer from an empty argument list.
        if !decl.generics.is_empty() {
            let args: Vec<Ty> = decl
                .generics
                .iter()
                .map(|g| subst.get(&g.name).cloned().unwrap_or(Ty::Unknown))
                .collect();
            self.out.use_handler_args.insert(self.key(span), args);
        }
        // Record argument coercions against the substituted param types.
        for (&(i, arg), logical) in given.iter().zip(&arg_tys) {
            let Some(p) = param_tys.get(i) else { continue };
            let sp = substitute_vars(p, &subst, &generic_set);
            let logical = logical.clone();
            let repr = self.repr_of(arg, &logical);
            self.maybe_coerce(arg.span(), &logical, &repr, &sp);
            // A constructor argument has to *fit* its parameter, exactly as a
            // call's argument does — a handler has no overload set, so nothing
            // else was reporting it and a claim the parameter demands
            // (`numbers: NE List<Double>`) was accepted from a value that does
            // not carry it. The argument is stored, so the position is owned.
            if !logical.is_unknown() && !self.arg_fits_param(&logical, &sp, false) {
                let pname = value_params
                    .get(i)
                    .map(|p| p.name.name.clone())
                    .unwrap_or_else(|| format!("argument {}", i + 1));
                self.error(
                    arg.span(),
                    messages::effect_handler_generics_arg_mismatch(&id.name, &pname, &sp, &logical),
                );
            }
        }
        // [copy-implicit] The constructor's implicit parameters are filled
        // here, at the handler's now-known type arguments — recorded under
        // the `use` span, where the emitters build the instance.
        let ctor_implicits: Vec<ImplicitParam> = {
            let saved = self.enter_generics(&decl.generics);
            let list = decl
                .params
                .iter()
                .filter(|p| p.implicit)
                .map(|p| ImplicitParam {
                    name: p.name.name.clone(),
                    ty: self.lower_type(&p.ty),
                    span: p.span,
                    borrowed_arms: Vec::new(),
                    binder: false,
                    slot: None,
                    bound: None,
                    local: p.name.name.clone(),
                })
                .collect();
            self.generics = saved;
            list
        };
        if !ctor_implicits.is_empty() {
            let mut subst = subst.clone();
            // [fn-param-default] The names that filled value parameters above
            // are this construction's, not unknown implicits.
            let fixed: HashSet<String> = value_params.iter().map(|p| p.name.name.clone()).collect();
            let saved_fixed = std::mem::replace(&mut self.call_fixed_params, fixed);
            self.fill_implicits(&ctor_implicits, &id.name, &mut subst, &generic_set, named, span);
            self.call_fixed_params = saved_fixed;
        }
        let concrete: Vec<Ty> = of_tys
            .iter()
            .map(|of| substitute_vars(of, &subst, &generic_set))
            .collect();
        let deps: Vec<EffectAvail> = deps
            .iter()
            .map(|d| EffectAvail {
                ty: substitute_vars(&d.ty, &subst, &generic_set),
                declared: d.declared,
                any: d.any,
            })
            .collect();
        Some((concrete, deps))
    }

    /// The `use`-specific half: resolve the handler's dependencies from the
    /// **enclosing scope** and register the instance for the rest of it.
    fn finish_use(
        &mut self,
        id: &'p Ident,
        concrete: Vec<Ty>,
        deps: Vec<EffectAvail>,
        with_items: &'p [Expr],
        span: Span,
    ) {
        // [effect-use-no-dup] [effect-intercept] A `use` may *shadow* an earlier
        // registration for the same effect instance: the innermost wins for
        // the rest of the scope, which is what makes interception writable
        // (`use DefaultFs()` then `use RestrictedFs(root)`). What stays an
        // error is registering the same handler *instance* twice — and under
        // [handler-not-value] an instance exists only at its `use`, so that
        // clause is future-proofing rather than a check.
        // [effect-handler-deps] Every dependency must already have a handler
        // here: the registration is what wires them together, so this is the
        // point where "who provides it" is decided. Resolved instances are
        // recorded for the emitters, in declaration order. The lookup runs
        // *before* this `use` is registered, which is exactly the
        // binds-outward rule for a self-dependency [effect-intercept].
        let mut resolved_deps: Vec<Ty> = Vec::new();
        // [effect-with-clause] The written clause items, typed once, each carrying
        // the index the program wrote it at: the matching below drains them,
        // so a matched dep remembers *which* item satisfied it and the
        // emitters need not re-derive the pairing (`spawn_dep_items`' rule,
        // for the `use` side).
        let mut supplied: Vec<(Ty, Span, usize)> = Vec::new();
        for (at, item) in with_items.iter().enumerate() {
            if let Some(eff) = self.check_with_item(item) {
                supplied.push((eff, item.span(), at));
            }
        }
        // One entry per declared dependency, in declaration order: the
        // clause item that satisfied it, or `None` for a scope-resolved one.
        let mut items: Vec<Option<usize>> = Vec::new();
        let visible = self.visible_avail();
        for want in &deps {
            let want = want.ty.clone();
            // [effect-with-clause] A written item wins for the dep it matches —
            // partial clauses are the rule (user decision 2026-09-20), so
            // the rest still resolve from scope. The self-dependency may be
            // supplied too ([effect-intercept]'s written exception): an
            // interceptor then wraps the clause's private instance instead
            // of the scope's registration.
            let from_clause = supplied
                .iter()
                .position(|(eff, _, _)| *eff == want)
                .or_else(|| {
                    supplied
                        .iter()
                        .position(|(eff, _, _)| unify(&want, eff, &mut HashMap::new()))
                });
            if let Some(i) = from_clause {
                let (eff, _, at) = supplied.remove(i);
                resolved_deps.push(eff);
                items.push(Some(at));
                continue;
            }
            let found = visible
                .iter()
                .find(|c| c.ty == want)
                .cloned()
                .or_else(|| {
                    let compatible: Vec<&EffectAvail> = visible
                        .iter()
                        .filter(|c| unify(&want, &c.ty, &mut HashMap::new()))
                        .collect();
                    match compatible.len() {
                        1 => Some(compatible[0].clone()),
                        _ => None,
                    }
                });
            match found {
                Some(avail) => {
                    // [actor-spawn-inherit] [effect-handle] A capture over a
                    // **signature-supplied** effect is legal: the effect
                    // parameter *is* a handle.
                    resolved_deps.push(avail.ty);
                    items.push(None);
                }
                // [effect-intercept] A self-dependency binds *outward*, so
                // "nothing in scope" means there is nothing to intercept —
                // worth its own wording, since the remedy is not "register a
                // different handler first" but "register the one you are
                // wrapping".
                None if concrete.contains(&want) => self.error(
                    span,
                    messages::effect_intercept_nothing_to_wrap(&id.name, &want),
                ),
                None => {
                    // [effect-prereq] A dependency the handler never wrote is a
                    // prerequisite of an effect it implements: say which, since
                    // the reader looking at the handler will not find it.
                    let implied_by = self
                        .symbols
                        .handlers
                        .get(self.out.value_key(id))
                        .copied()
                        .and_then(|h| {
                            self.handler_dep_list(h).into_iter().find_map(|e| match e.origin {
                                EffectOrigin::Prereq(face) if e.ty == want => Some(face),
                                _ => None,
                            })
                        });
                    match implied_by {
                        Some(face) => self.error(
                            span,
                            messages::effect_prereq_face_needs(&id.name, &face, &want),
                        ),
                        None => self.error(
                            span,
                            messages::effect_handler_deps_missing(&id.name, &want),
                        ),
                    }
                }
            }
        }
        // [effect-with-clause] Anything left over was supplied for nothing — worth
        // naming, since the reader believes it is being used.
        for (eff, sp, _) in &supplied {
            self.error(*sp, messages::effect_with_clause_not_a_dep(&id.name, &eff));
        }
        if !resolved_deps.is_empty() {
            self.out.use_deps.insert(self.key(span), resolved_deps);
            if items.iter().any(|i| i.is_some()) {
                self.out.use_with_items.insert(self.key(span), items);
            }
        }
        // [effect-handler-multi] Every face is registered, in declaration
        // order: one instance, one binding per effect it implements, so a
        // caller reaches whichever face its own effect list names.
        self.out
            .use_effects
            .insert(self.key(span), concrete.clone());
        // [effect-any] A face written `of any E` binds the weak
        // availability: the handler forwards to many instances and promises
        // no order, so only a `[any E]` requirement may lean on it.
        let of_any: Vec<bool> = self
            .scope
            .handlers
            .get(id.name.as_str())
            .map(|d| d.of_any.clone())
            .unwrap_or_default();
        for effect in &concrete {
            self.refuse_erased_sibling(effect, span);
        }
        for (i, effect) in concrete.into_iter().enumerate() {
            self.effect_env.push(EffectAvail {
                ty: effect,
                declared: false,
                any: of_any.get(i).copied().unwrap_or(false),
            });
        }
    }

    // ================= scopes, locals, narrowing =================

    /// [effect-generic-decl] Two instances of an effect whose arguments are
    /// all effects — `RouteSelector<Sequencer>` beside `RouteSelector<Inventory>` — erase to
    /// **one** type in the output, so one scope cannot hold both: the emitters
    /// would implement one accessor twice (and the second would win silently
    /// in a fusion frame). Refused at the second `use`, naming the fix: a
    /// nested block, since a binding lasts for its scope.
    fn refuse_erased_sibling(&mut self, effect: &Ty, span: Span) {
        let Ty::Named { name, args } = effect.strip_quals() else { return };
        if args.is_empty() {
            return;
        }
        let effect_only = args.iter().all(|a| {
            matches!(a, Ty::Named { name, args } if args.is_empty() && self.symbols.effects.contains_key(name.as_str()))
        });
        if !effect_only {
            return;
        }
        let sibling = self.visible_avail().into_iter().find(|a| {
            matches!(a.ty.strip_quals(), Ty::Named { name: n, args: other } if n == name && other != args)
        });
        if let Some(sibling) = sibling {
            self.error(
                span,
                messages::effect_generic_decl_sibling_bound(&effect, &sibling.ty, &name),
            );
        }
    }

    /// [effect-use-no-dup] [effect-intercept] The effect instances visible here,
    /// **innermost first, shadowed duplicates hidden**. `effect_env` is a
    /// stack that a `use` pushes onto and a block truncates
    /// ([effect-scope]); since a `use` may shadow an earlier registration
    /// of the same instance, every lookup has to read it as a scope rather
    /// than as a set — otherwise the *outer* handler would answer a member
    /// call the inner one shadowed, and an intercepting handler would
    /// silently never run.
    fn visible_effects(&self) -> Vec<Ty> {
        self.visible_avail().into_iter().map(|a| a.ty).collect()
    }

    /// The availability-aware sibling: same visibility rule, with
    /// each instance's availability record.
    fn visible_avail(&self) -> Vec<EffectAvail> {
        let mut out: Vec<EffectAvail> = Vec::new();
        for avail in self.effect_env.iter().rev() {
            if !out.iter().any(|a| a.ty == avail.ty) {
                out.push(avail.clone());
            }
        }
        out
    }

    fn enter_generics(&mut self, generics: &[Ident]) -> HashSet<String> {
        let saved = self.generics.clone();
        for g in generics {
            self.generics.insert(g.name.clone());
        }
        saved
    }

    fn lookup(&self, name: &str) -> Option<&LocalVar> {
        self.locals.iter().rev().find_map(|s| s.get(name))
    }

    /// [name-table] [effect-available] That the effect members resolution
    /// found for a bare name (its scope's, and those of the effects its body
    /// has from what is written) are the ones the checker's availability
    /// gives — where resolution could see every availability in scope (a
    /// debug build checks; the checker still keeps its own availability,
    /// since a `use` of a handle or a lambda's fn type is the type phase's).
    #[cfg(debug_assertions)]
    fn check_value_members(&self, id: &Ident) {
        let Some(w) = self.resolution.names.value(id) else { return };
        if w.local.is_some() || w.role != crate::names::ValueRole::Bare || w.dynamic {
            return;
        }
        let names = &self.resolution.names;
        let mut table: Vec<usize> = names
            .value_meaning(w)
            .members
            .iter()
            .chain(names.available_members(w))
            .map(|(_, f)| *f as *const FnDecl as usize)
            .collect();
        let mut here: Vec<usize> =
            self.effect_members_here(&id.name).unwrap_or_default().iter().map(|(_, f)| *f as *const FnDecl as usize).collect();
        table.sort_unstable();
        table.dedup();
        here.sort_unstable();
        here.dedup();
        assert!(
            table == here,
            "[name-table] `{}` at {}..{}: resolution found {} effect member(s), the checker's availability {}",
            id.name,
            id.span.start,
            id.span.end,
            table.len(),
            here.len(),
        );
    }

    /// [name-table] That the binding resolution gave a variable read is the
    /// one this checker's scopes find (both by its name's span) — or that
    /// neither finds one. The two state one scoping rule twice until the
    /// checker reads locals by binding (PIPELINE.md C3).
    #[cfg(debug_assertions)]
    fn check_value_binding(&self, id: &Ident) {
        let Some(w) = self.resolution.names.value(id) else { return };
        let here = self.lookup(&id.name).map(|v| v.decl_span);
        let agree = match (here, w.local) {
            (Some(a), Some(b)) => a.node == b.node || (a.start <= b.start && b.end <= a.end) || (b.start <= a.start && a.end <= b.end),
            (None, None) => true,
            _ => false,
        };
        assert!(
            agree,
            "[name-table] `{}` at {}..{}: resolution bound it to {:?}, the checker's scopes to {:?}",
            id.name,
            id.span.start,
            id.span.end,
            w.local.map(|s| (s.start, s.end)),
            here.map(|s| (s.start, s.end)),
        );
    }

    /// Records a non-fn name use as pointing at its declaration's
    /// identifier [lsp-definition]. Silent when the name resolves to
    /// nothing visible (locals, generics, backend interop).
    /// [lsp-definition] Whether a written type reference is another file's:
    /// a callee's signature or a struct's field lowered at a use here. Its
    /// own file records what it points at; recording it here keyed it by
    /// this file and that file's span, a position in this file it does not
    /// occupy (found 2026-10-20, when the interface pass changed which
    /// writer came last: `list_dir`'s body overwrote `read_all`'s `Str` in
    /// `lib/std/fs/mem.sv` with a callee's `Int`).
    fn foreign_ref(&self, r: &TypeRef) -> bool {
        self.written_file(r).is_some_and(|f| f != self.file_idx)
    }

    /// [name-table] The file that wrote `r` (a copy found by its node).
    fn written_file(&self, r: &TypeRef) -> Option<usize> {
        self.resolution.names.written(r).map(|w| w.file as usize)
    }

    /// [name-table] What a written reference means where it is written; for
    /// a reference the checker made up, what its name means here.
    fn named(&self, r: &TypeRef) -> std::borrow::Cow<'r, crate::names::Meaning<'p>> {
        match self.resolution.names.written(r) {
            Some(w) => std::borrow::Cow::Borrowed(self.resolution.names.meaning(w)),
            None => std::borrow::Cow::Owned(crate::names::Meaning::of(self.scope, &r.name.name)),
        }
    }

    /// [name-table] Whether `r` names a type parameter: one of the
    /// declaration it is written in, or (for a reference the checker made
    /// up) one in scope here.
    fn names_generic(&self, r: &TypeRef) -> bool {
        match self.resolution.names.written(r) {
            Some(w) => w.generic || self.generics.contains(r.name.name.as_str()),
            None => self.generics.contains(r.name.name.as_str()),
        }
    }

    /// [lsp-definition] [name-table] A written name -> its declaration,
    /// recorded by the file that wrote it.
    fn record_written_def(&mut self, r: &TypeRef) {
        if self.foreign_ref(r) {
            return;
        }
        if let Some(site) = self.named(r).def {
            self.out.def_refs.insert(self.key(r.name.span), site);
        }
    }

    /// [type-identity] [name-table] The key of the type a written reference
    /// names where it is written, or its written name.
    fn written_key_of(&self, r: &TypeRef) -> String {
        self.named(r).key(self.symbols).unwrap_or(&r.name.name).to_string()
    }

    /// [qual-overload] [name-table] The first qualifier a written name
    /// means where it is written.
    fn written_qual_decl(&self, q: &TypeRef) -> Option<&'p QualifierDecl> {
        self.named(q).qualifiers.first().copied()
    }

    /// [lsp-definition] [name-table] A written qualifier name -> its
    /// declaration, recorded by the file that wrote it, and only for a
    /// **user** qualifier: a built-in auto-qualifier (`Mut`, `once`) is a
    /// language keyword with no declaration to jump to, and recording a ref
    /// for it made hover resolve `Mut` to an arbitrary `canbe Mut` type
    /// (e.g. `Set`).
    fn record_qualifier_def(&mut self, q: &TypeRef) {
        if self.foreign_ref(q) {
            return;
        }
        let m = self.named(q);
        if let (true, Some(site)) = (m.is_qualifier(), m.def) {
            self.out.def_refs.insert(self.key(q.name.span), site);
        }
    }

    fn record_def_ref(&mut self, span: Span, name: &str) {
        if let Some(site) = self.scope.def_sites.get(name).copied() {
            self.out.def_refs.insert(self.key(span), site);
        }
    }

    /// [op-no-none] Rejects a possibly-`None` operand of an arithmetic or
    /// comparison operator (user decision 2026-09-02). Nullability is
    /// tested with `is None`, so an optional reaching an operator is
    /// always a missing narrowing — and the backends disagree about it
    /// (Kotlin compares/prints `null`, Rust rejects the `Option`), which
    /// makes leniency a parity hole. `Unknown`/`Never` stay lenient.
    fn reject_optional_operand(&mut self, op: BinaryOp, operand: &Expr, ty: &Ty) -> bool {
        if ty.is_unknown() || matches!(ty, Ty::Never) {
            return false;
        }
        let stripped = ty.strip_quals();
        if !(stripped.has_none_arm() || stripped.is_none_ty()) {
            return false;
        }
        let symbol = op_symbol(op);
        let message = if stripped.is_none_ty() {
            messages::op_no_none_none_operand(&symbol)
        } else {
            messages::op_no_none_optional_operand(&symbol, &ty)
        };
        self.error(operand.span(), message);
        true
    }

    fn lookup_mut(&mut self, name: &str) -> Option<&mut LocalVar> {
        self.locals.iter_mut().rev().find_map(|s| s.get_mut(name))
    }

    /// [lsp-completion] Records a local binding so the language server can
    /// offer it as a completion inside its fn. Only while a fn body is being
    /// checked (`cur_fn_body` set); `_`-prefixed names and compiler temporaries
    /// (`__…`) are not names a programmer would complete, so they are left out.
    fn record_local_decl(&mut self, name: &Ident, ty: Ty) {
        self.record_local_decl_scoped(name, ty, false);
    }

    /// [lsp-completion] As `record_local_decl`, but `always_in_scope` marks a
    /// binding offered throughout the body regardless of where it is written
    /// (a parameter or a handler/`iter fn` state field).
    fn record_local_decl_scoped(&mut self, name: &Ident, ty: Ty, always_in_scope: bool) {
        let Some(fn_body) = self.cur_fn_body else { return };
        if name.name.starts_with('_') {
            return;
        }
        self.out
            .local_decls
            .entry(self.file_idx)
            .or_default()
            .push(crate::check::LocalDecl {
                // [comptime-scope] As written, not as a scoped body renamed it.
                name: crate::comptime::written_local(&name.name).to_string(),
                ty,
                span: name.span,
                fn_body,
                always_in_scope,
            });
    }

    /// Declares a new local, enforcing the no-shadowing rule
    /// [var-no-shadow].
    fn declare(&mut self, name: &Ident, ty: Ty) {
        self.declare_with_links(name, ty, Vec::new());
    }

    /// [comptime-scope] [var-no-shadow] A local a scoped comptime body renamed
    /// (`k__c3`) still may not hide a visible one it was written as (`k`, or
    /// `k__c1` when an enclosing copy renamed it first): the rename keeps the
    /// body's locals from leaking out, not from shadowing what is in.
    fn shadows_by_written_name(&self, name: &str) -> bool {
        let mut at = name;
        while let Some(outer) = crate::comptime::scoped_outer(at) {
            if self.lookup(outer).is_some() {
                return true;
            }
            at = outer;
        }
        false
    }

    /// Declares a new local carrying fate links to the variables it was
    /// bound from [fate-link].
    fn declare_with_links(&mut self, name: &Ident, ty: Ty, links: Vec<FateLink>) {
        self.declare_var(name, ty, links, false, None);
    }

    fn declare_var(
        &mut self,
        name: &Ident,
        ty: Ty,
        links: Vec<FateLink>,
        is_param: bool,
        for_origin: Option<Span>,
    ) {
        // A declared *name* is not an expression, but tooling hovers it
        // like one: record its type so hover answers on the declaration
        // (parameter, `let`, `is`/`for` binding) and not only on uses
        // [doc-hover-narrowed]. `or_insert` keeps a more specific entry
        // an earlier pass recorded for the same span.
        self.out
            .expr_ty
            .entry(self.key(name.span))
            .or_insert_with(|| ty.clone());
        // [lsp-completion] Offer this binding as a completion inside its fn.
        self.record_local_decl(name, ty.clone());
        // [comptime-copy-warn] One more copy declared this written local.
        if let Some(at) = self.in_place_written(name.span) {
            *self.copy_decls.entry((at.start, at.end)).or_default() += 1;
        }
        if self.lookup(&name.name).is_some() || self.shadows_by_written_name(&name.name) {
            self.error(
                name.span,
                messages::var_no_shadow_already_declared(
                    &crate::comptime::written_local(&name.name),
                ),
            );
        }
        // [fate-poison] [fate-move-mode] What the IR flow pass poisons this
        // binding by, and decides its mode from.
        self.record_fate_bind(name.span, &links);
        // [fate-link] Tooling hovers a *declaration* too, and that is where
        // a reader looks first to learn what a variable shares fate with —
        // so the presentation table is recorded here as well as at each
        // read. A binding that takes ownership has no links: the language
        // server drops what the IR decided (`ir::analyze::analyze_full`).
        if !links.is_empty() {
            let reads: Vec<FateRead> = links
                .iter()
                .map(|l| FateRead {
                    root: l.root_name.clone(),
                    bind: self.key(l.bind_span),
                    path: l
                        .path
                        .as_ref()
                        .map(|p| p.iter().map(|s| s.to_string()).collect()),
                })
                .collect();
            self.out.fate_reads.insert(self.key(name.span), reads);
        }
        let id = self.next_var_id;
        self.next_var_id += 1;
        // [fate-elem-distinct] [ref-notsame] A bound handle's links carry its own
        // identity: what a `NotSame` claim between two handles relates.
        let mut links = links;
        if has_ref_arm(&ty) {
            for l in &mut links {
                if l.borrowed && !l.held {
                    l.elem_idx = Some(id);
                }
            }
        }
        self.locals.last_mut().expect("scope stack").insert(
            name.name.clone(),
            LocalVar {
                declared: ty.clone(),
                narrowed: ty,
                id,
                links,
                is_param,
                for_origin,
                decl_span: name.span,
                lambda_kept: false,
                is_handler_state: false,
                widened: None,
                place_narrows: Vec::new(),
                used: false,
            },
        );
    }

    // ================= shared fate [fate-link] =================

    /// The local variables an expression's value derives from: a bare
    /// identifier or a projection chain (field/index/`!`) of one
    /// [fate-link]. Anything else (calls — including `copy` [copy-fn] —
    /// literals, constructed values, branch values) produces an
    /// independent value.
    fn provenance<'e>(expr: &'e Expr, out: &mut Vec<&'e Ident>) {
        match expr {
            Expr::Ident(id) => out.push(id),
            Expr::Field { base, .. } | Expr::TupleIndex { base, .. } => Self::provenance(base, out),
            Expr::Index { base, .. } => Self::provenance(base, out),
            e if e.presence_unwrapped().is_some() => Self::provenance(e.presence_unwrapped().unwrap(), out),
            _ => {}
        }
    }

    /// The fate links a binding from `value` carries: each source
    /// variable plus its own links, flattened (transitive links point at
    /// the ultimate roots) [fate-link], deduplicated by root id. The
    /// direct source link carries this bind event's span; transitive
    /// links *keep their original bind spans*, so a variable's links
    /// describe the whole derivation chain (`longest` → `name` →
    /// `person` → `persons`, each at its own bind site) — which is what
    /// lets move-mode candidates cover every binding of a consuming
    /// chain even after intermediate variables die [fate-move-mode].
    fn links_for_value(&self, value: &Expr, bind_span: Span) -> Vec<FateLink> {
        // [proj-field] A struct literal with `proj` fields is derived
        // from the values stored in them: a pass minted over `list` shares
        // fate with `list`. Other fields are moved in and carry no link.
        if let Expr::StructLit { fields, span, .. } = value {
            if let Some(struct_ty) = self.out.ty_of(self.file_idx, *span) {
                let proj_fields = self.proj_fields_of(struct_ty);
                let holds = self.ty_holds_proj(struct_ty);
                if !proj_fields.is_empty() || holds {
                    let mut links: Vec<FateLink> = Vec::new();
                    let push = |l: FateLink, links: &mut Vec<FateLink>| {
                        if !links.iter().any(|e| e.root_id == l.root_id) {
                            links.push(l);
                        }
                    };
                    for f in fields {
                        match &f.kind {
                            StructLitFieldKind::Named { name, value } => {
                                if proj_fields.contains(&name.name) {
                                    // [proj-infer] A `proj` field projects
                                    // what is stored in it: the literal holds
                                    // a borrow of that value's roots.
                                    for mut l in self.links_for_value(value, bind_span) {
                                        l.borrowed = true;
                                        l.held = true;
                                        push(l, &mut links);
                                    }
                                } else {
                                    // An owned field storing a *view* makes
                                    // the literal a view of the same roots;
                                    // an owned field storing owned data (or
                                    // a plain alias, which is a move) adds
                                    // nothing.
                                    for l in self.links_for_value(value, bind_span) {
                                        if l.held {
                                            push(l, &mut links);
                                        }
                                    }
                                }
                            }
                            StructLitFieldKind::Spread(inner) => {
                                for l in self.links_for_value(inner, bind_span) {
                                    if l.held {
                                        push(l, &mut links);
                                    }
                                }
                            }
                            // [comptime-inline] Gone before this runs.
                            StructLitFieldKind::InlineFor { .. } => {}
                        }
                    }
                    return links;
                }
            }
        }
        // [ref-anchor] A field of a view a call handed back is part of what
        // it views (`at(lib.albums, i)!.tracks` is in `lib`): it carries the
        // view's links, at the view's (conservative) path.
        if let Expr::Field { base, .. } = value {
            let mut b = base.as_ref();
            while let Expr::Field { base, .. } = b {
                b = base.as_ref();
            }
            let call = match b.presence_unwrapped() {
                Some(operand) => matches!(operand, Expr::Call { .. }),
                None => matches!(b, Expr::Call { .. }),
            };
            if call {
                return self.links_for_value(b, bind_span);
            }
        }
        // [proj-readonly-return] `get(xs, i) ?: unreachable!()` is still the
        // borrow `get` handed back: the unwrap changes the type, not the
        // provenance.
        if let Some(operand) = value.presence_unwrapped() {
            if matches!(operand, Expr::Call { .. }) {
                return self.links_for_value(operand, bind_span);
            }
        }
        // [proj-readonly-return] The result of a derived-return call borrows
        // the annotated argument: it carries that argument's links
        // (dot-notation receivers are argument 0).
        if let Expr::Call {
            callee, args, span, ..
        } = value
        {
            // [proj-infer] The result of a lending call holds borrows of the
            // lent arguments: an owned value (a pass) tied to them.
            if let Some(lent) = self.out.lending_calls.get(&self.key(*span)).cloned() {
                let mut links: Vec<FateLink> = Vec::new();
                for idx in lent {
                    let arg: Option<&Expr> = if let Expr::Field { base, .. } = callee.as_ref() {
                        if idx == 0 {
                            Some(base)
                        } else {
                            args.get(idx - 1)
                        }
                    } else {
                        args.get(idx)
                    };
                    let Some(arg) = arg else { continue };
                    for mut l in self.links_for_value(arg, bind_span) {
                        l.borrowed = true;
                        l.held = true;
                        if !links.iter().any(|e| e.root_id == l.root_id) {
                            links.push(l);
                        }
                    }
                }
                return links;
            }
            if let Some(sources) = self.out.derived_calls.get(&self.key(*span)).cloned() {
                // [copy-scalar-free] A borrowed copy scalar *is* the value on
                // both backends — `proj Int` is `Int`, which `Ty::qualify`
                // already erases — so a call handing one back borrows nothing
                // and the result travels freely. Without this, reading an
                // element of a `List<Double>` and returning it asks for a
                // `copy` that neither backend would emit.
                if self
                    .out
                    .ty_of(self.file_idx, *span)
                    .is_some_and(|t| crate::types::is_copy_scalar(t.strip_quals()))
                {
                    return Vec::new();
                }
                // [proj-readonly] A wholesale projection: the result *is* the
                // argument's data — of every named source.
                let mut links: Vec<FateLink> = Vec::new();
                for idx in sources {
                    let arg: Option<&Expr> = if let Expr::Field { base, .. } = callee.as_ref() {
                        if idx == 0 {
                            Some(base)
                        } else {
                            args.get(idx - 1)
                        }
                    } else {
                        args.get(idx)
                    };
                    let Some(arg) = arg else { continue };
                    for mut l in self.links_for_value(arg, bind_span) {
                        l.borrowed = true;
                        l.held = false;
                        // [deduce-field] A lend handed back by a *call* may
                        // reach into contents and leaves no trace of it in
                        // the path (`first(h.tags)` records `[.tags]`), so
                        // it is conservative — this is the fact that makes
                        // the bit necessary rather than inferable.
                        l.crosses = true;
                        if !links.iter().any(|e| e.root_id == l.root_id) {
                            links.push(l);
                        }
                    }
                }
                return links;
            }
        }
        // [fate-lambda-view] A lambda value is a *view* of its non-Copy read
        // captures [fate-lambda]: binding it carries those held links (the
        // direct ones restamped to this bind event).
        if let Expr::Lambda { span, .. } = value {
            return self
                .lambda_links
                .get(span)
                .map(|ls| {
                    ls.iter()
                        .map(|l| FateLink {
                            root_id: l.root_id,
                            root_name: l.root_name.clone(),
                            bind_span,
                            path: l.path.clone(),
                            borrowed: l.borrowed,
                            held: l.held,
                            elem_idx: l.elem_idx,
                            crosses: l.crosses,
                        })
                        .collect()
                })
                .unwrap_or_default();
        }
        // [copy-scalar-free] A Copy scalar read out of a place is a value of
        // its own: it shares no fate with what it was read from, so a later
        // write there (through a handle, say) leaves it standing.
        if self
            .out
            .ty_of(self.file_idx, value.span())
            .is_some_and(|t| crate::types::is_copy_scalar(t.strip_quals()))
        {
            return Vec::new();
        }
        let mut sources = Vec::new();
        Self::provenance(value, &mut sources);
        // [fate-field-disjoint] The projection this value reads out of its
        // source, as a path: `p.name` gives `[.name]`, a bare `p` gives
        // `[]`. `None` when the chain is not a plain projection (a `!`
        // unwrap), which stays conservative everywhere below.
        let extra: Option<Vec<Step>> = Place::of_expr(value).map(|p| p.path);
        let mut links: Vec<FateLink> = Vec::new();
        let push = |link: FateLink, links: &mut Vec<FateLink>| {
            if !links.iter().any(|l| l.root_id == link.root_id) {
                links.push(link);
            }
        };
        for src in sources {
            let Some(var) = self.lookup(&src.name) else {
                continue;
            };
            // A source that is itself physically borrowed propagates the
            // flag to its direct link [proj-readonly-return].
            let src_borrowed = var.links.iter().any(|l| l.borrowed);
            push(
                FateLink {
                    root_id: var.id,
                    root_name: src.name.clone(),
                    bind_span,
                    path: extra.clone(),
                    borrowed: src_borrowed,
                    held: false,
                    elem_idx: None,
                    // [deduce-field] Inline storage exactly when the whole
                    // derivation is a field chain (or a plain alias) of a
                    // place: anything the analysis cannot spell that way —
                    // an element read, a call, an unwrap — stays
                    // conservative. A source that itself crosses
                    // propagates.
                    crosses: extra
                        .as_deref()
                        .is_none_or(|p| !p.iter().all(|s| matches!(s, Step::Field(_))))
                        || var.links.iter().any(|l| l.crosses),
                },
                &mut links,
            );
            for l in var.links.clone() {
                // [fate-field-disjoint] A transitive link's path is
                // relative to the *ultimate* root, so this value's own
                // projection extends it: with `let p = q.inner` and
                // `let n = p.name`, `n`'s link to `q` is `[.inner, .name]`.
                let composed = match (&l.path, &extra) {
                    (Some(base), Some(more)) => {
                        let mut path = base.clone();
                        path.extend(more.iter().cloned());
                        Some(path)
                    }
                    _ => None,
                };
                let step_inline = extra
                    .as_deref()
                    .is_some_and(|p| p.iter().all(|s| matches!(s, Step::Field(_))));
                push(
                    FateLink {
                        path: composed,
                        // [deduce-field] Crossing is inherited: a field of
                        // something already reached through contents is
                        // still through contents.
                        crosses: l.crosses || !step_inline,
                        ..l
                    },
                    &mut links,
                );
            }
        }
        links
    }


    /// [interp-to-str] Whether a type renders natively in an interpolation on
    /// *both* backends: the scalars and `Str`. Rust formats these with
    /// `Display` and Kotlin with `toString`, and the text agrees — which is
    /// the requirement, since one program must print the same thing on both
    /// [backend-parity].
    fn interp_native(ty: &Ty) -> bool {
        // A union renders natively when *every* arm does: the value is one of
        // them, and both backends reach the payload (Kotlin through the
        // wrapper's `.value`, Rust through the arm accessor). `None` arms are
        // already refused before this [interp-no-none].
        if let Ty::Union(arms) = ty.strip_quals() {
            return arms.iter().all(Self::interp_native);
        }
        matches!(
            ty.strip_quals(),
            Ty::Named { name, args }
                if args.is_empty()
                    && matches!(
                        name.as_str(),
                        "Int" | "Long" | "Float" | "Double" | "Bool" | "Char"
                            | "Byte" | "Str"
                    )
        )
    }

    /// [interp-to-str] How a value of type `ty` reaches text when it is not
    /// native: an implicit `to_str` of the enclosing fn, a `to_str` in scope
    /// (its own implicits filled), or one that needs implicits of its own.
    /// Nothing is recorded; `None` when there is no such form.
    fn interp_text_form(&mut self, expr: &'p Expr, ty: &Ty) -> Option<ArmText> {
        let want = Ty::Fn {
            params: vec![ty.clone()],
            ret: Box::new(Ty::named("Str")),
            contract: None,
            effects: Vec::new(),
        };
        // [implicit-resolve-body] An implicit `to_str` of the enclosing fn that
        // takes this value renders it — the same rule a call to the name
        // follows, the most specific among several (R10 D21).
        let fits = |p: &ImplicitParam| {
            matches!(p.ty.strip_quals(), Ty::Fn { params, .. }
                if params.len() == 1 && Self::arg_fits_fn_value(ty, &params[0]))
        };
        match self.pick_own_implicit("to_str", &fits) {
            Ok(Some(own)) => return Some(ArmText::Own(own.local.clone())),
            Ok(None) => {}
            Err(tied) => {
                self.own_implicit_tie("to_str", &tied, expr.span());
                return Some(ArmText::Own("to_str".to_string()));
            }
        }
        self.resolve_as_call = true;
        let resolved = self.resolve_implicit_fn_at("to_str", None, &want);
        self.resolve_as_call = false;
        if let Ok((key, _)) = resolved {
            // A `to_str` with implicits of its own is filled here too.
            let implicits = self.implicits_of_text_form(expr, key, ty);
            return Some(ArmText::Fn { key, implicits });
        }
        // [implicit-resolve] [fn-overload-ambiguous] Several fit and none is
        // more specific: refused as at a call, with an interpolation's remedies.
        // (Reported here, so the value reads as handled: one mistake, one
        // diagnostic.) There is no other `to_str` to fall back on: the one
        // resolution chose is the one, as for a call (user decision
        // 2026-10-14; the first-declared `to_str` with implicits used to
        // stand in when resolution found none).
        if let Err(ImplicitMiss::Ambiguous(cands)) = resolved {
            let text = Self::implicit_ambiguity("to_str", &cands, Some("`${to_str@{m}(…)}`"));
            self.error(expr.span(), messages::interp_to_str_ambiguous(&ty, &text));
            return Some(ArmText::Native);
        }
        None
    }

    /// The implicits `key` (a `to_str` overload) needs to take a `ty`, filled
    /// at `expr`; empty for one with none.
    fn implicits_of_text_form(&mut self, expr: &'p Expr, key: DeclId, ty: &Ty) -> Vec<ImplicitArg> {
        let implicits = self.out.implicit_params.get(&key).cloned().unwrap_or_default();
        if implicits.is_empty() {
            return Vec::new();
        }
        let Some(entry) = self.overloads_of("to_str").into_iter().find(|e| e.key == key) else {
            return Vec::new();
        };
        let decl = entry.decl;
        let fixed: Vec<&ast::Param> = decl.params.iter().filter(|p| !p.implicit).collect();
        let saved = self.enter_generics(&decl.generics);
        let patterns: Vec<Ty> = fixed.iter().map(|p| self.lower_type(&p.ty)).collect();
        self.generics = saved;
        let mut subst: HashMap<String, Ty> = HashMap::new();
        for p in &patterns {
            unify(p, ty.strip_quals(), &mut subst);
        }
        let generics: HashSet<String> = decl.generics.iter().map(|g| g.name.clone()).collect();
        self.fill_implicit_list(&implicits, "to_str", &mut subst, &generics, &[], expr.span()).unwrap_or_default()
    }

    /// [interp-to-str] Whether anything would take the call `to_str(ty)`: an
    /// implicit `to_str` of the enclosing fn, or a visible fn or available
    /// member of the name (an ambiguity counts: the call reports it). Silent.
    fn interp_has_text(&mut self, ty: &Ty) -> bool {
        // The part is read, as a kept parameter reads its argument: a
        // borrow or a qualifier on it does not stand in the way of a
        // `to_str` of the base type (the call ranks the exact one).
        let ty = &ty.strip_quals().clone();
        let fits = |p: &ImplicitParam| {
            matches!(p.ty.strip_quals(), Ty::Fn { params, .. }
                if params.len() == 1 && Self::arg_fits_fn_value(ty, &params[0]))
        };
        if !matches!(self.pick_own_implicit("to_str", &fits), Ok(None)) {
            return true;
        }
        let want = Ty::Fn { params: vec![ty.clone()], ret: Box::new(Ty::named("Str")), contract: None, effects: Vec::new() };
        self.resolve_as_call = true;
        let found = self.resolve_implicit_value("to_str", &want, true);
        self.resolve_as_call = false;
        matches!(found, Ok(_) | Err(ImplicitMiss::Ambiguous(_)))
    }

    /// [interp-to-str] An interpolated part is the call `to_str(part)`
    /// (PIPELINE.md §II.10 P4, option (a), user decision 2026-10-28), resolved
    /// as that call written in the body is: the enclosing fn's own implicit
    /// `to_str` first [implicit-resolve-body] (at a scalar or a `Str` too,
    /// census D1), then the visible fns and the available effects' members of
    /// the name as one set (D3). Its facts are the call's, at the part's
    /// `Key::INTERP_TEXT`; the IR lowers it with `for_call`, and the backends
    /// spell std's intrinsic `to_str` natively. The argument is the part as
    /// already typed, and it is read, not passed: no contract or coercion
    /// applies to it (as before).
    fn interp_call(&mut self, expr: &'p Expr, ty: &Ty) {
        let span = expr.span();
        let key = self.key(span).synthetic(Key::INTERP_TEXT);
        let at = span.at(span.end, span.end);
        let fits = |p: &ImplicitParam| {
            matches!(p.ty.strip_quals(), Ty::Fn { params, .. }
                if params.len() == 1 && Self::arg_fits_fn_value(ty, &params[0]))
        };
        let site = ForSite { at, key, loc: span, call: format!("to_str({ty})"), subject: ty.clone(), interp: true };
        match self.pick_own_implicit("to_str", &fits) {
            Ok(Some(own)) => {
                self.out.local_calls.insert(key);
                self.out.local_call_names.insert(key, own.local.clone());
                if let Some(v) = self.lookup_mut(&own.local) {
                    v.used = true;
                }
                return;
            }
            Ok(None) => {}
            Err(tied) => {
                let saved = self.for_site.replace(site);
                self.own_implicit_tie("to_str", &tied, at);
                self.for_site = saved;
                return;
            }
        }
        let saved = self.for_site.replace(site);
        self.pending_arg_tys = Some(vec![ty.clone()]);
        self.pending_typed_only = true;
        let args: [&'p Expr; 1] = [expr];
        self.resolve_named_call("to_str", at, &[], &args, &[], None, None, at);
        self.pending_arg_tys = None;
        self.pending_typed_only = false;
        self.for_site = saved;
    }

    fn check_interpolable(&mut self, expr: &'p Expr, ty: &Ty) {
        if ty.is_unknown() || matches!(ty, Ty::Never) {
            return;
        }
        // [interp-union] A union is text by the text of the arm it is: every
        // arm needs a form of its own (the scalars and `Str` have one), and
        // the emitters call it on the arm the value turns out to be — until a
        // general union `to_str` exists (R10 D4, deferred).
        let collapsed = crate::literal::collapse_ty(ty);
        if let Ty::Union(arms) = collapsed.strip_quals() {
            let arms: Vec<&Ty> = arms.iter().filter(|a| !a.is_none_ty()).collect();
            // A `to_str` that takes the union itself (`to_str(FsError)`) wins
            // when the arms are not all natively text.
            let whole = !arms.iter().all(|a| Self::interp_native(a));
            if arms.len() >= 2 && whole && self.interp_has_text(ty) {
                self.interp_call(expr, ty);
                return;
            }
            if arms.len() >= 2 {
                let mut forms: Vec<ArmText> = Vec::new();
                for arm in &arms {
                    if Self::interp_native(arm) {
                        forms.push(ArmText::Native);
                    } else if let Some(form) = self.interp_text_form(expr, arm) {
                        forms.push(form);
                    } else {
                        self.error(expr.span(), messages::interp_union_arm_no_text(&ty, &arm));
                        return;
                    }
                }
                self.out.interp_union.insert(self.key(expr.span()), forms);
                return;
            }
        }
        if self.interp_has_text(ty) {
            self.interp_call(expr, ty);
            return;
        }
        // [interp-to-str] No `to_str` in scope. A struct interpolates by
        // opting in (user decision 2026-09-28, replacing the default-on
        // derivation): the remedy is one clause.
        let remedy = match ty.strip_quals() {
            Ty::Named { name, .. } if self.symbols.structs.contains_key(name.as_str()) => format!(
                " — declare `: ToStr<self> by auto` on `{name}` for the field-wise one, or a \
                 `to_str` of your own"
            ),
            _ => String::new(),
        };
        self.error(expr.span(), messages::interp_to_str_no_text(&ty, &remedy));
    }

    /// [fate-elem-distinct] The two-mutable-element-handles-in-one-call rule,
    /// shared by named calls, calls through fn values and effect members
    /// ([fn-contract]'s "keep the two in sync" applied to this rule):
    /// `mut_kept[i]` says argument `i` lands in a kept `Mut` position. A
    /// second handle into a container an earlier argument already handles
    /// is accepted — and recorded in `Checked::distinct_pairs` for the
    /// pair lowering [rs-elem-mut] — only when the minting indices are
    /// proven apart; anything less is refused, naming the remedy.
    ///
    /// [ref-anchor] `anchors[i]` is `Some(k)` when the callee's parameter
    /// `i` is a `ref(c) Mut` handle naming parameter `k` as its container:
    /// the argument must then be a handle into the argument passed at `k`
    /// (the callee indexes *that* container with it), and two such
    /// arguments anchored at the same `k` may alias — two positions into
    /// one container, self-strike included — with no proof needed.
    fn check_elem_handle_pairs(
        &mut self,
        args: &[&'p Expr],
        mut_kept: &[bool],
        anchors: &[Option<usize>],
        span: Span,
    ) {
        let mut handles: Vec<(u32, Option<u32>, Option<Vec<Step>>, usize)> = Vec::new();
        let mut proven_pairs: Option<HashSet<(u32, u32)>> = None;
        // [ref-anchor] Each anchored argument must hand in a position of its
        // container: one of its links is the container argument's own.
        for (i, arg) in args.iter().enumerate() {
            let Some(k) = anchors.get(i).copied().flatten() else { continue };
            let Some(container) = args.get(k).copied() else { continue };
            let want: Vec<(u32, Option<Vec<Step>>)> = self
                .links_for_value(container, container.span())
                .into_iter()
                .map(|l| (l.root_id, l.path))
                .collect();
            let have = match arg {
                Expr::Ident(id) => self.lookup(&id.name).map(|v| v.links.clone()).unwrap_or_default(),
                other => self.links_for_value(other, other.span()),
            };
            let is_handle = self
                .out
                .ty_of(self.file_idx, arg.span())
                .is_some_and(|t| has_ref_arm(t));
            // A position anywhere *inside* the container counts (user
            // decision 2026-10-10): the link's path extends the
            // container's.
            let under = |p: &Option<Vec<Step>>, lp: &Option<Vec<Step>>| match (p, lp) {
                (None, _) => true,
                (Some(p), Some(lp)) => lp.len() >= p.len() && lp[..p.len()] == p[..],
                (Some(_), None) => false,
            };
            let into_it = is_handle
                && have
                    .iter()
                    .any(|l| want.iter().any(|(r, p)| *r == l.root_id && under(p, &l.path)));
            if !into_it {
                self.error(
                    arg.span(),
                    messages::ref_anchor_not_a_handle(),
                );
            }
        }
        for (i, arg) in args.iter().enumerate() {
            if !mut_kept.get(i).copied().unwrap_or(false) {
                continue;
            }
            let mutable_handle = self
                .out
                .ty_of(self.file_idx, arg.span())
                .is_some_and(|t| t.is_ref() && Self::carries_mut(t));
            if !mutable_handle {
                continue;
            }
            let links = match arg {
                Expr::Ident(id) => self
                    .lookup(&id.name)
                    .map(|v| v.links.clone())
                    .unwrap_or_default(),
                other => self.links_for_value(other, other.span()),
            };
            for l in links.iter().filter(|l| l.borrowed && !l.held) {
                let Some((_, prev_idx, prev_path, prev_param)) =
                    handles.iter().find(|(r, ..)| *r == l.root_id)
                else {
                    handles.push((l.root_id, l.elem_idx, l.path.clone(), i));
                    continue;
                };
                // [ref-anchor] Two handles anchored at one container
                // parameter may alias: accepted, nothing to prove. An
                // anchor that is itself a handle parameter (`a: ref(al)`,
                // `al: ref(lib)`) chains to the container it is in: every
                // handle of the chain is a position in that one container.
                let prev_param = *prev_param;
                let root_anchor = |mut j: usize| -> Option<usize> {
                    let mut seen = 0;
                    let mut out = None;
                    while let Some(k) = anchors.get(j).copied().flatten() {
                        out = Some(k);
                        j = k;
                        seen += 1;
                        if seen > anchors.len() {
                            break;
                        }
                    }
                    out
                };
                let chain = |j: usize| -> Option<usize> { root_anchor(j).or_else(|| anchors.iter().any(|a| *a == Some(j)).then_some(j)) };
                if let (Some(a), Some(b)) = (chain(prev_param), chain(i)) {
                    if a == b {
                        continue;
                    }
                }
                let prev_param = &prev_param;
                let proven = match (*prev_idx, l.elem_idx) {
                    (Some(a), Some(b)) if a != b && l.path.is_some() && *prev_path == l.path => {
                        proven_pairs
                            .get_or_insert_with(|| self.live_distinct_pairs())
                            .contains(&(a, b))
                    }
                    _ => false,
                };
                let key = self.key(span);
                if proven && !self.out.distinct_pairs.contains_key(&key) {
                    self.out.distinct_pairs.insert(key, (*prev_param, i));
                } else {
                    let root = &l.root_name;
                    self.error(arg.span(), messages::fate_elem_distinct_two_handles(&root));
                }
            }
        }
    }


    /// [fate-elem-distinct] [ref-notsame] Every pair of handle identities
    /// currently proven apart by a live `NotSame` claim, both orientations:
    /// a handle whose narrowed type carries `NotSame(a)` relates its own
    /// identity to `a`'s. Claims are matched by the qualifier's name, the
    /// posture every std claim takes (`Sorted`, `Mut`); [qual-depend]'s
    /// stripping keeps a live claim honest.
    fn live_distinct_pairs(&self) -> HashSet<(u32, u32)> {
        let mut pairs = HashSet::new();
        for frame in &self.locals {
            for var in frame.values() {
                let subject = var.id;
                let Ty::Qualified { quals, .. } = &var.narrowed else {
                    continue;
                };
                for q in quals.iter().filter(|q| q.name == "NotSame") {
                    for a in &q.args {
                        if let Ty::ValueRef { roots, .. } = a {
                            if let [other] = roots.as_slice() {
                                pairs.insert((subject, *other));
                                pairs.insert((*other, subject));
                            }
                        }
                    }
                }
            }
        }
        pairs
    }

    /// [fate-elem-distinct] Reassigning (or stepping) an index variable erases
    /// every element identity minted from it: the identity means "the
    /// element selected by the variable's *current* value", and the current
    /// value just changed. Eager, at the event — the invalidation style of
    /// the whole analysis — so a surviving identity needs no staleness
    /// check at consult time.
    fn erase_elem_identities(&mut self, id: u32) {
        for frame in &mut self.locals {
            for var in frame.values_mut() {
                for l in &mut var.links {
                    if l.elem_idx == Some(id) {
                        l.elem_idx = None;
                    }
                }
            }
        }
    }

    /// [fate-poison] A mutation event on `root_id` at `event_path`, for the
    /// IR flow pass (`Checked::fate_mutations`), which poisons every value
    /// linked to the root at an overlapping path [fate-field-disjoint] —
    /// with what the walk knows it spares: the acting handle (`exempt`
    /// [ref-handle]: a mutation *through* a mutable element handle must not
    /// kill the handle itself, its storage did not move), and the handles a
    /// live `NotSame` claim proves apart (`acting_elem` is the acting
    /// handle's identity [fate-elem-distinct]: a sibling link into the same root
    /// **at the same path** whose identity is proven apart names disjoint
    /// storage; anything short of the full proof poisons). A **contents**
    /// mutation (`contents_only` [deduce-field]) spares a handle to the
    /// mutated thing itself, which is also a virtual-place candidate
    /// (`Checked::virtual_candidates`).
    #[allow(clippy::too_many_arguments)]
    fn record_mutation(
        &mut self,
        root_id: u32,
        root_name: &str,
        span: Span,
        event_path: Option<&[Step]>,
        exempt: u32,
        acting_elem: Option<u32>,
        contents_only: bool,
    ) {
        let distinct = match acting_elem {
            Some(_) => self.live_distinct_pairs(),
            None => HashSet::new(),
        };
        // [deduce-field] Bindings the contents-rule spares: in Rust they
        // cannot be live borrows (the mutation names the same place, so
        // `&h.tags` across `h.tags.push(…)` is E0502), so each is a
        // candidate for the virtual-place rendering — which is also what
        // keeps the two backends in step, since re-reading an unreplaced
        // field yields the object Kotlin's binding holds [backend-parity].
        let mut spared: Vec<(Span, String)> = Vec::new();
        // [fate-poison] For the IR flow pass: the variables the element
        // rule spares (a typing fact, the live `NotSame` claims), and the
        // acting handle by name.
        let mut elem_spared: Vec<String> = Vec::new();
        let mut exempt_name: Option<String> = None;
        for frame in &self.locals {
            for (var_name, var) in frame.iter() {
                if var.id == exempt && exempt != root_id {
                    exempt_name = Some(var_name.clone());
                }
                if var.id == root_id || var.id == exempt {
                    continue;
                }
                let mut elem_spare = false;
                let hit = var.links.iter().any(|l| {
                    if l.root_id != root_id || !l.overlaps_event(event_path) {
                        return false;
                    }
                    // [deduce-field] Rung ⑤ v2's spare: a **contents**
                    // mutation leaves the mutated thing's own storage in
                    // place, so a derivation that *is* that thing — an
                    // inline handle at exactly the event's path — survives,
                    // and both backends observe the same object. A
                    // derivation reaching *through* its contents does not
                    // (`crosses`), nor does anything deeper, nor a
                    // replacement.
                    if contents_only && !l.crosses {
                        if let (Some(link), Some(ev)) = (l.path.as_deref(), event_path) {
                            if !link.is_empty() && link == ev {
                                let mut place = l.root_name.clone();
                                for step in link {
                                    place.push_str(&step.to_string());
                                }
                                spared.push((l.bind_span, place));
                                return false;
                            }
                        }
                    }
                    // [fate-elem-distinct] The spare: same container place,
                    // both element identities present, proven apart.
                    if let (Some(i), Some(k)) = (acting_elem, l.elem_idx) {
                        let same_place = match (event_path, &l.path) {
                            (Some(a), Some(b)) => a == b.as_slice(),
                            _ => false,
                        };
                        if same_place && i != k && distinct.contains(&(i, k)) {
                            elem_spare = true;
                            return false;
                        }
                    }
                    true
                });
                if elem_spare && !hit {
                    elem_spared.push(var_name.clone());
                }
            }
        }
        let key = self.key(span);
        let fact = FlowMutation {
            root: root_name.to_string(),
            path: event_path.map(|p| p.to_vec()),
            contents_only,
            exempt: exempt_name,
            spared: elem_spared,
        };
        let at = self.out.fate_mutations.entry(key).or_default();
        if !at.contains(&fact) {
            at.push(fact);
        }
        // [deduce-field] The IR keeps the spares whose binding is still
        // borrow-mode there [fate-move-mode].
        for (bind_span, place) in spared {
            let c = VirtualCandidate { stamp: self.key(bind_span), place, var: String::new(), survivor: false };
            let at = self.out.virtual_candidates.entry(self.key(span)).or_default();
            if !at.contains(&c) {
                at.push(c);
            }
        }
    }

    /// A move or a `Mut` operation on a fate-linked (derived) variable
    /// [fate-derived-readonly] [fate-move-mode]: recorded for the IR flow
    /// pass (`Checked::derived_uses`), which decides whether a binding behind
    /// it takes ownership — and reports the S1 error when none may. The use
    /// then goes on as the move of an owned value (answers `true`), except
    /// for a Copy scalar, whose move is a copy (answers `false`).
    fn note_derived_use(&mut self, span: Span, action: &str, name: &str, links: &[FateLink]) -> bool {
        // [copy-scalar-free] Moving a derived *Copy scalar* is a read: an
        // `Int` taken out of a borrow is the value itself on both backends,
        // so nothing can observe the difference and no `copy` is owed.
        // Poison still applies to it (a mutated root can change the number);
        // only the *move* is free.
        let scalar = self
            .lookup(name)
            .map(|v| v.narrowed.clone())
            .is_some_and(|t| {
                !matches!(t, Ty::Union(_))
                    && Self::interp_native(&t)
                    && t.strip_quals() != &Ty::named("Str")
            });
        if scalar {
            return false;
        }
        let message = Self::derived_message(action, name, links);
        let mut own: Vec<Key> = Vec::new();
        for l in links {
            let stamp = self.key(l.bind_span);
            if !own.contains(&stamp) {
                own.push(stamp);
            }
        }
        let use_ = DerivedUse { name: name.to_string(), action: action.to_string(), message, own };
        let at = self.out.derived_uses.entry(self.key(span)).or_default();
        if !at.contains(&use_) {
            at.push(use_);
        }
        true
    }

    /// [fate-derived-readonly] [proj-readonly] The S1 error for moving or
    /// mutating the derived variable `name` with `links` in borrow-mode.
    fn derived_message(action: &str, name: &str, links: &[FateLink]) -> Message {
        let root = &links[0].root_name;
        // [proj-readonly] A wholesale projection is the root's own data seen
        // through `proj`: read-only whatever its `Mut` says, and `copy` is
        // the way to a value of one's own.
        if links.iter().any(|l| l.borrowed && !l.held) {
            return messages::proj_readonly_projection_use(action, &name, root);
        }
        messages::fate_derived_readonly_shares_fate(&action, &name, root)
    }

    /// [deduce-syntax] Records that the enclosing fn invalidates one of
    /// its parameters (a mutation of the parameter or of data reached
    /// through it). Drives the "mutation forces an exhaustive deduction
    /// list" rule; unlike claims, it is recorded even when the list is
    /// written, because that is exactly what the validation needs.
    fn record_param_mutation(&mut self, name: &str) {
        let Some(key) = self.own_fn else { return };
        let is_param = self.lookup(name).is_some_and(|var| var.is_param);
        if is_param {
            self.param_mutations
                .entry(key)
                .or_default()
                .insert(name.to_string());
        }
    }

    fn var_by_id(&self, id: u32) -> Option<&LocalVar> {
        self.locals
            .iter()
            .rev()
            .find_map(|frame| frame.values().find(|v| v.id == id))
    }

    /// Whether a parameter is *owned* by the current fn: its effective
    /// deduction contract moves it [fate-move-mode].
    fn param_owned(&self, name: &str) -> bool {
        self.own_contract
            .as_ref()
            .and_then(|c| c.iter().find(|d| d.param == name))
            .is_some_and(|d| !d.kept)
    }

    /// [fate-move-mode] Whether a binding with `links` may take ownership of
    /// what it binds: nothing reached through a derived-return call
    /// [proj-readonly-return] (the value is *physically borrowed*: the binding
    /// stays borrow-mode and the move site reports the S1 error with the
    /// `copy` remedy), every live ancestor owned by the fn (a local, or a
    /// parameter its contract moves; a dead root has nothing left to consume
    /// and does not block), and no ancestor outside an enclosing lambda (a
    /// lambda cannot consume a capture [fate-lambda]).
    fn may_take_ownership(&self, links: &[FateLink]) -> bool {
        if links.iter().any(|l| l.borrowed) {
            return false;
        }
        for l in links {
            let Some(var) = self.var_by_id(l.root_id) else {
                continue;
            };
            if (var.is_param && !self.param_owned(&l.root_name)) || var.lambda_kept {
                return false;
            }
        }
        for l in links {
            let Some(frame) = self.frame_of_id(l.root_id) else {
                continue;
            };
            if self.lambda_ctx.iter().any(|ctx| frame < ctx.boundary) {
                return false;
            }
        }
        true
    }

    /// [fate-move-mode] A `for` loop data was moved out of through its
    /// binding iterates by value.
    fn loop_by_value(&mut self, key: Key) {
        self.out.by_value_loops.insert(key);
    }

    /// [fate-poison] [fate-move-mode] Records a binding's fate links, keyed
    /// by the bound name or the assignment's target, with whether it may
    /// take ownership (judged here, where the binding is) and the `for`
    /// loops its roots are bound by. Written into `Checked::bind_facts` when
    /// the file's walk ends (`finish_fate`); a loop body's second walk adds
    /// what it found. Every binding is borrow-mode in the walk: the IR flow
    /// pass decides which take ownership.
    fn record_fate_bind(&mut self, at: Span, links: &[FateLink]) {
        if links.is_empty() {
            return;
        }
        let bind_span = links[0].bind_span;
        let eligible = self.may_take_ownership(links);
        let entry = self.fate_log.entry(at).or_insert_with(|| (bind_span, Vec::new()));
        for l in links {
            if !entry.1.iter().any(|e| e.root_id == l.root_id && e.bind_span == l.bind_span) {
                entry.1.push(l.clone());
            }
        }
        let origins: Vec<Span> = links.iter().filter_map(|l| self.var_by_id(l.root_id).and_then(|v| v.for_origin)).collect();
        let meta = self.fate_meta.entry(at).or_insert((false, Vec::new()));
        meta.0 |= eligible;
        for o in origins {
            if !meta.1.contains(&o) {
                meta.1.push(o);
            }
        }
    }

    /// [fate-move-mode] The end of a file's walk: every binding as the walk
    /// made it, borrow-mode, into `Checked::bind_facts` — each link stamped
    /// by the binding that made it, so the IR can drop the copies an
    /// ancestor that took ownership made.
    fn finish_fate(&mut self) {
        let meta = std::mem::take(&mut self.fate_meta);
        for (at, (bind_span, links)) in std::mem::take(&mut self.fate_log) {
            let links: Vec<FlowLink> = links
                .iter()
                .map(|l| FlowLink { root: l.root_name.clone(), path: l.path.clone(), crosses: l.crosses, stamp: self.key(l.bind_span) })
                .collect();
            if links.is_empty() {
                continue;
            }
            let (eligible, origins) = meta.get(&at).cloned().unwrap_or_default();
            let origins = origins.into_iter().map(|o| self.key(o)).collect();
            let at = self.key(at);
            self.out.bind_facts.insert(at, BindFact { stamp: self.key(bind_span), links, eligible, origins });
        }
    }

    fn var_by_id_mut(&mut self, id: u32) -> Option<&mut LocalVar> {
        self.locals
            .iter_mut()
            .rev()
            .find_map(|frame| frame.values_mut().find(|v| v.id == id))
    }

    /// The scope-frame index a variable id lives in [fate-lambda].
    fn frame_of_id(&self, id: u32) -> Option<usize> {
        self.locals
            .iter()
            .enumerate()
            .rev()
            .find_map(|(i, frame)| frame.values().any(|v| v.id == id).then_some(i))
    }

    // ================= lambda captures [fate-lambda] =================

    /// Records a read of an outer local inside enclosing lambdas: each
    /// lambda whose boundary lies above the variable's frame captures it
    /// [fate-lambda]. `mutable` = the value is transitively mutable.
    fn record_capture(&mut self, frame: usize, name: &str, var_id: u32, mutable: bool) {
        for ctx in &mut self.lambda_ctx {
            if frame < ctx.boundary && !ctx.captures.iter().any(|c| c.var_id == var_id) {
                ctx.captures.push(CaptureInfo {
                    name: name.to_string(),
                    var_id,
                    mutable,
                    mutated: false,
                    moved: false,
                });
            }
        }
    }

    /// Marks a captured variable as mutated by the lambda body: the
    /// closure takes ownership at creation [fate-lambda].
    fn mark_capture_mutated(&mut self, frame: usize, var_id: u32) {
        for ctx in &mut self.lambda_ctx {
            if frame < ctx.boundary {
                if let Some(c) = ctx.captures.iter_mut().find(|c| c.var_id == var_id) {
                    c.mutated = true;
                }
            }
        }
    }

    /// Handles consumption of a variable inside a lambda body
    /// [fate-lambda] [fn-once]: consuming a capture makes the lambda
    /// `once` — callable at most once — so the consumption is legal and
    /// proceeds (the value is owned by the closure from creation on).
    /// Exception: a *linear* capture may not be swallowed (the closure
    /// would inherit an exactly-once obligation, a future feature) —
    /// that reports an error and returns `true` so the consumption is
    /// skipped.
    fn capture_move_violation(&mut self, frame: usize, name: &str, span: Span) -> bool {
        let captured = self.lambda_ctx.iter().any(|ctx| frame < ctx.boundary);
        if !captured {
            return false;
        }
        let is_linear = self
            .lookup(name)
            .is_some_and(|v| self.ty_own_linear(&v.declared));
        if is_linear {
            self.error(span, messages::linear_lambda_consume(&name));
            return true;
        }
        // Mark every enclosing lambda `once` (an outer lambda re-creating
        // an inner consuming closure would re-consume per run).
        let var_id = self.lookup(name).map(|v| v.id);
        if let Some(var_id) = var_id {
            for ctx in &mut self.lambda_ctx {
                if frame < ctx.boundary {
                    if let Some(c) = ctx.captures.iter_mut().find(|c| c.var_id == var_id) {
                        c.moved = true;
                    }
                }
            }
        }
        false
    }

    /// [proj-anywhere] The qualifier a constructor call builds (`emitted(x)`
    /// → `Emitted`), when `value` is a call to a `-> T as Q` fn.
    fn constructed_qualifier(&self, value: &Expr) -> Option<String> {
        let Expr::Call { span, .. } = value else {
            return None;
        };
        self.constructed_qualifier_at(*span)
    }

    /// [proj-anywhere] `constructed_qualifier` by the call's span.
    fn constructed_qualifier_at(&self, span: Span) -> Option<String> {
        let key = *self.out.call_fn.get(&self.key(span))?;
        self.scope
            .fns
            .values()
            .flatten()
            .find(|e| e.key == key)
            .and_then(|e| e.decl.constructs.as_ref())
            .map(|c| c.name.name.clone())
    }

    /// [proj-anywhere] The value a one-argument constructor call wraps, or
    /// the expression itself.
    fn constructor_operand(value: &'p Expr) -> &'p Expr {
        match value {
            Expr::Call { args, .. } if args.len() == 1 => &args[0],
            _ => value,
        }
    }

    /// [proj-field] The names of a struct type's `proj` fields (empty
    /// for anything that is not a struct with one).
    fn proj_fields_of(&self, ty: &Ty) -> Vec<String> {
        let Ty::Named { name, .. } = ty.strip_quals() else {
            return Vec::new();
        };
        let Some(decl) = self.symbols.structs.get(name.as_str()) else {
            return Vec::new();
        };
        decl.fields
            .iter()
            .filter(|f| f.ty.as_ref().is_some_and(|t| first_proj_span(t).is_some()))
            .map(|f| f.name.name.clone())
            .collect()
    }

    /// [proj-infer] Whether a value of this (lowered) type can hold a
    /// borrow: it is, or contains, a struct with a `proj` field, directly or
    /// through an owned field whose type does.
    fn ty_holds_proj(&self, ty: &Ty) -> bool {
        fn names(ty: &Ty, out: &mut Vec<String>) {
            match ty {
                Ty::Named { name, .. } => out.push(name.clone()),
                Ty::Qualified { base, .. } => names(base, out),
                Ty::Union(arms) | Ty::Tuple(arms) => arms.iter().for_each(|a| names(a, out)),
                Ty::Array(elem) => names(elem, out),
                _ => {}
            }
        }
        let mut ns = Vec::new();
        names(ty, &mut ns);
        ns.into_iter().any(|n| {
            self.symbols.structs.get(n.as_str()).is_some_and(|d| {
                d.fields.iter().filter_map(|f| f.ty.as_ref()).any(|t| {
                    crate::lends::type_has_proj(t)
                        || crate::lends::holds_proj(t, &self.scope.structs)
                })
            })
        })
    }

    /// [deduce-syntax] A declaration without a body has nothing to infer
    /// from, so its clause must say what happens to every parameter — kept
    /// (`=> p`), consumed (`=> !p`), or qualified (`=> p: Mut`). Copy
    /// scalars are exempt: an `Int`'s fate is nothing to deduce
    /// [copy-scalar-free]. Implicit and variadic parameters are exempt too
    /// (an implicit is a fn value the call fills; a variadic tail is owned).
    fn require_full_clause(&mut self, f: &FnDecl, what: &str) {
        let mentioned: Vec<String> = f
            .deductions
            .as_ref()
            .map(|l| {
                l.iter()
                    .filter_map(|d| d.param_name().map(|n| n.name.clone()))
                    .collect()
            })
            .unwrap_or_default();
        for p in f.params.iter().filter(|p| !p.implicit && !p.variadic) {
            if mentioned.contains(&p.name.name) {
                continue;
            }
            let scalar = salvo_syntax::is_copy_scalar_type(&p.ty);
            if scalar {
                continue;
            }
            self.error(p.name.span, messages::deduce_syntax_bodiless_clause(&what, &p.name.name));
        }
    }

    /// [deduce-syntax] A fn's *effective* contract: the whole-program table's
    /// entry when the deduce pass has produced one (written entries fixed,
    /// the rest inferred), else the written clause with its unmentioned
    /// parameters optimistic — a declaration with no key.
    fn effective_contract(
        &self,
        key: Option<DeclId>,
        decl: &FnDecl,
    ) -> Option<Vec<crate::deduce::ParamDeduction>> {
        if let Some(k) = key {
            if let Some(found) = self.inferred.get(&k).cloned() {
                return Some(found);
            }
        }
        decl.deductions
            .as_ref()
            .map(|list| crate::deduce::from_written(decl, list, &HashSet::new(), |_, _| {}))
    }

    /// The resolver's key for a declaration, by identity.
    fn fn_key_of_decl(&self, f: &FnDecl) -> Option<DeclId> {
        self.scope
            .fns
            .get(f.name.name.as_str())
            .and_then(|v| v.iter().find(|e| std::ptr::eq(e.decl, f)).map(|e| e.key))
    }

    /// [proj-infer] The parameters `decl`'s result holds borrows of —
    /// declared (`[p: proj]`), inferred from its body, or every kept
    /// parameter when there is no body. Memoised per declaration.
    fn infer_lends(&mut self, decl: &'p FnDecl) -> Vec<usize> {
        let scope_fns = &self.scope.fns;
        let lookup = |name: &str| -> Vec<&'p FnDecl> {
            scope_fns
                .get(name)
                .map(|v| v.iter().map(|e| e.decl).collect())
                .unwrap_or_default()
        };
        let mut env = crate::lends::LendsEnv {
            structs: &self.scope.structs,
            fns: &lookup,
            memo: &mut self.lends_memo,
        };
        crate::lends::lends_of(decl, &mut env)
    }

    /// [proj-infer] A returned held view may be rooted only in the fn's own
    /// lent parameters (declared or inferred); a root that is a local dies
    /// with this call, and a root that is a parameter the signature does
    /// not lend would tie the caller's result to something it was told is
    /// free.
    fn check_returned_view_roots(&mut self, links: &[FateLink], span: Span) {
        for l in links {
            // Only *ultimate* roots are reported: a derived intermediate
            // (`let a = get(ts, i)`) is in the list alongside what it
            // derives from, and naming both would say one thing twice.
            if self
                .var_by_id(l.root_id)
                .is_some_and(|v| !v.links.is_empty())
            {
                continue;
            }
            let is_param_root = self.var_by_id(l.root_id).is_some_and(|v| v.is_param)
                || self.var_by_id(l.root_id).is_some_and(|v| {
                    v.links
                        .iter()
                        .any(|x| self.var_by_id(x.root_id).is_some_and(|r| r.is_param))
                });
            let root = l.root_name.clone();
            if !is_param_root {
                self.error(span, messages::proj_infer_local_borrow(&root));
                continue;
            }
            let lent = self.own_lends.iter().any(|n| n == &root)
                || self.var_by_id(l.root_id).is_some_and(|v| {
                    v.links
                        .iter()
                        .any(|x| self.own_lends.iter().any(|n| n == &x.root_name))
                });
            // A written `[p: proj]` list is checked against the body as a
            // whole (in `check_fn`); the per-return report would repeat it.
            if !lent && !self.own_lends_declared {
                self.error(span, messages::proj_infer_unlent_borrow(&root));
            }
        }
    }

    /// [proj-anywhere] Whether an argument is a *temporary* — not a variable
    /// or a projection of one, and not a call that forwards a view of one.
    fn is_temporary(&self, arg: &Expr) -> bool {
        // [fate-lambda-view] A lambda expression is never a dangling source: a
        // capturing one is a view whose links pass *through* to the
        // captured variables, and a capture-free one holds nothing a
        // result could borrow.
        if matches!(arg, Expr::Lambda { .. }) {
            return false;
        }
        let mut sources = Vec::new();
        Self::provenance(arg, &mut sources);
        if !sources.is_empty() {
            return false;
        }
        // A field of a view is part of what it views (`at(lib.albums,
        // i)!.tracks` is in `lib`): the question is the view's.
        let mut inner = arg;
        loop {
            inner = match inner {
                e if e.presence_unwrapped().is_some() => e.presence_unwrapped().unwrap(),
                Expr::Field { base, .. } if !matches!(base.as_ref(), Expr::Ident(_)) => base.as_ref(),
                _ => break,
            };
        }
        let forwards_view = matches!(inner, Expr::Call { .. } | Expr::StructLit { .. })
            && !self.links_for_value(inner, inner.span()).is_empty();
        !forwards_view
    }

    /// [proj-anywhere] Errors when `value` is a view of a temporary being
    /// bound, returned or stored: the temporary dies at the end of the
    /// statement, and the view would outlive it. Sees through a `!` and
    /// through a call that *forwards* such a view.
    fn reject_temp_view(&mut self, value: &Expr, what: &str) {
        let inner = value.presence_unwrapped().unwrap_or(value);
        let Expr::Call { span, callee, .. } = inner else {
            return;
        };
        if !self.out.temp_views.contains(&self.key(*span)) {
            return;
        }
        let name = match callee.as_ref() {
            Expr::Ident(id) => id.name.clone(),
            Expr::Field { field, .. } => field.name.clone(),
            _ => "this call".to_string(),
        };
        self.error(value.span(), messages::proj_anywhere_temporary(&what, &name));
    }

    /// Validates a returned value against the fn's derived-return
    /// annotation [proj-readonly-return]: `None` is fine (no borrow), and
    /// everything else must be derived from the annotated parameter —
    /// its provenance chain must terminate at `from` and nowhere else.
    fn check_derived_return_value(&mut self, value: &Expr, from: &str) {
        if matches!(value, Expr::Ident(id) if id.name == "None") {
            return;
        }
        // Any of the declared sources will do (`proj(a, b)`).
        let sources: Vec<String> = if self.own_derived_sources.is_empty() {
            vec![from.to_string()]
        } else {
            self.own_derived_sources.clone()
        };
        let source_ids: Vec<u32> = sources
            .iter()
            .filter_map(|n| self.lookup(n).map(|v| v.id))
            .collect();
        if source_ids.is_empty() {
            return;
        }
        let links = self.links_for_value(value, value.span());
        let ok = !links.is_empty()
            && links.iter().all(|l| {
                source_ids.contains(&l.root_id)
                    || self
                        .var_by_id(l.root_id)
                        .is_some_and(|v| v.links.iter().any(|x| source_ids.contains(&x.root_id)))
            });
        if !ok {
            let shown = sources.join(", ");
            self.error(value.span(), messages::proj_readonly_return_not_derived(&shown));
        }
    }

    /// Applies a fn *value's* contract to the arguments of a call
    /// through it [fn-contract] — the fn-type sibling of the named-call
    /// contract loop (keep the two in sync): moved arguments are
    /// consumed, kept `Mut` positions are mutation events, kept
    /// positions shed their removal set, projections follow
    /// the moved/kept-`Mut` rules, and same-call ordering applies
    /// [deduce-same-call]. An absent contract keeps everything (the
    /// default), so only its `Mut` mutation events fire.
    fn apply_fn_value_contract(
        &mut self,
        args: &[&'p Expr],
        params: &[Ty],
        contract: Option<&[FnParamContract]>,
        span: Span,
    ) {
        // Record the effective per-argument contract for the emitter's
        // argument rendering [fn-contract].
        let effective: Vec<FnParamContract> = (0..args.len())
            .map(|i| {
                let declared_q: Vec<String> = params
                    .get(i)
                    .map(|t| t.quals().iter().map(|q| q.name.clone()).collect())
                    .unwrap_or_default();
                match contract.and_then(|c| c.get(i)) {
                    Some(e) => e.clone(),
                    None => FnParamContract {
                        name: None,
                        kept: true,
                        effect: QualEffect::KeepAll,
                        mutable: declared_q.iter().any(|q| q == "Mut"),
                        lent: false,
                    },
                }
            })
            .collect();
        self.out.fn_value_calls.insert(self.key(span), effective.clone());
        // [ref-handle] A kept `Mut` position needs a handle: a plain `proj`
        // (read-only, even carrying `Mut`) does not fit it — the named-call
        // overload check's `NotHandle` refusal, for calls through fn values.
        for (i, arg) in args.iter().enumerate() {
            let Some(e) = effective.get(i) else { continue };
            if !(e.kept && e.mutable) {
                continue;
            }
            let Some(t) = self.out.ty_of(self.file_idx, arg.span()).cloned() else { continue };
            if t.is_proj() && !t.is_ref() {
                self.error(arg.span(), messages::ref_handle_plain_projection(&t));
            }
        }
        self.apply_call_contract(args, params, contract, span);
    }

    /// The flow half of a contract application, shared by calls through
    /// fn values [fn-contract] and effect-member calls [effect-decl]:
    /// moved arguments are consumed, kept `Mut` positions are mutation
    /// events, kept positions shed their removal set [deduce-syntax],
    /// projections follow the moved/kept-`Mut` rules, and same-call
    /// ordering applies [deduce-same-call]. An absent contract keeps
    /// everything, so only its `Mut` mutation events fire.
    fn apply_call_contract(
        &mut self,
        args: &[&'p Expr],
        params: &[Ty],
        contract: Option<&[FnParamContract]>,
        span: Span,
    ) {
        // [fate-elem-distinct] The handle-pair rule applies to these calls
        // exactly as to named ones.
        let mut_kept: Vec<bool> = (0..args.len())
            .map(|i| {
                let declared_mut = params
                    .get(i)
                    .is_some_and(|t| t.quals().iter().any(|q| q.name == "Mut"));
                match contract.and_then(|c| c.get(i)) {
                    Some(e) => e.kept && e.mutable,
                    None => declared_mut,
                }
            })
            .collect();
        self.check_elem_handle_pairs(args, &mut_kept, &[], span);
        for (i, arg) in args.iter().enumerate() {
            let param_ty = params.get(i);
            let declared_q: Vec<String> = param_ty
                .map(|t| t.quals().iter().map(|q| q.name.clone()).collect())
                .unwrap_or_default();
            let (mut kept, effect, mutable) = match contract.and_then(|c| c.get(i)) {
                Some(e) => (e.kept, e.effect.clone(), e.mutable),
                None => (
                    true,
                    QualEffect::KeepAll,
                    declared_q.iter().any(|q| q == "Mut"),
                ),
            };
            // [proj-anywhere] A constructor lending into a `proj` arm keeps
            // its argument: the caller receives a borrow of it. Only when
            // the call really builds a constructive qualifier — otherwise
            // the ordinary contract stands and the return check reports.
            if self.lending_ctor == Some(span) && self.constructed_qualifier_at(span).is_some() {
                kept = true;
            }
            let Expr::Ident(id) = arg else {
                if kept && mutable {
                    self.fate_mutation_through(arg, span);
                } else if !kept {
                    self.projection_move(arg, span);
                    // Data moved out of the projection: nothing narrowed
                    // about it survives [flow-place-invalidate].
                    if let Some(place) = Place::of_expr(arg) {
                        self.invalidate_place_narrows(&place);
                    }
                }
                continue;
            };
            let arg_once = self
                .lookup(&id.name)
                .map(|v| v.narrowed.quals().iter().any(|q| q.name == "once"))
                .unwrap_or(false);
            // [copy-scalar-free] Moving a Copy scalar is a copy, judged by the
            // argument's own type: a generic `T` bound to `Int` moves for free
            // too, and so does an `Int` handed to a written `!v`.
            if !kept && !arg_once && self.moves_for_free_var(&id.name) {
                continue;
            }
            if !kept || arg_once {
                let state = self.lookup(&id.name).map(|var| (var.id, var.links.clone()));
                let Some((var_id, links)) = state else {
                    continue;
                };
                if !links.is_empty() {
                    let name = id.name.clone();
                    if !self.note_derived_use(id.span, "move", &name, &links) {
                        continue;
                    }
                }
                let name = id.name.clone();
                if let Some(frame) = self.frame_of_id(var_id) {
                    if self.capture_move_violation(frame, &name, id.span) {
                        continue;
                    }
                }
                if self.consume_kept_lambda_param(&name, id.span) {
                    continue;
                }
                // [flow-use-after-move] The IR's argument may be a lent read
                // (a fn value: `param_mode` lends it whatever the contract):
                // the flow pass takes the move from here. A later argument
                // reading `name` is the pass's to report too (the IR reads a
                // call's arguments in order) [deduce-same-call].
                self.out.flow_moves.insert(self.key(id.span));
                continue;
            }
            if mutable {
                let name = id.name.clone();
                // [flow-place-invalidate] A `Mut`-keeping call may mutate
                // the whole value, so every fact about its parts falls. A
                // kept *immutable* parameter cannot mutate: narrowings
                // survive such a call (user decision P1b).
                self.fate_mutation_root(&name, span);
            }
            // [deduce-syntax] The removal set is computed against the
            // qualifiers the *argument* actually carries, so an exhaustive
            // list also drops qualifiers the callee never declared (and
            // therefore cannot have preserved through a mutation).
            let have: Vec<String> = self
                .lookup(&id.name)
                .map(|v| v.narrowed.quals().iter().map(|q| q.name.clone()).collect())
                .unwrap_or_default();
            let removed = effect.removal_set(&have, |q| self.survives_calls(q));
            if !removed.is_empty() {
                if let Some(var) = self.lookup_mut(&id.name) {
                    var.narrowed = var.narrowed.clone().remove_quals(&removed);
                }
            }
        }
    }

    /// [copy-scalar-free] Whether the variable `name` holds a Copy scalar, so
    /// moving it is a copy.
    fn moves_for_free_var(&self, name: &str) -> bool {
        self.lookup(name).is_some_and(|v| crate::types::moves_for_free(&v.declared))
    }

    /// Guards consumption of a lambda parameter the contract *keeps*
    /// [fn-contract]: the value belongs to the closure's caller, so it
    /// can only be read (a Rust borrow). Reports and returns `true` when
    /// the consumption must be skipped.
    fn consume_kept_lambda_param(&mut self, name: &str, span: Span) -> bool {
        let kept = self.lookup(name).is_some_and(|v| v.lambda_kept);
        if kept {
            self.error(span, messages::fn_contract_consume_kept(&name));
        }
        kept
    }

    /// [fate-move-mode] A projection in a *moved* position — a consuming
    /// call argument, a literal store, spread, `return`/`break`/`yield`,
    /// or a `use` constructor argument — moves data out of its
    /// provenance roots. Only projections of *transitively mutable* data
    /// are tracked: for immutable data the backends' clone-vs-alias
    /// difference is unobservable (backend-parity principle). Owned
    /// roots give up the value — they are consumed here, and the
    /// projection is recorded for the emitter (a real partial move); a
    /// written-kept parameter root is an error (moving out of a borrow),
    /// remedy `copy`. A root
    /// taken wholly is recorded in `flow_moves` at the projection, for the
    /// IR flow pass [flow-use-after-move] (which also reports a later
    /// argument of the same call reading it [deduce-same-call]).
    fn projection_move(&mut self, expr: &Expr, span: Span) {
        let mut sources = Vec::new();
        Self::provenance(expr, &mut sources);
        if sources.is_empty() {
            return;
        }
        let ty = self
            .out
            .ty_of(self.file_idx, expr.span())
            .cloned()
            .unwrap_or(Ty::Unknown);
        let mut visited = HashSet::new();
        // [linear-group] A projection of *linear* data is a real move
        // whatever its mutability: "immutable projections are free" is a
        // clone-vs-share latitude [fate-partial-move], and duplicating an
        // obligation is exactly what linearity cannot allow. Recording the
        // move is also what lets decomposition settle a container (`return
        // box.item` in its discharger).
        if !self.ty_transitively_mut(&ty, &mut visited) && !self.ty_own_linear(&ty) {
            return;
        }
        let links = self.links_for_value(expr, span);
        if links.is_empty() {
            return;
        }
        // A lambda cannot consume data out of a capture [fate-lambda].
        for l in &links {
            let Some(frame) = self.frame_of_id(l.root_id) else {
                continue;
            };
            let name = l.root_name.clone();
            if self.capture_move_violation(frame, &name, span) {
                return;
            }
        }
        for l in &links {
            let Some(var) = self.var_by_id(l.root_id) else {
                continue;
            };
            if (var.is_param && !self.param_owned(&l.root_name)) || var.lambda_kept {
                let root = l.root_name.clone();
                self.error(span, messages::fate_move_mode_kept_mutable(&root));
                return;
            }
        }
        for l in &links {
            let mut loop_origin = None;
            // [fate-partial-move] A *proper* projection leaves the root
            // usable (the IR flow pass records what left, from the consuming
            // projection read `moved_projections` makes, and reports a read
            // overlapping it). Only a whole-value move (or a derivation the
            // analysis could not place) takes the variable outright — the
            // flow pass's move (`flow_moves`).
            let partial = l.path.as_deref().is_some_and(|p| !p.is_empty());
            if partial {
                if let Some(var) = self.var_by_id_mut(l.root_id) {
                    loop_origin = var.for_origin;
                }
                // Moving data out of a `for`-loop binding means the loop
                // iterates by value [fate-move-mode].
                if let Some(origin) = loop_origin {
                    self.loop_by_value(self.key(origin));
                }
                continue;
            }
            if let Some(var) = self.var_by_id_mut(l.root_id) {
                loop_origin = var.for_origin;
                // [flow-use-after-move] The IR marks the projection, not
                // the root: the flow pass takes the root's move from here.
                let at = self.key(expr.span());
                self.out.flow_moves.insert(at);
            }
            // Moving data out of a `for`-loop binding means the loop
            // iterates by value [fate-move-mode].
            if let Some(origin) = loop_origin {
                self.loop_by_value(self.key(origin));
            }
        }
        let at = self.key(expr.span());
        self.out.moved_projections.insert(at);
    }

    /// Whether a type's data is transitively mutable: `Mut` at any depth
    /// — top-level qualifier, type argument, array/tuple/union
    /// component, or a struct field followed recursively through struct
    /// declarations [type-canbe-mut] [fate-move-mode]. Mirrors the Kotlin
    /// backend's transitive immutability analysis for `copy` lowering.
    fn ty_transitively_mut(&self, ty: &Ty, visited: &mut HashSet<String>) -> bool {
        if ty.quals().iter().any(|q| q.name == "Mut") {
            return true;
        }
        match ty.strip_quals() {
            Ty::Named { name, args } => {
                if args.iter().any(|a| self.ty_transitively_mut(a, visited)) {
                    return true;
                }
                let Some(decl) = self.symbols.structs.get(name.as_str()) else {
                    return false;
                };
                if !visited.insert(name.clone()) {
                    return false; // recursive struct: already being checked
                }
                decl.fields
                    .iter()
                    .any(|f| f.ty.as_ref().is_some_and(|t| self.ast_type_mut(t, visited)))
            }
            Ty::Array(elem) => self.ty_transitively_mut(elem, visited),
            Ty::Tuple(elems) => elems.iter().any(|e| self.ty_transitively_mut(e, visited)),
            Ty::Union(arms) => arms.iter().any(|a| self.ty_transitively_mut(a, visited)),
            _ => false,
        }
    }

    /// Whether a type *is* linear — it declares `: Linear<self>`
    /// [linear-group], or it is a union one of whose arms does (a union
    /// value is one value: the obligation cannot be lost by narrowing or
    /// by a branch merge), or it is a type parameter opted in with
    /// `<T canbe linear>` [linear-generics].
    ///
    /// **Not** transitive through composites, since R4 part 2: a
    /// composite may not *hold* a linear value at all
    /// [linear-composite], and every way of putting one in is refused at
    /// the store, so "a `List<FileHandle>` is itself linear" describes a
    /// type no accepted program can build. Keeping the obligation out of
    /// composites is also what keeps the diagnostics single: the store is
    /// the one error, with no follow-on leak for the container.
    fn ty_own_linear(&self, ty: &Ty) -> bool {
        self.ty_own_linear_guarded(ty, 0)
    }

    /// [col-key-eligible] Whether a type may be a **key**: a `Set`
    /// element, or a `Map` key. `None` means eligible; `Some(reason)` is
    /// the phrase the diagnostic uses.
    ///
    /// Hashing and equality are what a hash container needs, and this
    /// version answers them from the intrinsic types alone: `Int`, `Long`,
    /// `Str`, `Char` and `Bool` have both on every backend. Two exclusions
    /// are worth stating rather than discovering:
    ///
    /// * `Double`/`Float` are **not** keys. Rust's `f64` implements neither
    ///   `Eq` nor `Hash` (`NaN != NaN`), so a float-keyed map is not
    ///   representable there at all, while Kotlin would take it happily —
    ///   a divergence closed by restriction [backend-parity].
    /// * a struct is not a key *yet*: `: auto Hashed<self>` is the clause, and it
    ///   is what the diagnostic points at.
    ///
    /// A type *variable* is eligible: a generic fn's `K` is checked where
    /// it is instantiated, which is the same place [linear-generics] checks
    /// its own ban. `Unknown` passes for the usual reason
    /// [type-unknown-lenient] — one mistake, one diagnostic.
    fn key_ineligible(&self, ty: &Ty, canonical: bool) -> Option<Message> {
        self.hash_ineligible(ty, 0, canonical).map(|reason| {
            messages::col_key_eligible_key(&ty, &reason)
        })
    }

    /// [op-arm-eq] `union == value` / `value == union`: when one operand is a
    /// union and the other is a plain value whose type matches exactly one of
    /// its **value** arms, record the arm test so the IR can lower it to
    /// `union is arm && arm == value`. Returns whether it fired (and so
    /// replaces the ordinary operand rules). Scoped to a **basic**-typed arm
    /// (the realistic case — `Int?`, `Long?`, `Char?`, …), where the inner
    /// `==` is the host's own operator; a struct arm would need its `eq`
    /// resolved at a span of its own, which this form does not have, so it
    /// falls through to the ordinary rules there.
    fn try_arm_compare(&mut self, op: BinaryOp, span: Span, lhs: &Expr, rhs: &Expr, l: &Ty, r: &Ty) -> bool {
        if !matches!(op, BinaryOp::Eq | BinaryOp::NotEq) {
            return false;
        }
        let (lw, rw) = (crate::literal::widen(l), crate::literal::widen(r));
        // Identify the union side and the value side.
        let (subject_ty, value_ty, subject_is_lhs, subject_expr) = if matches!(lw, Ty::Union(_)) && !matches!(rw, Ty::Union(_)) {
            (&lw, &rw, true, lhs)
        } else if matches!(rw, Ty::Union(_)) && !matches!(lw, Ty::Union(_)) {
            (&rw, &lw, false, rhs)
        } else {
            return false;
        };
        let value_base = value_ty.strip_quals();
        // The value must not itself be `None`/optional (`x == None` is the
        // `is None` form, handled elsewhere), and must be a basic type.
        if value_base.is_none_ty() || !value_base.is_basic() {
            return false;
        }
        // Exactly one value arm shares the value's base type.
        let matching: Vec<&Ty> = subject_ty
            .value_arms()
            .into_iter()
            .filter(|a| a.strip_quals() == value_base)
            .collect();
        let [arm] = matching.as_slice() else {
            return false;
        };
        let arm_ty = (*arm).clone();
        // Build the arm test on the subject's representation, reusing the
        // `is`-lowering so the runtime arm identity matches [type-union-arm-identity].
        let repr = self.repr_of(subject_expr, subject_ty);
        let pat = CheckPat {
            quals: Vec::new(),
            qual_args: Vec::new(),
            base: Some(arm_ty.strip_quals().clone()),
            is_none: false,
            unresolved: false,
        };
        let Some(test) = self.union_test_for(&repr, &pat) else {
            return false;
        };
        self.out.arm_compares.insert(
            self.key(span),
            ArmCompare { test, arm_ty, subject_is_lhs },
        );
        true
    }

    /// [op-order] [op-equality] A comparison operator is **the call it names**
    /// (O1, R10): `a == b` is `eq(a, b)`, `a != b` is `!eq(a, b)`, and `a < b`
    /// is `cmp(a, b) < 0` (`>`, `<=`, `>=` alike), resolved exactly as the
    /// written call is — no semantic fast path (R10 D1), the operand types as
    /// the call ranks them, qualifiers included (D5), and no same-type rule
    /// (D6: `m == f` with `eq(Meters, Feet)` declared is that call).
    ///
    /// * **The enclosing fn's own implicit first** [implicit-resolve-body]:
    ///   one named `eq`/`cmp` whose parameters the operands fit takes the
    ///   operator, as it takes the call — at a scalar or `Str` too (D1) — and
    ///   several are ranked like overloads [implicit-same-name] (D21).
    ///   [cmp-binder] A binder alias counts by the slot it fills
    ///   (`?cmp: cmp2` is a `cmp` here), as decided 2026-09-22; the call
    ///   `cmp(a, b)` does not see it (PIPELINE.md §II.10 P13, open).
    /// * **Then the visible declarations and the available effects' members**,
    ///   by `resolve_named_call` (R10 D3: a member competes; a tie is the
    ///   ordinary ambiguity, `m@E` its remedy). Under [op-unique-shape] a
    ///   concrete type has one candidate.
    /// * **Lowerings before the call, kept:** [op-arm-eq] (R10 D7, already
    ///   done by the caller) and [op-promote]: mixed numeric widths widen the
    ///   narrower operand first, so `i < l` is `cmp(widen(i), l) < 0`, and an
    ///   integer and a float operand are refused — the call rule has no
    ///   widening of its own (§II.10 P11, open).
    /// * **Float ordering with nothing to call** keeps the host's IEEE order:
    ///   std declares no `cmp(Double, Double)` (a sorted container of them has
    ///   no total order), so `<` on floats goes through a `cmp` only when one
    ///   is in reach, an implicit (§II.10 P12, open).
    ///
    /// Whether the backends spell it natively is read off the selected
    /// declaration (std's intrinsic `eq`/`cmp` at a basic type), not the
    /// operand types [backend-core-layers]. A possibly-`None` operand was refused by
    /// the caller, which then skips this (one mistake, one diagnostic);
    /// `Unknown` and `Never` stay lenient [type-unknown-lenient].
    fn check_comparison_operands(
        &mut self,
        op: ast::BinaryOp,
        span: Span,
        lhs: &'p Expr,
        rhs: &'p Expr,
        l: &Ty,
        r: &Ty,
    ) {
        let equality = matches!(op, ast::BinaryOp::Eq | ast::BinaryOp::NotEq);
        // [type-literal] A literal (or a union of them) compares as its base.
        let (lw, rw) = (crate::literal::widen(l), crate::literal::widen(r));
        let (lb, rb) = (lw.strip_quals().clone(), rw.strip_quals().clone());
        if lb.is_unknown() || rb.is_unknown() || matches!(lb, Ty::Never) || matches!(rb, Ty::Never) {
            return;
        }
        let sym = op_symbol(op);
        let member: &'static str = if equality { "eq" } else { "cmp" };
        // [op-promote] Mixed numeric widths widen within their class before the
        // call, for every comparison (equality joined 2026-09-18): the
        // narrower operand records a promotion and the call is made at the
        // wider type. Mixing the integer and float classes is refused.
        let (lt, rt) = match (op_numeric(&lb), op_numeric(&rb)) {
            (Some((lf, lr)), Some((rf, rr))) => {
                if lf != rf {
                    self.error(span, messages::op_promote_mixed_classes(&sym, &lw, &rw));
                    return;
                }
                match lr.cmp(&rr) {
                    std::cmp::Ordering::Less => {
                        self.record_promotion(lhs.span(), &rb);
                        (rb.clone(), rw.clone())
                    }
                    std::cmp::Ordering::Greater => {
                        self.record_promotion(rhs.span(), &lb);
                        (lw.clone(), lb.clone())
                    }
                    std::cmp::Ordering::Equal => (lw.clone(), rw.clone()),
                }
            }
            _ => (lw.clone(), rw.clone()),
        };
        let tys = vec![lt.clone(), rt.clone()];
        let ret = if equality { Ty::named("Bool") } else { Ty::named("Int") };
        // 1. [implicit-resolve-body] The enclosing fn's own implicit of the
        // name, when the operands fit it; [cmp-binder] by the slot it fills.
        let fits = |p: &ImplicitParam| match p.ty.strip_quals() {
            Ty::Fn { params, .. } => params.len() == 2 && tys.iter().zip(params).all(|(a, q)| Self::arg_fits_fn_value(a, q)),
            _ => p.ty.is_unknown(),
        };
        let is_member = |p: &ImplicitParam| p.name == member || p.slot.as_deref() == Some(member);
        match self.pick_own_implicit_by(&is_member, &fits) {
            Ok(Some(own)) => {
                let got = self.operator_through_implicit(&own, lhs, rhs, &tys, span);
                self.operator_returns(&got, &ret, sym, member, &lt, &rt, span);
                return;
            }
            Ok(None) => {}
            Err(tied) => {
                // [cmp-binder] Named by what the body calls them, an alias
                // included: that is what the remedy writes.
                let shown: Vec<String> = self
                    .own_implicits
                    .iter()
                    .filter(|p| is_member(p) && fits(p))
                    .map(|p| format!("`{}`", p.local))
                    .collect();
                self.operator_implicit_tie(sym, member, &lt, &rt, tied.len(), &shown, span);
                return;
            }
        }
        // [op-order] Float ordering with no `cmp` in reach: the host's order.
        if !equality && matches!(op_numeric(lt.strip_quals()), Some((true, _))) {
            let want = Ty::Fn { params: tys.clone(), ret: Box::new(ret.clone()), contract: None, effects: Vec::new() };
            if !self.some_fn_accepts(member, &want) {
                return;
            }
        }
        // 2. The call: visible fns and the available effects' members.
        let remedy = self.compare_remedy(lt.strip_quals(), member);
        let saved = self.operator_site.replace(OperatorSite { sym, member, lhs: lt.clone(), rhs: rt.clone(), remedy });
        self.pending_arg_tys = Some(tys);
        let args: [&'p Expr; 2] = [lhs, rhs];
        let got = self.resolve_named_call(member, span, &[], &args, &[], Some(&ret), None, span);
        self.pending_arg_tys = None;
        self.operator_site = saved;
        self.operator_returns(&got, &ret, sym, member, &lt, &rt, span);
    }

    /// [op-equality] [op-order] `a == b` through the enclosing fn's own
    /// implicit `own`: the call through it [implicit-resolve-body], recorded
    /// as a call through that local is (`local_calls`, and the local it is
    /// for the IR), with its arguments checked as a fn value's are.
    /// [op-arith] Arithmetic alike. Answers what the implicit returns.
    fn operator_through_implicit(&mut self, own: &ImplicitParam, lhs: &'p Expr, rhs: &'p Expr, tys: &[Ty], span: Span) -> Ty {
        let key = self.key(span);
        self.out.local_calls.insert(key);
        self.out.local_call_names.insert(key, own.local.clone());
        let (params, got, contract, effects) = match self.lookup(&own.local).map(|v| v.narrowed.strip_quals().clone()) {
            Some(Ty::Fn { params, ret, contract, effects }) => (params, *ret, contract, effects),
            _ => match own.ty.strip_quals().clone() {
                Ty::Fn { params, ret, contract, effects } => (params, *ret, contract, effects),
                _ => return Ty::Unknown,
            },
        };
        if let Some(v) = self.lookup_mut(&own.local) {
            v.used = true;
        }
        self.check_fn_value_effects(&effects, span);
        let callee = format!("`{}`", own.local);
        self.check_fn_value_args(&callee, &[lhs, rhs], &params, contract.as_deref(), Some(tys.to_vec()), span);
        got
    }

    /// [op-equality] [op-order] [op-arith] [implicit-same-name] Several of the
    /// enclosing fn's own implicits fit an operator's operands and none is
    /// more specific: the operator cannot choose (R10 D21).
    #[allow(clippy::too_many_arguments)]
    fn operator_implicit_tie(&mut self, sym: &str, member: &str, lt: &Ty, rt: &Ty, tied: usize, shown: &[String], span: Span) {
        self.error(
            span,
            messages::implicit_same_name_operator(&sym, &lt, &member, &rt, &tied, &shown.join(", ")),
        );
    }

    /// [op-equality] [op-order] What the operator's call returned must be what
    /// the operator reads: `eq` a `Bool`, `cmp` an `Int` (an `eq` returning
    /// anything else is not of `==`'s shape [op-unique-shape], but a call may
    /// still reach one).
    #[allow(clippy::too_many_arguments)]
    fn operator_returns(&mut self, got: &Ty, want: &Ty, sym: &str, member: &str, lt: &Ty, rt: &Ty, span: Span) {
        if got.is_unknown() || matches!(got, Ty::Never) || is_subtype(got, want) {
            return;
        }
        self.error(span, messages::op_order_return_type(&sym, &lt, &member, &rt, &want, &got));
    }

    /// [op-order] [op-equality] The remedy a refused comparison names, which
    /// depends on what the operand *is*: a type of your own can declare the
    /// member (or ask for the structural one), while an opaque `T` can only
    /// have it passed in.
    fn compare_remedy(&self, base: &Ty, member: &str) -> String {
        let group = match member {
            "eq" => "Eq",
            _ => "Ordered",
        };
        match base {
            Ty::Var(v) => format!(
                " — nothing is knowable about `{v}` unless the signature asks: add \
                 `?{group}<{v}>` (or `?{member}: …`) to this function's parameters"
            ),
            Ty::Named { name, .. } if self.symbols.structs.contains_key(name.as_str()) => format!(
                " — declare a `{member}` inside `{name}`'s body, or ask for the \
                 structural one with `: …<self> by auto` on `{name}`"
            ),
            _ => format!(
                " — declare a `{member}` for it, or ask for the structural one with \
                 `: …<self> by auto` where the type is declared"
            ),
        }
    }

    /// [op-arith] [op-pow] An arithmetic operator is **the call it names**
    /// (OPERATOR_OVERLOAD.md O1, PIPELINE.md §3 R10): `a + b` is `plus(a, b)`,
    /// `-` `minus`, `*` `times`, `/` `divide`, and `a ** b` is `pow(a, b)`,
    /// resolved exactly as the written call is, as the comparisons are
    /// (B3.3c): the enclosing fn's own implicit of the name first, by name as
    /// the call sees it, ranked like overloads [implicit-same-name]; then the
    /// visible fns and the available effects' members by `resolve_named_call`
    /// with the operands pre-typed (R10 D3: a member competes, a tie is the
    /// call's ambiguity). Under [op-unique-shape] a concrete type has one
    /// candidate, declared in its own file — std's intrinsic ones for the
    /// numeric scalars, in `std.core.basic`.
    ///
    /// * **The result is the call's return type** (D-3: any).
    /// * **[op-promote] stays a lowering before the call** for `+ - * /`, as at
    ///   a comparison (§II.10 P11): mixed numeric widths widen the narrower
    ///   operand and the call is made at the wide type (`i + l` is
    ///   `plus(widen(i), l)`); mixing the integer and float classes is refused
    ///   before any call. **`**` widens nothing**: an exponent is not the same
    ///   kind of operand as a base (`pow(Long, Int)`), so `a ** b` is
    ///   `pow(a, b)` at the written types.
    /// * `Unknown` and `Never` stay lenient [type-unknown-lenient], a known
    ///   numeric side carrying the result; a **type variable no longer is**:
    ///   at a generic `T`, `a + b` needs an enclosing `?plus` (the call's
    ///   answer), as `<` needs a `?cmp`.
    ///
    /// Whether the backends spell the host's operator is read off the
    /// selected declaration (`Ctx::is_primitive_operator`), never the operand
    /// types [backend-core-layers].
    #[allow(clippy::too_many_arguments)]
    fn check_arith_call(
        &mut self,
        op: ast::BinaryOp,
        span: Span,
        lhs: &'p Expr,
        rhs: &'p Expr,
        l: &Ty,
        r: &Ty,
    ) -> Ty {
        let pow = matches!(op, ast::BinaryOp::Pow);
        // [type-literal] A literal (or a union of them) computes as its base.
        let (lw, rw) = (crate::literal::widen(l), crate::literal::widen(r));
        let (lb, rb) = (lw.strip_quals().clone(), rw.strip_quals().clone());
        let lenient = |t: &Ty| t.is_unknown() || matches!(t, Ty::Never);
        if lenient(&lb) || lenient(&rb) {
            // One mistake, one diagnostic: an unknown side neither errors nor
            // widens — a known numeric side carries the result.
            return match (op_numeric(&lb), op_numeric(&rb)) {
                (Some(_), _) => lb,
                (_, Some(_)) if !pow => rb,
                _ => Ty::Unknown,
            };
        }
        let sym = op_symbol(op);
        let member = arith_member(op);
        let (lt, rt) = match (op_numeric(&lb), op_numeric(&rb)) {
            (Some((lf, lr)), Some((rf, rr))) if !pow => {
                if lf != rf {
                    self.error(span, messages::op_promote_mixed_classes(&sym, &lw, &rw));
                    return Ty::Unknown;
                }
                match lr.cmp(&rr) {
                    std::cmp::Ordering::Less => {
                        self.record_promotion(lhs.span(), &rb);
                        (rb.clone(), rw.clone())
                    }
                    std::cmp::Ordering::Greater => {
                        self.record_promotion(rhs.span(), &lb);
                        (lw.clone(), lb.clone())
                    }
                    std::cmp::Ordering::Equal => (lw.clone(), rw.clone()),
                }
            }
            _ => (lw.clone(), rw.clone()),
        };
        let tys = vec![lt.clone(), rt.clone()];
        // 1. [implicit-resolve-body] The enclosing fn's own implicit of the
        // name, when the operands fit it.
        let fits = |p: &ImplicitParam| match p.ty.strip_quals() {
            Ty::Fn { params, .. } => params.len() == 2 && tys.iter().zip(params).all(|(a, q)| Self::arg_fits_fn_value(a, q)),
            _ => p.ty.is_unknown(),
        };
        let named = |p: &ImplicitParam| p.name == member;
        match self.pick_own_implicit_by(&named, &fits) {
            Ok(Some(own)) => return self.operator_through_implicit(&own, lhs, rhs, &tys, span),
            Ok(None) => {}
            Err(tied) => {
                let shown: Vec<String> =
                    self.own_implicits.iter().filter(|p| named(p) && fits(p)).map(|p| format!("`{}`", p.local)).collect();
                self.operator_implicit_tie(sym, member, &lt, &rt, tied.len(), &shown, span);
                return Ty::Unknown;
            }
        }
        // 2. The call: visible fns and the available effects' members.
        let remedy = self.arith_remedy(op, &lt, &rt);
        let saved = self.operator_site.replace(OperatorSite { sym, member, lhs: lt.clone(), rhs: rt.clone(), remedy });
        self.pending_arg_tys = Some(tys);
        let args: [&'p Expr; 2] = [lhs, rhs];
        let got = self.resolve_named_call(member, span, &[], &args, &[], None, None, span);
        self.pending_arg_tys = None;
        self.operator_site = saved;
        got
    }

    /// [op-arith] [op-pow] The remedy a refused arithmetic operator names,
    /// by what the left operand is (D-2: the operator is on it).
    fn arith_remedy(&self, op: ast::BinaryOp, l: &Ty, r: &Ty) -> String {
        let member = arith_member(op);
        let is = |t: &Ty, n: &str| matches!(t.strip_quals(), Ty::Named { name, .. } if name == n);
        if matches!(op, ast::BinaryOp::Add) && (is(l, "Str") || is(r, "Str")) {
            return " — `+` does not concatenate strings: build the text with interpolation \
                    (`\"${a}${b}\"`)"
                .to_string();
        }
        if is(l, "Byte") || is(r, "Byte") {
            return " — a `Byte` is an octet, not a number: compute with `to_int` and come back \
                    with `to_byte`"
                .to_string();
        }
        if matches!(op, ast::BinaryOp::Pow) && op_numeric(l.strip_quals()).is_some() {
            return " — std's `pow` takes `(Int, Int)`, `(Long, Int)`, `(Double, Int)` and \
                    `(Double, Double)`: convert an operand (`to_int`, `to_double`)"
                .to_string();
        }
        match l.strip_quals() {
            Ty::Var(v) => format!(
                " — nothing is knowable about `{v}` unless the signature asks: add `?{member}: \
                 (a: {v}, b: {r}) -> {v}` to this function's parameters"
            ),
            Ty::Named { name, .. } if self.symbols.structs.contains_key(name.as_str()) => format!(
                " — declare a `{member}` taking `({l}, {r})` in `{name}`'s own file"
            ),
            _ => String::new(),
        }
    }

    /// [op-arith] `%`'s operand typing, the one arithmetic operator that names
    /// no function (PIPELINE.md §II.10 P16; `+ - * /` and `**` are
    /// [`Checker::check_arith_call`]). Numeric operands only (user decision
    /// 2026-09-14), with implicit widening *within* a class
    /// (`Int % Long → Long`; the narrower side records a promotion
    /// [op-promote]) and an explicit-conversion error *across* classes. The
    /// result is the promoted operand type. `Unknown`/`Never` stay lenient
    /// [type-unknown-lenient]; a type variable does not.
    fn check_arith(
        &mut self,
        op: ast::BinaryOp,
        span: Span,
        lhs: &Expr,
        rhs: &Expr,
        l: &Ty,
        r: &Ty,
    ) -> Ty {
        let (lb, rb) = (l.strip_quals(), r.strip_quals());
        if op_lenient(lb) || op_lenient(rb) {
            // One mistake, one diagnostic: an unknown side neither errors
            // nor widens — a known numeric side carries the result.
            return match (op_numeric(lb), op_numeric(rb)) {
                (Some(_), _) => lb.clone(),
                (_, Some(_)) => rb.clone(),
                _ => Ty::Unknown,
            };
        }
        let sym = op_symbol(op);
        match (op_numeric(lb), op_numeric(rb)) {
            (Some((lf, lr)), Some((rf, rr))) => {
                if lf != rf {
                    self.error(span, messages::op_promote_mixed_classes(&sym, &l, &r));
                    return Ty::Unknown;
                }
                match lr.cmp(&rr) {
                    std::cmp::Ordering::Equal => lb.clone(),
                    std::cmp::Ordering::Less => {
                        self.record_promotion(lhs.span(), rb);
                        rb.clone()
                    }
                    std::cmp::Ordering::Greater => {
                        self.record_promotion(rhs.span(), lb);
                        lb.clone()
                    }
                }
            }
            _ => {
                self.error(span, messages::op_arith_non_numeric(&sym, &l, &r));
                Ty::Unknown
            }
        }
    }

    /// [op-bool] A truth-valued operand (`&&`, `||`, `!`): `Bool` only —
    /// the value-position twin of the condition rule (no truthiness).
    fn require_bool_operand(&mut self, sym: &str, operand: &Expr, ty: &Ty) {
        let tb = ty.strip_quals();
        if op_lenient(tb) {
            return;
        }
        if matches!(tb, Ty::Named { name, .. } if name == "Bool") {
            return;
        }
        self.error(operand.span(), messages::op_bool_not_bool(&sym, &ty));
    }

    /// [op-promote] Records a numeric widening on an operand, for the
    /// backends whose operators do not mix widths natively (Rust casts;
    /// Kotlin's operator set covers the mixes).
    fn record_promotion(&mut self, span: Span, target: &Ty) {
        self.out.promotions.insert(self.key(span), target.clone());
    }

    /// [cmp-groups] Whether a **visible** `cmp`/`eq`/`hash` takes this named
    /// type as its first argument — the "does it have the capability" question,
    /// asked the way the declaration walk can ask it (before any call is
    /// resolved). It replaced `canbe hashed`/`canbe ordered`, which asked
    /// whether the *declaration* said so: a type is orderable now exactly when
    /// an ordering for it exists, whether hand-written [fn-attached] or
    /// generated [obligation-by].
    fn has_member_for(&self, member: &str, name: &str) -> bool {
        self.scope.fns.get(member).is_some_and(|entries| {
            entries.iter().any(|e| {
                e.decl
                    .params
                    .first()
                    .is_some_and(|p| matches!(&p.ty, ast::Type::Named { base, .. }
                        if self.named(base).key(self.symbols).unwrap_or(&base.name.name) == name))
            })
        })
    }

    /// [col-hashed-ordered] Whether a type can be **hashed** — the
    /// requirement for a `Set` element or a `Map` key. `None` is eligible.
    ///
    /// [col-key-eligible] `canonical` asks for the bar a key meets when its
    /// identity is **resolved by name**: a struct (or an opaque type) has to
    /// have its own `hash` and `eq`. Where the identity is written instead —
    /// `Set<P>(my_hash, my_eq)`, a binder, a `let` annotation that the
    /// initializer fills — only the intrinsic bar applies: what no identity
    /// can fix (a float, a function value, a union).
    fn hash_ineligible(&self, ty: &Ty, depth: usize, canonical: bool) -> Option<String> {
        if depth > 8 {
            return None;
        }
        match ty.strip_quals() {
            Ty::Var(_) | Ty::Unknown | Ty::Never => None,
            Ty::Named { name, args } => match name.as_str() {
                "Int" | "Long" | "Str" | "Char" | "Bool" => None,
                "Double" | "Float" => Some(format!(
                    "`{name}` is not hashable, because floating-point equality \
                     and hashing disagree between the backends (`NaN` equals \
                     nothing, not even itself). Equality on a value holding one \
                     still works — hashing is what cannot"
                )),
                // A container hashes when its elements do (Rust's `Vec` and
                // Kotlin's `List` both hash structurally).
                "List" | "Set" => args
                    .first()
                    .and_then(|a| self.hash_ineligible(a, depth + 1, canonical)),
                "Map" => args
                    .iter()
                    .take(2)
                    .find_map(|a| self.hash_ineligible(a, depth + 1, canonical)),
                // A struct keyed by a written identity needs nothing of its
                // own; std's opaque types are what they are (`Bytes` is one
                // mutable object on one backend, whoever hashes it).
                _ if !canonical && self.symbols.structs.contains_key(name.as_str()) => None,
                _ if self.symbols.structs.contains_key(name.as_str()) => {
                    // [cmp-groups] A key needs both halves: a `hash` to find the
                    // bucket and an `eq` to compare within it.
                    if self.has_member_for("hash", name) && self.has_member_for("eq", name) {
                        None
                    } else {
                        Some(format!(
                            "`{name}` has no `hash`: declare one (with an `eq`) in its \
                             file, or ask for the structural pair with \
                             `: Hashed<self> by auto`"
                        ))
                    }
                }
                // An `intrinsic type` of std's with a canonical `hash`
                // (`Bytes` has `eq` only, so it is not a key).
                _ if self.has_member_for("hash", name) && self.has_member_for("eq", name) => None,
                _ => Some(format!("`{name}` is not hashable")),
            },
            Ty::Tuple(elems) => elems
                .iter()
                .find_map(|e| self.hash_ineligible(e, depth + 1, canonical)),
            Ty::Array(elem) => self.hash_ineligible(elem, depth + 1, canonical),
            Ty::Fn { .. } => Some(
                "a function value is not hashable: neither backend can \
                 compare or hash one meaningfully"
                    .to_string(),
            ),
            Ty::Union(_) => Some(
                "a union is not hashable yet: every arm would have to be, \
                 which this version does not check"
                    .to_string(),
            ),
            other => Some(format!("`{other}` is not hashable")),
        }
    }

    /// [col-hashed-ordered] Whether a type can be **ordered** — the
    /// requirement for a `SortedSet` element or a `SortedMap` key.
    fn order_ineligible(&self, ty: &Ty, depth: usize, canonical: bool) -> Option<String> {
        if depth > 8 {
            return None;
        }
        match ty.strip_quals() {
            Ty::Var(_) | Ty::Unknown | Ty::Never => None,
            Ty::Named { name, args } => match name.as_str() {
                "Int" | "Long" | "Str" | "Char" | "Bool" => None,
                "Double" | "Float" => Some(format!(
                    "`{name}` is not orderable, because Rust's `f64` has no \
                     total order (`NaN` compares less, greater and equal to \
                     nothing), so a sorted collection of them would not agree \
                     between the backends"
                )),
                // Lists and tuples order lexicographically by their elements
                // (user decision 2026-09-12).
                "List" => args
                    .first()
                    .and_then(|a| self.order_ineligible(a, depth + 1, canonical)),
                _ if !canonical && self.symbols.structs.contains_key(name.as_str()) => None,
                _ if self.symbols.structs.contains_key(name.as_str()) => {
                    if self.has_member_for("cmp", name) {
                        None
                    } else {
                        Some(format!(
                            "`{name}` has no `cmp`: declare one in its file, or ask for \
                             the structural one with `: Ordered<self> by auto`"
                        ))
                    }
                }
                _ if self.has_member_for("cmp", name) => None,
                _ => Some(format!("`{name}` is not orderable")),
            },
            Ty::Tuple(elems) => elems
                .iter()
                .find_map(|e| self.order_ineligible(e, depth + 1, canonical)),
            Ty::Array(elem) => self.order_ineligible(elem, depth + 1, canonical),
            Ty::Fn { .. } => Some(
                "a function value is not orderable: neither backend can \
                 compare one"
                    .to_string(),
            ),
            Ty::Union(_) => Some(
                "a union is not orderable: comparing values of different \
                 types has no obvious meaning (user decision 2026-09-12)"
                    .to_string(),
            ),
            other => Some(format!("`{other}` is not orderable")),
        }
    }

    /// [cmp-carry] Resolves and records the identities a written keyed-container
    /// type carries, so a backend can name the declaration behind each.
    ///
    /// Only *named* ones: a binder is filled per call [cmp-binder], and the
    /// emitters read that from the call's implicit arguments instead.
    fn record_carried_identities(&mut self, base: &TypeRef, arity: usize) {
        if base.value_args.is_empty() {
            return;
        }
        let _ = arity;
        let empty = HashMap::new();
        let type_args: Vec<Ty> = base
            .args
            .iter()
            .map(|a| self.lower_type_subst(a, &empty, 0))
            .collect();
        let subject = match type_args.first() {
            Some(ty) => ty.clone(),
            None => return,
        };
        // [type-identity] [name-table] The slots are the declaration's: by
        // the key the written name means where it is written.
        let name = self.written_key_of(base);
        for (at, written) in base.value_args.iter().enumerate() {
            let Some(want) = self.type_slot_ty(&name, &type_args, at) else {
                continue;
            };
            let Some(id @ FnId::Named { .. }) = self.written_fn_id(written, Some(&want)) else {
                continue;
            };
            let key = (self.file_idx, id.clone(), subject.clone());
            if self.out.carried_identities.contains_key(&key) {
                continue;
            }
            match self.resolve_identity(&id, &want) {
                Ok((found, _)) => {
                    self.out.carried_identities.insert(key, found);
                    // [fn-ref-table] [mod-used-only] The written identity is a
                    // fn *reference* at this span: recording it here is what
                    // makes the module declaring it reachable per-*file*, now
                    // that a pure fn name no longer carries a name-based edge.
                    self.out.fn_refs.insert(self.key(written.span()), found);
                }
                Err(_) => {
                    let slot = self
                        .type_fn_slots(&name)
                        .get(at)
                        .map(|s| s.name.clone())
                        .unwrap_or_else(|| "?".to_string());
                    self.error(
                        written.span(),
                        messages::cmp_carry_slot_mismatch(&id, &slot, &base.name.name, &want),
                    );
                }
            }
        }
    }

    /// [col-key-eligible] Reports an ineligible key in a written
    /// `Set<T>` / `Map<K, V>`. The *value* side of a map is unrestricted,
    /// so only the first argument is checked.
    fn check_key_eligibility(&mut self, base: &TypeRef) {
        // [col-sorted] The sorted collections need an *orderable* key, the
        // unordered ones a *hashable* one — different bars, so the container
        // decides which is checked.
        let Some((arity, ordered)) = keyed_container(&base.name.name) else {
            return;
        };
        // [cmp-carry] A keyed container may **name** the ordering or hash it keeps
        // its keys by. The identity is resolved *here*, where the type is
        // written, and recorded for the backends: one of them has to name the
        // declaration behind the name, and redoing resolution in an emitter is
        // how the two would come to disagree.
        self.record_carried_identities(base, arity);
        if base.args.len() != arity {
            return;
        }
        // [col-key-eligible] The canonical bar — the key's own `hash`/`eq`
        // (or `cmp`) — applies only where the identity will be resolved by
        // name: no identity written, and not a `let` pattern the initializer
        // fills. `Set<P>(my_hash, my_eq)` and `Set<P>(?hash, ?eq)` say where
        // the identity comes from, and a key with none of its own is fine
        // there (found 2026-10-20: the call form was accepted and the
        // annotation of the same value refused).
        let canonical = base.value_args.is_empty() && !self.let_pattern;
        let empty = HashMap::new();
        let key = self.lower_type_subst(&base.args[0], &empty, 0);
        let bad = if ordered {
            self.sorted_key_ineligible(&key, canonical)
        } else {
            self.key_ineligible(&key, canonical)
        };
        if let Some(reason) = bad {
            let span = base.args[0].span();
            // [type-unknown-lenient] Shared with the inferred path's dedup: a
            // written annotation and the call it types are one mistake.
            self.reported_ineligible_keys.insert(format!("{key}"));
            self.error(span, reason);
        }
    }

    /// [col-sorted-list] `Sorted` over a `List<T>` is a claim about the
    /// element order, so `Sorted List<Double>` is as meaningless as a
    /// `SortedSet<Double>` and is refused in the same place, by element.
    fn check_sorted_list_claim(&mut self, qualifiers: &[ast::TypeRef], base: &ast::TypeRef) {
        if base.name.name != "List" || base.args.len() != 1 {
            return;
        }
        if !qualifiers.iter().any(|q| q.name.name == "Sorted") {
            return;
        }
        let empty = HashMap::new();
        let elem = self.lower_type_subst(&base.args[0], &empty, 0);
        if let Some(reason) = self.sorted_list_elem_ineligible(&elem) {
            self.error(base.args[0].span(), reason);
        }
    }

    /// [col-sorted-list] The element rule for a `Sorted List<T>` claim.
    fn sorted_list_elem_ineligible(&self, elem: &Ty) -> Option<Message> {
        self.order_ineligible(elem, 0, true).map(|reason| {
            messages::col_sorted_list_element(&elem, &reason)
        })
    }

    /// [col-sorted] The key rule for the sorted collections.
    fn sorted_key_ineligible(&self, ty: &Ty, canonical: bool) -> Option<Message> {
        self.order_ineligible(ty, 0, canonical).map(|reason| {
            messages::col_sorted_key(&ty, &reason)
        })
    }

    /// [col-key-eligible] The same rule against an already-lowered type,
    /// for the **inferred** case: `Set(1.5)` writes no type at all, so
    /// the ineligible key only exists in the substitution the call
    /// resolved. Walks nested positions so `List<Map<Double, Int>>` is
    /// caught too.
    fn check_key_eligibility_ty(&mut self, ty: &Ty, span: Span, depth: usize) {
        // [type-unknown-lenient] One mistake, one diagnostic: an ineligible key
        // a *written* type already reported must not be reported again when a
        // call's substitution arrives at the same type. `fn probe() -> Set<Double>`
        // with `return Set()` says it once at the declaration — where the fix
        // goes — and the call inside it learned `T = Double` from that very
        // annotation (2026-09-26, with the expected-type seeding that made the
        // call's instantiation known at all).

        if depth > 8 {
            return;
        }
        // [col-sorted-list] An *inferred* `Sorted List<T>` — what `sort` and
        // `mut_sort` return — carries the claim as a qualifier, so it has to
        // be read before `strip_quals` throws it away.
        if ty.quals().iter().any(|q| q.name == "Sorted") {
            if let Ty::Named { name, args } = ty.strip_quals() {
                if name == "List" && args.len() == 1 {
                    if let Some(reason) = self.sorted_list_elem_ineligible(&args[0]) {
                        self.error(span, reason);
                        return;
                    }
                }
            }
        }
        match ty.strip_quals() {
            Ty::Named { name, args } => {
                let (arity, ordered) = match name.as_str() {
                    "Set" => (1, false),
                    "Map" => (2, false),
                    "SortedSet" => (1, true),
                    "SortedMap" => (2, true),
                    _ => (0, false),
                };
                // [cmp-carry] The identities ride after the type arguments
                // (`Set<P>(my_hash, my_eq)`), so the arity is the type
                // arguments'. Only the intrinsic bar is checked here: whether
                // the key has an identity is the constructor's implicit
                // resolution to say, which runs after this and stays quiet
                // about a key refused here [type-unknown-lenient].
                let type_args: Vec<&Ty> = args
                    .iter()
                    .filter(|a| !matches!(a, Ty::FnName(_) | Ty::ValueRef { .. } | Ty::Const(_)))
                    .collect();
                if arity > 0 && type_args.len() == arity {
                    let bad = if ordered {
                        self.sorted_key_ineligible(type_args[0], false)
                    } else {
                        self.key_ineligible(type_args[0], false)
                    };
                    if let Some(reason) = bad {
                        // [type-unknown-lenient] One mistake, one diagnostic: an
                        // ineligible key a *written* type already reported is not
                        // reported again when a call's substitution arrives at the
                        // same type. `fn probe() -> Set<Double>` with
                        // `return Set()` says it at the declaration — where the
                        // fix goes — and the call learned `T = Double` from that
                        // very annotation (2026-09-26, with the expected-type
                        // seeding that made the call's instantiation known).
                        if self.reported_ineligible_keys.insert(format!("{}", type_args[0])) {
                            self.error(span, reason);
                        }
                        return;
                    }
                }
                for a in args {
                    self.check_key_eligibility_ty(a, span, depth + 1);
                }
            }
            Ty::Union(arms) => {
                for a in arms {
                    self.check_key_eligibility_ty(a, span, depth + 1);
                }
            }
            Ty::Tuple(elems) => {
                for e in elems {
                    self.check_key_eligibility_ty(e, span, depth + 1);
                }
            }
            Ty::Array(elem) => self.check_key_eligibility_ty(elem, span, depth + 1),
            _ => {}
        }
    }

    /// [linear-generics] The containment half: a **conditional container**
    /// (`struct Box<T canbe linear>`) is linear exactly when the
    /// instantiation puts a linear type where an opted-in parameter
    /// reaches a field (user decision 2026-09-12) — `Box<Lines>` owes,
    /// `Box<Int>` is plain. Depth-guarded: mutually recursive containers
    /// terminate conservatively.
    fn ty_own_linear_guarded(&self, ty: &Ty, depth: usize) -> bool {
        let _ = depth;
        crate::linear::ty_own_linear(self.symbols, &self.own_linear_generics, ty)
    }

    /// [linear-group] Whether a declaration is **linear**: it carries the
    /// `linear struct` modifier (user decision 2026-09-12 — replacing the
    /// designated `: Linear<self>` group entry, which itself replaced
    /// `canbe linear`, 2026-09-08). Declaring it obliges the same file to
    /// contain at least one **discharger** — a fn consuming a parameter of
    /// this type — checked at the declaration.
    ///
    /// A `close` alone never makes a type linear: only the modifier does,
    /// and generic code opts in per type parameter with `<T canbe linear>`
    /// [linear-generics]. Attaching an obligation on the strength of a
    /// function name is what [qual-*] keeps the compiler from doing.
    fn has_auto_linear(&self, name: &str) -> bool {
        crate::linear::has_auto_linear(self.symbols, name)
    }

    /// [linear-group] The opaque half of the same rule: `linear intrinsic
    /// type Reply<T>` (user decision 2026-09-15). Nothing else differs — a
    /// linear opaque type owes exactly as a `linear struct` does, and its
    /// discharge set is computed the same way; it simply has no fields for
    /// linearity to reach through.
    fn opaque_linear(&self, name: &str) -> bool {
        crate::linear::opaque_linear(self.symbols, name)
    }

    /// [linear-generics] Whether values of this struct *can* owe: the
    /// `linear struct` marker, or a conditional container (`canbe linear`
    /// reaching a field). What gates being a discharger — a same-file
    /// consuming fn of a `Box<T canbe linear>` may `discard` its parameter
    /// whatever the instantiation, since a plain instantiation's discard
    /// is an ordinary drop.
    fn linear_capable(&self, name: &str) -> bool {
        if self.opaque_linear(name) {
            return true;
        }
        // [linear-container] An opaque conditional container (`intrinsic type
        // List<T canbe linear>`) can owe too, so its file's consuming fns —
        // `drain` — are dischargers.
        if !self.linear_opt_in_positions(name).is_empty() {
            return true;
        }
        self.symbols.structs.get(name).is_some_and(|s| {
            s.linear
                || s.generic_canbe.iter().any(|(id, q)| {
                    q.name.name == "linear"
                        && s.fields.iter().any(|f| f.ty.as_ref().is_some_and(|t| type_mentions_generic(t, &id.name)))
                })
        })
    }

    /// [linear-group] The **discharge set** of a linear type: every fn
    /// declared in the *same file* as the type whose effective contract
    /// consumes a parameter of it — **plus every consuming member of an
    /// effect declared in that file** (the amendment the bare-members
    /// decision entailed, user decision 2026-09-14, FILE_SYSTEM.md §5.8):
    /// phase 4's `close(s: InStream)` is an `Fs` member, not a free fn, and
    /// `lib/std/core/fs.sv` declares the token and the effect together.
    ///
    /// Any of these is a legal terminal for the obligation. `discard` is
    /// legal only inside one of them — and for a member that means inside
    /// **every handler's implementing body**, wherever the handler lives,
    /// since discharger status attaches to the *member declaration*
    /// [linear-discard].
    fn discharge_set(&self, type_name: &str) -> Vec<String> {
        crate::linear::discharge_set(self.symbols, self.resolution, self.scope, self.inferred, type_name)
    }

    /// [linear-group] The declaration-site check for the *opaque* form,
    /// mirroring `check_obligations`' struct half: a `linear intrinsic type`
    /// must have a legal death in its own file. Reported at the name, with
    /// the remedy spelled with an `intrinsic fn`, since an opaque type's
    /// discharger cannot have a body either.
    fn check_linear_opaque(&mut self, t: &'p ast::TypeDecl) {
        if !t.linear {
            return;
        }
        if !self.discharge_set(self.symbols.key_or(t, &t.name.name)).is_empty() {
            return;
        }
        self.error(t.name.span, messages::linear_opaque_no_discharger(&t.name.name));
    }

    /// [linear-group] The discharge context a handler member's body runs in:
    /// the linear types the **effect member it implements** consumes. Matched
    /// by name and written parameter types
    /// (`salvo_core::effect_member_index`), so an overloaded member's bodies
    /// each get their own overload's contract — `close(InStream)` discharges
    /// an `InStream`, `close(OutStream)` an `OutStream`.
    /// [effect-handler-multi] Conformance of a handler to the effects it
    /// implements: every member of every face has an implementation, and a
    /// handler member that implements a member of *several* faces is one
    /// signature rather than two.
    ///
    /// The first half is what the target compilers used to report for us (a
    /// missing trait method), which put a Salvo mistake in a foreign
    /// diagnostic; the second is T-4(a)'s refinement — same-named members
    /// across faces are legal when overloading tells them apart (different
    /// written parameter types, so they are two members here) or when one
    /// method implements both (identical signatures), and refused where
    /// overloading *cannot* tell them apart.
    ///
    /// An `intrinsic` or `platform` handler is bodyless by design: its members
    /// are the backend's or the host's, so there is nothing here to match.
    fn check_handler_conformance(&mut self, h: &'p ast::HandlerDecl) {
        if h.intrinsic || h.platform {
            return;
        }
        let faces: Vec<(&'p ast::Type, &'p ast::EffectDecl)> = h
            .of
            .iter()
            .filter_map(|of| {
                let base = match of {
                    ast::Type::Named { base, .. } => base,
                    ast::Type::QualifiedGroup { base, .. } => match base.as_ref() {
                        ast::Type::Named { base, .. } => base,
                        _ => return None,
                    },
                    _ => return None,
                };
                self.named(base).effect.map(|e| (of, e))
            })
            .collect();
        let decls: Vec<&'p ast::EffectDecl> = faces.iter().map(|(_, e)| *e).collect();
        // Every member of every face, implemented.
        for (written, effect) in &faces {
            for (idx, member) in effect.fns.iter().enumerate() {
                let implemented = h.fns.iter().any(|f| {
                    crate::handler_member_faces(&decls, f)
                        .iter()
                        .any(|(e, i)| std::ptr::eq(*e, *effect) && *i == idx)
                });
                if implemented {
                    continue;
                }
                let params: Vec<String> = member
                    .params
                    .iter()
                    .filter(|p| !p.implicit)
                    .map(|p| p.ty.to_string())
                    .collect();
                self.error(
                    written.span(),
                    messages::effect_handler_multi_missing_member(
                        &h.name.name,
                        &effect.name.name,
                        &member.name.name,
                        &params.join(", "),
                    ),
                );
            }
        }
        // A member that implements several faces at once: one signature, or
        // nothing to choose between them by.
        for f in &h.fns {
            let matched = crate::handler_member_faces(&decls, f);
            let Some((first, first_idx)) = matched.first().copied() else {
                // [actor-private-send] A `send fn` no face declares is a
                // **private** member: reachable by `k@self(…)` and
                // `replyto k(…)` only, with a message and continuation
                // variant of its own in the emitters (user decision
                // 2026-09-27). Nothing to check against a face here.
                continue;
            };
            let Some(first_member) = first.fns.get(first_idx) else {
                continue;
            };
            for (other, other_idx) in matched.iter().skip(1) {
                let Some(other_member) = other.fns.get(*other_idx) else {
                    continue;
                };
                if self.same_member_signature(first, first_member, other, other_member) {
                    continue;
                }
                self.error(
                    f.name.span,
                    messages::effect_handler_multi_member_conflict(
                        &f.name.name,
                        &first.name.name,
                        &first_member.name.name,
                        &other.name.name,
                        &other_member.name.name,
                    ),
                );
            }
        }
    }

    /// [effect-handler-multi] Whether two effect members are the *same*
    /// signature, which is what lets one handler method implement both. Their
    /// written parameter types already agree (that is how they were matched),
    /// so what is left is the return type and the deduction clause — the two
    /// halves of the contract a caller relies on. Compared as lowered types
    /// under each effect's own generics, so an alias on one side is not a
    /// difference.
    fn same_member_signature(
        &mut self,
        a_effect: &'p ast::EffectDecl,
        a: &'p FnDecl,
        b_effect: &'p ast::EffectDecl,
        b: &'p FnDecl,
    ) -> bool {
        let lower = |me: &mut Self, effect: &'p ast::EffectDecl, ty: &Option<ast::Type>| {
            let saved = me.enter_generics(&effect.generics);
            let out = ty.as_ref().map(|t| me.lower_type(t));
            me.generics = saved;
            out
        };
        let a_ret = lower(self, a_effect, &a.return_type);
        let b_ret = lower(self, b_effect, &b.return_type);
        if a_ret != b_ret {
            return false;
        }
        // The deduction clauses, as written: a face that says a parameter is
        // consumed and one that says it is kept are different promises, and the
        // body can only keep one of them.
        let entries = |f: &'p FnDecl| -> Vec<String> {
            f.deductions
                .iter()
                .flatten()
                .map(|d| format!("{d:?}"))
                .collect()
        };
        entries(a) == entries(b)
    }

    /// [effect-handler-multi] The effects a handler implements, as declarations
    /// and in declaration order. A face whose name is not a declared effect in
    /// scope is dropped here and reported where it was written.
    fn handler_faces(&self, h: &'p ast::HandlerDecl) -> Vec<&'p ast::EffectDecl> {
        h.of
            .iter()
            .filter_map(|of| match of {
                ast::Type::Named { base, .. } => Some(base),
                ast::Type::QualifiedGroup { base, .. } => match base.as_ref() {
                    ast::Type::Named { base, .. } => Some(base),
                    _ => None,
                },
                _ => None,
            })
            .filter_map(|base| self.named(base).effect)
            .collect()
    }

    /// [effect-handler-multi] Searched across **every** implemented effect,
    /// since a member may belong to any of the handler's faces (and a member
    /// that implements two of them gets the first face's contract — the
    /// signatures are identical where that is legal, so the contracts are too).
    fn member_discharge_context(
        &self,
        h: &'p ast::HandlerDecl,
        f: &FnDecl,
    ) -> HashSet<String> {
        let faces = self.handler_faces(h);
        for (effect, idx) in crate::handler_member_faces(&faces, f) {
            if let Some(member) = effect.fns.get(idx) {
                return self.member_discharges(&effect.name.name, member);
            }
        }
        // [actor-private-send] A private member has no face to take its
        // contract from, so its *own* written clause is the contract — a
        // consumed linear parameter declared in this file makes the body a
        // discharge context, as it does for a free `send fn` [actor-free-send-fn].
        if f.is_send {
            return self.member_discharges_in(Some(self.file_idx), f);
        }
        HashSet::new()
    }

    /// [linear-group] The linear types a *member* consumes — the discharge
    /// contexts its implementing bodies get. A member consumes a parameter
    /// when its written clause moves it (`=> !s`), and the type joins only
    /// when the effect is declared in that type's own file, which is what
    /// keeps the discharge set a property of the type's own module.
    fn member_discharges(&self, effect_name: &str, member: &FnDecl) -> HashSet<String> {
        let effect_file = self.scope.effect_files.get(effect_name).copied();
        self.member_discharges_in(effect_file, member)
    }

    /// [linear-group] `member_discharges` with the owning file given: the
    /// effect's for a face member, the handler's for a private one.
    fn member_discharges_in(&self, effect_file: Option<usize>, member: &FnDecl) -> HashSet<String> {
        member
            .params
            .iter()
            .filter_map(|p| {
                let written = match &p.ty {
                    ast::Type::Named { base, .. } => base,
                    ast::Type::QualifiedGroup { base, .. } => match base.as_ref() {
                        ast::Type::Named { base, .. } => base,
                        _ => return None,
                    },
                    _ => return None,
                };
                let base = &written.name.name;
                // [name-table] The parameter's type means what it means in
                // the member's own file.
                let key = match self.resolution.names.written(written) {
                    Some(_) => self.written_key_of(written),
                    None => {
                        let scope = effect_file.map(|f| &self.resolution.scopes[f]).unwrap_or(self.scope);
                        Self::key_in(self.symbols, scope, base)
                    }
                };
                if !self.linear_capable(&key) {
                    return None;
                }
                if self.scope.struct_files.get(base.as_str()).copied() != effect_file {
                    return None;
                }
                let moved = member.deductions.iter().flatten().any(|d| {
                    d.param_name().is_some_and(|n| n.name == p.name.name)
                        && matches!(d.kind, ast::DeductionKind::Moved)
                });
                // [type-identity] By key, resolved where the member is
                // declared: `discard` compares the value's type.
                moved.then_some(key)
            })
            .collect()
    }

    /// [linear-group] A human-readable name for a linear value's legal
    /// terminals: its type's dischargers, backticked and `/`-joined
    /// ("`stop`/`join`"), or a generic phrase where the type is opaque (a
    /// generic parameter) or the set is empty (the declaration check
    /// reports that separately).
    fn linear_discharge_hint(&self, ty: &Ty) -> String {
        let name = match ty.strip_quals() {
            Ty::Named { name, .. } => Some(name.clone()),
            Ty::Union(arms) => arms.iter().find_map(|a| match a.strip_quals() {
                Ty::Named { name, .. } if self.has_auto_linear(name) => Some(name.clone()),
                _ => None,
            }),
            _ => None,
        };
        let set = name.as_deref().map(|n| self.discharge_set(n)).unwrap_or_default();
        if set.is_empty() {
            "its discharger".to_string()
        } else {
            set.iter()
                .map(|f| format!("`{f}`"))
                .collect::<Vec<_>>()
                .join(" / ")
        }
    }

    /// `ty_own_linear` over written (AST) types, without lowering: used by
    /// the composite refusal, which runs at declaration sites
    /// [linear-composite].
    ///
    /// Deliberately blind to `<T canbe linear>` type parameters: a
    /// declaration that *may* be instantiated with a linear type stores
    /// nothing by itself — std's `add(list: Mut List<T>, elem: T)` is a
    /// legal signature — so the generic case is refused at the
    /// instantiation instead (`var_in_composite` at the call site, the
    /// type-argument check at a struct literal).
    fn ast_type_own_linear(&self, ty: &ast::Type) -> Option<String> {
        match ty {
            ast::Type::Named { base, .. } => {
                let name = &base.name.name;
                let key = self.written_key_of(base);
                if self.has_auto_linear(&key) {
                    return Some(name.clone());
                }
                // [linear-container] A conditional container written with a
                // linear argument in an opted-in, holding position
                // (`Box<Lines>`, `List<Reply<Int>>`) is linear itself.
                for i in self.linear_opt_in_positions(&key) {
                    if let Some(arg) = base.args.get(i) {
                        if let Some(found) = self.ast_type_own_linear(arg) {
                            return Some(found);
                        }
                    }
                }
                None
            }
            ast::Type::QualifiedGroup { base, .. } => self.ast_type_own_linear(base),
            // A union value is one value, so an arm's obligation is the
            // union's — which is why writing one is a store.
            ast::Type::Union { arms, .. } => arms.iter().find_map(|a| self.ast_type_own_linear(a)),
            ast::Type::Nullable { inner, .. } => self.ast_type_own_linear(inner),
            _ => None,
        }
    }

    /// [linear-container] Which of `name`'s type parameters opt into holding
    /// **linear** values (`<T canbe linear>`) *and* actually hold one — the
    /// positions that make an instantiation linear when their argument is
    /// (user decisions 2026-09-12 for structs, 2026-09-16 for opaque types).
    ///
    /// The two kinds differ in how "holds" is decided: a struct's parameter
    /// must **reach a field** (`Box<T canbe linear> { item: T }`), because a
    /// parameter the fields never mention stores nothing; an **opaque** type
    /// has no fields to read, so an opted parameter holds by definition —
    /// which is exactly what `intrinsic type List<T canbe linear>` claims
    /// about its elements.
    fn linear_opt_in_positions(&self, name: &str) -> Vec<usize> {
        crate::linear::linear_opt_in_positions(self.symbols, name)
    }

    /// [linear-composite] R4 part 2 (interim, user decision 2026-09-08):
    /// a linear value may not be **stored in a composite** — a struct or
    /// handler-state field, a type argument, an array element, a tuple
    /// component, a union arm. Its obligation would have to travel with
    /// the container, and composition plus conditional linearity are one
    /// design question (roadmap L8), so until that is answered a linear
    /// value lives only in a local, a parameter or a return value.
    ///
    /// `position` names where the value would have landed, so the message
    /// reads as a refusal of the *store* rather than of the type.
    fn refuse_linear_composite(&mut self, span: Span, linear: &str, position: String) {
        self.error(span, messages::linear_container_position(&linear, &position));
    }

    /// [linear-container] Why a *particular* container position refuses an
    /// obligation, where the general rule would be unhelpful (LC-3, user
    /// decision 2026-09-15). Both cases are **semantic** — the container drops
    /// a value as part of doing its job — rather than fences the
    /// implementation could remove later, so the diagnostic says which.
    fn linear_position_reason(&self, container: &str, index: usize) -> Option<String> {
        // Std's own containers, not a program's types of the same name.
        if !self.symbols.intrinsic_types.contains_key(container) {
            return None;
        }
        match (container, index) {
            ("Set", 0) | ("SortedSet", 0) => Some(
                "a set **deduplicates**: inserting a value equal to one already there \
                 drops one of the two, and silently dropping an obligation is exactly \
                 what linearity prevents. A `Mut List<T>` holds obligations (its \
                 terminal is `drain`); a set of *identifiers* with the obligations in a \
                 `Mut Map<K, T>` beside it is the other shape"
                    .to_string(),
            ),
            ("Map", 0) | ("SortedMap", 0) => Some(
                "a map's **keys** are compared and retained, and storing under a key \
                 that is already there drops one of the two. Keys are data; the \
                 *values* are where obligations go — `Mut Map<K, V>` opts its values \
                 in, and `remove`/`replace`/`drain` are how they leave"
                    .to_string(),
            ),
            _ => None,
        }
    }

    /// The immediate components of a written composite type, refused when
    /// one of them is linear [linear-composite]. Called from
    /// `validate_type`, which visits every written type once, and checks
    /// only one level: a nested composite reports at its own node, so
    /// `List<List<Lines>>` is one error, at the inner list.
    fn check_linear_components(&mut self, ty: &ast::Type) {
        let mut found: Vec<(Span, String, String)> = Vec::new();
        // [linear-container] LC-3's positions, which explain themselves.
        let mut reasoned: Vec<(Span, String, String)> = Vec::new();
        match ty {
            ast::Type::Literal { .. } => {}
            ast::Type::Named { base, .. } => {
                let opted = self.linear_opt_in_positions(&self.written_key_of(base));
                for (i, a) in base.args.iter().enumerate() {
                    if let Some(linear) = self.ast_type_own_linear(a) {
                        // [linear-container] A parameter that declares
                        // `canbe linear` accepts a linear argument: the
                        // container is then *conditionally linear* and the
                        // obligation is checked on the container itself
                        // (user decision 2026-09-12, extended to opaque
                        // containers like `List` 2026-09-16).
                        if opted.contains(&i) {
                            continue;
                        }
                        match self.linear_position_reason(&self.written_key_of(base), i) {
                            // [linear-container] LC-3's two semantic refusals
                            // say why in their own words.
                            Some(reason) => reasoned.push((a.span(), linear, reason)),
                            None => found.push((
                                a.span(),
                                linear,
                                format!("a type argument of `{}`", base.name.name),
                            )),
                        }
                    }
                }
            }
            ast::Type::Array { elem, .. } => {
                if let Some(linear) = self.ast_type_own_linear(elem) {
                    found.push((elem.span(), linear, "an array's element type".to_string()));
                }
            }
            ast::Type::Tuple { elems, .. } => {
                for e in elems {
                    if let Some(linear) = self.ast_type_own_linear(e) {
                        found.push((e.span(), linear, "a tuple component".to_string()));
                    }
                }
            }
            // [linear-union-arm] A union arm may be linear (O-C2, user
            // decision 2026-09-12): a union value is one handle, so the
            // obligation is the union's and narrowing settles it —
            // `Ok InputStream | Err Str` is exactly the fallible-open
            // shape phase 4 needs, and `T?` follows. The value-level
            // rules are the IR's ledger (`ir::check`); nothing to refuse here.
            ast::Type::Union { .. } | ast::Type::Nullable { .. } => {}
            ast::Type::QualifiedGroup { .. } | ast::Type::Fn { .. } => {}
            ast::Type::Spread { .. } => {}
        }
        for (span, linear, position) in found {
            self.refuse_linear_composite(span, &linear, position);
        }
        for (span, linear, reason) in reasoned {
            self.error(span, messages::linear_composite_position(&linear, &reason));
        }
    }

    // ================= fn-type effects [fn-effects] =================

    /// Lowers a fn type's effect list [fn-effects]. `use` is not meaningful
    /// there: registering a handler is a *local* act, so a lambda may do it
    /// exactly when the function containing it may.
    fn lower_fn_effects(&mut self, effects: Option<&[EffectRef]>) -> Vec<Ty> {
        let mut out: Vec<Ty> = Vec::new();
        for eff in effects.into_iter().flatten() {
            match eff {
                EffectRef::Use(span) => self.error(*span, messages::fn_effects_use()),
                // [actor-spawn-effect] Same reasoning: the capability is a
                // property of the body that spawns, not of a value's type.
                EffectRef::Spawn(span) => self.error(
                    *span,
                    messages::actor_spawn_effect_fn_type(),
                ),
                // [effect-any] A fn type's requirement is inherited by the
                // function that takes the value, and a type carries no
                // strength: the function that calls the value states
                // `[any E]` itself if any instance will do.
                EffectRef::AnyEffect(r) => {
                    self.error(r.span, messages::effect_any_fn_type(&r.name.name));
                    if let Some(ty) = self.lower_effect_ref(r) {
                        if !out.contains(&ty) {
                            out.push(ty);
                        }
                    }
                }
                EffectRef::Effect(_) => {}
            }
        }
        // [effect-alias] [effect-prereq] A fn type's list means what a fn's
        // does: aliases flattened, prerequisites added.
        let plain: Vec<EffectRef> = effects
            .into_iter()
            .flatten()
            .filter(|e| matches!(e, EffectRef::Effect(_)))
            .cloned()
            .collect();
        for e in self.expand_effect_refs(&plain, true) {
            if !out.contains(&e.ty) {
                out.push(e.ty);
            }
        }
        out
    }

    /// The effects a parameter's type contributes to the enclosing fn
    /// [fn-effects]: those declared on a fn type, reached through
    /// qualifiers (`once () [Console] -> None`) and optional wrappers
    /// (`((s: Str) [Logger] -> Str)?`).
    fn inherited_fn_effects(&mut self, ty: &ast::Type) -> Vec<Ty> {
        match ty {
            ast::Type::Fn { effects, .. } => self.lower_fn_effects(effects.as_deref()),
            // [fn-effects] An effect claim in qualifier position is
            // inherited from for the same reason a fn type's list is: it
            // says driving the value performs the effect. The spelling is
            // *refused* at declarations now (a pass performs its effects in
            // its `next`), but the refused type still lowers — one mistake,
            // one diagnostic — so the claim is read off the qualified type
            // here, and the *base* is still walked, since a qualified group
            // can wrap a fn type (`once (() [Console] -> None)`).
            ast::Type::QualifiedGroup { base, .. } => {
                let mut out = self.claimed_effects(ty);
                for ty in self.inherited_fn_effects(base) {
                    if !out.contains(&ty) {
                        out.push(ty);
                    }
                }
                out
            }
            ast::Type::Named { .. } => self.claimed_effects(ty),
            ast::Type::Nullable { inner, .. } => self.inherited_fn_effects(inner),
            ast::Type::Union { arms, .. } => arms
                .iter()
                .flat_map(|a| self.inherited_fn_effects(a))
                .collect(),
            _ => Vec::new(),
        }
    }

    /// [fn-effects] The effects a type *claims*: the names in qualifier
    /// position that resolve to effect declarations, lowered to instances.
    /// Reaches through nullability and union arms like [fn-effects]'s
    /// inheritance does, so `Logger MyPass?` claims `Logger`. The spelling
    /// is refused at declarations (a pass performs its effects in its
    /// `next`), so this feeds the refusal diagnostic and the leniency path.
    fn claimed_effects(&mut self, ty: &ast::Type) -> Vec<Ty> {
        let mut out: Vec<Ty> = Vec::new();
        match ty {
            ast::Type::Named { qualifiers, .. } | ast::Type::QualifiedGroup { qualifiers, .. } => {
                for q in qualifiers {
                    let m = self.named(q);
                    if m.is_qualifier() {
                        continue;
                    }
                    if m.effect.is_some() {
                        if let Some(ty) = self.lower_effect_ref(q) {
                            if !out.contains(&ty) {
                                out.push(ty);
                            }
                        }
                    }
                }
            }
            ast::Type::Nullable { inner, .. } => out.extend(self.claimed_effects(inner)),
            ast::Type::Union { arms, .. } => {
                for arm in arms {
                    for ty in self.claimed_effects(arm) {
                        if !out.contains(&ty) {
                            out.push(ty);
                        }
                    }
                }
            }
            _ => {}
        }
        out
    }

    /// Why a *written* qualifier name may not be removed with `^`, if it may
    /// not [qual-lift]. Consults the effect namespace first: an effect claim
    /// on a producer never drops [fn-effects], and the name-based list
    /// cannot know an arbitrary effect's name.
    fn removal_block(&self, name: &str) -> Option<&'static str> {
        if !self.scope.qualifiers.contains_key(name) && self.scope.effects.contains_key(name) {
            return Qual::effect(name, Vec::new()).drop_block();
        }
        crate::types::qual_drop_block(name)
    }

    /// Records that an effect instance was used, for the *inference* of an
    /// enclosing un-annotated lambda's effect set [fn-effects].
    fn note_effect_use(&mut self, ty: &Ty) {
        if let Some(frame) = self.effect_uses.last_mut() {
            if !frame.contains(ty) {
                frame.push(ty.clone());
            }
        }
    }

    /// The effects a fn value's *call* requires, checked against what is
    /// available here [fn-effects]. Records the instances to thread, keyed
    /// by the call span, exactly as a named call's dependencies are.
    fn check_fn_value_effects(&mut self, effects: &[Ty], span: Span) {
        self.check_effects_available(effects, span, true);
    }

    fn check_effects_available(&mut self, effects: &[Ty], span: Span, record: bool) {
        if effects.is_empty() {
            return;
        }
        let mut resolved: Vec<Ty> = Vec::new();
        // [effect-use-no-dup] Innermost first, shadowed duplicates hidden.
        let visible = self.visible_effects();
        for want in effects {
            // [throw] [fn-effects] A function value that may throw needs a
            // delimiter, not a handler, exactly as a named callee that may
            // does: the call is an exit `record_throw` accounts for, and a
            // `try` around it receives the throw (2026-10-20; before, it
            // looked for a `Throw` handler, so a `try` around `f(n)` saw
            // nothing that could throw).
            if record {
                if let Ty::Named { name: eff, args } = want {
                    if eff == THROW_EFFECT && !visible.iter().any(|c| c == want) {
                        let message = args.first().cloned().unwrap_or(Ty::Unknown);
                        self.record_throw(span, message, false);
                        continue;
                    }
                }
            }
            let found = visible.iter().find(|c| *c == want).cloned();
            let found = found.or_else(|| {
                let compatible: Vec<&Ty> = visible
                    .iter()
                    .filter(|c| unify(want, c, &mut HashMap::new()))
                    .collect();
                match compatible.len() {
                    1 => Some(compatible[0].clone()),
                    _ => None,
                }
            });
            match found {
                Some(instance) => {
                    self.note_effect_use(&instance);
                    resolved.push(instance);
                }
                None => {
                    self.error(span, messages::effect_available_fn_value(&want));
                    resolved.push(want.clone());
                }
            }
        }
        if record {
            self.out.call_effects.insert(self.key(span), resolved);
        }
    }

    // ================= throw and `try` [throw] [throw-try] =================

    /// The enclosing fn's declared throw message type, if it declared
    /// `[Throw<M>]`.
    fn declared_throw_message(&self) -> Option<Ty> {
        self.effect_env.iter().find_map(|e| match &e.ty {
            Ty::Named { name, args } if name == THROW_EFFECT => {
                Some(args.first().cloned().unwrap_or(Ty::Unknown))
            }
            _ => None,
        })
    }

    /// Records a site that may throw [throw] and reports the cases where
    /// nothing can receive it. Every such site is also an *exit*: the code
    /// between it and its delimiter does not run, so no linear obligation
    /// may be live [linear-obligation].
    fn record_throw(&mut self, span: Span, message: Ty, performs: bool) {
        match self.try_stack.last_mut() {
            // Inside a `try`: the delimiter collects the message type; the
            // wrap into its `M` is filled in once the body is checked.
            Some(ctx) => {
                let _ = ctx.entry_depth;
                ctx.sites.push((span, message.clone()));
                self.out.may_throw.insert(
                    self.key(span),
                    ThrowSite {
                        performs,
                        message,
                        // Filled in by `check_try` (the innermost `try` is
                        // the one being checked) [throw-try-innermost].
                        delimiter: None,
                        target: Ty::Unknown,
                        arm: None,
                    },
                );
                // [ir-analyze] The throw-path linear leak check moved to the IR.
            }
            // Outside every `try`: the enclosing fn must declare it.
            None => {
                let Some(target) = self.declared_throw_message() else {
                    self.error(span, messages::throw_no_receiver(&THROW_EFFECT, &message));
                    return;
                };
                let arm = self.throw_message_arm(span, &message, &target);
                self.out.may_throw.insert(
                    self.key(span),
                    ThrowSite {
                        performs,
                        message,
                        delimiter: None,
                        target,
                        arm,
                    },
                );
                // [ir-analyze] The throw-path linear leak check moved to the IR.
            }
        }
    }

    /// The arm of the target message type a site's message wraps into
    /// [type-union-arm-identity], reporting a message the target cannot carry.
    fn throw_message_arm(&mut self, span: Span, message: &Ty, target: &Ty) -> Option<usize> {
        if target.is_unknown() || message.is_unknown() {
            return None;
        }
        if target.is_wrapper_union() {
            let arms = target.value_arms();
            match arms.iter().position(|arm| **arm == *message) {
                Some(i) => {
                    return Some(i);
                }
                None => {
                    if !is_subtype(message, target) {
                        self.error(span, messages::throw_try_message_mismatch(&message, &target));
                    }
                    return None;
                }
            }
        }
        if !is_subtype(message, target) {
            self.error(span, messages::throw_try_message_mismatch(&message, &target));
        }
        None
    }

    /// `throw(message)` [throw]. Not an ordinary effect-member call: there
    /// is no handler to resolve — the delimiter is `try` — and the result
    /// is the bottom type, so the code after it never runs.
    fn check_throw_call(&mut self, member: &'p FnDecl, args: &[&'p Expr], typed: Option<&[Ty]>, span: Span) -> Ty {
        let message = match args.first() {
            Some(a) => {
                // Typed already when the call was selected among overloads.
                let ty = match typed.and_then(|t| t.first()) {
                    Some(t) => t.clone(),
                    None => self.check_expr(a, None),
                };
                // The message is moved into the outcome, like the value
                // passed to `err` [deduce-consume].
                self.fate_move(a, "throw with", span);
                ty
            }
            None => {
                self.error(span, messages::throw_argument_count(&member.name.name));
                Ty::Unknown
            }
        };
        if typed.is_none() {
            for extra in args.iter().skip(1) {
                self.check_expr(extra, None);
            }
        }
        self.record_throw(span, message, true);
        Ty::Never
    }

    /// `try { ... }` [throw-try]: the delimiter. The body's value becomes the
    /// `Ok T` arm and the throws it performs the `Thrown M` arm, with `M`
    /// the union of their message types (user decision 2026-09-04) — which
    /// is why the outcome is an ordinary union: `is`, `when` and
    /// exhaustiveness need no new rules.
    /// Whether the code being checked is inside a lambda body: a function
    /// value's body runs wherever it is *called*, which is why the
    /// asynchronous forms stop at that boundary [fate-lambda].
    fn in_lambda(&self) -> bool {
        !self.lambda_ctx.is_empty()
    }

    /// [actor-self-send] `self.k(args)` — send a message to **the actor this
    /// member belongs to**: the one thing a member cannot say with an
    /// unqualified call, since that would be self-dispatch (a handler has no
    /// way to reach its own instance) rather than a message.
    ///
    /// Its point is *ordering*, not reach: an unqualified call would run `k`
    /// now, inside this activation; a self-send runs it as its own later one,
    /// which is how "finish this, then continue with `k`" is written. Defined
    /// for both bindings, like every other form: an enqueue on the actor's
    /// own mailbox when the handler is spawned, and the ordinary inline member
    /// call when it is `use`d — which is what a local binding of a `send`
    /// protocol already does.
    fn check_self_send(&mut self, member: &'p Ident, args: &'p [Expr], span: Span) -> Ty {
        let Some(h) = self.own_handler else {
            for a in args {
                self.check_expr(a, None);
            }
            let detail = if self.in_lambda() {
                " — and a lambda is not one: a function value runs wherever it is \
                 called, so `@self` names nothing there"
            } else {
                ""
            };
            self.error(span, messages::actor_self_send_outside_member(&member.name, &detail));
            return Ty::Unknown;
        };
        let targets: Vec<&'p FnDecl> = h.fns.iter().filter(|f| f.name.name == member.name).collect();
        let Some(first) = targets.first().copied() else {
            for a in args {
                self.check_expr(a, None);
            }
            self.error_unresolved(
                member.span,
                messages::actor_self_send_no_member(&h.name.name, &member.name),
                &member.name,
            );
            return Ty::Unknown;
        };
        // A self-send is a *message*, so its target is a send member: an
        // ordinary member would have to answer, and a member cannot wait for
        // itself.
        if !first.is_send {
            self.error(span, messages::actor_self_send_not_send(&member.name));
        }
        // [fn-overload] The target and its arguments by the call's rule
        // (PIPELINE.md B3.7, D24 (a)).
        let arg_refs: Vec<&'p Expr> = args.iter().collect();
        if self.own_send_target(h, &member.name, &targets, &arg_refs, &[], span).is_none() {
            return Ty::none();
        }
        self.record_def_ref(member.span, &member.name);
        // [actor-mixed-handler] Inside a mixed handler's **sync** member the
        // explicit spelling means what the bare call means — a send to the
        // servant through the façade value's addr — so it shares that
        // table and lowering (user decision 2026-09-19: `@self` is the
        // disambiguator, in both member kinds).
        if self.facade_handler.is_some() {
            self.out
                .facade_sends
                .insert(self.key(span), member.name.clone());
        } else {
            self.out
                .self_sends
                .insert(self.key(span), member.name.clone());
        }
        // [actor-send-fn] A send answers nothing.
        Ty::none()
    }

    /// The type of a place, without checking it: `None` for anything that is
    /// not one, or whose type is not yet known. Errors are never reported
    /// from here — the caller either uses the answer or falls through to the
    /// path that does report.
    fn peek_place_ty(&mut self, expr: &Expr) -> Option<Ty> {
        match expr {
            Expr::Ident(id) => {
                let var = self.lookup(&id.name)?;
                let ty = if var.narrowed.is_unknown() {
                    var.declared.clone()
                } else {
                    var.narrowed.clone()
                };
                Some(ty)
            }
            Expr::Field { base, field, .. } => {
                let base_ty = self.peek_place_ty(base)?;
                self.field_ty(&base_ty, &field.name)
            }
            Expr::TupleIndex { base, index, .. } => match self.peek_place_ty(base)?.strip_quals() {
                Ty::Tuple(elems) => elems.get(*index).cloned(),
                _ => None,
            },
            // [col-index-resolve] Only arrays are subscriptable, so this is the
            // whole of element access as a place.
            Expr::Index { base, .. } => match self.peek_place_ty(base)?.strip_quals() {
                Ty::Array(elem) => Some((**elem).clone()),
                _ => None,
            },
            _ => None,
        }
    }

    /// [actor-use-addr] `addr.member(args)` — a send to an actor, and the
    /// inline form of `use addr` plus an unqualified call. The receiver names
    /// *where* the message goes rather than an argument, so the member's
    /// parameters line up with the written arguments exactly as they do at a
    /// handler.
    #[allow(clippy::too_many_arguments)]
    fn check_addr_call(
        &mut self,
        instance: &Ty,
        receiver: &'p Expr,
        receiver_checked: bool,
        member: &'p Ident,
        type_args: &'p [ast::Type],
        args: &'p [Expr],
        named: &'p [ast::NamedArg],
        expected: Option<&Ty>,
        span: Span,
    ) -> Ty {
        let _ = type_args;
        // The receiver is *read* — it names the target rather than being an
        // argument, but a read is what it is: without checking it here nothing
        // would record the use, and the variable would be reported unused
        // [var-unused]. Checked exactly once, which is why deciding that this
        // *is* an addr call peeks the type instead of checking it (or the
        // caller already checked it: `?.`, a receiver that is not a place).
        if !receiver_checked {
            self.check_expr(receiver, None);
        }
        let effect_name = match instance.strip_quals() {
            Ty::Named { name, .. } => name.clone(),
            _ => return Ty::Unknown,
        };
        let Some(effect) = self.symbols.effects.get(effect_name.as_str()).copied() else {
            for a in args {
                self.check_expr(a, None);
            }
            self.error(span, messages::actor_use_addr_not_in_scope(&effect_name));
            return Ty::Unknown;
        };
        let members = crate::effect_members_named(effect, &member.name);
        if members.is_empty() {
            for a in args {
                self.check_expr(a, None);
            }
            self.error_unresolved(
                member.span,
                messages::actor_use_addr_no_member(&instance, &effect_name, &member.name),
                &member.name,
            );
            return Ty::Unknown;
        }
        self.record_def_ref(member.span, &member.name);
        // [effect-member-overload] [fn-overload] The overload and its
        // arguments by the call's rule (PIPELINE.md B3.7, D24 (a)): typed
        // once, the lead's parameter types flowing in, ranked like any
        // overloads; the instance the addr names binds the effect's generics.
        let cands: Vec<CallCand<'p>> = members
            .iter()
            .map(|d| CallCand::Member { effect, decl: d, instance: Some(instance.strip_quals().clone()) })
            .collect();
        let arg_refs: Vec<&'p Expr> = args.iter().collect();
        let Some((best, arg_tys)) = self.select_among(&member.name, &cands, &[], &arg_refs, named, expected, None, None, span) else {
            return Ty::none();
        };
        let target = best.decl;
        if members.len() > 1 {
            // [effect-member-overload] Which overload a call resolved to, for
            // the emitters: they name an overloaded member positionally.
            if let Some(idx) = crate::effect_member_index(effect, target) {
                self.out.effect_member_calls.insert(self.key(span), idx);
            }
        }
        // [actor-send-fn] Only a send member can be reached through an addr in
        // the first pass: an ordinary member answers, and answering across a
        // actor boundary is the call sugar that comes later.
        if !target.is_send {
            self.error(span, messages::actor_use_addr_not_send(&member.name));
        }
        // [linear-defer] Forwarding a received reply to another actor
        // extends its dependency chain past this activation.
        self.send_payload(target, &best, &arg_refs, &arg_tys, named, "forwarding it to another actor", span);
        self.out.addr_calls.insert(self.key(span), instance.clone());
        // [actor-deadlock-cycle] A send from inside a member body is an edge
        // in the wait-for graph: it blocks while the target's bounded mailbox
        // is full. Recorded with the handler doing the sending, so the graph
        // pass can key it on the protocol that handler serves.
        if let (Some(h), Ty::Named { name, .. }) = (self.own_handler, instance.strip_quals()) {
            self.out
                .actor_sends
                .push((h.name.name.clone(), name.clone(), self.key(span)));
        } else if let (Some(task), Ty::Named { name, .. }) =
            (self.own_task.clone(), instance.strip_quals())
        {
            // [task-mint] A send from a *task* body: the graph attributes it to
            // every actor whose mints reach this task (FC-6's conservative
            // tracing), so it is recorded against the `send fn` here.
            self.out
                .task_sends
                .push((task, name.clone(), self.key(span)));
        }
        // [actor-send-fn] A send answers nothing.
        Ty::none()
    }

    /// [actor-spawn-expr] `spawn H(args) with D(...), addr on POOL` — the
    /// asynchronous binding of a handler. Almost every rule here is a rule
    /// `use` already has, moved to the spawn site: the same handler
    /// construction, the same dependency resolution, the same
    /// argument-is-stored consumption. What differs is *where* the
    /// dependencies come from — the spawn's own `use` clause, because a
    /// handler never crosses into an actor (only construction does) — and
    /// that the result is a value: the child's `Addr<E>`.
    ///
    /// [actor-mailbox] The mailbox bound is **not** a clause here: it is the
    /// handler's own slot (user decision 2026-09-16), so a spawn says what to
    /// run, what it depends on and where — and the queue depth is stated once,
    /// by the author who knows the protocol.
    ///
    /// [actor-spawn-expr] The `on` clause is **required** (user decision
    /// 2026-10-18): a `spawn` always names the pool it runs on, since `use`
    /// now covers the this-scope binding. The old optional-`on` main-pool
    /// default is retired. [waitfor-dedicated] A `Dedicated Pool` placement is
    /// **consumed** here — one thread, one occupant, enforced by the move.
    /// [actor-group] The `in GROUP` clause of a spawn: `group` must be an
    /// `eff[ActorGroup<E>]` for one of the faces the spawn answers, and that
    /// face's addr is what joins. A place, not a placement: the actor still
    /// runs on its pool, and the clause adds the one `join` send.
    fn check_spawn_join(&mut self, group: &'p Expr, spawned: &Ty) {
        let gty = self.check_expr(group, None);
        if gty.is_unknown() || spawned.is_unknown() {
            return;
        }
        let of = match addr_effect(&gty) {
            Some(Ty::Named { name, args }) if name == "ActorGroup" && args.len() == 1 => args[0].clone(),
            _ => {
                self.error(group.span(), messages::actor_group_not_a_group(&gty));
                return;
            }
        };
        let faces: Vec<Ty> = match spawned {
            Ty::Tuple(elems) => elems.iter().filter_map(addr_effect).collect(),
            other => addr_effect(other).into_iter().collect(),
        };
        match faces.iter().position(|f| *f == of) {
            Some(_) => {}
            None => {
                let names: Vec<String> = faces.iter().map(|f| f.to_string()).collect();
                self.error(
                    group.span(),
                    messages::actor_group_no_face(
                        &of,
                        &(if names.is_empty() { "no actor effect".to_string() } else { format!("`{}`", names.join("`, `")) }),
                    ),
                );
            }
        }
    }

    fn check_spawn(
        &mut self,
        handler: &'p Expr,
        uses: &'p [Expr],
        pool: Option<&'p Expr>,
        span: Span,
    ) -> Ty {
        if let Some(pool) = pool {
            let pool_ty = self.check_expr(pool, Some(&Ty::named(POOL_TYPE)));
            if !pool_ty.is_unknown() && !is_subtype(pool_ty.strip_quals(), &Ty::named(POOL_TYPE)) {
                self.error(
                    pool.span(),
                    messages::actor_spawn_expr_pool_type(&POOL_TYPE, &pool_ty),
                );
            }
            // [waitfor-dedicated] A dedicated thread has exactly one
            // occupant, and the `on` clause is what spends it: the placement
            // is consumed, so a second spawn onto the same `thread()` is the
            // ordinary use-after-move diagnostic rather than a rule of its
            // own. Placement one may *want* — no grant requires it since
            // SH-5(d) deleted the capability (user decision 2026-09-19).
            if pool_ty.quals().iter().any(|q| q.name == DEDICATED_QUALIFIER) {
                self.fate_move(pool, "spawn on", pool.span());
            }
        }
        // [actor-spawn-effect] The capability gate. Reported once, at the
        // spawn, and the rest of the form is still checked so a program with
        // a missing capability gets its other errors too.
        if !self.can_spawn {
            let msg = if self.in_lambda() {
                messages::actor_spawn_effect_in_lambda()
            } else {
                messages::actor_spawn_effect_missing()
            };
            self.error(span, msg);
        }
        let Some((id, args, written_type_args, named)) = self.handler_construction(handler, "spawn")
        else {
            return Ty::Unknown;
        };
        let Some((effects, declared)) =
            self.check_handler_construction(id, args, written_type_args, named, "spawn", span)
        else {
            for u in uses {
                self.check_spawn_dep(u);
            }
            return Ty::Unknown;
        };
        // [effect-handler-deps] The child's dependencies, supplied here
        // rather than inherited: each clause item is a handler construction
        // (built on the child) or an `Addr` (an effect another actor serves).
        // [actor-effect-kind] [actor-monitor-handler] The spawn form serves two
        // kinds, split by the faces' kind. Every face an actor effect: the
        // actor spawn — a mailbox, a scheduler index, an addr per face. Every
        // face a *plain* effect: the **monitor spawn** (SH-3, user decision
        // 2026-09-19) — one shared instance behind a lock, reached through the
        // same `Addr<E>` type, its members running on the callers' threads.
        // A mixture is refused face-by-face by the actor path's kind check.
        let plain_faces = !effects.is_empty()
            && effects.iter().all(|effect| {
                matches!(effect.strip_quals(), Ty::Named { name, .. }
                    if self.symbols.effects.get(name.as_str()).is_some_and(|d| !d.is_actor))
            });
        if plain_faces {
            // [actor-mixed-handler] Send members split the plain-face spawn in two:
            // with them the handler is mixed (a servant + a façade), without
            // them it is a monitor (a lock).
            let mixed = self
                .scope
                .handlers
                .get(id.name.as_str())
                .is_some_and(|h| h.fns.iter().any(|f| f.is_send));
            if mixed {
                self.check_mixed_spawn(id, &effects, span);
            } else {
                self.check_monitor_spawn(id, &effects, pool, span);
                // [actor-monitor-handler] A shared handler's dependencies come from
                // the **enclosing scope**, captured as handles at
                // construction — resolved exactly as a `use` resolves them,
                // never from a spawn clause (that clause builds *on the
                // child*, and a monitor has no child thread to build on).
                for u in uses {
                    self.error(u.span(), messages::actor_monitor_handler_with_clause(&id.name));
                    self.check_expr(u, None);
                }
                if !declared.is_empty() {
                    self.resolve_monitor_deps(id, &declared, span);
                }
                self.out
                    .spawn_effects
                    .insert(self.key(span), effects.clone());
                let mut addrs: Vec<Ty> = effects
                    .into_iter()
                    .map(|effect| Ty::Named {
                        name: ADDR_TYPE.to_string(),
                        args: vec![effect],
                    })
                    .collect();
                return if addrs.len() == 1 {
                    addrs.pop().unwrap_or(Ty::Unknown)
                } else {
                    Ty::Tuple(addrs)
                };
            }
        } else {
            for effect in &effects {
                self.require_actor_effect(effect, span, "spawn");
            }
            // [actor-spawn-expr] An actor spawn names the pool it runs on
            // (user decision 2026-10-18): `use H()` now covers the this-scope
            // binding, so `spawn` is reserved for "on a thread" and the `on`
            // clause is required. The old implicit main-pool default is
            // retired with it. (A monitor spawn runs on no thread, so this
            // does not apply to it.)
            if pool.is_none() {
                self.error(span, messages::actor_spawn_expr_no_pool(&id.name));
            }
        }
        // The clause item's own index travels with the effect it supplies:
        // the matching below drains this list, so the position in it is not
        // the position the program wrote.
        let mut supplied: Vec<(Ty, Span, usize)> = Vec::new();
        for (at, u) in uses.iter().enumerate() {
            // [actor-deadlock-cycle] A clause construction is built *on the
            // child*: its members run inline in the child's activations, so
            // "may wait" propagates child-ward — recorded for the graph's
            // fixpoint, keyed on the child handler's name.
            let constructed = match u {
                Expr::Ident(cid) if self.scope.handlers.contains_key(cid.name.as_str()) => {
                    Some(cid.name.clone())
                }
                Expr::Call { callee, .. } => match callee.as_ref() {
                    Expr::Ident(cid)
                        if self.scope.handlers.contains_key(cid.name.as_str()) =>
                    {
                        Some(cid.name.clone())
                    }
                    _ => None,
                },
                _ => None,
            };
            if let Some(constructed) = constructed {
                self.out.handler_constructs.push((
                    id.name.clone(),
                    constructed,
                    self.key(u.span()),
                ));
            }
            if let Some(eff) = self.check_spawn_dep(u) {
                supplied.push((eff, u.span(), at));
            }
        }
        let mut resolved: Vec<Ty> = Vec::new();
        let mut items: Vec<Option<usize>> = Vec::new();
        let visible = self.visible_avail();
        for want in &declared {
            let want = &want.ty;
            let found = supplied
                .iter()
                .position(|(eff, _, _)| eff == want)
                .or_else(|| {
                    supplied
                        .iter()
                        .position(|(eff, _, _)| unify(want, eff, &mut HashMap::new()))
                });
            match found {
                Some(i) => {
                    let (eff, _, at) = supplied.remove(i);
                    resolved.push(eff);
                    items.push(Some(at));
                }
                // [actor-spawn-inherit] **Synthesis** (user decision 2026-09-20):
                // a declared dependency the clause does not cover is
                // resolved from the *spawning scope* — the modular feature
                // `[E]`-means-shareable bought, since an availability the
                // signature guarantees is shareable can be captured as a
                // handle and cross the seam. An ambiguity between two
                // compatible instances is an error rather than a guess.
                None => match self.synthesized_spawn_dep(want, &visible, id, span) {
                    Some(ty) => {
                        resolved.push(ty);
                        items.push(None);
                    }
                    None => {}
                },
            }
        }
        // Anything left over was supplied for nothing — a mistake worth
        // naming, since the reader believes it is being used.
        for (eff, sp, _) in &supplied {
            self.error(*sp, messages::actor_spawn_inherit_not_a_dep(&id.name, &eff));
        }
        if !resolved.is_empty() {
            self.out.spawn_deps.insert(self.key(span), resolved);
            self.out.spawn_dep_items.insert(self.key(span), items);
        }        self.out.spawn_effects.insert(self.key(span), effects.clone());
        // [effect-handler-multi] One addr per implemented effect: a single face
        // answers the bare `Addr<E>` it always did, and several answer a tuple
        // in declaration order — which is how least authority falls out of the
        // types, since a holder of one face cannot name the other's members.
        let mut addrs: Vec<Ty> = effects
            .into_iter()
            .map(|effect| Ty::Named {
                name: ADDR_TYPE.to_string(),
                args: vec![effect],
            })
            .collect();
        if addrs.len() == 1 {
            addrs.pop().unwrap_or(Ty::Unknown)
        } else {
            Ty::Tuple(addrs)
        }
    }

    /// [actor-monitor-handler] Resolve a shareable spawn's
    /// dependencies from the enclosing scope — `finish_use`'s rules, at the
    /// spawn: each must be a shareable, lexically bound availability, since
    /// it is captured into the instance as an owned handle. Recorded in
    /// `use_deps` under the spawn's span for the emitters.
    fn resolve_monitor_deps(&mut self, id: &Ident, declared: &[EffectAvail], span: Span) {
        let mut resolved_deps: Vec<Ty> = Vec::new();
        let visible = self.visible_avail();
        for want in declared {
            let want = want.ty.clone();
            let found = visible
                .iter()
                .find(|c| c.ty == want)
                .cloned()
                .or_else(|| {
                    let compatible: Vec<&EffectAvail> = visible
                        .iter()
                        .filter(|c| unify(&want, &c.ty, &mut HashMap::new()))
                        .collect();
                    match compatible.len() {
                        1 => Some(compatible[0].clone()),
                        _ => None,
                    }
                });
            match found {
                Some(avail) => resolved_deps.push(avail.ty),
                None => self.error(
                    span,
                    messages::actor_monitor_handler_missing_dep(&id.name, &want),
                ),
            }
        }
        if !resolved_deps.is_empty() {
            self.out.use_deps.insert(self.key(span), resolved_deps);
        }
    }

    /// [actor-monitor-handler] The monitor spawn (SH-3, user decision 2026-09-19):
    /// `spawn H(args)` where every face of `H` is a **plain** effect answers a
    /// shared instance behind a lock — reached through the same `Addr<E>`
    /// type, bound with `use addr` like any handle, its members running on
    /// the callers' threads under mutual exclusion.
    ///
    /// The restriction *was* "no dependency list"; since 2026-09-20 (user
    /// decision) a monitor may declare **shareable** dependencies, captured
    /// as owned handles at construction. The availability rule keeps the
    /// lock discipline: a dependency was bound before its dependent, so
    /// lock acquisition follows construction order (no cycles) and no
    /// synchronous path routes back into its own lock (no reentrancy — and
    /// the JVM-reentrant/Rust-non-reentrant divergence stays unwritable).
    /// What stays closed is the door reentrancy would need: no `use`, no
    /// `spawn` capability — a shareable handler's
    /// bindings are fixed at construction. Waits reachable through its deps
    /// are **priced, not refused**: the deadlock graph gives dep-bearing
    /// shareable handlers nodes of their own [actor-deadlock-cycle].
    fn check_monitor_spawn(
        &mut self,
        id: &Ident,
        effects: &[Ty],
        pool: Option<&'p Expr>,
        span: Span,
    ) {
        let Some(decl) = self.scope.handlers.get(id.name.as_str()).copied() else {
            return;
        };
        // One face only, for now: one instance behind several effect types
        // needs a representation neither backend has yet (Rust would want one
        // `Arc<Mutex<dyn E1 + E2>>`, and trait objects have one principal
        // trait). Refused rather than guessed [backend-never-wrong].
        if effects.len() > 1 {
            let faces: Vec<String> = effects.iter().map(|e| e.to_string()).collect();
            self.error(
                span,
                messages::actor_monitor_handler_several_faces(&id.name, &faces.join(", ")),
            );
        }
        // A monitor runs on its callers' threads: there is nothing to place.
        if let Some(pool) = pool {
            self.error(pool.span(), messages::actor_monitor_handler_on_pool(&id.name));
        }
        // [actor-monitor-handler] [effect-handle] A monitor may declare deps —
        // captured as handles at construction, resolved from the enclosing
        // scope exactly as a `use` resolves them (the availability rule makes
        // the capture acyclic: a dep was bound before this spawn, so no lock
        // order can cycle and no path routes back).
        // A `send fn` member routes the spawn to the mixed path before this
        // check, so reaching one here is an internal inconsistency.
        if let Some(f) = decl.fns.iter().find(|f| f.is_send) {
            self.error(span, messages::actor_monitor_handler_send_member(&id.name, &f.name.name));
        }
        // [actor-sendable] The instance crosses to every thread that binds
        // the handle, so what it holds must be sendable: constructor
        // parameters and state fields alike.
        for p in &decl.params {
            let ty = self.lower_type(&p.ty);
            if let Some(why) = self.unshareable_reason(&ty) {
                self.error(
                    span,
                    messages::actor_monitor_handler_unsendable_param(
                        &id.name,
                        &p.name.name,
                        &ty,
                        &why,
                    ),
                );
            }
        }
        for field in &decl.state {
            let ty = match &field.ty {
                Some(t) => self.lower_type(t),
                None => self
                    .out
                    .expr_ty
                    .get(&self.key(field.name.span))
                    .cloned()
                    .unwrap_or(Ty::Unknown),
            };
            if let Some(why) = self.unshareable_reason(&ty) {
                self.error(
                    span,
                    messages::actor_monitor_handler_unsendable_field(
                        &id.name,
                        &field.name.name,
                        &ty,
                        &why,
                    ),
                );
            }
        }
    }

    /// [actor-mixed-handler] Whether a handler is **mixed** (SH-1, user decision
    /// 2026-09-19): every face a plain effect, and at least one `send fn`
    /// member. The send members and the state form the servant (an ordinary
    /// actor over a handler-local protocol); the sync members form the
    /// façade, running on the caller's thread.
    fn handler_is_mixed(&self, h: &ast::HandlerDecl) -> bool {
        if !h.fns.iter().any(|f| f.is_send) {
            return false;
        }
        // [name-table] The faces as the handler's file means them: a `use`
        // in another module asks too.
        !h.of.is_empty()
            && h.of.iter().all(|of| {
                let base = match of {
                    ast::Type::Named { base, .. } => base,
                    ast::Type::QualifiedGroup { base, .. } => match base.as_ref() {
                        ast::Type::Named { base, .. } => base,
                        _ => return false,
                    },
                    _ => return false,
                };
                self.named(base).effect.is_some_and(|e| !e.is_actor)
            })
    }

    /// [actor-mixed-handler] [actor-free-send-fn] A handler-local `send fn` carries the
    /// free send fn's obligations, because no effect declaration mirrors it:
    /// an explicit all-consumed deduction clause (a scheduled body outlives
    /// the frame that enqueued it, so what it is given is always consumed),
    /// no `Mut` parameter, no generics, and every parameter sendable
    /// [actor-sendable]. And one restriction of its own: no overloading —
    /// the servant's message dispatch is by member name.
    fn check_local_send_member(&mut self, h: &'p ast::HandlerDecl, f: &'p FnDecl) {
        // [copy-scalar-free] A Copy scalar is never consumed, so the clause
        // has nothing to say about one.
        let has_params = f.params.iter().any(|p| !p.implicit && !salvo_syntax::is_copy_scalar_type(&p.ty));
        if f.deductions.is_none() && has_params {
            self.error(
                f.name.span,
                messages::actor_mixed_handler_send_clause(
                    &f.name.name,
                    &f.params
                        .iter()
                        .filter(|p| !p.implicit && !salvo_syntax::is_copy_scalar_type(&p.ty))
                        .map(|p| format!("!{}", p.name.name))
                        .collect::<Vec<_>>()
                        .join(", "),
                ),
            );
        }
        for d in f.deductions.iter().flatten() {
            // [linear-defer] A deferral consumes too.
            if matches!(
                d.kind,
                ast::DeductionKind::Moved | ast::DeductionKind::Deferred
            ) {
                continue;
            }
            let Some(name) = d.param_name() else { continue };
            // [copy-scalar-free] Keeping a Copy scalar is moving it: a copy.
            if f.params.iter().any(|p| p.name.name == name.name && salvo_syntax::is_copy_scalar_type(&p.ty)) {
                continue;
            }
            self.error(d.span, messages::actor_mixed_handler_kept_param(&f.name.name, &name.name));
        }
        if let Some(g) = f.generics.first() {
            self.error(
                f.name.span,
                messages::actor_mixed_handler_generic_send(&f.name.name, &g.name),
            );
        }
        let inner = self.enter_generics(&f.generics);
        for p in &f.params {
            if p.implicit {
                continue;
            }
            if let ast::Type::Named { qualifiers, .. } = &p.ty {
                if let Some(q) = qualifiers.iter().find(|q| q.name.name == "Mut") {
                    self.error(
                        q.span,
                        messages::actor_mixed_handler_mut_param(&f.name.name, &p.name.name),
                    );
                }
            }
            let ty = self.lower_type(&p.ty);
            if let Some(why) = self.unsendable_reason(&ty) {
                self.error(
                    p.ty.span(),
                    messages::actor_mixed_handler_unsendable_param(&f.name.name, &ty, &why),
                );
            }
        }
        self.generics = inner;
        if h.fns
            .iter()
            .filter(|other| other.is_send && other.name.name == f.name.name)
            .count()
            > 1
        {
            self.error(f.name.span, messages::actor_mixed_handler_overloaded_send(&f.name.name));
        }
    }

    /// [actor-mixed-handler] A bare call inside a mixed handler's member that
    /// names one of the handler's own `send fn` members: a **send to the
    /// servant** (user decision 2026-09-19 — from a sync member since SH-1,
    /// from a send member too since the same-day extension, where it is a
    /// self-enqueue [actor-self-send]). Typed like an addr send — every
    /// argument consumed (the payload crosses), answering nothing — and
    /// recorded for the emitters: façade sends lower to an enqueue on the
    /// façade value's addr, servant sends to one on the handler's own.
    /// Answers `None` when the callee is not a local send member, so
    /// ordinary resolution proceeds.
    ///
    /// **Ambiguity is refused, not resolved** (the same decision): a name
    /// that is *also* a member of an effect available in this body — one of
    /// the handler's dependencies, which a send member sees — must say
    /// which it means: `k@self(…)` for the servant, `k@Effect(…)` for the
    /// effect [effect-at].
    fn check_servant_send(&mut self, id: &'p Ident, args: &[&'p Expr], span: Span) -> Option<Ty> {
        // Façade context (sync member) or servant context (send member)?
        let (h, servant) = match (self.facade_handler, self.servant_reply_params.is_some()) {
            (Some(h), _) => (h, false),
            (None, true) => (self.own_handler?, true),
            _ => return None,
        };
        let targets: Vec<&'p FnDecl> = h.fns.iter().filter(|f| f.is_send && f.name.name == id.name).collect();
        if targets.is_empty() {
            return None;
        }
        let claimed: Vec<String> = self
            .effect_members_here(id.name.as_str())
            .map(|ms| {
                ms.iter()
                    .filter(|(e, _)| {
                        self.effect_env.iter().any(
                            |t| matches!(&t.ty, Ty::Named { name, .. } if *name == self.symbols.key_or(*e, &e.name.name)),
                        )
                    })
                    .map(|(e, _)| format!("`{}`", e.name.name))
                    .collect()
            })
            .unwrap_or_default();
        if !claimed.is_empty() {
            for a in args {
                self.check_expr(a, None);
            }
            self.error(
                span,
                messages::actor_mixed_handler_send_or_member(&id.name, &claimed.join(", ")),
            );
            return Some(Ty::Unknown);
        }
        self.record_def_ref(id.span, &id.name);
        // [fn-overload] The target and the arguments by the call's rule
        // (PIPELINE.md B3.7, user decision 2026-10-28: D24 (a)).
        if self.own_send_target(h, &id.name, &targets, args, &[], span).is_none() {
            return Some(Ty::none());
        }
        if servant {
            // [actor-self-send] A servant's bare sibling call *is* a
            // self-send, so it shares the spelling's table and lowering.
            self.out.self_sends.insert(self.key(span), id.name.clone());
        } else {
            self.out.facade_sends.insert(self.key(span), id.name.clone());
        }
        Some(Ty::none())
    }

    /// [actor-self-send] [actor-mixed-handler] A send to one of the
    /// enclosing handler's own members, chosen among `targets` (its members
    /// of the name) by the call's rule [fn-overload-rank], and its payload
    /// taken ([`Self::send_payload`]). The lowering names the member, so an
    /// overloaded one is refused here until it can say which (ROADMAP 0au).
    /// `None` once refused.
    fn own_send_target(
        &mut self,
        h: &'p ast::HandlerDecl,
        name: &str,
        targets: &[&'p FnDecl],
        args: &[&'p Expr],
        named: &'p [ast::NamedArg],
        span: Span,
    ) -> Option<&'p FnDecl> {
        if targets.len() > 1 {
            for a in args {
                self.check_expr(a, None);
            }
            self.error(span, messages::actor_send_fn_overloaded_own(&name, &h.name.name));
            return None;
        }
        let cands: Vec<CallCand<'p>> = targets.iter().map(|d| CallCand::Own { handler: h, decl: d }).collect();
        let (best, arg_tys) = self.select_among(name, &cands, &[], args, named, None, None, None, span)?;
        let target = best.decl;
        self.send_payload(target, &best, args, &arg_tys, named, "sending it onward", span);
        Some(target)
    }

    /// [actor-send-fn] The payload of a send whose target the call's
    /// selection chose: each argument coerced to its parameter, checked for an
    /// escaping reply [linear-defer], and moved — it crosses the seam, so the
    /// sender gives it up [deduce-consume]. A message carries its arguments as
    /// written, so a send that leaves a defaulted parameter out, names one, or
    /// reaches implicit or variadic parameters is refused until the lowering
    /// can fill them (PIPELINE.md B3.7; ROADMAP 0au).
    #[allow(clippy::too_many_arguments)]
    fn send_payload(
        &mut self,
        target: &'p FnDecl,
        best: &Viable<'p>,
        args: &[&'p Expr],
        arg_tys: &[Ty],
        named: &[ast::NamedArg],
        how: &str,
        span: Span,
    ) {
        let positional = target.params.iter().filter(|p| !p.implicit && !p.variadic).count();
        let shape = if target.params.iter().any(|p| p.implicit) {
            Some("implicit parameters")
        } else if target.params.iter().any(|p| p.variadic) {
            Some("a variadic parameter")
        } else if !named.is_empty() {
            Some("named arguments")
        } else if args.len() < positional {
            Some("a parameter left to its default")
        } else {
            None
        };
        if let Some(what) = shape {
            self.error(span, messages::actor_send_fn_message_shape(&target.name.name, &what));
        }
        for (i, pt) in best.pairings.clone() {
            let (Some(a), Some(logical)) = (args.get(i), arg_tys.get(i)) else { continue };
            let repr = self.repr_of(a, logical);
            self.maybe_coerce(a.span(), logical, &repr, &pt);
        }
        for a in args {
            self.reply_escape(a, how);
            self.fate_move(a, "send", a.span());
        }
    }

    /// [linear-defer] [actor-mixed-handler] The escape check at the rung-4
    /// contract point: inside a mixed send member, a `Reply` parameter that
    /// leaves this activation any way but the discharge — passed to a
    /// function, forwarded to an actor, stored, captured — must be declared
    /// `defer`, which is the handler's rung-4 opt-in. An upper bound the
    /// other way: a declared `defer` that the body never exercises is legal
    /// (SH-10(b), user decision 2026-09-19).
    fn reply_escape(&mut self, arg: &Expr, how: &str) {
        let Some(list) = &self.servant_reply_params else {
            return;
        };
        let Expr::Ident(id) = arg else { return };
        let Some((name, deferred)) = list
            .iter()
            .find(|(n, _)| *n == id.name)
            .cloned()
        else {
            return;
        };
        if deferred {
            return;
        }
        self.error(id.span, messages::actor_mixed_handler_undeclared_defer(&name, &how));
    }

    /// [actor-mixed-handler] The mixed spawn: `spawn H(args)`, every face plain,
    /// send members present. It answers the same `Addr<E>` a monitor spawn
    /// answers — the façade value: the servant's addr plus the constructor
    /// parameters plus dispatch to the sync bodies. The servant is an
    /// ordinary actor, so the `on` clause stays (optional, inheriting the
    /// current pool), unlike a monitor's.
    fn check_mixed_spawn(&mut self, id: &Ident, effects: &[Ty], span: Span) {
        let Some(decl) = self.scope.handlers.get(id.name.as_str()).copied() else {
            return;
        };
        if effects.len() > 1 {
            let faces: Vec<String> = effects.iter().map(|e| e.to_string()).collect();
            self.error(
                span,
                messages::actor_mixed_handler_several_faces(&id.name, &faces.join(", ")),
            );
        }
        // [actor-sendable] The façade value copies the constructor
        // parameters to every thread that binds the handle.
        for p in &decl.params {
            // A `Mut` parameter would be *shared* between the servant and
            // every façade copy on Kotlin and *cloned apart* on Rust — an
            // observable divergence, so it is refused rather than emitted
            // [backend-never-wrong].
            if let ast::Type::Named { qualifiers, .. } = &p.ty {
                if qualifiers.iter().any(|q| q.name.name == "Mut") {
                    self.error(
                        span,
                        messages::actor_mixed_handler_mut_ctor_param(&id.name, &p.name.name),
                    );
                }
            }
            let ty = self.lower_type(&p.ty);
            if let Some(why) = self.unsendable_reason(&ty) {
                self.error(
                    span,
                    messages::actor_mixed_handler_unsendable_ctor_param(
                        &id.name,
                        &p.name.name,
                        &ty,
                        &why,
                    ),
                );
            }
        }
    }

    /// [actor-spawn-expr] One item of a spawn's `with` clause: a handler
    /// construction, whose effect is what it implements, or a value of type
    /// `Addr<E>`, whose effect is `E`. Answers the effect it supplies.
    fn check_spawn_dep(&mut self, item: &'p Expr) -> Option<Ty> {
        // A name that a handler declares is a construction; anything else is
        // an expression, and an `Addr` is the only useful kind.
        let is_handler = match item {
            Expr::Ident(id) => self.scope.handlers.contains_key(id.name.as_str()),
            Expr::Call { callee, .. } => match callee.as_ref() {
                Expr::Ident(id) => self.scope.handlers.contains_key(id.name.as_str()),
                _ => false,
            },
            _ => false,
        };
        if is_handler {
            let (id, args, type_args, named) = self.handler_construction(item, "spawn")?;
            // A dependency constructed for the child: its dependencies are
            // the child's problem in turn, and a handler with any of its own
            // cannot be written in a spawn clause — there is no scope on the
            // child to resolve them from. Named where it is written.
            let (effects, deps) =
                self.check_handler_construction(id, args, type_args, named, "spawn", item.span())?;
            let effect = effects.first().cloned().unwrap_or(Ty::Unknown);
            // [effect-handler-multi] A multi-face handler *constructed* in a
            // spawn clause would have to supply two of the child's
            // dependencies from one instance, and the child owns what a clause
            // builds — so there is nothing to share it with. Two addrs of the
            // same actor are the shape that works, and they are two clause
            // items.
            if effects.len() > 1 {
                let faces: Vec<String> = effects.iter().map(|e| e.to_string()).collect();
                self.error(
                    item.span(),
                    messages::actor_spawn_expr_with_several_faces(&id.name, &faces.join(", ")),
                );
            }
            for dep in &deps {
                let dep = &dep.ty;
                self.error(
                    item.span(),
                    messages::actor_spawn_expr_with_dependencies(&id.name, &dep, &effect),
                );
            }
            return Some(effect);
        }
        let ty = self.check_expr(item, None);
        match addr_effect(&ty) {
            Some(effect) => Some(effect),
            None if ty.is_unknown() => None,
            None => {
                self.error(item.span(), messages::actor_spawn_expr_with_not_a_handler(&ty));
                None
            }
        }
    }

    /// [task-mint] [fn-overload] Which free `send fn` a mint `replyto
    /// k(captures)` targets, by the call's rule over what a mint knows
    /// (PIPELINE.md B3.7, user decision 2026-10-28: D18 (a)): every visible
    /// `send fn` of the name competes, whatever rung brought it into scope
    /// (renames respected, `k@module` narrowing it); a candidate fits when it
    /// takes the captures and one more parameter, the token, and — where the
    /// position says what the token carries — that parameter takes it; the
    /// most specific wins, and a tie is the ordinary ambiguity, naming
    /// `replyto k@module(…)`. Answers the target and, when several competed,
    /// the captures as typed; `Err(())` once refused, `Ok(None)` for none.
    fn free_send_target(
        &mut self,
        member: &Ident,
        module: Option<&'p [Ident]>,
        captures: &'p [Expr],
        expected: Option<&Ty>,
        form: &str,
    ) -> Result<Option<(crate::resolve::FnEntry<'p>, Option<Vec<Ty>>)>, ()> {
        let mut entries: Vec<crate::resolve::FnEntry<'p>> =
            self.overloads_of(&member.name).into_iter().filter(|e| e.decl.is_send).collect();
        let mut seen: HashSet<DeclId> = HashSet::new();
        entries.retain(|e| seen.insert(e.key));
        if let Some(path) = module {
            let wanted = path.iter().map(|i| i.name.as_str()).collect::<Vec<_>>().join(".");
            let named: Vec<crate::resolve::FnEntry<'p>> = entries
                .iter()
                .copied()
                .filter(|e| ModulePath::text_matches_suffix(&e.module.to_string(), &wanted))
                .collect();
            if named.is_empty() {
                if !entries.is_empty() {
                    for c in captures {
                        self.check_expr(c, None);
                    }
                    self.error(member.span, messages::fn_overload_at_no_fn_in_module(&member.name, &wanted));
                    return Err(());
                }
                return Ok(None);
            }
            entries = named;
        }
        let shaped: Vec<crate::resolve::FnEntry<'p>> = entries
            .iter()
            .copied()
            .filter(|e| e.decl.params.iter().filter(|p| !p.implicit).count() == captures.len() + 1)
            .collect();
        match (entries.len(), shaped.as_slice()) {
            (0, _) => return Ok(None),
            (1, _) => return Ok(Some((entries[0], None))),
            (_, [one]) => return Ok(Some((*one, None))),
            // None takes this many captures: the first reports the count.
            (_, []) => return Ok(Some((entries[0], None))),
            _ => {}
        }
        // Several take this many: the captures are typed once, and each
        // candidate fitted by them and by the token the position wants.
        let tys: Vec<Ty> = captures.iter().map(|c| self.check_expr(c, None)).collect();
        let token: Option<Ty> = match expected.map(|t| t.strip_quals()) {
            Some(Ty::Named { name, args }) if name == REPLY_TYPE && args.len() == 1 && !args[0].is_unknown() => {
                Some(args[0].clone())
            }
            _ => None,
        };
        let mut fits: Vec<(crate::resolve::FnEntry<'p>, crate::types::RankedCandidate)> = Vec::new();
        for e in &shaped {
            let saved = self.enter_generics(&e.decl.generics);
            let patterns: Vec<Ty> = e.decl.params.iter().filter(|p| !p.implicit).map(|p| self.lower_type(&p.ty)).collect();
            self.generics = saved;
            let generics: HashSet<String> = e.decl.generics.iter().map(|g| g.name.clone()).collect();
            let mut subst: HashMap<String, Ty> = HashMap::new();
            let unified = patterns.iter().zip(&tys).all(|(p, a)| unify(p, a, &mut subst));
            let takes = unified
                && patterns.iter().zip(&tys).all(|(p, a)| self.arg_fits_param(a, &substitute_vars(p, &subst, &generics), false))
                && token.as_ref().is_none_or(|t| {
                    let last = patterns.last().cloned().unwrap_or(Ty::Unknown);
                    unify(&last, t, &mut subst) && is_subtype(t, &substitute_vars(&last, &subst, &generics))
                });
            if takes {
                fits.push((*e, crate::types::RankedCandidate { patterns, variadic: false }));
            }
        }
        let shown_caps = || tys.iter().map(|t| t.to_string()).collect::<Vec<_>>().join(", ");
        if fits.is_empty() {
            self.error(member.span, messages::call_resolve_no_overload(&member.name, &shown_caps(), &""));
            return Err(());
        }
        let ranks: Vec<crate::types::RankedCandidate> = fits.iter().map(|(_, r)| r.clone()).collect();
        match crate::types::most_specific(&ranks) {
            Some(i) if fits.iter().filter(|(_, r)| r.patterns == fits[i].1.patterns).count() == 1 => {
                Ok(Some((fits[i].0, Some(tys))))
            }
            _ if tys.iter().any(ty_mentions_unknown) => Ok(Some((fits[0].0, Some(tys)))),
            _ => {
                let mut modules: Vec<String> = fits.iter().map(|(e, _)| e.module.to_string()).collect();
                modules.sort();
                modules.dedup();
                let forms: Vec<String> = modules.iter().map(|m| format!("`replyto {}@{m}(…)`", member.name)).collect();
                self.error(
                    member.span,
                    messages::task_mint_ambiguous_send(&form, &member.name, &shown_caps(), &forms.join(" or ")),
                );
                Err(())
            }
        }
    }

    /// [task-mint] A free `fn` visible under `member`'s name that is *not* a
    /// `send fn` — the shape that makes `free_send_target` return `None` for
    /// a reason worth naming. Resolution mirrors `free_send_target`'s own
    /// scope ladder, so the rung reported is the one that would have won had
    /// the function been declared `send`.
    fn free_plain_fn(&self, member: &Ident) -> Option<&'p FnDecl> {
        let entries = self.scope.fns.get(member.name.as_str())?;
        let best = entries.iter().map(|e| e.rung).max()?;
        entries
            .iter()
            .filter(|e| e.rung == best && !e.decl.is_send)
            .map(|e| e.decl)
            .next()
    }

    /// [task-mint] [task-pool-inherit] `replyto k(captures) on POOL` where `k`
    /// is a free `send fn`: the mint that makes a plain function a citizen of
    /// the concurrent world (user decision 2026-09-17, FC-2 + FC-3).
    ///
    /// What differs from a member mint, and why each difference is a
    /// simplification rather than a special case: there is **no mailbox**, so
    /// no capacity is reserved and no deadlock edge is contributed
    /// [actor-deadlock-cycle]; there is **no enclosing handler**, so the mint
    /// is legal in any function; and there **is** a placement, because the
    /// continuation has to run somewhere — the pool current at the mint unless
    /// an `on` clause says otherwise, since whoever creates work pays for it.
    /// [task-effects] The effects a task mint inherits, resolved against the
    /// minting scope exactly as a `spawn`'s synthesized dependencies are
    /// [actor-spawn-inherit]: an availability yields an owned handle that can cross
    /// the seam, and an ambiguity between two compatible instances is refused
    /// rather than guessed.
    ///
    /// Recorded in `task_mint_effects` in the target's declared order; the
    /// emitters clone the scope's handles into the closure.
    fn resolve_task_effects(&mut self, target: &'p FnDecl, span: Span) {
        let declared: Vec<Ty> = self
            .expand_effect_refs_quiet(target.effects.as_deref().unwrap_or(&[]), true)
            .into_iter()
            .filter(|e| !e.any)
            .map(|e| e.ty)
            .collect();
        if declared.is_empty() {
            return;
        }
        let visible = self.visible_avail();
        let mut resolved: Vec<Ty> = Vec::new();
        for want in &declared {
            let exact = visible.iter().find(|c| c.ty == *want).cloned();
            let found = match exact {
                Some(a) => Some(a),
                None => {
                    let compatible: Vec<&EffectAvail> = visible
                        .iter()
                        .filter(|c| unify(want, &c.ty, &mut HashMap::new()))
                        .collect();
                    match compatible.len() {
                        1 => Some(compatible[0].clone()),
                        0 => None,
                        _ => {
                            self.error(
                                span,
                                messages::task_effects_ambiguous(
                                    &target.name.name,
                                    &want,
                                    &compatible
                                        .iter()
                                        .map(|c| c.ty.to_string())
                                        .collect::<Vec<_>>()
                                        .join(", "),
                                ),
                            );
                            continue;
                        }
                    }
                }
            };
            let Some(avail) = found else {
                self.error(span, messages::task_effects_missing(&target.name.name, &want));
                continue;
            };
            resolved.push(avail.ty.clone());
        }
        if resolved.len() == declared.len() {
            self.out.task_mint_effects.insert(self.key(span), resolved);
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn check_task_mint(
        &mut self,
        member: &Ident,
        entry: crate::resolve::FnEntry<'p>,
        typed: Option<Vec<Ty>>,
        captures: &'p [Expr],
        gated: bool,
        pool: Option<&'p Expr>,
        span: Span,
    ) -> Ty {
        // A gate is a mailbox policy, and a task has no mailbox: there is
        // nothing to hold back while the answer is outstanding.
        if gated {
            self.error(span, messages::task_mint_gated_free_send(&member.name));
        }
        // A placement is optional and may be dedicated: `thread()` answers a
        // `Dedicated Pool`, which the clause consumes [waitfor-dedicated] —
        // placement one may *want*, no longer a grant anything requires
        // (SH-5(d), user decision 2026-09-19).
        if let Some(p) = pool {
            let pool_ty = self.check_expr(p, Some(&Ty::named(POOL_TYPE)));
            if !pool_ty.is_unknown() && !is_subtype(pool_ty.strip_quals(), &Ty::named(POOL_TYPE)) {
                self.error(p.span(), messages::actor_replyto_pool_type(&POOL_TYPE, &pool_ty));
            }
            if pool_ty.quals().iter().any(|q| q.name == DEDICATED_QUALIFIER) {
                self.fate_move(p, "run on", p.span());
            }
        }
        let target = entry.decl;
        let params: Vec<&Param> = target.params.iter().filter(|p| !p.implicit).collect();
        if params.len() != captures.len() + 1 {
            if typed.is_none() {
                for c in captures {
                    self.check_expr(c, None);
                }
            }
            self.error(
                span,
                messages::actor_replyto_capture_count(
                    &member.name,
                    &params.len(),
                    &params.len().saturating_sub(1),
                    &captures.len(),
                ),
            );
            return Ty::Unknown;
        }
        let saved = self.enter_generics(&target.generics);
        let param_tys: Vec<Ty> = params.iter().map(|p| self.lower_type(&p.ty)).collect();
        self.generics = saved;
        for (i, c) in captures.iter().enumerate() {
            let want = &param_tys[i];
            // [fn-overload-rank] A capture is stored, so it takes a consumed
            // position's fit, as a call's argument there would.
            let got = match typed.as_ref().and_then(|t| t.get(i)) {
                Some(t) => t.clone(),
                None => self.check_expr(c, Some(want)),
            };
            if !got.is_unknown() && !self.arg_fits_param(&got, want, false) {
                self.error(c.span(), messages::actor_replyto_capture_mismatch(&want, &got));
            }
            // [actor-sendable] A capture crosses to another thread at the
            // crossing site, exactly as a spawn argument does.
            if !got.is_unknown() {
                if let Some(why) = self.unsendable_reason(&got) {
                    self.error(
                        c.span(),
                        messages::actor_sendable_capture(&member.name, &got, &why),
                    );
                }
            }
            // Stored in the continuation, so a bare name moves
            // [deduce-consume].
            self.reply_escape(c, "capturing it in a continuation");
            self.fate_move(c, "capture", c.span());
        }
        // [task-mint] Who minted it, for FC-6's tracing: a handler, or another
        // task (a task minting a task chains the attribution).
        if let Some(minter) = self
            .own_handler
            .map(|h| h.name.name.clone())
            .or_else(|| self.own_task.clone())
        {
            self.out.task_mints.push((minter, member.name.clone(), self.key(span)));
        }
        let key = entry.key;
        self.out.replyto_tasks.insert(self.key(span), key);
        // [lsp-definition] The mint names a function, so it is a reference
        // to it like any call.
        self.out.fn_refs.insert(self.key(member.span), key);
        self.resolve_task_effects(target, span);
        let answer = param_tys.last().cloned().unwrap_or(Ty::Unknown);
        Ty::Named {
            name: REPLY_TYPE.to_string(),
            args: vec![answer],
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn check_replyto(
        &mut self,
        member: &'p Ident,
        module: Option<&'p [Ident]>,
        captures: &'p [Expr],
        gated: bool,
        pool: Option<&'p Expr>,
        expected: Option<&Ty>,
        span: Span,
    ) -> Ty {
        let form = if gated { "replyto!" } else { "replyto" };
        // [task-mint] A **free `send fn`** is a legal target, and the mint is
        // then legal in any function — the answer needs no mailbox, because
        // the continuation is a detached task rather than an activation (user
        // decision 2026-09-17, FC-2). Resolved *after* the enclosing handler's
        // members, which keeps the existing rule exactly as it was.
        let member_of_own = module.is_none()
            && self.own_handler.is_some_and(|h| h.fns.iter().any(|f| f.name.name == member.name));
        if !member_of_own {
            match self.free_send_target(member, module, captures, expected, form) {
                Ok(Some((entry, typed))) => {
                    return self.check_task_mint(member, entry, typed, captures, gated, pool, span);
                }
                Ok(None) => {}
                Err(()) => return Ty::Unknown,
            }
        }
        if let Some(p) = pool {
            self.check_expr(p, Some(&Ty::named(POOL_TYPE)));
            self.error(p.span(), messages::actor_replyto_own_member_on(&form));
        }
        let Some(h) = self.own_handler else {
            for c in captures {
                self.check_expr(c, None);
            }
            // [task-mint] `member` may be a free `fn` that simply isn't
            // `send` yet — a more specific diagnostic than "no handler to
            // mint into" when that's the actual fix.
            if self.free_plain_fn(member).is_some() {
                self.error(member.span, messages::task_mint_plain_fn_target(&member.name, &form));
                return Ty::Unknown;
            }
            let detail = if self.in_lambda() {
                " — and a lambda is not one: a function value runs wherever it is \
                 called, so it has no member for an answer to arrive at"
            } else {
                "; `main` gets its token from `waitfor` instead"
            };
            self.error(span, messages::actor_replyto_outside_member(&form, &detail));
            return Ty::Unknown;
        };
        let targets: Vec<&'p FnDecl> = h.fns.iter().filter(|f| f.name.name == member.name).collect();
        // [fn-overload] A member mint names its member, which cannot say which
        // overload yet (PIPELINE.md B3.7; ROADMAP 0au).
        if targets.len() > 1 {
            for c in captures {
                self.check_expr(c, None);
            }
            self.error(span, messages::actor_send_fn_overloaded_own(&member.name, &h.name.name));
            return Ty::Unknown;
        }
        let Some(target) = targets.first().copied() else {
            for c in captures {
                self.check_expr(c, None);
            }
            // [task-mint] Same specific diagnostic as above: `member` exists
            // as a free `fn`, just not a `send` one, so saying so beats
            // reporting it as a missing handler member.
            if self.free_plain_fn(member).is_some() {
                self.error(member.span, messages::task_mint_plain_fn_target(&member.name, &form));
                return Ty::Unknown;
            }
            // [actor-replyto] A **remote** mint — `k` is a member of an
            // `actor effect` in scope rather than of this handler — is the
            // generalized form (decided — ROADMAP.md's sugar pass) and a
            // later slice: it makes the mint itself send-like, since capacity
            // has to be reserved in the *target's* queue. Named here rather
            // than reported as an unresolved name, with the workaround that
            // needs nothing new: a token is an ordinary linear value, so the
            // handler that owns `k` mints it and hands it over.
            let remote = self
                .scope
                .effect_members
                .get(member.name.as_str())
                .map(|ms| {
                    ms.iter()
                        .filter(|(e, _)| e.is_actor)
                        .map(|(e, _)| format!("`{}`", e.name.name))
                        .collect::<Vec<_>>()
                })
                .filter(|names| !names.is_empty());
            if let Some(mut names) = remote {
                names.sort();
                names.dedup();
                self.error(
                    member.span,
                    messages::actor_replyto_other_actor_member(
                        &form,
                        &member.name,
                        &names.join(", "),
                    ),
                );
                return Ty::Unknown;
            }
            self.error_unresolved(
                member.span,
                messages::actor_replyto_unknown_member(&h.name.name, &member.name, &form),
                &member.name,
            );
            return Ty::Unknown;
        };
        // A continuation is delivered by *sending*, so its target must be a
        // send member: an ordinary member would have to answer, and there is
        // nothing to answer to.
        if !target.is_send {
            // One mistake, one diagnostic: the captures are moot until the
            // target is a send member.
            for c in captures {
                self.check_expr(c, None);
            }
            self.error(member.span, messages::actor_replyto_not_send(&member.name, &form));
            return Ty::Unknown;
        }
        let params: Vec<&Param> = target.params.iter().filter(|p| !p.implicit).collect();
        if params.is_empty() {
            for c in captures {
                self.check_expr(c, None);
            }
            self.error(span, messages::actor_replyto_no_answer_param(&member.name, &form));
            return Ty::Unknown;
        }
        if params.len() != captures.len() + 1 {
            for c in captures {
                self.check_expr(c, None);
            }
            self.error(
                span,
                messages::actor_replyto_member_capture_count(
                    &member.name,
                    &params.len(),
                    &params.len().saturating_sub(1),
                    &form,
                    &captures.len(),
                ),
            );
            return Ty::Unknown;
        }
        let saved = self.enter_generics(&h.generics);
        let param_tys: Vec<Ty> = params.iter().map(|p| self.lower_type(&p.ty)).collect();
        self.generics = saved;
        for (i, c) in captures.iter().enumerate() {
            let want = &param_tys[i];
            let got = self.check_expr(c, Some(want));
            // [fn-overload-rank] A stored capture takes a consumed position's fit.
            if !got.is_unknown() && !self.arg_fits_param(&got, want, false) {
                self.error(c.span(), messages::actor_replyto_capture_mismatch(&want, &got));
            }
            // A capture travels with the continuation, so it is stored, not
            // borrowed [deduce-consume] — the same rule a `use` argument has.
            self.reply_escape(c, "capturing it in a continuation");
            self.fate_move(c, "capture", c.span());
        }
        self.out
            .replyto_members
            .insert(self.key(span), member.name.clone());
        // [actor-replyto] This handler parks, so it may only be spawned: the
        // continuation needs a mailbox to arrive on and a dispatcher to run
        // it, and a synchronously bound instance has neither. Refused at the
        // `use` site (below), which is where the binding is chosen.
        let key = self.symbols.key_or(h, &h.name.name).to_string();
        self.parking_handlers.insert(key.clone());
        if self.record {
            self.parking_log.push(key);
        }
        // [actor-deadlock-cycle] The gate is the wait-for graph's tail: while
        // this continuation is outstanding the actor serves only its answer,
        // so whatever this handler can send to must be able to answer without
        // waiting on *it*. A bare `replyto` leaves the mailbox open and
        // contributes nothing.
        if gated {
            self.out
                .actor_gates
                .push((h.name.name.clone(), self.key(span)));
        }
        let answer = param_tys
            .last()
            .cloned()
            .unwrap_or(Ty::Unknown);
        Ty::Named {
            name: REPLY_TYPE.to_string(),
            args: vec![answer],
        }
    }

    /// [waitfor-effect] `waitfor out: Reply<T> { ... }` — the bridge into the
    /// asynchronous world, legal wherever the `waitfor` capability was
    /// declared (user decision 2026-09-17, T-5(c)): it was never `main` that
    /// was special, only the fact that `main` owns its thread, and that is
    /// now what the rule says [waitfor-dedicated].
    ///
    /// The token is an ordinary **linear** local, so "the block must consume
    /// it" needs no rule of its own: [linear-obligation] reports a leak at
    /// the block's end. The expression's value is the token's payload.
    /// [waitfor-infer] The token's type, read off the block when it was not
    /// written: the binder is passed to something, and that parameter says what
    /// answer is being waited for.
    ///
    /// Deliberately *not* overload resolution: the binder's type is what
    /// resolution would need as an input, so this reads the **declared**
    /// parameter type at the position the binder occupies, over every overload
    /// of that name. One distinct `Reply<T>` is the answer; several is the
    /// ambiguity the user's decision made an error, with the written form as its
    /// remedy; none means nothing in the block sends the token.
    fn infer_waitfor_ty(&mut self, binding: &'p Ident, body: &'p Block, span: Span) -> Ty {
        let mut sites: Vec<(&'p str, usize)> = Vec::new();
        collect_binder_arg_sites(body, &binding.name, &mut sites);
        let mut found: Vec<Ty> = Vec::new();
        for (name, idx) in sites {
            // Both surfaces a call can reach: ordinary functions, and **effect
            // members** — which is where a `Reply<T>` parameter actually lives,
            // since `total@Counter(out)` names an `actor effect`'s member
            // [actor-effect] rather than a free fn.
            let mut decls: Vec<&'p ast::FnDecl> = match self.scope.fns.get(name) {
                Some(entries) => entries.iter().map(|e| e.decl).collect(),
                None => Vec::new(),
            };
            for effect in self.scope.effects.values() {
                for m in &effect.fns {
                    if m.name.name == name {
                        decls.push(m);
                    }
                }
            }
            if decls.is_empty() {
                continue;
            }
            for decl in decls {
                // Two candidate positions, because a `receiver.member(args)`
                // call means different things in the two cases the syntax
                // cannot tell apart: dot-notation on a *value* makes the
                // receiver the first declared parameter [fn-uniform], while the
                // same shape on an **addr** is a send, whose member declares
                // only the message's own parameters [actor-effect]. Only a
                // `Reply<T>` position is accepted, so the wrong guess
                // contributes nothing — and two that both hit are the
                // ambiguity this reports anyway.
                for pos in [idx, idx.saturating_sub(1)] {
                    let Some(param) = decl.params.iter().filter(|p| !p.implicit).nth(pos) else {
                        continue;
                    };
                    let ty = self.lower_type(&param.ty);
                    let is_reply = matches!(
                        &ty,
                        Ty::Named { name, args } if name == REPLY_TYPE && args.len() == 1
                    );
                    if is_reply && !found.contains(&ty) {
                        found.push(ty);
                    }
                }
            }
        }
        match found.len() {
            1 => found.remove(0),
            0 => {
                self.error(
                    span,
                    messages::waitfor_infer_no_reply_param(&binding.name, &REPLY_TYPE),
                );
                Ty::Unknown
            }
            _ => {
                let shown: Vec<String> = found.iter().map(|t| t.to_string()).collect();
                self.error(
                    span,
                    messages::waitfor_infer_ambiguous(&binding.name, &shown.join(" or "), &shown[0]),
                );
                Ty::Unknown
            }
        }
    }

    fn check_waitfor(
        &mut self,
        binding: &'p Ident,
        ty: &'p Option<ast::Type>,
        body: &'p Block,
        span: Span,
    ) -> Ty {
        // [actor-waitfor] No capability: a wait occupying its frame until it
        // returns is what a call is (SH-5(d), user decision 2026-09-19), the
        // wait serves its pool while it waits [waitfor-pump], and the
        // deadlock net is the graph's inferred occupancy plus the runtime
        // report. One refusal stays, on its own reason: a lambda's call
        // sites are not statically known, so the graph could not place the
        // occupancy a wait inside one would create.
        if self.in_lambda() {
            self.error(span, messages::actor_waitfor_in_lambda());
        }
        // [actor-deadlock-cycle] The graph's input: this handler's members
        // wait, which the deleted `[waitfor]` declaration used to say.
        if let Some(h) = self.own_handler {
            self.out
                .waitfor_sites
                .push((h.name.name.clone(), self.key(span)));
        }
        let token = match ty {
            Some(written) => {
                self.validate_type(written);
                self.lower_type(written)
            }
            None => self.infer_waitfor_ty(binding, body, span),
        };
        let payload = match &token {
            Ty::Named { name, args } if name == REPLY_TYPE && args.len() == 1 => {
                args[0].clone()
            }
            other => {
                if !other.is_unknown() {
                    self.error(
                        ty.as_ref().map(|t| t.span()).unwrap_or(span),
                        messages::actor_waitfor_binding_type(&REPLY_TYPE, &other),
                    );
                }
                Ty::Unknown
            }
        };
        // The token lives in a scope of its own: a `waitfor` is an
        // expression, so nothing after it may still hold the token.
        self.locals.push(HashMap::new());
        self.declare(binding, token);
        let (value, _) = self.check_branch_block(body, Vec::new());
        let _ = value;
        // [ir-analyze] The linear-obligation leak check moved to the IR.
        self.locals.pop();
        payload
    }

    fn check_try(&mut self, body: &'p Block, span: Span) -> Ty {
        let (Some(ok_qual), Some(thrown_qual)) = (
            self.core_qualifier(span, OK_QUALIFIER),
            self.core_qualifier(span, THROWN_QUALIFIER),
        ) else {
            // The diagnostic is reported by `core_qualifier`; check the
            // body so its own errors still surface.
            let _ = self.check_branch_block(body, Vec::new());
            return Ty::Unknown;
        };
        self.try_stack.push(TryCtx {
            entry_depth: self.locals.len(),
            sites: Vec::new(),
        });
        let (value_ty, _) = self.check_branch_block(body, Vec::new());
        let ctx = self.try_stack.pop().expect("try ctx pushed above");
        if ctx.sites.is_empty() {
            self.error(span, messages::throw_try_nothing_throws(&THROW_EFFECT));
            return Ty::Unknown;
        }
        // [throw-try] `M` is the union of the message types performed in the
        // body, deduplicated in first-seen order; a single type stays bare.
        let mut messages: Vec<Ty> = Vec::new();
        for (_, ty) in &ctx.sites {
            if !messages.contains(ty) {
                messages.push(ty.clone());
            }
        }
        let message_ty = self.mk_union(messages);
        // Fill in each site's landing information now that `M` is known.
        for (site_span, site_message) in &ctx.sites {
            let arm = self.throw_message_arm(*site_span, site_message, &message_ty);
            if let Some(site) = self.out.may_throw.get_mut(&self.key(*site_span)) {
                site.delimiter = Some(span);
                site.target = message_ty.clone();
                site.arm = arm;
            }
        }
        // The body's value is the `Ok` arm; a body that always exits
        // (`return`, an unconditional throw) contributes `Ok None`.
        let value_ty = if matches!(value_ty, Ty::Never) {
            Ty::none()
        } else {
            value_ty
        };
        let ok_arm = value_ty.qualify(vec![ok_qual]);
        let thrown_arm = message_ty.qualify(vec![thrown_qual]);
        self.mk_union(vec![ok_arm, thrown_arm])
    }

    /// Resolves one of the two qualifier names the `try` intrinsic needs
    /// from the implicitly imported core [throw-try]: `Ok` for the value arm,
    /// `Thrown` for the message arm. Absent means std is broken or not on
    /// the source path, which is worth saying out loud rather than
    /// producing a nameless union.
    fn core_qualifier(&mut self, span: Span, name: &str) -> Option<Qual> {
        let decl = self.qualifier_named(name);
        match decl {
            // Written as `Ok Int` / `Thrown Str`, so the qualifier's own
            // type argument stays implicit — exactly as `lower_quals`
            // produces it, which is what makes the outcome type equal to a
            // hand-written `Ok T | Thrown M`.
            Some(_) => Some(Qual {
                effect: false,
                name: name.to_string(),
                args: Vec::new(),
            }),
            None => {
                self.error(span, messages::throw_try_core_qualifier_missing(&name));
                None
            }
        }
    }

    // ================= path analysis =================

    /// Whether a block always leaves the enclosing construct — every path
    /// hits a `return`, `break`, `continue`, or a **diverging expression**
    /// — so its state never reaches the code *after* a branching construct
    /// [deduce-consume].
    ///
    /// [throw] is why this is type-aware: `throw(m)` is an ordinary call
    /// whose type is `Never`, so a branch ending in one exits exactly as
    /// a `return` does. Only sound *after* the block has been checked (the
    /// types it reads are the ones just recorded), which is where both
    /// callers stand.
    fn block_exits(&self, block: &Block) -> bool {
        // [expr-escape] The three escapes are `Never`-typed *expressions*
        // (2026-09-21), so they arrive here as expression statements and the
        // syntactic special cases they used to need are gone: `diverges`
        // recognizes them by the type the checker recorded, exactly as it
        // already recognized a `throw(m)` call [type-any-never].
        block.stmts.iter().any(|stmt| match stmt {
            Stmt::Expr(e) => self.expr_exits(e),
            _ => false,
        })
    }

    fn expr_exits(&self, expr: &Expr) -> bool {
        if self.diverges(expr) {
            return true;
        }
        match expr {
            // [assert-fn] `unreachable!()` is typed `Never`, so a path reaching
            // it does not continue — the same as a `throw` or a `return`. An
            // `assert!` continues when it holds, which is the whole point.
            Expr::Unreachable { .. } => true,
            // [assert-fn] `todo!()` diverges like `unreachable!()`.
            Expr::Todo { .. } => true,
            Expr::Assert { .. } | Expr::WhyNot { .. } => false,
            // [op-elvis] Neither side escapes by itself: a diverging right side
            // is recognized by its recorded type, like any diverging call.
            Expr::Elvis { .. } | Expr::Placeholder { .. } => false,
            // [expr-pipe] A pipe's value is its right side; it does not escape
            // by itself.
            Expr::Pipe { .. } | Expr::SafePipe { .. } => false,
            // [op-safe-nav] A `?.` yields an optional; it exits nothing by itself.
            Expr::SafeNav { .. } => false,
            // [expr-escape] All three leave the enclosing block. `diverges`
            // above already answers for them off the recorded type; listed
            // here because this match is deliberately exhaustive, so a new
            // control-flow form has to be classified.
            Expr::Return { .. } | Expr::Break { .. } | Expr::Continue { .. } => true,
            Expr::If {
                branches,
                else_block,
                ..
            } => {
                else_block.as_ref().is_some_and(|b| self.block_exits(b))
                    && branches.iter().all(|(_, b)| self.block_exits(b))
            }
            Expr::When { branches, .. } => {
                !branches.is_empty() && branches.iter().all(|b| self.block_exits(&b.body))
            }
            // [when-condition] Exhaustive by construction: the `else` is
            // mandatory, so "every branch exits" is enough.
            Expr::WhenCond {
                branches,
                else_block,
                ..
            } => self.block_exits(else_block) && branches.iter().all(|(_, b)| self.block_exits(b)),
            // Nothing else exits its enclosing block by itself. Loops are
            // deliberately excluded (they may run zero times), a lambda
            // owns its own control flow, and a `try` body's exits are
            // caught by the delimiter. Listed rather than defaulted so a
            // new control-flow form has to be classified here
            // [fn-must-return].
            Expr::While { .. }
            | Expr::For { .. }
            | Expr::Lambda { .. }
            | Expr::Try { .. }
            // [actor-spawn-expr] [actor-replyto] [actor-waitfor] Each has a
            // value and none transfers control out of the enclosing block: a
            // `spawn` yields an `Addr`, a `replyto` a token, and a `waitfor`
            // yields what was sent to its token — whatever its block does.
            // [actor-self-send] `k@self` is a callee, so it is a leaf here.
            | Expr::SelfScoped { .. }
            | Expr::SelfAddr { .. }
            | Expr::Spawn { .. }
            | Expr::Use { .. }
            | Expr::Project { .. }
            | Expr::Merge { .. }
            | Expr::ReplyTo { .. }
            | Expr::WaitFor { .. }
            | Expr::Int { .. }
            | Expr::Float { .. }
            | Expr::Bool { .. }
            | Expr::Char { .. }
            | Expr::Str { .. }
            | Expr::Ident(_)
            | Expr::Field { .. }
            | Expr::TupleIndex { .. }
            | Expr::Call { .. }
            | Expr::Index { .. }
            | Expr::Tuple { .. }
            | Expr::StructLit { .. }
            | Expr::Unary { .. }
            | Expr::Binary { .. }
            | Expr::Is { .. }
            | Expr::Widen { .. }
            | Expr::IncDec { .. }
            | Expr::Spread { .. }
            | Expr::Scoped { .. }
            | Expr::EffectScoped { .. }
            | Expr::FieldDefault { .. } | Expr::Error { .. } => false,
        }
    }

    /// [fn-must-return] Whether a block always returns from the enclosing
    /// fn. Same shape as `block_exits` without the loop exits — a `break`
    /// leaves a loop, not the function — and with the same [throw]
    /// divergence rule: a path that throws never falls off the end.
    fn block_returns(&self, block: &Block) -> bool {
        block.stmts.iter().any(|stmt| match stmt {
            Stmt::Expr(e) => self.expr_returns(e),
            _ => false,
        })
    }

    fn expr_returns(&self, expr: &Expr) -> bool {
        // [expr-escape] A `break`/`continue` is `Never`-typed like a `return`
        // or a `throw`, but it leaves a **loop**, not the function, so it must
        // not satisfy [fn-must-return]. Checked here rather than left to
        // `diverges`, which knows only the type: before the escapes became
        // expressions this distinction was free, because only `Stmt::Return`
        // counted.
        if matches!(expr, Expr::Break { .. } | Expr::Continue { .. }) {
            return false;
        }
        if self.diverges(expr) {
            return true;
        }
        match expr {
            // [assert-fn] It leaves the function, but not by returning a value:
            // a `fn` whose only tail is `unreachable!()` has no missing return
            // [fn-must-return], which `expr_exits` above answers.
            Expr::Unreachable { .. } | Expr::Todo { .. } | Expr::Assert { .. } | Expr::WhyNot { .. } => false,
            Expr::Elvis { .. } | Expr::Placeholder { .. } => false,
            Expr::Pipe { .. } | Expr::SafePipe { .. } => false,
            Expr::SafeNav { .. } => false,
            // [expr-escape] Only `return` leaves the *function*; the guard
            // above has already answered `false` for the other two.
            Expr::Return { .. } => true,
            Expr::Break { .. } | Expr::Continue { .. } => false,
            Expr::If {
                branches,
                else_block,
                ..
            } => {
                else_block.as_ref().is_some_and(|b| self.block_returns(b))
                    && branches.iter().all(|(_, b)| self.block_returns(b))
            }
            Expr::When { branches, .. } => {
                !branches.is_empty() && branches.iter().all(|b| self.block_returns(&b.body))
            }
            // [when-condition] Mandatory `else`, so the chain covers every
            // path [fn-must-return].
            Expr::WhenCond {
                branches,
                else_block,
                ..
            } => {
                self.block_returns(else_block)
                    && branches.iter().all(|(_, b)| self.block_returns(b))
            }
            // Nothing else returns from the enclosing fn by itself — see
            // `expr_exits` for why each is listed rather than defaulted.
            Expr::While { .. }
            | Expr::For { .. }
            | Expr::Lambda { .. }
            | Expr::Try { .. }
            // [actor-spawn-expr] [actor-replyto] [actor-waitfor] Each has a
            // value and none transfers control out of the enclosing block: a
            // `spawn` yields an `Addr`, a `replyto` a token, and a `waitfor`
            // yields what was sent to its token — whatever its block does.
            // [actor-self-send] `k@self` is a callee, so it is a leaf here.
            | Expr::SelfScoped { .. }
            | Expr::SelfAddr { .. }
            | Expr::Spawn { .. }
            | Expr::Use { .. }
            | Expr::Project { .. }
            | Expr::Merge { .. }
            | Expr::ReplyTo { .. }
            | Expr::WaitFor { .. }
            | Expr::Int { .. }
            | Expr::Float { .. }
            | Expr::Bool { .. }
            | Expr::Char { .. }
            | Expr::Str { .. }
            | Expr::Ident(_)
            | Expr::Field { .. }
            | Expr::TupleIndex { .. }
            | Expr::Call { .. }
            | Expr::Index { .. }
            | Expr::Tuple { .. }
            | Expr::StructLit { .. }
            | Expr::Unary { .. }
            | Expr::Binary { .. }
            | Expr::Is { .. }
            | Expr::Widen { .. }
            | Expr::IncDec { .. }
            | Expr::Spread { .. }
            | Expr::Scoped { .. }
            | Expr::EffectScoped { .. }
            | Expr::FieldDefault { .. } | Expr::Error { .. } => false,
        }
    }

    /// Whether the checker typed this expression as `Never` — it
    /// diverges, so nothing after it runs [type-any-never].
    fn diverges(&self, expr: &Expr) -> bool {
        matches!(
            self.out.ty_of(self.file_idx, expr.span()),
            Some(Ty::Never)
        )
    }

    /// `ty_transitively_mut` over written (AST) types — struct fields
    /// are declared syntactically [fate-move-mode].
    fn ast_type_mut(&self, ty: &ast::Type, visited: &mut HashSet<String>) -> bool {
        match ty {
            ast::Type::Literal { .. } => false,
            ast::Type::Named { qualifiers, base } => {
                if qualifiers.iter().any(|q| q.name.name == "Mut") {
                    return true;
                }
                if base.args.iter().any(|a| self.ast_type_mut(a, visited)) {
                    return true;
                }
                let Some(decl) = self.named(base).structure else {
                    return false;
                };
                if !visited.insert(base.name.name.clone()) {
                    return false;
                }
                decl.fields
                    .iter()
                    .any(|f| f.ty.as_ref().is_some_and(|t| self.ast_type_mut(t, visited)))
            }
            ast::Type::QualifiedGroup {
                qualifiers, base, ..
            } => {
                qualifiers.iter().any(|q| q.name.name == "Mut") || self.ast_type_mut(base, visited)
            }
            ast::Type::Union { arms, .. } => arms.iter().any(|a| self.ast_type_mut(a, visited)),
            ast::Type::Tuple { elems, .. } => elems.iter().any(|e| self.ast_type_mut(e, visited)),
            ast::Type::Array { elem, .. } => self.ast_type_mut(elem, visited),
            ast::Type::Nullable { inner, .. } => self.ast_type_mut(inner, visited),
            ast::Type::Spread { inner, .. } => self.ast_type_mut(inner, visited),
            ast::Type::Fn { .. } => false,
        }
    }

    /// Handles a whole-variable mutation event on `name` (a `Mut` call
    /// argument, a projection assignment through it, or `++`): mutating a
    /// derived variable is an error [fate-derived-readonly]; mutating a
    /// root poisons its derived variables [fate-poison].
    fn fate_mutation(&mut self, name: &str, span: Span) {
        self.fate_mutation_at(name, span, Some(&[]));
    }

    /// [fate-field-disjoint] `fate_mutation`, told *which projection* of
    /// the variable the mutation hits: `[]` is the whole variable (every
    /// derived value falls), `[.tags]` only what overlaps `p.tags`, `None`
    /// the conservative unknown.
    fn fate_mutation_at(&mut self, name: &str, span: Span, event_path: Option<&[Step]>) {
        self.fate_mutation_kind(name, span, event_path, false);
    }

    /// [deduce-field] `fate_mutation_at`, told whether the event is a
    /// **contents** mutation (identity preserved) rather than a
    /// replacement: rung ⑤ v2 spares a *handle to the mutated thing
    /// itself* from a contents mutation — its storage is still there and
    /// both backends see the same object — while a derivation reaching
    /// through its contents, and any replacement, poison as ever.
    fn fate_mutation_kind(
        &mut self,
        name: &str,
        span: Span,
        event_path: Option<&[Step]>,
        contents_only: bool,
    ) {
        // [iter-fn] The origin of an open `for` may not be mutated:
        // its machine reads it across suspensions.
        if let Some((_, subject_span)) = self
            .driven_origins
            .iter()
            .find(|(origin, _)| origin == name)
            .cloned()
        {
            let _ = subject_span;
            self.error(span, messages::iter_fn_origin_mutated(&name));
        }

        // [deduce-syntax] Record the invalidation against the enclosing
        // fn's parameter: mutation can falsify qualifiers the caller has
        // and this signature never mentions, so such a parameter may not
        // keep "everything else". Recorded for written lists too — that
        // is what the written-list validation checks.
        self.record_param_mutation(name);
        // [deduce-field] …and *where*, for the written-entry validation.
        if self.lookup(name).is_some_and(|v| v.is_param) {
            self.own_mut_paths.push((
                name.to_string(),
                event_path.map(|p| p.to_vec()),
                contents_only,
            ));
        }
        let Some(var) = self.lookup(name) else { return };
        let (id, links) = (var.id, var.links.clone());
        if !links.is_empty() {
            // [proj-infer] A variable whose every link is *held* is an owned
            // object that merely projects its roots (a pass over a list):
            // its own fields are its own, and its `proj` fields cannot be
            // written through, so mutating it cannot reach a root. It may be
            // advanced. A wholesale projection or a plain alias cannot
            // [proj-readonly].
            if links.iter().all(|l| l.held) {
                self.record_mutation(
                    id,
                    name,
                    span,
                    event_path,
                    id,
                    None,
                    contents_only,
                );
                return;
            }
            // [ref-handle] A `ref` carrying `Mut` is a **mutable
            // element handle** (P-3's lift of [proj-readonly], user
            // decisions 2026-09-24; narrowed to `ref` specifically,
            // 2026-10-08 — a plain `proj` carrying `Mut` is no longer a
            // handle): mutating through it is legal, and it is a mutation
            // event on the handle's *roots* at the linked paths — sibling
            // derivations fall [fate-poison], the handle itself stays
            // usable (its storage did not move), and a parameter root is
            // recorded as mutated so its inferred contract takes the
            // exhaustive form [deduce-syntax]. The bind event is recorded
            // for the emitter (P-9: mode is inferred per binding).
            // An optional handle is one too: what mutates is its present
            // arm, handed to a `Mut T?` position [proj-opt-slot].
            let handle_ty = |t: &Ty| {
                let one = |t: &Ty| t.is_ref() && Self::carries_mut(t);
                one(t) || matches!(t, Ty::Union(arms) if arms.iter().any(one))
            };
            // (A write through a handle the IR flow pass sees poisoned is its
            // use there [flow-use-after-move]: the flow pass reports it, so
            // the walk records the write as it would any other — R8 piece 8;
            // until then a poisoned handle's write returned early here.)
            let handle_mut = self
                .lookup(name)
                .map(|v| v.narrowed.clone())
                .is_some_and(|t| handle_ty(&t));
            if handle_mut {
                for l in links.clone() {
                    self.record_param_mutation(&l.root_name);
                    // [fate-elem-distinct] The acting link's index identity rides
                    // along: siblings proven apart survive the event.
                    self.record_mutation(
                        l.root_id,
                        &l.root_name,
                        span,
                        l.path.as_deref(),
                        id,
                        l.elem_idx,
                        false,
                    );
                    let at = self.key(l.bind_span);
                    self.out.handle_muts.insert(at);
                }
                self.record_mutation(
                    id,
                    name,
                    span,
                    event_path,
                    id,
                    None,
                    contents_only,
                );
                return;
            }
            if !self.note_derived_use(span, "mutate", name, &links) {
                return;
            }
        }
        // Mutating a variable captured from outside an enclosing lambda:
        // the closure takes ownership at creation [fate-lambda].
        if !self.lambda_ctx.is_empty() {
            if let Some(frame) = self.frame_of_id(id) {
                self.mark_capture_mutated(frame, id);
            }
        }
        self.record_mutation(
            id,
            name,
            span,
            event_path,
            id,
            None,
            contents_only,
        );
    }

    // ================= place narrowing [flow-place] =================

    /// The recorded narrowing of a projection place, if flow analysis has
    /// one [flow-place].
    fn place_narrow_entry(&self, place: &Place) -> Option<&PlaceNarrow> {
        let var = self.lookup(&place.root)?;
        var.place_narrows.iter().find(|n| n.path == place.path)
    }

    fn place_narrow(&self, place: &Place) -> Option<&Ty> {
        self.place_narrow_entry(place).map(|n| &n.narrowed)
    }

    /// Records a projection narrowing, returning the fact it displaced.
    fn set_place_narrow(&mut self, narrow: &Narrow) -> Option<PlaceNarrow> {
        let entry = PlaceNarrow {
            path: narrow.place.path.clone(),
            narrowed: narrow.narrowed.clone(),
            declared: narrow.declared.clone(),
        };
        let var = self.lookup_mut(&narrow.place.root)?;
        match var.place_narrows.iter().position(|n| n.path == entry.path) {
            Some(i) => Some(std::mem::replace(&mut var.place_narrows[i], entry)),
            None => {
                var.place_narrows.push(entry);
                None
            }
        }
    }

    fn drop_place_narrow(&mut self, place: &Place) {
        if let Some(var) = self.lookup_mut(&place.root) {
            var.place_narrows.retain(|n| n.path != place.path);
        }
    }

    /// Drops every projection narrowing an event on `place` could falsify
    /// [flow-place-invalidate]: the place itself and everything below it
    /// (writing `h.a` replaces the subtree), and everything *above* it
    /// (writing `h.a` mutates `h`, so a fact about `h` as a whole is no
    /// longer known to hold) — i.e. every overlapping place. Sibling
    /// facts (`h.b`) survive. Only *narrowing* facts are dropped here;
    /// fate/poison is `fate_mutation`'s job.
    fn invalidate_place_narrows(&mut self, place: &Place) {
        let path = place.path.clone();
        let root = place.root.clone();
        if let Some(var) = self.lookup_mut(&root) {
            var.place_narrows.retain(|n| {
                let other = Place {
                    root: root.clone(),
                    path: n.path.clone(),
                };
                let event = Place {
                    root: root.clone(),
                    path: path.clone(),
                };
                !event.overlaps(&other)
            });
        }
    }

    /// A mutation *through a projection* [fate-poison] [flow-place]: the
    /// fate event lands on every provenance root, and projection
    /// narrowings are invalidated for exactly the storage the mutation can
    /// reach. Every site that mutates through a non-identifier expression
    /// goes through here, so no invalidation site can be forgotten.
    fn fate_mutation_through(&mut self, expr: &Expr, span: Span) {
        self.fate_mutation_through_kind(expr, span, true);
    }

    /// [deduce-field] `fate_mutation_through`, told the event's kind: a
    /// **call** taking the place as `Mut` changes its contents (identity
    /// preserved), while an **assignment** to it replaces what is there.
    fn fate_mutation_through_kind(&mut self, expr: &Expr, span: Span, contents_only: bool) {
        // [rs-loc] A mutation through a lending call's result is the
        // demand that makes the Rust backend emit the callee's mut
        // variant: record the call.
        if let Some(call_span) = self.mut_lend_call_span(expr) {
            self.out.mut_lend_calls.insert(self.key(call_span));
        }
        let mut sources = Vec::new();
        Self::provenance(expr, &mut sources);
        let names: Vec<String> = sources.iter().map(|s| s.name.clone()).collect();
        // [fate-field-disjoint] The mutation lands on the projection the
        // argument names (`p.tags` → `[.tags]`), so only values derived
        // from an overlapping projection are poisoned. A chain the analysis
        // cannot spell gives `None` — conservative, as before.
        let place = Place::of_expr(expr);
        let event_path: Option<&[Step]> = place.as_ref().map(|p| p.path.as_slice());
        for name in &names {
            self.fate_mutation_kind(name, span, event_path, contents_only);
        }
        match &place {
            Some(place) => self.invalidate_place_narrows(place),
            // Not a place rooted in a variable (a call result, say): the
            // provenance roots are still mutated, so nothing projected out
            // of them survives.
            None => {
                for name in names {
                    self.invalidate_place_narrows(&Place::root(name));
                }
            }
        }
    }

    /// [rs-loc] The innermost **derived-return call** a mutable use
    /// reaches through: `heal(front(es)!)` and `front(es)!.hp = 1` both
    /// answer `front(es)`'s span. `None` when the expression does not
    /// bottom out in a lending call whose result carries `ref(...) Mut`.
    fn mut_lend_call_span(&self, expr: &Expr) -> Option<Span> {
        let mut e = expr;
        // The type carrying `ref(...) Mut` is the *unwrapped* one for an
        // optional lender (`(ref(es) Mut T)?` at the call, `ref(es) Mut T`
        // at the `!`), so remember the innermost unwrap.
        let mut unwrap_span: Option<Span> = None;
        loop {
            match e {
                Expr::Elvis { span, .. } if e.presence_unwrapped().is_some() => {
                    unwrap_span = Some(*span);
                    e = e.presence_unwrapped().unwrap();
                }
                Expr::Field { base, .. } => e = base,
                Expr::TupleIndex { base, .. } => e = base,
                Expr::Index { base, .. } => e = base,
                _ => break,
            }
        }
        let Expr::Call { span, .. } = e else {
            return None;
        };
        // The evidence is the *type*: any call answering a `ref(...) Mut`
        // handle is a lend, whoever answers it — a named fn (the demand
        // seed), an intrinsic (①'s splice territory), or an effect member
        // (the loud v1 cut, no named decl to emit a variant of).
        let handle_ty = |sp: Span| {
            self.out
                .ty_of(self.file_idx, sp)
                .is_some_and(|t| t.is_ref() && Self::carries_mut(t))
        };
        let mutable_handle = handle_ty(*span) || unwrap_span.is_some_and(handle_ty);
        mutable_handle.then_some(*span)
    }

    /// A mutation of a whole variable: every projection fact under it
    /// falls [flow-place-invalidate].
    fn fate_mutation_root(&mut self, name: &str, span: Span) {
        self.fate_mutation(name, span);
        self.invalidate_place_narrows(&Place::root(name));
        self.strip_dependent_claims(name, &[NOT_SAME.to_string()]);
    }

    /// [deduce-field] The **field paths** a callee declares it mutates for
    /// one parameter (2026-09-25, user decision): `=> h.tags: Mut` and
    /// `=> !h.tags` each narrow the whole-value event the parameter's
    /// `Mut` would otherwise produce to `[.tags]`. `None` when the callee
    /// declares no field entry for it — the event stays `[]`, as it always
    /// has. A whole-parameter mutation entry (`=> h: Mut`) *widens* back
    /// to `[]`, since it says "mutated anywhere".
    fn declared_mut_paths(decl: &'p FnDecl, param: &str) -> Option<Vec<(Vec<Step>, bool)>> {
        let list = decl.deductions.as_ref()?;
        // Each path with its kind: `true` for a **contents** mutation
        // (`h.tags: Mut` — identity preserved), `false` for a
        // **replacement** (`!h.tags`).
        let mut paths: Vec<(Vec<Step>, bool)> = Vec::new();
        for d in list {
            let ast::DeductionTarget::Param { name, path } = &d.target else {
                continue;
            };
            if name.name != param {
                continue;
            }
            let contents_only = match &d.kind {
                // An exhaustive list mentioning `Mut` is a *contents*
                // mutation entry; a field-level `!` is a replacement.
                ast::DeductionKind::Exhaustive { quals, reapplied } => {
                    if quals
                        .iter()
                        .chain(reapplied)
                        .any(|q| q.name.name == "Mut")
                    {
                        true
                    } else {
                        continue;
                    }
                }
                ast::DeductionKind::Moved if !path.is_empty() => false,
                _ => continue,
            };
            if path.is_empty() {
                // `=> h: Mut` — anywhere.
                return Some(vec![(Vec::new(), false)]);
            }
            paths.push((
                path.iter().map(|f| Step::Field(f.name.clone())).collect(),
                contents_only,
            ));
        }
        (!paths.is_empty()).then_some(paths)
    }

    /// [qual-preserve] As `fate_mutation_root`, for a mutation whose call
    /// **preserves** some dependent claims: those survive the strip.
    fn fate_mutation_root_preserving(&mut self, name: &str, span: Span, preserve: &[String]) {
        self.fate_mutation(name, span);
        self.invalidate_place_narrows(&Place::root(name));
        self.strip_dependent_claims(name, &with_identity(preserve));
    }

    /// [deduce-field] As `fate_mutation_root_preserving`, for a call whose
    /// callee declared **which fields** it mutates: the event lands on
    /// those paths instead of the whole variable, so a derivation of a
    /// disjoint field survives by the ordinary overlap rule
    /// [fate-field-disjoint] — no new invalidation rule. Narrowings and
    /// dependent claims fall per path for the same reason.
    fn fate_mutation_fields_preserving(
        &mut self,
        name: &str,
        span: Span,
        preserve: &[String],
        paths: &[(Vec<Step>, bool)],
    ) {
        for (path, contents_only) in paths {
            self.fate_mutation_kind(name, span, Some(path.as_slice()), *contents_only);
            self.invalidate_place_narrows(&Place {
                root: name.to_string(),
                path: path.clone(),
            });
        }
        // Claims about the value are stripped as ever: a claim's own
        // precision is the follow-on (qualifiers on struct fields).
        self.strip_dependent_claims(name, &with_identity(preserve));
        // [deduce-field] Whatever survives this narrowed event cannot be a
        // live borrow in Rust (the callee still takes the whole value
        // `&mut`), so it is a candidate for the virtual-place rendering:
        // every binding linked to the root at a field path. Which survive —
        // still live after the event, and still borrow-mode — is the IR flow
        // pass's to say [fate-move-mode] (until R8 piece 8 the walk's
        // consumption marking said it).
        let Some(root_id) = self.lookup(name).map(|v| v.id) else {
            return;
        };
        let mut survivors: Vec<(Span, String, String)> = Vec::new();
        for frame in &self.locals {
            for (var_name, var) in frame {
                for l in &var.links {
                    if l.root_id != root_id {
                        continue;
                    }
                    let Some(path) = l.path.as_deref() else { continue };
                    if path.is_empty() || !path.iter().all(|s| matches!(s, Step::Field(_))) {
                        continue;
                    }
                    let mut place = l.root_name.clone();
                    for step in path {
                        place.push_str(&step.to_string());
                    }
                    survivors.push((l.bind_span, place, var_name.clone()));
                }
            }
        }
        for (stamp, place, var) in survivors {
            let c = VirtualCandidate { stamp: self.key(stamp), place, var, survivor: true };
            let at = self.out.virtual_candidates.entry(self.key(span)).or_default();
            if !at.contains(&c) {
                at.push(c);
            }
        }
    }

    /// [qual-depend] The type and fate roots of a written **place path**
    /// (`m`, `state.cache`): the base identifier must be a local in scope;
    /// each `.field` step follows the declared field type. Roots are the
    /// base variable's ultimate fate roots [fate-link] — itself, when it is
    /// a root.
    fn place_ty_and_roots(&mut self, path: &str) -> Option<(Ty, Vec<u32>)> {
        let mut parts = path.split('.');
        let base = parts.next()?;
        // Reading a place through a filled block is a use of its base.
        if let Some(var) = self.lookup_mut(base) {
            var.used = true;
        }
        let var = self.lookup(base)?;
        let mut roots: Vec<u32> = var.links.iter().map(|l| l.root_id).collect();
        if roots.is_empty() {
            roots.push(var.id);
        }
        let mut ty = var.narrowed.clone();
        for field in parts {
            let next = self.declared_field_ty(&ty.strip_quals(), field)?;
            ty = next;
        }
        Some((ty, roots))
    }

    /// [qual-depend] Mutating a value invalidates every **dependent claim**
    /// bound to it: a `KeyOf(m)` on some key is a fact about `m`'s
    /// contents, so any mutation of `m` strips it from every value holding
    /// it — the conservative direction (user decision 2026-09-23; the
    /// opt-back is the `preserve` entry, a later step of the sequence).
    fn strip_dependent_claims(&mut self, name: &str, preserve: &[String]) {
        let Some(var) = self.lookup(name) else { return };
        let mut mutated: Vec<u32> = var.links.iter().map(|l| l.root_id).collect();
        mutated.push(var.id);
        // [ref-handle] A write through a handle changes its *element*, not
        // the container's shape: only claims about the handle itself (its
        // identity, or a place under it) fall, not an `Idx` of its container.
        let handle = has_ref_arm(&var.narrowed).then_some(var.id);
        let name = name.to_string();
        for scope in self.locals.iter_mut() {
            for v in scope.values_mut() {
                let Ty::Qualified { quals, .. } = &v.narrowed else { continue };
                let stale: HashSet<String> = quals
                    .iter()
                    .filter(|q| {
                        // [qual-preserve] A preserved claim survives the
                        // mutation: the call said so (a refinement by the
                        // claim's owner, or the callee's own checked entry).
                        !preserve.contains(&q.name)
                            && q.args.iter().any(|a| match a {
                                Ty::ValueRef { roots, path } => match handle {
                                    Some(id) => roots.contains(&id) || path.split('.').next() == Some(name.as_str()),
                                    None => roots.iter().any(|r| mutated.contains(r)),
                                },
                                _ => false,
                            })
                    })
                    .map(|q| q.name.clone())
                    .collect();
                if !stale.is_empty() {
                    v.narrowed = v.narrowed.clone().remove_quals(&stale);
                }
            }
        }
    }

    /// Runs `f` with the given narrowings applied, restoring afterwards.
    /// [is-narrow-guard] Applies narrowing facts **permanently** — the
    /// `with_narrows` application half without the restore. Used for the
    /// guard idiom: when every branch of an `if` exits (`return`, `break`,
    /// `continue`, or a diverging call), the code after it is on the
    /// else-path, so the else-narrows of every condition hold there.
    ///
    /// A variable already consumed keeps that fact — a flow fact outranks a
    /// narrowing, exactly as the restore half has it [deduce-consume].
    /// [op-elvis-guard] A `?:` whose right side **leaves** has proved something
    /// about its subject on the path that follows: the value was there. So the
    /// subject's place narrows to the picked type, exactly as the branch of an
    /// `is` guard does [is-narrow-guard] — the same facts, reached from an
    /// expression instead of a condition.
    ///
    /// Only when the right side diverges: one that yields a value leaves the
    /// subject possibly-unpicked afterwards, since that is the path it took.
    fn install_elvis_guard(&mut self, subject: &'p Expr, picked: &Ty, subj_repr: &Ty) {
        let Some(place) = Place::of_expr(subject)
            .filter(|p| p.narrowable() && self.lookup(&p.root).is_some())
        else {
            return;
        };
        let narrow = Narrow {
            place,
            narrowed: picked.clone(),
            declared: subj_repr.clone(),
        };
        self.install_narrows(&[narrow]);
    }

    /// The type the checker recorded for an expression it has already walked —
    /// `analyze_cond` checks the condition itself, so re-checking it here would
    /// write its side tables twice.
    fn expr_ty_recorded(&self, expr: &Expr) -> Option<Ty> {
        self.out.expr_ty.get(&self.key(expr.span())).cloned()
    }

    /// [assert-fn] An assertion's message: an ordinary `Str` expression,
    /// evaluated **only when the assertion fails** — which is why the forms are
    /// compiler-owned rather than functions (an argument would be evaluated on
    /// every success, interpolation and all).
    /// [qual-whynot] `whynot?(x is Q)`: the test is checked as any `is` is,
    /// and must be a predicate test — the message comes from the predicate
    /// qualifiers it calls. A test decided statically (no predicate to call)
    /// answers `None`. The subject's text form is recorded for messages that
    /// show it.
    fn check_whynot(&mut self, test: &'p Expr, span: Span) -> Ty {
        let opt_str = Ty::union_of(vec![Ty::named("Str"), Ty::none()]);
        let Expr::Is { subject, binding, span: is_span, .. } = test else {
            // The parser refuses anything else.
            self.check_expr(test, None);
            return opt_str;
        };
        self.check_expr(test, None);
        if let Some(b) = binding {
            self.error(b.span, messages::qual_whynot_binding());
        }
        let key = self.key(*is_span);
        if self.out.is_tests.contains_key(&key) {
            self.error(span, messages::qual_whynot_union_test());
        }
        self.whynot_text_form(subject, *is_span);
        opt_str
    }

    /// [qual-whynot] Records the text form of a predicate test's subject when
    /// the message of one of its qualifiers shows it (a `[subject]` in its
    /// `@whynot`, or no `@whynot`, whose default does). A subject with no
    /// text form is "the value" in the message: never an error, since the
    /// message is the qualifier's, not the site's.
    fn whynot_text_form(&mut self, subject: &'p Expr, is_span: Span) {
        let Some(checks) = self.out.predicate_tests.get(&self.key(is_span)).cloned() else { return };
        let Some(ty) = self.expr_ty_recorded(subject) else { return };
        if ty.is_unknown() || Self::interp_native(&ty) {
            return;
        }
        let shows = checks.iter().any(|c| {
            let Some(decl) = self.qualifier_for(&c.name, Some(&ty)) else { return false };
            let Some(qf) = decl.fns.iter().find(|f| f.name.name == "qualifies") else { return false };
            let Some(first) = qf.params.iter().find(|p| !p.implicit) else { return false };
            match salvo_syntax::doc::split(&qf.docs).tag("whynot") {
                None => true,
                Some(tag) => salvo_syntax::doc::template(&tag.text)
                    .iter()
                    .any(|p| matches!(p, salvo_syntax::doc::TemplatePart::Param(n) if *n == first.name.name)),
            }
        });
        // [interp-to-str] The subject's text is the call `to_str(subject)`, as
        // an interpolated part's is.
        if shows && self.interp_has_text(&ty) {
            self.interp_call(subject, &ty);
        }
    }

    fn check_assert_message(&mut self, message: &'p Expr) {
        let t = self.check_expr(message, Some(&Ty::named("Str")));
        if !matches!(t, Ty::Unknown) && t.to_string() != "Str" {
            self.error(message.span(), messages::assert_fn_message_not_str(&t));
        }
    }

    fn install_narrows(&mut self, narrows: &[Narrow]) {
        for n in narrows {
            if n.place.is_root() {
                if let Some(var) = self.lookup_mut(&n.place.root) {
                    var.narrowed = n.narrowed.clone();
                    if n.declared != var.declared {
                        var.widened = Some(n.declared.clone());
                    }
                }
            } else if self.lookup(&n.place.root).is_some() {
                self.set_place_narrow(n);
            }
        }
    }

    fn with_narrows<T>(&mut self, narrows: &[Narrow], f: impl FnOnce(&mut Self) -> T) -> T {
        let mut saved: Vec<(String, Ty)> = Vec::new();
        // Applied place facts, with the fact each one displaced
        // [flow-place].
        let mut saved_places: Vec<(Place, Ty, Option<PlaceNarrow>)> = Vec::new();
        // [qual-lift] Root narrows whose *view* differs from the variable's
        // declared type (a `^` widening) install it for the branch.
        let mut saved_views: Vec<(String, Option<Ty>)> = Vec::new();
        for n in narrows {
            if n.place.is_root() {
                if let Some(var) = self.lookup_mut(&n.place.root) {
                    saved.push((n.place.root.clone(), var.narrowed.clone()));
                    var.narrowed = n.narrowed.clone();
                    if n.declared != var.declared {
                        saved_views.push((n.place.root.clone(), var.widened.clone()));
                        var.widened = Some(n.declared.clone());
                    }
                }
            } else if self.lookup(&n.place.root).is_some() {
                let displaced = self.set_place_narrow(n);
                saved_places.push((n.place.clone(), n.narrowed.clone(), displaced));
            }
        }
        let result = f(self);
        for (name, view) in saved_views.into_iter().rev() {
            if let Some(var) = self.lookup_mut(&name) {
                var.widened = view;
            }
        }
        for (name, ty) in saved.into_iter().rev() {
            if let Some(var) = self.lookup_mut(&name) {
                var.narrowed = ty;
            }
        }
        for (place, applied, displaced) in saved_places.into_iter().rev() {
            // The dual of the consumed-stays-consumed rule [flow-place]:
            // if the branch invalidated the fact we applied (an
            // assignment or a mutating call through a prefix), the
            // invalidation is a flow fact and must survive the restore.
            if self.place_narrow(&place) != Some(&applied) {
                continue;
            }
            match displaced {
                Some(previous) => {
                    self.set_place_narrow(&Narrow {
                        place,
                        narrowed: previous.narrowed,
                        declared: previous.declared,
                    });
                }
                None => self.drop_place_narrow(&place),
            }
        }
        result
    }

    /// Resets narrowing to the declared type for every variable assigned
    /// inside `block` (called after branching constructs). Projection
    /// facts fall with it [flow-place]: an assignment rebinds the variable,
    /// so nothing projected out of it is known any more.
    fn reset_assigned(&mut self, block: &Block) {
        let mut names = HashSet::new();
        collect_assigned(block, &mut names);
        for name in names {
            if let Some(var) = self.lookup_mut(&name) {
                var.narrowed = var.declared.clone();
                var.place_narrows.clear();
            }
        }
    }

    /// Snapshot of every local's flow state (narrowed type, fate links),
    /// per scope frame — the basis for branch-aware merging of
    /// consumption/qualifier-removal narrowing [deduce-consume]
    /// [fate-link].
    fn snapshot_narrows(&self) -> NarrowSnapshot {
        self.locals
            .iter()
            .map(|frame| {
                frame
                    .iter()
                    .map(|(name, var)| {
                        (
                            name.clone(),
                            VarState {
                                narrowed: var.narrowed.clone(),
                                links: var.links.clone(),
                                place_narrows: var.place_narrows.clone(),
                            },
                        )
                    })
                    .collect()
            })
            .collect()
    }

    fn restore_narrows(&mut self, snap: &NarrowSnapshot) {
        for (frame, saved) in self.locals.iter_mut().zip(snap) {
            for (name, state) in saved {
                if let Some(var) = frame.get_mut(name) {
                    var.narrowed = state.narrowed.clone();
                    var.links = state.links.clone();
                    var.place_narrows = state.place_narrows.clone();
                }
            }
        }
    }

    /// Checks a loop body; when the body's exit state changed what the walk
    /// knows — a variable's narrowing weakened (a qualifier a `Mut` call
    /// removed), a projection narrowing fell, a variable's fate links
    /// changed — re-checks it once with that exit state as the entry state,
    /// so back-edge flows surface: an overload resolved against a qualifier
    /// the previous iteration removed is refused, and a binding made from a
    /// value the previous iteration re-linked records those links too
    /// [fate-link]. Consumption is not part of the state (R8 piece 8: the IR
    /// flow pass owns moves, poison and move-mode, with its own loop
    /// fixpoint). The re-check's diagnostics are deduplicated against
    /// already-reported ones (checking is deterministic, so pass one's
    /// errors re-derive identically); its value results are discarded.
    fn check_loop_body(
        &mut self,
        body: &'p Block,
        narrows: &[Narrow],
        bindings: Vec<Binding>,
    ) -> (Ty, Option<TailInfo>) {
        let entry = self.snapshot_narrows();
        let result = self.with_narrows(narrows, |c| c.check_branch_block(body, bindings.clone()));
        if self.snapshot_narrows() != entry {
            let seen: HashSet<(usize, Span, String)> = self
                .out
                .errors
                .iter()
                .map(|e| (e.file, e.span, e.message.clone()))
                .collect();
            let before = self.out.errors.len();
            let _ = self.with_narrows(narrows, |c| c.check_branch_block(body, bindings));
            let second_pass: Vec<FileDiagnostic> = self.out.errors.split_off(before);
            for e in second_pass {
                if !seen.contains(&(e.file, e.span, e.message.clone())) {
                    self.out.errors.push(e);
                }
            }
        }
        result
    }

    /// Merges the fall-through branch states of a branching construct
    /// into the current state. For each local: states that all agree win;
    /// otherwise disagreeing states conservatively keep only the qualifiers
    /// common to all of them (a `Never` on any path is `Never`). Fate links
    /// union across branches (may-be-linked is linked [fate-link]). An
    /// empty list (every branch exits) leaves the pre-branch state
    /// untouched. Moves and poison are the IR flow pass's
    /// [flow-use-after-move], which joins its own paths.
    fn merge_fallthrough(&mut self, fallthrough: &[NarrowSnapshot]) {
        if fallthrough.is_empty() {
            return;
        }
        for (frame_idx, frame_snap) in fallthrough[0].iter().enumerate() {
            for name in frame_snap.keys() {
                let states: Vec<&VarState> = fallthrough
                    .iter()
                    .filter_map(|s| s.get(frame_idx).and_then(|f| f.get(name)))
                    .collect();
                if states.len() != fallthrough.len() {
                    continue;
                }
                let narrowed_states: Vec<&Ty> = states.iter().map(|s| &s.narrowed).collect();
                let joined = join_narrowed(&narrowed_states);
                // Fate links union across branches [fate-link].
                let mut links: Vec<FateLink> = Vec::new();
                for s in &states {
                    for l in &s.links {
                        if !links.iter().any(|e| e.root_id == l.root_id) {
                            links.push(l.clone());
                        }
                    }
                }
                // [flow-place] A projection narrowing survives the join
                // only when every fall-through path agrees on it exactly;
                // otherwise the place falls back to its declared type,
                // which is always a supertype. A `Never` variable keeps no
                // facts about its parts.
                let place_narrows: Vec<PlaceNarrow> = if matches!(joined, Ty::Never) {
                    Vec::new()
                } else {
                    states[0]
                        .place_narrows
                        .iter()
                        .filter(|n| {
                            states[1..]
                                .iter()
                                .all(|s| s.place_narrows.iter().any(|m| *m == **n))
                        })
                        .cloned()
                        .collect()
                };
                if let Some(var) = self.locals.get_mut(frame_idx).and_then(|f| f.get_mut(name)) {
                    var.narrowed = joined;
                    var.links = links;
                    var.place_narrows = place_narrows;
                }
            }
        }
    }

    // ================= type lowering =================

    fn lower_type(&mut self, ty: &ast::Type) -> Ty {
        let subst = HashMap::new();
        let lowered = self.lower_type_subst(ty, &subst, 0);
        if !lowered.is_unknown() {
            self.out.written_types.insert(written_type_key(ty), lowered.clone());
            if self.record {
                self.written_log.push((written_type_key(ty), lowered.clone(), false));
            }
        }
        lowered
    }

    fn lower_type_subst(
        &mut self,
        ty: &ast::Type,
        subst: &HashMap<String, Ty>,
        depth: usize,
    ) -> Ty {
        if depth > 32 {
            return Ty::Unknown;
        }
        // [ir-nodes] A written type reached only with a substitution (a
        // struct's field at a use) is recorded in its *declared* shape — the
        // generics as variables — the first time, so the IR builder has a type
        // for every declaration's fields.
        if depth == 0 && !subst.is_empty() {
            let key = written_type_key(ty);
            if !self.out.written_types.contains_key(&key) {
                let as_declared: HashMap<String, Ty> = subst.keys().map(|k| (k.clone(), Ty::Var(k.clone()))).collect();
                let declared = self.lower_type_subst(ty, &as_declared, 1);
                if !declared.is_unknown() {
                    if self.record {
                        self.written_log.push((key, declared.clone(), true));
                    }
                    self.out.written_types.insert(key, declared);
                }
            } else if self.record {
                // [lsp-check-cache] Found written: this walk writes it when
                // no earlier one has, so a cached check writes it then too,
                // in the shape found (every lowering of a node's declared
                // shape gives the same).
                if let Some(found) = self.out.written_types.get(&key) {
                    self.written_log.push((key, found.clone(), true));
                }
            }
        }
        match ty {
            ast::Type::Literal { value, .. } => Ty::Lit(value.clone()),
            ast::Type::Named { qualifiers, base } => {
                let lowered = self.lower_base_ref(base, subst, depth);
                let quals = self.lower_quals(qualifiers, subst, depth);
                lowered.qualify(quals)
            }
            ast::Type::QualifiedGroup {
                qualifiers, base, ..
            } => {
                let lowered = self.lower_type_subst(base, subst, depth);
                let quals = self.lower_quals(qualifiers, subst, depth);
                lowered.qualify(quals)
            }
            ast::Type::Union { arms, .. } => {
                let arms = arms
                    .iter()
                    .map(|a| self.lower_type_subst(a, subst, depth))
                    .collect();
                self.mk_union(arms)
            }
            ast::Type::Nullable { inner, .. } => {
                let inner = self.lower_type_subst(inner, subst, depth);
                self.mk_union(vec![inner, Ty::none()])
            }
            ast::Type::Spread { inner, .. } => {
                // [type-union-spread] `...T` lowers to the spread marker over its
                // lowered inner type; `unify_union_arms` reads it. Everywhere
                // else the marker is stripped to its inner (an arm's concrete
                // reading), so no position outside unification sees it.
                let inner = self.lower_type_subst(inner, subst, depth);
                Ty::spread_marker(inner)
            }
            ast::Type::Tuple { elems, .. } => Ty::Tuple(
                elems
                    .iter()
                    .map(|e| self.lower_type_subst(e, subst, depth))
                    .collect(),
            ),
            ast::Type::Array { elem, .. } => {
                Ty::Array(Box::new(self.lower_type_subst(elem, subst, depth)))
            }
            ast::Type::Fn {
                params,
                ret,
                effects,
                ..
            } => Ty::Fn {
                contract: self.lower_fn_contract(ty),
                // [fn-effects] The effects a call of the value performs.
                effects: self.lower_fn_effects(effects.as_deref()),
                params: params
                    .iter()
                    .map(|p| self.lower_type_subst(p, subst, depth))
                    .collect(),
                ret: Box::new(self.lower_type_subst(ret, subst, depth)),
            },
        }
    }

    /// Builds a fn type's contract from its written parameter names and
    /// deduction list [fn-contract]. `None` when nothing is written (the
    /// default: keeps everything). Entries: kept unless the (explicit)
    /// deduction list omits the named parameter; kept quals per the list
    /// (bare name = all declared); `mutable` = the declared param type
    /// carries `Mut`.
    fn lower_fn_contract(&mut self, ty: &ast::Type) -> Option<Vec<FnParamContract>> {
        let ast::Type::Fn {
            params,
            param_names,
            deductions,
            ret,
            ..
        } = ty
        else {
            return None;
        };
        if param_names.iter().all(|n| n.is_none()) && deductions.is_none() {
            return None;
        }
        // [proj-infer-fn-type] Whether this fn type's kept positions lend
        // without saying so: only where the **return is opaque to the
        // signature**, meaning a bare type parameter. That is the case a
        // written lend exists for — the result's real type is chosen by
        // whoever fills the slot, so the signature cannot see whether it holds
        // a borrow, and one Rust signature has to serve every filling. A
        // *concrete* return says for itself (`-> Mut List<T>` holds nothing;
        // `-> Mut ListNext<T>` is a named borrowing type the emitter already
        // ties), so nothing is inferred there and no existing signature
        // changes meaning.
        let infer_lends = matches!(ret.as_ref(), ast::Type::Named { qualifiers, base, .. }
            if base.args.is_empty()
                && qualifiers.iter().all(|q| q.name.name == "Mut")
                && self.generics.contains(base.name.name.as_str()));
        let declared_quals = |t: &ast::Type| -> Vec<String> {
            match t {
                ast::Type::Named { qualifiers, .. }
                | ast::Type::QualifiedGroup { qualifiers, .. } => {
                    qualifiers.iter().map(|q| q.name.name.clone()).collect()
                }
                _ => Vec::new(),
            }
        };
        let entries: Vec<FnParamContract> = params
            .iter()
            .zip(param_names)
            .map(|(t, name)| {
                let declared = declared_quals(t);
                let mutable = declared.iter().any(|q| q == "Mut");
                let names = |items: &[ast::TypeRef]| -> Vec<String> {
                    items.iter().map(|q| q.name.name.clone()).collect()
                };
                let (kept, effect) = match (name, deductions) {
                    (Some(id), Some(list)) => {
                        match list
                            .iter()
                            .find(|d| d.param_name().is_some_and(|n| n.name == id.name))
                        {
                            Some(d) => match &d.kind {
                                ast::DeductionKind::KeepAll
                                | ast::DeductionKind::Proj(_)
                                // [qual-preserve] About other values' claims,
                                // not this parameter's own list.
                                | ast::DeductionKind::Preserve(_)
                                // [implicit-with] A relation between two
                                // parameters; it says nothing about either
                                // one's qualifier list.
                                | ast::DeductionKind::With { .. } => {
                                    (true, QualEffect::KeepAll)
                                }
                                ast::DeductionKind::Exhaustive { quals, reapplied } => {
                                    // [deduce-reapply] A fn *type*'s contract is
                                    // a claim about a value someone else wrote,
                                    // so it has no body to trust or check and
                                    // `+Q` is refused at the signature (below).
                                    // The names still union, so a refused one
                                    // stays one diagnostic.
                                    let mut keep = names(quals);
                                    keep.extend(names(reapplied));
                                    (true, QualEffect::Exhaustive(keep))
                                }
                                ast::DeductionKind::Remove(items) => {
                                    (true, QualEffect::Remove(names(items)))
                                }
                                ast::DeductionKind::Moved
                                | ast::DeductionKind::Deferred => {
                                    (false, QualEffect::Exhaustive(Vec::new()))
                                }
                            },
                            // [deduce-syntax] Unmentioned in a fn type's
                            // group: kept, the default.
                            None => (true, QualEffect::KeepAll),
                        }
                    }
                    // Named but no group, or unnamed: keeps everything.
                    _ => (true, QualEffect::KeepAll),
                };
                // [proj-infer] `-> T holds proj(c)` on a fn type (synthesized
                // into its contract list by the parser): what a bodiless
                // value's result holds.
                let written = match (name, deductions) {
                    (Some(id), Some(list)) => list
                        .iter()
                        .filter_map(|d| d.proj_sources())
                        .flatten()
                        .any(|src| src.name == id.name),
                    _ => false,
                };
                // [proj-infer-fn-type] **Unwritten, so inferred** (user
                // decision 2026-09-26): a fn type whose *return* is opaque —
                // a bare type parameter, which is every pass-minting slot
                // (`?iter: (c: C) -> Mut It`) — may instantiate to a type
                // holding a borrow of what it was given, and only the lend
                // makes that borrow nameable. So every **kept** position of
                // such a fn type lends, conservatively, which is what
                // [proj-infer]'s fallback already says for a bodiless
                // declaration — and a fn type *is* a bodiless declaration.
                //
                // Free, and probed: the lend is strictly more permissive than
                // its absence, because a candidate whose result holds no
                // borrow simply does not use the lifetime. Writing the clause
                // is therefore redundant rather than meaningful, which is why
                // this reads the two cases the same way.
                // A lend **names a source**, so an unnamed position cannot
                // carry one: std's `?copy: (T) -> T` has no name for a
                // lifetime to attach to, and inferring one there emitted a
                // `&'c T` nothing declared.
                let lent = written || (infer_lends && kept && name.is_some());
                FnParamContract {
                    name: name.as_ref().map(|id| id.name.clone()),
                    kept,
                    effect,
                    mutable,
                    lent,
                }
            })
            .collect();
        // [proj-infer-fn-type] A written lend on an **opaque-returning** slot
        // says what the signature already infers, and an annotation that
        // changes nothing reads as evidence that something needs saying — the
        // same reason a no-op `@place` selector warns [fn-overload-at] (user
        // decision 2026-09-26). It stays a warning, not an error: the program
        // is correct and the clause is merely spare.
        if infer_lends {
            // One diagnostic per *clause*, naming every source it spends:
            // `holds proj(c, k)` is one thing the author wrote, so it reads as
            // one thing to remove.
            let spare: Vec<&ast::Ident> = deductions
                .iter()
                .flatten()
                .filter(|d| matches!(d.target, ast::DeductionTarget::Opaque))
                .filter_map(|d| d.proj_sources())
                .flatten()
                .filter(|src| param_names.iter().flatten().any(|p| p.name == src.name))
                .collect();
            if let Some(first) = spare.first() {
                let span = first.span;
                if self.warned_spare_lends.insert((self.file_idx, span)) {
                    let names: Vec<&str> = spare.iter().map(|i| i.name.as_str()).collect();
                    self.warn(
                        span,
                        messages::proj_infer_fn_type_redundant_holds(&names.join(", ")),
                    );
                }
            }
        }
        // Validate the group's entries name the fn type's parameters.
        if let Some(list) = deductions {
            for d in list {
                let mut named: Vec<&ast::Ident> = Vec::new();
                if let ast::DeductionTarget::Param { name, .. } = &d.target {
                    named.push(name);
                }
                if let Some(sources) = d.proj_sources() {
                    named.extend(sources.iter());
                }
                for n in named {
                    let known = param_names.iter().flatten().any(|p| p.name == n.name);
                    if !known {
                        self.error(n.span, messages::fn_contract_not_a_param(&n.name));
                    }
                }
            }
        }
        Some(entries)
    }

    fn lower_quals(
        &mut self,
        qualifiers: &[TypeRef],
        subst: &HashMap<String, Ty>,
        depth: usize,
    ) -> Vec<Qual> {
        // [cmp-carry] A qualifier that declares fn slots takes **identities**
        // in its argument list, in slot order — never types: a qualifier's
        // type arguments come from the type it qualifies (`Ok Str` implies
        // `Ok<Str>`), so `Heap(cmp@Person)` is unambiguous and one heap's
        // arguments always read the same way.
        let slotted: Vec<Option<Vec<FnSlotInfo>>> = qualifiers
            .iter()
            .map(|q| {
                let slots = self.qual_fn_slots(&q.name.name);
                if slots.is_empty() {
                    None
                } else {
                    Some(slots)
                }
            })
            .collect();
        let mut out: Vec<Qual> = Vec::new();
        for (q, slots) in qualifiers.iter().zip(&slotted) {
            if self.is_route_key(q) {
                continue;
            }
            if let Some(slots) = slots {
                // [cmp-carry] A qualifier's type arguments are written first
                // (`Heap<T>(?cmp) List<T>`), its slots after — the same
                // positional reading a keyed type has (user decision
                // 2026-09-22).
                let generics: Vec<String> = self
                    .written_qual_decl(q)
                    .map(|d| d.generics.iter().map(|g| g.name.clone()).collect())
                    .unwrap_or_default();
                let arity = generics.len();
                let args = self.lower_identity_args(
                    &q.args,
                    &q.value_args,
                    Some(arity),
                    &generics,
                    slots,
                    subst,
                    depth,
                );
                // [lsp-definition] Only a user qualifier has a declaration to
                // point at; a built-in auto-qualifier (`Mut`) does not.
                self.record_qualifier_def(q);
                out.push(Qual {
                    effect: false,
                    name: q.name.name.clone(),
                    args,
                });
                continue;
            }
            out.push(self.lower_qual_plain(q, subst, depth));
        }
        out
    }

    /// [cmp-binder] Every binder occurrence in a lowered type, paired with the
    /// fn type its **slot** demands — the position states the type, so the fn
    /// never writes it. One binding per name: a repeat occurrence adds
    /// nothing, which is what makes `heap_merge`'s two parameters share an
    /// ordering.
    fn collect_binder_slots(
        &mut self,
        ty: &Ty,
        span: Span,
        out: &mut Vec<(String, Ty, Span, Option<String>)>,
    ) {
        match ty {
            Ty::Qualified { quals, base } => {
                for q in quals {
                    // [cmp-carry] A qualifier's type arguments come first, its
                    // slots after, so the slot index is the argument's position
                    // less the declared type arity.
                    let arity = self.qual_decl(&q.name).map_or(0, |d| d.generics.len());
                    for (i, arg) in q.args.iter().enumerate() {
                        let Ty::FnName(FnId::Binder(name)) = arg else {
                            continue;
                        };
                        if out.iter().any(|(n, _, _, _)| n == name) {
                            continue;
                        }
                        let at = i.saturating_sub(arity);
                        let Some(want) = self.qual_slot_ty(&q.name, at, base) else {
                            continue;
                        };
                        let slot = self.qual_fn_slots(&q.name).get(at).map(|s| s.name.clone());
                        out.push((name.clone(), want, span, slot));
                    }
                }
                self.collect_binder_slots(base, span, out);
            }
            Ty::Named { name, args } => {
                let slots = self.type_fn_slots(name);
                let arity = args.len().saturating_sub(slots.len());
                for (i, arg) in args.iter().enumerate() {
                    if let Ty::FnName(FnId::Binder(binder)) = arg {
                        if out.iter().any(|(n, _, _, _)| n == binder) {
                            continue;
                        }
                        let at = i.saturating_sub(arity);
                        if let Some(want) =
                            self.type_slot_ty(name, &args[..arity.min(args.len())], at)
                        {
                            let slot = self.type_fn_slots(name).get(at).map(|s| s.name.clone());
                            out.push((binder.clone(), want, span, slot));
                        }
                        continue;
                    }
                    self.collect_binder_slots(arg, span, out);
                }
            }
            Ty::Union(arms) => {
                for a in arms {
                    self.collect_binder_slots(a, span, out);
                }
            }
            Ty::Tuple(elems) => {
                for e in elems {
                    self.collect_binder_slots(e, span, out);
                }
            }
            Ty::Array(elem) => self.collect_binder_slots(elem, span, out),
            Ty::Fn { params, ret, .. } => {
                for p in params {
                    self.collect_binder_slots(p, span, out);
                }
                self.collect_binder_slots(ret, span, out);
            }
            _ => {}
        }
    }

    /// [cmp-carry] The fn type a **qualifier's** slot demands, over the types the
    /// qualified value is made of: `Heap<T>(?cmp: (T, T) -> Int) of List<T>`
    /// applied to a `List<Person>` wants `(Person, Person) -> Int`. The
    /// qualifier's own type parameters come from its `of` type matched against
    /// the value, which is the same reading `Ok Str` implies `Ok<Str>` by.
    fn qual_slot_ty(&mut self, qual: &str, index: usize, base: &Ty) -> Option<Ty> {
        let decl = self.qual_decl(qual)?;
        let slots = self.qual_fn_slots(qual);
        let want = slots.get(index)?.ty.clone();
        let generic_names = decl.generics.clone();
        let saved = self.enter_generics(&generic_names);
        let of = self.lower_type(&decl.of);
        self.generics = saved;
        let mut subst: HashMap<String, Ty> = HashMap::new();
        unify(&of, base, &mut subst);
        let generics: HashSet<String> = generic_names.iter().map(|g| g.name.clone()).collect();
        Some(substitute_vars(&want, &subst, &generics))
    }

    /// [cmp-carry] The fn type an `intrinsic type`'s slot demands, over the type
    /// arguments written beside it: `SortedSet<Str>(?cmp)` wants
    /// `(Str, Str) -> Int`.
    fn type_slot_ty(&mut self, name: &str, type_args: &[Ty], index: usize) -> Option<Ty> {
        let (_, decl_generics) = self.slotted_type(name)?;
        let slots = self.type_fn_slots(name);
        let want = slots.get(index)?.ty.clone();
        let subst: HashMap<String, Ty> = decl_generics
            .iter()
            .map(|g| g.name.clone())
            .zip(type_args.iter().cloned())
            .collect();
        let generics: HashSet<String> = decl_generics.iter().map(|g| g.name.clone()).collect();
        Some(substitute_vars(&want, &subst, &generics))
    }

    /// [cmp-carry] The visible declaration of a qualifier name.
    fn qual_decl(&self, name: &str) -> Option<&'p QualifierDecl> {
        self.scope
            .qualifiers
            .get(name)
            .and_then(|decls| decls.first())
            .copied()
    }

    /// [default-fits] Checks a `= default` against the slot it fills: a struct
    /// field, a parameter or a handler's state. One helper for every default
    /// site, so they cannot drift (until 2026-10-20 the struct-field and
    /// parameter sites discarded the result, and `port: InRange(1, 10) Int =
    /// 8080` compiled with a false claim).
    ///
    /// A default may lack a **predicate** qualifier the slot carries when the
    /// qualifier can be tested where the default is applied ([`Self::
    /// default_checkable`]): the IR then tests it there and traps on failure,
    /// as `x!` does ([default-predicate], user decision 2026-10-20, the CLI design record
    /// round 2 Q2). Any other mismatch is an error.
    fn check_default(&mut self, default: &'p ast::Expr, expected: &Ty) {
        let got = self.check_expr(default, Some(expected));
        if got.is_unknown() || expected.is_unknown() || is_subtype(&got, expected) {
            return;
        }
        let missing: Vec<&Qual> = expected
            .quals()
            .iter()
            .filter(|q| !got.quals().iter().any(|g| g.name == q.name && g.args == q.args))
            .collect();
        let deferred: HashSet<String> = missing
            .iter()
            .filter(|q| self.default_checkable(q))
            .map(|q| q.name.clone())
            .collect();
        if !deferred.is_empty() && is_subtype(&got, &expected.clone().remove_quals(&deferred)) {
            return;
        }
        let unprovable: Vec<String> = missing
            .iter()
            .filter(|q| !deferred.contains(&q.name) && self.qual_decl(&q.name).is_some())
            .map(|q| format!("`{}`", q.name))
            .collect();
        let why = if unprovable.is_empty() || !is_subtype(&got, expected.strip_quals()) {
            String::new()
        } else {
            format!(
                ": a default can lack only a predicate qualifier with constant arguments \
                 (tested where the default is used), and {} is not one",
                unprovable.join(", ")
            )
        };
        self.error(default.span(), messages::default_fits_mismatch(&expected, &got, &why));
    }

    /// [default-predicate] Whether a slot's qualifier can be tested where a
    /// default is applied: a predicate qualifier (it has `qualifies`) whose
    /// arguments are all constants [qual-const], and whose `qualifies` needs
    /// no implicits and performs no effects, since a default is applied at
    /// sites that need not have either.
    fn default_checkable(&self, q: &Qual) -> bool {
        if !q.args.iter().all(|a| matches!(a, Ty::Const(_))) {
            return false;
        }
        let Some(decl) = self.qual_decl(&q.name) else { return false };
        let Some(f) = decl.fns.iter().find(|f| f.name.name == "qualifies") else { return false };
        f.params.iter().all(|p| !p.implicit) && f.effects.iter().flatten().next().is_none()
    }

    /// [cmp-carry] Validates a declaration's **slot list**: every written slot's
    /// type resolves, a group spread names a visible `fns` group, two slots of
    /// one name at one type are merged (so only a clash at two *types* is
    /// reported), and a `= default` names a fn that exists.
    ///
    /// What is *not* checked here is whether a default fits its slot: the slot is
    /// written over the declaration's own type parameters (`(T, T) -> Int`), and
    /// `cmp` fits it only once `T` is something. That check belongs to the
    /// instantiation, which is also where its error is worth reading.
    fn check_fn_slots(
        &mut self,
        owner: &str,
        slots: &'p [ast::SlotDecl],
        generics: &[ast::Ident],
    ) {
        for entry in slots {
            match entry {
                ast::SlotDecl::One(slot) => self.validate_type(&slot.ty),
                // [cmp-carry] A group spread in a slot list is the same
                // declaration-side shorthand it is in a parameter list, so it
                // gets the same diagnostic when the group is not there.
                ast::SlotDecl::Group(spread) => {
                    self.record_written_def(spread);
                    let Some(group) = self.named(spread).group else {
                        let name = spread.name.name.clone();
                        self.error_unresolved(
                            spread.span,
                            messages::cmp_carry_unknown_group(&name),
                            &name,
                        );
                        continue;
                    };
                    for a in &spread.args {
                        self.validate_type(a);
                    }
                    if spread.args.len() != group.generics.len() {
                        self.error(
                            spread.span,
                            messages::implicit_group_type_arg_count(
                                &group.name.name,
                                &group.generics.len(),
                                &spread.args.len(),
                            ),
                        );
                    }
                }
            }
        }
        // The clash a merge cannot resolve: one name, two types.
        self.slot_clashes(owner, slots, generics);
    }

    /// [cmp-carry] Reports a slot name declared twice at two different types —
    /// the one overlap a merge cannot absorb [implicit-group].
    fn slot_clashes(
        &mut self,
        owner: &str,
        slots: &'p [ast::SlotDecl],
        generics: &[ast::Ident],
    ) {
        let expanded = self.expand_slots(slots, generics);
        let mut seen: Vec<(String, Ty)> = Vec::new();
        for slot in expanded {
            match seen.iter().find(|(n, _)| *n == slot.name) {
                Some((_, ty)) if *ty == slot.ty => {}
                Some((_, ty)) => {
                    let (first, second) = (ty.clone(), slot.ty.clone());
                    self.error(
                        self.slot_span(slots, &slot.name),
                        messages::implicit_group_slot_twice(&owner, &slot.name, &first, &second),
                    );
                }
                None => seen.push((slot.name.clone(), slot.ty)),
            }
        }
    }

    /// Where to report something about a named slot: its own entry if it was
    /// written out, else the spread that contributed it.
    fn slot_span(&self, slots: &'p [ast::SlotDecl], name: &str) -> Span {
        for entry in slots {
            match entry {
                ast::SlotDecl::One(s) if s.name.name == name => return s.span,
                ast::SlotDecl::Group(g) => return g.span,
                _ => {}
            }
        }
        slots
            .first()
            .map(|e| match e {
                ast::SlotDecl::One(s) => s.span,
                ast::SlotDecl::Group(g) => g.span,
            })
            .unwrap_or_default()
    }

    /// [cmp-carry] The slot list a qualifier declares, expanded: written slots as
    /// themselves, a group spread as one slot per member.
    fn qual_fn_slots(&mut self, name: &str) -> Vec<FnSlotInfo> {
        let Some(decl) = self.qual_decl(name) else {
            return Vec::new();
        };
        if decl.fn_slots.is_empty() {
            return Vec::new();
        }
        let generics = decl.generics.clone();
        let slots = &decl.fn_slots;
        self.expand_slots(slots, &generics)
    }

    /// [cmp-carry] The same for an `intrinsic type`.
    fn type_fn_slots(&mut self, name: &str) -> Vec<FnSlotInfo> {
        let Some((slots, generics)) = self.slotted_type(name) else {
            return Vec::new();
        };
        if slots.is_empty() {
            return Vec::new();
        }
        let generics = generics.to_vec();
        self.expand_slots(slots, &generics)
    }

    /// [cmp-carry] [struct-slot] The slot list and type parameters of a type
    /// declaration that may have slots: an `intrinsic type` or a struct.
    fn slotted_type(&self, name: &str) -> Option<(&'p [ast::SlotDecl], &'p [Ident])> {
        if let Some(decl) = self.symbols.intrinsic_types.get(name).copied() {
            return Some((&decl.fn_slots, &decl.generics));
        }
        let decl: &'p StructDecl = self.symbols.structs.get(name).copied()?;
        Some((&decl.fn_slots, &decl.generics))
    }

    /// [cmp-carry] Expands a declaration's slot list under its own type
    /// parameters. A group spread contributes its members in declaration order,
    /// taking the positions where the spread is written, and two entries asking
    /// for the same position at the same type are **merged** — exactly as two
    /// implicit spreads are [implicit-group].
    fn expand_slots(
        &mut self,
        slots: &'p [ast::SlotDecl],
        generics: &[ast::Ident],
    ) -> Vec<FnSlotInfo> {
        let saved = self.enter_generics(generics);
        let mut out: Vec<FnSlotInfo> = Vec::new();
        for entry in slots {
            match entry {
                ast::SlotDecl::One(slot) => {
                    let ty = self.lower_type(&slot.ty);
                    push_slot(
                        &mut out,
                        FnSlotInfo {
                            name: slot.name.name.clone(),
                            ty,
                        },
                    );
                }
                ast::SlotDecl::Group(spread) => {
                    let Some(group) = self
                        .scope
                        .fn_groups
                        .get(spread.name.name.as_str())
                        .copied()
                    else {
                        continue;
                    };
                    let args: Vec<Ty> = spread.args.iter().map(|a| self.lower_type(a)).collect();
                    if args.len() != group.generics.len() {
                        continue;
                    }
                    let subst: HashMap<String, Ty> = group
                        .generics
                        .iter()
                        .map(|g| g.name.clone())
                        .zip(args)
                        .collect();
                    let bound: HashSet<String> =
                        group.generics.iter().map(|g| g.name.clone()).collect();
                    for member in &group.fns {
                        let inner = self.enter_generics(&group.generics);
                        let ty = self.member_fn_ty(member);
                        self.generics = inner;
                        push_slot(
                            &mut out,
                            FnSlotInfo {
                                name: member.name.name.clone(),
                                ty: substitute_vars(&ty, &subst, &bound),
                            },
                        );
                    }
                }
            }
        }
        self.generics = saved;
        out
    }


    /// [cmp-carry] Lowers a written argument list against a declaration's slot
    /// list. `type_arity` is how many leading arguments are ordinary *types*.
    ///
    /// Two ways to fill a slot, and the spelling says which: an **identity**
    /// (`cmp@Person`) fills the next slot positionally, while a **binder**
    /// (`?cmp`, `?cmp: cmp2`) names its slot — `?` on the left is the slot's own
    /// name, and an alias on the right is what the binder is called here
    /// [cmp-binder]. Naming the slot is what makes a partial list readable:
    /// `Heap<T>(?eq)` constrains the `eq` slot and says nothing about `cmp`.
    ///
    /// A slot nobody wrote takes its declared default, or stays **unconstrained**
    /// — `Ty::Unknown`, which is compatible in both directions
    /// [type-unknown-lenient] and is exactly what "this signature does not care
    /// which" means. That is what makes a written slot list a *pattern* rather
    /// than an exact type, and today's bare `Heap` the empty case of one rule.
    fn lower_identity_args(
        &mut self,
        written: &[ast::Type],
        values: &[ast::Type],
        type_arity: Option<usize>,
        generics: &[String],
        slots: &[FnSlotInfo],
        subst: &HashMap<String, Ty>,
        depth: usize,
    ) -> Vec<Ty> {
        let type_arity = type_arity.unwrap_or(0);
        // [qual-value-arg] Type generics are **all-or-none** at a use site
        // (user decision 2026-09-23): written in full or all inferred, so a
        // partial list cannot silently shift which position a reader takes
        // an argument for.
        if !written.is_empty() && written.len() != type_arity {
            if let Some(span) = written.first().map(|w| w.span()) {
                self.error(span, messages::qual_value_arg_partial_type_args(&type_arity));
            }
        }
        let mut types: Vec<Ty> = Vec::new();
        let mut filled: Vec<Option<Ty>> = vec![None; slots.len()];
        let mut next_positional = 0usize;
        for arg in written.iter().take(type_arity) {
            types.push(self.lower_type_subst(arg, subst, depth));
        }
        for arg in values.iter() {
            // Which slot this argument is for.
            let named = match arg {
                ast::Type::Named { base, .. } if base.binder => {
                    match slots.iter().position(|s| s.name == base.name.name) {
                        Some(at) => Some(at),
                        None => {
                            let known: Vec<String> =
                                slots.iter().map(|s| format!("`?{}`", s.name)).collect();
                            self.error(
                                arg.span(),
                                messages::cmp_binder_unknown_slot(
                                    &base.name.name,
                                    &(if known.is_empty() {
                                        String::new()
                                        } else {
                                        format!(" (it has {})", known.join(", "))
                                        }),
                                ),
                            );
                            continue;
                        }
                    }
                }
                _ => {
                    let at = next_positional;
                    next_positional += 1;
                    if at >= slots.len() {
                        let names: Vec<String> =
                            slots.iter().map(|s| format!("`?{}`", s.name)).collect();
                        self.error(
                            arg.span(),
                            messages::cmp_binder_too_many(
                                &slots.len(),
                                &(if names.is_empty() {
                                    String::new()
                                    } else {
                                    format!(" ({})", names.join(", "))
                                    }),
                            ),
                        );
                        continue;
                    }
                    Some(at)
                }
            };
            let Some(at) = named else { continue };
            if filled[at].is_some() {
                self.error(arg.span(), messages::cmp_binder_filled_twice(&slots[at].name));
                continue;
            }
            // [cmp-carry] The slot's fn type at these type arguments, so a
            // written name is resolved to the overload that fits it.
            let want = {
                let bind: HashMap<String, Ty> = generics.iter().cloned().zip(types.iter().cloned()).collect();
                let names: HashSet<String> = generics.iter().cloned().collect();
                substitute_vars(&slots[at].ty, &bind, &names)
            };
            filled[at] = Some(match self.written_fn_id(arg, Some(&want)) {
                Some(id) => Ty::FnName(id),
                None => Ty::Unknown,
            });
        }
        // A qualifier's type arguments are "rarely written explicitly" (`Ok Str`
        // implies `Ok<Str>`), so an unwritten one is unconstrained too — and
        // padding them keeps every mention of the qualifier the same arity,
        // which is what lets a bare `Heap` and a `Heap<Person>(cmp@Person)`
        // compare at all.
        // [cmp-carry] **An unwritten slot is resolved by its name**, exactly as an
        // implicit parameter is [implicit-resolve] — there is no default to
        // materialize, so a type nobody wrote an identity into carries none.
        // `Set<Str>` is therefore exactly the type it has always been, a bare
        // `Heap` carries nothing, and only a type that says something *different*
        // about its ordering grows an argument to say it in. That is what keeps
        // this out of the hundreds of places that read a container's type
        // arguments positionally.
        let identities: Vec<Ty> = filled
            .iter()
            .map(|f| f.clone().unwrap_or(Ty::Unknown))
            .collect();
        let mut out = types;
        if identities.iter().all(|id| id.is_unknown()) {
            return out;
        }
        while out.len() < type_arity {
            out.push(Ty::Unknown);
        }
        out.extend(identities);
        out
    }

    /// [cmp-carry] The function **identity** a type-argument position writes:
    /// `?cmp` (the signature's binder), `cmp@Person` (a selector, so the
    /// reader and the checker both know it names a fn) or a bare name.
    ///
    /// A bare name must have **static identity** (decision 12) — it must name
    /// a top-level fn. A local, a parameter or an implicit of fn type is
    /// refused here, because a type cannot carry something with no name of its
    /// own: that is what makes an identity printable, comparable and
    /// substitutable.
    fn written_fn_id(&mut self, arg: &ast::Type, want: Option<&Ty>) -> Option<FnId> {
        // [type-identity] [cmp-carry] An identity is resolved in the file that
        // **wrote** it: a callee's signature is lowered at every call, and its
        // `Set<P>(my_hash, my_eq)` means the writer's `my_hash`, not whatever the
        // calling file sees under that name (found 2026-10-20). That file
        // reports its own mistakes when it is checked; lowering it here only
        // reads the answer.
        let own = match arg {
            ast::Type::Named { base, .. } => self.written_file(base).filter(|f| *f != self.file_idx),
            _ => None,
        };
        if let Some(own) = own {
            let saved_scope = self.scope;
            let saved_errors = self.out.errors.len();
            self.scope = &self.resolution.scopes[own];
            let out = self.written_fn_id_here(arg, want, false);
            self.scope = saved_scope;
            self.out.errors.truncate(saved_errors);
            return out;
        }
        self.written_fn_id_here(arg, want, true)
    }

    fn written_fn_id_here(&mut self, arg: &ast::Type, want: Option<&Ty>, own_file: bool) -> Option<FnId> {
        let ast::Type::Named { qualifiers, base } = arg else {
            self.error(arg.span(), messages::cmp_carry_type_not_identity());
            return None;
        };
        if !qualifiers.is_empty() || !base.args.is_empty() || !base.from.is_empty() {
            self.error(arg.span(), messages::cmp_carry_identity_not_plain());
            return None;
        }
        let name = base.name.name.clone();
        if base.binder {
            // [cmp-binder] The binder's name in this signature: its alias when
            // one is written, else the slot's own name.
            return Some(FnId::Binder(
                base.alias.as_ref().map(|a| a.name.clone()).unwrap_or(name),
            ));
        }
        if let Some(at) = &base.at {
            let at_name = at.name.clone();
            if !self.fn_exists_at(&name, &at_name) {
                let msg = if at_name.starts_with(|c: char| c.is_uppercase()) {
                    messages::fn_attached_no_identity_on_type(&name, &at_name)
                } else {
                    messages::fn_overload_at_no_identity_in_module(&name, &at_name)
                };
                self.error(arg.span(), msg);
                return None;
            }
            return self.written_declaration(&name, Some(&at_name), want, arg.span());
        }
        // A bare name: a top-level fn, and nothing else. (A local is the
        // checking fn's, so it only shadows in the file that is checking.)
        if own_file && self.lookup(&name).is_some() {
            self.error(arg.span(), messages::cmp_carry_local_identity(&name));
            return None;
        }
        if self.generics.contains(&name) {
            self.error(arg.span(), messages::cmp_carry_type_param_identity(&name));
            return None;
        }
        if !self.has_callable(&name) {
            self.error_unresolved(arg.span(), messages::cmp_carry_unknown_fn(&name), &name);
            return None;
        }
        self.written_declaration(&name, None, want, arg.span())
    }

    /// [cmp-carry] The identity a written name (`my_hash`, `cmp@Person`,
    /// `size@core.list`) carries: the declaration it means here, which is
    /// resolution's answer at the slot's fn type — the overload of the right
    /// shape, as a resolved fill would pick it, so a written `(hash, eq)` and
    /// a resolved one are one identity. **No rung fallback** (R10 D23): where
    /// resolution cannot decide between candidates that fit, the written type
    /// is ambiguous — an error naming `name@module` — and no identity; until
    /// 2026-10-28 the most specific rung's declaration was taken silently.
    /// Where nothing fits, the one declaration of the name is named anyway
    /// (several: the bare name), and the mismatch is reported where the slot
    /// is checked.
    fn written_declaration(&mut self, name: &str, at: Option<&str>, want: Option<&Ty>, span: Span) -> Option<FnId> {
        if let Some(want) = want {
            let before = self.out.errors.len();
            let found = self.resolve_implicit_fn_at(name, at, want);
            self.out.errors.truncate(before);
            match found {
                Ok((_, id)) => return Some(id),
                Err(ImplicitMiss::Ambiguous(cands)) => {
                    let shown = match at {
                        Some(sel) => format!("{name}@{sel}"),
                        None => name.to_string(),
                    };
                    if self.reported_identities.insert((self.file_idx, span)) {
                        let text = Self::implicit_ambiguity(name, &cands, Some(&format!("`{name}@{{m}}`")));
                        self.error(span, messages::cmp_carry_ambiguous(&shown, &want, &text));
                    }
                    return None;
                }
                Err(_) => {}
            }
        }
        let mut found: Vec<crate::resolve::FnEntry<'p>> = self
            .overloads_of(name)
            .into_iter()
            .filter(|e| match at {
                None => true,
                Some(sel) => {
                    self.attached_to(e.key, e.decl).as_deref() == Some(sel)
                        || ModulePath::text_matches_suffix(&e.module.to_string(), sel)
                }
            })
            .collect();
        let mut seen: HashSet<DeclId> = HashSet::new();
        found.retain(|e| seen.insert(e.key));
        Some(match found.as_slice() {
            [e] => self.identity_of(e.key, e.decl),
            _ => FnId::Named { name: name.to_string(), at: at.map(str::to_string), module: None, qualify: false },
        })
    }

    /// [cmp-carry] Whether some visible overload of `name` answers to the
    /// selector `at` — a type (`cmp@Person`, an `@`-scoped canonical
    /// [fn-attached]) or a module (`size@core.list` [fn-overload-at]).
    fn fn_exists_at(&self, name: &str, at: &str) -> bool {
        self.overloads_of(name).iter().any(|e| {
            self.attached_to(e.key, e.decl).as_deref() == Some(at)
                || ModulePath::text_matches_suffix(&e.module.to_string(), at)
        })
    }

    fn lower_qual_plain(
        &mut self,
        q: &TypeRef,
        subst: &HashMap<String, Ty>,
        depth: usize,
    ) -> Qual {
        let one = std::slice::from_ref(q);
        self.lower_quals_plain(one, subst, depth).remove(0)
    }

    fn lower_quals_plain(
        &mut self,
        qualifiers: &[TypeRef],
        subst: &HashMap<String, Ty>,
        depth: usize,
    ) -> Vec<Qual> {
        let kept: Vec<&TypeRef> = qualifiers.iter().filter(|q| !self.is_route_key(q)).collect();
        kept.into_iter()
            // [proj-type] `proj` is part of the lowered type (user decision
            // 2026-09-12): `proj Str` and `Str` are different types, ordered
            // `Str <: proj Str`, so a borrow inside a union arm or a container
            // is visible wherever the value flows. Its `[from: p]` is not: the
            // source is a fact about the value, carried by fate links.
            .map(|q| {
                // [lsp-definition] qualifier name -> its declaration, but only
                // a **user** qualifier has one: a built-in auto-qualifier
                // (`Mut`, `once`) is a language keyword with no declaration to
                // jump to, and recording a ref for it made hover resolve `Mut`
                // to an arbitrary `canbe Mut` type (e.g. `Set`) [lsp-definition].
                self.record_qualifier_def(q);
                Qual {
                    // [fn-effects] A name in qualifier position that
                    // resolves to an *effect* is an effect claim on a
                    // producer, not a qualifier: same spelling, different
                    // rules (inverted variance, never dropped, never
                    // tested). Qualifier and effect names cannot collide
                    // [mod-collision], so the lookup decides.
                    effect: {
                        let m = self.named(q);
                        !m.is_qualifier() && m.effect.is_some()
                    },
                    name: q.name.name.clone(),
                    args: q
                        .args
                        .iter()
                        .map(|a| self.lower_type_subst(a, subst, depth))
                        .chain(q.value_args.iter().filter_map(|a| {
                            // [qual-depend] A place in the value block lowers
                            // to a root-free template here — an annotation or
                            // signature names the dependency; the roots are
                            // bound where the claim attaches to a value in
                            // flow (an `is` test, a mint).
                            match a {
                                ast::Type::Named { qualifiers, base }
                                    if qualifiers.is_empty() && !base.binder =>
                                {
                                    // [qual-const] A digit-, char- or
                                    // string-named ref is the parser's
                                    // constant encoding.
                                    match crate::types::Const::parse(&base.name.name) {
                                        Some(c) => Some(Ty::Const(c)),
                                        None => Some(Ty::ValueRef {
                                            path: base.name.name.clone(),
                                            roots: Vec::new(),
                                        }),
                                    }
                                }
                                _ => None,
                            }
                        }))
                        .collect(),
                }
            })
            .collect()
    }

    /// [actor-route-stub] Whether `q` is std `net`'s `Key` — the routing marker on a
    /// protocol parameter. It is recorded at the effect (`route_keys`, for the
    /// route the IR derives) and **erased here**, so the parameter's type is the plain one and a
    /// caller passes a plain value: `Key` claims nothing about the value, it
    /// says which argument decides the member.
    fn is_route_key(&self, q: &TypeRef) -> bool {
        q.name.name == ROUTE_KEY_QUALIFIER
            && self
                .scope
                .name_origins
                .get(q.name.name.as_str())
                .is_some_and(|ms| ms.iter().any(|m| m.std_rest().and_then(|r| r.first()).is_some_and(|s| s == "net")))
    }

    /// Lowers the base of a named type: substitutions, generic parameters,
    /// alias expansion, plain nominals.
    fn lower_base_ref(&mut self, base: &TypeRef, subst: &HashMap<String, Ty>, depth: usize) -> Ty {
        // [mod-namespace] A leading-dot arm inside a `type` alias's own
        // union-arm list (`.Int` inside `namespace Arg { type Type = .Int |
        // .Str }`) resolves against the alias's own enclosing namespace —
        // there is no outer expected type here, only the declaration naming
        // itself (user decision 2026-10-19). Resolved to the real name up
        // front, as a owned string standing in for `base.name.name` through
        // the rest of this fn, so alias expansion, struct lookup and the
        // def-ref below all run on it exactly as they would for a fully
        // written name.
        let resolved_dot: Option<String> = if base.name.name.starts_with('.') {
            match self.own_alias_namespace.clone() {
                Some(ns) => match self.resolve_alias_arm_dot_ref(&base.name.name, &ns) {
                    Ok(full) => Some(full),
                    Err(msg) => {
                        self.error(base.name.span, msg);
                        return Ty::Unknown;
                    }
                },
                None => None,
            }
        } else {
            None
        };
        let name = resolved_dot.as_deref().unwrap_or(base.name.name.as_str());
        // [type-identity] [name-table] A written name means what it means in
        // the file that wrote it, which is not this one when a callee's
        // signature or a struct's field is lowered at a use: resolution bound
        // it there. A leading-dot arm's full name is looked up where the
        // arm is written.
        let meaning = match &resolved_dot {
            Some(full) => std::borrow::Cow::Owned(crate::names::Meaning::of(self.scope_of(base), full)),
            None => self.named(base),
        };
        if base.args.is_empty() {
            if let Some(bound) = subst.get(name) {
                return bound.clone();
            }
            if self.generics.contains(name) {
                return Ty::Var(name.to_string());
            }
        }
        // The written name points at its declaration [lsp-definition] —
        // recorded before alias expansion, so an alias use jumps to the
        // alias itself rather than its target.
        let name_span = base.name.span;
        if !self.foreign_ref(base) {
            if let Some(site) = meaning.def {
                self.out.def_refs.insert(self.key(name_span), site);
            }
        }
        // [generic-arity] A generic struct, opaque type, or alias referenced
        // in a type position must supply every type argument it declares —
        // unlike a struct *literal* (`Box { value: 7 }`), which may infer
        // `T` from its field values [struct-literal-arg], a bare type-
        // position reference (a field declaration, a parameter, a return
        // type) has no values to infer from, so an omitted argument has
        // nothing to resolve it from either. Without this check it silently
        // bound to `Ty::Unknown` and rode [type-unknown-lenient] for every
        // later use — accepting any read through the field with no checking
        // at all, found 2026-10-19 via a bare `List<Arg>` where `Arg<T>`
        // dropped its own argument. Checked once here, before alias
        // expansion and the fn-identity-slot branch below (which runs its
        // own, different all-or-none arity rule for `?cmp`-style arguments
        // [qual-value-arg] and would otherwise double-report).
        let declared_generics = meaning.declared_generics().map(|gs| gs.len());
        if let Some(expected) = declared_generics {
            // [effect-eff-handle] `eff[A, B, …]` parses straight to this same
            // `Addr` name with one argument per effect — a legitimate
            // multi-effect handle, not an under/over-supplied generic
            // argument list on the single-generic `intrinsic type Addr<E>`
            // declaration. Exempt here the same way a struct literal's
            // written type is exempt: `Addr`'s own arity is governed by
            // [effect-eff-handle], not this check.
            if expected > 0 && base.args.len() != expected && !self.in_struct_lit_ty && name != ADDR_TYPE {
                self.error(
                    base.span,
                    messages::qual_value_arg_type_arg_count(&name, &expected, &base.args.len()),
                );
            }
        }
        // [proj-type-arg] A `proj` type argument makes a *container of
        // borrows* (`List<proj T>` is a view, `Vec<&T>`). That is only
        // meaningful for the intrinsic containers the backends render that
        // way; on a user struct it would smuggle a borrow into a field
        // through the back door of generics, unseen by [proj-infer]'s
        // field-driven inference.
        if !matches!(name, "List") && meaning.structure.is_some() {
            for arg in &base.args {
                if let Some(span) = first_proj_span(arg) {
                    self.error(span, messages::proj_infer_struct_type_arg(&name));
                }
            }
        }
        // [type-any-never] The written `Never` *is* the bottom type,
        // not a nominal type that happens to be called that: `throw`
        // declares `-> [] Never` and its callers must see a value that
        // fits everywhere and ends the path.
        if name == "Never" && base.args.is_empty() {
            return Ty::Never;
        }
        // [type-any-never] And the written `Any` *is* the top type, for the
        // same reason: a parameter declared `Any` accepts every value, and
        // overload ranking treats it as the broadest thing a parameter can
        // say [fn-overload-rank]. As a nominal `Named("Any")` it accepted
        // nothing at all, since unification compares names.
        if name == "Any" && base.args.is_empty() {
            return Ty::Any;
        }
        // [group-not-a-value] A `fns` group is not a type; the refusal is
        // `reject_group_as_data`'s (validation), and the *lowering* is
        // `Unknown` so the one mistake does not cascade into type-mismatch
        // errors at every use of the annotated value [type-unknown-lenient].
        if name != "None" && !meaning.is_type() && meaning.group.is_some() {
            return Ty::Unknown;
        }
        // [effect-eff-handle] [effect-alias] An alias among an `eff[…]` handle's
        // effects stands for its members, flattened and deduped in order:
        // `eff[IO]` is `eff[Console, Fs, Streams]`.
        let alias_arg = |c: &Self, a: &ast::Type| match a {
            ast::Type::Named { qualifiers, base: b } => {
                qualifiers.is_empty() && c.named(b).effect_alias.is_some()
            }
            _ => false,
        };
        if name == ADDR_TYPE && base.args.iter().any(|a| alias_arg(self, a)) {
            let mut listed: Vec<ListedEffect> = Vec::new();
            for a in &base.args {
                match a {
                    ast::Type::Named { base: b, .. } if alias_arg(self, a) => {
                        self.expand_effect_entry(b, false, b.span, EffectOrigin::Alias(b.name.name.clone()), &mut Vec::new(), &mut listed);
                    }
                    other => {
                        let ty = self.lower_type_subst(other, subst, depth);
                        if !listed.iter().any(|e| e.ty == ty) {
                            listed.push(ListedEffect { ty, any: false, span: other.span(), origin: EffectOrigin::Written });
                        }
                    }
                }
            }
            let args: Vec<Ty> = listed.into_iter().map(|e| e.ty).collect();
            if args.len() > 1 {
                return Ty::Tuple(args.into_iter().map(|a| Ty::Named { name: ADDR_TYPE.to_string(), args: vec![a] }).collect());
            }
            return Ty::Named { name: ADDR_TYPE.to_string(), args };
        }
        let args: Vec<Ty> = {
            // [cmp-carry] A keyed container names the ordering (or hash) its
            // keys are kept by in a **fn slot** after its type parameters:
            // `SortedSet<Str>(my_cmp)`. The leading arguments are types as
            // ever; the trailing ones are identities, and a slot nobody wrote
            // takes its declared default (`?cmp: (T, T) -> Int = cmp`).
            let key = meaning.key(self.symbols).unwrap_or(name).to_string();
            let slots = self.type_fn_slots(&key);
            if slots.is_empty() {
                base.args
                    .iter()
                    .map(|a| self.lower_type_subst(a, subst, depth))
                    .collect()
            } else {
                let generics: Vec<String> = meaning
                    .opaque
                    .map(|d| &d.generics)
                    .or_else(|| meaning.structure.map(|d| &d.generics))
                    .map(|gs| gs.iter().map(|g| g.name.clone()).collect())
                    .unwrap_or_default();
                let arity = generics.len();
                self.lower_identity_args(&base.args, &base.value_args, Some(arity), &generics, &slots, subst, depth)
            }
        };
        // Type aliases expand structurally (with generic substitution).
        if let Some(alias) = meaning.alias {
            if let Some(target) = &alias.alias {
                let mut alias_subst = HashMap::new();
                for (g, arg) in alias.generics.iter().zip(&args) {
                    alias_subst.insert(g.name.clone(), arg.clone());
                }
                // [mod-namespace] A leading-dot arm in the alias's own body
                // (`.Int` inside `namespace Arg { type Type = .Int | .Str
                // }`) resolves against *this* alias's own enclosing
                // namespace — set here, at the one place the alias's target
                // is actually expanded, so it is correct regardless of
                // which use site triggered the expansion (a use's own
                // namespace context must never leak into the alias body's
                // resolution; user decision 2026-10-19). Saved/restored
                // around the recursive lowering, since an alias may itself
                // reference another alias in a different namespace.
                let saved_ns = self.own_alias_namespace.take();
                self.own_alias_namespace = alias.name.name.rsplit_once('.').map(|(ns, _)| ns.to_string());
                // The declaration's own node, not a copy: its references are
                // resolved in the alias's file [type-identity].
                let lowered = self.lower_type_subst(target, &alias_subst, depth + 1);
                self.own_alias_namespace = saved_ns;
                return lowered;
            }
        }
        // [effect-eff-handle] A multi-effect handle `eff[A, B, …]` *is* a tuple of
        // single-effect handles — `(eff[A], eff[B], …)` — in the type system
        // and the IR alike: each element is an ordinary single handle with a
        // real backend representation, so there is no flat multi-face handle
        // to represent. A single-effect handle stays the `Addr`-named marker
        // (it carries the plain-vs-actor distinction the emitters read).
        if name == ADDR_TYPE && args.len() > 1 {
            return Ty::Tuple(
                args.into_iter()
                    .map(|a| Ty::Named { name: ADDR_TYPE.to_string(), args: vec![a] })
                    .collect(),
            );
        }
        Ty::Named {
            name: meaning.key(self.symbols).unwrap_or(name).to_string(),
            args,
        }
    }

    /// [type-identity] The key of the type a *written* name means in this
    /// file: the declaration the file's scope resolves it to (through an
    /// import alias too), or the name itself when it names no declaration
    /// (a generic, a builtin the scope does not list).
    /// [type-identity] The scope of the file that wrote [r]; this file's for
    /// a reference the checker made up.
    fn scope_of(&self, r: &TypeRef) -> &'r ModuleScope<'p> {
        // [comptime-hygiene] Inside a stamped body, its stamp scope.
        match self.resolution.names.written(r) {
            Some(w) => self.resolution.scope_at(w.at),
            None => self.scope,
        }
    }

    fn type_key(&self, name: &str) -> String {
        Self::key_in(self.symbols, self.scope, name)
    }

    fn key_in(symbols: &Symbols<'p>, scope: &ModuleScope<'p>, name: &str) -> String {
        Self::written_key(symbols, scope, name).unwrap_or(name).to_string()
    }

    fn written_key(symbols: &Symbols<'p>, scope: &ModuleScope<'p>, name: &str) -> Option<&'p str> {
        crate::resolve::key_in(symbols, scope, name)
    }


    /// Builds a union, recording the wrapper size when one is needed.
    fn mk_union(&mut self, arms: Vec<Ty>) -> Ty {
        let ty = Ty::union_of(arms);
        ty
    }

    // ================= name resolution =================

    /// Whether `name` is usable as a written *type* name [name-resolve]:
    /// a struct, an `intrinsic type`, a type alias, an effect
    /// (effect lists are written as types), or the language-level `None`
    /// (which has no declaration). Generic parameters are resolved by the
    /// caller, before this is consulted.
    fn type_name_exists(&self, name: &str) -> bool {
        name == "None"
            || self.scope.structs.contains_key(name)
            || self.scope.opaque_types.contains_key(name)
            || self.scope.type_aliases.contains_key(name)
            || self.scope.effects.contains_key(name)
    }

    /// Whether `name` is usable as a written *qualifier* name
    /// [name-resolve]: a declared qualifier, or one of the compiler's
    /// intrinsic ones (which have no declaration to find — their
    /// position-specific rules are enforced by `validate_quals`).
    fn qual_name_exists(&self, name: &str) -> bool {
        is_intrinsic_qualifier(name)
            || self.scope.is_qualifier(name)
            // [fn-effects] An effect claims what driving a producer
            // performs, and it is written where a qualifier goes. Where it
            // may be written is `validate_quals`' business; that it *is* a
            // name in this position is settled here.
            || self.scope.effects.contains_key(name)
    }

    /// [mod-namespace] Resolve a leading-dot sugar reference (`.S`, whose written
    /// name is `.S` — see the parser) against the namespaces the `expected`
    /// type exposes (D3/D4). Returns the full namespaced name (`AttributeValue.S`)
    /// when exactly one exposed namespace has a type-like member of that name,
    /// `Err(reason)` otherwise. The alias's own name is irrelevant: resolution
    /// is driven by the expected type's *shape*.
    ///
    /// Namespaces exposed by `expected`:
    /// * a **union** exposes the namespace of each arm whose type is dotted
    ///   (`NS1.T | NS2.K` exposes `{NS1, NS2}`);
    /// * a **single namespaced type** `Foo.Bar` exposes `Foo` — a sibling
    ///   lookup, `.Baz` → `Foo.Baz`, last segment replaced (D4a).
    fn resolve_dot_ref(&self, written: &str, expected: Option<&Ty>) -> Result<(String, Option<Ty>), Message> {
        // `written` is a leading-dot *suffix* of a namespaced name: `.Thing`,
        // `.C.Thing`, `.B.C.Thing` … The suffix is everything after the
        // leading dot. A candidate full name matches when it equals the suffix
        // or ends with `.suffix` — i.e. the suffix lines up on a segment
        // boundary (user refinement 2026-10-16).
        let suffix = written.trim_start_matches('.');
        let matches_suffix = |full: &str| full == suffix || full.ends_with(&format!(".{suffix}"));
        let Some(expected) = expected else {
            return Err(messages::mod_namespace_no_expected_type(&written));
        };
        match expected.strip_quals() {
            // A union resolves against its **arms** directly: the arm whose
            // dotted type ends with the suffix. The arm's own `Ty` is returned
            // so the check matches the arm regardless of how (or whether) its
            // type is nameable here — the sugar's point is that the namespace
            // is left unwritten (D4).
            Ty::Union(arms) => {
                let mut hits: Vec<(String, Ty)> = Vec::new();
                for arm in arms {
                    if let Ty::Named { name, .. } = arm.strip_quals() {
                        let base = self.base_name(name);
                        if matches_suffix(&base) && !hits.iter().any(|(n, _)| n == &base) {
                            hits.push((base, arm.clone()));
                        }
                    }
                }
                match hits.as_slice() {
                    [(name, ty)] => Ok((name.clone(), Some(ty.clone()))),
                    [] => Err(messages::mod_namespace_no_arm(&written, &expected, &arm_names(arms))),
                    many => Err(messages::mod_namespace_ambiguous_arms(
                        &written,
                        &expected,
                        &many.iter().map(|(m, _)| format!("`{m}`")).collect::<Vec<_>>().join(" or "),
                    )),
                }
            }
            // A single namespaced type `A.B.Bar` resolves a suffix against the
            // names reachable in its ancestor namespaces: for each ancestor
            // prefix `P` of the expected type's path (`A.B`, `A`), a candidate
            // `P.suffix` — so `.Bar` is a sibling (`A.B.Bar`), `.B.X` reaches
            // `A.B.X`, and the full `A.B.C.Thing` is accepted. The unique
            // declared one wins (D4a, generalized to suffixes).
            Ty::Named { name, .. } => {
                let base = self.base_name(name);
                if matches_suffix(&base)
                    && (self.type_name_exists(&base) || self.qual_name_exists(&base))
                {
                    return Ok((base.clone(), None));
                }
                let mut hits: Vec<String> = Vec::new();
                let mut rest = base.as_str();
                while let Some((prefix, _)) = rest.rsplit_once('.') {
                    let cand = format!("{prefix}.{suffix}");
                    if (self.type_name_exists(&cand) || self.qual_name_exists(&cand))
                        && !hits.contains(&cand)
                    {
                        hits.push(cand);
                    }
                    rest = prefix;
                }
                match hits.as_slice() {
                    [one] => Ok((one.clone(), None)),
                    [] => Err(messages::mod_namespace_no_member(&written, &expected)),
                    many => Err(messages::mod_namespace_ambiguous(
                        &written,
                        &many.iter().map(|m| format!("`{m}`")).collect::<Vec<_>>().join(" or "),
                    )),
                }
            }
            _ => Err(messages::mod_namespace_not_namespaced(&written, &expected)),
        }
    }

    /// [mod-namespace] Resolves a leading-dot sugar reference (`.Int`) written
    /// inside a `type` alias's own union-arm list, against the alias's own
    /// enclosing namespace `ns` directly — the counterpart to
    /// `resolve_dot_ref` for the one case that has no outer expected type to
    /// derive a namespace from (user decision 2026-10-19): `.Int` inside
    /// `namespace Arg { type Type = .Int | .Str }` means the unique declared
    /// `Arg.Int`. Only `ns` itself is searched — not its ancestors — since an
    /// alias's own namespace is exact, not a path to walk upward from.
    fn resolve_alias_arm_dot_ref(&self, written: &str, ns: &str) -> Result<String, Message> {
        let suffix = written.trim_start_matches('.');
        let cand = format!("{ns}.{suffix}");
        if self.type_name_exists(&cand) || self.qual_name_exists(&cand) {
            Ok(cand)
        } else {
            Err(messages::mod_namespace_no_alias_member(&written, &ns, &suffix))
        }
    }

    /// The base name of a type key, module key (`§…`) stripped, for namespace
    /// comparison.
    fn base_name(&self, name: &str) -> String {
        name.split('§').next().unwrap_or(name).to_string()
    }

    /// Reports a written name in a type position that resolves to nothing
    /// visible [name-resolve]. `expect_qual` picks the wording and the
    /// namespace searched.
    fn require_name(&mut self, r: &TypeRef, expect_qual: bool) {
        // [mod-namespace] A leading-dot arm inside a `type` alias's own
        // union-arm list (`.Int` inside `namespace Arg { type Type = .Int |
        // .Str }`) resolves against the alias's own enclosing namespace —
        // the one case with no outer expected type to derive a namespace
        // from, so it is checked here rather than through
        // `resolve_dot_ref`'s `expected`-type mechanism (user decision
        // 2026-10-19). `!expect_qual` since a namespace member is a type,
        // never a qualifier, by construction.
        if !expect_qual && r.name.name.starts_with('.') {
            if let Some(ns) = self.own_alias_namespace.clone() {
                if let Err(msg) = self.resolve_alias_arm_dot_ref(&r.name.name, &ns) {
                    self.error(r.span, msg);
                }
                return;
            }
        }
        let name = r.name.name.as_str();
        if self.names_generic(r) {
            return;
        }
        // [name-table] What the name means where it is written.
        let meaning = self.named(r);
        let known = if expect_qual {
            names_qualifier(name, &meaning)
        } else {
            names_type(name, &meaning)
        };
        if known {
            return;
        }
        // A `fns` group in type position is a *position* mistake with its
        // own diagnostic [group-not-a-value] (`reject_group_as_data`); an
        // "unknown type" here would be a second report of the same error.
        if !expect_qual && meaning.group.is_some() {
            return;
        }
        let what = if expect_qual { "qualifier" } else { "type" };
        // A name that exists in the *other* namespace is a position
        // mistake, not a missing declaration: say so instead of
        // suggesting an import that would not help.
        let hint = if expect_qual && names_type(name, &meaning) {
            format!(" (`{name}` is a type, not a qualifier)")
        } else if !expect_qual && names_qualifier(name, &meaning) {
            format!(" (`{name}` is a qualifier, not a type)")
        } else {
            String::new()
        };
        let name = name.to_string();
        self.error_unresolved(
            r.span,
            messages::name_resolve_unknown_type(&what, &name, &hint),
            &name,
        );
    }

    /// [effect-handler-deps] The effects a handler declares as dependencies
    /// (`handler Stamped [Logger, Clock] of Logger`), lowered and validated:
    /// they are supplied by the compiler at the `use` site, so the list is
    /// unnamed and every entry must be an effect a `use` could provide.
    /// `use` and `Throw` are refused — a handler registers nothing, and a
    /// throw needs a delimiter rather than a handler [throw].
    fn handler_dep_effects(&mut self, h: &'p ast::HandlerDecl) -> Vec<EffectAvail> {
        self.handler_dep_list(h)
            .into_iter()
            .map(|e| EffectAvail { ty: e.ty, declared: true, any: e.any })
            .collect()
    }

    /// [effect-handler-deps] [effect-prereq] A handler's dependencies as the
    /// program means them, with where each came from.
    fn handler_dep_list(&mut self, h: &'p ast::HandlerDecl) -> Vec<ListedEffect> {
        // [effect-handler-deps] The list is written in the handler's own file
        // and names what *that* file can see, so it is lowered in that file's
        // scope — a `use` in a module that never imports the dependency
        // resolved it against the wrong scope before (found 2026-09-29 with
        // [effect-prereq], whose implied dependencies are never imported at a
        // use site). Diagnostics about the list itself belong to the
        // handler's file, which reports them when it is checked; lowering
        // under another file's name drops them rather than misfiling them.
        // [node-file] The handler's file is its name's.
        let own = self.resolution.decls.file_of(h.name.span);
        if let Some(own) = own.filter(|f| *f != self.file_idx) {
            let saved_scope = self.scope;
            let saved_errors = self.out.errors.len();
            self.scope = &self.resolution.scopes[own];
            let out = self.handler_dep_list_here(h);
            self.scope = saved_scope;
            self.out.errors.truncate(saved_errors);
            return out;
        }
        self.handler_dep_list_here(h)
    }

    fn handler_dep_list_here(&mut self, h: &'p ast::HandlerDecl) -> Vec<ListedEffect> {
        let mut out: Vec<ListedEffect> = Vec::new();
        for eff in h.effects.iter().flatten() {
            let (r, any) = match eff {
                EffectRef::Use(span) => {
                    self.error(*span, messages::effect_handler_deps_use(&h.name.name));
                    continue;
                }
                // [actor-spawn-effect] A handler *may* depend on `spawn` — a
                // supervisor spawns and re-spawns its children. It names no
                // effect type, so there is nothing to lower here; the gate
                // arrives with the `spawn` expression.
                EffectRef::Spawn(_) => continue,
                EffectRef::Effect(r) => (r, false),
                // [effect-any] A dependency on `any E`: the handler assumes
                // no order between its sends, so a router may be bound for it.
                EffectRef::AnyEffect(r) => (r, true),
            };
            if r.name.name == THROW_EFFECT {
                self.error(
                    r.span,
                    messages::effect_handler_deps_throw(&h.name.name, &THROW_EFFECT),
                );
                continue;
            }
            // [effect-alias] An alias entry stands for its members; a
            // handler's written dependencies are not prerequisite-expanded
            // (the handler of each supplies its own).
            for e in self.expand_effect_refs(std::slice::from_ref(eff), false) {
                if out.iter().any(|a| a.ty == e.ty) {
                    if e.origin == EffectOrigin::Written {
                        self.error(
                            r.span,
                            messages::effect_handler_deps_duplicate(&h.name.name, &e.ty),
                        );
                    }
                    continue;
                }
                out.push(ListedEffect { any: any || e.any, ..e });
            }
        }
        // [effect-prereq] A handler of an effect with prerequisites reaches
        // them as dependencies — unless it implements one itself (`of Fs,
        // Streams`). Not a platform or intrinsic handler: the host constructs
        // those and has nothing to pass them.
        if !h.platform && !h.intrinsic {
            let faces: Vec<(Ty, Span)> = h.of.iter().map(|t| (self.lower_type(t), t.span())).collect();
            let mut implied: Vec<ListedEffect> = faces
                .iter()
                .map(|(ty, span)| ListedEffect { ty: ty.clone(), any: false, span: *span, origin: EffectOrigin::Written })
                .collect();
            self.add_prerequisites(&mut implied);
            for e in implied.into_iter().filter(|e| e.origin != EffectOrigin::Written) {
                if faces.iter().any(|(f, _)| *f == e.ty) || out.iter().any(|a| a.ty == e.ty) {
                    continue;
                }
                out.push(e);
            }
        }
        out
    }

    // ================= qualifier validation =================

    /// [effect-not-data] An effect names a *capability*, not a type of
    /// values: it may appear in a fn's effect list, in a handler's effect
    /// list and its `of` clause, and nowhere else. Using one as a struct
    /// field, parameter, return, or `let` annotation is an error — the value
    /// would have to be a handler instance, which only `use` produces, and
    /// neither backend can render it (Rust emits a bare trait, `E0782`).
    ///
    /// **One exception, sanctioned by decision** (user, 2026-09-15):
    /// `Addr<E>`'s type argument [actor-spawn-expr]. An addr is a handle to a
    /// actor, and what a holder may *do* with it is exactly the effect the
    /// actor serves — so the effect is what parameterizes the handle, and
    /// that is what makes an actor and a locally `use`d handler
    /// interchangeable behind one name. The exception is one type argument of
    /// one std type; an addr is still not a handler instance, and every other
    /// data position stays refused (checked in `validate_type`, which knows
    /// the enclosing type).
    /// [actor-spawn-expr] Whether this type argument is the effect argument
    /// of an `Addr` — the one place an effect names something in a type
    /// position. Deliberately narrow: the enclosing base must be std's
    /// `Addr`, the position must be its only type parameter, and the argument
    /// must be a bare name that a visible effect declares. Anything else
    /// (`Addr<Int>`, a second argument, an effect elsewhere) goes down the
    /// ordinary path and is validated — or refused — as before.
    /// [actor-effect-kind] The binding gate: `spawn` and `use addr` are the two
    /// ways an actor is reached, and both need an `actor effect`. This is what
    /// closes the design's carried named question — "may an ordinary member be
    /// actor-backed?" — as *forbid*, with the actor kind as the sanctioned
    /// spelling (user decision 2026-09-15).
    fn require_actor_effect(&mut self, effect: &Ty, span: Span, form: &str) {
        let Ty::Named { name, .. } = effect.strip_quals() else {
            return;
        };
        let name = name.clone();
        let Some(decl) = self.symbols.effects.get(name.as_str()).copied() else {
            return;
        };
        if decl.is_actor {
            return;
        }
        self.error(span, messages::actor_effect_kind_plain_effect_actor(&form, &name));
    }

    /// [actor-effect-kind] [actor-monitor-handler] The kind gate on an `Addr`'s
    /// argument, since SH-3 an *acceptance* of both kinds: an `Addr` of an
    /// actor effect is a mailbox handle (a spawn produced it), and an `Addr`
    /// of a **plain** effect is a shared monitor's handle (a monitor spawn
    /// produced it) — one type, two backing shapes, chosen by the effect's
    /// declared kind. What remains refused here is only an argument that is
    /// not an effect at all, which the general argument checks report.
    /// [actor-effect-kind] [actor-monitor-handler] Naming `Addr<E>` accepts both
    /// effect kinds since SH-3 (user decision 2026-09-19): an actor effect's
    /// addr is a mailbox handle, and a plain effect's is a shared monitor's
    /// handle. The former per-kind refusal lived here; the walk above now
    /// documents the acceptance at the one call site it had.
    fn is_addr_effect_arg(&self, base: &TypeRef, index: usize, arg: &ast::Type) -> bool {
        // [effect-eff-handle] Any argument of an `eff[…]` handle is an effect, not
        // just the first: `eff[A, B]` names several (it lowers to a tuple of
        // single handles). The former single-arg `Addr<E>` restriction is
        // widened to every arg.
        if base.name.name != ADDR_TYPE || base.args.is_empty() {
            return false;
        }
        let _ = index;
        // Std's `Addr`, not a program's own type of that name.
        if !self.scope.opaque_types.contains_key(ADDR_TYPE) {
            return false;
        }
        match arg {
            // [effect-generic-decl] A generic effect's instance is an effect
            // too (`Addr<ActorGroup<Counter>>`): its arguments are checked as
            // the effect's own generics are, which the general walk does.
            // [effect-alias] An alias of effects is effects too: `eff[IO]`.
            ast::Type::Named { qualifiers, base } => {
                qualifiers.is_empty()
                    && {
                        let m = self.named(base);
                        m.effect.is_some() || m.effect_alias.is_some()
                    }
            }
            _ => false,
        }
    }

    fn reject_effect_as_data(&mut self, r: &TypeRef) {
        let name = r.name.name.as_str();
        if self.names_generic(r) || self.named(r).effect.is_none() {
            return;
        }
        let name = name.to_string();
        self.error(r.span, messages::effect_not_data_data_position(&name));
    }

    /// [group-not-a-value] A `fns` group names an *obligation*, not a
    /// type of values: no value may ever have a group as its type. This is
    /// the single restriction that keeps the mechanism a where-clause
    /// rather than a trait — there is no `dyn`, no erasure, no interface
    /// value; a group constrains a *named* type and is resolved statically
    /// (user decision 2026-09-08). A rule in its own right, not a
    /// consequence of one.
    /// [comptime-fields] `std.core.comptime`'s types (`Type`, `Field`, `Struct`,
    /// …) exist at compile time only: what a `comptime fn` may know about a
    /// type, never a value a program holds. Naming one in an ordinary type
    /// position is refused where it is written; a `comptime struct`'s own
    /// fields are exempt, since that is where the model is declared.
    fn reject_comptime_as_data(&mut self, base: &TypeRef) {
        if self.in_comptime_decl {
            return;
        }
        let name = base.name.name.as_str();
        let meaning = self.named(base);
        let is_comptime = meaning.structure.is_some_and(|s| s.comptime) || meaning.alias.is_some_and(|t| t.comptime);
        if is_comptime {
            self.error(base.span, messages::comptime_fields_data_position(&name));
        }
    }

    fn reject_group_as_data(&mut self, r: &TypeRef) {
        let name = r.name.name.as_str();
        let meaning = self.named(r);
        if self.names_generic(r) || names_type(name, &meaning) || meaning.group.is_none() {
            return;
        }
        let name = name.to_string();
        self.error(r.span, messages::group_not_a_value_data_position(&name));
    }

    /// Validates a written type: every name resolves [name-resolve], and
    /// every qualifier application is well formed — duplicates,
    /// `of`-type applicability, pairwise `with` compatibility. Called at
    /// declaration sites (fn signatures, `let` annotations, struct
    /// fields, ...) so each error is reported once; type *lowering* runs
    /// repeatedly and stays silent.
    /// [linear-composite] Whether a written type puts `var`-typed values
    /// *inside* a composite: a type argument, an array element, a tuple
    /// component or a union arm. Std's
    /// `add(list: Mut List<T>, elem: T)` is the shape that matters — a
    /// call instantiating such a `T` with a linear type **is** the store,
    /// so it is refused at the call site whatever the callee's
    /// `<T canbe linear>` claims. A bare `T` (or a qualified one, `T as
    /// Ok`) is a value passed along, not stored, and stays legal.
    fn var_in_composite(&self, ty: &ast::Type, var: &str) -> bool {
        let inside =
            |c: &ast::Type| Self::type_mentions_var(c, var) || self.var_in_composite(c, var);
        match ty {
            ast::Type::Literal { .. } => false,
            // [linear-container] A type argument to a *conditional
            // container's* opted-in parameter is not a refused store (user
            // decision 2026-09-12, extended to opaque containers like `List`
            // 2026-09-16): the container carries the obligation itself
            // (`take(source, 2)` building a `Take<It>`, `add(waiting, out)`
            // filling a `Mut List<Reply<Str>>`), and its terminal is checked
            // where the container is.
            ast::Type::Named { base, .. } => {
                let opted = self.linear_opt_in_positions(&self.written_key_of(base));
                base.args
                    .iter()
                    .enumerate()
                    .any(|(i, a)| !opted.contains(&i) && inside(a))
            }
            ast::Type::QualifiedGroup { base, .. } => self.var_in_composite(base, var),
            ast::Type::Array { elem, .. } => inside(elem),
            ast::Type::Tuple { elems, .. } => elems.iter().any(|e| inside(e)),
            // [linear-union-arm] A union — and `T?`, which is one — is **not**
            // a composite (O-C2): the value *is* the value, so an arm carries
            // the obligation and narrowing settles it. That is what makes
            // every take-by-move answer (`remove_first(list) -> T?`,
            // `replace(map, k, v) -> V?`) a legal signature rather than a
            // store: the obligation comes back out through it.
            ast::Type::Union { .. } | ast::Type::Nullable { .. } => false,
            // A fn type neither owns nor stores what it is handed.
            ast::Type::Fn { .. } => false,
            // [type-union-spread] A `...T` arm is a top-level union-arm position,
            // not a composite that stores the variable.
            ast::Type::Spread { .. } => false,
        }
    }

    /// Whether a written type is the bare type variable `var` — possibly
    /// qualified (`T as Ok`), which is still the value itself and not a
    /// container of it.
    fn type_is_bare_var(ty: &ast::Type, var: &str) -> bool {
        match ty {
            ast::Type::Named { base, .. } => base.name.name == var && base.args.is_empty(),
            ast::Type::QualifiedGroup { base, .. } => Self::type_is_bare_var(base, var),
            _ => false,
        }
    }

    /// Whether a written type mentions the type variable `var` anywhere.
    fn type_mentions_var(ty: &ast::Type, var: &str) -> bool {
        match ty {
            ast::Type::Literal { .. } => false,
            ast::Type::Named { base, .. } => {
                base.name.name == var || base.args.iter().any(|a| Self::type_mentions_var(a, var))
            }
            ast::Type::QualifiedGroup { base, .. } => Self::type_mentions_var(base, var),
            ast::Type::Array { elem, .. } => Self::type_mentions_var(elem, var),
            ast::Type::Tuple { elems, .. } => elems.iter().any(|e| Self::type_mentions_var(e, var)),
            ast::Type::Union { arms, .. } => arms.iter().any(|a| Self::type_mentions_var(a, var)),
            ast::Type::Nullable { inner, .. } => Self::type_mentions_var(inner, var),
            ast::Type::Spread { inner, .. } => Self::type_mentions_var(inner, var),
            ast::Type::Fn { params, ret, .. } => {
                params.iter().any(|p| Self::type_mentions_var(p, var))
                    || Self::type_mentions_var(ret, var)
            }
        }
    }

    /// [linear-composite] A field may not *hold* a linear value: the
    /// composite's own declaration is where that store is refused, so the
    /// message can name the field. (Composite field *types* —
    /// `xs: List<Lines>` — are refused by `validate_type`; this catches
    /// the bare `h: Lines`.)
    /// [proj-field] A `proj` field is written without a source: the struct
    /// declares *that* it projects, and each literal says *what* — the
    /// source is a property of the value, not the type, and is tracked by
    /// the fate links of whoever holds the struct [proj-infer].
    /// [type-no-cycle] A struct may not **contain itself**: a field whose
    /// type reaches the struct again without indirecting through a container
    /// makes an infinitely large value. Kotlin never noticed (its fields are
    /// references) while Rust failed downstream with a raw E0072 and no Salvo
    /// diagnostic — a [backend-never-wrong] hole, closed here with the
    /// declaration-site error the recursive-types plan owed (2026-09-25).
    ///
    /// Cycle edges are the ones that lay a value out *inline*: a field of
    /// struct type, a tuple element, a union arm, a nullable's inner type, an
    /// alias expansion, and a type argument of a **user** generic (which is
    /// substituted into its fields). Not edges, because each indirects
    /// already: `List<T>`, `Set`/`Map`, an array, a fn type, and a `proj`
    /// field (a borrow — which is how the `List<T>` remedy the diagnostic
    /// names works, and why a pass over a tree is fine).
    fn check_struct_cycle(&mut self, decl: &ast::StructDecl) {
        let start = decl.name.name.as_str();
        // The field whose type closes the cycle, and the path it took.
        let mut culprit: Option<(&ast::FieldDecl, Vec<String>)> = None;
        for field in &decl.fields {
            if culprit.is_some() {
                break;
            }
            let mut seen: Vec<String> = vec![start.to_string()];
            // [handler-state-infer] An inferred field (a generated iterator struct's
            // state) names no written type to trace a cycle through — its
            // inferred type is concrete data, never a self-reference.
            let Some(written) = &field.ty else { continue };
            if self.type_reaches(written, start, &mut seen, 0) {
                culprit = Some((field, seen));
            }
        }
        let Some((field, path)) = culprit else { return };
        let via = if path.len() > 1 {
            format!(" (through {})", path[1..].join(" → "))
        } else {
            String::new()
        };
        self.error(
            field.name.span,
            messages::type_no_cycle_contains_itself(&start, &field.name.name, &via),
        );
    }

    /// [type-no-cycle] Whether `ty` reaches the struct named `target` through
    /// inline edges only. `seen` carries the path for the diagnostic and stops
    /// the walk from looping on an unrelated cycle; `depth` is a guard against
    /// a pathological alias chain.
    fn type_reaches(
        &self,
        ty: &ast::Type,
        target: &str,
        seen: &mut Vec<String>,
        depth: usize,
    ) -> bool {
        if depth > 64 {
            return false;
        }
        match ty {
            ast::Type::Literal { .. } => false,
            // An array indirects (`Vec<T>`), so it is not a cycle edge.
            ast::Type::Array { .. } => false,
            ast::Type::Fn { .. } => false,
            ast::Type::Nullable { inner, .. } => {
                self.type_reaches(inner, target, seen, depth + 1)
            }
            ast::Type::Spread { inner, .. } => {
                self.type_reaches(inner, target, seen, depth + 1)
            }
            ast::Type::Union { arms, .. } | ast::Type::Tuple { elems: arms, .. } => arms
                .iter()
                .any(|arm| self.type_reaches(arm, target, seen, depth + 1)),
            ast::Type::QualifiedGroup { qualifiers, base, .. } => {
                // A `proj`/`ref` group is a borrow: it indirects.
                if qualifiers.iter().any(|q| crate::types::is_proj_name(&q.name.name)) {
                    return false;
                }
                self.type_reaches(base, target, seen, depth + 1)
            }
            ast::Type::Named { qualifiers, base } => {
                if qualifiers.iter().any(|q| crate::types::is_proj_name(&q.name.name)) {
                    return false;
                }
                self.named_reaches(base, target, seen, depth)
            }
        }
    }

    fn named_reaches(
        &self,
        base: &ast::TypeRef,
        target: &str,
        seen: &mut Vec<String>,
        depth: usize,
    ) -> bool {
        let name = base.name.name.as_str();
        if name == target {
            return true;
        }
        let decl = self.named(base).structure;
        // A type argument is an inline edge only where the type *stores* it
        // inline: a user struct with a bare `value: T` field does, while
        // `List<T>`, `Bag<T>` (whose `T` sits inside a `List`) and every
        // opaque intrinsic container indirect. Getting this wrong in the
        // permissive direction refuses a legal `List<Dir>`/`List<File>` pair,
        // which is how it was found.
        if let Some(d) = decl {
            for (i, arg) in base.args.iter().enumerate() {
                if self.generic_stored_inline(d, i, 0)
                    && self.type_reaches(arg, target, seen, depth + 1)
                {
                    return true;
                }
            }
        }
        if seen.iter().any(|s| s == name) {
            return false;
        }
        // A type alias expands.
        if let Some(alias) = self
            .scope
            .type_aliases
            .get(name)
            .and_then(|t| t.alias.as_ref())
        {
            seen.push(name.to_string());
            if self.type_reaches(alias, target, seen, depth + 1) {
                return true;
            }
            seen.pop();
        }
        let Some(next) = decl else { return false };
        seen.push(name.to_string());
        for field in &next.fields {
            let Some(written) = &field.ty else { continue };
            if self.type_reaches(written, target, seen, depth + 1) {
                return true;
            }
        }
        seen.pop();
        false
    }

    /// [type-no-cycle] Whether a struct stores its `gi`th type parameter
    /// **inline** — directly, or through another struct that does. A
    /// parameter reached only through a container (`items: List<T>`) is not
    /// stored inline, which is what makes a tree of `List<Tree>` legal.
    fn generic_stored_inline(&self, decl: &ast::StructDecl, gi: usize, depth: usize) -> bool {
        if depth > 32 {
            return true; // conservative: report rather than miss
        }
        let Some(param) = decl.generics.get(gi) else {
            return false;
        };
        decl.fields
            .iter()
            .any(|f| f.ty.as_ref().is_some_and(|t| self.type_stores_inline(t, &param.name, depth)))
    }

    fn type_stores_inline(&self, ty: &ast::Type, param: &str, depth: usize) -> bool {
        match ty {
            ast::Type::Literal { .. } => false,
            ast::Type::Array { .. } | ast::Type::Fn { .. } => false,
            ast::Type::Nullable { inner, .. } => self.type_stores_inline(inner, param, depth),
            ast::Type::Spread { inner, .. } => self.type_stores_inline(inner, param, depth),
            ast::Type::Union { arms, .. } | ast::Type::Tuple { elems: arms, .. } => {
                arms.iter().any(|a| self.type_stores_inline(a, param, depth))
            }
            ast::Type::QualifiedGroup { qualifiers, base, .. } => {
                !qualifiers.iter().any(|q| crate::types::is_proj_name(&q.name.name))
                    && self.type_stores_inline(base, param, depth)
            }
            ast::Type::Named { qualifiers, base } => {
                if qualifiers.iter().any(|q| crate::types::is_proj_name(&q.name.name)) {
                    return false;
                }
                if base.name.name == param {
                    return true;
                }
                let Some(d) = self.named(base).structure else {
                    return false;
                };
                base.args.iter().enumerate().any(|(i, arg)| {
                    self.generic_stored_inline(d, i, depth + 1)
                        && self.type_stores_inline(arg, param, depth + 1)
                })
            }
        }
    }

    fn check_proj_field(&mut self, owner: &str, field: &ast::FieldDecl) {
        // [handler-state-infer] An inferred field has no written type to inspect for
        // `proj`; the form takes no qualifiers, so there is nothing to check.
        let Some(field_ty) = &field.ty else { return };
        for r in proj_refs(field_ty) {
            if let Some(from) = r.from.first() {
                self.error(from.span, messages::proj_field_source_named(&owner, &field.name.name));
            }
        }
    }

    fn check_linear_field(&mut self, owner: &str, field: &ast::FieldDecl) {
        // [handler-state-infer] No written type → no `linear struct` marker to check;
        // an inferred type's own linearity is enforced by the IR linear check.
        let Some(field_ty) = &field.ty else { return };
        // [linear-composite] [linear-group] A concrete linear field is
        // legal exactly on a `linear struct` (user decision 2026-09-12):
        // the marker is what gives the composite its own obligation and
        // discharge set, so the contents have a legal death through it.
        // Unmarked, the store stays refused — with the marker as the
        // remedy. (A `canbe linear` generic field is the *conditional*
        // case and is not a concrete store.)
        if let Some(linear) = self.ast_type_own_linear(field_ty) {
            let owner_is_linear = self
                .scope
                .structs
                .get(owner)
                .is_some_and(|s| s.linear);
            if owner_is_linear {
                return;
            }
            if self.scope.structs.contains_key(owner) {
                self.error(
                    field_ty.span(),
                    messages::linear_composite_field(&linear, &owner, &field.name.name),
                );
                return;
            }
            // [linear-state] Handler state is the exception, and the reason
            // this rule has an exception at all (LC-4, user decision
            // 2026-09-15): an actor *is* its state, and the shapes the
            // concurrency surface is for — a queue of parked reply tokens, a
            // map of gathers — live in a handler field. No marker exists to
            // ask for, and none is wanted: the handler already has a lifetime
            // of its own, so the obligation rests with the **actor** until
            // it ends. What an activation may not do is leave a hole
            // (checked where a member returns), and what death does with
            // parked obligations is `watch`'s answer [actor-watch].
            //
            // One shape is refused: a **bare** obligation (a `linear struct`
            // or a linear opaque type, rather than a container of them). It
            // could be stored and never taken back out — a member consuming
            // it is the hole this rule forbids, and there is nothing to put
            // back — so the obligation would have no reachable discharge at
            // all. Hold it in a container, whose take-by-move operations
            // leave the storage itself intact.
            if self.has_auto_linear(&self.type_key(&linear)) && self.container_of_linear(field_ty).is_none() {
                self.error(
                    field_ty.span(),
                    messages::linear_state_field(&linear, &owner, &field.name.name),
                );
            }
        }
    }

    /// [linear-container] The container a field's linearity comes *through*,
    /// if any: `Mut List<Reply<Str>>` answers `List`, a bare `Reply<Str>`
    /// answers `None`. What distinguishes "state holds a queue of
    /// obligations" (legal, LC-4) from "state holds one" (refused: nothing
    /// could take it out again).
    fn container_of_linear(&self, ty: &ast::Type) -> Option<String> {
        match ty {
            ast::Type::Named { base, .. } => {
                let name = base.name.name.clone();
                let opted = self.linear_opt_in_positions(name.as_str());
                if opted
                    .iter()
                    .filter_map(|i| base.args.get(*i))
                    .any(|a| self.ast_type_own_linear(a).is_some())
                {
                    return Some(name);
                }
                None
            }
            ast::Type::QualifiedGroup { base, .. } => self.container_of_linear(base),
            _ => None,
        }
    }

    fn validate_type(&mut self, ty: &ast::Type) {
        // [linear-composite] A linear value may not be stored in a
        // composite: refused at each composite node, one level deep, so a
        // nested one reports at its own node.
        self.check_linear_components(ty);
        match ty {
            ast::Type::Literal { .. } => {}
            ast::Type::Named { qualifiers, base } => {
                self.require_name(base, false);
                self.reject_effect_as_data(base);
                self.reject_group_as_data(base);
                self.reject_comptime_as_data(base);
                // [col-key-eligible] `Set<Double>` / `Map<Double, V>` are
                // refused where they are written, which covers every
                // declaration site this walk reaches.
                self.check_key_eligibility(base);
                // [col-sorted-list] `Sorted List<T>` claims an order over the
                // elements, so they have to *have* one — the same bar the
                // sorted containers apply to their keys.
                self.check_sorted_list_claim(qualifiers, base);
                // [cmp-carry] [qual-value-arg] The `(…)` block's arguments
                // are **identities** (`SortedSet<Str>(my_cmp)`), checked by
                // the lowering rather than as types; everything in `<…>` is
                // a type.
                let type_args = base.args.len();
                for (i, a) in base.args.iter().enumerate() {
                    if i >= type_args {
                        continue;
                    }
                    // [actor-spawn-expr] `Addr<E>`'s argument is the *effect*
                    // the actor serves — the one sanctioned effect-in-a-
                    // type-argument (user decision 2026-09-15). Validated
                    // here rather than in `reject_effect_as_data`, because
                    // only this walk knows what the argument belongs to.
                    if self.is_addr_effect_arg(base, i, a) {
                        // [actor-effect-kind] [actor-monitor-handler] Legal *as* an
                        // effect here, of either kind: an actor effect's addr
                        // is a mailbox handle, a plain effect's a shared
                        // monitor's handle (SH-3, user decision 2026-09-19).
                        continue;
                    }
                    self.validate_type(a);
                }
                // [lsp-definition] Always lower the base — not only when
                // qualifiers are written — so a plain (unqualified) type
                // reference's `def_refs` entry is recorded too, the same
                // way `lower_base_ref` already records one for a qualified
                // reference here and an alias's target in
                // `QualifiedGroup` below. Without this, a bare union arm
                // (`type Type = Option.Int | Option.Str`) or struct field
                // type reached only through `validate_type` (never through
                // a call argument or struct literal) had no recorded
                // reference at all, so hover/go-to-definition on it found
                // nothing (2026-10-19, [lsp-definition] gap).
                let empty = HashMap::new();
                let lowered = self.lower_base_ref(base, &empty, 0);
                if !qualifiers.is_empty() {
                    self.validate_quals(qualifiers, &lowered);
                }
            }
            ast::Type::QualifiedGroup {
                qualifiers, base, ..
            } => {
                self.validate_type(base);
                let empty = HashMap::new();
                let lowered = self.lower_type_subst(base, &empty, 0);
                self.validate_quals(qualifiers, &lowered);
            }
            ast::Type::Union { arms, .. } => {
                // [type-literal-qualified] A literal listed twice under
                // different qualifiers (`Short "port" | "port"`, aliases
                // expanded): the qualifiers erase, so the value cannot say
                // which arm it is. Checked on the lowered union, where
                // aliases are expanded — only when some arm is qualified,
                // since a conflict needs one (and lowering again must not
                // repeat name errors for every plain union).
                let qualified_arm = arms.iter().any(|a| {
                    matches!(a, ast::Type::QualifiedGroup { .. })
                        || matches!(a, ast::Type::Named { qualifiers, .. } if !qualifiers.is_empty())
                });
                let lowered = if qualified_arm { self.lower_type(ty) } else { Ty::Unknown };
                if let Some((lit, a, b)) = crate::literal::literal_conflict(&lowered.value_arms()) {
                    self.error(
                        ty.span(),
                        messages::type_literal_qualified_listed_twice(&lit, &a, &b),
                    );
                }
                for a in arms {
                    // [type-union-spread] A spread arm is validated through its
                    // inner here; `validate_type(Spread)` on its own is the
                    // error for a spread outside a union.
                    match a {
                        ast::Type::Spread { inner, .. } => self.validate_type(inner),
                        other => self.validate_type(other),
                    }
                }
                // [type-union-spread] At most one `...T` spread arm, and each
                // spread's inner must be a bare generic type parameter in
                // scope — the spread captures a span of arms, which only a
                // generic can stand for.
                let spreads: Vec<&ast::Type> =
                    arms.iter().filter(|a| matches!(a, ast::Type::Spread { .. })).collect();
                if spreads.len() > 1 {
                    if let ast::Type::Spread { span, .. } = spreads[1] {
                        self.error(*span, messages::type_union_spread_two_spreads());
                    }
                }
                for s in &spreads {
                    if let ast::Type::Spread { inner, span } = s {
                        let bare_generic = matches!(inner.as_ref(), ast::Type::Named { qualifiers, base }
                            if qualifiers.is_empty() && base.args.is_empty()
                                && self.generics.contains(base.name.name.as_str()));
                        if !bare_generic {
                            self.error(*span, messages::type_union_spread_not_generic(&inner));
                        }
                    }
                }
                // [type-literal] A literal beside its own bare base adds
                // nothing: every value of the base is already an arm. The
                // open arm is spelled `Other Str`.
                for a in arms {
                    if let ast::Type::Literal { value, span } = a {
                        let base = value.base();
                        let bare = arms.iter().any(|b| {
                            matches!(b, ast::Type::Named { qualifiers, base: r }
                                if qualifiers.is_empty() && r.args.is_empty() && r.name.name == base)
                        });
                        if bare {
                            self.warn(*span, messages::type_literal_subsumed(&value, &base));
                        }
                    }
                }
            }
            ast::Type::Tuple { elems, .. } => {
                for e in elems {
                    self.validate_type(e);
                }
            }
            ast::Type::Array { elem, .. } => self.validate_type(elem),
            ast::Type::Nullable { inner, .. } => self.validate_type(inner),
            ast::Type::Spread { inner, span } => {
                // [type-union-spread] A `...T` is only meaningful as a union arm;
                // elsewhere it captures nothing.
                self.validate_type(inner);
                self.error(*span, messages::type_union_spread_alone());
            }
            ast::Type::Fn { params, ret, .. } => {
                        for p in params {
                    self.validate_type(p);
                }
                self.validate_type(ret);
            }
        }
    }

    fn validate_quals(&mut self, qualifiers: &[TypeRef], base: &Ty) {
        // Every applied qualifier names a declaration [name-resolve].
        for q in qualifiers {
            self.require_name(q, true);
            // [cmp-carry] A qualifier that declares fn slots takes
            // **identities** there, not types: `Heap(cmp@Person)` names a
            // function, and validating it as a type would report an unknown
            // one. The identity's own check is the lowering's
            // (`written_fn_id`), which is where the static-identity rule and
            // its diagnostic live.
            if !self.qual_fn_slots(&q.name.name).is_empty() {
                continue;
            }
            for a in &q.args {
                self.validate_type(a);
            }
        }
        // [comptime-qualifier] A comptime qualifier describes a declaration,
        // not a value: it is never part of a type.
        for q in qualifiers {
            if self.written_qual_decl(q).is_some_and(|d| d.comptime) {
                self.error(q.name.span, messages::comptime_qualifier_in_type(&q.name.name));
            }
        }
        // The same qualifier cannot be applied twice [qual-no-dup].
        for (i, q) in qualifiers.iter().enumerate() {
            if qualifiers[..i].iter().any(|p| p.name.name == q.name.name) {
                self.error(q.span, messages::qual_no_dup_applied_twice(&q.name.name));
            }
        }
        // [qual-overload] The subject picks among same-named qualifiers here:
        // `NonEmpty List<T>` and `NonEmpty Set<T>` are different declarations,
        // and the base type written in front of the qualifier says which.
        let decls: Vec<Option<&'p QualifierDecl>> = qualifiers
            .iter()
            .map(|q| self.qualifier_for(q.name.name.as_str(), Some(base)))
            .collect();
        // [qual-const] A constant fills a value slot of its own type:
        // `Short('p')` a `Char`, `Prefix("arn:")` a `Str`, `InRange(0, 9)` an
        // `Int`. A place's type is the `is` test's to check, where it has one.
        for (q, decl) in qualifiers.iter().zip(&decls) {
            let Some(decl) = decl else { continue };
            for (written, slot) in q.value_args.iter().zip(&decl.value_slots) {
                let ast::Type::Named { qualifiers: wq, base: wb } = written else { continue };
                if !wq.is_empty() || wb.binder {
                    continue;
                }
                let Some(c) = crate::types::Const::parse(&wb.name.name) else { continue };
                let saved = self.enter_generics(&decl.generics);
                let want = self.lower_type(&slot.ty);
                self.generics = saved;
                if !want.is_unknown() && !matches!(want.strip_quals(), Ty::Named { name, args } if args.is_empty() && name == c.base()) {
                    self.error(
                        wb.span,
                        messages::qual_const_slot_mismatch(
                            &c,
                            &slot.name.name,
                            &q.name.name,
                            &want,
                            &c.base(),
                        ),
                    );
                }
            }
        }
        // Each qualifier must apply to the base type (per its `of` type)
        // [qual-of].
        if !matches!(base, Ty::Unknown | Ty::Var(_)) {
            for (q, decl) in qualifiers.iter().zip(&decls) {
                // [comptime-qualifier] Reported above, once.
                if decl.is_some_and(|d| d.comptime) {
                    continue;
                }
                // `Mut` is the language-level auto-qualifier: valid only
                // on declarations that opt in with `canbe Mut`
                // [struct-mut] [type-canbe-mut].
                if q.name.name == "Mut" {
                    if !self.has_auto_mut(base) {
                        self.error(q.span, messages::struct_mut_not_canbe_mut(&base));
                    }
                    continue;
                }
                // [linear-group] Linearity is declared, not applied: every
                // value of a `canbe linear` type is linear, so writing
                // `Linear` at a use site is meaningless (and forgetting
                // it must not silently drop the protection).
                if q.name.name == "linear" {
                    self.error(q.span, messages::linear_group_linear_in_type());
                    continue;
                }
                // [fn-once] `once` is the language-level *use*-multiplicity
                // qualifier. It began as call-multiplicity, on function
                // types only, and was generalized 2026-09-07 (user
                // decision): using a function value means calling it, and
                // using an `Iter<T>` means driving it, so the same
                // "at most once" claim marks a **pass** — a position in a
                // sequence — as against a replayable factory.
                //
                // The position list is deliberately explicit rather than
                // "any type": a general affine qualifier is a vocabulary
                // decision of its own, kept as roadmap D6 rather than
                // shipped as a side effect of this one.
                // [fn-effects] An **effect** name is not a qualifier. It was
                // one for as long as a producer was a *type* (`FileSystem
                // Iter<Str>` claimed what driving it performed); with the
                // reduction to `next` a producer is a struct and its effects
                // are the effects of a *function*, where `[…]` already says
                // them. So the claim-on-a-type spelling is gone, and saying
                // so names the replacement.
                if decl.is_none() && self.named(q).effect.is_some() {
                    let fn_type = matches!(base, Ty::Fn { .. });
                    self.error(
                        q.span,
                        if fn_type {
                            messages::fn_effects_in_qualifier_position(&q.name.name)
                        } else {
                            messages::fn_effects_effect_as_qualifier(&q.name.name)
                        },
                    );
                    continue;
                }
                if q.name.name == "once" {
                    // [fn-once] D6 (user decision 2026-09-12): `once` is
                    // valid on **any** type — the upper bound `[0,1]` is a
                    // self-restriction that demands nothing of the type's
                    // author, so `once FileHandle` or `once Ticket` means
                    // "use at most once" wherever it is written. The old
                    // fn-only/`canbe once` gate is gone; enforcement is the
                    // IR flow pass's moves [deduce-consume] [flow-use-after-move].
                    continue;
                }
                let Some(decl) = decl else {
                    // [qual-overload] The name is declared, but not over this
                    // subject: with several candidates the resolution simply
                    // found none, which must be the same error as a single
                    // declaration that does not apply rather than silence.
                    if self.qualifier_named(q.name.name.as_str()).is_some() {
                        self.error(q.span, messages::qual_of_does_not_apply(&q.name.name, &base));
                    }
                    continue;
                };
                if !self.qual_applies(decl, base) {
                    self.error(q.span, messages::qual_of_does_not_apply(&q.name.name, &base));
                }
            }
        }
        // [qual-no-with] Several qualifiers compose freely (user decision
        // 2026-10-12, retiring `with`): there is no declared compatibility
        // allowlist. What a value can be is implicit in which functions mint
        // each qualifier and each qualifier's own `qualifies` predicate, so
        // nothing here forbids a pair.
    }

    /// [qual-overload] The qualifier a use of `name` means. One name may be
    /// declared over several **subject types** (`NonEmpty of List<T>` beside
    /// `NonEmpty of Set<T>`), and the subject decides which — the way a fn
    /// overload is decided by its arguments.
    ///
    /// With a single candidate the subject is not consulted at all, so a use
    /// over an unknown or generic subject still resolves; that is also the
    /// path every program took before overloading existed.
    fn qualifier_for(&mut self, name: &str, subject: Option<&Ty>) -> Option<&'p QualifierDecl> {
        let candidates = self.scope.qualifiers.get(name)?.clone();
        match candidates.as_slice() {
            [] => None,
            [one] => Some(*one),
            many => {
                // Against the *base* type: a qualifier's `of` is about the
                // data, so a `Mut Set<Str>` subject picks the `of Set<T>`
                // declaration exactly as a plain `Set<Str>` does.
                let subject = subject?.strip_quals().clone();
                many.iter().copied().find(|d| self.qual_applies(d, &subject))
            }
        }
    }

    /// [qual-overload] A qualifier with this name, for questions that are
    /// about the *name* rather than about a subject — does one exist, does it
    /// have a body, is it provenance. Where several are declared these
    /// answers agree in practice (they are the same claim over different
    /// containers), and the first is as good as any.
    fn qualifier_named(&self, name: &str) -> Option<&'p QualifierDecl> {
        self.scope.qualifiers.get(name)?.first().copied()
    }

    /// Whether a qualifier's `of` type accepts the given base type.
    fn qual_applies(&mut self, decl: &'p QualifierDecl, base: &Ty) -> bool {
        if matches!(base, Ty::Unknown | Ty::Var(_)) {
            return true;
        }
        let saved = self.enter_generics(&decl.generics);
        let of_ty = self.lower_type(&decl.of);
        self.generics = saved;
        let mut subst = HashMap::new();
        unify(&of_ty, base.strip_quals(), &mut subst)
    }

    /// Whether the base type's declaration opted into the `Mut`
    /// auto-qualifier: `struct S canbe Mut` [struct-mut] or
    /// `intrinsic type List<T> canbe Mut` [type-canbe-mut].
    /// Whether `name` is a *provenance* qualifier [qual-subject]: a claim
    /// about where the handle came from, which no call can invalidate.
    /// [qual-subject] [ref-notsame] Whether a qualifier survives a call that
    /// does not keep it: provenance, a borrow's own flavour (`proj`/`ref`
    /// say what the value *is*), and `NotSame` (identity, not contents).
    fn survives_calls(&self, name: &str) -> bool {
        self.is_provenance_qual(name) || crate::types::is_proj_name(name) || name == NOT_SAME
    }

    fn is_provenance_qual(&self, name: &str) -> bool {
        self.qualifier_named(name)
            .is_some_and(|d| d.subject == QualSubject::Provenance)
    }

    /// [qual-arm-infer] Provenance-arm inference (user decision 2026-10-12): at a
    /// position whose expected type is a wrapper union, a bare value that
    /// matches no arm by subtyping may still be the payload of exactly one
    /// *provenance-tagged* arm — `return name.size()` for `-> Ok Int | Err
    /// Str` is implicitly `Ok(name.size())`. Returns the index (into the
    /// union's value arms) of the one provenance arm whose inner type (the
    /// arm with its provenance qualifier stripped) accepts `value`, or `None`
    /// when zero or more than one qualify, or any non-provenance arm also
    /// accepts the value (then the plain value should have matched and this
    /// does not fire). The qualifier is erased [qual-erasure], so wrapping the
    /// bare value into that arm *is* the mint — no ctor call need be emitted.
    /// [qual-arm-infer] What a provenance-tagged arm holds: the arm with its
    /// provenance qualifiers stripped (`Ok (A | B)` → `A | B`), or `None` for
    /// an arm that is not one.
    fn provenance_payload(&self, arm: &Ty) -> Option<Ty> {
        let Ty::Qualified { quals, base } = arm else { return None };
        if !quals.iter().any(|q| self.is_provenance_qual(&q.name)) {
            return None;
        }
        let keep: Vec<Qual> = quals.iter().filter(|q| !self.is_provenance_qual(&q.name)).cloned().collect();
        Some(if keep.is_empty() { (**base).clone() } else { (**base).clone().qualify(keep) })
    }

    fn infer_provenance_arm(&self, value: &Ty, arms: &[&Ty]) -> Option<usize> {
        match self.provenance_arms(value, arms)[..] {
            [i] => Some(i),
            _ => None,
        }
    }

    /// [qual-arm-infer] Every provenance-tagged arm whose payload accepts
    /// `value`: one is the arm inferred, several are an ambiguity the
    /// explicit constructor resolves.
    fn provenance_arms(&self, value: &Ty, arms: &[&Ty]) -> Vec<usize> {
        // If any arm accepts the value outright, this is not an inference case.
        if arms.iter().any(|arm| is_subtype(value, arm)) {
            return Vec::new();
        }
        // [qual-arm-infer] A *literal* union with an open provenance arm
        // (`"A" | "B" | Other Str`) is the deliberate escape-hatch shape: a
        // plain `Str` must be narrowed to a listed literal or wrapped
        // *explicitly* with `other(…)` [type-literal], never auto-wrapped
        // into the open arm. So inference does not fire when any arm is a
        // literal type.
        if arms.iter().any(|arm| crate::literal::mentions_lit(arm)) {
            return Vec::new();
        }
        let mut found: Vec<usize> = Vec::new();
        for (i, arm) in arms.iter().enumerate() {
            // A provenance-tagged arm: a qualified type one of whose
            // qualifiers is a provenance qualifier with exactly one
            // constructor in scope.
            let Ty::Qualified { quals, base } = arm else {
                continue;
            };
            let prov: Vec<&Qual> = quals
                .iter()
                .filter(|q| self.is_provenance_qual(&q.name))
                .collect();
            // Exactly one provenance qualifier on the arm, and the value fits
            // the arm's inner payload (the arm with every provenance qual
            // stripped). Other (non-provenance) qualifiers must still be met
            // by the inner subtype check.
            if prov.len() != 1 {
                continue;
            }
            let inner = {
                let keep: Vec<Qual> = quals
                    .iter()
                    .filter(|q| !self.is_provenance_qual(&q.name))
                    .cloned()
                    .collect();
                if keep.is_empty() {
                    (**base).clone()
                } else {
                    (**base).clone().qualify(keep)
                }
            };
            if !is_subtype(value, &inner) {
                continue;
            }
            found.push(i);
        }
        found
    }

    ///
    /// The additions are what the feature exists for — `add`'s exhaustive
    /// `[list: Mut]` must drop `NonEmpty` ([deduce-syntax] is sound only
    /// that way), and `NonEmpty`'s own refinement puts it back. Trusted,
    /// like `-> T as Q` [qual-ctor-fn]: no `qualifies` call is emitted.
    ///
    /// Two cases apply nothing. A group whose refinements *conflict*
    /// [qual-refn] is suppressed, with one warning per (callee,
    /// parameter) — no error, since the caller can still test by hand or
    /// name the place it means [qual-refn], but not silence either, or an
    /// imported refinement would appear to do nothing for no visible
    /// reason. And a single addition is skipped when it could not co-apply
    /// with a qualifier the call *preserved* [qual-with]: the value cannot
    /// carry both claims, and knowing less is the safe direction.
    /// [deduce-reapply] Adds the claims a callee's clause says it
    /// **establishes** on this argument, with the call's type arguments and
    /// resolved identities substituted in — `+Heap<T>(?cmp)` on a
    /// `heapify(list, ?Ordered<T>)` makes the caller's `list` a
    /// `Heap<Int>(by_age) Mut List<Int>` when the call resolved `?cmp` to
    /// `by_age`.
    ///
    /// Trusted, like a refinement's addition and a constructor's `as Q`: the
    /// signature check has already confined it to the qualifier's own file and
    /// to a qualifier that applies to the parameter's type.
    fn establish_quals(
        &mut self,
        callee: DeclId,
        param: &str,
        arg: &str,
        subst: &HashMap<String, Ty>,
        callee_generics: &HashSet<String>,
    ) {
        let Some(quals) = self
            .out
            .established_quals
            .get(&(callee, param.to_string()))
            .cloned()
        else {
            return;
        };
        for q in quals {
            let args: Vec<Ty> = q
                .args
                .iter()
                .map(|a| substitute_vars(a, subst, callee_generics))
                .collect();
            let have: Vec<String> = self
                .lookup(arg)
                .map(|v| v.narrowed.quals().iter().map(|x| x.name.clone()).collect())
                .unwrap_or_default();
            if let Some(var) = self.lookup_mut(arg) {
                // Already there — the re-establishment case — so the claim
                // stays what the value carries: the arguments cannot differ
                // (the signature check refuses that), and rewriting them would
                // only risk losing what the value knows.
                if have.contains(&q.name) {
                    continue;
                }
                var.narrowed = var.narrowed.clone().qualify(vec![Qual { args, ..q }]);
            }
        }
    }

    /// [deduce-gained] The qualifiers a *written* deduction entry reports for
    /// one parameter that the parameter itself does not declare: claims the
    /// body established, verified against it by the deduction pass rather than
    /// trusted like `+Q`. Empty for an inferred clause — reporting a gain is
    /// something a signature has to say out loud.
    fn plain_gains(&self, decl: &'p FnDecl, param: &str) -> Vec<String> {
        let Some(list) = &decl.deductions else {
            return Vec::new();
        };
        let Some(p) = decl.params.iter().find(|p| p.name.name == param) else {
            return Vec::new();
        };
        let declared = crate::deduce::declared_quals(&p.ty);
        list.iter()
            .filter(|d| d.param_name().is_some_and(|n| n.name == param))
            .flat_map(|d| match &d.kind {
                salvo_syntax::ast::DeductionKind::Exhaustive { quals, .. } => quals
                    .iter()
                    .map(|q| q.name.name.clone())
                    .filter(|q| !declared.contains(q))
                    .collect::<Vec<_>>(),
                _ => Vec::new(),
            })
            .collect()
    }

    /// [qual-refn] Applies the refinements written about one parameter of a
    /// call, to the argument `arg`.
    ///
    /// [qual-refn-narrow] `had` is what the argument carried **before** this
    /// call, which is what a conditional refinement is tested against: a
    /// refinement whose parameter is narrower than the declaration's
    /// (`refn swap(list: NonEmpty Mut List<T>, …)`) states what happens *when
    /// the claim is already there*, and must not put it there.
    /// [qual-preserve] The dependent claims a call to `key`/`decl` keeps
    /// alive on values depending on its `param`: the qualifier owners'
    /// refinements (requires-gated like every group [qual-refn-narrow]),
    /// plus the callee's own checked `preserve` entries.
    fn preserved_claims(
        &mut self,
        key: Option<DeclId>,
        decl: &ast::FnDecl,
        param: &str,
        have: &[String],
    ) -> Vec<String> {
        let mut out: Vec<String> = Vec::new();
        if let Some(key) = key {
            for g in self.refinements.for_param_all(self.file_idx, key, param) {
                if !g.requires.iter().all(|q| have.iter().any(|h| h == q)) {
                    continue;
                }
                for q in &g.preserve {
                    if !out.contains(q) {
                        out.push(q.clone());
                    }
                }
            }
        }
        if let Some(list) = &decl.deductions {
            for d in list {
                if let (Some(name), ast::DeductionKind::Preserve(quals)) =
                    (d.param_name(), &d.kind)
                {
                    if name.name == param {
                        for q in quals {
                            if !out.contains(&q.name.name) {
                                out.push(q.name.name.clone());
                            }
                        }
                    }
                }
            }
        }
        out
    }

    fn apply_refinements(
        &mut self,
        callee: DeclId,
        param: &str,
        arg: &str,
        had: &[String],
        span: Span,
    ) {
        // [qual-refn] Every matching refinement applies (user decision
        // 2026-10-12). A `+Q`/`-Q` contradiction is a declaration error, so
        // there is no call-site conflict to resolve and no `@place` selector.
        // Requires-gated [qual-refn-narrow]: a conditional refinement applies
        // only where the argument already carries what it requires.
        let groups: Vec<crate::refine::RefnGroup> = self
            .refinements
            .for_param_all(self.file_idx, callee, param)
            .into_iter()
            .filter(|g| g.requires.iter().all(|q| had.iter().any(|h| h == q)))
            .cloned()
            .collect();
        for group in groups {
            self.apply_refinement_group(&group, callee, param, arg, span);
        }
    }

    /// One group of refinements that agree about a parameter, applied.
    fn apply_refinement_group(
        &mut self,
        group: &crate::refine::RefnGroup,
        callee: DeclId,
        param: &str,
        arg: &str,
        span: Span,
    ) {
        let _ = (callee, param, span);
        let remove: HashSet<String> = group.remove.iter().cloned().collect();
        let add = group.add.clone();
        if !remove.is_empty() {
            if let Some(var) = self.lookup_mut(arg) {
                var.narrowed = var.narrowed.clone().remove_quals(&remove);
            }
        }
        for q in add {
            let have: Vec<String> = self
                .lookup(arg)
                .map(|v| v.narrowed.quals().iter().map(|x| x.name.clone()).collect())
                .unwrap_or_default();
            if have.contains(&q) {
                continue;
            }
            // [qual-refn] Every matching refinement applies: a `+Q`/`-Q`
            // contradiction is refused at the declaration, so there is no
            // call-site compatibility to re-check.
            if let Some(var) = self.lookup_mut(arg) {
                var.narrowed = var.narrowed.clone().qualify(vec![Qual {
                    effect: false,
                    name: q,
                    args: Vec::new(),
                }]);
            }
        }
    }

    /// [struct-field-canbe-mut] `name: T canbe Mut` is legal in a `canbe Mut` struct
    /// only (elsewhere the struct value is never `Mut`, so the field never
    /// would be), over a `T` whose declaration says `canbe Mut`, written
    /// without a `Mut` of its own.
    fn check_canbe_mut_field(&mut self, s: &'p StructDecl, field: &'p ast::FieldDecl) {
        if !field.canbe_mut {
            return;
        }
        let span = field.written_ty().span();
        if !s.auto_qualifiers.iter().any(|q| q.name.name == "Mut") {
            self.error(
                span,
                messages::struct_field_canbe_mut_struct_not_canbe_mut(
                    &field.name.name,
                    &s.name.name,
                ),
            );
            return;
        }
        let ty = self.lower_type(field.written_ty());
        if ty.is_unknown() {
            return;
        }
        if ty.quals().iter().any(|q| q.name == "Mut") {
            self.error(span, messages::struct_field_canbe_mut_already_mut(&field.name.name));
        } else if !self.has_auto_mut(&ty) {
            self.error(span, messages::struct_field_canbe_mut_not_applicable(&ty));
        }
    }

    fn has_auto_mut(&self, base: &Ty) -> bool {
        let Ty::Named { name, .. } = base.strip_quals() else {
            return false;
        };
        let has_mut = |quals: &[ast::TypeRef]| quals.iter().any(|q| q.name.name == "Mut");
        self.symbols
            .structs
            .get(name.as_str())
            .is_some_and(|s| has_mut(&s.auto_qualifiers))
            || self
                .symbols
                .intrinsic_types
                .get(name.as_str())
                .is_some_and(|t| has_mut(&t.auto_qualifiers))
    }

    /// Validates a qualifier declaration: predicate qualifiers need a
    /// well-formed `qualifies` function [qual-predicate]; field overrides
    /// must refine real fields of the `of` struct [qual-field-override];
    /// bodiless (constructive) qualifiers take neither [qual-constructive].
    /// [doc-tags] The tags of every doc block in `module`: a tag this
    /// version does not know, an `@param` naming no parameter, and an
    /// `@whynot` anywhere but on a qualifier's `fn qualifies` are warnings,
    /// at the documented declaration's name (doc lines carry no spans). A
    /// `@whynot` that names what it may not is the qualifier check's error
    /// [qual-whynot].
    fn check_doc_tags(&mut self, module: &'p Module) {
        enum Owner<'a> {
            Fn(&'a [ast::Param], bool),
            Other,
        }
        let mut found: Vec<(Span, Message)> = Vec::new();
        let mut visit = |docs: &[String], name: &ast::Ident, owner: Owner| {
            for tag in salvo_syntax::doc::split(docs).tags {
                if !salvo_syntax::doc::KNOWN_TAGS.contains(&tag.name.as_str()) {
                    let known: Vec<String> = salvo_syntax::doc::KNOWN_TAGS.iter().map(|t| format!("@{t}")).collect();
                    found.push((name.span, messages::doc_tags_unknown_tag(&tag.name, &known.join(", "))));
                    continue;
                }
                match (tag.name.as_str(), &owner) {
                    ("param", Owner::Fn(params, _)) => match &tag.target {
                        None => found.push((name.span, messages::doc_tags_param_unnamed())),
                        Some(t) if !params.iter().any(|p| p.name.name == *t) => {
                            found.push((name.span, messages::doc_tags_param_unknown(&t, &name.name)))
                        }
                        Some(_) => {}
                    },
                    ("param", Owner::Other) => found.push((name.span, messages::doc_tags_param_not_fn(&name.name))),
                    ("compilerrules", _) if salvo_syntax::doc::compiler_rules(&tag.text).is_none() => found.push((
                        name.span,
                        messages::doc_compilerrules_no_rules(),
                    )),
                    ("whynot", Owner::Fn(_, true)) => {}
                    ("whynot", _) => found.push((
                        name.span,
                        messages::qual_whynot_misplaced_tag(),
                    )),
                    _ => {}
                }
            }
        };
        let fns = |fs: &'p [ast::FnDecl], visit: &mut dyn FnMut(&[String], &ast::Ident, Owner)| {
            for f in fs {
                visit(&f.docs, &f.name, Owner::Fn(&f.params, false));
            }
        };
        for item in &module.items {
            match item {
                Item::Fn(f) => visit(&f.docs, &f.name, Owner::Fn(&f.params, false)),
                Item::Struct(s) => {
                    visit(&s.docs, &s.name, Owner::Other);
                    for fd in &s.fields {
                        visit(&fd.docs, &fd.name, Owner::Other);
                    }
                }
                Item::Type(t) => visit(&t.docs, &t.name, Owner::Other),
                Item::Qualifier(q) => {
                    visit(&q.docs, &q.name, Owner::Other);
                    for f in &q.fns {
                        visit(&f.docs, &f.name, Owner::Fn(&f.params, f.name.name == "qualifies"));
                    }
                }
                Item::Effect(e) => {
                    visit(&e.docs, &e.name, Owner::Other);
                    fns(&e.fns, &mut visit);
                }
                Item::Handler(h) => {
                    visit(&h.docs, &h.name, Owner::Other);
                    fns(&h.fns, &mut visit);
                }
                Item::Fns(p) => {
                    visit(&p.docs, &p.name, Owner::Other);
                    fns(&p.fns, &mut visit);
                }
                Item::EffectAlias(a) => visit(&a.docs, &a.name, Owner::Other),
                Item::Refn(r) => visit(&r.docs, &r.name, Owner::Fn(&r.params, false)),
                _ => {}
            }
        }
        for (span, msg) in found {
            self.warn(span, msg);
        }
    }

    /// [copy-scalar-free] A written `!v` on a parameter typed as a Copy scalar
    /// says nothing: moving one is a copy, so the caller keeps its value
    /// either way. A warning naming the clause entry, so the clause says only
    /// what it means (user decision 2026-10-20). std is exempt, like the
    /// other smells. A generic `!elem` stays legal and silent: whether its
    /// argument moves is the call's question.
    fn check_scalar_moves(&mut self, module: &'p Module) {
        if self.is_std {
            return;
        }
        let mut found: Vec<(Span, Message)> = Vec::new();
        let mut visit = |f: &ast::FnDecl| {
            for d in f.deductions.iter().flatten() {
                if !matches!(d.kind, ast::DeductionKind::Moved) {
                    continue;
                }
                let Some(name) = d.param_name() else { continue };
                let Some(p) = f.params.iter().find(|p| p.name.name == name.name) else { continue };
                if salvo_syntax::is_copy_scalar_type(&p.ty) {
                    found.push((
                        d.span,
                        messages::copy_scalar_free_moved_scalar(&p.ty, &name.name),
                    ));
                }
            }
        };
        for item in &module.items {
            match item {
                Item::Fn(f) => visit(f),
                Item::Effect(e) => e.fns.iter().for_each(&mut visit),
                Item::Handler(h) => h.fns.iter().for_each(&mut visit),
                Item::Qualifier(q) => q.fns.iter().for_each(&mut visit),
                Item::Fns(p) => p.fns.iter().for_each(&mut visit),
                _ => {}
            }
        }
        for (span, msg) in found {
            self.warn(span, msg);
        }
    }

    /// [qual-whynot] A predicate qualifier says why a value failed it in a
    /// `@whynot` tag on `fn qualifies`: a template whose `[name]`s are
    /// `qualifies`' parameters — the subject, or a slot of a scalar type,
    /// which has a text form wherever the test is written. The member fn
    /// `explain` it replaced is refused, naming the tag.
    fn check_whynot_decl(&mut self, q: &'p QualifierDecl) {
        if let Some(explain) = q.fns.iter().find(|f| f.name.name == "explain") {
            self.error(explain.name.span, messages::qual_whynot_on_fn(&q.name.name));
        }
        let Some(qualifies) = q.fns.iter().find(|f| f.name.name == "qualifies") else { return };
        let parts = salvo_syntax::doc::split(&qualifies.docs);
        let Some(tag) = parts.tag("whynot") else { return };
        let params: Vec<&ast::Param> = qualifies.params.iter().filter(|p| !p.implicit).collect();
        for part in salvo_syntax::doc::template(&tag.text) {
            let salvo_syntax::doc::TemplatePart::Param(name) = part else { continue };
            match params.iter().position(|p| p.name.name == name) {
                Some(0) => {}
                Some(i) => {
                    let scalar = matches!(&params[i].ty, ast::Type::Named { qualifiers, base }
                        if qualifiers.is_empty() && base.args.is_empty()
                            && matches!(base.name.name.as_str(), "Int" | "Long" | "Double" | "Bool" | "Char" | "Str"));
                    if !scalar {
                        self.error(
                            qualifies.name.span,
                            messages::qual_whynot_slot_type(&name, &params[i].ty),
                        );
                    }
                }
                None => {
                    let names: Vec<String> = params.iter().map(|p| format!("[{}]", p.name.name)).collect();
                    self.error(
                        qualifies.name.span,
                        messages::qual_whynot_unknown_slot(&name, &q.name.name, &names.join(", ")),
                    );
                }
            }
        }
    }

    /// [qual-whynot] `Q.qualifies(args)`: a qualifier's own fn called
    /// directly, with every non-implicit parameter given, the qualifier's
    /// type parameters inferred from the arguments.
    fn check_qual_member_call(&mut self, q: &'p QualifierDecl, f: &'p ast::FnDecl, args: &'p [Expr], span: Span) -> Ty {
        let saved = self.enter_generics(&q.generics);
        let params: Vec<&ast::Param> = f.params.iter().filter(|p| !p.implicit).collect();
        if f.params.iter().any(|p| p.implicit) {
            self.error(span, messages::qual_whynot_call_implicits(&q.name.name, &f.name.name));
        }
        if params.len() != args.len() {
            self.error(
                span,
                messages::qual_whynot_call_arg_count(
                    &q.name.name,
                    &f.name.name,
                    &params.len(),
                    &args.len(),
                ),
            );
            for a in args {
                self.check_expr(a, None);
            }
            self.generics = saved;
            return Ty::Unknown;
        }
        let mut subst: HashMap<String, Ty> = HashMap::new();
        let gens: HashSet<String> = q.generics.iter().map(|g| g.name.clone()).collect();
        for (p, a) in params.iter().zip(args) {
            let want = self.lower_type(&p.ty);
            let got = self.check_expr(a, Some(&want));
            unify(&want, got.strip_quals(), &mut subst);
            let want = if gens.is_empty() { want } else { substitute_vars(&want, &subst, &gens) };
            if !got.is_unknown() && !want.is_unknown() && !is_subtype(&got, &want) && !is_subtype(got.strip_quals(), &want) {
                self.error(
                    a.span(),
                    messages::qual_whynot_call_arg_mismatch(&q.name.name, &f.name.name, &want, &got),
                );
            }
        }
        let ret = match &f.return_type {
            Some(t) if !gens.is_empty() => substitute_vars(&self.lower_type(t), &subst, &gens),
            Some(t) => self.lower_type(t),
            None => Ty::none(),
        };
        self.generics = saved;
        let of = match &q.of {
            ast::Type::Named { base, .. } => Some(base.name.name.clone()),
            _ => None,
        };
        self.out.qual_member_calls.insert(self.key(span), (q.name.name.clone(), f.name.name.clone(), of));
        ret
    }

    /// [comptime-qualifier] The comptime qualifiers written on a declaration
    /// (`subject` is `Struct`) or before a field's name (`Field`): each names
    /// a `comptime qualifier` of that subject, once, with a constant of its
    /// slot's type in every slot.
    fn check_annotations(&mut self, annotations: &[TypeRef], subject: &str) {
        for (i, a) in annotations.iter().enumerate() {
            let name = a.name.name.as_str();
            if annotations[..i].iter().any(|b| b.name.name == name) {
                self.error(a.span, messages::comptime_qualifier_applied_twice(&name));
                continue;
            }
            self.require_name(a, true);
            let Some(decl) = self.written_qual_decl(a) else { continue };
            self.record_qualifier_def(a);
            if !decl.comptime {
                let place = if subject == "Field" { "before a field's name" } else { "before a declaration" };
                self.error(
                    a.name.span,
                    messages::comptime_qualifier_not_comptime_annotation(&name, &place, &subject),
                );
                continue;
            }
            let of = match &decl.of {
                ast::Type::Named { base, .. } => base.name.name.as_str(),
                _ => "",
            };
            if of != subject {
                self.error(
                    a.name.span,
                    messages::comptime_qualifier_wrong_subject(&name, &of, &subject),
                );
                continue;
            }
            if !a.args.is_empty() {
                self.error(a.span, messages::comptime_qualifier_type_args(&name));
            }
            if a.value_args.len() != decl.value_slots.len() {
                self.error(
                    a.span,
                    messages::comptime_qualifier_const_count(
                        &name,
                        &decl.value_slots.len(),
                        &a.value_args.len(),
                    ),
                );
                continue;
            }
            for (written, slot) in a.value_args.iter().zip(&decl.value_slots) {
                let constant = match written {
                    ast::Type::Named { qualifiers, base } if qualifiers.is_empty() && !base.binder => {
                        crate::types::Const::parse(&base.name.name).map(|c| (c, base.span))
                    }
                    _ => None,
                };
                let want = match &slot.ty {
                    ast::Type::Named { base, .. } => base.name.name.as_str(),
                    _ => "",
                };
                match constant {
                    Some((c, _)) if c.base() == want => {}
                    Some((c, span)) => self.error(
                        span,
                        messages::qual_const_slot_mismatch(
                            &c,
                            &slot.name.name,
                            &name,
                            &want,
                            &c.base(),
                        ),
                    ),
                    None => self.error(
                        written.span(),
                        messages::comptime_qualifier_slot_not_constant(),
                    ),
                }
            }
        }
    }

    /// [comptime-qualifier] A `comptime qualifier`: its subject is
    /// `std.core.comptime`'s `Field` or `Struct`, it has no body (nothing runs at
    /// compile time to test it), no type parameters and no fn slots, and its
    /// value slots hold constants (`Int`, `Char`, `Str`).
    fn check_comptime_qualifier_decl(&mut self, q: &'p QualifierDecl) {
        let of = match &q.of {
            ast::Type::Named { qualifiers, base } if qualifiers.is_empty() && base.args.is_empty() => {
                Some(base.name.name.as_str())
                    .filter(|n| matches!(*n, "Field" | "Struct"))
                    .filter(|_| self.named(base).structure.is_some_and(|s| s.comptime))
            }
            _ => None,
        };
        if of.is_none() {
            self.error(q.of.span(), messages::comptime_qualifier_subject(&q.of));
        }
        if q.has_body {
            self.error(q.name.span, messages::comptime_qualifier_body(&q.name.name));
        }
        if !q.generics.is_empty() || !q.fn_slots.is_empty() {
            self.error(
                q.name.span,
                messages::comptime_qualifier_generics(&q.name.name, &of.unwrap_or("Field")),
            );
        }
        for v in &q.value_slots {
            let ok = matches!(&v.ty, ast::Type::Named { qualifiers, base }
                if qualifiers.is_empty() && base.args.is_empty() && matches!(base.name.name.as_str(), "Int" | "Char" | "Str"));
            if !ok {
                self.error(v.ty.span(), messages::comptime_qualifier_slot_type(&v.ty));
            }
        }
    }

    fn check_qualifier_decl(&mut self, q: &'p QualifierDecl) {
        if q.comptime {
            self.check_comptime_qualifier_decl(q);
            return;
        }
        self.validate_type(&q.of);
        let of_ty = self.lower_type(&q.of);
        match &of_ty {
            Ty::Union(_) => self.error(q.of.span(), messages::qual_of_union_subject()),
            Ty::Tuple(_) => self.error(q.of.span(), messages::qual_of_tuple_subject()),
            _ => {}
        }
        // [qual-subject] Provenance is mint-only: no inspection of the
        // bits can establish where a handle came from, so a `qualifies`
        // body (and the field overrides that come with one — those are
        // claims about *contents*) is a contradiction.
        if q.subject == QualSubject::Provenance && q.has_body {
            self.error(q.name.span, messages::qual_subject_provenance_body(&q.name.name));
            return;
        }
        if !q.has_body {
            return;
        }
        self.check_whynot_decl(q);
        let Some(qualifies) = q.fns.iter().find(|f| f.name.name == "qualifies") else {
            // [qual-refn-scope] A **constructive** qualifier may still have a
            // body: refinements live in the qualifier that owns the claim, and a
            // mint-only claim has refinements to write like any other (`Sorted`'s
            // insert). What makes a qualifier *predicate* is having a
            // `qualifies`, not having braces — so a body of refinements alone is
            // this shape, not a missing member.
            if !q.refns.is_empty() && q.fns.is_empty() && q.field_overrides.is_empty() {
                return;
            }
            self.error(q.name.span, messages::qual_refn_scope_no_qualifies(&q.name.name));
            return;
        };
        // [col-idx] Implicit parameters trail and are filled where the test is
        // made, so they are not part of the shape.
        let fixed: Vec<&ast::Param> = qualifies.params.iter().filter(|p| !p.implicit).collect();
        if fixed.len() != 1 + q.value_slots.len() {
            // [qual-depend] A dependent predicate takes the subject first,
            // then one parameter per value slot — `KeyOf`'s `qualifies` is
            // `(key: K, map: Map<K, V>)`.
            if q.value_slots.is_empty() {
                self.error(qualifies.name.span, messages::qual_predicate_param_count());
            } else {
                self.error(
                    qualifies.name.span,
                    messages::qual_depend_param_count(&q.value_slots.len()),
                );
            }
        } else {
            let pt = self.lower_type(&fixed[0].ty);
            if !is_subtype(&of_ty, &pt) {
                self.error(fixed[0].span, messages::qual_predicate_param_type(&of_ty));
            }
            // [qual-depend] Each dependency parameter matches its slot's
            // declared type, in slot order.
            for (slot, param) in q.value_slots.iter().zip(fixed.iter().skip(1)) {
                let want = self.lower_type(&slot.ty);
                let got = self.lower_type(&param.ty);
                if !is_subtype(&want, &got) {
                    self.error(
                        param.span,
                        messages::qual_depend_slot_param_type(&slot.name.name, &want),
                    );
                }
            }
        }
        let ret = qualifies
            .return_type
            .as_ref()
            .map(|t| self.lower_type(t))
            .unwrap_or_else(Ty::none);
        if !matches!(&ret, Ty::Named { name, args } if name == "Bool" && args.is_empty()) {
            self.error(qualifies.name.span, messages::qual_predicate_return_type());
        }
        if qualifies.deductions.as_ref().is_some_and(|d| !d.is_empty()) {
            self.error(qualifies.name.span, messages::qual_predicate_deductions());
        }
        for fo in &q.field_overrides {
            self.validate_type(fo.written_ty());
            let override_ty = self.lower_type(fo.written_ty());
            match self.declared_field_ty(&of_ty, &fo.name.name) {
                Some(orig) => {
                    if !is_subtype(&override_ty, &orig) {
                        self.error(
                            fo.span,
                            messages::qual_field_override_not_subtype(
                                &fo.name.name,
                                &override_ty,
                                &orig,
                            ),
                        );
                    }
                }
                None => {
                    if let Ty::Named { name, .. } = of_ty.strip_quals() {
                        if self.symbols.structs.contains_key(name.as_str()) {
                            let name = name.clone();
                            self.error(
                                fo.name.span,
                                messages::qual_field_override_no_field(&name, &fo.name.name),
                            );
                        }
                    }
                }
            }
        }
    }

    /// [deduce-reapply] Validates the `+Q` entries of a fn's own deduction
    /// clause (user decision 2026-09-22, ROADMAP's D2): a claim the function
    /// **re-establishes** rather than preserves, which is what lets a mutator
    /// keep a qualifier its own body strips. Trusted — no `qualifies` runs, as
    /// with `-> T as Q` [qual-ctor-fn] and a refinement [qual-refn] — so the
    /// rules here are the ones that keep the trust honest:
    ///
    /// * the qualifier must be declared **in this file** [qual-ctor-same-file],
    ///   which is the same party we already trust to mint the claim;
    /// * it must be a qualifier the *parameter* declares (that is checked in
    ///   `deduce.rs`, against the written type): re-establishing is not adding;
    /// * written arguments must **agree** with the parameter's, since the claim
    ///   the caller ends up with is the parameter's own [cmp-binder] — a
    ///   different identity would be a different type and belongs in the return
    ///   type, which is what a constructor fn is for;
    /// * a compiler qualifier (`Mut`, `proj`) cannot be re-applied: it is a
    ///   representation choice rather than a claim, and it is not erased.
    fn check_reapplied_deductions(&mut self, f: &'p FnDecl) {
        // [deduce-reapply] [fn-contract] A `=>[g]` group states a *callback's*
        // contract — a claim about a value someone else wrote, with no body here
        // to trust and none there to check. Re-establishing is the declarer's to
        // claim, so it is refused in a group and the remedy is the one that
        // already exists for someone else's function: a refinement.
        for p in &f.params {
            let ast::Type::Fn {
                deductions: Some(list),
                ..
            } = &p.ty
            else {
                continue;
            };
            for d in list {
                let ast::DeductionKind::Exhaustive { reapplied, .. } = &d.kind else {
                    continue;
                };
                for q in reapplied {
                    self.error(
                        q.span,
                        messages::deduce_reapply_group_claim(&q.name.name, &p.name.name),
                    );
                }
            }
        }
        for d in f.deductions.iter().flatten() {
            let ast::DeductionKind::Exhaustive { reapplied, .. } = &d.kind else {
                continue;
            };
            if reapplied.is_empty() {
                continue;
            }
            let Some(param_name) = d.param_name() else {
                for q in reapplied {
                    self.error(q.span, messages::deduce_reapply_no_param(&q.name.name));
                }
                continue;
            };
            let param = f
                .params
                .iter()
                .find(|p| p.name.name == param_name.name)
                .map(|p| self.lower_type(&p.ty));
            // Collected per entry and *inserted*, so running this twice — the
            // signature pre-pass and the signature check — records the same
            // thing once [deduce-reapply].
            let mut established: Vec<Qual> = Vec::new();
            for q in reapplied {
                let name = q.name.name.as_str();
                if matches!(name, "Mut" | "proj" | "ref" | "linear" | "once") {
                    self.error(q.span, messages::deduce_reapply_compiler_qualifier(&name));
                    continue;
                }
                if !self.own_qualifiers.contains(name) {
                    self.error(q.span, messages::deduce_reapply_foreign_qualifier(&name));
                    continue;
                }
                let Some(param_ty) = &param else { continue };
                let empty = HashMap::new();
                let lowered = self.lower_quals(std::slice::from_ref(q), &empty, 0);
                let Some(lowered) = lowered.into_iter().next() else {
                    continue;
                };
                // [deduce-reapply] The claim the *parameter* already carries, if
                // it carries one: then this is a **re-establishment** and the
                // arguments must agree, since the caller's value keeps the type
                // it had. With no such claim this is a fresh **establishment**
                // and the written arguments are the claim.
                let held = param_ty.quals().iter().find(|pq| pq.name == name).cloned();
                match &held {
                    Some(pq) if !q.args.is_empty() && lowered.args != pq.args => {
                        let show = |args: &[Ty]| {
                            args.iter()
                                .map(|a| a.to_string())
                                .collect::<Vec<_>>()
                                .join(", ")
                        };
                        self.error(
                            q.span,
                            messages::deduce_reapply_args_differ(
                                &name,
                                &show(&lowered.args),
                                &param_name.name,
                                &show(&pq.args),
                            ),
                        );
                        continue;
                    }
                    Some(_) => {}
                    None => {
                        // Establishing a claim the parameter does not hold: the
                        // rules a constructor's `as Q` answers to apply here for
                        // the same reason [qual-ctor-fn].
                        if let Some(decl) = self.qualifier_for(name, Some(param_ty)) {
                            if !self.qual_applies(decl, param_ty.strip_quals()) {
                                self.error(
                                    q.span,
                                    messages::deduce_reapply_does_not_apply(
                                        &name,
                                        &param_ty,
                                        &param_name.name,
                                    ),
                                );
                                continue;
                            }
                            // A qualifier with fn slots carries an identity, and
                            // a claim with none is one nothing can use: every
                            // operation that reads the claim binds the slot
                            // [cmp-binder], and an unwritten slot here has
                            // nothing to bind to.
                            if !decl.fn_slots.is_empty() && q.args.is_empty() {
                                let slots: Vec<String> = decl
                                    .fn_slots
                                    .iter()
                                    .map(|s| match s {
                                        ast::SlotDecl::One(one) => format!("?{}", one.name.name),
                                        // A group spread stands for one slot per
                                        // member; its own name is what a reader
                                        // wrote, so it is what the message shows.
                                        ast::SlotDecl::Group(g) => format!("?{}", g.name.name),
                                    })
                                    .collect();
                                self.error(
                                    q.span,
                                    messages::deduce_reapply_no_identity(
                                        &name,
                                        &(if slots.len() == 1 {
                                            "a function"
                                            } else {
                                            "functions"
                                            }),
                                        &slots.join(", "),
                                    ),
                                );
                                continue;
                            }
                        }
                    }
                }
                established.push(lowered);
            }
            // Recorded for the call sites, which substitute this call's type
            // arguments and identities into it.
            if let Some(key) = self.own_fn {
                if !established.is_empty() {
                    self.out
                        .established_quals
                        .insert((key, param_name.name.clone()), established);
                }
            }
        }
    }

    /// Validates a qualifier-constructor signature (`fn f(...) -> T as Q`)
    /// [qual-ctor-fn]: same file as the qualifier [qual-ctor-same-file],
    /// simple return type, `of`-type satisfaction [qual-ctor-simple].
    /// Both constructive and predicate qualifiers may have constructors
    /// [qual-ctor-predicate]: a predicate-qualifier constructor asserts
    /// its predicate holds by construction, so callers get the qualified
    /// type without a runtime `is` check.
    /// [fn-type-named] Rule (c): a type-named fn's return type must have the
    /// named type's base and at least its qualifiers. Base equality plus
    /// named-quals ⊆ return-quals — extra qualifiers on the return are fine
    /// (`fn Heap List<T>` may return `Heap(?cmp) Mut List<T>`). A purely
    /// *provenance* name (`fn Ok<T>` — the "base" is itself a provenance
    /// qualifier) checks only that the qualifier is present on the return.
    fn check_type_named_fn(&mut self, f: &'p FnDecl) {
        let Some(name_ty) = &f.type_name else { return };
        let span = name_ty.span();
        let named = self.lower_type(name_ty);
        // The components the name demands: its qualifier names, and its base
        // name (unless the base is itself a provenance qualifier — the
        // base-less provenance form).
        let named_quals: Vec<String> = named.quals().iter().map(|q| q.name.clone()).collect();
        let named_base = named.strip_quals().clone();
        let base_name = match &named_base {
            Ty::Named { name, .. } => Some(name.clone()),
            _ => None,
        };
        let base_is_provenance = base_name.as_deref().is_some_and(|n| self.is_provenance_qual(n));
        let Some(rt) = &f.return_type else {
            self.error(span, messages::fn_type_named_no_return());
            return;
        };
        let ret = self.lower_type(rt);
        let ret_quals: Vec<String> = ret.quals().iter().map(|q| q.name.clone()).collect();
        // [qual-ctor-fn] A `-> +Q T` establishment parses into `f.constructs`
        // (the `+Q` is lifted out of the return type by the parser), so the
        // named qualifier of a provenance/constructive type-fn shows up there,
        // not on the lowered return `ret`. Treat a constructed qualifier as
        // carried.
        let ctor_qual = f.constructs.as_ref().map(|c| c.name.name.clone());
        let carries =
            |q: &str| ret_quals.iter().any(|r| r == q) || ctor_qual.as_deref() == Some(q);
        // Every named qualifier must be present on the return.
        for q in &named_quals {
            if !carries(q) {
                self.error(
                    rt.span(),
                    messages::fn_type_named_missing_qualifier(&f.name.name, &named, &q),
                );
            }
        }
        // The base must match — unless the name is the base-less provenance
        // form, where the "base" is really a qualifier the return carries.
        if let Some(bn) = &base_name {
            if base_is_provenance {
                // Provenance form: the qualifier (`Ok`) must be on the return,
                // typically as an establishment (`-> +Ok T`).
                let has = carries(bn)
                    || ret.strip_quals().quals().iter().any(|q| &q.name == bn);
                if !has {
                    self.error(
                        rt.span(),
                        messages::fn_type_named_missing_provenance(&f.name.name, &bn),
                    );
                }
            } else {
                let ret_base = match ret.strip_quals() {
                    Ty::Named { name, .. } => Some(name.clone()),
                    _ => None,
                };
                if ret_base.as_deref() != Some(bn.as_str()) {
                    self.error(
                        rt.span(),
                        messages::fn_type_named_wrong_base(&f.name.name, &named, &bn, &ret),
                    );
                }
            }
        } else {
            self.error(span, messages::fn_type_named_no_base());
        }
    }

    fn check_constructor_sig(&mut self, f: &'p FnDecl) {
        let Some(cref) = &f.constructs else { return };
        let name = cref.name.name.as_str();
        let subject = f.return_type.as_ref().map(|t| self.lower_type(t));
        let Some(decl) = self.qualifier_for(name, subject.as_ref()) else {
            self.error(cref.span, messages::qual_ctor_fn_unknown_qualifier(&name));
            return;
        };
        if !self.own_qualifiers.contains(name) {
            self.error(cref.span, messages::qual_ctor_same_file_other_file(&name));
        }
        let Some(rt) = &f.return_type else {
            self.error(cref.span, messages::qual_ctor_fn_no_return());
            return;
        };
        let base = self.lower_type(rt);
        match base.strip_quals() {
            Ty::Union(_) => self.error(rt.span(), messages::qual_ctor_simple_union()),
            Ty::Tuple(_) => self.error(rt.span(), messages::qual_ctor_simple_tuple()),
            other => {
                if !self.qual_applies(decl, other) {
                    self.error(rt.span(), messages::qual_ctor_simple_does_not_apply(&name, &base));
                }
            }
        }
    }

    /// The return type a *caller* sees for a fn: constructors add their
    /// qualifier on top of the declared return type.
    fn fn_return_ty(&mut self, decl: &'p FnDecl) -> Ty {
        let ret = decl
            .return_type
            .as_ref()
            .map(|t| self.lower_type(t))
            .unwrap_or_else(Ty::none);
        match &decl.constructs {
            Some(cref) => {
                // [cmp-carry] Through `lower_quals`, so the claim a constructor
                // mints carries its identity: `-> Mut List<T> as Heap(?cmp)`
                // publishes the ordering the call resolved.
                let empty = HashMap::new();
                let quals = self.lower_quals(std::slice::from_ref(cref), &empty, 0);
                ret.qualify(quals)
            }
            None => ret,
        }
    }
}

/// [deduce-reapply] Every `+Q` written in a type, with its span: the claims
/// a return type says the fn establishes, wherever they sit (a union arm,
/// an optional).
fn established_quals(ty: &ast::Type) -> Vec<(String, Span)> {
    let mut out = Vec::new();
    fn go(ty: &ast::Type, out: &mut Vec<(String, Span)>) {
        match ty {
            ast::Type::Named { qualifiers, base } => {
                for q in qualifiers {
                    if q.established {
                        out.push((q.name.name.clone(), q.span));
                    }
                }
                if base.established {
                    out.push((base.name.name.clone(), base.span));
                }
            }
            ast::Type::QualifiedGroup {
                qualifiers, base, ..
            } => {
                for q in qualifiers {
                    if q.established {
                        out.push((q.name.name.clone(), q.span));
                    }
                }
                go(base, out);
            }
            ast::Type::Union { arms, .. } => {
                for a in arms {
                    go(a, out);
                }
            }
            ast::Type::Nullable { inner, .. } => go(inner, out),
            ast::Type::Array { elem, .. } => go(elem, out),
            ast::Type::Tuple { elems, .. } => {
                for e in elems {
                    go(e, out);
                }
            }
            _ => {}
        }
    }
    go(ty, &mut out);
    out
}

/// Collects names assigned (or incremented) anywhere in a block, for
/// post-branch narrowing resets.
fn collect_assigned(block: &Block, out: &mut HashSet<String>) {
    for stmt in &block.stmts {
        match stmt {
            Stmt::Assign { target, .. } => {
                if let Expr::Ident(id) = target {
                    out.insert(id.name.clone());
                }
            }
            Stmt::Expr(e) | Stmt::Let { value: e, .. } => collect_assigned_expr(e, out),
            _ => {}
        }
    }
}

/// Collects the names assigned anywhere inside `expr` [is-narrow-assign-reset].
///
/// Exhaustive over `Expr` **on purpose**: a wildcard arm here loses
/// assignments inside a new syntactic form silently, and the narrowing that
/// should have been reset stays in place — a wrong-code bug, not a
/// diagnostic. A new variant must be classified, not defaulted.
/// [waitfor-infer] Where a binder is passed as a **positional argument**, as
/// `(callee name, declared parameter index)` pairs.
///
/// A dot-notation call shifts the index by one: `counter.total(out)` is
/// `total(counter, out)` [fn-uniform], so `out` sits at declared index 1. Only
/// direct arguments count — a binder wrapped in another expression says nothing
/// about a `Reply<T>` parameter.
fn collect_binder_arg_sites<'p>(
    block: &'p Block,
    name: &str,
    out: &mut Vec<(&'p str, usize)>,
) {
    fn expr<'p>(e: &'p Expr, name: &str, out: &mut Vec<(&'p str, usize)>) {
        if let Expr::Call { callee, args, .. } = e {
            let (callee_name, shift) = match callee.as_ref() {
                Expr::Ident(id) => (Some(id.name.as_str()), 0),
                // Dot-notation: the receiver is the first declared parameter.
                Expr::Field { field, .. } => (Some(field.name.as_str()), 1),
                // The selectors name the same member: `total@Counter(out)`,
                // `total@core.x(out)`, `k@self(out)` [effect-at]
                // [fn-overload-at] [actor-self-send]. A selector with a
                // receiver is dot-notation, so it shifts too.
                Expr::EffectScoped { base, name, .. } | Expr::Scoped { base, name, .. } => (
                    Some(name.name.as_str()),
                    usize::from(base.is_some()),
                ),
                Expr::SelfScoped { name, .. } => (Some(name.name.as_str()), 0),
                _ => (None, 0),
            };
            if let Some(callee_name) = callee_name {
                for (i, a) in args.iter().enumerate() {
                    if matches!(a, Expr::Ident(id) if id.name == name) {
                        out.push((callee_name, i + shift));
                    }
                }
            }
        }
        // Recurse into the forms that can *contain* a call. Anything not
        // listed simply contributes no site, and the failure mode of a missed
        // shape is the "cannot tell" diagnostic — which names the written form
        // as its remedy — never a wrong inference.
        match e {
            Expr::Call { callee, args, .. } => {
                expr(callee, name, out);
                for a in args {
                    expr(a, name, out);
                }
            }
            Expr::Field { base, .. }
            | Expr::TupleIndex { base, .. }
            | Expr::Unary { operand: base, .. }
            | Expr::IncDec { operand: base, .. }
            | Expr::Spread { operand: base, .. }
            | Expr::Is { subject: base, .. }
            | Expr::Widen { subject: base, .. } => expr(base, name, out),
            Expr::Binary { lhs, rhs, .. } => {
                expr(lhs, name, out);
                expr(rhs, name, out);
            }
            Expr::Elvis { subject, rhs, .. } => {
                expr(subject, name, out);
                expr(rhs, name, out);
            }
            Expr::Pipe { lhs, rhs, .. } | Expr::SafePipe { lhs, rhs, .. } => {
                expr(lhs, name, out);
                expr(rhs, name, out);
            }
            Expr::Index { base, index, .. } => {
                expr(base, name, out);
                expr(index, name, out);
            }
            Expr::Tuple { elems, .. } => {
                for el in elems {
                    expr(el, name, out);
                }
            }
            Expr::If {
                branches,
                else_block,
                ..
            } => {
                for (c, b) in branches {
                    expr(c, name, out);
                    block_walk(b, name, out);
                }
                if let Some(b) = else_block {
                    block_walk(b, name, out);
                }
            }
            Expr::When {
                subject, branches, ..
            } => {
                expr(subject, name, out);
                for br in branches {
                    block_walk(&br.body, name, out);
                }
            }
            Expr::WhenCond {
                branches,
                else_block,
                ..
            } => {
                for (c, b) in branches {
                    expr(c, name, out);
                    block_walk(b, name, out);
                }
                block_walk(else_block, name, out);
            }
            Expr::While { cond, body, .. } => {
                expr(cond, name, out);
                block_walk(body, name, out);
            }
            Expr::For {
                iterable,
                body,
                else_block,
                ..
            } => {
                expr(iterable, name, out);
                block_walk(body, name, out);
                if let Some(b) = else_block {
                    block_walk(b, name, out);
                }
            }
            Expr::Try { body, .. } | Expr::WaitFor { body, .. } => {
                block_walk(body, name, out)
            }
            Expr::Return { value, .. } | Expr::Break { value, .. } => {
                if let Some(v) = value {
                    expr(v, name, out);
                }
            }
            Expr::ReplyTo { captures, .. } => {
                for c in captures {
                    expr(c, name, out);
                }
            }
            _ => {}
        }
    }
    fn block_walk<'p>(b: &'p Block, name: &str, out: &mut Vec<(&'p str, usize)>) {
        for stmt in &b.stmts {
            match stmt {
                Stmt::Let { value, .. } => expr(value, name, out),
                Stmt::Assign { target, value, .. } => {
                    expr(target, name, out);
                    expr(value, name, out);
                }
                Stmt::Use { handler, .. } => expr(handler, name, out),
                Stmt::Expr(e) => expr(e, name, out),
                Stmt::Rename(_) => {}
                // [comptime-inline] Gone before this runs.
                Stmt::Comp(_) => {}
            }
        }
    }
    block_walk(block, name, out);
}

fn collect_assigned_expr(expr: &Expr, out: &mut HashSet<String>) {
    match expr {
        Expr::Assert { cond, message, .. } => {
            collect_assigned_expr(cond, out);
            if let Some(m) = message {
                collect_assigned_expr(m, out);
            }
        }
        Expr::Unreachable { message, .. } | Expr::Todo { message, .. } => {
            if let Some(m) = message {
                collect_assigned_expr(m, out);
            }
        }
        Expr::WhyNot { test, .. } => collect_assigned_expr(test, out),
        // [op-elvis] Both sides may hold assignments (a block-valued branch).
        Expr::Elvis { subject, rhs, .. } => {
            collect_assigned_expr(subject, out);
            collect_assigned_expr(rhs, out);
        }
        // [expr-pipe] Both sides may hold assignments.
        Expr::Pipe { lhs, rhs, .. } | Expr::SafePipe { lhs, rhs, .. } => {
            collect_assigned_expr(lhs, out);
            collect_assigned_expr(rhs, out);
        }
        // [op-safe-nav] The receiver and any call arguments may hold assignments.
        Expr::SafeNav { base, access, .. } => {
            collect_assigned_expr(base, out);
            if let ast::SafeAccess::Call { args, named, .. } = access {
                for a in args {
                    collect_assigned_expr(a, out);
                }
                for n in named {
                    collect_assigned_expr(&n.value, out);
                }
            }
        }
        Expr::Placeholder { .. } => {}
        // [expr-escape] The escapes carry a value expression, which may hold
        // assignments of its own (a block-valued `if`, say).
        Expr::Return { value, .. } | Expr::Break { value, .. } => {
            if let Some(v) = value {
                collect_assigned_expr(v, out);
            }
        }
        Expr::Continue { .. } => {}
        Expr::IncDec { operand, .. } => {
            if let Expr::Ident(id) = operand.as_ref() {
                out.insert(id.name.clone());
            }
            collect_assigned_expr(operand, out);
        }
        Expr::If {
            branches,
            else_block,
            ..
        } => {
            for (c, b) in branches {
                collect_assigned_expr(c, out);
                collect_assigned(b, out);
            }
            if let Some(b) = else_block {
                collect_assigned(b, out);
            }
        }
        Expr::While {
            cond,
            body,
            else_block,
            ..
        } => {
            collect_assigned_expr(cond, out);
            collect_assigned(body, out);
            if let Some(b) = else_block {
                collect_assigned(b, out);
            }
        }
        Expr::For {
            iterable,
            body,
            else_block,
            ..
        } => {
            collect_assigned_expr(iterable, out);
            collect_assigned(body, out);
            if let Some(b) = else_block {
                collect_assigned(b, out);
            }
        }
        Expr::When {
            subject, branches, ..
        } => {
            collect_assigned_expr(subject, out);
            for b in branches {
                collect_assigned(&b.body, out);
            }
        }
        // [when-condition]
        Expr::WhenCond {
            branches,
            else_block,
            ..
        } => {
            for (c, b) in branches {
                collect_assigned_expr(c, out);
                collect_assigned(b, out);
            }
            collect_assigned(else_block, out);
        }
        // [throw-try] The delimiter's body is ordinary code.
        Expr::Try { body, .. } => collect_assigned(body, out),
        // [actor-spawn-expr] Every clause is an ordinary expression, and an
        // argument that crosses to the child may itself assign.
        Expr::Spawn {
            handler,
            with_items,
            pool,
            ..
        } => {
            collect_assigned_expr(handler, out);
            for handler in with_items {
                collect_assigned_expr(handler, out);
            }
            if let Some(pool) = pool {
                collect_assigned_expr(pool, out);
            }
        }
        Expr::Use { handler, with_items, .. } => {
            collect_assigned_expr(handler, out);
            for handler in with_items {
                collect_assigned_expr(handler, out);
            }
        }
        Expr::Project { base, .. } => collect_assigned_expr(base, out),
        Expr::Merge { items, .. } => {
            for i in items {
                collect_assigned_expr(i, out);
            }
        }
        // [actor-replyto] The captures are ordinary expressions.
        Expr::ReplyTo { captures, .. } => {
            for capture in captures {
                collect_assigned_expr(capture, out);
            }
        }
        // [actor-self-send] A leaf: the selector names a handler member.
        Expr::SelfScoped { .. } | Expr::SelfAddr { .. } => {}
        // [actor-waitfor] The bridge's block is ordinary code.
        Expr::WaitFor { body, .. } => collect_assigned(body, out),
        // A lambda body's assignments happen when the value is called, and
        // the checker cannot see where that is: counted here, so a
        // narrowing an enclosing branch relied on is reset conservatively.
        Expr::Lambda { body, .. } => match body {
            LambdaBody::Expr(e) => collect_assigned_expr(e, out),
            LambdaBody::Block(b) => collect_assigned(b, out),
            LambdaBody::Terminal => {}
        },
        Expr::Call { callee, args, .. } => {
            collect_assigned_expr(callee, out);
            for a in args {
                collect_assigned_expr(a, out);
            }
        }
        Expr::Index { base, index, .. } => {
            collect_assigned_expr(base, out);
            collect_assigned_expr(index, out);
        }
        Expr::Binary { lhs, rhs, .. } => {
            collect_assigned_expr(lhs, out);
            collect_assigned_expr(rhs, out);
        }
        Expr::Tuple { elems, .. } => {
            for e in elems {
                collect_assigned_expr(e, out);
            }
        }
        Expr::StructLit { fields, .. } => {
            for f in fields {
                match &f.kind {
                    StructLitFieldKind::Named { value, .. } => collect_assigned_expr(value, out),
                    StructLitFieldKind::Spread(e) => collect_assigned_expr(e, out),
                    // [comptime-inline] Gone before this runs.
                    StructLitFieldKind::InlineFor { .. } => {}
                }
            }
        }
        Expr::Str { parts, .. } => {
            for p in parts {
                if let StrExprPart::Interp(e) = p {
                    collect_assigned_expr(e, out);
                }
            }
        }
        Expr::Field { base, .. } | Expr::TupleIndex { base, .. } => {
            collect_assigned_expr(base, out)
        }
        // [fn-overload-at] `xs.add@core.list(..)`: the receiver is an
        // ordinary expression.
        Expr::Scoped { base, .. } | Expr::EffectScoped { base, .. } => {
            if let Some(base) = base {
                collect_assigned_expr(base, out);
            }
        }
        Expr::Unary { operand, .. }
        | Expr::Spread { operand, .. } => collect_assigned_expr(operand, out),
        Expr::Is { subject, .. } | Expr::Widen { subject, .. } => {
            collect_assigned_expr(subject, out)
        }
        // Leaves: no sub-expression, so nothing can be assigned inside.
        Expr::Int { .. }
        | Expr::Float { .. }
        | Expr::Bool { .. }
        | Expr::Char { .. }
        | Expr::Ident(_)
        | Expr::FieldDefault { .. } | Expr::Error { .. } => {}
    }
}

/// Removes the named qualifiers from a type [qual-lift], or `None` when it
/// does not carry all of them. `Qual T` with every qualifier removed is `T`.
fn strip_quals_named(ty: &Ty, names: &[String]) -> Option<Ty> {
    let Ty::Qualified { quals, base } = ty else {
        return None;
    };
    if !names.iter().all(|n| quals.iter().any(|q| q.name == *n)) {
        return None;
    }
    let kept: Vec<Qual> = quals
        .iter()
        .filter(|q| !names.contains(&q.name))
        .cloned()
        .collect();
    Some(if kept.is_empty() {
        (**base).clone()
    } else {
        (**base).clone().qualify(kept)
    })
}

/// Whether any statement of `block` mentions the variable `name` — the
/// block half of [`expr_mentions`].
fn block_mentions_name(block: &Block, name: &str) -> bool {
    block.stmts.iter().any(|stmt| match stmt {
        Stmt::Let { value, .. } => expr_mentions(value, name),
        Stmt::Assign { target, value, .. } => {
            expr_mentions(target, name) || expr_mentions(value, name)
        }
        Stmt::Use { handler, .. } => expr_mentions(handler, name),
        Stmt::Expr(e) => expr_mentions(e, name),
        _ => false,
    })
}

/// Whether `expr` mentions the variable `name` anywhere — any read,
/// projection base, interpolation, nested branch/loop body, or lambda
/// capture. Used by the IR builder's literal hoisting [flow-use-after-move]:
/// a literal reads every component before it stores, so a component
/// mentioning a local another component stores is evaluated first.
///
/// Exhaustive over `Expr` **on purpose**: a wildcard arm here answers "no"
/// for a form it has never heard of, and a use-after-move goes unreported.
pub(crate) fn expr_mentions(expr: &Expr, name: &str) -> bool {
    let block_mentions = |block: &Block| -> bool { block_mentions_name(block, name) };
    match expr {
        Expr::Assert { cond, message, .. } => {
            expr_mentions(cond, name)
                || message.as_ref().is_some_and(|m| expr_mentions(m, name))
        }
        Expr::Unreachable { message, .. } | Expr::Todo { message, .. } => {
            message.as_ref().is_some_and(|m| expr_mentions(m, name))
        }
        Expr::WhyNot { test, .. } => expr_mentions(test, name),
        Expr::Elvis { subject, rhs, .. } => {
            expr_mentions(subject, name) || expr_mentions(rhs, name)
        }
        Expr::Pipe { lhs, rhs, .. } | Expr::SafePipe { lhs, rhs, .. } => {
            expr_mentions(lhs, name) || expr_mentions(rhs, name)
        }
        // [op-safe-nav] Mentions whatever its receiver or call arguments mention.
        Expr::SafeNav { base, access, .. } => {
            expr_mentions(base, name)
                || match access {
                    ast::SafeAccess::Call { args, named, .. } => {
                        args.iter().any(|a| expr_mentions(a, name))
                            || named.iter().any(|n| expr_mentions(&n.value, name))
                    }
                    ast::SafeAccess::Field(_) => false,
                }
        }
        Expr::Placeholder { .. } => false,
        // [expr-escape] `return x` mentions `x`.
        Expr::Return { value, .. } | Expr::Break { value, .. } => {
            value.as_ref().is_some_and(|v| expr_mentions(v, name))
        }
        Expr::Continue { .. } => false,
        Expr::Ident(id) => id.name == name,
        Expr::Str { parts, .. } => parts.iter().any(|p| match p {
            StrExprPart::Interp(e) => expr_mentions(e, name),
            _ => false,
        }),
        Expr::Field { base, .. } | Expr::TupleIndex { base, .. } => expr_mentions(base, name),
        Expr::Call { callee, args, .. } => {
            expr_mentions(callee, name) || args.iter().any(|a| expr_mentions(a, name))
        }
        Expr::Index { base, index, .. } => expr_mentions(base, name) || expr_mentions(index, name),
        Expr::Tuple { elems, .. } => {
            elems.iter().any(|e| expr_mentions(e, name))
        }
        Expr::StructLit { fields, .. } => fields.iter().any(|f| match &f.kind {
            StructLitFieldKind::Named { value, .. } => expr_mentions(value, name),
            StructLitFieldKind::Spread(e) => expr_mentions(e, name),
            // [comptime-inline] Gone before this runs.
            StructLitFieldKind::InlineFor { .. } => false,
        }),
        Expr::Unary { operand, .. }
        | Expr::IncDec { operand, .. }
        | Expr::Spread { operand, .. } => expr_mentions(operand, name),
        Expr::Binary { lhs, rhs, .. } => expr_mentions(lhs, name) || expr_mentions(rhs, name),
        Expr::Is { subject, .. } | Expr::Widen { subject, .. } => expr_mentions(subject, name),
        Expr::If {
            branches,
            else_block,
            ..
        } => {
            branches
                .iter()
                .any(|(c, b)| expr_mentions(c, name) || block_mentions(b))
                || else_block.as_ref().is_some_and(|b| block_mentions(b))
        }
        Expr::When {
            subject, branches, ..
        } => expr_mentions(subject, name) || branches.iter().any(|b| block_mentions(&b.body)),
        // [when-condition]
        Expr::WhenCond {
            branches,
            else_block,
            ..
        } => {
            branches
                .iter()
                .any(|(c, b)| expr_mentions(c, name) || block_mentions(b))
                || block_mentions(else_block)
        }
        Expr::While {
            cond,
            body,
            else_block,
            ..
        } => {
            expr_mentions(cond, name)
                || block_mentions(body)
                || else_block.as_ref().is_some_and(|b| block_mentions(b))
        }
        Expr::For {
            iterable,
            body,
            else_block,
            ..
        } => {
            expr_mentions(iterable, name)
                || block_mentions(body)
                || else_block.as_ref().is_some_and(|b| block_mentions(b))
        }
        Expr::Lambda { body, .. } => match body {
            LambdaBody::Expr(e) => expr_mentions(e, name),
            LambdaBody::Block(b) => block_mentions(b),
            LambdaBody::Terminal => false,
        },
        // [throw-try] The delimiter's body is ordinary code — a value mentioned
        // only inside it is still mentioned.
        Expr::Try { body, .. } => block_mentions(body),
        // [actor-spawn-expr] A spawn's clauses mention values the same way a
        // call's arguments do — and a value sent to a child is consumed by
        // it, so this must see through every clause.
        Expr::Spawn {
            handler,
            with_items,
            pool,
            ..
        } => {
            expr_mentions(handler, name)
                || with_items.iter().any(|h| expr_mentions(h, name))
                || pool.as_ref().is_some_and(|p| expr_mentions(p, name))
        }
        Expr::Use { handler, with_items, .. } => {
            expr_mentions(handler, name) || with_items.iter().any(|h| expr_mentions(h, name))
        }
        Expr::Project { base, .. } => expr_mentions(base, name),
        Expr::Merge { items, .. } => items.iter().any(|i| expr_mentions(i, name)),
        // [actor-replyto] A capture is a value the continuation takes.
        Expr::ReplyTo { captures, .. } => captures.iter().any(|c| expr_mentions(c, name)),
        // [actor-self-send] A leaf: it mentions no value of its own.
        Expr::SelfScoped { .. } | Expr::SelfAddr { .. } => false,
        // [actor-waitfor] The bridge's block is ordinary code.
        Expr::WaitFor { body, .. } => block_mentions(body),
        // [fn-overload-at] The name is a *function*, never a value; only the
        // dot-notation receiver can mention anything.
        Expr::Scoped { base, .. } | Expr::EffectScoped { base, .. } => {
            base.as_ref().is_some_and(|b| expr_mentions(b, name))
        }
        // Leaves: no sub-expression, so nothing to mention.
        Expr::Int { .. }
        | Expr::Float { .. }
        | Expr::Bool { .. }
        | Expr::Char { .. }
        | Expr::FieldDefault { .. } | Expr::Error { .. } => false,
    }
}

/// Value info about a block's trailing expression (for branch-value
/// coercions applied once the join type is known).
struct TailInfo {
    span: Span,
    logical: Ty,
    repr: Ty,
}

/// Value contributions collected while checking one loop body
/// [loop-while-value].
#[derive(Default)]
struct LoopCtx {
    /// `locals.len()` when the loop was entered: frames at or above this
    /// index die when a `break`/`continue` leaves the iteration
    /// [linear-obligation].
    entry_depth: usize,
    /// `break value` contributions (span of the value expression).
    breaks: Vec<TailInfo>,
    /// A bare `break` or a `continue` occurred: an iteration may end
    /// without producing a value, so `None` joins the loop's value type.
    may_skip_value: bool,
    /// Flow-state snapshot at each `break`: the loop's exit merges these
    /// with the fall-through exit state, so a value consumed on a break
    /// path stays consumed after the loop [deduce-consume].
    break_states: Vec<NarrowSnapshot>,
}

/// A parsed `is` check: qualifiers + optional base type (or `None`).
struct CheckPat {
    quals: Vec<String>,
    /// [qual-depend] Per-qualifier value arguments, indexed as `quals` is:
    /// the places a dependent check fills its slots with (`k is KeyOf(m)`),
    /// each with the span it was written at. Empty for ordinary checks.
    qual_args: Vec<Vec<(String, Span)>>,
    base: Option<Ty>,
    is_none: bool,
    /// A name in the check resolved to nothing and was reported
    /// [name-resolve]: downstream match diagnostics are suppressed.
    unresolved: bool,
}

/// The outcome of analyzing one `is` expression.
struct IsInfo {
    /// The place the subject denotes, when it is one flow analysis tracks
    /// [flow-place]: a variable or a field chain out of one.
    subject_place: Option<Place>,
    /// The physical (declared) type of the subject's storage — the type the
    /// `is` test was lowered against, and the type a narrowed read unwraps
    /// from [flow-place].
    subject_repr: Ty,
    /// Logical type when the check succeeds.
    matched: Ty,
    /// Logical type when the check fails (union subjects only).
    remaining: Option<Ty>,
    binding: Option<Binding>,
}

impl<'p, 'r> Checker<'p, 'r> {
    // ================= widening checks [qual-lift] =================

    /// [op-elvis] `subject ?: rhs` — the first-arm pick (user decision
    /// 2026-10-14). The subject's **first** declared arm becomes the value (a
    /// one-arm sub-union by `[type-rewrap]`) when the subject holds it; `rhs` runs
    /// otherwise with `_` bound to the arms left behind. Widening is allowed —
    /// a `rhs` outside the subject's arms joins into the result — and a
    /// diverging `rhs` narrows the subject to the first arm below
    /// [op-elvis-guard].
    fn check_elvis(
        &mut self,
        subject: &'p Expr,
        rhs: &'p Expr,
        span: Span,
    ) -> Ty {
        let subj_ty = self.check_expr(subject, None);
        if subj_ty.is_unknown() {
            // [type-unknown-lenient] One mistake, one diagnostic.
            let _ = self.check_expr(rhs, None);
            return Ty::Unknown;
        }
        // [op-elvis] The pick keeps the subject's **first arm**, in declared
        // order [type-union-arm-identity]; the rest go to `_`. A non-union subject
        // has one arm, which leaves nothing for the other side — refused like
        // a pointless pick, the same "dead scaffolding" a throw-free `try`
        // gets.
        let declared: Vec<Ty> = match &subj_ty {
            Ty::Union(arms) => arms.clone(),
            _ => vec![subj_ty.clone()],
        };
        if declared.len() < 2 {
            self.error(span, messages::op_elvis_single_arm(&subj_ty));
            let _ = self.check_expr(rhs, None);
            return Ty::Unknown;
        }
        let picked_arms = vec![declared[0].clone()];
        let left_arms = declared[1..].to_vec();
        let picked = self.mk_union(picked_arms.clone());
        let left = self.mk_union(left_arms.clone());
        // The runtime test the emitters need: which of the subject's value
        // arms are on the picked side, and whether the `None` arm is. Only the
        // checker knows the subject's arm identity, and a *call* subject has no
        // recorded representation for an emitter to rebuild it from.
        let value_arms: Vec<&Ty> = subj_ty.value_arms();
        let value_arm_index = |arm: &Ty| -> Option<usize> {
            value_arms.iter().position(|a| *a == arm)
        };
        let picked_value_arms: Vec<usize> =
            picked_arms.iter().filter_map(|a| value_arm_index(a)).collect();
        let picks_none = picked_arms.iter().any(|a| a.is_none_ty());
        self.out.elvis_tests.insert(
            self.key(span),
            PickTest {
                size: value_arms.len(),
                value_arms: picked_value_arms,
                picks_none,
                nullable: subj_ty.has_none_arm(),
            },
        );
        self.out.elvis_picks.insert(self.key(span), picked.clone());
        self.out.pick_left.insert(self.key(span), left.clone());
        // [expr-placeholder] `_` reads as the arms the pick left behind, tags and
        // all.
        let saved = self.placeholder_ty.replace(left.clone());
        // [op-elvis-guard] A leaving right side takes its flow effects with it:
        // a `return elem` there moves `elem` on a path the fall-through never
        // shares, so the consumption must not poison it.
        let entry = self.snapshot_narrows();
        let rhs_ty = self.check_expr(rhs, None);
        self.placeholder_ty = saved;
        // A diverging right side contributes nothing to the type [type-any-never]
        // and *proves* the subject was the picked arm, so the place
        // narrows [op-elvis-guard].
        if matches!(rhs_ty, Ty::Never) {
            self.restore_narrows(&entry);
            let repr = self.repr_of(subject, &subj_ty);
            self.install_elvis_guard(subject, &picked, &repr);
            return picked;
        }
        // Both sides join. The right side is coerced into the join exactly as
        // an `if`'s branches are — and widening past the subject's arms is
        // allowed (`Int? ?: "none"` is `Int | Str`): the picked value is also
        // coerced into the join at the operator's span.
        let join = self.mk_union(vec![picked.clone(), rhs_ty.clone()]);
        let rhs_repr = self.repr_of(rhs, &rhs_ty);
        self.maybe_coerce(rhs.span(), &rhs_ty, &rhs_repr, &join);
        // [type-rewrap] The picked value widens into the join too when `rhs` widened
        // it. Compute that coercion into `elvis_widen` (not the ordinary
        // `coerce` table, whose entry at this span is the Elvis node's own
        // outer coercion): temporarily borrow the `coerce` slot, record, and
        // move the result across.
        if join != picked {
            let key = self.key(span);
            let saved = self.out.coerce.remove(&key);
            self.maybe_coerce(span, &picked, &picked, &join);
            if let Some(c) = self.out.coerce.remove(&key) {
                self.out.elvis_widen.insert(key, c);
            }
            if let Some(outer) = saved {
                self.out.coerce.insert(key, outer);
            }
        }
        join
    }

    /// [expr-pipe] `lhs |> rhs` (user decision 2026-10-14). The left side is
    /// evaluated once and bound to `_`; the right side reads it. The pipe's
    /// type is the right side's. Pure sugar — it reuses the placeholder
    /// machinery the elvis right side uses, so `_` means "the piped value"
    /// here exactly as it means "the arms left behind" there.
    fn check_pipe(&mut self, lhs: &'p Expr, rhs: &'p Expr, _span: Span) -> Ty {
        let lhs_ty = self.check_expr(lhs, None);
        if lhs_ty.is_unknown() {
            // [type-unknown-lenient] One mistake, one diagnostic.
            let saved = self.placeholder_ty.replace(Ty::Unknown);
            let _ = self.check_expr(rhs, None);
            self.placeholder_ty = saved;
            return Ty::Unknown;
        }
        // [expr-placeholder] `_` reads as the whole piped value inside the right
        // side. Record whether the right side actually read it: a pipe whose
        // right side ignores the piped value is dead scaffolding (the same
        // reasoning that refuses a pick keeping every arm) — write a plain
        // statement instead.
        let saw_before = self.placeholder_read;
        self.placeholder_read = false;
        let saved = self.placeholder_ty.replace(lhs_ty.clone());
        let rhs_ty = self.check_expr(rhs, None);
        let read = std::mem::replace(&mut self.placeholder_read, saw_before);
        self.placeholder_ty = saved;
        if !read && !rhs_ty.is_unknown() {
            self.error(rhs.span(), messages::expr_pipe_unused_placeholder());
        }
        rhs_ty
    }

    /// [expr-safe-pipe] `lhs ?> rhs` (user decision 2026-10-14): the null-safe
    /// pipe, `?.`'s analogue, over **any** union. It picks `lhs`'s first arm,
    /// binds `_` to it, runs `rhs`, and replaces that arm with `rhs`'s result
    /// in the union — the other arms pass through unchanged. `(A | B | C) ?>
    /// f(_)` where `f: A -> X` is `X | B | C` (arms collapse). A `T?` recovers
    /// the old behaviour (`X | None`). A **diverging** `rhs` (`x ?> return _`)
    /// leaves only the pass-through arms, since the first-arm path left.
    fn check_safe_pipe(&mut self, lhs: &'p Expr, rhs: &'p Expr, span: Span) -> Ty {
        let lhs_ty = self.check_expr(lhs, None);
        if lhs_ty.is_unknown() {
            // [type-unknown-lenient] One mistake, one diagnostic.
            let saved = self.placeholder_ty.replace(Ty::Unknown);
            let _ = self.check_expr(rhs, None);
            self.placeholder_ty = saved;
            return Ty::Unknown;
        }
        let declared: Vec<Ty> = match &lhs_ty {
            Ty::Union(arms) => arms.clone(),
            _ => vec![lhs_ty.clone()],
        };
        if declared.len() < 2 {
            self.error(span, messages::expr_safe_pipe_single_arm(&lhs_ty));
            let saved = self.placeholder_ty.replace(Ty::Unknown);
            let _ = self.check_expr(rhs, None);
            self.placeholder_ty = saved;
            return Ty::Unknown;
        }
        // `_` is the **first arm**, narrowed, the same pick `?.`'s receiver
        // gets and `?:` keeps.
        let inner = declared[0].clone();
        let rest = self.mk_union(declared[1..].to_vec());
        let saw_before = self.placeholder_read;
        self.placeholder_read = false;
        let saved = self.placeholder_ty.replace(inner);
        let rhs_ty = self.check_expr(rhs, None);
        let read = std::mem::replace(&mut self.placeholder_read, saw_before);
        self.placeholder_ty = saved;
        if !read && !rhs_ty.is_unknown() && !matches!(rhs_ty, Ty::Never) {
            self.error(rhs.span(), messages::expr_safe_pipe_unused_placeholder());
        }
        // A diverging right side: the first-arm path left, so the result is
        // the pass-through arms only ([expr-escape], mirroring `?:`'s
        // elvis-guard).
        if matches!(rhs_ty, Ty::Never) {
            return rest;
        }
        if rhs_ty.is_unknown() {
            return Ty::Unknown;
        }
        // Replace the first arm with `rhs`'s result; `union_of` collapses it
        // into a pass-through arm of the same type ([op-safe-nav]'s arm-collapse,
        // the generalized `Option<Option<T>>` guard).
        self.mk_union(vec![rhs_ty, rest])
    }
    /// one `is` of the same qualifiers performs — same arm, same lowering —
    /// but the matched type is *generalized* (the qualifiers removed) rather
    /// than refined, so the subject reads without them inside the branch.
    fn widen_info(
        &mut self,
        subject: &'p Expr,
        quals: &'p [TypeRef],
        binding: Option<&'p Ident>,
        span: Span,
    ) -> IsInfo {
        let subj_ty = self.check_expr(subject, None);
        let repr = self.repr_of(subject, &subj_ty);
        let pat = self.parse_check(quals, Some(&subj_ty));
        // Same places `is` narrows [flow-place]: a variable or a field chain
        // out of a tracked local (user decision 2026-09-05: consistent with
        // `is`).
        let subject_place =
            Place::of_expr(subject).filter(|p| p.narrowable() && self.lookup(&p.root).is_some());
        let unchanged = IsInfo {
            subject_place: None,
            subject_repr: repr.clone(),
            matched: subj_ty.clone(),
            remaining: None,
            binding: None,
        };
        if pat.unresolved {
            return unchanged;
        }
        // `^` removes qualifiers: a base type in the check would be an `is`
        // question, not a widening one.
        if pat.base.is_some() || pat.is_none {
            self.error(span, messages::qual_lift_not_qualifiers());
            return unchanged;
        }
        if pat.quals.is_empty() {
            self.error(span, messages::qual_lift_nothing_named());
            return unchanged;
        }
        // [qual-lift] The single exclusion list, shared with `Qual T <: T`.
        let mut blocked = false;
        for q in &pat.quals {
            if let Some(reason) = self.removal_block(q) {
                self.error(span, messages::qual_lift_cannot_remove(&q, &reason));
                blocked = true;
            }
        }
        if blocked {
            return unchanged;
        }
        // The same runtime test `is` would emit; absent for a tautology (the
        // qualifiers are statically present), where the check is `true`.
        if let Some(test) = self.union_test_for(&repr, &pat) {
            self.out.is_tests.insert(self.key(span), test);
        }
        let mut multi_arm = false;
        let (matched, remaining) = match &subj_ty {
            Ty::Union(arms) => {
                let (m, r): (Vec<Ty>, Vec<Ty>) = arms
                    .iter()
                    .cloned()
                    .partition(|arm| self.arm_matches(arm, &pat));
                multi_arm = m.len() > 1;
                if m.len() > 1 && binding.is_none() {
                    // [qual-lift] Each arm peels a *different* wrapper
                    // position, so re-reading the subject cannot stand for all
                    // of them — but a **binding** can (user decision
                    // 2026-09-21): the lifted value is materialized once, into
                    // a name, so several arms may be lifted at a time there.
                    // The diagnostic names that remedy.
                    self.error(
                        span,
                        messages::qual_lift_several_arms(&pat.quals.join(" ^"), &subj_ty),
                    );
                    return unchanged;
                }
                let stripped: Vec<Ty> = m
                    .iter()
                    .filter_map(|arm| strip_quals_named(arm, &pat.quals))
                    .collect();
                if stripped.len() != m.len() || m.is_empty() {
                    self.error(
                        span,
                        messages::qual_lift_no_arm_carries(&subj_ty, &pat.quals.join(" ")),
                    );
                    return unchanged;
                }
                (self.mk_union(stripped), Some(self.mk_union(r)))
            }
            other => match strip_quals_named(other, &pat.quals) {
                // Statically present: the check cannot fail, and the else
                // branch learns nothing.
                Some(stripped) => (stripped, None),
                None => {
                    if !other.is_unknown() && !matches!(other, Ty::Never) {
                        self.error(
                            span,
                            messages::qual_lift_not_carried(&other, &pat.quals.join(" ")),
                        );
                    }
                    return unchanged;
                }
            },
        };
        // [qual-lift] Inside the branch the value is seen *at* the widened
        // type: the arm test peeled the wrapper, so a further `is`/`when` on
        // the subject must narrow relative to the stripped type, not to the
        // storage it came out of. (The emitters materialize the peel as a
        // branch-local temporary.)
        let subject_repr = if self.out.is_tests.contains_key(&self.key(span)) {
            self.out
                .widen_targets
                .insert(self.key(span), matched.clone());
            matched.clone()
        } else {
            repr
        };
        // [qual-lift] A **multi-arm** lift narrows nothing: re-reading the
        // subject is exactly what cannot stand for several arms, so the lifted
        // value lives only in the binding and the subject keeps its declared
        // type inside the branch. (Single-arm lifts narrow the place as they
        // always did.)
        let subject_place = if multi_arm { None } else { subject_place };
        // [qual-lift] `is ^Ok inner` binds the **lifted** value to a fresh
        // name for the branch (user decision 2026-09-21). It is the same
        // binding an `is Type name` makes, at the lifted type, and it shares
        // fate with the subject [fate-link] — so a multi-arm lift has exactly
        // one place to live, which is what makes it legal above.
        let binding = binding.map(|b| {
            let bty = matched.clone();
            self.out.expr_ty.insert(self.key(b.span), bty.clone());
            // [type-rewrap] A **multi-arm** lift binds a value of a *smaller* union
            // than the storage, so it is not a payload read: the emitters map
            // arm to arm. Recorded against the binding, which is where they
            // build it.
            if self.ty_own_linear(&bty) {
                self.out.linear_moves.insert(self.key(b.span));
            }
            let links = self.links_for_value(subject, b.span);
            (b.clone(), bty, links, None)
        });
        IsInfo {
            subject_place,
            subject_repr,
            matched,
            remaining,
            binding,
        }
    }

    // ================= blocks & statements =================

    /// Checks a block in value position: returns its value type (last
    /// expression, `Never` after return/break/continue, else `None`).
    fn check_block_value(&mut self, block: &'p Block) -> Ty {
        self.check_branch_block(block, Vec::new()).0
    }

    /// [var-unused] Warns for locals in the scope about to close that were
    /// never read. A leading `_` opts out — the conventional way to say "I
    /// know, and I mean it" — and so do parameters (a signature often
    /// dictates them, especially an effect or handler member implementing a
    /// declared interface) and handler state. std is exempt: its unused
    /// bindings are the compiler's business, not the user's.
    ///
    /// A *warning*, not an error: an unused variable is a smell, and the
    /// program it appears in is still well-defined.
    fn warn_unused_locals(&mut self) {
        if self.is_std {
            return;
        }
        let Some(frame) = self.locals.last() else {
            return;
        };
        let mut unused: Vec<(String, Span)> = frame
            .iter()
            .filter(|(name, var)| {
                !var.used && !var.is_param && !var.is_handler_state && !name.starts_with('_')
            })
            .map(|(name, var)| (name.clone(), var.decl_span))
            .collect();
        // Deterministic order: frames are hash maps, and a diagnostic list
        // that reorders between runs is not comparable in tests.
        unused.sort_by_key(|(_, span)| span.order_key());
        for (name, span) in unused {
            let msg = messages::var_unused_never_used(&name);
            // [comptime-copy-warn] In a copy of an expanded-in-place fn,
            // counted against the copies that declared it: reported once,
            // and only if no copy used it.
            if let Some(at) = self.in_place_written(span) {
                let (id, text) = msg.into_message();
                let entry = self.copy_unused.entry((at.start, at.end)).or_insert((0, id, text));
                entry.0 += 1;
                continue;
            }
            self.warn(span, msg);
        }
    }

    /// Checks a block with `is`-bindings pre-declared in its scope.
    fn check_branch_block(
        &mut self,
        block: &'p Block,
        bindings: Vec<Binding>,
    ) -> (Ty, Option<TailInfo>) {
        self.locals.push(HashMap::new());
        // [effect-scope] `use` registrations expire with the block.
        let effect_depth = self.effect_env.len();
        // [fn-rename] So do renames: a `rename fn` is in force from its line
        // to the end of the block it is written in — including a loop body or
        // a lambda body, which are blocks like any other.
        let rename_depth = self.renames.len();
        for binding in bindings {
            self.declare_binding(binding);
        }
        let mut value = Ty::none();
        let mut tail = None;
        // [expr-dead-code] The first statement reached only after a diverging one
        // (`return`, `break`, `continue`, `throw`, `unreachable!()`,
        // `todo!()` — all `Never`-typed) is unreachable. Warn once per block,
        // on that first dead statement; std is exempt, like other smells.
        let mut diverged = false;
        // [fn-overload-return] R-3: a value branch's tail is where the value
        // goes, so its call may be chosen by the branch's expected type.
        let tail_hint = self.tail_hint.take();
        let last = block.stmts.len().saturating_sub(1);
        for (si, stmt) in block.stmts.iter().enumerate() {
            if diverged && !self.is_std {
                self.warn(stmt.span(), messages::expr_dead_code_unreachable());
                diverged = false; // one warning per run of dead code
            }
            if si == last {
                if let (Some(h), Stmt::Expr(Expr::Call { .. })) = (&tail_hint, stmt) {
                    self.select_hint = Some(h.clone());
                }
            }
            value = self.check_stmt(stmt);
            self.select_hint = None;
            if matches!(value, Ty::Never) {
                diverged = true;
            }
            tail = match stmt {
                Stmt::Expr(e) => Some(TailInfo {
                    span: e.span(),
                    logical: value.clone(),
                    repr: self.repr_of(e, &value),
                }),
                _ => None,
            };
        }
        // [ir-analyze] The linear-obligation leak check moved to the IR.
        self.warn_unused_locals();
        self.locals.pop();
        self.effect_env.truncate(effect_depth);
        self.renames.truncate(rename_depth);
        (value, tail)
    }

    fn check_stmt(&mut self, stmt: &'p Stmt) -> Ty {
        match stmt {
            // [fn-rename] In force from here to the end of the block.
            Stmt::Rename(decl) => {
                self.declare_rename(decl, true);
                Ty::none()
            }
            // [comptime-inline] A comptime statement outside a `compfn` is a
            // parse error; inside one, the expansion removed it. Reaching here
            // means the expansion did not run, which every driver arranges.
            Stmt::Comp(c) => {
                self.error(c.span(), messages::comptime_inline_not_expanded());
                Ty::none()
            }
            Stmt::Let {
                pattern,
                ty,
                value,
                span,
            } => {
                if let Some(t) = ty {
                    let saved = std::mem::replace(&mut self.let_pattern, true);
                    self.validate_type(t);
                    self.let_pattern = saved;
                }
                let annotated = ty.as_ref().map(|t| self.lower_type(t));
                let value_ty = self.check_expr(value, annotated.as_ref());
                if let Some(ann) = &annotated {
                    // [type-literal] A value outside a literal union's list
                    // is reported once, by the coercion, naming the values.
                    let listed_elsewhere = crate::literal::mentions_lit(ann)
                        && literal_refusal(ann, &value_ty, self.lit_spans.get(&self.key(value.span()))).is_some();
                    if !is_subtype(&value_ty, ann) && !listed_elsewhere {
                        let what = match value {
                            Expr::Ident(id) => format!("`{}`", id.name),
                            _ => "this fn value".to_string(),
                        };
                        let why = consumed_borrow_hint(&value_ty, ann, &what).map(|h| format!(": {h}")).unwrap_or_default();
                        self.error(
                            value.span(),
                            messages::var_let_infer_annotation_mismatch(&ann, &value_ty, &why),
                        );
                    }
                }
                let declared = annotated
                    .map(|ann| fill_unwritten_args(&ann, &value_ty))
                    .unwrap_or_else(|| {
                        // [var-let-infer] Without an annotation the *logical* value
                        // type becomes
                        // the declared type; re-wrap narrowed unions physically.
                        let repr = self.repr_of(value, &value_ty);
                        self.maybe_coerce(value.span(), &value_ty, &repr, &value_ty.clone());
                        value_ty.clone()
                    });
                // [proj-anywhere] A view of a temporary cannot be kept.
                self.reject_temp_view(value, "bind");
                // Binding from a bare identifier or projection links the
                // new variable(s) to the source: they share fate
                // [fate-link].
                let links = self.links_for_value(value, *span);
                // [ref-handle] Remember a local bound from a reader's
                // borrow: a mint returning it would be recovering a position.
                if let Pattern::Ident(id) = pattern {
                    if let Some(reader) = self.reader_call(value) {
                        self.reader_bound.insert(id.name.clone(), reader);
                    } else {
                        self.reader_bound.remove(&id.name);
                    }
                }
                self.declare_pattern(pattern, declared, links);
                Ty::none()
            }
            Stmt::Assign {
                target,
                value,
                span,
            } => {
                let target_ty = match target {
                    Expr::Ident(id) => match self.lookup(&id.name) {
                        Some(var) => var.declared.clone(),
                        None => {
                            self.error(
                                id.span,
                                messages::name_resolve_assign_undeclared(&id.name),
                            );
                            Ty::Unknown
                        }
                    },
                    other => {
                        // [op-assign] A target has to be a **place** — a
                        // variable, a field path, a subscript. Assigning to
                        // anything else used to be accepted here and then
                        // rejected by the target compiler (rustc's E0070 for
                        // `f(x) = 1`), a [backend-never-wrong] violation found
                        // 2026-09-22 while adding `+=`, which inherits every
                        // rule of the assignment it desugars to.
                        let place_ok = is_assignable_place(other);
                        if !place_ok {
                            self.error(other.span(), messages::op_assign_not_a_place());
                        }
                        // [flow-place-invalidate] A narrowed place is
                        // assigned at its declared type, as a narrowed local
                        // is: the assignment ends the narrowing, it does not
                        // write through it.
                        let declared = Place::of_expr(other).and_then(|p| self.place_narrow_entry(&p)).map(|e| e.declared.clone());
                        let ty = self.check_expr(other, None);
                        let ty = declared.unwrap_or(ty);
                        // A target that is not a place has been reported:
                        // what it would mutate is nothing, so no permission
                        // or fate check applies (one mistake, one
                        // diagnostic) [op-assign].
                        if !place_ok {
                            ty
                        } else {
                        // [struct-mut] Only `Mut`-qualified struct values
                        // may have fields assigned.
                        if let Expr::Field { base, field, .. } = other {
                            let base_ty = self
                                .out
                                .ty_of(self.file_idx, base.span())
                                .cloned()
                                .unwrap_or(Ty::Unknown);
                            let is_struct = matches!(
                                base_ty.strip_quals(),
                                Ty::Named { name, .. }
                                    if self.symbols.structs.contains_key(name.as_str())
                            );
                            let has_mut = base_ty.quals().iter().any(|q| q.name == "Mut");
                            if is_struct && !has_mut {
                                self.error(
                                    field.span,
                                    messages::struct_mut_immutable_field_assign(
                                        &field.name,
                                        &base_ty,
                                    ),
                                );
                            }
                        }
                        // [expr-tuple-index] A tuple element is never
                        // assignable: qualifiers — `Mut` among them —
                        // cannot apply to a tuple [qual-union-arm], so no
                        // tuple value can grant mutation permission.
                        if let Expr::TupleIndex { index, span, .. } = other {
                            self.error(*span, messages::expr_tuple_index_assign(&index));
                        }
                        // Assigning through a projection mutates the root
                        // variable [fate-poison]; mutating a derived
                        // variable is an error [fate-derived-readonly].
                        // Narrowings of the overwritten storage fall
                        // [flow-place-invalidate].
                        // [deduce-field] An assignment **replaces** what is
                        // there, so it is not a contents-only event: a
                        // handle to the old value does not survive it.
                        self.fate_mutation_through_kind(other, *span, false);
                        ty
                        }
                    }
                };
                let value_ty = self.check_expr(value, Some(&target_ty));
                // [var-no-widen] assignments must fit the declared type.
                if !is_subtype(&value_ty, &target_ty) {
                    self.error(
                        value.span(),
                        messages::var_no_widen_assign_mismatch(&value_ty, &target_ty),
                    );
                } else if let Expr::Ident(id) = target {
                    let value_ty = value_ty.clone();
                    // [proj-local] A variable of a projected type holds a
                    // borrow, and an owned value cannot be stored in one:
                    // `X <: proj X` lets an owned value *stand* where a borrow
                    // is read, but a variable has to be one or the other for
                    // the whole of its life. The program says which, once,
                    // where the variable is declared (user decision
                    // 2026-10-20: "a specific operation (copy()) which gives
                    // the more specific type from the more general").
                    if holds_top_borrow(&target_ty) && !holds_top_borrow(&value_ty) && !value_ty.is_none_ty() && !value_ty.is_unknown() && !matches!(value_ty, Ty::Never) {
                        self.error(
                            value.span(),
                            messages::proj_local_owned_into_borrow(&id.name, &target_ty, &value_ty),
                        );
                    }
                    // [fn-param-const] A parameter is a constant binding.
                    self.reject_param_assignment(&id.name, id.span, "assign to");
                    // [linear-obligation] Overwriting a variable that
                    // still owns a linear value drops it: the IR's ledger
                    // reports it (`ir::check`; a state field, `ir::flow`).
                    // [effect-state-store] Assigning into a handler *state*
                    // field is a **store**, not a binding: the field
                    // outlives every member call, so the handler takes
                    // ownership — exactly as a struct literal does. A
                    // *link* here would outlive the call it was made in,
                    // which Kotlin can represent (aliasing) and Rust
                    // cannot; before this rule the Rust backend silently
                    // cloned, and mutable data diverged observably between
                    // the backends.
                    let is_state = self
                        .lookup(&id.name)
                        .is_some_and(|var| var.is_handler_state);
                    if is_state {
                        self.reply_escape(value, "storing it in state");
                        self.fate_move(value, "store", value.span());
                    }
                    // Reassignment: the variable's old value is gone, so
                    // variables derived from it are poisoned
                    // [fate-poison]; the variable itself revives with
                    // fresh links to the new value's sources [fate-link].
                    // An assignment is a bind event: move-mode applies
                    // [fate-move-mode].
                    let links = if is_state {
                        Vec::new()
                    } else {
                        self.links_for_value(value, *span)
                    };
                    // [fate-poison] [fate-move-mode] What the IR flow pass
                    // poisons it by, and decides its mode from. (The old
                    // value's derivatives are poisoned by the flow pass,
                    // which sees the reassignment.)
                    let root_var_id = self.lookup(&id.name).map(|var| var.id);
                    self.record_fate_bind(id.span, &links);
                    // [qual-depend] The old value is gone, so every
                    // dependent claim bound to it describes a value that no
                    // longer exists: reassignment strips them exactly as
                    // mutation does. (Before this, an `Idx(xs)` claim held
                    // across `xs = [9]` kept resolving the total `get` — a
                    // checked out-of-bounds read; defect fixed 2026-09-24.)
                    self.strip_dependent_claims(&id.name, &[]);
                    // [fate-elem-distinct] And element identities minted from the
                    // old value die with it.
                    if let Some(var_id) = root_var_id {
                        self.erase_elem_identities(var_id);
                    }
                    if let Some(var) = self.lookup_mut(&id.name) {
                        var.narrowed = value_ty;
                        var.links = links;
                        // The old value is gone: every fact about its
                        // parts falls with it [flow-place-invalidate].
                        var.place_narrows.clear();
                    }
                }
                Ty::none()
            }
            Stmt::Use {
                handler,
                with_items,
                any,
                span,
            } => {
                // [effect-use-requires-use] only `[use]` fns may register handlers.
                if !self.can_use {
                    self.error(*span, messages::effect_use_requires_use_missing());
                }
                self.check_use(handler, with_items, *any, *span);
                Ty::none()
            }
            Stmt::Expr(e) => {
                let ty = self.check_expr(e, None);
                // [linear-obligation] A linear value in statement
                // position is dropped on the spot.
                if self.ty_own_linear(&ty) {
                    self.error(e.span(), messages::linear_obligation_dropped_statement());
                }
                ty
            }
        }
    }

    fn declare_pattern(&mut self, pattern: &Pattern, ty: Ty, links: Vec<FateLink>) {
        for binding in self.pattern_bindings(pattern, ty, links, None) {
            self.declare_binding(binding);
        }
    }

    /// Declares one branch/loop binding (name, type, inherited links,
    /// `for`-loop origin) [fate-link] [fate-move-mode].
    fn declare_binding(&mut self, (ident, ty, links, for_origin): Binding) {
        self.declare_var(&ident, ty, links, false, for_origin);
    }

    /// Flattens a binding pattern into the `(name, type, links)` triples
    /// it declares [fate-link]. Loop bindings go through this so each
    /// checking pass of a loop body re-declares them fresh — an iteration
    /// binds a *new* element, so consumption of the binding never
    /// survives the back edge [deduce-consume].
    fn pattern_bindings(
        &mut self,
        pattern: &Pattern,
        ty: Ty,
        links: Vec<FateLink>,
        for_origin: Option<Span>,
    ) -> Vec<Binding> {
        match pattern {
            Pattern::Ident(id) => vec![(id.clone(), ty, links, for_origin)],
            Pattern::Tuple { elems, span } => {
                // A pattern is not an expression, but it *has* a type — the
                // subject's — and both tooling (hover) and the emitters read it
                // by span: a destructuring loop binds the element to a
                // temporary whose declared type this is.
                self.out
                    .expr_ty
                    .entry(self.key(*span))
                    .or_insert_with(|| ty.clone());
                // [var-let-destructure] The subject has to *be* a tuple of this
                // arity. Until 2026-09-18 a mismatch bound `Unknown`s and said
                // nothing, so `let (a, b) = 7` compiled and the emitters
                // produced target code that could not build — a Salvo mistake
                // reported, at best, by rustc or kotlinc.
                //
                // `Unknown` still passes silently [type-unknown-lenient]: one
                // mistake, one diagnostic.
                let elem_tys: Vec<Ty> = match ty.strip_quals() {
                    Ty::Tuple(ts) if ts.len() == elems.len() => ts.clone(),
                    Ty::Unknown | Ty::Never => vec![Ty::Unknown; elems.len()],
                    other => {
                        let what = match other {
                            Ty::Tuple(ts) => format!(
                                "`{ty}` is a tuple of {}, not {}",
                                ts.len(),
                                elems.len()
                            ),
                            _ => format!("`{ty}` is not a tuple"),
                        };
                        self.error(
                            *span,
                            messages::var_let_destructure_arity(&elems.len(), &what),
                        );
                        vec![Ty::Unknown; elems.len()]
                    }
                };
                elems
                    .iter()
                    .zip(elem_tys)
                    .flat_map(|(p, t)| self.pattern_bindings(p, t, links.clone(), for_origin))
                    .collect()
            }
            Pattern::Struct { fields, span } => {
                self.out
                    .expr_ty
                    .entry(self.key(*span))
                    .or_insert_with(|| ty.clone());
                // [struct-opaque] Destructuring reads every named field.
                self.refuse_opaque(&ty, "destructuring it", *span);
                fields
                .iter()
                .map(|f| {
                    // [var-let-destructure] Destructuring reads the declared
                    // field type (qualifier overrides only apply to direct
                    // field accesses, which the backend can cast).
                    let fty = self
                        .declared_field_ty(&ty, &f.field.name)
                        .unwrap_or(Ty::Unknown);
                    // Each destructured binding is a projection of the
                    // source: it shares the source's fate [fate-link].
                    (f.binding.clone(), fty, links.clone(), for_origin)
                })
                .collect()
            }
        }
    }

    /// Handles a move-position value — `return x`, `break x`, `yield x`,
    /// a struct/array/tuple literal store, spread `...x`, or a `use`
    /// handler-constructor argument [deduce-consume]. Only bare
    /// identifiers (through spread) are tracked. Moving a fate-linked
    /// (derived) variable is an error [fate-derived-readonly] — `copy`
    /// is the remedy; moving a root consumes it (narrows to `Never`; the
    /// use-site diagnostic is the IR flow pass's [flow-use-after-move]) and
    /// poisons its derived variables [fate-poison], exactly like a
    /// call-site move.
    /// [linear-container] Records a read that **moves a linear value**, so the
    /// emitters hand it over rather than copy it: Rust's narrowed-read path
    /// clones through a borrow, which duplicates an obligation — and a reply
    /// token is not `Clone` at all. Called from both consumption paths (the
    /// deduction-driven one at a call, and `fate_move`) while the variable's
    /// live type is still readable, i.e. before it is marked consumed.
    fn note_linear_move(&mut self, name: &str, span: Span) {
        let live = self.lookup(name).map(|v| {
            if matches!(v.narrowed, Ty::Unknown) {
                v.declared.clone()
            } else {
                v.narrowed.clone()
            }
        });
        if live.is_some_and(|t| self.ty_own_linear(&t)) {
            self.out.linear_moves.insert(self.key(span));
        }
    }

    fn fate_move(&mut self, value: &Expr, action: &str, span: Span) {
        // [proj-anywhere] Returning or storing a view of a temporary. Driving
        // one (`for x in iter(List(1, 2))`) is allowed — and the Rust
        // backend earns it by hoisting the temporary into a local in front of
        // the loop [rs-loop-temp], since the loop *binds* the pass and a Rust
        // temporary would die at the end of the statement (E0716). The claim
        // this comment used to make — that the temporary lives for the whole
        // loop statement on both backends — was simply false, and the emitted
        // program did not compile (fixed 2026-09-25).
        if action != "iterate" {
            self.reject_temp_view(value, action);
        }
        let inner = match value {
            Expr::Spread { operand, .. } => operand.as_ref(),
            _ => value,
        };
        let Expr::Ident(id) = inner else {
            // [proj-anywhere] A *value* that borrows — the result of a
            // derived-return call (`iter(bag.items)`, `first(xs)`) or a
            // literal with `proj` fields — cannot be moved out: it is a view
            // of something the caller keeps, and moving it (a `return`, a
            // store) would let the view outlive what it borrows. The remedy
            // is the same as for a derived variable: `copy`.
            if matches!(inner, Expr::Call { .. } | Expr::StructLit { .. }) {
                let links = self.links_for_value(inner, span);
                // [proj-infer] A value that *holds* borrows (a pass minted
                // here) is an owned object and may travel — into a caller,
                // a field, a consuming parameter — as long as it does not
                // outlive its roots: returned, it may be rooted only in the
                // parameters this fn lends.
                if !links.is_empty() && links.iter().all(|l| l.held) {
                    if action == "return" {
                        self.check_returned_view_roots(&links, inner.span());
                    }
                    return;
                }
                if let Some(l) = links.first() {
                    let root = l.root_name.clone();
                    // Inside a fn that *itself* returns a borrow of that root,
                    // returning the view is the declared contract — the
                    // derived-return validation covers it.
                    if action == "return" && self.own_derived_sources.iter().any(|s| s == &root) {
                        return;
                    }
                    self.error(
                        inner.span(),
                        messages::fate_derived_readonly_view_moved(&action, &root),
                    );
                    return;
                }
            }
            // A projection in a moved position moves data out of its
            // provenance roots [fate-move-mode].
            self.projection_move(inner, span);
            return;
        };
        let Some(var) = self.lookup(&id.name) else {
            return;
        };
        // [copy-scalar-free] Moving a Copy scalar is a copy: a store, a
        // `return`, a spread or a `use` argument leaves the source standing.
        if crate::types::moves_for_free(&var.declared) {
            return;
        }
        let (var_id, links) = (var.id, var.links.clone());
        let name = id.name.clone();
        // [effect-state-store] A handler's **storage** — a state field or a
        // constructor parameter — outlives every member call, so a member
        // cannot move a value out of it: the handler still owns it after the
        // call returns. The mirror of the store rule, and owed for the same
        // reason it was: the two backends cannot agree otherwise. Rust
        // silently `.clone()`d (so the handler kept a *copy* and mutable data
        // diverged observably — and a `linear` value had its obligation
        // duplicated), Kotlin shared the reference, and where the clone was
        // missing — the consuming *intrinsics*, `send` and `add` — rustc
        // reported a raw E0507 with no Salvo diagnostic at all. Found
        // 2026-09-15; a `Copy` state field hides every part of it.
        //
        // `copy` is the remedy, and the diagnostic says so — except for a
        // linear value, which has none: taking one out of a composite is the
        // interim refusal [linear-composite], and here the composite is the
        // handler.
        if self.consume_of_handler_storage(&name, action, id.span) {
            return;
        }
        if !links.is_empty() {
            // [proj-infer] A held view travels as an owned object (see the
            // value case above); a wholesale projection or alias cannot.
            if links.iter().all(|l| l.held) {
                if action == "return" {
                    self.check_returned_view_roots(&links, id.span);
                }
            } else if !self.note_derived_use(id.span, action, &name, &links) {
                return;
            }
        }
        // A lambda cannot consume a capture [fate-lambda].
        if let Some(frame) = self.frame_of_id(var_id) {
            if self.capture_move_violation(frame, &name, id.span) {
                return;
            }
        }
        // A kept lambda parameter belongs to the caller [fn-contract].
        if self.consume_kept_lambda_param(&name, id.span) {
            return;
        }
        self.note_linear_move(&name, id.span);
        // [flow-use-after-move] The IR reads this one as a move.
        self.out.moved_reads.insert(self.key(id.span));
    }
    /// [effect-state-store] Is `name` one of the *enclosing handler's* stored
    /// values — a state field or a constructor parameter — being consumed?
    /// Reports if so and answers whether it did.
    ///
    /// Both kinds are storage the handler keeps across every activation, so a
    /// member has nothing to move out of: what the caller of the member would
    /// leave behind is a handler with a hole in it. The remedy is `copy`, and
    /// a linear value has none.
    fn consume_of_handler_storage(&mut self, name: &str, action: &str, span: Span) -> bool {
        let Some(h) = self.own_handler else {
            return false;
        };
        let kind = if h.state.iter().any(|f| f.name.name == name) {
            "state field"
        } else if h.params.iter().any(|p| p.name.name == name) {
            "constructor parameter"
        } else {
            return false;
        };
        let ty = self
            .lookup(name)
            .map(|v| v.declared.clone())
            .unwrap_or(Ty::Unknown);
        // [copy-scalar-free] A native scalar's copy is free and
        // indistinguishable from a move, so a member may hand one over: the
        // handler keeps its own, both backends agree, and nothing is cloned
        // that the reader would care about. This is the exemption the
        // deduction rules already grant, and it is why the first asynchronous
        // test (`sum: Int`) never saw the rule below.
        if crate::types::is_copy_scalar(&ty.strip_quals()) {
            return false;
        }
        // [linear-composite] Linearity is deliberately *not* transitive
        // through composites, so the type's own obligation is the whole
        // question here.
        let linear = self.ty_own_linear(&ty);
        let handler = h.name.name.clone();
        // [linear-state] LC-4 (user decision 2026-09-15): a **state field**
        // holding an obligation may be moved out of — that is how a queue of
        // parked tokens is drained — provided the activation puts something
        // back before it returns (the IR flow pass checks every exit,
        // `ir::flow`). The actor owns the obligation across activations;
        // what is forbidden is
        // leaving a hole in state a later activation would read. A
        // *constructor parameter* stays refused: it is the handler's own
        // record of how it was built, and nothing can restore it.
        if linear && kind == "state field" {
            // [linear-state] [rs-state-take] Recorded for the emitters: on
            // Rust a field cannot simply be moved out of `&mut self`, so the
            // read becomes a `std::mem::take` — which is also exactly the
            // semantics (the field is empty until the member puts something
            // back, and the checker made it).
            self.out.state_takes.insert(self.key(span));
            return false;
        }
        if linear {
            self.error(
                span,
                messages::linear_composite_handler_storage(&action, &name, &kind, &handler),
            );
        } else {
            self.error(
                span,
                messages::effect_state_store_moved_out(&action, &name, &kind, &handler),
            );
        }
        true
    }

    // ================= expressions =================
    fn check_expr(&mut self, expr: &'p Expr, expected: Option<&Ty>) -> Ty {
        let ty = self.check_expr_inner(expr, expected);
        self.out.expr_ty.insert(self.key(expr.span()), ty.clone());
        if let Some(exp) = expected {
            let repr = self.repr_of(expr, &ty);
            self.maybe_coerce(expr.span(), &ty, &repr, exp);
        }
        ty
    }

    /// The physical representation type of an expression: for identifier
    /// uses this is the declared type (narrowing does not re-wrap values),
    /// and for a narrowed projection place the type its storage keeps
    /// [flow-place].
    fn repr_of(&self, expr: &Expr, logical: &Ty) -> Ty {
        if let Expr::Ident(id) = expr {
            if let Some(var) = self.lookup(&id.name) {
                // [qual-lift] Inside a `^` branch the value is seen at the
                // widened type.
                return var.widened.clone().unwrap_or_else(|| var.declared.clone());
            }
        }
        if matches!(expr, Expr::Field { .. } | Expr::TupleIndex { .. }) {
            if let Some(entry) = Place::of_expr(expr)
                .as_ref()
                .and_then(|p| self.place_narrow_entry(p))
            {
                return entry.declared.clone();
            }
        }
        logical.clone()
    }

    fn check_expr_inner(&mut self, expr: &'p Expr, expected: Option<&Ty>) -> Ty {
        if let Some(lit) = expr_literal(expr) {
            let key = self.key(expr.span());
            self.lit_spans.insert(key, lit);
        }
        match expr {
            // [type-lit-adopt] An *unsuffixed* numeric literal adopts the
            // expected numeric type where one exists (`let x: Long = 1`,
            // `f(1)` into a `Long` parameter, `let d: Double = 3`), so
            // `Long` positions need no `to_long(1)` noise (user decision
            // 2026-09-14). A written suffix stays explicit and never
            // adopts; an integer literal never adopts `Int`-ward (a
            // `Float` literal cannot become `Int`).
            Expr::Int { value, long, .. } => {
                let lit = if *long { TypeLit::Long(*value) } else { TypeLit::Int(*value) };
                if let Some(t) = adopt_literal(expected, lit) {
                    return t;
                }
                match adopted_numeric(expected, *long, false) {
                    Some(name) => Ty::named(name),
                    None => Ty::named(if *long { "Long" } else { "Int" }),
                }
            }
            Expr::Float { single, .. } => match adopted_numeric(expected, *single, true) {
                Some(name) => Ty::named(name),
                None => Ty::named(if *single { "Float" } else { "Double" }),
            },
            Expr::Bool { value, .. } => {
                adopt_literal(expected, TypeLit::Bool(*value)).unwrap_or_else(|| Ty::named("Bool"))
            }
            Expr::Char { .. } => Ty::named("Char"),
            // [type-literal] A plain string (no interpolation) takes a literal
            // type where the expected type lists it — contextual only, so
            // `let x = "a"` stays a `Str`.
            Expr::Str { parts, .. }
                if parts.iter().all(|p| matches!(p, StrExprPart::Text(_)))
                    && {
                        let text: String = parts
                            .iter()
                            .map(|p| match p {
                                StrExprPart::Text(t) => t.as_str(),
                                StrExprPart::Interp(_) => "",
                            })
                            .collect();
                        adopt_literal(expected, TypeLit::Str(text)).is_some()
                    } =>
            {
                let text: String = parts
                    .iter()
                    .map(|p| match p {
                        StrExprPart::Text(t) => t.as_str(),
                        StrExprPart::Interp(_) => "",
                    })
                    .collect();
                Ty::Lit(TypeLit::Str(text))
            }
            Expr::Str { parts, .. } => {
                for part in parts {
                    if let StrExprPart::Interp(e) = part {
                        let ty = self.check_expr(e, None);
                        // [str-drop-mut] Interpolation reads the *text* of
                        // a value, so a builder is converted first.
                        self.drop_mut_operand(e, &ty);
                        // [interp-no-none] Interpolating a possibly-absent
                        // value is an error (user decision 2026-09-02):
                        // Kotlin would print `null` while Rust rejects the
                        // `Option` — an observable backend divergence.
                        if !ty.is_unknown() && !matches!(ty, Ty::Never) {
                            let stripped = ty.strip_quals();
                            if stripped.has_none_arm() || stripped.is_none_ty() {
                                let message = if stripped.is_none_ty() {
                                    messages::interp_no_none_none_value()
                                } else {
                                    messages::interp_no_none_optional_value(&ty)
                                };
                                self.error(e.span(), message);
                                continue;
                            }
                            // [interp-to-str] The value has to have a text
                            // form. Scalars and `Str` render natively on both
                            // backends; anything else needs a `to_str`,
                            // resolved *here* like an implicit parameter
                            // (user decision 2026-09-11). Without one this
                            // used to reach the backend and become rustc's
                            // "doesn't implement Display"
                            // [backend-never-wrong].
                            self.check_interpolable(e, &ty);
                        }
                    }
                }
                Ty::named("Str")
            }
            Expr::Ident(id) => {
                if id.name == "None" {
                    return Ty::none();
                }
                // [var-unused] An identifier *expression* is a read — the
                // only thing that counts as a use. An assignment target
                // looks the variable up directly instead, so writing to a
                // variable without ever reading it leaves it unused.
                if let Some(var) = self.lookup_mut(&id.name) {
                    var.used = true;
                }
                // [name-table] Resolution bound this name to the binding
                // the scopes here find, or to none: a debug build checks.
                #[cfg(debug_assertions)]
                self.check_value_binding(id);
                #[cfg(debug_assertions)]
                if self.lookup(&id.name).is_none() {
                    self.check_value_members(id);
                }
                if let Some(var) = self.lookup(&id.name) {
                    let mut narrowed = var.narrowed.clone();
                    // [qual-lift] Inside a `^` branch the physical view is
                    // the widened type: the wrapper the arm test peeled is
                    // materialized by the emitters, so reads (and any
                    // further narrowing) unwrap relative to *it*.
                    let declared = var.widened.clone().unwrap_or_else(|| var.declared.clone());
                    let links = var.links.clone();
                    let var_id = var.id;
                    // [deduce-ownership-audit] A read types as the narrowing says,
                    // whatever ownership did: the walk tracks no moves (the
                    // IR flow pass reports a use of a moved, poisoned or
                    // bound-away value [flow-use-after-move]). A variable
                    // narrowed to `Never` reads as declared.
                    if matches!(narrowed, Ty::Never) {
                        narrowed = declared.clone();
                    }
                    // A read of a variable from outside an enclosing
                    // lambda is a *capture* [fate-lambda].
                    if !self.lambda_ctx.is_empty() {
                        if let Some(frame) = self.frame_of_id(var_id) {
                            let mut visited = HashSet::new();
                            let mutable = self.ty_transitively_mut(&declared, &mut visited);
                            let name = id.name.clone();
                            self.record_capture(frame, &name, var_id, mutable);
                        }
                    }
                    if narrowed != declared {
                        self.out.repr_ty.insert(self.key(id.span), declared);
                    }
                    // Expose the fate links of derived-variable reads for
                    // tooling (`proj` presentation) [fate-link].
                    if !links.is_empty() {
                        let reads: Vec<FateRead> = links
                            .iter()
                            .map(|l| FateRead {
                                root: l.root_name.clone(),
                                bind: self.key(l.bind_span),
                                path: l
                                    .path
                                    .as_ref()
                                    .map(|p| p.iter().map(|s| s.to_string()).collect()),
                            })
                            .collect();
                        self.out.fate_reads.insert(self.key(id.span), reads);
                    }
                    return narrowed;
                }
                if self.scope.handlers.contains_key(id.name.as_str()) {
                    return Ty::named(&self.type_key(&id.name));
                }
                if self.has_callable(&id.name) || !self.available_members(&id.name).is_empty() {
                    // [fn-value-select] Passing a function *by name*: the
                    // same selection every call goes through, against the
                    // expected fn type instead of an argument list — an
                    // available effect's member among the candidates (R10 D3).
                    return self.fn_value_by_name(&id.name, id.span, None, expected);
                }
                // [name-ident-resolve] Nothing declares this name *as a value*.
                // Salvo assumes it can see everything, so a reference no
                // declaration justifies is an error here rather than a
                // `Ty::Unknown` that reaches a backend and becomes rustc's or
                // kotlinc's problem [backend-never-wrong].
                //
                // [actor-mixed-handler] Inside a mixed handler's sync member, a
                // state field's name is deliberately out of scope — the
                // confinement rule — and the diagnostic names the rule
                // rather than claiming the name does not exist.
                if self.confined_state.iter().any(|n| n == &id.name) {
                    self.error(
                        id.span,
                        messages::actor_mixed_handler_servant_state_sync(&id.name),
                    );
                    return Ty::Unknown;
                }
                //
                // A name that *is* declared, but as something that is not a
                // value, says so instead — the same courtesy the effect and
                // handler rules already extend [effect-not-a-type].
                let kind = if self.scope.structs.contains_key(id.name.as_str()) {
                    Some("a struct type, not a value: construct one (`Name { … }`)")
                } else if self.scope.effects.contains_key(id.name.as_str()) {
                    Some(
                        "an effect, not a value: call one of its members, \
                         having registered a handler with `use`",
                    )
                } else if self.scope.qualifiers.contains_key(id.name.as_str()) {
                    Some(
                        "a qualifier, not a value: write it on a type \
                         (`Name value`) or test it with `is`",
                    )
                } else if self.scope.fn_groups.contains_key(id.name.as_str()) {
                    Some(
                        "a `fns` group, not a value: spread it into a \
                         signature (`?Name<…>`)",
                    )
                } else if self.scope.opaque_types.contains_key(id.name.as_str())
                    || self.scope.type_aliases.contains_key(id.name.as_str())
                {
                    Some("a type, not a value")
                } else {
                    None
                };
                match kind {
                    Some(what) => self.error(
                        id.span,
                        messages::name_ident_resolve_not_a_value(&id.name, &what),
                    ),
                    None => self.error_unresolved(
                        id.span,
                        messages::name_ident_resolve_unknown(&id.name),
                        &id.name,
                    ),
                }
                Ty::Unknown
            }
            // [effect-at] An effect-selected member: a call form, and a value
            // only at a fn-typed position with an instance in scope (R10 D3),
            // where it is a closure over that instance — detached from its
            // dispatch, nothing would implement it.
            Expr::EffectScoped {
                base, name, effect, ..
            } => {
                if let Some(base) = base {
                    self.check_expr(base, None);
                }
                // [fn-attached] …unless the capitalized name is a **type**,
                // in which case this is a canonical named as a *value* —
                // `cmp = cmp@Person` [implicit-override], and the one place
                // this selector follows the *module* precedent
                // ([fn-overload-at] is "also valid as a value") rather than
                // [effect-at]'s call-only form.
                if self.names_a_type(&effect.name) && self.has_callable(&name.name) {
                    self.record_def_ref(effect.span, &effect.name);
                    return self.fn_value_by_name(
                        &name.name,
                        name.span,
                        Some(Selector::Type(effect)),
                        expected,
                    );
                }
                // [effect-member-overload] [effect-at] …and at a fn-typed
                // position, an effect's member **as a value** (R10 D3: members
                // fill every position a fn does): the members of that name of
                // the effect's instances in scope, selected by the call's rule
                // at the position's type, passed as a closure over the
                // instance. This is the remedy an ambiguous implicit names
                // (`to_str = to_str@Fmt`).
                if base.is_none() {
                    if let Some(want) = expected.filter(|t| matches!(t.strip_quals(), Ty::Fn { .. })) {
                        let cands: Vec<ValueCand<'p>> = self
                            .available_members(&name.name)
                            .into_iter()
                            .filter(|m| m.effect.name.name == effect.name)
                            .map(ValueCand::Member)
                            .collect();
                        if !cands.is_empty() {
                            self.record_def_ref(name.span, &name.name);
                            let want = want.clone();
                            match self.select_fn_value(&name.name, cands, &want) {
                                Ok((ValueCand::Member(m), fit)) => {
                                    return self.member_as_value(&name.name, name.span, m, fit, &want);
                                }
                                Ok(_) => {}
                                Err(ImplicitMiss::Ambiguous(c)) => {
                                    let text = Self::implicit_ambiguity(&name.name, &c, None);
                                    self.error(
                                        name.span,
                                        messages::effect_at_value_ambiguous(
                                            &name.name,
                                            &effect.name,
                                            &want,
                                            &text,
                                        ),
                                    );
                                    return Ty::Unknown;
                                }
                                Err(ImplicitMiss::NearMiss(reason)) => {
                                    self.error(
                                        name.span,
                                        messages::effect_at_value_near_miss(
                                            &name.name,
                                            &effect.name,
                                            &want,
                                            &reason,
                                        ),
                                    );
                                    return Ty::Unknown;
                                }
                                Err(_) => {
                                    self.error(
                                        name.span,
                                        messages::effect_at_value_no_fit(
                                            &name.name,
                                            &effect.name,
                                            &want,
                                        ),
                                    );
                                    return Ty::Unknown;
                                }
                            }
                        }
                    }
                }
                self.error(
                    name.span,
                    messages::effect_at_value_not_expected(&name.name, &effect.name),
                );
                Ty::Unknown
            }
            // [fn-overload-at] [fn-value-select] A scope-selected fn *value*
            // (`describe@main` passed to a higher-order function). As a
            // *callee* it never reaches here — `check_call` handles it — so a
            // receiver written here is a partially applied call, which Salvo
            // does not have.
            Expr::Scoped {
                base,
                name,
                module,
                span,
            } => {
                if let Some(base) = base {
                    self.check_expr(base, None);
                    self.error(
                        *span,
                        messages::fn_overload_at_value_receiver(
                            &name.name,
                            &module.iter().map(|m| m.name.as_str()).collect::<Vec<_>>().join("."),
                        ),
                    );
                    return Ty::Unknown;
                }
                if !self.has_callable(&name.name) {
                    self.error_unresolved(
                        name.span,
                        messages::call_resolve_unknown_fn(&name.name),
                        &name.name,
                    );
                    return Ty::Unknown;
                }
                self.fn_value_by_name(&name.name, name.span, Some(Selector::Module(module)), expected)
            }
            Expr::Field { base, field, span, .. } => {
                let base_ty = self.check_expr(base, None);
                // A predicate-qualifier field override refines the type
                // [qual-field-override];
                // the backend casts + asserts at the access site.
                // [lsp-definition] the field name points at its
                // declaration in the struct.
                // [struct-opaque] Outside its module an opaque struct's fields
                // are not there to read or write.
                if self.refuse_opaque(&base_ty, &format!("reading its field `{}`", field.name), *span) {
                    return Ty::Unknown;
                }
                self.record_field_ref(&base_ty, field);
                if let Some(override_ty) = self.field_override_ty(&base_ty, &field.name) {
                    self.out
                        .field_casts
                        .insert(self.key(*span), override_ty.clone());
                    return override_ty;
                }
                // [flow-place] A narrowed projection place reads at its
                // narrowed type. The storage keeps the declared type — the
                // one the `is` test was lowered against — so the read is
                // recorded in `repr_ty` for the emitters to unwrap from,
                // exactly as a narrowed identifier read is.
                if let Some(place) = Place::of_expr(expr) {
                    if let Some(entry) = self.place_narrow_entry(&place) {
                        let (narrowed, declared) = (entry.narrowed.clone(), entry.declared.clone());
                        if narrowed != declared {
                            self.out.repr_ty.insert(self.key(*span), declared);
                        }
                        return narrowed;
                    }
                }
                self.field_ty_or_error(&base_ty, field)
            }
            Expr::TupleIndex { base, index, span } => {
                let base_ty = self.check_expr(base, None);
                // [flow-place] A narrowed element place reads at its
                // narrowed type, exactly as a field does.
                if let Some(place) = Place::of_expr(expr) {
                    if let Some(entry) = self.place_narrow_entry(&place) {
                        let (narrowed, declared) = (entry.narrowed.clone(), entry.declared.clone());
                        if narrowed != declared {
                            self.out.repr_ty.insert(self.key(*span), declared);
                        }
                        return narrowed;
                    }
                }
                self.tuple_elem_ty_or_error(&base_ty, *index, *span)
            }
            Expr::Call {
                callee,
                type_args,
                args,
                named,
                span,
            } => {
                // [fn-overload-return] A position with no expected type of its
                // own (`!`'s operand, `?:`'s subject, a value branch's tail) may
                // still say where the value goes: for choosing among return-type
                // overloads only, never for coercion.
                let hint = self.select_hint.take();
                let exp = expected.cloned().or(hint);
                self.check_call(callee, type_args, args, named, exp.as_ref(), *span)
            }
            Expr::Index { base, index, span } => {
                let base_ty = self.check_expr(base, None);
                self.check_expr(index, Some(&Ty::named("Int")));
                match base_ty.strip_quals() {
                    Ty::Array(elem) => (**elem).clone(),
                    // [col-index-resolve] Only arrays are subscriptable; other
                    // collections expose element access as declared
                    // functions (`get(list, i)`). Only an un-inferred base
                    // stays lenient [type-unknown-lenient] — a generic `T`
                    // is opaque, not unknown.
                    Ty::Unknown | Ty::Never => Ty::Unknown,
                    other => {
                        let other = other.clone();
                        self.error(*span, messages::col_index_resolve_not_indexable(&other));
                        Ty::Unknown
                    }
                }
            }
            Expr::Tuple { elems, .. } => {
                let expected_elems: Option<&Vec<Ty>> = match expected {
                    Some(Ty::Tuple(ts)) if ts.len() == elems.len() => Some(ts),
                    _ => None,
                };
                let mut tys = Vec::new();
                for (i, e) in elems.iter().enumerate() {
                    tys.push(self.check_expr(e, expected_elems.map(|ts| &ts[i])));
                }
                // [linear-composite] A tuple is a composite too.
                for (e, ty) in elems.iter().zip(&tys) {
                    if self.ty_own_linear(ty) {
                        let linear = format!("{ty}");
                        self.refuse_linear_composite(
                            e.span(),
                            &linear,
                            "a tuple component".to_string(),
                        );
                    }
                }
                // Storing a value in a tuple literal moves it
                // [deduce-consume].
                for e in elems {
                    self.fate_move(e, "store", e.span());
                }
                Ty::Tuple(tys)
            }
            Expr::StructLit { ty, fields, span } => {
                let struct_ty = self.check_struct_lit(ty.as_ref(), fields, expected, *span);
                // Storing a value in a struct literal moves it; spreading
                // a value moves it too (its fields are stored)
                // [deduce-consume].
                let proj_fields = self.proj_fields_of(&struct_ty);
                for f in fields {
                    match &f.kind {
                        // [proj-field] A `proj` field *borrows* what is
                        // stored in it: the literal becomes derived from the
                        // value (see `links_for_value`), and nothing moves.
                        StructLitFieldKind::Named { name, .. }
                            if proj_fields.contains(&name.name) => {}
                        StructLitFieldKind::Named { value, .. } => {
                            self.fate_move(value, "store", value.span());
                        }
                        StructLitFieldKind::Spread(e) => {
                            self.fate_move(e, "spread", e.span());
                        }
                        // [comptime-inline] Gone before this runs.
                        StructLitFieldKind::InlineFor { .. } => {}
                    }
                }
                struct_ty
            }
            Expr::Unary { op, operand, .. } => {
                match op {
                    // [op-arith] Negation is numeric. The expectation
                    // passes through, so `let x: Long = -5` adopts
                    // [type-lit-adopt].
                    UnaryOp::Neg => {
                        let t = self.check_expr(operand, expected);
                        let tb = t.strip_quals();
                        if !op_lenient(tb) && op_numeric(tb).is_none() {
                            self.error(operand.span(), messages::op_arith_unary_minus(&t));
                        }
                        t
                    }
                    // [op-bool] Negation of a truth value: `Bool` only —
                    // Salvo has no truthiness.
                    UnaryOp::Not => {
                        let t = self.check_expr(operand, None);
                        self.require_bool_operand("!", operand, &t);
                        Ty::named("Bool")
                    }
                }
            }
            Expr::Binary { op, lhs, rhs, .. } => {
                use BinaryOp::*;
                match op {
                    Add | Sub | Mul | Div | Rem | Pow => {
                        let l = self.check_expr(lhs, None);
                        let r = self.check_expr(rhs, None);
                        // [op-no-none] Arithmetic never operates on a
                        // possibly-absent value.
                        let refused = self.reject_optional_operand(*op, lhs, &l);
                        let refused = self.reject_optional_operand(*op, rhs, &r) || refused;
                        // [str-drop-mut] An operator works on plain values.
                        self.drop_mut_operand(lhs, &l);
                        self.drop_mut_operand(rhs, &r);
                        if matches!(op, Rem) {
                            // [op-arith] `%` names no function (O1's table has
                            // none): numeric operands, widening within a
                            // class, promoted result type (PIPELINE.md §II.10
                            // P16).
                            self.check_arith(*op, expr.span(), lhs, rhs, &l, &r)
                        } else if refused {
                            // One mistake, one diagnostic: the call would only
                            // repeat the refusal.
                            Ty::Unknown
                        } else {
                            // [op-arith] [op-pow] The call the operator names.
                            self.check_arith_call(*op, expr.span(), lhs, rhs, &l, &r)
                        }
                    }
                    And | Or => {
                        // Value-position boolean: no narrowing propagation.
                        let l = self.check_expr(lhs, None);
                        let r = self.check_expr(rhs, None);
                        // [op-bool] Both sides are truth values.
                        self.require_bool_operand(op_symbol(*op), lhs, &l);
                        self.require_bool_operand(op_symbol(*op), rhs, &r);
                        Ty::named("Bool")
                    }
                    _ => {
                        let l = self.check_expr(lhs, None);
                        let r = self.check_expr(rhs, None);
                        // [op-arm-eq] `union == value` where the value matches
                        // exactly one arm reduces to `union is arm && arm ==
                        // value` — so an optional (or any union) can be
                        // compared against a concrete arm, a non-matching arm
                        // comparing unequal (user decision 2026-10-12). When
                        // this fires it replaces the operand rules below.
                        if self.try_arm_compare(*op, expr.span(), lhs, rhs, &l, &r) {
                            return Ty::named("Bool");
                        }
                        // [op-no-none] Comparison (ordering and equality)
                        // likewise: nullability is tested with `is None`.
                        let refused = self.reject_optional_operand(*op, lhs, &l);
                        let refused = self.reject_optional_operand(*op, rhs, &r) || refused;
                        // [str-drop-mut] Equality especially: a builder
                        // compares by identity where a string compares by
                        // content.
                        self.drop_mut_operand(lhs, &l);
                        self.drop_mut_operand(rhs, &r);
                        // [op-equality] [op-order] The operator is the call
                        // it names — unless an operand was just refused, whose
                        // call would only repeat the refusal (one mistake, one
                        // diagnostic).
                        if !refused {
                            self.check_comparison_operands(*op, expr.span(), lhs, rhs, &l, &r);
                        }
                        Ty::named("Bool")
                    }
                }
            }
            Expr::Is { .. } => {
                self.is_info(expr);
                Ty::named("Bool")
            }
            // [qual-lift] Boolean-valued like `is`; the flow facts are
            // produced by `analyze_cond` in condition position.
            Expr::Widen {
                subject,
                quals,
                binding,
                span,
            } => {
                self.widen_info(subject, quals, binding.as_ref(), *span);
                Ty::named("Bool")
            }
            Expr::SafeNav { base, access, span } => self.check_safe_nav(base, access, *span, expected),
            // [assert-fn] [assert-narrow] `assert!(cond)` / `assert!(cond, why)`
            // — a condition that must hold, checked in every build
            // [assert-trap]. When the condition is an `is` test its narrowing
            // is installed **permanently**, exactly as the guard idiom's is
            // [is-narrow-guard]: an assertion that informs the type is the
            // reason the form exists (user decision 2026-09-23, A-3).
            Expr::Assert {
                cond,
                message,
                span,
            } => {
                let info = self.analyze_cond(cond);
                let cond_ty = self.expr_ty_recorded(cond);
                // [expr-cond-bool] No truthiness: the condition is a `Bool`.
                if let Some(t) = cond_ty {
                    if !matches!(t, Ty::Unknown) && t.to_string() != "Bool" {
                        self.error(cond.span(), messages::expr_cond_bool_assert_condition(&t));
                    }
                }
                self.install_narrows(&info.then_narrows);
                match message {
                    Some(m) => self.check_assert_message(m),
                    // [qual-whynot] With no message of its own, a failed
                    // `assert!(x is Q)` says what `whynot?(x is Q)` would.
                    None => {
                        if let Expr::Is { subject, span: is_span, .. } = &**cond {
                            self.whynot_text_form(subject, *is_span);
                        }
                    }
                }
                let _ = span;
                Ty::none()
            }
            // [assert-fn] `unreachable!()` — a place the program says it cannot
            // reach. `Never`, so it stands where any value is expected and ends
            // the path [expr-escape].
            Expr::Unreachable { message, .. } => {
                if let Some(m) = message {
                    self.check_assert_message(m);
                }
                Ty::Never
            }
            // [assert-fn] `todo!()` is `unreachable!()` that **warns**: a
            // place not yet implemented, flagged at every site so a build
            // surfaces unfinished code. Same `Never` type and same runtime
            // trap; only the warning sets it apart. std is exempt — its
            // stubs are the compiler's business, like unused locals.
            Expr::Todo { message, span } => {
                if let Some(m) = message {
                    self.check_assert_message(m);
                }
                if !self.is_std {
                    self.warn(*span, messages::assert_fn_todo());
                }
                Ty::Never
            }
            // [qual-whynot] `whynot?(x is Q)`: the test, and a `Str?`.
            Expr::WhyNot { test, span } => self.check_whynot(test, *span),
            // [op-inc-dec] All four forms do the same thing to the operand — a
            // step of one on an `Int` place — so the checker ignores the
            // direction and the fixity; they only decide the expression's
            // *value*, which is the emitters' business.
            Expr::IncDec {
                operand,
                down: _,
                prefix: _,
                span,
            } => {
                let ty = self.check_expr(operand, None);
                // `i++` rebinds a whole variable (revival: severs its own
                // links, poisons variables derived from it [fate-poison]);
                // through a projection it mutates the root
                // [fate-derived-readonly].
                match operand.as_ref() {
                    Expr::Ident(id) => {
                        // [fn-param-const] `n++` on a parameter is an
                        // assignment to it.
                        self.reject_param_assignment(&id.name, id.span, "step");
                        let root_var_id = self.lookup(&id.name).map(|var| var.id);
                        // [qual-depend] A step rebinds the variable, so
                        // dependent claims bound to its old value strip,
                        // exactly as reassignment's do — before the links
                        // are severed, since the claim roots to strip are
                        // the old value's.
                        self.strip_dependent_claims(&id.name, &[]);
                        // [fate-elem-distinct] Element identities minted from
                        // the stepped variable die with the old value.
                        if let Some(var_id) = root_var_id {
                            self.erase_elem_identities(var_id);
                        }
                        if let Some(var) = self.lookup_mut(&id.name) {
                            var.links = Vec::new();
                            // `i++` rebinds the variable: facts about its
                            // parts fall [flow-place-invalidate].
                            var.place_narrows.clear();
                        }
                    }
                    other => {
                        self.fate_mutation_through(other, *span);
                    }
                }
                ty
            }
            Expr::If {
                branches,
                else_block,
                ..
            } => {
                let saved = std::mem::replace(&mut self.value_expected, expected.cloned());
                let t = self.check_if(branches, else_block.as_ref());
                self.value_expected = saved;
                t
            }
            Expr::When {
                binding,
                subject,
                branches,
                span,
            } => {
                let saved = std::mem::replace(&mut self.value_expected, expected.cloned());
                let t = self.check_when(binding.as_ref(), subject, branches, *span);
                self.value_expected = saved;
                t
            }
            // [when-condition] The subject-less form is a condition chain
            // with a mandatory `else`: the same checking as
            // `if`/`elif`/`else`, and the `else` is what keeps `None` out of
            // the value type.
            Expr::WhenCond {
                branches,
                else_block,
                ..
            } => {
                let saved = std::mem::replace(&mut self.value_expected, expected.cloned());
                let t = self.check_if(branches, Some(else_block));
                self.value_expected = saved;
                t
            }
            // [throw-try] The throw delimiter: an intrinsic, not an effect.
            Expr::Try { body, span } => self.check_try(body, *span),
            // [op-elvis] `subject ?…?: rhs` / `subject :?…? rhs` — the positional
            // pick. A run of `count` `?`s names how many arms of the subject's
            // union it keeps, counted from the declared **front** (`Forward`)
            // or **back** (`Backward`); those arms become the value, and `rhs`
            // runs otherwise with `_` bound to the arms left behind.
            Expr::Elvis {
                subject,
                rhs,
                span,
            } => {
                // [fn-overload-return] `f(s) ?: d` where a `T` is expected asks
                // `f` for a `T?`: the pick keeps the subject's first arm.
                if let (Some(e), Expr::Call { .. }) = (expected, subject.as_ref()) {
                    self.select_hint = Some(self.mk_union(vec![e.clone(), Ty::none()]));
                }
                self.check_elvis(subject, rhs, *span)
            }
            // [expr-pipe] `lhs |> rhs` — the left side evaluated once, bound to
            // `_`, read in the right side. The result is the right side's type.
            Expr::Pipe { lhs, rhs, span } => self.check_pipe(lhs, rhs, *span),
            Expr::SafePipe { lhs, rhs, span } => self.check_safe_pipe(lhs, rhs, *span),
            // [expr-placeholder] Outside an `?:` right-hand side there is no value
            // for `_` to mean.
            Expr::Placeholder { span } => match self.placeholder_ty.clone() {
                Some(ty) => {
                    // [expr-pipe] Record the read so `check_pipe` can refuse a
                    // right side that ignores the piped value. Harmless for an
                    // elvis right side, which does not consult the flag.
                    self.placeholder_read = true;
                    ty
                }
                None => {
                    self.error(*span, messages::expr_placeholder_outside_pick());
                    Ty::Unknown
                }
            },
            // [expr-escape] The three escapes are expressions of type
            // `Never` (user decision 2026-09-21). The rules are unchanged
            // from when they were statements — only where they live is.
            Expr::Return { value, span } => {
                let expected = self.ret_ty.clone();
                // [deduce-conditional] Proof-only: a `return true` in a fn
                // with a qualifier-conditional response must have narrowed
                // each `is`-subject to its qualifier on this path (and each
                // `!is`-subject must *not* carry it). The body earns the
                // claim with a real `is` test; nothing else may return `true`.
                if let (Some(responses), Some(Expr::Bool { value: true, .. })) =
                    (self.own_response.clone(), value.as_deref())
                {
                    for r in &responses {
                        let have: Vec<String> = self
                            .lookup(&r.subject.name)
                            .map(|v| v.narrowed.quals().iter().map(|q| q.name.clone()).collect())
                            .unwrap_or_default();
                        let present = have.contains(&r.qual.name.name);
                        if r.negated && present {
                            self.error(
                                *span,
                                messages::deduce_conditional_claims_not(
                                    &r.subject.name,
                                    &r.qual.name.name,
                                ),
                            );
                        } else if !r.negated && !present {
                            self.error(
                                *span,
                                messages::deduce_conditional_unproven(
                                    &r.subject.name,
                                    &r.qual.name.name,
                                ),
                            );
                        }
                    }
                }
                match value {
                    Some(v) => {
                        // [proj-anywhere] A constructor call whose result
                        // goes into a `proj` arm lends its argument: mark
                        // it before checking so the contract does not
                        // consume the value the caller is about to borrow.
                        // The call is resolved during checking, so the arm
                        // test itself happens after; the mark is on the
                        // *shape* (a one-argument call under a union-return
                        // derived fn) and the arm decides below.
                        let saved_lending = self.lending_ctor;
                        if self.own_derived_return.is_some() && !self.own_proj_arms.is_empty() {
                            if let Expr::Call { span, args, .. } = v.as_ref() {
                                if args.len() == 1 {
                                    self.lending_ctor = Some(*span);
                                }
                            }
                        }
                        let vty = self.check_expr(v, Some(&expected));
                        self.lending_ctor = saved_lending;
                        // [ref-handle] The mint: a function declared to
                        // return a `ref` handle, whose body returns a
                        // projection of the same container (`at`'s `return
                        // get(list, index)`), is minting the handle — accept
                        // the `proj → ref` promotion at the designated
                        // locator. A plain `proj` body for a `proj` return is
                        // unaffected; only a `ref` *return type* promotes.
                        // The handle is usually optional (`ref(c) Mut T?`),
                        // so the promotion distributes over union arms.
                        let ref_mint = has_ref_arm(&expected)
                            && !has_ref_arm(&vty)
                            && is_subtype(&promote_proj_to_ref(vty.clone()), &expected);
                        // [ref-handle] `proj → ref` does not exist: a
                        // handle comes from a place or a mint, never from a
                        // reader's borrow, which has forgotten where the
                        // element is.
                        if ref_mint {
                            if let Some(name) = self.reader_call(v) {
                                self.error(v.span(), messages::ref_handle_from_reader(&name));
                            }
                        }
                        if ref_mint {
                            // The promoted type is what the value *is* from
                            // here on: the emitters render it as the handle
                            // (the Rust locator path keys on a `ref Mut`
                            // call type, [rs-loc]).
                            let mut e: &Expr = v;
                            loop {
                                if let Some(t) = self.out.expr_ty.get(&self.key(e.span())).cloned() {
                                    self.out.expr_ty.insert(self.key(e.span()), promote_proj_to_ref(t));
                                }
                                match e.presence_unwrapped() {
                                    Some(operand) => e = operand,
                                    None => break,
                                }
                            }
                        }
                        if !ref_mint
                            && !is_subtype(&vty, &expected)
                            // [qual-arm-infer] A bare value that is the payload of
                            // exactly one provenance-tagged arm is accepted:
                            // `check_expr` above already recorded the
                            // WrapUnion against the expected union.
                            && !(expected.is_wrapper_union()
                                && self
                                    .infer_provenance_arm(&vty, &expected.value_arms())
                                    .is_some())
                        {
                            self.error(
                                v.span(),
                                messages::fn_syntax_return_mismatch(&expected, &vty),
                            );
                        }
                        // [proj-readonly-return] A derived-return fn
                        // *borrows* its result out: the value must be
                        // derived from the annotated parameter (or be
                        // `None`), and nothing is consumed.
                        let into_proj_arm = match self.own_derived_return.clone() {
                            None => None,
                            Some(from) if self.own_proj_arms.is_empty() => Some(from),
                            // [proj-anywhere] A union return: only a value
                            // built for a `proj` arm is a borrow. The arm is
                            // read off the constructor the value goes
                            // through (`emitted(x)` builds `Emitted`).
                            Some(from) => self
                                .constructed_qualifier(v)
                                .filter(|q| self.own_proj_arms.contains(q))
                                .map(|_| from),
                        };
                        if let Some(from) = into_proj_arm {
                            // [proj-anywhere] Only a *union* return goes
                            // through a tag constructor whose operand is the
                            // borrowed value (`emitted(x)`); the arm test
                            // above is what established that. A plain
                            // `proj(p) T` return is checked as
                            // written — unwrapping any one-argument call
                            // here mistook `list.get(0)` for a constructor
                            // and asked the *index* for its provenance.
                            let inner = if self.own_proj_arms.is_empty() {
                                v
                            } else {
                                Self::constructor_operand(v)
                            };
                            self.check_derived_return_value(inner, &from);
                        } else {
                            // Returning a value moves it: a fate-linked
                            // (derived) variable cannot be moved
                            // [fate-derived-readonly]; returning a root
                            // consumes it [deduce-consume] (terminal
                            // here, but visible to unreachable code and
                            // to derived-variable poison [fate-poison]).
                            self.fate_move(v, "return", *span);
                        }
                        // [ir-analyze] The linear-obligation leak check at a
                        // return, and [linear-state] the state-whole check,
                        // are the IR's.
                    }
                    None => {
                        if !expected.is_none_ty() && !expected.is_unknown() {
                            self.error(*span, messages::fn_return_none_bare_return(&expected));
                        }
                    }
                }
                Ty::Never
            }
            Expr::Break { value, span } => {
                if self.loop_stack.is_empty() {
                    self.error(*span, messages::expr_escape_break_outside_loop());
                }
                // [loop-while-value] `break value` contributes to the loop's
                // value; a bare `break` may leave the loop without a value.
                match value {
                    Some(v) => {
                        let vty = self.check_expr(v, None);
                        // `break value` moves the value out of the loop:
                        // a derived variable cannot be moved
                        // [fate-derived-readonly]; a root is consumed
                        // [deduce-consume] — the code after the loop sees
                        // it moved.
                        self.fate_move(v, "break with", *span);
                        let repr = self.repr_of(v, &vty);
                        if let Some(ctx) = self.loop_stack.last_mut() {
                            ctx.breaks.push(TailInfo {
                                span: v.span(),
                                logical: vty,
                                repr,
                            });
                        }
                    }
                    None => {
                        if let Some(ctx) = self.loop_stack.last_mut() {
                            ctx.may_skip_value = true;
                        }
                    }
                }
                // [linear-obligation] Frames inside the loop die at a
                // `break`: nothing linear may still be owed in them.
                // The loop's exit is reachable from every `break`: record
                // this path's flow state so the after-loop merge sees
                // values consumed on break paths [deduce-consume] (an
                // always-exiting branch containing the `break` contributes
                // nothing to the merge *inside* the body, but the loop
                // exit is exactly where its state lands).
                match self.loop_stack.last().map(|c| c.entry_depth) {
                    Some(depth) => {
                        let _ = depth;
                        // [ir-analyze] The break-path linear leak check moved
                        // to the IR analysis.
                        let snap = self.snapshot_narrows();
                        if let Some(ctx) = self.loop_stack.last_mut() {
                            ctx.break_states.push(snap);
                        }
                    }
                    None => {
                        let snap = self.snapshot_narrows();
                        if let Some(ctx) = self.loop_stack.last_mut() {
                            ctx.break_states.push(snap);
                        }
                    }
                }
                Ty::Never
            }
            Expr::Continue { span } => {
                match self.loop_stack.last_mut() {
                    Some(ctx) => ctx.may_skip_value = true,
                    None => self.error(*span, messages::expr_escape_continue_outside_loop()),
                }
                // [ir-analyze] The continue-path linear leak check moved to
                // the IR analysis.
                let _ = self.loop_stack.last().map(|c| c.entry_depth);
                Ty::Never
            }
            // [actor-spawn-expr] The asynchronous binding of a handler: its
            // value is the child's `Addr<E>`.
            Expr::Spawn {
                handler,
                with_items,
                pool,
                join,
                span,
            } => {
                let ty = self.check_spawn(handler, with_items, pool.as_deref(), *span);
                if let Some(group) = join {
                    self.check_spawn_join(group, &ty);
                }
                ty
            }
            // [effect-eff-handle] `use H()` as a value: register the handler (all the
            // side-effects of the statement form) and yield its handle. One
            // face is `eff[E]`; several is a *tuple* of single handles
            // `(eff[A], eff[B])` — the IR already binds one handle per face,
            // so the value is a tuple of them, mirroring a multi-face `spawn`.
            Expr::Use { handler, with_items, any, span } => {
                self.check_use(handler, with_items, *any, *span);
                let faces = self
                    .out
                    .use_effects
                    .get(&self.key(*span))
                    .cloned()
                    .unwrap_or_default();
                match faces.len() {
                    0 => Ty::Unknown,
                    1 => Ty::Named { name: ADDR_TYPE.to_string(), args: faces },
                    _ => Ty::Tuple(
                        faces
                            .into_iter()
                            .map(|f| Ty::Named { name: ADDR_TYPE.to_string(), args: vec![f] })
                            .collect(),
                    ),
                }
            }
            // [effect-eff-handle] `e[A, B]` / `e[IO]` — projection: a non-consuming
            // copy of the sub-handle carrying the named effects, which must be
            // a subset of what `e` carries. Yields `eff[S]` (single) or a tuple
            // of single handles (several). An alias among the names expands.
            Expr::Project { base, effects, span } => {
                let base_ty = self.check_expr(base, None);
                // The effects `base` carries: a single handle's one, or a
                // tuple of handles' flat set.
                let mut have: Vec<Ty> = Vec::new();
                let ok = self.collect_handle_tuple(&base_ty, &mut have);
                if !ok && !base_ty.is_unknown() {
                    self.error(*span, messages::effect_eff_handle_not_a_handle(&base_ty));
                    return Ty::Unknown;
                }
                // The requested effects (an alias expands to its members).
                let mut listed: Vec<ListedEffect> = Vec::new();
                for r in effects {
                    self.expand_effect_entry(r, false, r.span, EffectOrigin::Written, &mut Vec::new(), &mut listed);
                }
                let mut want: Vec<Ty> = Vec::new();
                for e in listed {
                    if !want.contains(&e.ty) {
                        want.push(e.ty);
                    }
                }
                // Each requested effect must be one `base` carries.
                for w in &want {
                    if !have.iter().any(|h| h == w) {
                        self.error(
                            *span,
                            messages::effect_eff_handle_effect_not_carried(&base_ty, &w),
                        );
                    }
                }
                self.out.project_effects.insert(self.key(*span), want.clone());
                match want.len() {
                    0 => Ty::Unknown,
                    1 => Ty::Named { name: ADDR_TYPE.to_string(), args: want },
                    _ => Ty::Tuple(
                        want.into_iter()
                            .map(|f| Ty::Named { name: ADDR_TYPE.to_string(), args: vec![f] })
                            .collect(),
                    ),
                }
            }
            // [effect-eff-handle] `eff[a, b]` / `eff[*]` — merge already-bound handles
            // into one. Each item is a handle value (single or tuple); their
            // effects union (deduped, order preserved) into the result handle.
            // `eff[*]` gathers every handle currently in scope.
            Expr::Merge { items, all, span } => {
                let mut effects: Vec<Ty> = Vec::new();
                if *all {
                    // Every effect handle in scope, innermost-first, deduped.
                    for avail in self.visible_avail() {
                        if !effects.contains(&avail.ty) {
                            effects.push(avail.ty);
                        }
                    }
                } else {
                    for item in items {
                        let ty = self.check_expr(item, None);
                        let mut have: Vec<Ty> = Vec::new();
                        if self.collect_handle_tuple(&ty, &mut have) {
                            for e in have {
                                if !effects.contains(&e) {
                                    effects.push(e);
                                }
                            }
                        } else if !ty.is_unknown() {
                            self.error(
                                item.span(),
                                messages::effect_eff_handle_merge_not_handle(&ty),
                            );
                        }
                    }
                }
                // [effect-eff-handle] A handle set has no inherent order; when an
                // expected handle(-tuple) type is known, produce the effects
                // in *its* order so the positional tuple matches (a merge or
                // `eff[*]` returned where `eff[A, B]` is wanted). Extra effects
                // the expectation does not name keep their place at the end.
                if let Some(exp) = expected {
                    let mut wanted: Vec<Ty> = Vec::new();
                    let _ = self.collect_handle_tuple(exp, &mut wanted);
                    if !wanted.is_empty() {
                        let mut ordered: Vec<Ty> = Vec::new();
                        for w in &wanted {
                            if let Some(e) = effects.iter().find(|e| *e == w) {
                                ordered.push(e.clone());
                            }
                        }
                        for e in &effects {
                            if !ordered.contains(e) {
                                ordered.push(e.clone());
                            }
                        }
                        effects = ordered;
                    }
                }
                self.out.merge_effects.insert(self.key(*span), effects.clone());
                match effects.len() {
                    0 => Ty::Unknown,
                    1 => Ty::Named { name: ADDR_TYPE.to_string(), args: effects },
                    _ => Ty::Tuple(
                        effects
                            .into_iter()
                            .map(|f| Ty::Named { name: ADDR_TYPE.to_string(), args: vec![f] })
                            .collect(),
                    ),
                }
            }
            // [actor-self-send] A selector is a *callee*, never a value: a
            // handler member is not a function value any more than an effect
            // member is [effect-not-data]. Reached only when one is written
            // without a call.
            Expr::SelfScoped { name, span } => {
                self.error(*span, messages::actor_self_send_member_value(&name.name));
                Ty::Unknown
            }
            // [handler-init] `self@Face`: the enclosing handler's own address
            // as one of its actor faces. Legal inside a handler's members
            // (init included); the handler becomes spawn-only, since only an
            // activation has an address to read.
            Expr::SelfAddr { face, span } => {
                let Some(h) = self.own_handler else {
                    self.error(*span, messages::actor_self_send_address_outside_member());
                    return Ty::Unknown;
                };
                let Some(ty) = self.lower_effect_ref(face) else {
                    return Ty::Unknown;
                };
                let is_actor_face = self
                    .scope
                    .effects
                    .get(face.name.name.as_str())
                    .is_some_and(|e| e.is_actor);
                if !self.handler_ofs.iter().any(|of| *of == ty) || !is_actor_face {
                    let faces: Vec<String> = self.handler_ofs.iter().map(|t| t.to_string()).collect();
                    self.error(
                        *span,
                        messages::actor_self_send_no_face(&ty, &h.name.name, &faces.join("`, `")),
                    );
                    return Ty::Unknown;
                }
                // The address exists only when the instance runs as an actor:
                // a `use` of this handler is refused where the binding is
                // chosen, as a `replyto` handler's is [actor-replyto].
                let key = self.symbols.key_or(h, &h.name.name).to_string();
                self.parking_handlers.insert(key.clone());
                if self.record {
                    self.parking_log.push(key);
                }
                Ty::Named { name: ADDR_TYPE.to_string(), args: vec![ty] }
            }
            // [actor-replyto] A parked one-shot continuation targeting a
            // member of the enclosing handler; its value is the linear token.
            Expr::ReplyTo {
                member,
                module,
                captures,
                gated,
                pool,
                span,
            } => self.check_replyto(member, module.as_deref(), captures, *gated, pool.as_deref(), expected, *span),
            // [actor-waitfor] `main`'s bridge: its value is what was sent to
            // the token it mints.
            Expr::WaitFor {
                binding,
                ty,
                body,
                span,
            } => self.check_waitfor(binding, ty, body, *span),
            Expr::While {
                cond,
                body,
                else_block,
                ..
            } => {
                // [loop-while-value] The loop is an expression: its value is the
                // body's tail (last iteration), a `break value`, or the
                // `else` tail when the loop never ran.
                // [is-bind-once] A binding `is` over a non-place subject is the
                // loop's whole condition or it is refused.
                self.reject_unhoistable_is(cond, true, "inside a larger condition");
                let info = self.analyze_cond(cond);
                self.loop_stack.push(LoopCtx {
                    entry_depth: self.locals.len(),
                    ..LoopCtx::default()
                });
                let (body_ty, body_tail) =
                    self.check_loop_body(body, &info.then_narrows.clone(), info.bindings.clone());
                let mut ctx = self.loop_stack.pop().expect("loop ctx pushed above");
                // The code after the loop is reached from the fall-through
                // exit *and* from every `break`: merge the break-path
                // states in, so a value consumed on a break path stays
                // consumed after the loop [deduce-consume].
                let break_states = std::mem::take(&mut ctx.break_states);
                if !break_states.is_empty() {
                    let mut states = vec![self.snapshot_narrows()];
                    states.extend(break_states);
                    self.merge_fallthrough(&states);
                }
                // `else` runs only when the loop never ran, i.e. the
                // condition failed on first evaluation: else-narrows apply.
                let (else_ty, else_tail) = match else_block {
                    Some(b) => {
                        let (t, tail) = self.with_narrows(&info.else_narrows.clone(), |c| {
                            c.check_branch_block(b, Vec::new())
                        });
                        (Some(t), tail)
                    }
                    None => (None, None),
                };
                self.reset_assigned(body);
                if let Some(b) = else_block {
                    self.reset_assigned(b);
                }
                // [loop-never] A `while true` with no `break` targeting it
                // never terminates and never falls through, so it is `Never`
                // — like `return`/`throw`, it ends the path (user decision
                // 2026-10-12). Only the literal `true` counts (no constant
                // folding), and only a `break` of *this* loop lets control
                // out: a `break` in a nested loop targets the inner one (the
                // loop stack already attributes it there), and `continue`,
                // `return`, and `throw` do not fall through here. An `else`
                // is statically unreachable under `while true`, so it does
                // not matter.
                let infinite = matches!(cond.as_ref(), Expr::Bool { value: true, .. })
                    && ctx.breaks.is_empty()
                    && !ctx.may_skip_value;
                if infinite {
                    return Ty::Never;
                }
                self.finish_loop_value(body_ty, body_tail, ctx, else_ty, else_tail)
            }
            Expr::For {
                pattern,
                iterable,
                body,
                else_block,
                span: for_span,
            } => {
                let iter_ty = self.check_expr(iterable, None);
                let elem = match self.step_call_elem_ty(&iter_ty, iterable) {
                    Some(elem) => elem,
                    None => self.for_subject(&iter_ty, iterable, *for_span),
                };
                // [qual-depend] A pass's element may carry a dependent claim
                // whose slot names the pass's own borrowed field
                // (`: Next<self, Idx(self.items) Int>`). The claim is
                // really about the pass's *source* — the list it borrows —
                // so the binding's claim binds the source's roots: what
                // `rev_indices(xs)` emits is an `Idx` of `xs`. Sound
                // because the source cannot be mutated while the pass
                // lives [proj-infer].
                let elem = if Self::ty_has_value_ref(&elem) {
                    let roots = self.pass_source_roots(iterable);
                    if roots.is_empty() {
                        elem
                    } else {
                        Self::fill_value_ref_roots(&elem, &roots)
                    }
                } else {
                    elem
                };
                // [fn-once] Driving a **pass** consumes it: `once Iter<T>`
                // is a position in a sequence, not a recipe, so a second
                // `for` over the same value is the ordinary consumed-use
                // error and the elements are owned by the loop rather than
                // derived from a value that is still alive. A plain
                // `Iter<T>` is a factory: `for` mints a pass from it and
                // leaves it usable, exactly as before.
                // [iter-fn] An *origin* is not a pass: each `for`
                // mints a fresh hidden machine from it, so driving neither
                // consumes nor mutates it and the binding stays an ordinary
                // projection. Only a real pass — the value that *holds* the
                // position — is moved into the loop.
                let recorded = self
                    .out
                    .for_drivers
                    .get(&self.key(iterable.span()))
                    .cloned();
                let drives_origin = recorded.as_ref().is_some_and(|d| d.origin);
                // [iter-drive-in-place] A pass the fn *keeps* is advanced where
                // it lives: the loop mutates it rather than taking it over, so
                // the caller sees the position it reached and may drive it on.
                let drives_in_place = recorded.as_ref().is_some_and(|d| d.in_place);
                // [iter-for] The subject *is* the iterator: `next(e)` drives it
                // (not a minted one, not a step call) — or the `next` is the
                // fn's own implicit, whose element is handed over by value
                // [iter-generic-drive], or a step call is made through a fn
                // value, whose element is the value's own.
                let next_through_implicit = self
                    .out
                    .local_calls
                    .contains(&self.key(iterable.span()).synthetic(Key::FOR_NEXT));
                let drives_pass = !drives_origin
                    && !drives_in_place
                    && (iter_ty.quals().iter().any(|q| q.name == "once")
                        || recorded.as_ref().is_some_and(|d| {
                            if d.step_call {
                                !self.out.call_fn.contains_key(&self.key(iterable.span()))
                            } else {
                                d.mint.is_none() || next_through_implicit
                            }
                        }));
                if drives_in_place {
                    if let Some(place) = crate::place::Place::of_expr(iterable) {
                        let root = place.root.clone();
                        self.fate_mutation_root(&root, iterable.span());
                    }
                }
                // [iter-yield-proj] Whether the pass's `next` emits a *borrow*:
                // then each element shares fate with the pass's source, and
                // driving the pass is a read of that source, not a move.
                let next_borrows = recorded.as_ref().is_some_and(|d| {
                    if d.step_call {
                        self.out
                            .call_fn
                            .get(&self.key(iterable.span()))
                            .copied()
                            .and_then(|k| self.fn_decl_by_key(k))
                            .and_then(|f| f.return_type.as_ref())
                            .is_some_and(|t| !proj_arm_indices(t).is_empty())
                    } else {
                        self.for_next_borrows(iterable)
                    }
                });
                // A pass that is itself a *view* — a local bound from
                // `iter(xs)`, or a call result borrowing its argument — has
                // links of its own; those are the source the elements borrow.
                let view_links: Vec<FateLink> = match iterable.as_ref() {
                    Expr::Ident(id) => self
                        .lookup(&id.name)
                        .map(|v| v.links.clone())
                        .unwrap_or_default(),
                    other => self.links_for_value(other, other.span()),
                };
                let is_view = !view_links.is_empty();
                let links = if drives_pass || drives_in_place {
                    if drives_pass && !is_view {
                        self.fate_move(iterable, "iterate", iterable.span());
                    }
                    if next_borrows && is_view {
                        // The element is a borrow of what the pass walks: it
                        // links to the pass's own links (its source), and the
                        // `borrowed` flag keeps it from ever taking ownership
                        // [proj-readonly-return].
                        view_links
                            .into_iter()
                            .map(|mut l| {
                                l.borrowed = true;
                                l
                            })
                            .collect()
                    } else {
                        // A pass **hands the element over**: `next` returns
                        // `Emitted T` by value, so the binding is an owned
                        // value and not a projection of the pass — which is
                        // what lets a combinator move each element into its
                        // output.
                        Vec::new()
                    }
                } else {
                    // The loop binding is a projection of the iterated
                    // collection: it shares the collection's fate
                    // [fate-link]. It goes through the per-pass bindings
                    // channel so every checking pass re-declares it fresh —
                    // each iteration binds a new element [deduce-consume].
                    self.links_for_value(iterable, iterable.span())
                };
                // [proj-type] Elements are projections of what the loop walks
                // — unless the loop *owns* what it walks: a temporary
                // (`for s in List("x", "y")`) or a pass moved into the loop
                // dies with it, so its elements are the loop's to give away.
                // Nothing to share fate with means nothing to borrow from.
                let elem = if links.is_empty() {
                    elem.strip_top_proj()
                } else {
                    elem
                };
                // [iter-for-elem-write] [ref-handle] Walking a collection of `Mut`
                // elements in place hands out **handles** into it: the loop
                // is a sequence of positions in the walked container, so a
                // body may write through the element (user decision
                // 2026-10-04), as through an `at` mint.
                let elem = if !drives_pass
                    && !drives_in_place
                    && !links.is_empty()
                    && elem.is_proj()
                    && !elem.is_ref()
                    && Self::carries_mut(&elem)
                {
                    promote_proj_to_ref(elem)
                } else {
                    elem
                };
                // [var-let-destructure] A loop element may be destructured: the
                // header binds it to a temporary and the body opens with the
                // pattern's own bindings, read off that temporary.
                let bindings = self.pattern_bindings(pattern, elem, links, Some(iterable.span()));
                self.loop_stack.push(LoopCtx {
                    entry_depth: self.locals.len(),
                    ..LoopCtx::default()
                });
                // [iter-fn] While this loop is open, the origin it
                // drives is off limits for mutation. Keyed on the subject's
                // *root* variable, so `add(b.rows, …)` — a write through a
                // projection — reports too: everything reachable from the
                // origin is what the machine may read.
                let driven = if drives_origin {
                    crate::place::Place::of_expr(iterable).map(|p| p.root.clone())
                } else {
                    None
                };
                if let Some(root) = &driven {
                    self.driven_origins.push((root.clone(), iterable.span()));
                }
                let (body_ty, body_tail) = self.check_loop_body(body, &[], bindings);
                if driven.is_some() {
                    self.driven_origins.pop();
                }
                let mut ctx = self.loop_stack.pop().expect("loop ctx pushed above");
                // Merge break-path states into the after-loop state (the
                // loop-binding frame is popped first, so the snapshots'
                // shared outer frames align) [deduce-consume].
                let break_states = std::mem::take(&mut ctx.break_states);
                if !break_states.is_empty() {
                    let mut states = vec![self.snapshot_narrows()];
                    states.extend(break_states);
                    self.merge_fallthrough(&states);
                }
                let (else_ty, else_tail) = match else_block {
                    Some(b) => {
                        let (t, tail) = self.check_branch_block(b, Vec::new());
                        (Some(t), tail)
                    }
                    None => (None, None),
                };
                self.reset_assigned(body);
                if let Some(b) = else_block {
                    self.reset_assigned(b);
                }
                self.finish_loop_value(body_ty, body_tail, ctx, else_ty, else_tail)
            }
            Expr::Lambda { params, body, span } => self.check_lambda(params, body, *span, expected),
            Expr::Spread { operand, .. } => self.check_expr(operand, None),
            // [comptime-default] Checked once where its struct is declared;
            // here it is a value of the field's type. The owner is lowered so
            // the IR can find the struct the expansion meant.
            Expr::FieldDefault { owner, ty, .. } => {
                let _ = self.lower_type(owner);
                self.lower_type(ty)
            }
            Expr::Error { .. } => Ty::Unknown,
        }
    }

    /// Records where an accessed field is declared [lsp-definition]. The
    /// struct's own field, even when a predicate qualifier overrides its
    /// type [qual-field-override]: the override refines the field, it does
    /// not replace the declaration.
    ///
    /// [generic-arity]'s `name` (the `Ty::Named` key) is the struct's
    /// **disambiguation key** (`Arg§main` once another module's `Arg` has
    /// already claimed the plain name — see typekey.rs) — the same key
    /// `self.symbols.structs` is keyed by. `self.scope.def_sites`, however,
    /// is keyed by the plain declared name only (`resolve.rs`'s `def_site`
    /// closure inserts `name`, never a key): a lookup with the qualified
    /// key missed there even though the struct and its field both
    /// resolved, silently recording no reference at all (defect found
    /// 2026-10-20: a field's rename reached a dot-access read but not a
    /// struct-literal label, and on closer look, not even every dot-access
    /// — only structs whose name happened to be globally unique). Strip the
    /// key down to its plain name — `typekey::plain` — before this lookup.
    fn record_field_ref(&mut self, base_ty: &Ty, field: &Ident) {
        let Ty::Named { name, .. } = base_ty.strip_quals() else {
            return;
        };
        let Some(decl) = self.symbols.structs.get(name.as_str()).copied() else {
            return;
        };
        let Some(f) = decl.fields.iter().find(|f| f.name.name == field.name) else {
            return;
        };
        // The struct's `DefSite` names the file it was declared in; the
        // field span comes from that same declaration. `def_sites` keys by
        // the plain name, not the disambiguation key.
        let Some(site) = self.scope.def_sites.get(crate::typekey::plain(name.as_str())).copied() else {
            return;
        };
        self.out.field_refs.insert(
            self.key(field.span),
            DefSite {
                file: site.file,
                span: f.name.span,
            },
        );
    }

    fn field_ty_or_error(&mut self, base_ty: &Ty, field: &Ident) -> Ty {
        match self.field_ty(base_ty, &field.name) {
            Some(t) => t,
            None => {
                // [struct-field-resolve] Only structs have fields, and only the
                // ones they declare. A target-language member is reached by
                // declaring an accessor, not by reading
                // through an opaque type — so an unknown field is an error
                // (user decision 2026-09-03). A generic value exposes
                // nothing either: Salvo has no bounds, so `T` is opaque.
                // Only an *un-inferred* base (`Unknown`) stays lenient
                // [type-unknown-lenient].
                let stripped = base_ty.strip_quals().clone();
                match &stripped {
                    Ty::Named { name, .. } if self.symbols.structs.contains_key(name.as_str()) => {
                        let name = name.clone();
                        self.error(
                            field.span,
                            messages::struct_field_resolve_no_field(&name, &field.name),
                        );
                    }
                    Ty::Unknown | Ty::Never => {}
                    // [type-unknown-lenient] A name that resolved to no
                    // declaration here but names a struct elsewhere (an
                    // unimported one; resolution reported it) is not read
                    // through: one mistake, one diagnostic.
                    Ty::Named { name, .. } if !self.symbols.key_modules.contains_key(name.as_str()) && self.symbols.structs.keys().any(|k| crate::typekey::plain(k) == name.as_str()) => {}
                    // A generic parameter needs its own wording: adding an
                    // accessor cannot help, because nothing is known about
                    // `T` at all.
                    Ty::Var(name) => {
                        let name = name.clone();
                        self.error(
                            field.span,
                            messages::struct_field_resolve_type_param(&name, &field.name),
                        );
                    }
                    other => {
                        let other = other.clone();
                        self.error(
                            field.span,
                            messages::struct_field_resolve_not_a_struct(&other, &field.name),
                        );
                    }
                }
                Ty::Unknown
            }
        }
    }

    fn field_ty(&mut self, base_ty: &Ty, field_name: &str) -> Option<Ty> {
        if let Some(t) = self.field_override_ty(base_ty, field_name) {
            return Some(t);
        }
        self.declared_field_ty(base_ty, field_name)
    }

    /// The type of `base.index` [expr-tuple-index]: the element at a
    /// constant position of a tuple. Only tuples have elements, and the
    /// position must exist — both are errors rather than leniency, since
    /// the index is written in the source and cannot be interop-dependent.
    /// A non-tuple `Unknown` base stays lenient
    /// [type-unknown-lenient].
    fn tuple_elem_ty_or_error(&mut self, base_ty: &Ty, index: usize, span: Span) -> Ty {
        match base_ty.strip_quals() {
            Ty::Tuple(elems) => match elems.get(index) {
                Some(t) => t.clone(),
                None => {
                    let len = elems.len();
                    self.error(
                        span,
                        messages::expr_tuple_index_out_of_range(&base_ty, &len, &index),
                    );
                    Ty::Unknown
                }
            },
            other if other.is_unknown() || matches!(other, Ty::Never) => Ty::Unknown,
            _ => {
                self.error(span, messages::expr_tuple_index_not_a_tuple(&index, &base_ty));
                Ty::Unknown
            }
        }
    }

    /// A predicate-qualifier field override for this (qualified) base type,
    /// e.g. `surname: Str` under `Surname Person`.
    fn field_override_ty(&mut self, base_ty: &Ty, field_name: &str) -> Option<Ty> {
        for qual in base_ty.quals() {
            let Some(decl) = self.qualifier_for(qual.name.as_str(), Some(base_ty)) else {
                continue;
            };
            let Some(field) = decl
                .field_overrides
                .iter()
                .find(|f| f.name.name == field_name)
            else {
                continue;
            };
            let mut subst = HashMap::new();
            for (i, g) in decl.generics.iter().enumerate() {
                subst.insert(
                    g.name.clone(),
                    qual.args.get(i).cloned().unwrap_or(Ty::Unknown),
                );
            }
            let field_ty = field.written_ty().clone();
            return Some(self.lower_type_subst(&field_ty, &subst, 0));
        }
        None
    }

    /// The declared struct-field type, ignoring qualifier overrides.
    fn declared_field_ty(&mut self, base_ty: &Ty, field_name: &str) -> Option<Ty> {
        let Ty::Named { name, args } = base_ty.strip_quals() else {
            return None;
        };
        let decl: &'p StructDecl = self.symbols.structs.get(name.as_str())?;
        let field = decl.fields.iter().find(|f| f.name.name == field_name)?;
        // [handler-state-infer] A generated iterator struct's inferred state field has
        // no written type; the minter's literal determined it and the checker
        // recorded it at the field-name span (the channel the IR reads too).
        // Return the inferred type as declared — the `Mut`-ness of a read flows
        // from a `Mut` base exactly as for a written field type, so it must not
        // be added here (that would make `at = at + 1` fail to assign `Int`
        // into a spuriously-`Mut Int` field).
        if field.ty.is_none() {
            return Some(
                self.out
                    .expr_ty
                    .get(&self.key(field.name.span))
                    .cloned()
                    .unwrap_or(Ty::Unknown),
            );
        }
        let mut subst = HashMap::new();
        for (i, g) in decl.generics.iter().enumerate() {
            subst.insert(g.name.clone(), args.get(i).cloned().unwrap_or(Ty::Unknown));
        }
        let mutable = base_ty.quals().iter().any(|q| q.name == "Mut");
        Some(self.struct_field_ty(field, &subst, mutable))
    }

    /// [struct-field-canbe-mut] A field's type in a struct value: the declared type
    /// under `subst`, gaining `Mut` when the field says `canbe Mut` and the
    /// struct value is `Mut`. Every reading of a declared field type (reads,
    /// literals, destructuring) goes through here, so a plain struct is
    /// immutable all the way down.
    fn struct_field_ty(&mut self, field: &ast::FieldDecl, subst: &HashMap<String, Ty>, mutable: bool) -> Ty {
        let ty = self.lower_type_subst(field.written_ty(), subst, 0);
        if field.canbe_mut && mutable && !ty.quals().iter().any(|q| q.name == "Mut") && self.has_auto_mut(&ty) {
            let mut quals = ty.quals().to_vec();
            quals.push(Qual::plain("Mut", Vec::new()));
            ty.strip_quals().clone().qualify(quals)
        } else {
            ty
        }
    }

    /// [iter-protocol] [group-obligation] Whether this type's declaration
    /// states the designated `: Next<T>` obligation — the one fact that
    /// makes a value a **pass** (roadmap R2, user decisions 2026-09-08).
    /// `for` reads the declaration; it does not scan overloads for a `next`
    /// and guess.
    fn next_obligation(&self, stripped: &Ty) -> Option<(&'p StructDecl, &'p TypeRef)> {
        let Ty::Named { name, .. } = stripped else {
            return None;
        };
        let decl: &'p StructDecl = self.symbols.structs.get(name.as_str()).copied()?;
        let ob = decl
            .obligations
            .iter()
            .map(|o| &o.group)
            .find(|g| g.name.name == "Next")?;
        Some((decl, ob))
    }

    /// [implicit-group] [iter-protocol] A `?Next<It, T>` spread teaches `T`
    /// from the *declaration* of whatever `It` turned out to be: a pass says
    /// what it yields at its `: Next<self, T>` clause, so a combinator's
    /// element type never has to be written and a bare lambda can be typed
    /// against it. Reaches through an origin mint [iter-fn].
    ///
    /// [proj-type] The pass also decides whether its elements are *borrowed*:
    /// a binding an argument made (`(s: Str) -> …`) is widened to the pass's
    /// `proj Str` when it fits under it — a kept lambda parameter reads the
    /// projection just fine, and the `next` that fills the spread returns it.
    fn learn_next_elems(
        &mut self,
        decl: &'p FnDecl,
        callee_generics: &HashSet<String>,
        subst: &mut HashMap<String, Ty>,
    ) {
        for (state_var, elem_var) in self.next_spread_pairs(decl) {
            if !callee_generics.contains(&elem_var) {
                continue;
            }
            let Some(state) = subst.get(&state_var).cloned() else {
                continue;
            };
            let Some(elem) = self.pass_or_origin_elem_ty(&state) else {
                continue;
            };
            if elem.is_unknown() {
                continue;
            }
            match subst.get(&elem_var).cloned() {
                None => {
                    subst.insert(elem_var, elem);
                }
                Some(bound) if bound != elem && is_subtype(&bound, &elem) => {
                    subst.insert(elem_var, elem);
                }
                Some(_) => {}
            }
        }
    }

    /// The `(state, element)` type-variable pairs a signature spreads as
    /// `?Next<It, T>` — what a combinator's element type can be *inferred*
    /// from [implicit-group].
    fn next_spread_pairs(&self, decl: &'p FnDecl) -> Vec<(String, String)> {
        let mut out = Vec::new();
        for g in &decl.implicit_groups {
            if g.name.name != "Next" || g.args.len() < 2 {
                continue;
            }
            let (
                Some(ast::Type::Named { base: state, .. }),
                Some(ast::Type::Named { base: elem, .. }),
            ) = (g.args.first(), g.args.get(1))
            else {
                continue;
            };
            out.push((state.name.name.clone(), elem.name.name.clone()));
        }
        out
    }

    /// The element type of a pass **or** of the origin behind a minted machine
    /// [iter-fn]: read from the `: Next<self, T>` clause, which is
    /// where a pass declares what it yields [group-obligation].
    fn pass_or_origin_elem_ty(&mut self, state: &Ty) -> Option<Ty> {
        let bare = state.strip_quals().clone();
        if let Some(elem) = self.pass_declared_elem_ty(&bare) {
            return Some(elem);
        }
        // A machine stands for its origin, whose declaration carries the clause.
        let Ty::Named { name, args } = &bare else {
            return None;
        };
        let origin = name.strip_prefix(ORIGIN_PASS_PREFIX)?;
        let origin_ty = Ty::Named {
            name: origin.to_string(),
            args: args.clone(),
        };
        self.pass_declared_elem_ty(&origin_ty)
    }

    /// The element type a pass *declares* it yields, read from the obligation
    /// alone [group-obligation] — no `next` resolved and no driver recorded,
    /// which is what the native container loop needs [iter-for-native].
    fn pass_declared_elem_ty(&mut self, pass: &Ty) -> Option<Ty> {
        let (decl, ob) = self.next_obligation(pass)?;
        let subst: HashMap<String, Ty> = decl
            .generics
            .iter()
            .map(|g| g.name.clone())
            .zip(match pass {
                Ty::Named { args, .. } => args.clone(),
                _ => Vec::new(),
            })
            .collect();
        let saved = self.enter_generics(&decl.generics);
        let elem = next_elem_arg(ob).map(|a| self.lower_type_subst(a, &subst, 0));
        self.generics = saved;
        elem
    }

    /// [iter-drive-in-place] Whether a `for` subject is a place the enclosing
    /// fn **keeps**: a parameter its contract hands back, or a projection of
    /// one. Driving such a pass has to be visible to the caller, so the loop
    /// advances it in place rather than binding it into a local.
    fn drives_in_place(&self, iterable: &'p Expr) -> bool {
        // [iter-drive-in-place] Any *named place* is driven where it lives
        // (user decision 2026-09-12, extending the kept-parameter rule to
        // locals and owned parameters): a `for` never consumes a variable,
        // so a linear pass is bound, driven, and explicitly discharged
        // after — the loop is not a discharge site. Only a *temporary*
        // subject (a minted pass, a call result) is consumed by the loop.
        crate::place::Place::of_expr(iterable)
            .map(|p| self.lookup(&p.root).is_some())
            .unwrap_or(false)
    }

    /// The declaration behind a `DeclId`, through its own file's scope (which
    /// holds every fn the file declares, private ones included).
    fn fn_decl_by_key(&self, key: DeclId) -> Option<&'p FnDecl> {
        self.resolution
            .scopes
            .get(self.resolution.decls.file(key))?
            .fns
            .values()
            .flatten()
            .find(|e| e.key == key)
            .map(|e| e.decl)
    }

    /// [iter-step-call] A `for` over a **step call**: `for i in next(p)`,
    /// `for i in step(a, b)` — a call whose result is `Emitted T | Finished`
    /// (user decision 2026-09-26). The call *is* the loop's condition, re-invoked
    /// each turn until `Finished`, which is what lets a non-canonical step (a
    /// second `next` over the same struct, a step under any other name) be
    /// driven at all. Its arguments are evaluated as written on every turn, so
    /// each must be a **place or a literal** — the same value each time — and
    /// the callee must **keep** every one of them: a step that consumed its
    /// argument could not be called twice on it (the general form of "`next`
    /// takes `Mut It`"). A value of that shape that is *not* a call is refused:
    /// a union is not iterable, and only a call can be re-invoked.
    ///
    /// `None` when the subject is not of the step shape at all, so the ordinary
    /// resolution runs.
    fn step_call_elem_ty(&mut self, iter_ty: &Ty, iterable: &'p Expr) -> Option<Ty> {
        let (elem, emitted_arm, arms) = emitted_arm_ty(iter_ty.strip_quals())?;
        let span = iterable.span();
        let Expr::Call {
            callee,
            args,
            named,
            span: call_span,
            ..
        } = iterable
        else {
            self.error(span, messages::iter_step_call_step_value(&iter_ty));
            return Some(Ty::Unknown);
        };
        let mut all: Vec<&'p Expr> = Vec::new();
        if let Expr::Field { base, .. } = callee.as_ref() {
            all.push(base);
        }
        all.extend(args.iter());
        all.extend(named.iter().map(|n| &n.value));
        for a in &all {
            if !is_step_call_arg(a) {
                self.error(a.span(), messages::iter_step_call_argument_not_place());
            }
        }
        // The callee's contract: every argument kept, so the call can repeat.
        let callee_key = self.out.call_fn.get(&self.key(*call_span)).copied();
        let callee_name = match callee.as_ref() {
            Expr::Ident(id) => id.name.clone(),
            Expr::Field { field, .. } => field.name.clone(),
            _ => "step".to_string(),
        };
        if let Some(key) = callee_key {
            if let Some(decl) = self.fn_decl_by_key(key) {
                let contract = self.effective_contract(Some(key), decl);
                let fixed: Vec<&ast::Param> =
                    decl.params.iter().filter(|p| !p.implicit).collect();
                for (i, p) in fixed.iter().enumerate() {
                    let kept = contract
                        .as_ref()
                        .and_then(|c| c.iter().find(|d| d.param == p.name.name))
                        .map(|d| d.kept)
                        .unwrap_or(true);
                    if !kept {
                        let at = all.get(i).map(|a| a.span()).unwrap_or(span);
                        self.error(
                            at,
                            messages::iter_step_call_consumes_argument(&callee_name, &p.name.name),
                        );
                    }
                }
            }
        }
        self.out.for_drivers.insert(
            self.key(span),
            PassDriver { emitted_arm, arms, origin: false, in_place: false, mint: None, step_call: true },
        );
        Some(elem)
    }

    /// Whether a `for` subject is one of the containers a backend iterates
    /// natively [iter-for-native]: an `intrinsic type` (a list, a `Str`; an
    /// array is a language-level type and never reaches here). Every other
    /// container is walked through the pass its `iter` mints.
    fn is_intrinsic_container(&self, subject: &Ty) -> bool {
        match subject {
            Ty::Named { name, .. } => self
                .symbols
                .intrinsic_types
                .get(name.as_str())
                // [platform-iterable] An `iterable platform type` loops over
                // its host's `each`.
                .is_some_and(|d| d.intrinsic || (d.platform && d.iterable)),
            _ => false,
        }
    }

    /// [iter-for] [iter-protocol] Whether something named `name` takes a
    /// value of type `ty` as the one argument a `for` hands it — the question
    /// "does a `next` fit" that decides between driving the subject and
    /// minting from it (R10 D10). Asked of every candidate the call would
    /// have: the enclosing fn's own implicits [implicit-resolve-body], the
    /// available effects' members (R10 D3) and the visible fns, renamed ones
    /// under their new name only [fn-rename]. By shape, as an [implicit-fit]
    /// probe is: the call that follows ranks, fills and reports. A `next` is
    /// one only with `next`'s result shape, `Emitted T | Finished` (D-3): a
    /// `next` of any other shape is an ordinary fn [op-unique-shape].
    fn for_fits(&mut self, name: &str, ty: &Ty) -> bool {
        let arg = crate::literal::widen(ty).strip_quals().clone();
        let shaped = |ret: &Ty| name != "next" || ret.is_unknown() || emitted_arm_ty(ret.strip_quals()).is_some();
        if self.own_implicits.iter().any(|p| Self::own_for_fit(p, name, ty)) {
            return true;
        }
        for m in self.available_members(name) {
            let (full, _) = self.member_value_ty(&m);
            let Ty::Fn { params, ret, .. } = full else { continue };
            let fixed: Vec<&Ty> = m.decl.params.iter().zip(&params).filter(|(p, _)| !p.implicit).map(|(_, t)| t).collect();
            if fixed.len() == 1 && shaped(&ret) && unify(fixed[0].strip_quals(), &arg, &mut HashMap::new()) {
                return true;
            }
        }
        for entry in self.overloads_of(name) {
            let decl = entry.decl;
            let fixed: Vec<&ast::Param> = decl.params.iter().filter(|p| !p.implicit && !p.variadic).collect();
            if !Self::call_shape_fits(&fixed, false, 1, &[]) || !self.may_take(decl, &fixed[0].ty, &arg) {
                continue;
            }
            let saved = self.enter_generics(&decl.generics);
            let pt = self.lower_type(&fixed[0].ty);
            let ret = decl.return_type.as_ref().map(|t| self.lower_type(t)).unwrap_or_else(Ty::none);
            self.generics = saved;
            if shaped(&ret) && unify(pt.strip_quals(), &arg, &mut HashMap::new()) {
                return true;
            }
        }
        false
    }

    /// [iter-for] A cheap pre-test for [`Checker::for_fits`], read off the
    /// written parameter: a parameter naming a struct or an intrinsic type
    /// — not one of the fn's own type parameters, not an alias — takes only a
    /// value of that type, so a value of another one need not have the
    /// parameter lowered and unified at all.
    fn may_take(&self, decl: &FnDecl, param: &ast::Type, arg: &Ty) -> bool {
        let base = match param {
            ast::Type::Named { base, .. } => base,
            ast::Type::QualifiedGroup { base, .. } => match base.as_ref() {
                ast::Type::Named { base, .. } => base,
                _ => return true,
            },
            _ => return true,
        };
        let written = base.name.name.as_str();
        // [type-identity] An alias as the file that wrote the parameter sees
        // it: by written name in the keyed table, only std's were found.
        if decl.generics.iter().any(|g| g.name == written) || self.named(base).alias.is_some() {
            return true;
        }
        match arg {
            Ty::Named { name, .. } => name.split('§').next() == Some(written),
            _ => false,
        }
    }

    /// [iter-for] [implicit-resolve-body] Whether the enclosing fn's own
    /// implicit `p` takes the `for`'s call `name(ty)`: named so, one
    /// parameter the value fits, and for `next` the `Emitted T | Finished`
    /// result.
    fn own_for_fit(p: &ImplicitParam, name: &str, ty: &Ty) -> bool {
        if p.name != name {
            return false;
        }
        match p.ty.strip_quals() {
            Ty::Fn { params, ret, .. } => {
                params.len() == 1
                    && Self::arg_fits_fn_value(ty, &params[0])
                    && (name != "next" || emitted_arm_ty(ret.strip_quals()).is_some())
            }
            _ => false,
        }
    }

    /// [iter-for] The call `name(ty)` a `for` names, resolved as that call
    /// is, its facts at `key` (`Key::FOR_NEXT` / `Key::FOR_ITER` of the
    /// subject's node): the enclosing fn's own implicit of the name first
    /// [implicit-resolve-body], ranked like overloads [implicit-same-name],
    /// then `resolve_named_call` over the available members and the visible
    /// fns, with the argument typed (`subject` is only a stand-in for its
    /// position). Answers the call's result type, `Unknown` when it was
    /// refused (and reported).
    #[allow(clippy::too_many_arguments)]
    fn for_call(&mut self, name: &'static str, subject: &'p Expr, ty: &Ty, key: Key, at: Span, call: String, shown: &Ty) -> Ty {
        let loc = subject.span();
        match self.pick_own_implicit(name, &|p: &ImplicitParam| Self::own_for_fit(p, name, ty)) {
            Ok(Some(own)) => {
                self.out.local_calls.insert(key);
                self.out.local_call_names.insert(key, own.local.clone());
                let (ret, effects) = match self.lookup(&own.local).map(|v| v.narrowed.strip_quals().clone()) {
                    Some(Ty::Fn { ret, effects, .. }) => (*ret, effects),
                    _ => match own.ty.strip_quals().clone() {
                        Ty::Fn { ret, effects, .. } => (*ret, effects),
                        _ => (Ty::Unknown, Vec::new()),
                    },
                };
                if let Some(v) = self.lookup_mut(&own.local) {
                    v.used = true;
                }
                let saved = self.for_site.replace(ForSite { at, key, loc, call, subject: shown.clone(), interp: false });
                self.check_fn_value_effects(&effects, at);
                self.for_site = saved;
                return ret;
            }
            Ok(None) => {}
            Err(tied) => {
                let saved = self.for_site.replace(ForSite { at, key, loc, call, subject: shown.clone(), interp: false });
                self.own_implicit_tie(name, &tied, at);
                self.for_site = saved;
                return Ty::Unknown;
            }
        }
        let saved = self.for_site.replace(ForSite { at, key, loc, call, subject: shown.clone(), interp: false });
        self.pending_arg_tys = Some(vec![ty.clone()]);
        self.pending_typed_only = true;
        let args: [&'p Expr; 1] = [subject];
        let got = self.resolve_named_call(name, at, &[], &args, &[], None, None, at);
        self.pending_arg_tys = None;
        self.pending_typed_only = false;
        self.for_site = saved;
        got
    }

    /// [iter-for] Forgets the call facts a `for` recorded at `key`: the native
    /// loop a backend writes for a container makes no call [iter-for-native],
    /// so nothing it would have reached is reached.
    fn forget_for_call(&mut self, key: Key) {
        self.out.call_fn.remove(&key);
        self.out.call_type_args.remove(&key);
        self.out.implicit_args.remove(&key);
        self.out.call_effects.remove(&key);
        self.out.effect_calls.remove(&key);
    }

    /// [iter-for] Whether the call a `for` recorded at `key` went to a
    /// declared fn — not the enclosing fn's implicit, not an effect member.
    fn for_call_is_decl(&self, key: Key) -> bool {
        self.out.call_fn.contains_key(&key) && !self.out.local_calls.contains(&key) && !self.out.member_calls.contains_key(&key)
    }

    /// [iter-protocol] Whether the `next` a `for` resolved at `key` takes its
    /// state as `Mut`, and the state type to name when it does not: a
    /// declared fn's or member's first parameter, the implicit's parameter.
    fn for_next_state(&mut self, key: Key, pass: &Ty) -> (bool, Ty) {
        if let Some(name) = self.out.local_call_names.get(&key).cloned() {
            let ty = self.lookup(&name).map(|v| v.narrowed.clone()).or_else(|| self.own_implicits.iter().find(|p| p.local == name).map(|p| p.ty.clone()));
            if let Some(Ty::Fn { params, .. }) = ty.map(|t| t.strip_quals().clone()) {
                if let Some(p) = params.first() {
                    return (p.quals().iter().any(|q| q.name == "Mut"), pass.strip_quals().clone());
                }
            }
            return (true, pass.clone());
        }
        if let Some(mc) = self.out.member_calls.get(&key).cloned() {
            let Some(effect) = self.symbols.effects.get(mc.effect.as_str()).copied() else { return (true, pass.clone()) };
            let Some(member) = effect.fns.get(mc.index) else { return (true, pass.clone()) };
            let Some(p) = member.params.iter().find(|p| !p.implicit) else { return (true, pass.clone()) };
            let saved = self.enter_generics(&effect.generics);
            self.enter_generics(&member.generics);
            let pt = self.lower_type(&p.ty);
            self.generics = saved;
            return (pt.quals().iter().any(|q| q.name == "Mut"), pt.strip_quals().clone());
        }
        let Some(decl) = self.out.call_fn.get(&key).copied().and_then(|k| self.fn_decl_by_key(k)) else { return (true, pass.clone()) };
        let Some(p) = decl.params.iter().find(|p| !p.implicit) else { return (true, pass.clone()) };
        let saved = self.enter_generics(&decl.generics);
        let pt = self.lower_type(&p.ty);
        self.generics = saved;
        (pt.quals().iter().any(|q| q.name == "Mut"), pt.strip_quals().clone())
    }

    /// [iter-for] [iter-resolve] The element type of `for x in e`, which is
    /// the calls it names (OPERATOR_OVERLOAD.md O1, R10 D10): `next(e)` when a
    /// `next` takes `e` — `e` is an **iterator**, driven where it lives —
    /// and otherwise `next(iter(e))` — `e` is a **source**, and the loop
    /// mints an iterator from it first. Each call is resolved as it would be
    /// written [fn-overload-rank] [fn-rename] [implicit-resolve-body], so no
    /// `: Next` or `: Iter` declaration is needed; a type with both a `next`
    /// and an `iter` is driven (P15). What the loop does with the calls is
    /// `Checked::for_drivers`; the calls' own facts are the call tables at
    /// `Key::FOR_NEXT` and `Key::FOR_ITER` of the subject's node. A container
    /// a backend walks natively (an array, an `iterable platform type`), when
    /// both calls went to declarations, records neither [iter-for-native].
    fn for_subject(&mut self, iter_ty: &Ty, iterable: &'p Expr, for_span: Span) -> Ty {
        let span = iterable.span();
        let ty = crate::literal::widen(iter_ty);
        let subject = ty.strip_quals().clone();
        if subject.is_unknown() || matches!(subject, Ty::Never) {
            return Ty::Unknown;
        }
        let node = self.key(span);
        let (next_key, iter_key) = (node.synthetic(Key::FOR_NEXT), node.synthetic(Key::FOR_ITER));
        // 1. An iterator: `next(e)`.
        if self.for_fits("next", &ty) {
            let call = format!("next({subject})");
            let ret = self.for_call("next", iterable, &Self::driven(&ty), next_key, for_span, call.clone(), &subject);
            return self.for_drive(&ty, ret, next_key, None, iterable, &call, &subject);
        }
        // 2. A source: `next(iter(e))`.
        if self.for_fits("iter", &ty) {
            let call = format!("next(iter({subject}))");
            let before = self.out.errors.len();
            let it = self.for_call("iter", iterable, &ty, iter_key, for_span, format!("iter({subject})"), &subject);
            if it.is_unknown() || matches!(it, Ty::Never) {
                return Ty::Unknown;
            }
            if !self.for_fits("next", &it) {
                self.error(
                    span,
                    messages::iter_protocol_no_next(&subject, &call, &it, &it.strip_quals()),
                );
                return Ty::Unknown;
            }
            let ret = self.for_call("next", iterable, &Self::driven(&it), next_key, for_span, call.clone(), &subject);
            // [iter-for-native] A container the backends walk themselves.
            let native = (matches!(subject, Ty::Array(_)) || self.is_intrinsic_container(&subject))
                && self.for_call_is_decl(iter_key)
                && self.for_call_is_decl(next_key);
            if native {
                // The loop makes neither call, so what a call instantiating
                // `iter<T>` would refuse (a linear `T` [linear-generics]) is
                // not refused: only the element type is read off them.
                self.out.errors.truncate(before);
                self.forget_for_call(iter_key);
                self.forget_for_call(next_key);
                return match &subject {
                    Ty::Array(elem) => (**elem).clone(),
                    _ => emitted_arm_ty(ret.strip_quals()).map(|(elem, _, _)| elem).unwrap_or(Ty::Unknown),
                };
            }
            return self.for_drive(&it, ret, next_key, Some(it.clone()), iterable, &call, &subject);
        }
        // An iterator struct whose `: Next<self, T>` promise no `next` keeps
        // is refused at its declaration [group-obligation]; the loop stays
        // quiet then, one mistake one diagnostic [type-unknown-lenient].
        if let Some(elem) = self.broken_next_promise(&subject) {
            return elem;
        }
        let home = match &subject {
            Ty::Named { name, .. } => self.symbols.structs.get(name.as_str()).copied().and_then(|d| self.home_next(d).map(|f| (d, f))),
            _ => None,
        };
        let remedy = match &subject {
            // [fn-attached] A `next` declared with the struct travels with
            // it, so the struct is what this file has not imported.
            _ if home.is_some_and(|(_, f)| f != self.file_idx) => {
                let (d, f) = home.expect("checked above");
                format!(
                    ": a `next` over it is declared in `{}`, and is not in scope here — import \
                     `{}.{}`, whose `next` travels with it",
                    self.files[f].module,
                    self.files[f].module,
                    d.name.name
                )
            }
            Ty::Named { name, .. } if self.symbols.structs.contains_key(name.as_str()) => format!(
                ": declare `next(it: Mut {subject}) -> Emitted T | Finished` beside it to make it an \
                 iterator, or an `iter` to make it a source, or loop over a step call (`for x in \
                 step(p)`)"
            ),
            _ => String::new(),
        };
        self.error(span, messages::iter_resolve_not_iterable(&subject, &remedy));
        Ty::Unknown
    }

    /// [iter-protocol] [iter-drive-in-place] What `next` is handed: the
    /// iterator in the loop's mutable place — the place it lives in, or the
    /// loop's own binding of a temporary — so `Mut` whether the value's type
    /// says so or not, as the driving always was.
    fn driven(ty: &Ty) -> Ty {
        if ty.quals().iter().any(|q| q.name == "Mut") {
            return ty.clone();
        }
        ty.clone().qualify(vec![Qual { effect: false, name: "Mut".to_string(), args: Vec::new() }])
    }

    /// [type-unknown-lenient] [group-obligation] The element type `subject`'s
    /// `: Next<self, T>` clause promises, when the promise is broken where it
    /// is made: the group is unknown in the struct's file, or no `next` of the
    /// protocol's shape over the struct is declared there — the one place it
    /// may be [op-unique-shape] — so the clause has been refused there already,
    /// and the loop answers the promised element instead of a second
    /// diagnostic. `None` whenever such a `next` exists, even one this loop
    /// cannot reach: then the loop's own error is the only one.
    fn broken_next_promise(&mut self, subject: &Ty) -> Option<Ty> {
        let (decl, _) = self.next_obligation(subject)?;
        let file = self.resolution.decls.file_of(decl.name.span)?;
        let scope = self.resolution.scopes.get(file)?;
        // A group the struct's file cannot see is refused there as unknown.
        if scope.fn_groups.contains_key("Next") && self.home_next(decl).is_some() {
            return None;
        }
        self.pass_declared_elem_ty(subject)
    }

    /// [iter-protocol] [op-unique-shape] The file of `decl` when it declares a
    /// `next` of the protocol's shape over the struct — the one place such a
    /// `next` may be — whether or not this file can reach it.
    fn home_next(&mut self, decl: &'p StructDecl) -> Option<usize> {
        let file = self.resolution.decls.file_of(decl.name.span)?;
        let scope = self.resolution.scopes.get(file)?;
        let entries: Vec<crate::resolve::FnEntry<'p>> = scope.fns.get("next").cloned().unwrap_or_default();
        let key = self.symbols.key_or(decl, &decl.name.name).to_string();
        let saved_scope = self.scope;
        let saved_errors = self.out.errors.len();
        self.scope = scope;
        let mut found = false;
        for e in entries {
            if self.resolution.decls.file(e.key) != file || (file == self.file_idx && self.renamed_away("next", e.key)) {
                continue;
            }
            let fixed: Vec<&ast::Param> = e.decl.params.iter().filter(|p| !p.implicit).collect();
            let [p] = fixed.as_slice() else { continue };
            let saved = self.enter_generics(&e.decl.generics);
            let pt = self.lower_type(&p.ty);
            let ret = e.decl.return_type.as_ref().map(|t| self.lower_type(t)).unwrap_or_else(Ty::none);
            self.generics = saved;
            if matches!(pt.strip_quals(), Ty::Named { name, .. } if *name == key) && emitted_arm_ty(ret.strip_quals()).is_some() {
                found = true;
                break;
            }
        }
        self.scope = saved_scope;
        self.out.errors.truncate(saved_errors);
        found.then_some(file)
    }

    /// [iter-protocol] Drives `pass` with the `next` resolved at `next_key`,
    /// which answered `ret`: the element is its `Emitted` arm, the state must
    /// be `Mut`, a named iterator is driven where it lives
    /// [iter-drive-in-place], and a linear one the loop would consume is
    /// refused [linear-group]. `minted` is the iterator's type when `iter`
    /// made it [iter-mint].
    #[allow(clippy::too_many_arguments)]
    fn for_drive(&mut self, pass: &Ty, ret: Ty, next_key: Key, minted: Option<Ty>, iterable: &'p Expr, call: &str, subject: &Ty) -> Ty {
        let span = iterable.span();
        if ret.is_unknown() || matches!(ret, Ty::Never) {
            return Ty::Unknown;
        }
        let Some((elem, emitted_arm, arms)) = emitted_arm_ty(ret.strip_quals()) else {
            self.error(span, messages::iter_protocol_next_return(&subject, &call, &ret));
            return Ty::Unknown;
        };
        // [iter-protocol] Advancing an iterator mutates its position, and the
        // backends pass a mutable place.
        let (mutable, state) = self.for_next_state(next_key, pass);
        if !mutable {
            self.error(span, messages::iter_protocol_next_not_mut(&state));
        }
        let bare = pass.strip_quals().clone();
        // [linear-group] No implicit discharge sites (user decision
        // 2026-09-12): a `for` never closes an iterator, so a consuming drive
        // of a linear one is refused. [iter-drive-in-place] A named one is
        // the owner's, advanced where it lives; a minted one is the loop's.
        let in_place = minted.is_none() && self.drives_in_place(iterable);
        if !in_place && !matches!(bare, Ty::Var(_)) && self.ty_own_linear(&bare) {
            let hint = self.linear_discharge_hint(&bare);
            self.error(span, messages::iter_drive_in_place_linear_consumed(&bare, &hint));
        } else if !in_place && minted.is_none() && matches!(bare, Ty::Var(_)) && self.ty_own_linear(&bare) {
            self.error(span, messages::iter_drive_in_place_maybe_linear_consumed(&bare));
        }
        self.out.for_drivers.insert(
            self.key(span),
            PassDriver { emitted_arm, arms, origin: false, in_place, mint: minted, step_call: false },
        );
        elem
    }

    /// [iter-step-call] The `next` a `for` drives, when it is a declared fn
    /// whose written result emits a borrow [iter-yield-proj].
    fn for_next_borrows(&self, iterable: &'p Expr) -> bool {
        let key = self.key(iterable.span()).synthetic(Key::FOR_NEXT);
        let Some(k) = self.out.call_fn.get(&key).copied() else { return false };
        if self.out.local_calls.contains(&key) || self.out.member_calls.contains_key(&key) {
            return false;
        }
        self.fn_decl_by_key(k)
            .and_then(|d| d.return_type.as_ref())
            .is_some_and(|t| !proj_arm_indices(t).is_empty())
    }

    fn check_lambda(
        &mut self,
        params: &'p [LambdaParam],
        body: &'p LambdaBody,
        span: Span,
        expected: Option<&Ty>,
    ) -> Ty {
        let (exp_params, exp_ret, exp_contract, exp_effects) =
            match expected.map(|t| t.strip_quals()) {
                Some(Ty::Fn {
                    params,
                    ret,
                    contract,
                    effects,
                }) => (
                    Some(params.clone()),
                    Some((**ret).clone()),
                    contract.clone(),
                    Some(effects.clone()),
                ),
                _ => (None, None, None, None),
            };
        // [fate-lambda] Everything below this frame boundary is a
        // capture; the body's reads/mutations of such variables are
        // recorded, and consuming one is an error (the lambda may run
        // any number of times).
        self.lambda_ctx.push(LambdaCtx {
            boundary: self.locals.len(),
            captures: Vec::new(),
        });
        self.locals.push(HashMap::new());
        let mut param_tys = Vec::new();
        for (i, p) in params.iter().enumerate() {
            let ty =
                p.ty.as_ref()
                    .map(|t| self.lower_type(t))
                    .or_else(|| exp_params.as_ref().and_then(|ps| ps.get(i).cloned()))
                    .unwrap_or(Ty::Unknown);
            self.declare(&p.name, ty.clone());
            // [fn-contract] A parameter the expected contract *keeps*
            // belongs to the closure's caller: never consumable inside
            // the body.
            let kept = exp_contract
                .as_ref()
                .and_then(|c| c.get(i))
                .is_some_and(|e| e.kept);
            if kept {
                if let Some(var) = self.lookup_mut(&p.name.name) {
                    var.lambda_kept = true;
                }
            }
            param_tys.push(ty);
        }
        // [fn-contract] Exported for the emitter's parameter-binding
        // modes.
        if let Some(c) = &exp_contract {
            self.out.lambda_contracts.insert(self.key(span), c.clone());
        }
        let saved_ret = std::mem::replace(&mut self.ret_ty, exp_ret.clone().unwrap_or(Ty::Unknown));
        // [fn-effects] The body performs the effects the fn *type* declares
        // — the call site supplies them, so nothing is captured. With no
        // expected type the set is *inferred* from the body, which is what
        // `effect_uses` collects; the enclosing environment stands in for
        // the duration so the calls resolve.
        let saved_effects = match &exp_effects {
            // Transitional (ROADMAP §2b): a fn value's effects arrive as its
            // effect parameters, which the emitters cannot mint a handle
            // from yet — marked inline so a capture is refused.
            Some(effects) => Some(std::mem::replace(
                &mut self.effect_env,
                effects
                    .iter()
                    .map(|ty| EffectAvail {
                        ty: ty.clone(),
                        declared: true,
                        any: false,
                    })
                    .collect(),
            )),
            None => None,
        };
        self.effect_uses.push(Vec::new());
        // A lambda body is a loop barrier: `break`/`continue` inside it
        // never bind a loop enclosing the lambda expression.
        let saved_loops = std::mem::take(&mut self.loop_stack);
        // [actor-spawn-expr] [actor-waitfor] [actor-replyto] …and a barrier
        // for the asynchronous capabilities, for the same reason: a lambda is
        // a *value*, so where its body runs is decided by whoever calls it,
        // and no first-pass form may cross a closure. A fn type cannot
        // declare `spawn` [actor-spawn-effect], `waitfor` needs `main`'s own
        // thread, and a `replyto` continuation belongs to the handler that
        // minted it — none of which travels with a function value.
        let saved_can_spawn = std::mem::replace(&mut self.can_spawn, false);
        let saved_own_handler = self.own_handler.take();
        let ret = match body {
            // [type-none-unit] `(v: Int) -> None` into a `(v: Int) -> Str?` slot
            // answers the slot's optional: typed as answering `None` alone,
            // Kotlin emitted a `Unit` function where a `String?` one was
            // expected (found building `args`, 2026-10-20).
            LambdaBody::Expr(e) => {
                let t = self.check_expr(e, exp_ret.as_ref());
                match &exp_ret {
                    Some(want) if t.is_none_ty() && !want.is_none_ty() && want.has_none_arm() => want.clone(),
                    _ => t,
                }
            }
            LambdaBody::Block(b) => {
                for stmt in &b.stmts {
                    self.check_stmt(stmt);
                }
                exp_ret.unwrap_or(Ty::Unknown)
            }
            // [expr-terminal-lambda] The parser fills a `...` body before checking.
            LambdaBody::Terminal => Ty::Unknown,
        };
        self.loop_stack = saved_loops;
        self.can_spawn = saved_can_spawn;
        self.own_handler = saved_own_handler;
        self.ret_ty = saved_ret;
        // [ir-analyze] A lambda parameter's linear-obligation leak check
        // moved to the IR analysis.
        self.locals.pop();
        let used = self.effect_uses.pop().unwrap_or_default();
        if let Some(saved) = saved_effects {
            self.effect_env = saved;
        }
        let ctx = self.lambda_ctx.pop().expect("lambda ctx pushed above");
        let consumes_captures = ctx.captures.iter().any(|c| c.moved);
        self.finish_lambda_captures(ctx, span);
        // [fn-effects] A declared set is the type's (even where the body
        // uses less of it — the emitted signature has to match what the
        // caller passes); otherwise the inferred set is the type's.
        let effects = exp_effects.unwrap_or(used);
        // What the emitters need: the effect values this lambda takes as
        // leading parameters, in order.
        self.out
            .lambda_effects
            .insert(self.key(span), effects.clone());
        let fn_ty = Ty::Fn {
            params: param_tys,
            ret: Box::new(ret),
            contract: None,
            effects,
        };
        // [fn-once] A lambda that consumes a capture is callable at most
        // once: its type gains `once`, so it only fits `once` fn
        // positions and calling it consumes it.
        if consumes_captures {
            fn_ty.qualify(vec![Qual {
                effect: false,
                name: "once".to_string(),
                args: Vec::new(),
            }])
        } else {
            fn_ty
        }
    }

    /// Applies the capture contract of a checked lambda body
    /// [fate-lambda]:
    /// - a *mutated* capture is consumed at creation — the closure took
    ///   ownership (each call mutates it, and the original observing
    ///   those mutations on one backend but not the other would break
    ///   parity); a written-kept parameter cannot be captured-and-
    ///   mutated (you cannot own what the caller keeps), and an
    ///   inferable parameter is claimed as moved;
    /// - the lambda *value* fate-links to its transitively-mutable
    ///   read captures: the variables stay readable, mutating one
    ///   poisons the closure, and moving the closure follows the
    ///   ordinary derived-value rules [fate-link] [fate-move-mode];
    /// - immutable captures are free (clone-vs-alias is unobservable —
    ///   backend-parity principle);
    /// - the capture list is exported for tooling and emitters
    ///   (`Checked::lambda_captures`).
    fn finish_lambda_captures(&mut self, ctx: LambdaCtx, span: Span) {
        let mut links: Vec<FateLink> = Vec::new();
        let mut exported: Vec<LambdaCapture> = Vec::new();
        for cap in &ctx.captures {
            exported.push(LambdaCapture {
                name: cap.name.clone(),
                consumed: cap.mutated || cap.moved,
                mutable: cap.mutable,
                mutated: cap.mutated,
            });
            if cap.mutated {
                // [linear-lambda] A mutated capture would move the
                // obligation into the closure: forbidden.
                let is_linear = self
                    .var_by_id(cap.var_id)
                    .is_some_and(|v| self.ty_own_linear(&v.declared));
                if is_linear {
                    self.error(span, messages::linear_lambda_captures_linear(&cap.name));
                    continue;
                }
                let is_kept_param = self.var_by_id(cap.var_id).is_some_and(|v| v.is_param)
                    && !self.param_owned(&cap.name);
                if is_kept_param {
                    // [deduce-default] A kept parameter — by default or by a
                    // written entry — cannot be captured-and-mutated: the
                    // caller keeps it, so the closure cannot own it. (Before
                    // 2026-10-11 an unwritten parameter was *claimed* as moved
                    // by the capture; there is no such inference now, so the
                    // move must be declared with `=> !p`, or the capture made
                    // over a `copy`.)
                    self.error(span, messages::fate_lambda_captures_kept(&cap.name));
                    continue;
                }
                // Consume the original: the closure owns the value now.
                continue;
            }
            // [fate-lambda-view] A read capture of non-Copy data makes the
            // closure a **view**: it holds a borrow of the captured
            // variable, exactly as a struct holds its `proj` fields
            // [proj-field] — the body can return projections rooted in a
            // capture (`i -> get(words, i)!`), which no fn type can name,
            // so the value itself carries the link. Binding the lambda
            // links it (held, borrowed); a call result linked to the
            // lambda reaches the captured roots transitively; moving or
            // mutating the capture poisons the closure. Two exclusions: a
            // *consumed* capture is owned — the closure swallowed the
            // value at creation (which is what made it `once`
            // [fn-once]), so there is no source left to borrow from — and
            // a Copy scalar capture is the value itself on both backends
            // [copy-scalar-free].
            if cap.moved {
                continue;
            }
            let copy_scalar = self
                .var_by_id(cap.var_id)
                .is_some_and(|v| crate::types::is_copy_scalar(&v.declared));
            if copy_scalar {
                continue;
            }
            if !links.iter().any(|l| l.root_id == cap.var_id) {
                links.push(FateLink {
                    held: true,
                    root_id: cap.var_id,
                    root_name: cap.name.clone(),
                    bind_span: span,
                    elem_idx: None,
                    // A capture is of the variable itself; the closure is a
                    // view, and mutation through it is refused anyway.
                    crosses: false,
                    // [fate-lambda] A capture is read through whatever
                    // the body does with it; the capture analysis
                    // records the variable, not a projection, so the
                    // link stays whole-variable.
                    path: Some(Vec::new()),
                    borrowed: true,
                });
            }
            if let Some(var) = self.var_by_id(cap.var_id) {
                for l in var.links.clone() {
                    if !links.iter().any(|e| e.root_id == l.root_id) {
                        links.push(FateLink {
                            held: true,
                            borrowed: true,
                            ..l
                        });
                    }
                }
            }
        }
        if !links.is_empty() {
            self.lambda_links.insert(span, links);
        }
        if !exported.is_empty() {
            self.out.lambda_captures.insert(self.key(span), exported);
        }
    }

    fn check_struct_lit(
        &mut self,
        ty: Option<&ast::Type>,
        fields: &'p [StructLitField],
        expected: Option<&Ty>,
        span: Span,
    ) -> Ty {
        // [type-canbe-mut] A literal's written type is validated like any
        // other: `Mut Cell { … }` for a struct without `canbe Mut` is refused
        // here, where it used to be accepted and only kotlinc noticed
        // (ROADMAP §0g, fixed 2026-10-05).
        // [mod-namespace] A leading-dot literal type (`.S { … }`) resolves its
        // namespace against the expected type first (D3/D4), so the rest of
        // the check sees the full `AttributeValue.S`.
        let ty_resolved: Option<ast::Type> = match ty {
            Some(ast::Type::Named { qualifiers, base }) if base.name.name.starts_with('.') => {
                match self.resolve_dot_ref(&base.name.name, expected) {
                    Ok((full, _)) => {
                        let mut b = base.clone();
                        b.name.name = full;
                        Some(ast::Type::Named { qualifiers: qualifiers.clone(), base: b })
                    }
                    Err(msg) => {
                        self.error(base.name.span, msg);
                        return Ty::Unknown;
                    }
                }
            }
            _ => None,
        };
        let ty: Option<&ast::Type> = ty_resolved.as_ref().or(ty);
        // [generic-arity] A struct literal's written type may omit its
        // arguments — they are inferred from the field values below
        // [struct-literal-arg] — so the arity check `lower_base_ref` runs
        // for every other type-position reference is suppressed for the
        // span of validating/lowering *this* written type.
        let saved_lit_ty = self.in_struct_lit_ty;
        self.in_struct_lit_ty = true;
        if let Some(t) = ty {
            self.validate_type(t);
        }
        let annotated = ty.map(|t| self.lower_type(t)).or_else(|| expected.cloned());
        self.in_struct_lit_ty = saved_lit_ty;
        // [struct-literal-arg] A written type name with too few arguments
        // (`Arg { ... }` for `Arg<T>`, writing none of `T`) carries an empty
        // `args` here — `lower_type`'s arity check was suppressed above, and
        // nothing pads a short list to the declared arity on its own. When
        // the call (or other outer context) already supplies a fully-argued
        // `expected` of the same base type, prefer its arguments over the
        // written type's short/empty ones: the field-value fallback below
        // only reads evidence from values actually written, so a field that
        // happens to not mention the missing generic (`short_name`, not
        // `default`) would otherwise leave `T` as `Unknown` even though the
        // call site already knows it — exactly the case
        // [call-generic-progressive] already threads into every other kind
        // of argument.
        let annotated = match (&annotated, expected) {
            (Some(Ty::Named { name: wn, args: wa }), Some(Ty::Named { name: en, args: ea }))
                if wn == en && wa.len() < ea.len() =>
            {
                Some(Ty::Named { name: wn.clone(), args: ea.clone() })
            }
            _ => annotated,
        };
        let Some(struct_ty) = annotated else {
            for f in fields {
                match &f.kind {
                    StructLitFieldKind::Named { value, .. } => {
                        self.check_expr(value, None);
                    }
                    StructLitFieldKind::Spread(e) => {
                        self.check_expr(e, None);
                    }
                    // [comptime-inline] Gone before this runs.
                    StructLitFieldKind::InlineFor { .. } => {}
                }
            }
            return Ty::Unknown;
        };
        let (decl, subst) = match struct_ty.strip_quals() {
            Ty::Named { name, args } => match self.symbols.structs.get(name.as_str()).copied() {
                Some(decl) => {
                    let mut subst = HashMap::new();
                    for (i, g) in decl.generics.iter().enumerate() {
                        subst.insert(g.name.clone(), args.get(i).cloned().unwrap_or(Ty::Unknown));
                    }
                    (Some(decl), subst)
                }
                None => (None, HashMap::new()),
            },
            _ => (None, HashMap::new()),
        };
        let Some(decl) = decl else {
            for f in fields {
                match &f.kind {
                    StructLitFieldKind::Named { value, .. } => {
                        self.check_expr(value, None);
                    }
                    StructLitFieldKind::Spread(e) => {
                        self.check_expr(e, None);
                    }
                    // [comptime-inline] Gone before this runs.
                    StructLitFieldKind::InlineFor { .. } => {}
                }
            }
            return struct_ty;
        };
        // [struct-opaque] Only the declaring module builds an opaque struct.
        if self.refuse_opaque(&struct_ty, "building one with a literal", span) {
            for f in fields {
                match &f.kind {
                    StructLitFieldKind::Named { value, .. } => {
                        self.check_expr(value, None);
                    }
                    StructLitFieldKind::Spread(e) => {
                        self.check_expr(e, None);
                    }
                    StructLitFieldKind::InlineFor { .. } => {}
                }
            }
            return struct_ty;
        }
        // [comptime-fields] A compile-time type is never constructed.
        if decl.comptime {
            self.error(span, messages::comptime_fields_literal(&decl.name.name));
        }
        // [linear-composite] A generic field type hides the store from the
        // struct's own declaration (`struct Box<T> { item: T }`), so the
        // literal is where it surfaces. A field whose *declared* type is
        // linear was already refused at the struct, so it is not reported
        // twice.
        // [struct-literal-arg] The type arguments no annotation and no
        // expectation determined: inferred from the field values below.
        // Each undetermined generic lowered as itself (a `Ty::Var`), so the
        // declared field type becomes a pattern `unify` can bind against.
        let pattern_subst: HashMap<String, Ty> = decl
            .generics
            .iter()
            .filter(|g| subst.get(&g.name).is_none_or(|t| t.is_unknown()))
            .map(|g| (g.name.clone(), Ty::Var(g.name.clone())))
            .collect();
        let mut inferred: HashMap<String, Ty> = HashMap::new();
        let mut has_spread = false;
        let mut provided: HashSet<&str> = HashSet::new();
        // [struct-field-canbe-mut] A `Mut` literal gives its `canbe Mut` fields `Mut`
        // values; a plain one, plain values.
        let lit_mut = struct_ty.quals().iter().any(|q| q.name == "Mut");
        let mut spreads: Vec<&'p Expr> = Vec::new();
        for f in fields {
            match &f.kind {
                StructLitFieldKind::Named { name, value } => {
                    match decl.fields.iter().find(|df| df.name.name == name.name) {
                        Some(df) if df.ty.is_none() => {
                            // [handler-state-infer] An inferred state field of a
                            // generated iterator struct: the minter's literal
                            // entry *is* the initializer whose type the field
                            // takes. Infer it (no expectation), and record it
                            // at the struct field's name [node-id] — the
                            // channel the `next` body's `__p.<field>` reads and
                            // the IR read back, the same one handler state uses.
                            let vty = self.check_expr(value, None);
                            self.out
                                .expr_ty
                                .insert(self.key(df.name.span), vty.clone());
                            provided.insert(name.name.as_str());
                            // Fall through to the move/fate handling the caller
                            // does; nothing to unify (an inferred field has no
                            // declared type pattern) and no `canbe`/linear
                            // generic surfaces (the field is concrete).
                        }
                        Some(df) => {
                            // [lsp-definition] A struct literal's field label
                            // points at its declaration, exactly like a
                            // dot-access field read — so a rename issued from
                            // the declaration (or from a dot-access use)
                            // reaches every literal that names this field too
                            // (defect reported 2026-10-20: renaming
                            // `Arg<T>.short_name` left `Arg { short_name:
                            // ... }` call sites unchanged).
                            self.record_field_ref(&struct_ty, name);
                            let fty = self.struct_field_ty(df, &subst, lit_mut);
                            self.check_expr(value, Some(&fty));
                            let vty = self.out.expr_ty[&self.key(value.span())].clone();
                            // [struct-literal-arg] What this field says about an
                            // **undetermined** type argument. `Box { value: 7 }`
                            // written bare has nothing to take `T` from — no
                            // annotation and, as a call argument, no expectation
                            // — so the field values are the only evidence there
                            // is. Collected here, where the declared field type
                            // and the value's type are both in hand, and applied
                            // after the loop so a later field can widen an
                            // earlier binding the way an argument list does.
                            if !pattern_subst.is_empty() {
                                let pattern =
                                    self.struct_field_ty(df, &pattern_subst, lit_mut);
                                unify(&pattern, &vty, &mut inferred);
                            }
                            // [linear-generics] A field whose declared type
                            // mentions an opted-in parameter (`canbe
                            // linear`) accepts the store: the container is
                            // conditionally linear and owes as a whole
                            // (user decision 2026-09-12).
                            let opted_field = decl.generic_canbe.iter().any(|(id, q)| {
                                q.name.name == "linear"
                                    && df.ty.as_ref().is_some_and(|t| type_mentions_generic(t, &id.name))
                            });
                            if self.ty_own_linear(&vty) && !self.ty_own_linear(&fty) && !opted_field
                            {
                                let linear = format!("{vty}");
                                self.refuse_linear_composite(
                                    value.span(),
                                    &linear,
                                    format!("stored in field `{}.{}`", decl.name.name, name.name),
                                );
                            }
                            if !is_subtype(&vty, &fty) {
                                self.error(
                                    value.span(),
                                    messages::struct_decl_field_mismatch(&name.name, &fty, &vty),
                                );
                            }
                            provided.insert(&name.name);
                        }
                        None => {
                            self.check_expr(value, None);
                            self.error(
                                name.span,
                                messages::struct_field_resolve_literal_no_field(
                                    &decl.name.name,
                                    &name.name,
                                ),
                            );
                        }
                    }
                }
                StructLitFieldKind::Spread(e) => {
                    has_spread = true;
                    self.check_expr(e, None);
                    spreads.push(e);
                }
                // [comptime-inline] Gone before this runs.
                StructLitFieldKind::InlineFor { .. } => {}
            }
        }
        // [struct-field-canbe-mut] A `Mut` literal must not take a `canbe Mut` field
        // from a plain value: the field would become mutable while whatever
        // shares it (a `copy` of a plain value is the value itself) still
        // reads it as immutable. A spread source must be `Mut` too, and a
        // default (checked once, at the plain type) does not apply.
        if lit_mut {
            for df in decl.fields.iter().filter(|df| df.canbe_mut) {
                if provided.contains(df.name.name.as_str()) {
                    continue;
                }
                for e in &spreads {
                    let sty = self.out.expr_ty.get(&self.key(e.span())).cloned().unwrap_or(Ty::Unknown);
                    if !sty.is_unknown() && !sty.quals().iter().any(|q| q.name == "Mut") {
                        self.error(
                            e.span(),
                            messages::struct_field_canbe_mut_plain_spread(
                                &decl.name.name,
                                &df.name.name,
                                &sty,
                            ),
                        );
                    }
                }
                if spreads.is_empty() && df.default.is_some() {
                    self.error(
                        span,
                        messages::struct_field_canbe_mut_default_not_mut(
                            &decl.name.name,
                            &df.name.name,
                        ),
                    );
                    provided.insert(&df.name.name);
                }
            }
        }
        if !has_spread {
            for df in &decl.fields {
                if df.default.is_none() && !provided.contains(df.name.name.as_str()) {
                    self.error(
                        span,
                        messages::struct_defaults_missing_field(&df.name.name, &decl.name.name),
                    );
                }
            }
        }
        // [struct-literal-arg] Rebuild the literal's type with what the fields
        // determined. Only the *undetermined* positions are filled, so a
        // written `Box<Int>` or an expectation still decides — the fields are
        // evidence of last resort, which is the same rank a collection
        // literal's elements have [col-literal-arg].
        if !inferred.is_empty() {
            if let Ty::Named { name, args } = struct_ty.strip_quals() {
                let filled: Vec<Ty> = decl
                    .generics
                    .iter()
                    .enumerate()
                    .map(|(i, g)| match args.get(i) {
                        Some(t) if !t.is_unknown() => t.clone(),
                        _ => inferred.get(&g.name).cloned().unwrap_or(Ty::Unknown),
                    })
                    .collect();
                if filled.iter().any(|t| !t.is_unknown()) {
                    let rebuilt = Ty::Named {
                        name: name.clone(),
                        args: filled,
                    };
                    let quals = match &struct_ty {
                        Ty::Qualified { quals, .. } => quals.clone(),
                        _ => Vec::new(),
                    };
                    return rebuilt.qualify(quals);
                }
            }
        }
        struct_ty
    }
}

impl<'p, 'r> Checker<'p, 'r> {
    // ================= conditions & narrowing =================

    /// Checks a condition expression and derives narrowing facts.
    /// [is-bind-once] Where a binding `is` may take a subject that is **not a
    /// place** (a call, above all): as the *whole* condition of a `while`, or
    /// of an `if`'s first branch. Those two are the shapes the emitters hoist
    /// into a single evaluation — one temporary, read by both the test and the
    /// binding.
    ///
    /// Everywhere else it is refused rather than emitted, because the honest
    /// alternatives are both bad: evaluating the subject twice is what this
    /// rule exists to stop (it silently dropped values — the defect closed
    /// 2026-09-16), and hoisting it out of a `&&` chain or an `else if` would
    /// evaluate it when short-circuiting says it should not run at all.
    fn reject_unhoistable_is(&mut self, cond: &'p Expr, hoistable: bool, what: &str) {
        // The whole condition being the hoistable shape is the legal case.
        if hoistable {
            if let Expr::Is {
                subject,
                binding: Some(_),
                ..
            } = cond
            {
                if !is_place_expr(subject) {
                    return;
                }
            }
        }
        let mut offenders: Vec<Span> = Vec::new();
        collect_binding_is(cond, &mut |subject, span| {
            if !is_place_expr(subject) {
                offenders.push(span);
            }
        });
        for span in offenders {
            self.error(span, messages::is_bind_once_not_hoistable(&what));
        }
    }

    /// [deduce-conditional] The narrows a Bool-returning call with a
    /// qualifier-conditional response (`fn non_empty(list) -> list is
    /// NonEmpty => list`) installs: for each response entry, the argument
    /// bound to the named parameter gains (`is`) or loses (`!is`) the
    /// qualifier on the branch the `true` result selects. Erased and trusted
    /// — the fn's body proved it [deduce-conditional].
    fn response_narrows(&mut self, cond: &'p Expr) -> CondInfo {
        let mut out = CondInfo::default();
        let Expr::Call { args, .. } = cond else {
            return out;
        };
        let Some(callee) = self.out.call_fn.get(&self.key(cond.span())).copied() else {
            return out;
        };
        // The callee's declaration: its FnEntry is in scope (the call
        // resolved through it). Search the current file's fn scope by key.
        let Some(f) = self
            .scope
            .fns
            .values()
            .flatten()
            .find(|e| e.key == callee)
            .map(|e| e.decl)
        else {
            return out;
        };
        let Some(responses) = f.response.clone() else {
            // [deduce-conditional] 6c: a refn may attach a Bool-conditional
            // response to this callee even when the fn declares none.
            return self.refn_response_narrows(cond, callee, args);
        };
        // Positional parameters (implicits take no argument slot).
        let fixed: Vec<&ast::Param> = f.params.iter().filter(|p| !p.implicit).collect();
        for r in &responses {
            let Some(idx) = fixed.iter().position(|p| p.name.name == r.subject.name) else {
                continue;
            };
            let Some(arg) = args.get(idx) else { continue };
            let Some(place) = Place::of_expr(arg) else { continue };
            // The argument's current narrowed type and its storage repr.
            let (narrowed_base, declared) = if place.is_root() {
                match self.lookup(&place.root) {
                    Some(v) => (v.narrowed.clone(), v.declared.clone()),
                    None => continue,
                }
            } else {
                let t = self.out.expr_ty.get(&self.key(arg.span())).cloned().unwrap_or(Ty::Unknown);
                (t.clone(), t)
            };
            let qual = self.lower_quals(std::slice::from_ref(&r.qual), &HashMap::new(), 0);
            let qual_set: HashSet<String> = qual.iter().map(|q| q.name.clone()).collect();
            // `is` adds the qualifier on the true branch; `!is` removes it
            // there. The opposite holds on the false branch.
            let with_qual = narrowed_base.clone().qualify(qual.clone());
            let without_qual = narrowed_base.clone().remove_quals(&qual_set);
            let (then_ty, else_ty) = if r.negated {
                (without_qual, with_qual)
            } else {
                (with_qual, without_qual)
            };
            out.then_narrows.push(Narrow {
                place: place.clone(),
                narrowed: then_ty,
                declared: declared.clone(),
            });
            out.else_narrows.push(Narrow {
                place,
                narrowed: else_ty,
                declared,
            });
        }
        out
    }

    /// [deduce-conditional] 6c: a refinement may attach a Bool-conditional
    /// response to a matched callee. At a call to such a callee, narrow the
    /// argument at each response's parameter position, exactly as a fn's own
    /// response clause does.
    fn refn_response_narrows(
        &mut self,
        cond: &'p Expr,
        callee: DeclId,
        args: &'p [Expr],
    ) -> CondInfo {
        let mut out = CondInfo::default();
        let responses = self.refinements.responses_for(self.file_idx, callee).to_vec();
        for (pos, negated, qual_name) in responses {
            let Some(arg) = args.get(pos) else { continue };
            let Some(place) = Place::of_expr(arg) else { continue };
            let (narrowed_base, declared) = if place.is_root() {
                match self.lookup(&place.root) {
                    Some(v) => (v.narrowed.clone(), v.declared.clone()),
                    None => continue,
                }
            } else {
                let t = self.out.expr_ty.get(&self.key(arg.span())).cloned().unwrap_or(Ty::Unknown);
                (t.clone(), t)
            };
            let qual = Qual { effect: false, name: qual_name.clone(), args: Vec::new() };
            let mut set = HashSet::new();
            set.insert(qual_name);
            let with_qual = narrowed_base.clone().qualify(vec![qual]);
            let without_qual = narrowed_base.clone().remove_quals(&set);
            let (then_ty, else_ty) = if negated {
                (without_qual, with_qual)
            } else {
                (with_qual, without_qual)
            };
            out.then_narrows.push(Narrow { place: place.clone(), narrowed: then_ty, declared: declared.clone() });
            out.else_narrows.push(Narrow { place, narrowed: else_ty, declared });
        }
        let _ = cond;
        out
    }

    fn analyze_cond(&mut self, cond: &'p Expr) -> CondInfo {
        match cond {
            // [qual-lift] The dual of `is`: same test, generalized type.
            Expr::Widen {
                subject,
                quals,
                binding,
                span,
            } => {
                let info = self.widen_info(subject, quals, binding.as_ref(), *span);
                self.out.expr_ty.insert(self.key(*span), Ty::named("Bool"));
                let mut out = CondInfo::default();
                if let Some(place) = &info.subject_place {
                    out.then_narrows.push(Narrow {
                        place: place.clone(),
                        narrowed: info.matched.clone(),
                        declared: info.subject_repr.clone(),
                    });
                    if let Some(rem) = &info.remaining {
                        out.else_narrows.push(Narrow {
                            place: place.clone(),
                            narrowed: rem.clone(),
                            declared: info.subject_repr.clone(),
                        });
                    }
                }
                // [qual-lift] `is ^Ok inner` declares `inner` in the branch,
                // exactly as an `is` binding does.
                if let Some(binding) = info.binding {
                    out.bindings.push(binding);
                }
                out
            }
            Expr::Is { .. } => {
                let info = self.is_info(cond);
                self.out
                    .expr_ty
                    .insert(self.key(cond.span()), Ty::named("Bool"));
                let mut out = CondInfo::default();
                if let Some(place) = &info.subject_place {
                    out.then_narrows.push(Narrow {
                        place: place.clone(),
                        narrowed: info.matched.clone(),
                        declared: info.subject_repr.clone(),
                    });
                    if let Some(rem) = &info.remaining {
                        out.else_narrows.push(Narrow {
                            place: place.clone(),
                            narrowed: rem.clone(),
                            declared: info.subject_repr.clone(),
                        });
                    }
                }
                if let Some(binding) = info.binding {
                    out.bindings.push(binding);
                }
                out
            }
            Expr::Binary {
                op: BinaryOp::And,
                lhs,
                rhs,
                ..
            } => {
                let l = self.analyze_cond(lhs);
                let r = self.with_narrows(&l.then_narrows.clone(), |c| {
                    c.locals.push(HashMap::new());
                    for (ident, ty, links, _) in &l.bindings {
                        c.declare_with_links(ident, ty.clone(), links.clone());
                    }
                    let r = c.analyze_cond(rhs);
                    c.locals.pop();
                    r
                });
                let mut out = CondInfo::default();
                out.then_narrows.extend(l.then_narrows);
                out.then_narrows.extend(r.then_narrows);
                out.bindings.extend(l.bindings);
                out.bindings.extend(r.bindings);
                out
            }
            Expr::Binary {
                op: BinaryOp::Or,
                lhs,
                rhs,
                ..
            } => {
                let l = self.analyze_cond(lhs);
                let r = self.with_narrows(&l.else_narrows.clone(), |c| c.analyze_cond(rhs));
                let mut out = CondInfo::default();
                // [is-union] When either side holds, a place both sides narrow
                // is one of the two: `s is "json" || s is "text"` (and its
                // spelling `s is "json" | "text"`) narrows `s` to `"json" |
                // "text"`, `x is Int || x is Str` to `Int | Str`. A place only
                // one side narrows is not narrowed [flow-or-not].
                for ln in &l.then_narrows {
                    if let Some(rn) = r.then_narrows.iter().find(|rn| rn.place == ln.place) {
                        let joined = self.mk_union(vec![ln.narrowed.clone(), rn.narrowed.clone()]);
                        out.then_narrows.push(Narrow {
                            place: ln.place.clone(),
                            narrowed: joined,
                            declared: ln.declared.clone(),
                        });
                    }
                }
                out.else_narrows.extend(l.else_narrows);
                out.else_narrows.extend(r.else_narrows);
                out
            }
            Expr::Unary {
                op: UnaryOp::Not,
                operand,
                ..
            } => {
                let inner = self.analyze_cond(operand);
                CondInfo {
                    then_narrows: inner.else_narrows,
                    else_narrows: inner.then_narrows,
                    bindings: Vec::new(),
                }
            }
            other => {
                let ty = self.check_expr(other, None);
                self.require_bool(&ty, other.span());
                // [deduce-conditional] A call to a fn with a qualifier-
                // conditional response narrows its argument like a literal
                // `is` test: `if non_empty(xs)` installs `NonEmpty` on `xs` in
                // the then-branch (and the `!is` form in whichever branch it
                // holds). Only the matching branch learns the fact.
                self.response_narrows(other)
            }
        }
    }

    /// [expr-cond-bool] A condition is a boolean expression. `if`, `elif`,
    /// `while` and a subject-less `when`'s branch heads take `Bool` and
    /// nothing else — Salvo has no truthiness, so there is no rule that
    /// could turn another type into a decision. Checked per *leaf* of a
    /// `&&`/`||`/`!` condition, which is where the wrong type was written.
    /// A type the checker could not infer stays lenient
    /// [type-unknown-lenient], and a diverging expression never produces a
    /// value to test [type-any-never].
    fn require_bool(&mut self, ty: &Ty, span: Span) {
        if ty.is_unknown() || matches!(ty, Ty::Never) || ty.is_bool() {
            return;
        }
        self.error(span, messages::expr_cond_bool_not_bool(&ty));
    }

    /// [is-qualifies] [qual-depend] Validates a predicate-qualifier check —
    /// applicability, the filled value slots (places resolved to fate roots,
    /// constants taken whole), the `qualifies` effects — records the runtime
    /// lowering in `predicate_tests` at `span`, and answers the lowered
    /// value arguments per qualifier for the then-narrow. Used by `is`
    /// predicate checks.
    fn check_predicate_quals(
        &mut self,
        pat: &CheckPat,
        resolved: &[Option<&'p QualifierDecl>],
        subj_ty: &Ty,
        span: Span,
    ) -> HashMap<String, Vec<Ty>> {
        let mut dependent_args: HashMap<String, Vec<Ty>> = HashMap::new();
        for (q, decl) in pat.quals.iter().zip(resolved) {
            let Some(decl) = *decl else { continue };
            if !self.qual_applies(decl, subj_ty.strip_quals()) {
                self.error(span, messages::is_qualifies_does_not_apply(&q, &subj_ty));
            }
        }
        // [qual-depend] A dependent qualifier's value slots are filled
        // with places: validate arity, resolve each place in scope,
        // check its type against the slot's, and record the fate roots
        // the claim will bind to.
        let mut checks: Vec<PredicateCheck> = Vec::new();
        for ((q, decl), args) in pat.quals.iter().zip(resolved).zip(&pat.qual_args) {
            // The declaration's own slots, not copies: a slot's type is
            // lowered and its names resolved as the declaring file's
            // (`Resolution::names` [name-table]), and recorded at its own node.
            let slots: &'p [ast::ValueSlot] = decl.map(|d| d.value_slots.as_slice()).unwrap_or(&[]);
            if slots.is_empty() && !args.is_empty() {
                self.error(args[0].1, messages::qual_depend_no_value_args(&q));
                checks.push(PredicateCheck { name: q.clone(), args: Vec::new(), implicits_at: None });
                continue;
            }
            if slots.len() != args.len() {
                let filled: Vec<String> =
                    slots.iter().map(|s| s.name.name.clone()).collect();
                self.error(
                    span,
                    messages::qual_depend_unfilled(&q, &slots.len(), &filled.join(", ")),
                );
                checks.push(PredicateCheck { name: q.clone(), args: Vec::new(), implicits_at: None });
                continue;
            }
            let mut rendered = Vec::new();
            let mut roots: Vec<u32> = Vec::new();
            // [col-idx] What the slots bind the qualifier's own type
            // parameters to (`C` ↦ `List<Int>`), for the `qualifies` call's
            // implicits.
            let qual_generics: Vec<Ident> = decl.map(|d| d.generics.clone()).unwrap_or_default();
            let mut slot_subst: HashMap<String, Ty> = HashMap::new();
            for (slot, (path, pspan)) in slots.iter().zip(args) {
                // [qual-const] A constant fills its slot whole: nothing
                // to resolve, nothing to invalidate — but it must be of the
                // slot's type (`Short('p')` into a `Char`).
                if let Some(c) = crate::types::Const::parse(path) {
                    let saved = self.enter_generics(&qual_generics);
                    let want = self.lower_type(&slot.ty);
                    self.generics = saved;
                    if !matches!(want.strip_quals(), Ty::Named { name, args } if args.is_empty() && name == c.base()) && !want.is_unknown() {
                        self.error(
                            *pspan,
                            messages::qual_const_slot_mismatch(
                                &c,
                                &slot.name.name,
                                &q,
                                &want,
                                &c.base(),
                            ),
                        );
                    }
                    rendered.push(PredicateArg {
                        path: path.clone(),
                        copy: true,
                    });
                    continue;
                }
                let Some((place_ty, place_roots)) = self.place_ty_and_roots(path) else {
                    self.error(*pspan, messages::qual_depend_not_a_value(&path));
                    continue;
                };
                // [ref-notsame] A `NotSame` claim is about the handle itself,
                // not the container it shares fate with: it binds the
                // handle's own identity.
                let place_roots = if q == "NotSame" {
                    let base = path.split('.').next().unwrap_or(path);
                    self.lookup(base).map(|v| vec![v.id]).unwrap_or(place_roots)
                } else {
                    place_roots
                };
                // The slot's type is written over the qualifier's own type
                // parameters, so it is lowered under them.
                let saved = self.enter_generics(&qual_generics);
                let want = self.lower_type(&slot.ty);
                self.generics = saved;
                unify(&want, place_ty.strip_quals(), &mut slot_subst);
                // Loose by design: the slot's type mentions the
                // qualifier's own generics (`Map<K, V>`), which have no
                // binding here — the base name is the honest check, and
                // the `qualifies` signature validation already tied the
                // slot to the predicate's parameter.
                let fits = match (&place_ty.strip_quals(), &want.strip_quals()) {
                    (Ty::Named { name: a, .. }, Ty::Named { name: b, .. }) => a == b,
                    (_, Ty::Var(_)) | (_, Ty::Unknown) | (Ty::Unknown, _) => true,
                    _ => false,
                };
                if !fits {
                    self.error(
                        *pspan,
                        messages::qual_depend_slot_mismatch(
                            &path,
                            &slot.name.name,
                            &q,
                            &want,
                            &place_ty,
                        ),
                    );
                }
                roots.extend(place_roots);
                rendered.push(PredicateArg {
                    path: path.clone(),
                    copy: crate::types::moves_for_free(&place_ty),
                });
            }
            roots.sort_unstable();
            roots.dedup();
            if !args.is_empty() {
                dependent_args.insert(
                    q.clone(),
                    args.iter()
                        .map(|(path, _)| match crate::types::Const::parse(path) {
                            // [qual-const] Constants are complete facts.
                            Some(c) => Ty::Const(c),
                            None => Ty::ValueRef {
                                path: path.clone(),
                                roots: roots.clone(),
                            },
                        })
                        .collect::<Vec<Ty>>(),
                );
            }
            // [col-idx] The `qualifies` call is made here, so its implicits are
            // filled here, at the types the slots bound: `Idx(xs)`'s `?size`
            // is the `size` of whatever `xs` is.
            let mut implicits_at = None;
            if let Some(qf) = decl.and_then(|d| d.fns.iter().find(|f| f.name.name == "qualifies")) {
                let saved = self.enter_generics(&qual_generics);
                let inner = self.enter_generics(&qf.generics);
                let implicits = self.collect_implicits(qf);
                self.generics = inner;
                self.generics = saved;
                if !implicits.is_empty() {
                    let base = args.first().map(|(_, s)| *s).unwrap_or(span);
                    let at = Key { span: base.at(base.start, base.start), ..self.key(base).synthetic(checks.len() as u32) };
                    let generics: HashSet<String> = qual_generics
                        .iter()
                        .chain(&qf.generics)
                        .map(|g| g.name.clone())
                        .collect();
                    self.fill_implicits_keyed(&implicits, "qualifies", &mut slot_subst, &generics, &[], base.at(base.start, base.start), at);
                    implicits_at = Some(at);
                }
            }
            checks.push(PredicateCheck { name: q.clone(), args: rendered, implicits_at });
        }
        self.out.predicate_tests.insert(self.key(span), checks);
        // The `qualifies` call happens here at runtime: its declared
        // effects must be available in this scope
        // [is-qualifies-effects].
        for (q, decl) in pat.quals.iter().zip(resolved) {
            let Some(decl) = *decl else { continue };
            let Some(qf) = decl.fns.iter().find(|f| f.name.name == "qualifies") else {
                continue;
            };
            for eff in qf.effects.iter().flatten() {
                let (EffectRef::Effect(r) | EffectRef::AnyEffect(r)) = eff else { continue };
                let ename = r.name.name.as_str();
                let available = self
                    .effect_env
                    .iter()
                    .any(|c| matches!(&c.ty, Ty::Named { name, .. } if name == ename));
                if !available {
                    self.error(span, messages::is_qualifies_effects_no_handler(&q, &ename));
                }
            }
        }
        dependent_args
    }

    /// Analyzes an `is` expression: checks the subject, records the runtime
    /// lowering (`is_tests`), and computes matched/remaining types.
    fn is_info(&mut self, is_expr: &'p Expr) -> IsInfo {
        let Expr::Is {
            subject,
            check,
            binding,
            span,
        } = is_expr
        else {
            unreachable!("is_info called on non-is expression")
        };
        let subj_ty = self.check_expr(subject, None);
        let repr = self.repr_of(subject, &subj_ty);
        let pat = self.parse_check(check, Some(&subj_ty));

        // A qualifier check on a non-union subject is a predicate test
        // [is-qualifies]: it calls each qualifier's `qualifies` function at
        // runtime.
        // [qual-overload] Resolve each named qualifier against *this* subject
        // once, up front: with several declarations of one name it is the
        // subject that says which is being tested, and every question below
        // (does it have a body, does it apply, what effects does its
        // `qualifies` declare) is about that one.
        let resolved: Vec<Option<&'p QualifierDecl>> = pat
            .quals
            .iter()
            .map(|q| {
                let subj = subj_ty.clone();
                self.qualifier_for(q.as_str(), Some(&subj))
            })
            .collect();
        let is_predicate = !pat.is_none
            && !pat.quals.is_empty()
            && !matches!(subj_ty, Ty::Union(_))
            && !subj_ty.is_unknown()
            && resolved.iter().all(|d| d.is_some_and(|d| d.has_body));
        // [qual-depend] The lowered value arguments per dependent qualifier,
        // for the then-narrow: `k is KeyOf(m)` narrows `k` to a `KeyOf` whose
        // argument is `m` bound to its fate roots.
        let mut dependent_args: HashMap<String, Vec<Ty>> = HashMap::new();
        if is_predicate {
            if let Some(base) = &pat.base {
                if !is_subtype(subj_ty.strip_quals(), base) {
                    self.error(*span, messages::is_qualifies_never_succeeds());
                }
            }
            dependent_args = self.check_predicate_quals(&pat, &resolved, &subj_ty, *span);
        } else if let Some(test) = self.union_test_for(strip_proj_union(&repr), &pat) {
            // Runtime lowering against the declared union representation
            // [is-narrowing] [is-precise].
            self.out.is_tests.insert(self.key(*span), test);
        } else if let (Some(Ty::Lit(lit)), true, Ty::Named { name, args }) =
            (&pat.base, pat.quals.is_empty(), repr.strip_quals())
        {
            // [is-union] [type-literal] `s is "json"` on a plain `Str` tests
            // the value: a one-arm "union" with no wrapper and a value
            // condition. Before 2026-10-20 nothing was recorded here, and the
            // IR read a missing test as decided statically — `true` — so the
            // test passed for every string.
            if args.is_empty() && name == lit.base() {
                self.out.is_tests.insert(
                    self.key(*span),
                    UnionTest { size: 1, arms: vec![0], nullable: false, match_none: false, values: vec![(0, false, vec![lit.clone()])] },
                );
            } else {
                self.error(*span, messages::type_literal_never_matches(&repr, &lit));
            }
        } else if !pat.quals.is_empty() && !matches!(subj_ty, Ty::Union(_)) && !pat.unresolved {
            // [qual-constructive] no runtime test exists for constructive
            // qualifiers on non-union values.
            let constructive = pat
                .quals
                .iter()
                .zip(&resolved)
                .find(|(_, d)| d.is_some_and(|d| !d.has_body))
                .map(|(q, _)| q);
            match constructive {
                Some(q) => self.error(*span, messages::qual_constructive_is_test(&q)),
                None => self.error(*span, messages::is_qualifies_unknown_qualifier()),
            }
        }

        // Narrowing math on the logical (possibly already narrowed) type.
        let (matched, remaining) = match &subj_ty {
            // An unresolved check name was already reported: keep the
            // subject's type and narrow nothing, so nothing cascades
            // [name-resolve].
            _ if pat.unresolved => (subj_ty.clone(), None),
            // [is-union] [type-literal] `s is "json"` on a `Str?` (or any
            // union with the literal's base arm): the `Str` arm holding that
            // value. It matched no arm (a `Str` is not a `"json"`), so the
            // test was refused as one that can never succeed, though the
            // runtime test was recorded. The matched side is the literal;
            // the other side keeps every arm, `Str` included, since other
            // strings remain.
            Ty::Union(arms) if Self::literal_on_base_arm(arms, &pat) => {
                let Some(Ty::Lit(lit)) = &pat.base else { unreachable!() };
                (Ty::Lit(lit.clone()), Some(subj_ty.clone()))
            }
            Ty::Union(arms) => {
                let (m, r): (Vec<Ty>, Vec<Ty>) = arms
                    .iter()
                    .cloned()
                    .partition(|arm| self.arm_matches(arm, &pat));
                if m.is_empty() {
                    self.error(*span, messages::is_union_no_arm_matches());
                }
                (self.mk_union(m), Some(self.mk_union(r)))
            }
            // [is-narrowing] A union read through a qualifier that is about
            // where the value lives, not what it holds — a `proj(list)`
            // element of a `List<P?>` — narrows like the union, each side
            // keeping the qualifier: the matched arm is still a view.
            Ty::Qualified { quals, base } if matches!(base.as_ref(), Ty::Union(_)) && quals.iter().all(|q| crate::types::is_proj_name(&q.name)) => {
                let Ty::Union(arms) = base.as_ref() else { unreachable!() };
                let (m, r): (Vec<Ty>, Vec<Ty>) = arms
                    .iter()
                    .cloned()
                    .partition(|arm| self.arm_matches(arm, &pat));
                if m.is_empty() {
                    self.error(*span, messages::is_union_no_arm_matches());
                }
                let m = self.mk_union(m).qualify(quals.clone());
                let r = self.mk_union(r).qualify(quals.clone());
                (m, Some(r))
            }
            other => {
                if is_predicate {
                    // A successful predicate check adds the qualifiers; a
                    // failed one proves nothing about the type.
                    let quals: Vec<Qual> = pat
                        .quals
                        .iter()
                        .map(|n| Qual {
                            effect: false,
                            name: n.clone(),
                            args: dependent_args.get(n).cloned().unwrap_or_default(),
                        })
                        .collect();
                    (other.clone().qualify(quals), None)
                } else if let (Some(Ty::Lit(lit)), true) = (&pat.base, pat.quals.is_empty()) {
                    // [is-union] [type-literal] `s is "json"` on a plain `Str`
                    // proves `s` is that literal: the test compares the value,
                    // and the narrowed type is one the runtime already holds
                    // (a literal is its base at run time).
                    match other.strip_quals() {
                        Ty::Named { name, args } if args.is_empty() && name == lit.base() => (Ty::Lit(lit.clone()), None),
                        _ => (other.clone(), None),
                    }
                } else {
                    (other.clone(), None)
                }
            }
        };

        let subject_place = Place::of_expr(subject).filter(|p| {
            // Only field chains out of a tracked local narrow [flow-place]
            // (user decision P1a): an element step cannot be told from a
            // sibling, and a place whose root is not a local has no flow
            // state to hang the fact on.
            p.narrowable() && self.lookup(&p.root).is_some()
        });
        let binding = binding.as_ref().map(|b| {
            let bty = if matches!(matched, Ty::Union(_)) {
                self.error(b.span, messages::is_binding_several_types());
                matched.clone()
            } else {
                matched.clone()
            };
            self.out.expr_ty.insert(self.key(b.span), bty.clone());
            // [linear-container] A binding whose payload is **linear** takes
            // the obligation *out* of the subject: `remove_at(pending, i) is
            // Reply<Fired> token` is the take-by-move surface's own idiom.
            // Recorded so the emitters move rather than copy — Rust's
            // narrowed-read path clones through a borrow, which duplicates an
            // obligation and does not even compile for a reply token (a
            // `SalvoReply` is not `Clone`), and this is the *binding* site, so
            // `note_linear_move`'s use-site path never sees it.
            if self.ty_own_linear(&bty) {
                self.out.linear_moves.insert(self.key(b.span));
            }
            // The binding aliases the subject: they share fate
            // [fate-link].
            let links = self.links_for_value(subject, b.span);
            (b.clone(), bty, links, None)
        });

        IsInfo {
            subject_place,
            subject_repr: repr,
            matched,
            remaining,
            binding,
        }
    }

    /// Splits an `is` check into qualifier names and an optional base type.
    /// Names that resolve to nothing are reported here [name-resolve] and
    /// mark the pattern `unresolved`, which suppresses the match-arm
    /// diagnostics downstream (an unresolved name matches nothing, and
    /// "this check can never succeed" would only mislead).
    fn parse_check(&mut self, check: &[TypeRef], expected: Option<&Ty>) -> CheckPat {
        if check.len() == 1 && check[0].name.name == "None" && check[0].args.is_empty() {
            return CheckPat {
                quals: Vec::new(),
                qual_args: Vec::new(),
                base: None,
                is_none: true,
                unresolved: false,
            };
        }
        let mut quals = Vec::new();
        let mut qual_args = Vec::new();
        let mut base = None;
        let mut unresolved = false;
        for (i, r) in check.iter().enumerate() {
            let last = i + 1 == check.len();
            // [mod-namespace] A leading-dot sugar name (`.S`) resolves against the
            // expected type here; on failure, report and mark unresolved so
            // nothing cascades. A union arm resolves to the arm's own type,
            // used as the check base directly — so it matches the arm whatever
            // the member's type is spelled (or aliased) as locally.
            if r.name.name.starts_with('.') {
                match self.resolve_dot_ref(&r.name.name, expected) {
                    Ok((full, arm_ty)) => {
                        self.record_def_ref(r.name.span, &full);
                        match arm_ty {
                            Some(ty) => base = Some(ty),
                            None => {
                                let mut c = r.clone();
                                c.name.name = full.clone();
                                let empty = HashMap::new();
                                base = Some(self.lower_base_ref(&c, &empty, 0));
                            }
                        }
                    }
                    Err(msg) => {
                        self.error(r.name.span, msg);
                        unresolved = true;
                    }
                }
                continue;
            }
            let name = r.name.name.as_str();
            // [type-literal] `is "A"`: the check's one ref is the literal.
            if let Some(lit) = salvo_syntax::ast::TypeLit::from_ref_name(name) {
                base = Some(Ty::Lit(lit));
                continue;
            }
            // [name-table] What the name means where the check is written.
            let meaning = self.named(r);
            let generic = self.names_generic(r);
            let is_qual = names_qualifier(name, &meaning) || generic;
            let is_type = names_type(name, &meaning) || generic;
            // Every position but the last is a qualifier; the last is a
            // qualifier when it names one, else the checked base type.
            if !last || names_qualifier(name, &meaning) {
                if !is_qual {
                    self.require_name(r, true);
                    unresolved = true;
                }
                // [lsp-definition] The qualifier name in an `is` check points
                // at its declaration, so hovering `Positive` in
                // `i is Positive` reaches the qualifier rather than falling
                // through to the enclosing expression's `Bool`.
                self.record_written_def(r);
                quals.push(r.name.name.clone());
                // [qual-depend] The filled block: `k is KeyOf(m)` — the
                // places arrive as value arguments on the check's ref.
                qual_args.push(
                    r.value_args
                        .iter()
                        .filter_map(|a| match a {
                            ast::Type::Named { qualifiers, base }
                                if qualifiers.is_empty() && !base.binder =>
                            {
                                Some((base.name.name.clone(), base.span))
                            }
                            other => {
                                self.error(other.span(), messages::qual_depend_arg_not_place());
                                None
                            }
                        })
                        .collect(),
                );
            } else if is_type {
                // The same for a *type* check (`x is Str`).
                self.record_written_def(r);
                let empty = HashMap::new();
                base = Some(self.lower_base_ref(r, &empty, 0));
            } else {
                // Both namespaces are admissible here, so neither wording
                // fits on its own.
                let name = name.to_string();
                self.error_unresolved(
                    r.span,
                    messages::name_resolve_unknown_type_or_qualifier(&name),
                    &name,
                );
                unresolved = true;
            }
        }
        CheckPat {
            quals,
            qual_args,
            base,
            is_none: false,
            unresolved,
        }
    }

    /// [type-literal] Whether `pat` is a bare literal that no arm of `arms`
    /// is, but one arm is the literal's base: `"json"` against `Str | None`.
    fn literal_on_base_arm(arms: &[Ty], pat: &CheckPat) -> bool {
        let (Some(Ty::Lit(lit)), true, false) = (&pat.base, pat.quals.is_empty(), pat.is_none) else { return false };
        let is_lit = |a: &Ty| matches!(a.strip_quals(), Ty::Lit(l) if l == lit);
        let is_base = |a: &Ty| matches!(a.strip_quals(), Ty::Named { name, args } if args.is_empty() && name == lit.base());
        !arms.iter().any(is_lit) && arms.iter().any(is_base)
    }

    /// Whether a union arm matches an `is` check pattern.
    fn arm_matches(&self, arm: &Ty, pat: &CheckPat) -> bool {
        if pat.is_none {
            return arm.is_none_ty();
        }
        if arm.is_none_ty() {
            return false;
        }
        if let Some(base) = &pat.base {
            if !is_subtype(arm.strip_quals(), base) {
                return false;
            }
        }
        let arm_quals: Vec<&str> = arm.quals().iter().map(|q| q.name.as_str()).collect();
        pat.quals.iter().all(|q| arm_quals.contains(&q.as_str()))
    }

    /// The runtime lowering of a check against a union representation.
    fn union_test_for(&mut self, repr: &Ty, pat: &CheckPat) -> Option<UnionTest> {
        let Ty::Union(_) = repr else { return None };
        if crate::literal::mentions_lit(repr) {
            return self.literal_union_test(repr, pat);
        }
        let value_arms = repr.value_arms();
        let size = value_arms.len();
        let nullable = repr.has_none_arm();
        if pat.is_none {
            return Some(UnionTest {
                size,
                arms: Vec::new(),
                nullable,
                match_none: true,
                values: Vec::new(),
            });
        }
        // [type-literal] [is-union] `v is "json"` on a `Str?` (or any union
        // with a `Str` arm) is that arm holding that value. It found no arm
        // before (a literal is not a `Str`), and the empty test was emitted as
        // `if (())` on Kotlin and `matches!(v, )` on Rust.
        if let (Some(Ty::Lit(lit)), true) = (&pat.base, pat.quals.is_empty()) {
            let at = value_arms.iter().position(|a| matches!(a.strip_quals(), Ty::Named { name, args } if args.is_empty() && name == lit.base()));
            if let Some(i) = at {
                return Some(UnionTest { size, arms: vec![i], nullable, match_none: false, values: vec![(i, false, vec![lit.clone()])] });
            }
        }
        let arms: Vec<usize> = value_arms
            .iter()
            .enumerate()
            .filter(|(_, arm)| self.arm_matches(arm, pat))
            .map(|(i, _)| i)
            .collect();
        Some(UnionTest {
            size,
            arms,
            nullable,
            match_none: false,
            values: Vec::new(),
        })
    }

    /// [type-literal] [type-union-arm-identity] An `is` test against a union with
    /// literals, lowered onto the *runtime* union: the matched declared arms
    /// become runtime arms, and a runtime arm only partly matched gets a
    /// value condition — `is "A"` on `"A" | "B" | Other Str` is "the value is
    /// `"A"`", `is Other` is "the value is none of the listed literals".
    fn literal_union_test(&mut self, repr: &Ty, pat: &CheckPat) -> Option<UnionTest> {
        let declared = repr.value_arms();
        let size = crate::literal::runtime_size(repr);
        let nullable = repr.has_none_arm();
        if pat.is_none {
            return Some(UnionTest { size, arms: Vec::new(), nullable, match_none: true, values: Vec::new() });
        }
        let runtime_of = |i: usize| crate::literal::runtime_arm(repr, i).unwrap_or(0);
        let matched: Vec<usize> =
            (0..declared.len()).filter(|i| self.arm_matches(declared[*i], pat)).collect();
        let mut arms: Vec<usize> = Vec::new();
        let mut values = Vec::new();
        for i in &matched {
            let r = runtime_of(*i);
            if arms.contains(&r) {
                continue;
            }
            arms.push(r);
            let on_arm: Vec<usize> = (0..declared.len()).filter(|j| runtime_of(*j) == r).collect();
            if on_arm.iter().all(|j| matched.contains(j)) {
                continue;
            }
            // [type-literal-qualified] A qualified literal is its literal: `is
            // Short` on `Short "port" | Short "verbose" | "host"` is the value
            // being `"port"` or `"verbose"`.
            let lit = |j: &usize| crate::literal::arm_lit(declared[*j]).cloned();
            let hit: Vec<usize> = on_arm.iter().copied().filter(|j| matched.contains(j)).collect();
            if hit.iter().all(|j| lit(j).is_some()) {
                values.push((r, false, hit.iter().filter_map(lit).collect()));
            } else {
                let missed: Vec<_> = on_arm.iter().filter(|j| !matched.contains(j)).filter_map(lit).collect();
                values.push((r, true, missed));
            }
        }
        Some(UnionTest { size, arms, nullable, match_none: false, values })
    }

    // ================= if / when =================

    fn check_if(
        &mut self,
        branches: &'p [(Expr, Block)],
        else_block: Option<&'p Block>,
    ) -> Ty {
        let mut acc_else: Vec<Narrow> = Vec::new();
        let mut branch_tys = Vec::new();
        let mut tails: Vec<Option<TailInfo>> = Vec::new();
        // Branch-aware consumption merging [deduce-consume]: each branch
        // body's narrowing effects (moves, qualifier removal) are isolated
        // and merged at the join — a branch that always exits never
        // contributes to the state after the `if`.
        let mut fallthrough: Vec<NarrowSnapshot> = Vec::new();
        for (i, (cond, block)) in branches.iter().enumerate() {
            // [is-bind-once] Only the first branch's condition can be hoisted
            // into a single evaluation; a later one would need the temporary
            // declared where Rust has no statement position for it.
            self.reject_unhoistable_is(
                cond,
                i == 0,
                if i == 0 { "inside a larger condition" } else { "an `elif` condition" },
            );
            let info = self.with_narrows(&acc_else.clone(), |c| c.analyze_cond(cond));
            let entry = self.snapshot_narrows();
            let mut narrows = acc_else.clone();
            narrows.extend(info.then_narrows.iter().cloned());
            let (ty, tail) = self.with_narrows(&narrows, |c| {
                c.tail_hint = c.value_expected.clone();
                c.check_branch_block(block, info.bindings.clone())
            });
            if !self.block_exits(block) {
                fallthrough.push(self.snapshot_narrows());
            }
            self.restore_narrows(&entry);
            branch_tys.push(ty);
            tails.push(tail);
            acc_else.extend(info.else_narrows);
        }
        match else_block {
            Some(block) => {
                let entry = self.snapshot_narrows();
                let (ty, tail) = self.with_narrows(&acc_else.clone(), |c| {
                    c.tail_hint = c.value_expected.clone();
                    c.check_branch_block(block, Vec::new())
                });
                if !self.block_exits(block) {
                    fallthrough.push(self.snapshot_narrows());
                }
                self.restore_narrows(&entry);
                branch_tys.push(ty);
                tails.push(tail);
            }
            None => {
                // No `else`: the no-branch-taken path falls through with
                // the current state. (What its else-narrows settle of a
                // linear union [linear-union-arm] is the IR ledger's.)
                fallthrough.push(self.snapshot_narrows());
                branch_tys.push(Ty::none());
                tails.push(None);
            }
        }
        self.merge_fallthrough(&fallthrough);
        // [is-narrow-guard] The guard idiom: every branch leaves the block
        // (`if e is None { return … }`), so whatever follows the `if` is on
        // the else-path and every condition's else-narrows hold there.
        // Installed *before* the assignment resets below, so a branch that
        // reassigned the subject still wins [is-narrow-assign-reset].
        if !branches.is_empty() && branches.iter().all(|(_, b)| self.block_exits(b)) {
            let facts = acc_else.clone();
            self.install_narrows(&facts);
        }
        let join = self.mk_union(branch_tys);
        for tail in tails.into_iter().flatten() {
            self.maybe_coerce(tail.span, &tail.logical, &tail.repr, &join);
        }
        for (_, block) in branches {
            // [is-narrow-guard] [is-narrow-assign-reset] A branch that exits
            // cannot be the path taken to the code below, so its
            // assignments do not reset anything there — the same reason
            // `merge_fallthrough` ignores it.
            if self.block_exits(block) {
                continue;
            }
            self.reset_assigned(block);
        }
        if let Some(block) = else_block {
            if !self.block_exits(block) {
                self.reset_assigned(block);
            }
        }
        join
    }

    /// Checks a `when` expression: union-typed variable subject
    /// [when-union-subject], sequential arm consumption and exhaustiveness
    /// [when-exhaustive], branch values unioning into the result
    /// [when-value].
    fn check_when(
        &mut self,
        binding: Option<&'p Ident>,
        subject: &'p Expr,
        branches: &'p [WhenBranch],
        span: Span,
    ) -> Ty {
        let subj_ty = self.check_expr(subject, None);
        // [when-bind] `when name = subject { … }` introduces `name`, a fresh
        // local bound to the subject and scoped to the `when`, and then
        // matches on it. The plain form requires the subject to already be a
        // variable, since the arms narrow it by name.
        let scoped = binding.is_some();
        if scoped {
            self.locals.push(HashMap::new());
        }
        let subject_name: String = match binding {
            Some(name) => {
                self.declare(name, subj_ty.clone());
                name.name.clone()
            }
            None => match subject {
                Expr::Ident(id) => id.name.clone(),
                _ => {
                    if scoped {
                        self.locals.pop();
                    }
                    self.error(span, messages::when_union_subject_not_a_variable());
                    for b in branches {
                        self.check_branch_block(&b.body, Vec::new());
                    }
                    return Ty::Unknown;
                }
            },
        };
        let result = self.check_when_body(binding, subject, &subject_name, &subj_ty, branches, span);
        if scoped {
            self.locals.pop();
        }
        result
    }

    /// The body of a `when` once the subject's name and type are fixed (the
    /// binding form introduced its local; the plain form named a variable).
    fn check_when_body(
        &mut self,
        binding: Option<&'p Ident>,
        subject: &'p Expr,
        subject_name: &str,
        subj_ty: &Ty,
        branches: &'p [WhenBranch],
        span: Span,
    ) -> Ty {
        // For the binding form the subject reads at its declared type; for the
        // plain form `repr_of` recovers a narrowed variable's storage type.
        let repr = match binding {
            Some(_) => subj_ty.clone(),
            None => self.repr_of(subject, subj_ty),
        };
        let Ty::Union(all_arms) = subj_ty else {
            // [when-union-subject] A *qualified* union (`Ok (A | B)`, or an
            // `Thrown (Str | Int)` message [throw-try]) is a claim **about** a
            // union, not a union: its arms belong to the inner type. The
            // qualifier is droppable ([qual-erasure]'s `Qual T <: T`), so
            // the remedy is a binding at the inner type — which also keeps
            // the level change visible to the reader, since the same
            // qualifier name can appear at both levels.
            let message = match &subj_ty {
                Ty::Qualified { quals, base } if matches!(**base, Ty::Union(_)) => {
                    let qual = quals
                        .iter()
                        .map(|q| q.name.clone())
                        .collect::<Vec<_>>()
                        .join(" ");
                    messages::when_union_subject_qualified_union(&subj_ty, &qual, &base)
                }
                _ => messages::when_union_subject_not_a_union(&subj_ty),
            };
            self.error(span, message);
            for b in branches {
                self.check_branch_block(&b.body, Vec::new());
            }
            return Ty::Unknown;
        };

        let mut remaining: Vec<Ty> = all_arms.clone();
        let mut branch_tys = Vec::new();
        let mut tails: Vec<Option<TailInfo>> = Vec::new();
        let mut fallthrough: Vec<NarrowSnapshot> = Vec::new();
        // A branch whose check named something unresolved cannot be
        // matched against the arms; its diagnostics — and the
        // exhaustiveness verdict, which the unmatched arms would falsify
        // — are suppressed [name-resolve].
        let mut unresolved_check = false;
        for branch in branches {
            let pat = self.parse_check(&branch.check, Some(&subj_ty));
            let matched: Vec<Ty> = remaining
                .iter()
                .filter(|arm| self.arm_matches(arm, &pat))
                .cloned()
                .collect();
            if pat.unresolved {
                unresolved_check = true;
            } else if matched.is_empty() {
                self.error(branch.span, messages::when_exhaustive_dead_branch());
            }
            if let Some(test) = self.union_test_for(&repr, &pat) {
                self.out.is_tests.insert(self.key(branch.span), test);
            }
            // [qual-lift] A `^` branch tests the same arm and then reads the
            // subject *without* the qualifiers: the whole point is the
            // nested case, where the arm's payload is itself a union
            // (`Ok (Ok Int | Err Str)`) that the branch can then `when` on.
            let narrow_ty = if branch.widen {
                let mut ok = !matched.is_empty();
                if pat.base.is_some() || pat.is_none {
                    self.error(branch.span, messages::qual_lift_branch_not_qualifiers());
                    ok = false;
                }
                for q in &pat.quals {
                    if let Some(reason) = self.removal_block(q) {
                        self.error(branch.span, messages::qual_lift_cannot_remove(&q, &reason));
                        ok = false;
                    }
                }
                let stripped: Vec<Ty> = matched
                    .iter()
                    .filter_map(|arm| strip_quals_named(arm, &pat.quals))
                    .collect();
                if ok && stripped.len() == matched.len() {
                    self.mk_union(stripped)
                } else {
                    if ok {
                        self.error(
                            branch.span,
                            messages::qual_lift_arm_not_carried(&pat.quals.join(" ")),
                        );
                    }
                    self.mk_union(matched.clone())
                }
            } else {
                self.mk_union(matched.clone())
            };
            let mut bindings = Vec::new();
            if let Some(b) = &branch.binding {
                if matches!(narrow_ty, Ty::Union(_)) {
                    self.error(b.span, messages::when_bind_several_types());
                }
                self.out.expr_ty.insert(self.key(b.span), narrow_ty.clone());
                // The `when` binding aliases the subject [fate-link].
                let links = self.links_for_value(subject, b.span);
                bindings.push((b.clone(), narrow_ty.clone(), links, None));
            }
            // [qual-lift] A `^` branch sees the subject at the widened
            // type, so nested narrowing composes on that rather than on the
            // storage the arm test peeled it out of.
            let declared = if branch.widen && self.out.is_tests.contains_key(&self.key(branch.span))
            {
                self.out
                    .widen_targets
                    .insert(self.key(branch.span), narrow_ty.clone());
                narrow_ty.clone()
            } else {
                repr.clone()
            };
            let narrows = vec![Narrow {
                place: Place::root(subject_name.to_string()),
                narrowed: narrow_ty,
                declared,
            }];
            // Isolate this branch's consumption effects; only
            // fall-through branches reach the code after the `when`
            // [deduce-consume].
            let entry = self.snapshot_narrows();
            let (ty, tail) =
                self.with_narrows(&narrows, |c| {
                    c.tail_hint = c.value_expected.clone();
                    c.check_branch_block(&branch.body, bindings)
                });
            if !self.block_exits(&branch.body) {
                fallthrough.push(self.snapshot_narrows());
            }
            self.restore_narrows(&entry);
            branch_tys.push(ty);
            tails.push(tail);
            remaining.retain(|arm| !matched.contains(arm));
        }
        self.merge_fallthrough(&fallthrough);
        if !unresolved_check {
            // [lsp-completion] The arms left to write, before the runtime-arm
            // rewrite collapses literals: spelled as the check would be.
            let key = self.key(span);
            self.out.when_arms.insert(key, remaining.iter().map(|a| a.to_string()).collect());
        }
        if !remaining.is_empty() && !unresolved_check {
            let missing: Vec<String> = remaining.iter().map(|a| a.to_string()).collect();
            self.error(
                span,
                messages::when_exhaustive_missing_arms(
                    &(if missing.len() == 1 { "" } else { "s" }),
                    &missing.join(", "),
                ),
            );
        } else if !branches.is_empty() && !unresolved_check {
            // [when-exhaustive] The arms cover every runtime arm. Record the
            // verdict so the IR can carry an explicit unreachable fallthrough
            // rather than have each backend re-derive it.
            let key = self.key(span);
            self.out.when_exhaustive.insert(key);
        }
        let join = self.mk_union(branch_tys);
        for tail in tails.into_iter().flatten() {
            self.maybe_coerce(tail.span, &tail.logical, &tail.repr, &join);
        }
        for branch in branches {
            self.reset_assigned(&branch.body);
        }
        join
    }

    /// [op-safe-nav] `base?.field` / `base?.method(args)`. Picks the receiver's
    /// **first arm** [type-union-arm-identity], performs the link on it, and
    /// replaces that arm with the link's result in the union — the other arms
    /// pass through unchanged. `(A | B | C)?.field` where `A.field: F` is
    /// `F | B | C` (arms collapse when `F` equals a pass-through arm). A `T?`
    /// (`T | None`) recovers the old behaviour: pick `T`, link to `F`, result
    /// `F | None`. One `?.` guards one link, so a chain `a?.b?.c` is nested
    /// `SafeNav` nodes, each checked here.
    fn check_safe_nav(
        &mut self,
        base: &'p Expr,
        access: &'p ast::SafeAccess,
        span: Span,
        expected: Option<&Ty>,
    ) -> Ty {
        let base_ty = self.check_expr(base, None);
        if matches!(base_ty, Ty::Unknown) {
            // [type-unknown-lenient] One mistake, one diagnostic.
            return Ty::Unknown;
        }
        // The pick is over the subject's declared arms, in order. A non-union
        // subject has one arm, leaving nothing to guard — refused, like a
        // pointless `!`.
        let declared: Vec<Ty> = match &base_ty {
            Ty::Union(arms) => arms.clone(),
            _ => vec![base_ty.clone()],
        };
        if declared.len() < 2 {
            self.error(span, messages::op_safe_nav_single_arm(&base_ty));
            return Ty::Unknown;
        }
        let inner = declared[0].clone();
        let rest = self.mk_union(declared[1..].to_vec());
        let optional = base_ty.has_none_arm() && declared.len() == 2 && rest.is_none_ty();
        let link_ty = self.safe_access_ty(base, &base_ty, access, &inner, expected, span);
        // [op-safe-nav] The result is the link's type joined with the arms left
        // behind; `union_of` collapses the link's result into a pass-through
        // arm of the same type (`(A | B | C)?.field` with `A.field: B` is
        // `B | C`). `already_opt` records that the link's value needs no
        // wrap/duplication — it is optional, or it lands on an existing arm.
        let result = self.mk_union(vec![link_ty.clone(), rest.clone()]);
        let already_opt = link_ty.has_none_arm()
            || declared[1..].iter().any(|a| *a == link_ty || a.strip_quals() == link_ty.strip_quals());
        self.out.safe_navs.insert(
            self.key(span),
            SafeNavInfo { inner: inner.clone(), rest, already_opt, optional },
        );
        result
    }

    /// [op-safe-nav] The type of the single link, given the receiver's non-`None`
    /// type `inner`. A field reads directly off `inner`. A call resolves as
    /// the dot call `base.m(args)` would, which needs the receiver to read at
    /// `inner`: that is a narrowing, so a call receiver must be a place (a
    /// chain `a?.b?.c` whose links are fields does not need one).
    fn safe_access_ty(
        &mut self,
        base: &'p Expr,
        base_ty: &Ty,
        access: &'p ast::SafeAccess,
        inner: &Ty,
        expected: Option<&Ty>,
        span: Span,
    ) -> Ty {
        match access {
            ast::SafeAccess::Field(field) => {
                self.record_field_ref(inner, field);
                self.field_ty_or_error(inner, field)
            }
            ast::SafeAccess::Call { field, type_args, args, named } => {
                // The receiver is read twice (the `None` test, then the call),
                // and the call reads it at the non-`None` type, so a call
                // receiver must be a place to carry the narrowing.
                let Some(place) = Place::of_expr(base) else {
                    self.error(span, messages::op_safe_nav_receiver_not_place());
                    for a in args {
                        self.check_expr(a, None);
                    }
                    return Ty::Unknown;
                };
                // [fn-member-call] [fn-uniform] The link is the dot call
                // `base.m(args)` on the first arm, under the one rule: a member
                // of `inner` is called, and anything else is `m(base, args)`.
                let narrow = [Narrow { place, narrowed: inner.clone(), declared: base_ty.clone() }];
                let inner = inner.clone();
                self.with_narrows(&narrow, |c| {
                    c.check_dot_call(None, base, field, false, Some(inner), type_args, args, named, expected, span)
                })
            }
        }
    }

    // ================= coercions =================

    /// Joins a loop's value contributions [loop-while-value]: the body tail,
    /// each `break value`, and the `else` tail — or `None` when there is
    /// no `else` (the loop may never run). A bare `break` or a `continue`
    /// also joins `None` (an iteration may end without producing a value).
    /// Tails and break values are coerced to the join like `if` branches.
    fn finish_loop_value(
        &mut self,
        body_ty: Ty,
        body_tail: Option<TailInfo>,
        ctx: LoopCtx,
        else_ty: Option<Ty>,
        else_tail: Option<TailInfo>,
    ) -> Ty {
        let mut arms = vec![body_ty];
        arms.extend(ctx.breaks.iter().map(|b| b.logical.clone()));
        match else_ty {
            Some(t) => arms.push(t),
            None => arms.push(Ty::none()),
        }
        if ctx.may_skip_value {
            arms.push(Ty::none());
        }
        let join = self.mk_union(arms);
        for tail in body_tail.into_iter().chain(ctx.breaks).chain(else_tail) {
            self.maybe_coerce(tail.span, &tail.logical, &tail.repr, &join);
        }
        join
    }

    /// [type-none-unit] Records that a `None` **literal** argument fills a
    /// slot whose type *is* `None`, so the emitters render the target's unit
    /// value (`()`, `Unit`) instead of an absent optional.
    ///
    /// `None` is one spelling for two things — the absent arm of a `T?` and
    /// the sole value of the `None` type — and the targets spell them
    /// differently, so the choice belongs wherever the *slot* is known. A
    /// generic argument the call inferred as `None` is the shape that needs
    /// it: `ok(None)` building an `Ok None | Err E`, `emitted(None)` for a
    /// sequence of optionals. Emitting the optional there is target code
    /// that does not compile, which is how the hole was found (phase 4's
    /// `close(s) -> Ok None | Err FsError`).
    fn note_none_unit(&mut self, arg: &Expr, slot: &Ty) {
        if slot.is_none_ty() && matches!(arg, Expr::Ident(id) if id.name == "None") {
            self.out
                .coerce
                .insert(self.key(arg.span()), Coercion::NoneUnit);
        }
    }

    /// Records the representation change (if any) needed to use a value of
    /// (`logical`, `repr`) where `expected` is required. Arm matching is
    /// positional over the declared type's non-`None` arms
    /// [type-union-arm-identity]; a qualified union group tries wrapping as
    /// a whole arm before stripping its qualifiers [qual-group].
    ///
    /// [str-drop-mut] A `Mut` qualifier dropped on the way is recorded too,
    /// wrapping whatever the representation math decided.
    ///
    /// [fn-effects] So is a producer *widening* — a pure producer used
    /// where a claiming one is expected — for the same reason: the two have
    /// different representations on both backends. Which positions need the
    /// adapter is therefore not a separate question: it is every position
    /// that funnels through here (call arguments, returns, `let`
    /// annotations, struct fields, union arms, branch joins).
    fn maybe_coerce(&mut self, span: Span, logical: &Ty, repr: &Ty, expected: &Ty) {
        self.coerce_repr(span, logical, repr, expected);
        if expected.is_unknown() || logical.is_unknown() {
            return;
        }
        // [proj-opt-slot] Borrowed arms read into an owned union: the
        // per-arm reading replaces whatever representation change was
        // recorded (a rewrap, a drop), since it says all of it.
        // A single borrow is the one-arm case (`proj X` into a kept `X`):
        // the IR says it the same way, so every such reading is visible.
        let single = logical.is_proj()
            && !matches!(crate::types::spread_union_quals(logical), Ty::Union(_))
            && !matches!(logical.strip_quals(), Ty::Fn { .. })
            && !crate::types::is_copy_scalar(logical.strip_quals());
        if (single || crate::types::has_borrowed_arm(logical)) && !expected.is_proj() {
            let to = crate::types::spread_union_quals(expected);
            let owned = |a: &Ty| !(a.is_proj() || crate::types::mentions_var(a) || matches!(a.strip_quals(), Ty::Any | Ty::Never | Ty::Unknown | Ty::Fn { .. }));
            // A single borrow wrapped into a union arm keeps its wrap: the
            // node is the one-arm reading, `proj X` → `X`.
            let plain = match &to {
                Ty::Union(arms) => !single && arms.iter().all(owned),
                t => owned(t),
            };
            if plain && crate::types::read_arm_map(logical, &to).is_some() {
                let key = self.key(span);
                self.out.coerce.insert(key, Coercion::BorrowAs { from: logical.clone(), to });
                return;
            }
        }
        // A `Mut` arm anywhere in the expected type means the value may
        // stay a builder: `Mut Str`, `Mut Str?`, and a generic position
        // (whose pattern is substituted to the argument's own type) all
        // keep it.
        if expected.arms().iter().any(|a| Self::carries_mut(a))
            || expected.strip_quals().arms().iter().any(|a| Self::carries_mut(a))
        {
            return;
        }
        if matches!(expected.strip_quals(), Ty::Var(_) | Ty::Any | Ty::Never) {
            return;
        }
        let from = if Self::carries_mut(logical) {
            logical.clone()
        } else if Self::carries_mut(repr) {
            repr.clone()
        } else if Self::optional_of_mut(logical) {
            // [proj-opt-slot] An optional `Mut` borrow read where the plain
            // optional is expected drops `Mut` on its present arm.
            logical.clone()
        } else {
            return;
        };
        self.record_mut_drop(span, from);
    }

    /// An optional whose one value arm carries `Mut`: `(proj Mut Str)?`.
    fn optional_of_mut(ty: &Ty) -> bool {
        matches!(ty, Ty::Union(arms) if arms.len() == 2
            && arms.iter().any(|a| a.is_none_ty())
            && arms.iter().any(Self::carries_mut))
    }

    /// Whether a type carries the `Mut` qualifier at its top level.
    fn carries_mut(ty: &Ty) -> bool {
        ty.quals().iter().any(|q| q.name == "Mut")
    }

    /// [str-drop-mut] Records a `Mut` drop at `span`, keeping any
    /// representation change already recorded there as the drop's
    /// continuation. Used by the positions that have no *expected type* to
    /// compare against — operator operands and string interpolation — as
    /// well as by `maybe_coerce`.
    fn record_mut_drop(&mut self, span: Span, from: Ty) {
        if !Self::carries_mut(&from) && !Self::optional_of_mut(&from) {
            return;
        }
        let key = self.key(span);
        let then = match self.out.coerce.remove(&key) {
            // Already recorded: keep it, but do not nest a drop in a drop.
            Some(Coercion::DropMut { from, then }) => {
                self.out
                    .coerce
                    .insert(key, Coercion::DropMut { from, then });
                return;
            }
            other => other.map(Box::new),
        };
        self.out
            .coerce
            .insert(key, Coercion::DropMut { from, then });
    }

    /// [str-drop-mut] The `Mut`-dropping conversion an *operand* needs: an
    /// operator compares or concatenates plain values, and on a backend
    /// where a builder is its own type the two are not comparable at all
    /// (Kotlin's `StringBuilder == String` is `false`, and `sb1 == sb2` is
    /// *reference* equality against Rust's structural `String == String`).
    /// Rejecting `Mut` operands the way [op-no-none] rejects optionals was
    /// declined: `Mut List` is accepted everywhere else, so a rejection
    /// here would surprise.
    fn drop_mut_operand(&mut self, expr: &'p Expr, ty: &Ty) {
        if Self::carries_mut(ty) {
            self.record_mut_drop(expr.span(), ty.clone());
        }
    }

    /// Records the representation change (if any) needed to use a value of
    /// (`logical`, `repr`) where `expected` is required.
    fn coerce_repr(&mut self, span: Span, logical: &Ty, repr: &Ty, expected: &Ty) {
        if expected.is_unknown() || logical.is_unknown() || matches!(logical, Ty::Never) {
            return;
        }
        // [type-literal] A literal typed as its base (no expected type when
        // it was checked) is the literal wherever the slot lists it.
        if let Some(lit) = self.lit_spans.get(&self.key(span)).cloned() {
            if logical == &Ty::named(lit.base()) {
                if let Some(t) = adopt_literal(Some(expected), lit) {
                    return self.coerce_repr(span, &t, &t, expected);
                }
            }
        }
        // The emitter unwraps identifier uses narrowed to a single arm, so
        // the effective representation is the narrowed type in that case.
        // The same holds for a `T?` representation narrowed to its value
        // arm: backends that read optionals physically (Rust) unwrap at
        // the use site, and Kotlin smart-casts to the same effect.
        let effective = if crate::literal::mentions_lit(logical)
            && crate::literal::collapse_ty(logical) == crate::literal::collapse_ty(repr)
        {
            // [is-union] [type-literal] A `Str` narrowed to `"json" | "text"`
            // is the same value at run time: its literal type is what fits.
            logical.clone()
        } else if repr.is_wrapper_union() && !matches!(logical, Ty::Union(_)) {
            logical.clone()
        } else if repr.has_none_arm()
            && matches!(repr, Ty::Union(_))
            && !logical.has_none_arm()
            && !logical.is_none_ty()
            && !matches!(logical, Ty::Union(_))
        {
            logical.clone()
        } else if matches!(repr, Ty::Union(_))
            && matches!(logical, Ty::Union(_))
            && logical != repr
            && logical.value_arms().iter().all(|a| repr.value_arms().contains(a))
            && (!logical.has_none_arm() || repr.has_none_arm())
        {
            // [type-rewrap] A union narrowed to some of its arms is read through
            // the narrowing binding, which already holds the narrower union
            // (the IR's `Narrow` has the logical type). Found 2026-10-20: a
            // `("json" | "text")?` narrowed past `None` into a `"json" |
            // "text"` field, and an `Int | Str | Bool` narrowed by `!is Bool`
            // into an `Int | Str` parameter, were both rewrapped from the
            // declared union a second time, which rustc and kotlinc refused.
            logical.clone()
        } else {
            repr.clone()
        };
        // A qualified union group (`Ok (A | B)`) wraps as a whole when it is
        // itself an arm of the expected union; otherwise it is physically
        // just the inner union and joins the representation math below.
        let effective = if let Ty::Qualified { base, .. } = &effective {
            if matches!(**base, Ty::Union(_)) {
                if expected.is_wrapper_union() {
                    let arms = expected.value_arms();
                    if let Some(i) = arms.iter().position(|arm| **arm == effective) {
                        self.out.coerce.insert(
                            self.key(span),
                            Coercion::WrapUnion {
                                target: expected.clone(),
                                arm: i,
                                inner: None,
                            },
                        );
                        return;
                    }
                }
                (**base).clone()
            } else {
                effective
            }
        } else {
            effective
        };
        if expected.is_wrapper_union() {
            if effective == *expected {
                return;
            }
            if let Ty::Union(_) = effective {
                if effective.value_arms() == expected.value_arms()
                    && (!effective.has_none_arm() || expected.has_none_arm())
                {
                    return;
                }
                self.out.coerce.insert(
                    self.key(span),
                    Coercion::Rewrap {
                        from: effective,
                        to: expected.clone(),
                    },
                );
                return;
            }
            if effective.is_none_ty() {
                if !expected.has_none_arm() {
                    self.error(span, messages::type_union_none_not_arm(&expected));
                }
                return;
            }
            let arms = expected.value_arms();
            let matches: Vec<usize> = arms
                .iter()
                .enumerate()
                .filter(|(_, arm)| is_subtype(&effective, arm))
                .map(|(i, _)| i)
                .collect();
            match matches.len() {
                1 => {
                    // [qual-group] A value whose qualifier list flattened
                    // (`emitted(ok("x"))` for an `Emitted (Ok Str | Err Str)`
                    // arm) is physically the bare inner value: wrap it into
                    // the inner union first.
                    let inner = crate::types::nested_group_arm(&effective, arms[matches[0]]).map(
                        |(inner_ty, inner_arm)| {
                            Box::new(Coercion::WrapUnion {
                                target: inner_ty,
                                arm: inner_arm,
                                inner: None,
                            })
                        },
                    );
                    self.out.coerce.insert(
                        self.key(span),
                        Coercion::WrapUnion {
                            target: expected.clone(),
                            arm: matches[0],
                            inner,
                        },
                    );
                }
                0 => {
                    // [qual-arm-infer] Before refusing, try provenance-arm
                    // inference: a bare value may be the payload of exactly
                    // one provenance-tagged arm (`return name.size()` for
                    // `-> Ok Int | Err Str` is implicitly `Ok(…)`). The
                    // qualifier is erased, so wrapping the value into that arm
                    // *is* the mint — a plain `WrapUnion`, no ctor call.
                    if let Some(i) = self.infer_provenance_arm(&effective, &arms) {
                        // [qual-group] An arm whose payload is itself a union
                        // (`Ok (Ok Int | Err Str)`, reached by `ok(ok(1))`,
                        // whose flat qualifier list is just `Ok Int`) holds
                        // the value wrapped into that union first.
                        let payload = self.provenance_payload(arms[i]);
                        let inner = match &payload {
                            Some(u) if u.is_wrapper_union() => {
                                let fits: Vec<usize> =
                                    u.value_arms().iter().enumerate().filter(|(_, a)| is_subtype(&effective, a)).map(|(j, _)| j).collect();
                                let [j] = fits[..] else {
                                    self.error(span, messages::type_union_no_arm(&expected, &logical, true));
                                    return;
                                };
                                Some(Box::new(Coercion::WrapUnion { target: u.clone(), arm: j, inner: None }))
                            }
                            _ => None,
                        };
                        self.out.coerce.insert(
                            self.key(span),
                            Coercion::WrapUnion {
                                target: expected.clone(),
                                arm: i,
                                inner,
                            },
                        );
                        return;
                    }
                    // [qual-group] One shape reads confusingly here: an
                    // expected arm `Q (A | B)` whose inner arms are
                    // themselves qualified, reached by a value carrying
                    // nothing *but* `Q`. Qualifier lists are flat and
                    // deduplicated, so a repeated qualifier vanishes
                    // (`ok(ok(x))` *is* `Ok Str`) and the value cannot say
                    // which reading it is — name the workaround, since the
                    // type in the message looks like it should fit.
                    let deduplicated = arms.iter().any(|arm| match arm {
                        Ty::Qualified { quals, base } => {
                            matches!(**base, Ty::Union(_))
                                && effective
                                    .quals()
                                    .iter()
                                    .all(|v| quals.iter().any(|q| q.name == v.name))
                                && base.value_arms().iter().any(|a| !a.quals().is_empty())
                        }
                        _ => false,
                    });
                    if let Some(msg) =
                        literal_refusal(expected, logical, self.lit_spans.get(&self.key(span)))
                    {
                        self.error(span, msg);
                        return;
                    }
                    // [qual-arm-infer] Two provenance arms would take the
                    // value (`return n` for `-> Ok Int | Err Int`): the
                    // mistake is the ambiguity, not a missing arm.
                    if self.provenance_arms(&effective, &arms).len() > 1 {
                        self.error(span, messages::type_union_ambiguous_arm(&logical, &expected));
                        return;
                    }
                    self.error(span, messages::type_union_no_arm(&expected, &logical, deduplicated))
                }
                _ => self.error(span, messages::type_union_ambiguous_arm(&logical, &expected)),
            }
        }
        // Nullable-style or plain expected types need no union wrapping; a
        // wrapper-union value in a non-union slot is a plain type error
        // reported at the boundary. A bare value used where an optional
        // (`T?`-style) representation is expected records a WrapOption
        // [type-nullable]: physical-optional backends (Rust) wrap it in
        // `Some(...)`; Kotlin nullability ignores it.
        if !expected.is_wrapper_union()
            && matches!(expected, Ty::Union(_))
            && expected.has_none_arm()
            && !effective.is_unknown()
            && !effective.is_none_ty()
            && !effective.has_none_arm()
            && !matches!(effective, Ty::Union(_))
        {
            self.out.coerce.insert(
                self.key(span),
                Coercion::WrapOption {
                    target: expected.clone(),
                },
            );
        }
    }
}

/// [type-literal] Why a value of type [got] does not fit the union of literals
/// [want], when that is the reason: a literal it does not list (a typo, most
/// often), or a plain value of the literals' base, which must be narrowed to
/// one of them first — or, where the union has an open arm, wrapped with
/// `other(…)`. `None` when the mismatch is something else.
fn literal_refusal(want: &Ty, got: &Ty, written: Option<&TypeLit>) -> Option<Message> {
    let lits: Vec<&TypeLit> = want
        .arms()
        .iter()
        .filter_map(|a| match a {
            Ty::Lit(l) => Some(l),
            _ => None,
        })
        .collect();
    let base = lits.first()?.base();
    if got != &Ty::named(base) {
        return None;
    }
    let listed: Vec<String> = lits.iter().filter(|l| l.base() == base).map(|l| l.to_string()).collect();
    let open = want.arms().iter().any(|a| {
        !matches!(a, Ty::Lit(_)) && a.strip_quals() == &Ty::named(base) && a.quals().iter().any(|q| q.name == "Other")
    });
    let listed = listed.join(", ");
    Some(match written {
        Some(lit) => {
            let hint = if open { format!(" — or `other({lit})` for the open arm") } else { String::new() };
            messages::type_literal_not_listed(&lit, &want, &listed, &hint)
        }
        None => {
            let hint = if open { ", or wrap it with `other(…)` for the open arm" } else { "" };
            messages::type_literal_needs_narrowing(&base, &want, &listed, &hint)
        }
    })
}

/// [type-literal] The literal a plain literal expression writes: a string with
/// no interpolation, an integer (negated too), a `Long`, a `Bool`.
fn expr_literal(e: &Expr) -> Option<TypeLit> {
    match e {
        Expr::Str { parts, .. } => {
            let mut text = String::new();
            for p in parts {
                match p {
                    StrExprPart::Text(t) => text.push_str(t),
                    StrExprPart::Interp(_) => return None,
                }
            }
            Some(TypeLit::Str(text))
        }
        Expr::Int { value, long, .. } => Some(if *long { TypeLit::Long(*value) } else { TypeLit::Int(*value) }),
        Expr::Bool { value, .. } => Some(TypeLit::Bool(*value)),
        _ => None,
    }
}

/// [type-literal] The literal type a literal expression takes from the
/// expected type: the literal itself, when the expected type is it or lists it
/// as a union arm — the contextual rule, so a literal nowhere near a literal
/// type stays its base.
fn adopt_literal(expected: Option<&Ty>, lit: TypeLit) -> Option<Ty> {
    fn lists(t: &Ty, lit: &TypeLit) -> bool {
        match t {
            Ty::Lit(l) => l == lit,
            Ty::Union(arms) => arms.iter().any(|a| lists(a, lit)),
            _ => false,
        }
    }
    let e = expected?;
    lists(e, &lit).then(|| Ty::Lit(lit))
}

/// [fn-kept-borrow] When a fn value of type `value` fails to fit `want` only
/// because it **consumes** a parameter the position would hand a borrow, the
/// diagnostic's text for it: what is consumed, what it would be given, and
/// the remedies. `what` names the value (`` `eat` `` or "this fn value").
fn consumed_borrow_hint(value: &Ty, want: &Ty, what: &str) -> Option<String> {
    let (Ty::Fn { params: vp, contract: Some(vc), ret, effects }, Ty::Fn { params: wp, .. }) = (value.strip_quals(), want.strip_quals()) else {
        return None;
    };
    if vp.len() != wp.len() {
        return None;
    }
    let j = (0..vp.len()).find(|&j| crate::types::fn_param_reads_borrow(&vp[j], &wp[j]) && !crate::types::fn_contract_keeps(Some(vc), j))?;
    let mut kept = vc.clone();
    if let Some(e) = kept.get_mut(j) {
        e.kept = true;
        e.mutable = false;
    }
    let fixed = Ty::Fn { params: vp.clone(), ret: ret.clone(), contract: Some(kept), effects: effects.clone() };
    if !is_subtype(&fixed, want) && !fn_value_fits(&fixed, want) {
        return None;
    }
    let pname = vc.get(j).and_then(|e| e.name.clone()).unwrap_or_else(|| format!("#{}", j + 1));
    Some(format!(
        "{what} consumes its parameter `{pname}` (`=> !{pname}`), and here it would be given a \
         borrowed `{}`, which cannot be given away. Keep the parameter, or pass a lambda \
         that copies the argument",
        wp[j]
    ))
}

/// [fn-kept-borrow] For a call candidate the arguments did not unify with:
/// the hint of [`consumed_borrow_hint`] when a fn argument's consumed
/// parameter is what kept it out — the candidate unifies once that argument
/// keeps its parameters, and its position then hands the parameter a borrow.
fn consumed_borrow_block(patterns: &[Ty], arg_tys: &[Ty], args: &[&Expr], generics: &[Ident]) -> Option<String> {
    let gens: HashSet<String> = generics.iter().map(|g| g.name.clone()).collect();
    for (i, a) in arg_tys.iter().enumerate() {
        let Ty::Fn { params, ret, contract: Some(c), effects } = a.strip_quals() else { continue };
        if c.iter().all(|e| e.kept && !e.mutable) {
            continue;
        }
        let kept: Vec<crate::types::FnParamContract> = c.iter().cloned().map(|mut e| { e.kept = true; e.mutable = false; e }).collect();
        let mut trial = arg_tys.to_vec();
        trial[i] = Ty::Fn { params: params.clone(), ret: ret.clone(), contract: Some(kept), effects: effects.clone() };
        let mut subst = HashMap::new();
        if !patterns.iter().zip(&trial).all(|(p, t)| unify(p, t, &mut subst)) {
            continue;
        }
        let Some(p) = patterns.get(i) else { continue };
        let sp = substitute_vars(p, &subst, &gens);
        let what = match args.get(i) {
            Some(Expr::Ident(id)) => format!("`{}`", id.name),
            _ => "this fn value".to_string(),
        };
        if let Some(h) = consumed_borrow_hint(a, &sp, &what) {
            return Some(h);
        }
    }
    None
}

/// [implicit-resolve] Whether a function *value* of type `candidate` fits a
/// position that wants `want`: **parameters contravariant, result
/// covariant**, plus the contract and effect variance [fn-contract]
/// [fn-effects].
///
/// `is_subtype` compares fn parameters *invariantly* — deliberately
/// conservative, since a backend renders a parameter's convention from its
/// declared type and two conventions are two different target types — except
/// in erased qualifiers, which no backend renders [fn-erased-variance]. Here
/// the rule the spec states applies in full, because the value is only ever *called*
/// by the callee that declared the position (and a resolved fill is passed
/// through an adapter built from the declaration's own modes
/// [implicit-intrinsic]): std's
/// `iter(list: List<T>) -> Iter<T>` has to fill an `?Iterable<It, T>` whose
/// `It` turned out to be a `Mut List<Int>`, and reading a list that happens
/// to be mutable is exactly what it does.
fn fn_value_fits(candidate: &Ty, want: &Ty) -> bool {
    match (candidate.strip_quals(), want.strip_quals()) {
        (
            Ty::Fn {
                params: cp,
                ret: cr,
                contract: cc,
                effects: ce,
            },
            Ty::Fn {
                params: wp,
                ret: wr,
                contract: wc,
                effects: we,
            },
        ) => {
            cp.len() == wp.len()
                && cp.iter().zip(wp).enumerate().all(|(i, (c, w))| {
                    is_subtype(w, c) || (crate::types::fn_param_reads_borrow(c, w) && crate::types::fn_contract_keeps(cc.as_deref(), i))
                })
                && is_subtype(cr, wr)
                && crate::types::contract_fits(cc.as_deref(), wc.as_deref(), cp.len())
                && ce.iter().all(|e| we.contains(e))
        }
        _ => is_subtype(candidate, want),
    }
}

// ================= unification =================

/// [type-union-spread] Unify a union *parameter* against a union *argument*. A
/// parameter arm written `...T` (an explicit spread, [`Ty::as_spread_marker`])
/// binds its variable to a **span** of ≥1 argument arms; every other
/// parameter arm — concrete, or a bare type variable — captures exactly one
/// argument arm. So `detach<T, C>(...T | Box2<C>)` meeting
/// `Str | Int | Box2<Bool>` binds `T = Str | Int`, `C = Bool`; a bare `T | S`
/// (no spread) captures one arm each.
///
/// The split is: match each argument arm against the parameter's *non-spread*
/// arms first; the argument arms none of them claims are the residual, which
/// goes to the lone `...T` spread arm. At most one spread per union (enforced
/// where the type is written), so there is never an ambiguous partition. With
/// no spread arm every argument arm must match some non-spread parameter arm
/// one-to-one.
fn unify_union_arms(parms: &[Ty], aarms: &[Ty], subst: &mut HashMap<String, Ty>) -> bool {
    // A parameter arm is a *span slot* when it is an explicit `...T` spread
    // whose variable the callee has not already bound to a concrete type.
    let is_span_slot = |p: &Ty| {
        matches!(p.as_spread_marker(), Some(Ty::Var(g))
            if subst.get(g).map(|b| matches!(b, Ty::Var(_))).unwrap_or(true))
    };
    // A non-spread parameter arm matched against one argument arm: the spread
    // marker (if any) is stripped to its inner variable, so `...T` as a plain
    // match still binds `T` to a single arm when it is the only candidate.
    let strip_spread = |p: &Ty| p.as_spread_marker().cloned().unwrap_or_else(|| p.clone());
    let one_to_one = |subst: &mut HashMap<String, Ty>| {
        aarms.iter().all(|a| {
            parms.iter().any(|p| {
                let p = strip_spread(p);
                unify(&p, a, &mut subst.clone()) && unify(&p, a, subst)
            })
        })
    };
    let span_slots: Vec<&Ty> = parms.iter().filter(|p| is_span_slot(p)).collect();
    // No span slot: the classic all-concrete union — every argument arm must
    // match some parameter arm.
    if span_slots.is_empty() {
        return one_to_one(subst);
    }
    // The residual: argument arms no non-spread parameter arm claims. A `None`
    // argument arm is never part of a span (optionality is positional, not an
    // arm a variable absorbs), so it must be matched by a non-spread arm.
    let concrete: Vec<Ty> = parms.iter().filter(|p| !is_span_slot(p)).map(strip_spread).collect();
    // More than one spread is refused where the type is written; defensively,
    // if two reach here the partition is ambiguous, so fall back to one-to-one
    // (a turbofish, having bound the variables, still satisfies it).
    if span_slots.len() != 1 {
        return one_to_one(subst);
    }
    let mut residual: Vec<Ty> = Vec::new();
    for a in aarms {
        let claimed = concrete.iter().any(|p| unify(p, a, &mut subst.clone()) && unify(p, a, subst));
        if !claimed {
            residual.push(a.clone());
        }
    }
    let Some(Ty::Var(g)) = span_slots[0].as_spread_marker() else { return false };
    // Nothing left over: every argument arm was a concrete match, so the
    // span variable has no arms to bind. Leave it unbound (a later argument
    // or the return context may still determine it) rather than binding the
    // empty `Never`.
    if residual.is_empty() {
        return true;
    }
    let span = Ty::union_of(residual);
    unify(&Ty::Var(g.clone()), &span, subst)
}

/// Structural unification of a (possibly generic) parameter type pattern
/// against an argument type, binding `Var`s in `subst`. Lenient: `Unknown`
/// matches anything; qualified arguments match unqualified parameters.
fn unify(param: &Ty, arg: &Ty, subst: &mut HashMap<String, Ty>) -> bool {
    if arg.is_unknown() || param.is_unknown() || *arg == Ty::Never {
        return true;
    }
    // [type-literal] A literal argument binds a type variable to its *base*
    // (`List("a", "b")` is a `List<Str>`), and a union of literals meets a
    // non-literal parameter as its base — the widening rule.
    if crate::literal::mentions_lit(arg) && !crate::literal::mentions_lit(param) {
        let w = crate::literal::widen(arg);
        if w != *arg {
            return unify(param, &w, subst);
        }
    }
    match (param, arg) {
        (Ty::Var(g), _) => {
            match subst.get(g) {
                Some(bound) => {
                    let bound = bound.clone();
                    if is_subtype(arg, &bound) {
                        true
                    } else if is_subtype(&bound, arg) {
                        // A later argument revealed the more general type:
                        // widen the binding (`pick(1, maybe_int)` binds
                        // `T = Int?`, not first-seen `Int`). Keeping the
                        // narrow binding would make the checker believe a
                        // possibly-`None` result is plain `T`.
                        subst.insert(g.clone(), arg.clone());
                        true
                    } else {
                        false
                    }
                }
                None => {
                    // No occurs check, deliberately: `Ty::Var` identity is
                    // name-scoped *per side* — the callee's `T` and a
                    // caller's `T` inside `arg` are different variables
                    // (`fn wrap<T>(x: List<T>)` forwarding to
                    // `inner<T>(x: T)` binds callee-`T` := `List<caller-T>`,
                    // which a name-based occurs check would wrongly
                    // reject). Argument types never contain the callee's
                    // own vars, and `substitute_vars` replaces without
                    // recursing into bindings, so expansion terminates.
                    subst.insert(g.clone(), arg.clone());
                    true
                }
            }
        }
        // [cmp-carry] The identity domain. A **binder** binds like a type
        // variable — one binding per signature, so two occurrences captured
        // from two arguments must agree (the ordering round's decision 11) — and two
        // *named* identities match only by being the same fn, which is what
        // makes `Heap(min_by_age)` and `Heap(max_by_age)` refuse to mix.
        (Ty::FnName(FnId::Binder(b)), Ty::FnName(id)) => {
            let key = FnId::subst_key(b);
            let bound = Ty::FnName(id.clone());
            match subst.get(&key) {
                Some(seen) => *seen == bound,
                None => {
                    subst.insert(key, bound);
                    true
                }
            }
        }
        (Ty::FnName(a), Ty::FnName(b)) => a == b,
        // An identity never unifies with a type, in either direction: the
        // slot decides which of the two a position is, so a mismatch here is
        // a written-form mistake the lowering has already reported.
        (Ty::FnName(_), _) | (_, Ty::FnName(_)) => false,
        // [qual-depend] Place identities: a rooted pattern (the parameter's
        // slot, substituted with the sibling argument's roots) matches a
        // rooted claim only when they agree — `KeyOf(m1)` refuses a
        // `KeyOf(m2)` position. A root-free side is a template (an
        // annotation, an unsubstituted signature) and stays lenient.
        (
            Ty::ValueRef { roots: pr, .. },
            Ty::ValueRef { roots: ar, .. },
        ) => {
            pr.is_empty() || ar.is_empty() || {
                let mut a = pr.clone();
                let mut b = ar.clone();
                a.sort_unstable();
                b.sort_unstable();
                a == b
            }
        }
        (Ty::ValueRef { .. }, _) | (_, Ty::ValueRef { .. }) => false,
        // [qual-const] Two constants match by value, and a constant never
        // unifies with a type.
        (Ty::Const(a), Ty::Const(b)) => a == b,
        (Ty::Const(_), _) | (_, Ty::Const(_)) => false,
        (
            Ty::Qualified {
                quals: pq,
                base: pb,
            },
            _,
        ) => {
            let arg_quals: Vec<&str> = arg.quals().iter().map(|q| q.name.as_str()).collect();
            // [fn-once] A `once` requirement is satisfied by any fn
            // (inverted subtyping: plain fns may be treated as
            // once-callable). [fn-effects] An effect claim is the same
            // direction: a producer that performs *fewer* effects fits a
            // position expecting more, so the claim need not be present on
            // the argument — while an effect the argument *does* claim must
            // be one the position expects, which `is_subtype` then checks.
            // [proj-type] `proj T` is satisfied by an owned value too
            // (`X <: proj X`), so it need not be on the argument either.
            // The residual the base unifies against keeps the argument's
            // never-drop qualifiers the pattern did not match (`Emitted T`
            // against `Emitted (proj Str)` binds `T = proj Str`), and
            // drops the droppable ones as before.
            let residual = {
                let mut names: HashSet<String> = pq.iter().map(|q| q.name.clone()).collect();
                // [ref-handle] A borrow position matches either flavour: a
                // `ref` handle read through `proj T` binds `T` to what it
                // names, not to the handle.
                if pq.iter().any(|q| crate::types::is_proj_name(&q.name)) {
                    names.extend(crate::types::proj_names());
                }
                match arg {
                    // [proj-opt-slot] A union with borrowed arms read through
                    // `proj T` binds `T` to the owned union: `copy(get(xs,
                    // i))` is a `Str?` of its own.
                    Ty::Union(arms)
                        if pq.iter().any(|q| crate::types::is_proj_name(&q.name))
                            && arms.iter().any(|a| a.is_proj()) =>
                    {
                        Ty::Union(arms.iter().map(|a| a.clone().remove_quals(&names)).collect())
                    }
                    _ => arg.clone().remove_quals(&names),
                }
            };
            pq.iter().all(|q| {
                q.name == "once"
                    || crate::types::is_proj_name(&q.name)
                    || q.effect
                    || arg_quals.contains(&q.name.as_str())
            }) && arg
                .quals()
                .iter()
                .filter(|q| q.effect)
                .all(|q| pq.contains(q))
                // [cmp-carry] A qualifier's own arguments unify too, which is
                // how a **captured binder** learns the identity its argument
                // carries: `Heap(?cmp)` against `Heap(cmp@Person)` binds
                // `?cmp`, and a second parameter sharing the binder must then
                // agree — `heap_merge`'s "two heaps ordered differently" is
                // this unification failing, reported as the ordinary
                // argument-does-not-fit error naming both types. A value
                // carrying the qualifier *bare* says nothing about the slot,
                // so there is nothing to bind and the missing identity is
                // reported where it is needed.
                && pq.iter().all(|q| {
                    if q.args.is_empty() {
                        return true;
                    }
                    match arg.quals().iter().find(|a| a.name == q.name) {
                        Some(a) if a.args.len() == q.args.len() => q
                            .args
                            .iter()
                            .zip(&a.args)
                            .all(|(p, x)| unify(p, x, subst)),
                        _ => true,
                    }
                })
                && unify(pb, &residual, subst)
        }
        // A union parameter tries each arm against the *intact* argument —
        // this must precede the qualifier-stripping arm below, or a
        // qualified argument (`Ok Str`) could never match a union's
        // qualified arm (`Ok Str | Err Str`) [type-union].
        (Ty::Union(parms), _) => match arg {
            Ty::Union(aarms) => unify_union_arms(parms, aarms, subst),
            // [call-type-args] A concrete arm is tried before a bare variable, so a `None`
            // argument meets `Q?`'s `None` and leaves `Q` for a later
            // argument: binding `Q` to `None` first refused `m<Str>(None,
            // (x: Str) -> x)` for `m<Q>(d: Q?, r: (v: Q) -> Q?)`.
            _ => {
                let is_var = |p: &Ty| matches!(p, Ty::Var(_));
                parms.iter().filter(|p| !is_var(p)).any(|p| unify(p, arg, &mut subst.clone()) && unify(p, arg, subst))
                    || parms.iter().filter(|p| is_var(p)).any(|p| unify(p, arg, subst))
            }
        },
        // `Qual T` can be passed where `T` is expected — except `once`,
        // which may never be dropped [fn-once]. (A top-level `proj` is
        // dropped *here*, for the binding: `size(list: List<T>)` given a
        // `proj List<Str>` binds `T = Str`; whether the position may take
        // the projection is the assignability check's business
        // [proj-type].)
        (_, Ty::Qualified { quals, base }) => {
            // [fn-once] D6 (user decision 2026-09-12): `once` drops on a
            // *data* type — a plain-typed holder consumes at most once
            // anyway — and never on a fn type, whose plain form is
            // callable repeatedly.
            let once_blocked =
                quals.iter().any(|q| q.name == "once") && matches!(**base, Ty::Fn { .. });
            !once_blocked && !quals.iter().any(|q| q.effect) && unify(param, base, subst)
        }
        (Ty::Named { name: pn, args: pa }, Ty::Named { name: an, args: aa }) => {
            // [cmp-carry] A pattern may omit a keyed container's trailing
            // identity arguments — unstated is unconstrained — so the common
            // prefix is what unifies, and a dropped tail must be identities.
            let common = pa.len().min(aa.len());
            let droppable = |t: &&Ty| matches!(t, Ty::FnName(_) | Ty::Unknown);
            pn == an
                && pa[common..].iter().all(|t| droppable(&t))
                && aa[common..].iter().all(|t| droppable(&t))
                && pa[..common]
                    .iter()
                    .zip(&aa[..common])
                    .all(|(p, a)| unify(p, a, subst))
        }
        (Ty::Array(p), Ty::Array(a)) => unify(p, a, subst),
        (Ty::Tuple(ps), Ty::Tuple(as_)) => {
            ps.len() == as_.len() && ps.iter().zip(as_).all(|(p, a)| unify(p, a, subst))
        }
        (
            Ty::Fn {
                params: pp,
                ret: pr,
                contract: pc,
                ..
            },
            Ty::Fn {
                params: ap,
                ret: ar,
                contract: ac,
                ..
            },
        ) => {
            pp.len() == ap.len()
                && pp.iter().zip(ap).all(|(p, a)| {
                    // [fn-erased-variance] A value's parameter may carry fewer
                    // erased qualifiers than the pattern's: bind through the
                    // bases, and let `is_subtype` judge the fit.
                    let mut trial = subst.clone();
                    if unify(p, a, &mut trial) {
                        *subst = trial;
                        return true;
                    }
                    let (ps, as_) = (crate::types::strip_erased_quals(p), crate::types::strip_erased_quals(a));
                    // [fn-kept-borrow] A value's owned parameter may read a
                    // borrow its pattern's variable is bound to: bind through
                    // the owned type, and let `is_subtype` judge the fit and
                    // the contract.
                    if let Ty::Var(g) = p {
                        if let Some(bound) = subst.get(g).cloned() {
                            if crate::types::fn_param_reads_borrow(a, &bound) {
                                let owned = crate::types::strip_erased_quals(&bound.remove_quals(&crate::types::proj_names()));
                                let mut trial = subst.clone();
                                if unify(&owned, &as_, &mut trial) {
                                    *subst = trial;
                                    return true;
                                }
                            }
                        }
                    }
                    (ps != *p || as_ != *a) && unify(&ps, &as_, subst)
                })
                && unify(pr, ar, subst)
                // [fn-contract] keeps <: consumes (inverted, like
                // [fn-once]); mutation permission must be granted.
                && crate::types::contract_fits(ac.as_deref(), pc.as_deref(), pp.len())
        }
        (Ty::Any, _) => true,
        _ => param == arg,
    }
}

/// Replaces the callee's generic parameters with their bindings (`Unknown`
/// when unbound). Foreign `Var`s (the caller's generics) are left alone.
/// Does `ty` mention the type variable `g` anywhere? [call-type-args]
fn ty_mentions_var(ty: &Ty, g: &str) -> bool {
    match ty {
        Ty::Var(v) => v == g,
        Ty::Named { args, .. } => args.iter().any(|a| ty_mentions_var(a, g)),
        Ty::Qualified { quals, base } => {
            ty_mentions_var(base, g)
                || quals
                    .iter()
                    .any(|q| q.args.iter().any(|a| ty_mentions_var(a, g)))
        }
        Ty::Union(arms) | Ty::Tuple(arms) => arms.iter().any(|a| ty_mentions_var(a, g)),
        Ty::Array(elem) => ty_mentions_var(elem, g),
        Ty::Fn { params, ret, .. } => {
            params.iter().any(|p| ty_mentions_var(p, g)) || ty_mentions_var(ret, g)
        }
        _ => false,
    }
}

/// Does `ty` mention any of `vars`? [call-type-args]
fn ty_mentions_vars(ty: &Ty, vars: &HashSet<String>) -> bool {
    vars.iter().any(|v| ty_mentions_var(ty, v))
}

/// Does `ty` contain an un-inferred part? [type-unknown-lenient] An
/// argument like this fits *every* candidate, so overload ranking must not
/// turn one un-inferred value into a second diagnostic
/// [fn-overload-rank].
fn ty_mentions_unknown(ty: &Ty) -> bool {
    match ty {
        Ty::Unknown => true,
        Ty::Named { args, .. } => args.iter().any(ty_mentions_unknown),
        Ty::Qualified { quals, base } => {
            ty_mentions_unknown(base)
                || quals.iter().any(|q| q.args.iter().any(ty_mentions_unknown))
        }
        Ty::Union(arms) => arms.iter().any(ty_mentions_unknown),
        Ty::Tuple(elems) => elems.iter().any(ty_mentions_unknown),
        Ty::Array(elem) => ty_mentions_unknown(elem),
        Ty::Fn { params, ret, .. } => {
            params.iter().any(ty_mentions_unknown) || ty_mentions_unknown(ret)
        }
        _ => false,
    }
}

/// [implicit-infer] Like [`substitute_vars`], but a variable the
/// substitution does not mention stays a **variable** instead of becoming
/// `Unknown` — which is what lets a partially known pattern still bind
/// something (`(List<Int>) -> Iter<T>` teaches `T`; `(?) -> ?` teaches
/// nothing).
fn substitute_known(ty: &Ty, subst: &HashMap<String, Ty>, callee_generics: &HashSet<String>) -> Ty {
    match ty {
        Ty::Var(g) if callee_generics.contains(g) => {
            subst.get(g).cloned().unwrap_or_else(|| ty.clone())
        }
        Ty::Named { name, args } => Ty::Named {
            name: name.clone(),
            args: args
                .iter()
                .map(|a| substitute_known(a, subst, callee_generics))
                .collect(),
        },
        Ty::Qualified { quals, base } => {
            let new_base = substitute_known(base, subst, callee_generics);
            new_base.qualify(
                quals
                    .iter()
                    .map(|q| Qual {
                        effect: q.effect,
                        name: q.name.clone(),
                        args: q
                            .args
                            .iter()
                            .map(|a| substitute_known(a, subst, callee_generics))
                            .collect(),
                    })
                    .collect(),
            )
        }
        Ty::Union(arms) => Ty::union_of(
            arms.iter()
                .map(|a| substitute_known(a, subst, callee_generics))
                .collect(),
        ),
        Ty::Tuple(elems) => Ty::Tuple(
            elems
                .iter()
                .map(|e| substitute_known(e, subst, callee_generics))
                .collect(),
        ),
        Ty::Array(elem) => Ty::Array(Box::new(substitute_known(elem, subst, callee_generics))),
        Ty::Fn {
            params,
            ret,
            contract,
            effects,
        } => Ty::Fn {
            params: params
                .iter()
                .map(|p| substitute_known(p, subst, callee_generics))
                .collect(),
            ret: Box::new(substitute_known(ret, subst, callee_generics)),
            contract: contract.clone(),
            effects: effects.clone(),
        },
        other => other.clone(),
    }
}

/// [iter-step-call] Whether an argument of a step call is the same value on
/// every turn: a place (a variable or a field path) or a literal.
fn is_step_call_arg(e: &Expr) -> bool {
    match e {
        Expr::Ident(_) | Expr::Int { .. } | Expr::Float { .. } | Expr::Bool { .. } | Expr::Char { .. } => {
            true
        }
        Expr::Str { parts, .. } => parts.iter().all(|p| matches!(p, ast::StrExprPart::Text(_))),
        Expr::Field { base, .. } => is_step_call_arg(base),
        _ => false,
    }
}

/// [iter-protocol] The element type argument of a `: Next<self, T>` clause:
/// the second one, since the state comes first [group-obligation].
fn next_elem_arg(ob: &TypeRef) -> Option<&ast::Type> {
    ob.args.get(1)
}

/// [group-self] Whether an obligation's type argument is the `self`
/// shorthand — "the type this declaration is". Written at the *obligation*
/// rather than inside the group (user decision 2026-09-08), which is what
/// keeps a group ordinary: its members mention only their own parameters, so
/// one group serves both `: Group<self, …>` and `?Group<…>`.
///
/// Bare and unqualified: `Mut self` or `self<T>` is not the shorthand, and
/// falls through to the ordinary unknown-type error.
fn is_self_ref(ty: &ast::Type) -> bool {
    matches!(
        ty,
        ast::Type::Named { qualifiers, base }
            if qualifiers.is_empty() && base.args.is_empty() && base.name.name == "self"
    )
}

/// [group-obligation] Structural equality of two types up to a *bijective*
/// renaming of type variables — how an obligation's expected member
/// signature (whose variables are the struct's generics) is matched against
/// a candidate overload (whose variables are its own generics). Bijective,
/// so `(A, A)` does not match `(A, B)` in either direction.
fn tys_match_renamed(
    a: &Ty,
    b: &Ty,
    fwd: &mut HashMap<String, String>,
    rev: &mut HashMap<String, String>,
) -> bool {
    let all = |xs: &[Ty],
               ys: &[Ty],
               fwd: &mut HashMap<String, String>,
               rev: &mut HashMap<String, String>| {
        xs.len() == ys.len()
            && xs
                .iter()
                .zip(ys)
                .all(|(x, y)| tys_match_renamed(x, y, fwd, rev))
    };
    match (a, b) {
        (Ty::Var(x), Ty::Var(y)) => {
            let f = fwd.entry(x.clone()).or_insert_with(|| y.clone());
            let r = rev.entry(y.clone()).or_insert_with(|| x.clone());
            f == y && r == x
        }
        // [cmp-carry] An identity is not a variable: there is nothing to
        // rename, so two identities match only by being the same fn.
        (Ty::FnName(x), Ty::FnName(y)) => x == y,
        // [qual-depend] A place template matches by its *field*, not its
        // receiver's spelling: the Next clause writes `Idx(self.items)`
        // and the `next` writes `Idx(p.items)` — one slot, two vantage
        // points on the same pass.
        (Ty::ValueRef { path: xp, .. }, Ty::ValueRef { path: yp, .. }) => {
            let tail = |p: &str| p.split('.').next_back().map(str::to_string);
            tail(xp) == tail(yp)
        }
        (Ty::Named { name: na, args: aa }, Ty::Named { name: nb, args: ab }) => {
            na == nb && all(aa, ab, fwd, rev)
        }
        (
            Ty::Qualified {
                quals: qa,
                base: ba,
            },
            Ty::Qualified {
                quals: qb,
                base: bb,
            },
        ) => {
            qa.len() == qb.len()
                && qa.iter().zip(qb).all(|(x, y)| {
                    x.name == y.name && x.effect == y.effect && all(&x.args, &y.args, fwd, rev)
                })
                && tys_match_renamed(ba, bb, fwd, rev)
        }
        (Ty::Union(aa), Ty::Union(ab)) => all(aa, ab, fwd, rev),
        (Ty::Tuple(aa), Ty::Tuple(ab)) => all(aa, ab, fwd, rev),
        (Ty::Array(ea), Ty::Array(eb)) => tys_match_renamed(ea, eb, fwd, rev),
        (
            Ty::Fn {
                params: pa,
                ret: ra,
                ..
            },
            Ty::Fn {
                params: pb,
                ret: rb,
                ..
            },
        ) => all(pa, pb, fwd, rev) && tys_match_renamed(ra, rb, fwd, rev),
        (Ty::Any, Ty::Any) | (Ty::Never, Ty::Never) | (Ty::Unknown, Ty::Unknown) => true,
        _ => false,
    }
}

/// [cmp-carry] One **fn slot**, expanded: the name a signature's binder shares
/// with it, the fn type an identity must fit (over the *declaration's* own type
/// parameters), and the identity a use site that writes none gets.
///
/// A group spread in a slot list contributes one of these per member
/// (`?Ordered<T>` → `cmp`), which is why the list is built by the checker rather
/// than read off the AST: a group's members are only visible here.
#[derive(Clone, Debug)]
struct FnSlotInfo {
    name: String,
    ty: Ty,
}

/// [col-key-eligible] [cmp-carry] The four **keyed containers**, with how many
/// type arguments each takes and whether its keys are kept in order. One list,
/// read by the key-eligibility check and by the lowering that degrades a
/// not-yet-supported identity, so the two cannot disagree about what a keyed
/// container is.
fn keyed_container(name: &str) -> Option<(usize, bool)> {
    match name {
        "Set" => Some((1, false)),
        "Map" => Some((2, false)),
        "SortedSet" => Some((1, true)),
        "SortedMap" => Some((2, true)),
        _ => None,
    }
}

/// [cmp-carry] A **written type is a pattern for its slots**: an argument the
/// writer left out is *unconstrained*, so a `let` annotation that names a
/// qualifier without its identity keeps the identity the value carries —
/// `let live: Mut Sorted List<Int> = mut_sort(xs)` is still sorted by the `cmp`
/// the sort published, and `add_sorted(live, 20)` can capture it.
///
/// The same rule a *parameter* gets from `qual_present`'s wildcard match, applied
/// where a type is written for a local. Only unwritten positions are filled
/// (`Ty::Unknown`, which is what an unwritten slot or a padded type argument
/// lowers to), so a written identity that disagrees with the value still fails
/// the subtype check above — naming an ordering is how you demand it.
fn fill_unwritten_args(ann: &Ty, value: &Ty) -> Ty {
    match (ann, value) {
        (
            Ty::Qualified { quals, base },
            Ty::Qualified {
                quals: vq,
                base: vb,
            },
        ) => Ty::Qualified {
            quals: quals
                .iter()
                .map(|q| match vq.iter().find(|v| v.name == q.name) {
                    Some(v) => Qual {
                        args: fill_arg_list(&q.args, &v.args),
                        ..q.clone()
                    },
                    None => q.clone(),
                })
                .collect(),
            base: Box::new(fill_unwritten_args(base, vb)),
        },
        // A qualified annotation over an unqualified value cannot happen (the
        // subtype check would have failed), but the reverse does: the value
        // carries claims the annotation drops, and dropping is the point.
        (_, Ty::Qualified { base: vb, .. }) => fill_unwritten_args(ann, vb),
        (Ty::Named { name, args }, Ty::Named { name: vn, args: va }) if name == vn => Ty::Named {
            name: name.clone(),
            args: fill_arg_list(args, va),
        },
        _ => ann.clone(),
    }
}

/// One positional argument list against the value's: an `Unknown` takes the
/// value's, everything else is recursed into and kept.
fn fill_arg_list(ann: &[Ty], value: &[Ty]) -> Vec<Ty> {
    let mut out: Vec<Ty> = ann
        .iter()
        .enumerate()
        .map(|(i, a)| match (a, value.get(i)) {
            (Ty::Unknown, Some(v)) => v.clone(),
            (_, Some(v)) => fill_unwritten_args(a, v),
            (_, None) => a.clone(),
        })
        .collect();
    // An annotation may write fewer arguments than the value carries — the
    // trailing ones are unwritten, and so unconstrained.
    if value.len() > out.len() {
        out.extend(value[out.len()..].iter().cloned());
    }
    out
}

/// [cmp-carry] [implicit-group] Adds a slot to an expanded list, **merging** an
/// entry that asks for the same position at the same type: two groups naming one
/// member name it once, exactly as two implicit spreads do.
fn push_slot(out: &mut Vec<FnSlotInfo>, slot: FnSlotInfo) {
    // A clash at two *types* is reported by `slot_clashes`; keeping both here
    // would make the positions disagree with what the diagnostic said.
    if !out.iter().any(|s| s.name == slot.name) {
        out.push(slot);
    }
}

/// [cmp-carry] The fn names declared, unattached, by more than one non-std
/// module: the identities whose printed name needs its module to say which.
fn fn_name_clash(files: &[crate::source::SourceFile], resolution: &Resolution<'_>) -> HashSet<String> {
    let mut by_name: HashMap<&str, HashSet<String>> = HashMap::new();
    for (i, scope) in resolution.scopes.iter().enumerate() {
        if files.get(i).is_none_or(|f| f.is_std) {
            continue;
        }
        for (name, entries) in &scope.fns {
            for e in entries {
                if e.rung == crate::resolve::Rung::Own
                    && e.decl.scoped_to.is_none()
                    && !resolution.attached.contains_key(&e.key)
                {
                    by_name.entry(name).or_default().insert(e.module.to_string());
                }
            }
        }
    }
    by_name.into_iter().filter(|(_, ms)| ms.len() > 1).map(|(n, _)| n.to_string()).collect()
}

fn substitute_vars(ty: &Ty, subst: &HashMap<String, Ty>, callee_generics: &HashSet<String>) -> Ty {
    match ty {
        Ty::Var(g) if callee_generics.contains(g) => subst.get(g).cloned().unwrap_or(Ty::Unknown),
        // [cmp-carry] A binder is substituted by whatever the call site's
        // resolution bound it to — which is how `empty_heap` publishes the
        // ordering resolution chose (`-> Mut List<T> as Heap(?cmp)` becomes
        // `Heap(cmp@Person) Mut List<Person>` at the call). An *unbound*
        // binder stays itself rather than becoming `Unknown`: inside the
        // declaring signature `?cmp` is the honest reading, and the missing
        // binding is reported where implicits are resolved, once
        // [type-unknown-lenient].
        Ty::FnName(FnId::Binder(name)) => subst
            .get(&FnId::subst_key(name))
            .cloned()
            .unwrap_or_else(|| ty.clone()),
        Ty::Named { name, args } => Ty::Named {
            name: name.clone(),
            args: args
                .iter()
                .map(|a| substitute_vars(a, subst, callee_generics))
                .collect(),
        },
        Ty::Qualified { quals, base } => {
            // Re-normalize through `qualify`: the substituted base may
            // itself be qualified (e.g. `Ok T` with `T = Ok Str`).
            let new_base = substitute_vars(base, subst, callee_generics);
            new_base.qualify(
                quals
                    .iter()
                    .map(|q| Qual {
                        effect: q.effect,
                        name: q.name.clone(),
                        args: q
                            .args
                            .iter()
                            .map(|a| substitute_vars(a, subst, callee_generics))
                            .collect(),
                    })
                    .collect(),
            )
        }
        Ty::Union(arms) => Ty::union_of(
            arms.iter()
                .map(|a| substitute_vars(a, subst, callee_generics))
                .collect(),
        ),
        Ty::Tuple(elems) => Ty::Tuple(
            elems
                .iter()
                .map(|e| substitute_vars(e, subst, callee_generics))
                .collect(),
        ),
        Ty::Array(elem) => Ty::Array(Box::new(substitute_vars(elem, subst, callee_generics))),
        Ty::Fn {
            params,
            ret,
            contract,
            effects,
        } => Ty::Fn {
            params: params
                .iter()
                .map(|p| substitute_vars(p, subst, callee_generics))
                .collect(),
            contract: contract.clone(),
            effects: effects.clone(),
            ret: Box::new(substitute_vars(ret, subst, callee_generics)),
        },
        other => other.clone(),
    }
}

impl<'p, 'r> Checker<'p, 'r> {
    // ================= calls =================

    /// [fn-member-call] [fn-uniform] `x.name(args)`: a **member call** when
    /// `x`'s type has a member `name` — a struct's field, called through its
    /// value, or an `eff[E]`'s send member, a send to that instance — and
    /// otherwise a **uniform call**, the plain call `name(x, args)` exactly
    /// (user decision 2026-10-28, replacing R10 D14). `grouped` is the
    /// explicit member call `(x.name)(args)`, never a uniform call.
    /// `known_recv` is the receiver's type when the caller has it (`?.`'s
    /// narrowed first arm); otherwise it is peeked from a place, or found by
    /// checking the receiver when no function of the name exists. `callee`
    /// is the written `x.name` expression; `?.` has none, and passes the
    /// receiver's type instead, so nothing needs it.
    #[allow(clippy::too_many_arguments)]
    fn check_dot_call(
        &mut self,
        callee: Option<&'p Expr>,
        base: &'p Expr,
        field: &'p Ident,
        grouped: bool,
        known_recv: Option<Ty>,
        type_args: &'p [ast::Type],
        args: &'p [Expr],
        named: &'p [ast::NamedArg],
        expected: Option<&Ty>,
        span: Span,
    ) -> Ty {
        let name = field.name.as_str();
        let base_checked = known_recv.is_some();
        let recv = known_recv.or_else(|| self.peek_place_ty(base));
        if let Some(recv_ty) = &recv {
            if let Some(member) = self.dot_member(recv_ty, name) {
                // [fn-member-call] A member is the callee whenever there is one;
                // a function the uniform call would have reached is named, so
                // the reader learns which one they got.
                if !grouped && self.uniform_reaches(name, recv_ty) {
                    self.warn(field.span, messages::fn_member_call_shadows(&name, &Self::member_owner(recv_ty)));
                }
                return self.check_member_call(member, recv_ty, callee, base, field, base_checked, type_args, args, named, expected, span);
            }
        }
        if let (true, Some(callee)) = (grouped, callee) {
            // `(x.f)(args)` names a member: the field read reports one that
            // is not there.
            return self.check_value_call(callee, args, span);
        }
        // [actor-use-addr] An `eff[E]` without the member, and nothing a
        // uniform call could reach with it first: the mistake is the member's
        // name, so that is what is reported, not the argument mismatches of a
        // same-named function that takes something else.
        if let Some(recv_ty) = recv.as_ref().filter(|r| addr_effect(r).is_some()) {
            if !self.uniform_reaches(name, recv_ty) {
                if !base_checked {
                    self.check_expr(base, None);
                }
                for a in args {
                    self.check_expr(a, None);
                }
                let effect = addr_effect(recv_ty).map(|e| e.strip_quals().to_string()).unwrap_or_default();
                self.error_unresolved(
                    field.span,
                    messages::actor_use_addr_no_member(&Self::member_owner(recv_ty), &effect, &name),
                    name,
                );
                return Ty::Unknown;
            }
        }
        // [fn-uniform] The plain call `name(x, args)`: an enclosing implicit
        // or a fn-typed local of the name takes it first, as it takes
        // `name(x, args)` (R10 D12, D13).
        let key = self.key(span);
        self.out.dot_calls.insert(key);
        if let Some(ty) = self.check_name_call(field, Some(base), type_args, args, named, expected, span) {
            return ty;
        }
        let mut all_args: Vec<&'p Expr> = Vec::with_capacity(args.len() + 1);
        all_args.push(base);
        all_args.extend(args.iter());
        // [actor-mixed-handler] …and a handler's own `send fn` takes it as it
        // takes `name(x, args)`: the handler's members are in scope for the
        // uniform call (user decision 2026-10-28, B3.7 question 3 (a)).
        if let Some(ty) = self.check_servant_send(field, &all_args, span) {
            return ty;
        }
        if self.effect_members_here(name).is_some() || self.has_callable(name) {
            return self.resolve_named_call(name, field.span, type_args, &all_args, named, expected, None, span);
        }
        self.out.dot_calls.remove(&key);
        // Nothing of the name to call with the receiver first: a receiver
        // that is not a place may still have the member (`get(addrs, 0).bump(1)`,
        // `make().f(3)`), which only checking it can tell.
        if recv.is_none() {
            let recv_ty = self.check_expr(base, None);
            if let Some(member) = self.dot_member(&recv_ty, name) {
                return self.check_member_call(member, &recv_ty, callee, base, field, true, type_args, args, named, expected, span);
            }
        } else if !base_checked {
            self.check_expr(base, None);
        }
        for a in args {
            self.check_expr(a, None);
        }
        self.error_unresolved(field.span, messages::fn_uniform_unknown_fn(&name), name);
        Ty::Unknown
    }

    /// [fn-member-call] The member `name` of a receiver of type `recv`: an
    /// `eff[E]`'s send member (any member of E by that name — a member that is
    /// not a send is refused by the send itself), or a visible field of a
    /// struct.
    fn dot_member(&mut self, recv: &Ty, name: &str) -> Option<DotMember> {
        if let Some(effect) = addr_effect(recv) {
            let Ty::Named { name: ename, .. } = effect.strip_quals() else { return None };
            let decl = self.symbols.effects.get(ename.as_str()).copied()?;
            return (!crate::effect_members_named(decl, name).is_empty()).then_some(DotMember::Send(effect));
        }
        let Ty::Named { name: sname, .. } = recv.strip_quals() else { return None };
        if !self.symbols.structs.contains_key(sname.as_str()) || self.hidden_opaque(sname).is_some() {
            return None;
        }
        self.field_ty(recv, name).map(DotMember::Field)
    }

    /// How a diagnostic names the owner of a member: `eff[E]` for a send.
    fn member_owner(recv: &Ty) -> String {
        match addr_effect(recv) {
            Some(e) => format!("eff[{e}]"),
            None => recv.strip_quals().to_string(),
        }
    }

    /// [fn-member-call] Whether a uniform call `x.name(…)` would have reached
    /// something but for the member: a fn-typed local or implicit, a declared
    /// function or an available effect member of the name whose first
    /// parameter takes the receiver.
    fn uniform_reaches(&mut self, name: &str, recv: &Ty) -> bool {
        if let Some(var) = self.lookup(name) {
            if let Ty::Fn { params, .. } = var.narrowed.strip_quals() {
                return params.first().is_some_and(|p| Self::arg_fits_fn_value(recv, p));
            }
            return false;
        }
        let mut firsts: Vec<(&'p [Ident], &'p ast::Type)> = Vec::new();
        for e in self.overloads_of(name) {
            if let Some(p) = e.decl.params.iter().find(|p| !p.implicit && !p.variadic) {
                firsts.push((&e.decl.generics, &p.ty));
            }
        }
        for (_, f) in self.effect_members_here(name).unwrap_or_default() {
            if let Some(p) = f.params.iter().find(|p| !p.implicit && !p.variadic) {
                firsts.push((&f.generics, &p.ty));
            }
        }
        // Only the callee's own generics are inferred: a type variable of the
        // enclosing declaration, or an effect's (fixed by the instance in
        // scope), is rigid, so `eff[E]` does not take `eff[Watcher<E>]`.
        firsts.into_iter().any(|(generics, ty)| {
            let saved = self.enter_generics(generics);
            let pt = self.lower_type(ty);
            self.generics = saved;
            let mut subst = HashMap::new();
            unify(&pt, recv, &mut subst)
                && subst
                    .iter()
                    .all(|(k, v)| generics.iter().any(|g| g.name == *k) || *v == Ty::Var(k.clone()))
        })
    }

    /// [fn-member-call] A call through a member: a send for an `eff[E]`'s, a
    /// call through the field's value for a struct's. `base_checked`: the
    /// receiver was already checked (`?.`, or a receiver that is not a place).
    #[allow(clippy::too_many_arguments)]
    fn check_member_call(
        &mut self,
        member: DotMember,
        recv: &Ty,
        callee: Option<&'p Expr>,
        base: &'p Expr,
        field: &'p Ident,
        base_checked: bool,
        type_args: &'p [ast::Type],
        args: &'p [Expr],
        named: &'p [ast::NamedArg],
        expected: Option<&Ty>,
        span: Span,
    ) -> Ty {
        match member {
            DotMember::Send(effect) => {
                self.check_addr_call(&effect, base, base_checked, field, type_args, args, named, expected, span)
            }
            DotMember::Field(fty) => {
                if !matches!(fty.strip_quals(), Ty::Fn { .. }) && !fty.is_unknown() {
                    if !base_checked {
                        self.check_expr(base, None);
                    }
                    for a in args {
                        self.check_expr(a, None);
                    }
                    self.error(
                        field.span,
                        messages::fn_member_call_not_callable(&field.name, &recv.strip_quals(), &fty),
                    );
                    return Ty::Unknown;
                }
                self.out.field_calls.insert(self.key(span));
                if let (false, Some(callee)) = (base_checked, callee) {
                    return self.check_value_call(callee, args, span);
                }
                // The receiver was checked on its own, so the field read the
                // IR lowers as the callee is typed here.
                if let Some(callee) = callee {
                    self.out.expr_ty.insert(self.key(callee.span()), fty.clone());
                }
                self.record_field_ref(recv, field);
                self.check_fn_value_call(&fty, &format!("`{}`", field.name), args, span)
            }
        }
    }

    /// A call through a computed callee (`adder()(1)`, `(b.f)(3)`): the callee
    /// checked as a value, then the call through it.
    fn check_value_call(&mut self, callee: &'p Expr, args: &'p [Expr], span: Span) -> Ty {
        let cty = self.check_expr(callee, None);
        self.check_fn_value_call(&cty, "this function value", args, span)
    }

    /// [call-resolve] [fn-value] A call through a fn value of type `cty`,
    /// checked as a call through a local is (B1 census D19, 2026-10-27):
    /// before, each argument was only *typed* against its parameter, so a
    /// wrong argument or a wrong count passed the checker and rustc and
    /// kotlinc refused it.
    fn check_fn_value_call(&mut self, cty: &Ty, what: &str, args: &'p [Expr], span: Span) -> Ty {
        if let Ty::Fn { params, ret, contract, effects } = cty.strip_quals().clone() {
            // [fn-effects]
            self.check_fn_value_effects(&effects, span);
            let arg_refs: Vec<&'p Expr> = args.iter().collect();
            self.check_fn_value_args(what, &arg_refs, &params, contract.as_deref(), None, span);
            return *ret;
        }
        // [call-resolve] A known non-fn type is not callable.
        for a in args {
            self.check_expr(a, None);
        }
        if !cty.is_unknown() && !matches!(cty, Ty::Never) {
            self.error(span, messages::call_resolve_not_callable(&cty));
        }
        Ty::Unknown
    }

    /// [call-resolve] [fn-uniform] The part of a call by name that a local
    /// or an implicit of the enclosing fn answers: a plain call `f(args)`
    /// (`recv` is `None`), or a uniform call `x.f(args)`, which is the plain
    /// call `f(x, args)` exactly (`recv` is `x`; B3 piece 4, R10 D12, D13).
    /// `None` when neither takes the name: the caller resolves the
    /// declarations.
    #[allow(clippy::too_many_arguments)]
    fn check_name_call(
        &mut self,
        id: &'p Ident,
        recv: Option<&'p Expr>,
        type_args: &'p [ast::Type],
        args: &'p [Expr],
        named: &'p [ast::NamedArg],
        expected: Option<&Ty>,
        span: Span,
    ) -> Option<Ty> {
        let all: Vec<&'p Expr> = recv.into_iter().chain(args.iter()).collect();
        // [implicit-same-name] Two implicits of this name: the one the
        // call goes through is the local recorded for the emitters.
        let same = self.own_implicits.iter().filter(|p| p.name == id.name).count();
        let mut pre_tys: Option<Vec<Ty>> = None;
        let lname: String = if same > 1 {
            let tys: Vec<Ty> = all.iter().map(|a| self.check_expr(a, None)).collect();
            // [implicit-same-name] The one whose parameters the arguments
            // fit; among several, the most specific, ranked like overloads
            // (R10 D21), and a tie is the ordinary ambiguity.
            let fits = |p: &ImplicitParam| match p.ty.strip_quals() {
                Ty::Fn { params, .. } => {
                    params.len() == tys.len() && tys.iter().zip(params).all(|(a, p)| Self::arg_fits_fn_value(a, p))
                }
                _ => false,
            };
            let pick = match self.pick_own_implicit(&id.name, &fits) {
                Ok(p) => p,
                Err(tied) => {
                    self.own_implicit_tie(&id.name, &tied, span);
                    None
                }
            };
            let chosen = pick.map(|p| p.local).unwrap_or_else(|| id.name.clone());
            self.out.local_call_names.insert(self.key(span), chosen.clone());
            pre_tys = Some(tys);
            chosen
        } else {
            id.name.clone()
        };
        // [implicit-resolve-body] An **implicit** parameter of the
        // enclosing fn joins resolution by argument types (user decision
        // 2026-10-05, ROADMAP §0j 6i, option A): the call goes through the
        // implicit when its arguments fit it, and to the visible fns of
        // the name otherwise. Typed once, here; a call that falls through
        // hands the types on, so nothing is checked twice.
        let mut implicit_typed: Option<Vec<Ty>> = pre_tys.take();
        if let Some(var) = self.lookup(&lname) {
            let is_implicit = self
                .own_implicits
                .iter()
                .any(|p| p.name == id.name && spans_overlap(p.span, var.decl_span));
            if is_implicit
                && !self.overloads_of(&id.name).is_empty()
                && !all.iter().any(|a| matches!(**a, Expr::Lambda { .. } | Expr::Spread { .. }))
            {
                if let Ty::Fn { params, .. } = var.narrowed.strip_quals().clone() {
                    let tys: Vec<Ty> = match implicit_typed.take() {
                        Some(t) => t,
                        None => all.iter().map(|a| self.check_expr(a, None)).collect(),
                    };
                    let fits = tys.len() == params.len()
                        && tys.iter().zip(&params).all(|(a, p)| Self::arg_fits_fn_value(a, p));
                    if !fits {
                        self.pending_arg_tys = Some(tys);
                        return Some(self.resolve_named_call(
                            &id.name, id.span, type_args, &all, named, expected, None, span,
                        ));
                    }
                    implicit_typed = Some(tys);
                }
            }
        }
        // A local holding a callable (lambda parameter etc.).
        if let Some(var) = self.lookup(&lname) {
            let mut vty = var.narrowed.clone();
            // [flow-use-after-move] A callable called again (a `once`
            // fn [fn-once]) or after a move is the flow pass's use; a
            // `Never` one is called as declared.
            if matches!(vty, Ty::Never) {
                vty = var.declared.clone();
            }
            let once = vty.quals().iter().any(|q| q.name == "once");
            if let Ty::Fn {
                params,
                ret,
                contract,
                effects,
            } = vty.strip_quals().clone()
            {
                // [call-resolve] The callee is a *local* holding a
                // function, which outranks any same-named declaration —
                // an effect member included. Recorded for the emitters,
                // whose own effect-member test is a program-wide name
                // map that cannot see locals.
                self.out.local_calls.insert(self.key(span));
                // Calling the local is a use of it.
                if let Some(v) = self.lookup_mut(&lname) {
                    v.used = true;
                }
                // [fn-effects] The call supplies the value's effects.
                self.check_fn_value_effects(&effects, span);
                let typed = implicit_typed.take();
                let callee_name = format!("`{}`", id.name);
                self.check_fn_value_args(&callee_name, &all, &params, contract.as_deref(), typed, span);
                // [proj-readonly-return] [rs-loc] A fn value whose return is a
                // **wholesale** projection lends that argument outright
                // (`?at: (c: C, k: Int) -> ref(c) Mut T?`, or a plain
                // read-only `proj`): record it like any derived-return
                // call, so the result links to the argument [fate-link]
                // and the backends know which one it borrows. Both
                // projection flavours fate-link the same way, so this
                // asks "is this a borrow of a source" ([`Ty::is_proj`],
                // covers `proj` and `ref`), not the handle-specific
                // question. The type keeps no source names, so the
                // sources are the kept non-Copy arguments —
                // conservative in the same direction as the held case
                // below.
                let wholesale = ret.is_proj()
                    || matches!(ret.as_ref(), Ty::Union(arms)
                        if arms.iter().any(|a| a.is_proj()));
                if wholesale {
                    let mut sources: Vec<usize> = (0..params.len())
                        .filter(|&i| {
                            contract
                                .as_deref()
                                .and_then(|c| c.get(i))
                                .is_none_or(|e| e.kept)
                                && params
                                    .get(i)
                                    .is_some_and(|t| !crate::types::is_copy_scalar(t))
                        })
                        .collect();
                    // [ref-handle] A handle is a position in *one*
                    // container: the first one it is lent (the
                    // locator convention the IR and the backends read
                    // too), not the key it was found by.
                    if has_ref_arm(&ret) {
                        sources.retain(|&i| !params.get(i).is_some_and(|t| matches!(t.strip_quals(), Ty::Fn { .. })));
                        sources.truncate(1);
                    }
                    if !sources.is_empty() {
                        self.out.derived_calls.insert(self.key(span), sources);
                    }
                }
                // [proj-infer] A fn value has no body to read: its result
                // holds a borrow of the arguments its type declares
                // (`[p: proj]`), or conservatively of every kept one.
                if self.ty_holds_proj(&ret) {
                    let declared: Vec<usize> = contract
                        .as_deref()
                        .map(|c| {
                            c.iter()
                                .enumerate()
                                .filter(|(_, e)| e.lent)
                                .map(|(i, _)| i)
                                .collect()
                        })
                        .unwrap_or_default();
                    let lent: Vec<usize> = if !declared.is_empty() {
                        declared
                    } else {
                        (0..params.len())
                            .filter(|&i| {
                                contract
                                    .as_deref()
                                    .and_then(|c| c.get(i))
                                    .is_none_or(|e| e.kept)
                            })
                            .collect()
                    };
                    if !lent.is_empty() {
                        self.out.lending_calls.insert(self.key(span), lent);
                    }
                }
                // [fn-once] Calling a `once` fn consumes it: the IR flow
                // pass's move then enforces the multiplicity (second
                // call, loop back edge, branch merges).
                if once {
                    let links = self.lookup(&lname).map(|var| var.links.clone());
                    if let Some(links) = links {
                        let name = id.name.clone();
                        if links.is_empty() || self.note_derived_use(id.span, "call", &name, &links) {
                            // [flow-use-after-move] The IR has no read
                            // at a call of a local: the call is the move.
                            self.out.flow_moves.insert(self.key(span));
                        }
                    }
                }
                return Some(*ret);
            }
            // [call-resolve] The local's type is known and is not a
            // function, so this call can never succeed — including a
            // generic `T`, which is opaque (no bounds to make it
            // callable). Only an *un-inferred* type stays lenient
            // ([type-unknown-lenient]).
            for a in &all {
                self.check_expr(a, None);
            }
            if !vty.is_unknown() {
                let detail = if matches!(vty, Ty::Var(_)) {
                    // Adding a declaration cannot make a `T` callable:
                    // there are no bounds to say it is a function.
                    messages::call_resolve_type_param_call(&id.name, &vty)
                } else {
                    messages::call_resolve_not_callable_local(&id.name, &vty)
                };
                self.error(span, detail);
            }
            return Some(Ty::Unknown);
        }
        None
    }

    fn check_call(
        &mut self,
        callee: &'p Expr,
        type_args: &'p [ast::Type],
        args: &'p [Expr],
        named: &'p [ast::NamedArg],
        expected: Option<&Ty>,
        span: Span,
    ) -> Ty {
        // A dot call `base.f(args)` is a member call or a uniform call
        // [fn-member-call] [fn-uniform]; either way `f` must be declared —
        // reaching a target-language method means declaring it (in an effect
        // a `platform handler` implements), so an unknown name here is an
        // error, not interop pass-through [call-resolve].
        // [actor-self-send] `k@self(args)` — a message to the actor the
        // enclosing member belongs to. A selector, so it arrives as its own
        // callee shape rather than as a receiver that has to be told apart
        // from a value.
        if let Expr::SelfScoped { name, .. } = callee {
            return self.check_self_send(name, args, span);
        }
        if let Expr::Field { base, field, grouped, .. } = callee {
            let name = field.name.as_str();
            // [qual-whynot] `InRange.qualifies(n, 1, 65535)`: a qualifier's
            // own fn, called with the subject and the slot values.
            if let (Expr::Ident(q), false) = (&**base, *grouped) {
                if q.name.starts_with(|c: char| c.is_uppercase()) && self.scope.is_qualifier(&q.name) {
                    if let Some(decl) = self.qual_decl(&q.name) {
                        if let Some(f) = decl.fns.iter().find(|f| f.name.name == name) {
                            self.record_def_ref(q.span, &q.name);
                            return self.check_qual_member_call(decl, f, args, span);
                        }
                    }
                }
            }
            // [mod-namespace] A namespaced free-fn call `Outer.Inner.make(x)`: a
            // `Field` chain of uppercase namespace segments ending in a
            // lowercase fn name. It resolves to the flat key `Outer.Inner.make`
            // in scope — a direct call, *not* dot-notation, so the base
            // segments are a path and contribute no receiver argument.
            if !*grouped && field.name.chars().next().is_some_and(|c| c.is_lowercase()) {
                if let Some(ns) = namespace_path_of(base) {
                    let flat = format!("{ns}.{name}");
                    if self.has_callable(&flat) {
                        let arg_refs: Vec<&'p Expr> = args.iter().collect();
                        return self.resolve_named_call(
                            &flat, field.span, type_args, &arg_refs, named, expected, None, span,
                        );
                    }
                }
            }
            return self.check_dot_call(Some(callee), base, field, *grouped, None, type_args, args, named, expected, span);
        }

        // [effect-at] `close@Fs(s)` / `s.close@Fs()`: the *effect* whose
        // member is meant, written where two effects declare the same
        // member name [effect-member-overload]. It goes straight to that
        // effect's member — same-named fn overloads and locals do not
        // compete — and the call's type arguments keep their
        // [effect-disambiguation] meaning (they pin the instance:
        // `next_random@Random<Int>()`).
        if let Expr::EffectScoped {
            base, name, effect, ..
        } = callee
        {
            let mut all_args: Vec<&'p Expr> = Vec::with_capacity(args.len() + 1);
            if let Some(base) = base {
                all_args.push(base);
            }
            all_args.extend(args.iter());
            let Some(decl) = self.scope.effects.get(effect.name.as_str()).copied() else {
                // [fn-attached] The capitalized selector's *third* sibling: a
                // **type**, naming the canonical implementation of a capability
                // for it (`cmp@Person(a, b)`). Effects and types share the
                // capitalized namespace [name-casing] and one name cannot be
                // both in scope, so the reading is decided by what the name
                // declares — no new grammar, and [effect-at]/[fn-overload-at]
                // gain a sibling rather than a competitor.
                if self.names_a_type(&effect.name) && self.has_callable(&name.name) {
                    self.record_def_ref(effect.span, &effect.name);
                    return self.resolve_named_call(
                        &name.name,
                        name.span,
                        type_args,
                        &all_args,
                        named,
                        expected,
                        Some(Selector::Type(effect)),
                        span,
                    );
                }
                for a in &all_args {
                    self.check_expr(a, None);
                }
                self.error_unresolved(
                    effect.span,
                    messages::effect_at_unknown_effect(&effect.name),
                    &effect.name,
                );
                return Ty::Unknown;
            };
            self.record_def_ref(effect.span, &effect.name);
            // [effect-member-overload] Every member of that name: the
            // selector picks the *effect*, the argument types still pick the
            // overload.
            let members = crate::effect_members_named(decl, &name.name);
            if members.is_empty() {
                for a in &all_args {
                    self.check_expr(a, None);
                }
                self.error(name.span, messages::effect_at_no_member(&effect.name, &name.name));
                return Ty::Unknown;
            }
            self.record_def_ref(name.span, &name.name);
            // [effect-member-overload] The call's own selection, over that
            // effect's members alone.
            return self.resolve_named_call(
                &name.name,
                name.span,
                type_args,
                &all_args,
                named,
                expected,
                Some(Selector::Effect(decl)),
                span,
            );
        }

        // [fn-overload-at] `f@core.list(x)` / `xs.f@core.list(y)`: the module
        // whose overload is meant. Written *instead of* letting scope
        // precedence decide, so it goes straight to overload selection — a
        // local of the same name does not shadow it, which is what makes `@`
        // the way out of a shadowed name.
        if let Expr::Scoped {
            base, name, module, ..
        } = callee
        {
            let mut all_args: Vec<&'p Expr> = Vec::with_capacity(args.len() + 1);
            if let Some(base) = base {
                all_args.push(base);
            }
            all_args.extend(args.iter());
            if !self.has_callable(&name.name) {
                for a in &all_args {
                    self.check_expr(a, None);
                }
                self.error_unresolved(
                    name.span,
                    messages::call_resolve_unknown_fn(&name.name),
                    &name.name,
                );
                return Ty::Unknown;
            }
            // [fn-overload-at] What the bare name would reach without the
            // selector: both forms see locals and parameters (an implicit
            // included, whether or not the arguments fit it) and effect
            // members [fn-uniform]; a plain call also sees a handler's own
            // `send fn`, and the dot form a member of the receiver
            // [fn-member-call]. Any of them makes the selector meaningful, so
            // its warning is withheld.
            let plain = base.is_none();
            let servant_send = (self.facade_handler.is_some() || self.servant_reply_params.is_some())
                && self
                    .facade_handler
                    .or(self.own_handler)
                    .is_some_and(|h| h.fns.iter().any(|f| f.is_send && f.name.name == name.name));
            let receiver_member = match base {
                Some(b) => self.peek_place_ty(b).is_some_and(|t| self.dot_member(&t, &name.name).is_some()),
                None => false,
            };
            if self.lookup(&name.name).is_some()
                || (plain && servant_send)
                || receiver_member
                || self.effect_members_here(&name.name).is_some()
            {
                if let Some(s) = Selector::Module(module).module_span() {
                    self.at_needed.insert(s);
                }
            }
            return self.resolve_named_call(
                &name.name,
                name.span,
                type_args,
                &all_args,
                named,
                expected,
                Some(Selector::Module(module)),
                span,
            );
        }

        if let Expr::Ident(id) = callee {
            #[cfg(debug_assertions)]
            if self.lookup(&id.name).is_none() {
                self.check_value_members(id);
            }
            if let Some(ty) = self.check_name_call(id, None, type_args, args, named, expected, span) {
                return ty;
            }
            let arg_refs: Vec<&'p Expr> = args.iter().collect();
            // [actor-mixed-handler] Inside a mixed handler's member — sync or
            // send (user decision 2026-09-19) — a bare call naming one of
            // the handler's own `send fn` members is a send to the
            // servant — resolved before the general ladder (the handler's
            // members are the innermost declaration scope), after locals
            // (which shadow, as they shadow everything). A collision with
            // an available effect member is refused inside, naming `@self`.
            if let Some(ty) = self.check_servant_send(id, &arg_refs, span) {
                return ty;
            }
            return self.resolve_named_call(
                &id.name, id.span, type_args, &arg_refs, named, expected, None, span,
            );
        }

        // Computed callee (a `once`-typed temporary is called at most
        // once by construction [fn-once]).
        self.check_value_call(callee, args, span)
    }

    #[allow(clippy::too_many_arguments)]
    /// [qual-depend] The roots each fixed parameter's argument brings to a
    /// call: parameter name → the argument place's fate roots. Only place
    /// arguments contribute — a temporary has no identity a claim could be
    /// about.
    fn call_value_roots(
        &self,
        fixed: &[&'p ast::Param],
        args: &[&'p Expr],
    ) -> HashMap<String, Vec<u32>> {
        let mut out = HashMap::new();
        for (p, a) in fixed.iter().zip(args) {
            let Some(place) = Place::of_expr(a) else { continue };
            let Some(var) = self.lookup(&place.root) else { continue };
            let mut roots: Vec<u32> = var.links.iter().map(|l| l.root_id).collect();
            if roots.is_empty() {
                roots.push(var.id);
            }
            roots.sort_unstable();
            roots.dedup();
            out.insert(p.name.name.clone(), roots);
        }
        out
    }

    /// [qual-depend] Fills the root-free `ValueRef` templates of a
    /// signature type with the roots the call's arguments bring: the
    /// parameter type `KeyOf(map) K` becomes `KeyOf` of *this call's* map.
    fn substitute_value_refs(ty: &Ty, map: &HashMap<String, Vec<u32>>) -> Ty {
        match ty {
            Ty::ValueRef { path, roots } if roots.is_empty() => {
                let base = path.split('.').next().unwrap_or(path);
                match map.get(base) {
                    Some(r) => Ty::ValueRef {
                        path: path.clone(),
                        roots: r.clone(),
                    },
                    None => ty.clone(),
                }
            }
            Ty::Qualified { quals, base } => Ty::Qualified {
                quals: quals
                    .iter()
                    .map(|q| Qual {
                        effect: q.effect,
                        name: q.name.clone(),
                        args: q
                            .args
                            .iter()
                            .map(|a| Self::substitute_value_refs(a, map))
                            .collect(),
                    })
                    .collect(),
                base: Box::new(Self::substitute_value_refs(base, map)),
            },
            Ty::Named { name, args } => Ty::Named {
                name: name.clone(),
                args: args
                    .iter()
                    .map(|a| Self::substitute_value_refs(a, map))
                    .collect(),
            },
            Ty::Union(arms) => Ty::Union(
                arms.iter()
                    .map(|a| Self::substitute_value_refs(a, map))
                    .collect(),
            ),
            Ty::Tuple(elems) => Ty::Tuple(
                elems
                    .iter()
                    .map(|e| Self::substitute_value_refs(e, map))
                    .collect(),
            ),
            Ty::Array(elem) => Ty::Array(Box::new(Self::substitute_value_refs(elem, map))),
            other => other.clone(),
        }
    }

    /// Whether a type mentions a `ValueRef` anywhere — the cheap gate in
    /// front of the substitutions above.
    fn ty_has_value_ref(ty: &Ty) -> bool {
        match ty {
            Ty::ValueRef { .. } => true,
            Ty::Qualified { quals, base } => {
                quals.iter().any(|q| q.args.iter().any(Self::ty_has_value_ref))
                    || Self::ty_has_value_ref(base)
            }
            Ty::Named { args, .. } => args.iter().any(Self::ty_has_value_ref),
            Ty::Union(arms) => arms.iter().any(Self::ty_has_value_ref),
            Ty::Tuple(elems) => elems.iter().any(Self::ty_has_value_ref),
            Ty::Array(elem) => Self::ty_has_value_ref(elem),
            _ => false,
        }
    }

    /// [qual-depend] Whether an argument **positively carries** every
    /// dependent claim a (substituted) parameter pattern demands: same
    /// qualifier name, and root sets that agree. Unknown types satisfy
    /// everything else in resolution [type-unknown-lenient], but a claim
    /// can never be assumed — that is the whole point of one — so this
    /// check runs before unification's leniency can.
    fn dependent_demands_met(pattern: &Ty, arg: &Ty) -> bool {
        let demanded: Vec<&Qual> = pattern
            .quals()
            .iter()
            .filter(|q| {
                q.args
                    .iter()
                    .any(|a| Self::ty_has_value_ref(a) || matches!(a, Ty::Const(_)))
            })
            .collect();
        if demanded.is_empty() {
            return true;
        }
        demanded.iter().all(|want| {
            // [qual-const] A constant-slotted demand is met by carrying the
            // claim with exactly those constants.
            if want.args.iter().all(|x| matches!(x, Ty::Const(_))) {
                return arg
                    .quals()
                    .iter()
                    .any(|have| have.name == want.name && have.args == want.args);
            }
            let Some(want_roots) = want.args.iter().find_map(|x| match x {
                Ty::ValueRef { roots, .. } if !roots.is_empty() => Some(roots),
                _ => None,
            }) else {
                // The sibling brought no identity (a temporary): nothing
                // can satisfy a claim about it.
                return false;
            };
            arg.quals().iter().any(|have| {
                have.name == want.name
                    && have.args.iter().any(|x| match x {
                        Ty::ValueRef { roots, .. } => {
                            let mut a = roots.clone();
                            let mut b = want_roots.clone();
                            a.sort_unstable();
                            b.sort_unstable();
                            !a.is_empty() && a == b
                        }
                        _ => false,
                    })
            })
        })
    }

    /// [qual-depend] The fate roots of a driven pass's **source** — the
    /// value the pass borrows [proj-field]: a named pass's own links, or a
    /// minting call's lent arguments ([proj-infer], via `lending_calls`).
    fn pass_source_roots(&mut self, iterable: &'p Expr) -> Vec<u32> {
        let mut roots: Vec<u32> = Vec::new();
        if let Some(place) = Place::of_expr(iterable) {
            if let Some(var) = self.lookup(&place.root) {
                roots.extend(var.links.iter().map(|l| l.root_id));
                if roots.is_empty() {
                    roots.push(var.id);
                }
            }
        } else if let Expr::Call { args, span, .. } = iterable {
            let lent = self
                .out
                .lending_calls
                .get(&self.key(*span))
                .cloned()
                .unwrap_or_default();
            for i in lent {
                let Some(arg) = args.get(i) else { continue };
                let Some(place) = Place::of_expr(arg) else { continue };
                let Some(var) = self.lookup(&place.root) else { continue };
                let linked: Vec<u32> = var.links.iter().map(|l| l.root_id).collect();
                if linked.is_empty() {
                    roots.push(var.id);
                } else {
                    roots.extend(linked);
                }
            }
        }
        roots.sort_unstable();
        roots.dedup();
        roots
    }

    /// [qual-depend] Fills every root-free `ValueRef` in `ty` with `roots` —
    /// the element-type half of `substitute_value_refs`, where the roots
    /// come from the pass's source rather than a sibling argument.
    fn fill_value_ref_roots(ty: &Ty, roots: &[u32]) -> Ty {
        let mut map: HashMap<String, Vec<u32>> = HashMap::new();
        let mut collect = |t: &Ty| {
            fn go(t: &Ty, map: &mut HashMap<String, Vec<u32>>, roots: &[u32]) {
                match t {
                    Ty::ValueRef { path, roots: r } if r.is_empty() => {
                        let base = path.split('.').next().unwrap_or(path).to_string();
                        map.insert(base, roots.to_vec());
                    }
                    Ty::Qualified { quals, base } => {
                        for q in quals {
                            for a in &q.args {
                                go(a, map, roots);
                            }
                        }
                        go(base, map, roots);
                    }
                    Ty::Named { args, .. } => {
                        for a in args {
                            go(a, map, roots);
                        }
                    }
                    Ty::Union(arms) => {
                        for a in arms {
                            go(a, map, roots);
                        }
                    }
                    Ty::Tuple(elems) => {
                        for e in elems {
                            go(e, map, roots);
                        }
                    }
                    Ty::Array(elem) => go(elem, map, roots),
                    _ => {}
                }
            }
            go(t, &mut map, roots);
        };
        collect(ty);
        Self::substitute_value_refs(ty, &map)
    }

    /// [struct-opaque] The declaration of struct `key` when it is `opaque`
    /// and this file is outside its module — the declaring file and that
    /// module's `*.test.sv` annex see inside, nothing else does.
    fn hidden_opaque(&self, key: &str) -> Option<&'p StructDecl> {
        let decl: &'p StructDecl = self.symbols.structs.get(key).copied()?;
        if !decl.opaque {
            return None;
        }
        let module = self.symbols.key_modules.get(key)?;
        let here = &self.files[self.file_idx];
        if here.module == **module {
            return None;
        }
        // [test-file] The annex of module `m` is module `m.test`.
        if here.is_test
            && here.module.0.len() == module.0.len() + 1
            && here.module.0.last().is_some_and(|l| l == "test")
            && here.module.0[..module.0.len()] == module.0[..]
        {
            return None;
        }
        Some(decl)
    }

    /// [struct-opaque] Refuses `what` on a value of a struct type this file may
    /// not look inside, naming the type as opaque and pointing at its fns.
    /// True when refused.
    fn refuse_opaque(&mut self, ty: &Ty, what: &str, span: Span) -> bool {
        let Ty::Named { name, .. } = ty.strip_quals() else {
            return false;
        };
        let name = name.clone();
        let Some(decl) = self.hidden_opaque(&name) else {
            return false;
        };
        let declaring = self.symbols.key_modules.get(name.as_str()).copied();
        let module = declaring.map(|m| m.to_string()).unwrap_or_default();
        let shown = decl.name.name.clone();
        // Its functions: the fns of its module whose first parameter is it —
        // its module's own, as one of the module's files sees them (by written
        // name across the program, another module's fns about a type of the
        // same name were offered, PIPELINE.md C1).
        let home = declaring.and_then(|m| self.files.iter().position(|f| f.module == *m));
        let own: Vec<&'p FnDecl> = match (home, declaring) {
            (Some(fi), Some(m)) => self.resolution.scopes[fi]
                .fns
                .values()
                .flatten()
                .filter(|e| e.module == m)
                .map(|e| e.decl)
                .collect(),
            _ => Vec::new(),
        };
        let mut fns: Vec<String> = own
            .into_iter()
            .filter(|f| {
                f.params.first().is_some_and(|p| {
                    let base = match &p.ty {
                        ast::Type::Named { base, .. } => Some(&base.name.name),
                        ast::Type::QualifiedGroup { base, .. } => match base.as_ref() {
                            ast::Type::Named { base, .. } => Some(&base.name.name),
                            _ => None,
                        },
                        _ => None,
                    };
                    base.is_some_and(|b| *b == shown)
                })
            })
            .filter(|f| f.exported || f.scoped_to.is_some())
            .map(|f| format!("`{}`", f.name.name))
            .collect();
        fns.sort();
        fns.dedup();
        fns.truncate(8);
        let pointer = if fns.is_empty() {
            String::new()
        } else {
            format!(": use its functions ({})", fns.join(", "))
        };
        self.error(span, messages::struct_opaque_outside_module(&shown, &module, &what, &pointer));
        true
    }

    /// [call-resolve] Whether an argument of type `arg` fits a fn value's
    /// parameter `param`, by base shape (an unknown fits anything).
    fn arg_fits_fn_value(arg: &Ty, param: &Ty) -> bool {
        arg.is_unknown()
            || param.is_unknown()
            || matches!(arg, Ty::Never)
            || is_subtype(arg.strip_quals(), param.strip_quals())
    }

    /// [call-resolve] [fn-value] [fn-contract] The arguments of a call
    /// through a fn value — a fn-typed local or parameter, an implicit, or a
    /// computed callee (`adder()(1)`, `fs[0](x)`): each typed against its
    /// parameter (or taken from `typed`, when the caller already typed them),
    /// then the fit, the count, and the value's contract. `callee` names it
    /// in a diagnostic (`` `f` ``, "this function value").
    fn check_fn_value_args(
        &mut self,
        callee: &str,
        args: &[&'p Expr],
        params: &[Ty],
        contract: Option<&[FnParamContract]>,
        typed: Option<Vec<Ty>>,
        span: Span,
    ) {
        // [qual-depend] A parameter's claim about another parameter
        // (`(xs: List<Int>, i: Idx(xs) Int) -> …`) is about *this call's*
        // argument there, as at a declared call (`call_value_roots`): the
        // names come from the fn type's contract.
        let mut roots_by_name: HashMap<String, Vec<u32>> = HashMap::new();
        for (i, a) in args.iter().enumerate() {
            let Some(name) = contract.and_then(|c| c.get(i)).and_then(|e| e.name.clone()) else { continue };
            let Some(place) = Place::of_expr(a) else { continue };
            let Some(var) = self.lookup(&place.root) else { continue };
            let mut roots: Vec<u32> = var.links.iter().map(|l| l.root_id).collect();
            if roots.is_empty() {
                roots.push(var.id);
            }
            roots.sort_unstable();
            roots.dedup();
            roots_by_name.insert(name, roots);
        }
        for (i, a) in args.iter().enumerate() {
            let aty = match &typed {
                Some(tys) => tys[i].clone(),
                None => self.check_expr(a, params.get(i)),
            };
            let Some(p) = params.get(i) else { continue };
            if matches!(a, Expr::Spread { .. }) {
                continue;
            }
            // [call-resolve] A call through a fn value goes through that
            // value, so an argument that does not fit it is an error here
            // (accepted unchecked until 2026-10-05, and the target compiler
            // refused it).
            if !Self::arg_fits_fn_value(&aty, p) {
                self.error(
                    a.span(),
                    messages::call_resolve_fn_value_arg_mismatch(&callee, &p, &aty),
                );
                continue;
            }
            // [call-resolve] The base fits; the claims the parameter demands
            // must hold too, as at a declared call (B1 census D20,
            // 2026-10-27: `f(ys)` with `f: (xs: NonEmpty List<Int>) -> Int`
            // took an empty list). What a `Mut`, a projection or `once`
            // demands stays the contract's business.
            let kept = contract.and_then(|c| c.get(i)).is_none_or(|e| e.kept);
            let claimed = Self::substitute_value_refs(p, &roots_by_name);
            if !self.fn_value_claims_fit(&aty, &claimed, kept) {
                self.error(
                    a.span(),
                    messages::call_resolve_fn_value_claim_mismatch(&callee, &p, &aty),
                );
            }
        }
        if args.len() != params.len() && !args.iter().any(|a| matches!(a, Expr::Spread { .. })) {
            self.error(
                span,
                messages::call_resolve_fn_value_arg_count(&callee, &params.len(), &args.len()),
            );
        }
        // [fn-contract] Apply the fn value's contract to the arguments
        // (default: keeps everything).
        self.apply_fn_value_contract(args, params, contract, span);
    }

    /// [call-resolve] Whether an argument whose base already fits a fn
    /// value's parameter carries the parameter's claims: the declared-call
    /// fit (`arg_fits_param`), with the qualifiers the contract judges — `Mut`,
    /// `proj`/`ref`, `once`, and effect claims — set aside on both sides.
    fn fn_value_claims_fit(&self, arg: &Ty, param: &Ty, kept: bool) -> bool {
        if arg.is_unknown() || param.is_unknown() || matches!(arg, Ty::Never) || self.arg_fits_param(arg, param, kept) {
            return true;
        }
        fn modeless(t: &Ty) -> Ty {
            match t {
                Ty::Qualified { quals, base } => {
                    let keep: Vec<Qual> = quals
                        .iter()
                        .filter(|q| !q.effect && !matches!(q.name.as_str(), "Mut" | "once") && !crate::types::is_proj_name(&q.name))
                        .cloned()
                        .collect();
                    let base = modeless(base);
                    if keep.is_empty() { base } else { base.qualify(keep) }
                }
                other => other.clone(),
            }
        }
        let (a, p) = (modeless(arg), modeless(param));
        is_subtype(&a, &p) || self.arg_fits_param(&a, &p, true)
    }

    /// [fn-overload] [fn-overload-rank] The call's selection, over any
    /// candidate set (PIPELINE.md B3.7: a call by name, and every send and
    /// mint target, choose by this one rule): the arguments typed once, the
    /// lead candidate's parameter types flowing into them; every candidate
    /// fitted by arity with defaults and named arguments, the fit test and
    /// its contract; [implicit-fit]; then `select_overload`. Answers the
    /// winner and the argument types, or `None` once the refusal is
    /// reported. `pre_typed`: arguments the caller already typed.
    #[allow(clippy::too_many_arguments)]
    fn select_among(
        &mut self,
        name: &str,
        candidates: &[CallCand<'p>],
        type_args: &'p [ast::Type],
        args: &[&'p Expr],
        named: &'p [ast::NamedArg],
        expected: Option<&Ty>,
        at: Option<Selector<'p>>,
        pre_typed: Option<Vec<Ty>>,
        span: Span,
    ) -> Option<(Viable<'p>, Vec<Ty>)> {
        // Type the arguments once, then match candidates against them.
        // The **lead** candidate's parameter types flow into the arguments
        // as expected types — which is what lets lambda literals infer
        // their parameter types and inherit fn-type contracts
        // [fn-contract].
        //
        // [fn-overload-rank] The lead is the single candidate, or — when
        // a name is overloaded — the most specific of those still compatible
        // with the arguments typed *so far*. Both halves matter: specificity
        // picks the candidate the ranking will pick anyway (so a bare lambda
        // has an expected type even for an overloaded name, which is what
        // std's `map(xs, n -> n * 2)` needs once a `List` fast path joins the
        // generic overload), and re-narrowing per argument is what keeps the
        // *subject* deciding — `map(arr, n -> n + 1)` drops the `List`
        // candidate when `arr` turns out to be an array, before the lambda
        // is typed against it.
        //
        // Expected types are only a hint: the scoring loop below re-derives
        // everything from the argument types it ends up with.
        //
        // [call-generic-progressive] Within the lead, its type variables bind
        // *progressively*, left to right: each argument's expected type is
        // the parameter pattern with everything the earlier arguments (and
        // any explicit type arguments) already determined substituted in.
        // Without this an un-annotated lambda would be checked against a
        // pattern still mentioning `T` — its inferred type would then
        // *contain the callee's own variable*, which is exactly what
        // `unify`'s deliberate lack of an occurs check assumes cannot
        // happen [fn-overload], so the call would fail to match itself
        // (`map(xs.iter(), n -> n * 2)` reported as
        // `map(Iter<Int>, (T) -> T)`). The same progressive rule effect
        // member generics already use [effect-member-generics].
        // A call that arrives with its arguments typed (through an implicit
        // of its name, an operator, a `for`) has no lead: typing them again
        // would report every mistake twice.
        let mut pool: Vec<LeadCandidate> = if pre_typed.is_some() {
            Vec::new()
        } else {
            self.lead_pool(&candidates, args.len(), type_args)
        };
        let typed_already = pre_typed.is_some();
        let mut arg_tys: Vec<Ty> = pre_typed.unwrap_or_else(|| Vec::with_capacity(args.len()));
        for (i, a) in args.iter().enumerate() {
            if typed_already {
                break;
            }
            let lead = Self::dominant_lead(&pool);
            let exp: Option<Ty> = match lead {
                Some(pi) => {
                    // [implicit-infer] What the *implicit* parameters
                    // determine counts as progress too, and it has to happen
                    // between the arguments: `map(xs, n -> n * 2)` learns `T`
                    // from resolving `iter` at `(It) -> Iter<T>` with `It`
                    // already bound by `xs`, and without it the lambda is
                    // typed against an unbound `T`.
                    let key = candidates[pool[pi].index].key();
                    let mut subst = std::mem::take(&mut pool[pi].subst);
                    let generics = pool[pi].generics.clone();
                    self.extend_subst_from_implicits(key, &generics, &mut subst, named);
                    pool[pi].subst = subst;
                    pool[pi]
                        .rank
                        .patterns
                        .get(i)
                        .map(|p| substitute_vars(p, &pool[pi].subst, &pool[pi].generics))
                }
                None => None,
            };
            let lead_generics: HashSet<String> = match lead {
                Some(pi) => pool[pi].generics.clone(),
                None => HashSet::new(),
            };
            // Only lambda literals benefit; other expressions keep
            // the historical untyped probe (expected types can
            // trigger coercion recording).
            let ty = match a {
                // [fn-overload-rank] [type-unknown-lenient] No candidate leads
                // (overloads none of which is more specific), and the lambda
                // leaves a parameter type unwritten: the candidates' common
                // type at this position types it; when they differ nothing
                // does, and the lambda is refused rather than typed `Unknown`
                // and the first overload taken — which was checker-clean and
                // refused by both target compilers (found 2026-10-27 beside
                // B1 census D16).
                Expr::Lambda { params, .. }
                    if exp.is_none() && pool.len() > 1 && params.iter().any(|p| p.ty.is_none()) =>
                {
                    let at: Vec<Ty> = pool
                        .iter()
                        .filter_map(|c| c.rank.patterns.get(i).map(|p| substitute_vars(p, &c.subst, &c.generics)))
                        .collect();
                    let agreed = at.first().filter(|t| {
                        at.iter().all(|u| u == *t) && !ty_mentions_unknown(t) && !crate::types::mentions_var(t)
                    });
                    match agreed.cloned() {
                        Some(t) => self.check_expr(a, Some(&t)),
                        None => {
                            let mut shown: Vec<String> = at.iter().map(|t| format!("`{t}`")).collect();
                            shown.sort();
                            shown.dedup();
                            let why = if shown.len() == 1 {
                                format!("type this position by a type parameter ({}) that nothing has bound yet", shown[0])
                            } else {
                                format!("take different types at this position ({}) and none is more specific", shown.join(", "))
                            };
                            self.error(
                                a.span(),
                                messages::fn_overload_rank_lambda_untyped(&name, &why),
                            );
                            self.check_expr(a, None)
                        }
                    }
                }
                Expr::Lambda { .. } => self.check_expr(a, exp.as_ref()),
                // [call-type-args] A *concrete* parameter type flows
                // into a nested call, so that call can infer its own
                // type arguments from where its result is going
                // (`takes_ints(Mut List())`). A pattern still
                // mentioning the callee's generics must not: coercion
                // would be recorded against an unsubstituted `T`.
                Expr::Call { .. } => {
                    // An **unbound** variable substitutes to `Unknown`, so a
                    // pattern that still mentions one arrives here looking
                    // concrete (`List<T>` as `List<Unknown>`) — and handing
                    // that in made the argument adopt `Unknown` and discard
                    // what it could infer, which is why `to_set(List(1, 2))`
                    // could not infer `T` (fixed 2026-09-25).
                    let concrete = exp.filter(|t| {
                        !ty_mentions_vars(t, &lead_generics) && !ty_mentions_unknown(t)
                    });
                    self.check_expr(a, concrete.as_ref())
                }
                // [struct-literal-arg] The callee's own declared parameter
                // type, substituted by what earlier arguments (the
                // receiver, most often — `list.add(Arg { ... })` already
                // knows `T` from `list`'s own `List<Arg<Int>>`) already
                // bound, flows into a literal argument's missing type
                // arguments the same way it flows into a nested call
                // [call-type-args] — so a literal needs no written `<T>`
                // and no field to infer one from when the call itself
                // already supplies it unambiguously. Filtered the same
                // way: a pattern still mentioning the callee's own unbound
                // generics must not reach the literal as a concrete-looking
                // `Unknown`.
                Expr::StructLit { .. } => {
                    let concrete = exp.filter(|t| {
                        !ty_mentions_vars(t, &lead_generics) && !ty_mentions_unknown(t)
                    });
                    self.check_expr(a, concrete.as_ref())
                }
                // [fn-effects] A *named fn* passed by value needs the
                // expected fn type too: what the position expects it to
                // accept decides the value's shape (a pure fn passed
                // where effects are expected still takes them).
                // [effect-member-overload] …and so does an available effect's
                // member passed by name (R10 D3, PIPELINE.md B3.6).
                Expr::Ident(id)
                    if self.lookup(&id.name).is_none()
                        && (self.scope.fns.contains_key(id.name.as_str())
                            || !self.available_members(&id.name).is_empty()) =>
                {
                    self.check_expr(a, exp.as_ref())
                }
                // [fn-value-select] [fn-overload-at] …and so does one named
                // with `@` (`apply(tag@main, 1)`): without the expected type a
                // generic `tag<T>` stayed `(T) -> Str` and the call found no
                // overload (found 2026-10-14).
                Expr::Scoped { base: None, name, .. } if self.scope.fns.contains_key(name.name.as_str()) => {
                    self.check_expr(a, exp.as_ref())
                }
                Expr::EffectScoped { base: None, name, effect, .. }
                    if (self.names_a_type(&effect.name) && self.scope.fns.contains_key(name.name.as_str()))
                        || self.scope.effects.contains_key(effect.name.as_str()) =>
                {
                    // [effect-at] `m@E` passed as an argument is a member
                    // value at the parameter's fn type (R10 D3; found with
                    // B3.6: it was typed with no expected type and refused).
                    self.check_expr(a, exp.as_ref())
                }
                // [type-lit-adopt] A numeric literal adopts the numeric type its
                // *parameter* expects — the rule's own `f(1)` into a `Long`
                // parameter, which until 2026-09-18 only worked for annotated
                // `let`s and struct fields, so `millis(500)` was refused with
                // "no matching overload for `millis(Int)`" and every call in
                // std's new time surface would have needed `500L`.
                //
                // Read off the *candidates* rather than the lead, so adoption
                // stays a fallback and never re-ranks an overload set: an
                // exact `Int` (or `Double`) candidate at this position blocks
                // it, and the adopted type must be the only numeric one the
                // candidates name there. Generic patterns are not numeric, so
                // they neither block nor supply a target.
                Expr::Int { .. } | Expr::Float { .. } => {
                    let want = Self::adoptable_numeric_param(
                        &pool,
                        i,
                        matches!(a, Expr::Float { .. }),
                    );
                    self.check_expr(a, want.as_ref())
                }
                _ => self.check_expr(a, None),
            };
            // Extend each pool candidate's bindings with what this argument
            // determined, and drop the ones it rules out — the narrowing
            // that keeps the lead honest. A candidate that no longer fits is
            // not an error here: the scoring loop below reports the call as
            // a whole, against the *un-substituted* patterns.
            pool.retain_mut(|c| match c.rank.patterns.get(i) {
                Some(pattern) => {
                    let mut extended = c.subst.clone();
                    if unify(pattern, &ty, &mut extended) {
                        c.subst = extended;
                        true
                    } else {
                        false
                    }
                }
                None => true,
            });
            arg_tys.push(ty);
        }

        let mut viable: Vec<Viable<'p>> = Vec::new();

        let mut proj_blocked: Vec<(String, String, usize, ProjBlock)> = Vec::new();
        let mut consumed_blocked: Option<String> = None;
        for entry in candidates {
            let (key, decl) = (entry.key(), entry.decl());
            // [implicit-param] Implicits are never passed positionally, so
            // they take no part in arity or ranking.
            let fixed: Vec<&Param> = decl
                .params
                .iter()
                .filter(|p| !p.variadic && !p.implicit)
                .collect();
            let variadic = decl.params.iter().find(|p| p.variadic);
            // [fn-param-default] Positional args fill the leading parameters,
            // named args fill parameters by name, and any left over must have
            // a default. (Named args that match no fixed parameter may be
            // implicit overrides, resolved later; they are not rejected here.)
            let arity_ok = if variadic.is_some() {
                args.len() >= fixed.len()
            } else {
                Self::call_shape_fits(&fixed, false, args.len(), named)
            };
            if !arity_ok {
                continue;
            }
            // [fn-variadic] A `...spread` may only supply the **variadic
            // tail**: its length is not known statically, so it cannot stand in
            // for a required parameter. Before this rule (2026-09-23) a spread
            // in a fixed position unified the array with that parameter's type,
            // which silently bound a type parameter to the array —
            // `List(...xs)` built a `List<Int[]>` and claimed `NonEmpty` for
            // a possibly empty spread [backend-never-wrong].
            if args
                .iter()
                .take(fixed.len())
                .any(|a| matches!(a, Expr::Spread { .. }))
            {
                continue;
            }
            let saved = self.enter_cand_generics(entry);
            // Pattern types for each argument slot.
            let mut patterns: Vec<Ty> = Vec::with_capacity(args.len());
            for (i, _) in args.iter().enumerate() {
                if i < fixed.len() {
                    patterns.push(self.lower_type(&fixed[i].ty));
                } else if let Some(vp) = variadic {
                    let arr = self.lower_type(&vp.ty);
                    let elem = match (&arr, args[i]) {
                        // `...spread` passes the whole array along.
                        (_, Expr::Spread { .. }) => arr.clone(),
                        (Ty::Array(e), _) => (**e).clone(),
                        _ => arr.clone(),
                    };
                    patterns.push(elem);
                }
            }
            self.generics = saved;

            // [qual-depend] A dependent parameter type names sibling
            // parameters; fill its templates with the roots this call's
            // arguments bring, so `get(xs, i)` demands a claim about *xs* —
            // a claim about another list refuses, and the plain overload
            // takes the call.
            if patterns.iter().any(Self::ty_has_value_ref) {
                let vmap = self.call_value_roots(&fixed, args);
                for p in patterns.iter_mut() {
                    *p = Self::substitute_value_refs(p, &vmap);
                }
                // A dependent claim is never *assumed*: the argument must
                // positively carry it — an `Unknown` (mid-inference) or
                // plain argument falls to the unqualified overload, and a
                // sibling with no identity (a temporary) satisfies nothing.
                let met = patterns
                    .iter()
                    .zip(&arg_tys)
                    .all(|(p, a)| Self::dependent_demands_met(p, a));
                if !met {
                    continue;
                }
            }

            // [type-literal] A literal argument is typed without an expected
            // type (its base, `Str`); where this candidate's parameter lists
            // the literal, it is that literal for the fit.
            let lit_tys: Vec<Ty> = arg_tys
                .iter()
                .enumerate()
                .map(|(i, t)| {
                    patterns
                        .get(i)
                        .and_then(|p| expr_literal(args[i]).and_then(|l| adopt_literal(Some(p), l)))
                        .unwrap_or_else(|| t.clone())
                })
                .collect();
            let arg_tys = &lit_tys;
            // [effect-disambiguation] A member's effect generics start from its
            // instance (or the written type arguments), so an argument is
            // checked against the effect it will be sent to.
            let mut subst = match entry {
                CallCand::Member { .. } => self.cand_seed(entry, type_args),
                CallCand::Fn(_) | CallCand::Own { .. } => HashMap::new(),
            };
            let ok = patterns
                .iter()
                .zip(arg_tys)
                .all(|(p, a)| unify(p, a, &mut subst));
            if !ok {
                // [fn-kept-borrow] Remember when a fn argument's consumed
                // parameter is what kept it out: unify again with that
                // parameter kept, and see whether the position hands it a
                // borrow.
                if consumed_blocked.is_none() {
                    consumed_blocked = consumed_borrow_block(&patterns, arg_tys, args, &decl.generics);
                }
                continue;
            }
            let callee_generics: HashSet<String> = entry.generic_names();
            // Explicit type args pin the substitution.
            if let CallCand::Fn(_) = entry {
                for (g, ta) in decl.generics.iter().zip(type_args) {
                    let lowered = self.lower_type(ta);
                    subst.insert(g.name.clone(), lowered);
                }
            }
            let mut pairings = Vec::new();
            let mut assignable = true;
            // [proj-type] A kept, non-`Mut` position reads its argument, so a
            // *top-level* projection of the parameter type fits it (the
            // borrow of an owned value is a borrow); a consumed or `Mut`
            // position needs the owned value, and a projection *inside* the
            // type (a union arm, a type argument) must match exactly.
            let contract = self.effective_contract(key, decl);
            for (i, p) in patterns.iter().enumerate() {
                // [type-union-spread] The `...T` marker guides call-site union
                // matching (above); the assignability check sees the plain
                // union it stands for.
                let sp = substitute_vars(p, &subst, &callee_generics).strip_spread();
                let kept = contract
                    .as_ref()
                    .and_then(|c| {
                        let pname = fixed.get(i).map(|fp| fp.name.name.as_str());
                        c.iter()
                            .find(|d| Some(d.param.as_str()) == pname)
                            .map(|d| d.kept)
                    })
                    .unwrap_or(true);
                // [type-literal] A literal argument fits a parameter listing
                // it, though it was typed without one (its base, `Str`).
                let fits = self.arg_fits_param(&arg_tys[i], &sp, kept);
                if !fits {
                    // Remember when *only* the projection stood in the way,
                    // for the diagnostic below.
                    if is_subtype(&strip_all_proj(&arg_tys[i]), &strip_all_proj(&sp)) {
                        let pname = fixed
                            .get(i)
                            .map(|fp| fp.name.name.clone())
                            .unwrap_or_else(|| format!("argument {}", i + 1));
                        // `fits` already failed, so an arg landing in a kept
                        // `Mut` position here lacks what [`arg_fits_param`]
                        // requires: either it is not a `ref(c)` handle at
                        // all (`NotHandle` — a plain `proj`, including
                        // `proj Mut`, is read-only [ref-handle]), or it is a
                        // `ref` that itself does not carry `Mut`
                        // (`Mutates`, the original "read-only projection"
                        // case).
                        // [proj-opt-slot] A union is judged by its arms: a
                        // borrowed arm against the parameter's `Mut` one.
                        let union_arm_mut = kept && crate::types::has_borrowed_arm(&arg_tys[i])
                            && matches!(crate::types::spread_union_quals(&sp), Ty::Union(arms) if arms.iter().any(Self::carries_mut));
                        let union_arm_handle = matches!(crate::types::spread_union_quals(&arg_tys[i]), Ty::Union(arms) if arms.iter().filter(|a| a.is_proj()).all(|a| a.is_ref()));
                        let why = if union_arm_mut && !union_arm_handle {
                            ProjBlock::NotHandle
                        } else if kept && Self::carries_mut(&sp) && !arg_tys[i].is_ref() {
                            ProjBlock::NotHandle
                        } else if kept && Self::carries_mut(&sp) {
                            ProjBlock::Mutates
                        } else if arg_tys[i].is_proj() {
                            ProjBlock::Consumes
                        } else {
                            ProjBlock::Nested
                        };
                        proj_blocked.push((decl.name.name.clone(), pname, i, why));
                    }
                    assignable = false;
                    break;
                }
                pairings.push((i, sp));
            }
            if !assignable {
                continue;
            }
            // [fn-overload-rank] The slots a *variadic* parameter collected
            // are what make the arity shape matter: with everything else
            // equal, a fixed list wins.
            let collects_variadic = variadic.is_some() && args.len() >= fixed.len();
            viable.push(Viable {
                key,
                decl,
                subst,
                pairings,
                rank: crate::types::RankedCandidate {
                    patterns,
                    variadic: collects_variadic,
                },
                module: entry.origin(),
                template: entry.is_template(),
                effect: entry.effect(),
            });
        }

        // [implicit-fit] A candidate whose implicit parameters nothing here
        // can fill does not fit (user decision 2026-10-04): a generic
        // `count(it: Mut It, ?Next<It, T>)` fits any `Mut` argument by type,
        // and must not outrank — or block — an overload that really fits.
        // Only among several candidates: a lone one keeps its own, more
        // specific diagnostic about the implicit.
        let mut unfillable: Vec<(String, String)> = Vec::new();
        if candidates.len() > 1 && !viable.is_empty() {
            let mut kept = Vec::with_capacity(viable.len());
            for v in viable.drain(..) {
                match v.key.and_then(|k| self.unfillable_implicit(k, &v.decl.generics, &v.subst, named)) {
                    Some(missing) => unfillable.push((v.module.clone(), missing)),
                    None => kept.push(v),
                }
            }
            viable = kept;
        }

        if viable.is_empty() {
            let shown: Vec<String> = arg_tys.iter().map(|t| t.to_string()).collect();
            if let Some((module, missing)) = unfillable.first() {
                self.error(
                    span,
                    messages::implicit_fit_no_fill(&name, &shown.join(", "), &module, &missing),
                );
                return None;
            }
            if let Some(hint) = consumed_blocked {
                self.error(
                    span,
                    messages::call_resolve_no_overload_why(&name, &shown.join(", "), &hint),
                );
                return None;
            }
            // [proj-type] When a projection is all that stands between the
            // arguments and a candidate, say so — and say the remedy.
            if let Some((callee, pname, i, why)) = proj_blocked.first().cloned() {
                let arg_shown = arg_tys.get(i).map(|t| t.to_string()).unwrap_or_default();
                let what = match args.get(i) {
                    Some(Expr::Ident(id)) => format!("`{}`", id.name),
                    _ => "this argument".to_string(),
                };
                let msg = match why {
                    ProjBlock::Mutates => messages::ref_handle_read_only_projection(&what, &arg_shown, &callee, &pname),
                    ProjBlock::NotHandle => messages::ref_handle_plain_projection_mutated(
                        &what,
                        &arg_shown,
                        &callee,
                        &pname,
                    ),
                    ProjBlock::Consumes => messages::proj_type_projection_consumed(&what, &arg_shown, &callee, &pname),
                    ProjBlock::Nested => messages::proj_type_nested_borrow(&what, &arg_shown, &callee, &pname),
                };
                self.error(span, msg);
                return None;
            }
            // [fn-variadic] The most likely reason when the call spreads: a
            // spread fills the variadic tail and nothing else, so a callee with
            // required parameters cannot be reached this way.
            let spread_first = args
                .iter()
                .position(|a| matches!(a, Expr::Spread { .. }))
                .is_some_and(|at| {
                    candidates.iter().any(|c| {
                        c.decl()
                            .params
                            .iter()
                            .filter(|p| !p.variadic && !p.implicit)
                            .count()
                            > at
                    })
                });
            let hint = if spread_first {
                ": a `...spread` can only supply a variadic tail, never a \
                 required parameter — its length is not known here, so pass the \
                 leading arguments individually"
            } else {
                ""
            };
            self.error(span, messages::call_resolve_no_overload(&name, &shown.join(", "), &hint));
            return None;
        }
        let best_idx = self.select_overload(name, &viable, &arg_tys, at, expected, span)?;
        Some((viable.swap_remove(best_idx), arg_tys))
    }

    fn resolve_named_call(
        &mut self,
        name: &str,
        name_span: Span,
        type_args: &'p [ast::Type],
        args: &[&'p Expr],
        named: &'p [ast::NamedArg],
        expected: Option<&Ty>,
        // [fn-overload-at] [fn-attached] What was written after `@`, when the
        // call selects: a module, whose overloads alone compete, or a type,
        // whose canonicals alone do.
        at: Option<Selector<'p>>,
        span: Span,
    ) -> Ty {
        // Argument types computed while deciding *which* overload set a
        // colliding name belongs to [effect-available]: the fn path below
        // takes them as they are instead of typing the arguments twice.
        // [implicit-resolve-body] A call that fell through an implicit of its
        // name arrives with its arguments typed.
        let pre_typed: Option<Vec<Ty>> = self.pending_arg_tys.take();
        // [iter-for] Typed arguments with no expressions of their own.
        let typed_only = std::mem::take(&mut self.pending_typed_only);
        // 1. The candidates [fn-overload] [effect-member-overload]: the
        // visible fns of the name and the members of the available effects
        // declaring it, as **one set** ranked by one rule (R10 P4, PIPELINE.md
        // B3.5): a member competes with the fns and with the members of other
        // effects, and a tie is the ordinary ambiguity, whose remedies name
        // the place (`m@E(…)`, `m@module(…)`).
        //
        // [effect-available] A `@module` or `@Type` selector names
        // declarations, which a member never is, so it sees no members: that
        // is how a fn shadowed by a member is called by hand. `m@E(…)` names
        // that effect's members alone.
        let effect_sel = match at {
            Some(Selector::Effect(e)) => Some(e),
            _ => None,
        };
        let mut member_cands: Vec<CallCand<'p>> = Vec::new();
        if let Some(e) = effect_sel {
            for f in crate::effect_members_named(e, name) {
                if !self.shape_refused(f) {
                    member_cands.push(self.member_cand(e, f));
                }
            }
        } else if at.is_none() {
            if let Some(members) = self.effect_members_here(name) {
                // [effect-available] **Availability decides first**
                // (2026-09-14): a member call needs an instance, so only the
                // members of an effect with one in scope are candidates — a
                // name that is also an ordinary fn is that fn wherever no
                // handler is in scope. Without this rule std's `Fs` claimed
                // `close`, `write`, `read_line` and `position` program-wide.
                let mut owners: Vec<&'p ast::EffectDecl> = Vec::new();
                for (e, _) in &members {
                    if !owners.iter().any(|o| std::ptr::eq(*o, *e)) {
                        owners.push(e);
                    }
                }
                let available: Vec<&'p ast::EffectDecl> = owners
                    .iter()
                    .copied()
                    .filter(|e| {
                        let key = self.symbols.key_or(*e, &e.name.name);
                        self.effect_env.iter().any(|t| matches!(&t.ty, Ty::Named { name: n, .. } if *n == key))
                    })
                    .collect();
                let chosen: Vec<&'p ast::EffectDecl> = if !available.is_empty() {
                    available
                } else if !self.overloads_of(name).is_empty() {
                    Vec::new()
                } else if owners.len() == 1 {
                    // No fn of the name: the one effect's members, whose call
                    // then reports the missing handler (or the self-dispatch
                    // it would be inside a handler of that effect).
                    owners
                } else {
                    if pre_typed.is_none() {
                        for a in args {
                            self.check_expr(a, None);
                        }
                    }
                    let shown = owners.iter().map(|e| format!("`{}`", e.name.name)).collect::<Vec<_>>().join(", ");
                    self.error(span, messages::effect_available_member_no_handler(&name, &shown));
                    return Ty::Unknown;
                };
                for (e, f) in members {
                    if chosen.iter().any(|c| std::ptr::eq(*c, e)) && !self.shape_refused(f) {
                        member_cands.push(self.member_cand(e, f));
                    }
                }
            }
        }
        // [throw] `throw(m)` has no handler and no overloads to rank: the
        // delimiter is `try`, so its operation resolves through its own path.
        if let [CallCand::Member { effect, decl, .. }] = member_cands.as_slice() {
            if effect.name.name == THROW_EFFECT && (effect_sel.is_some() || self.overloads_of(name).is_empty()) {
                let (effect, decl) = (*effect, *decl);
                self.record_member_call(effect, decl, span);
                return self.check_throw_call(decl, args, pre_typed.as_deref(), span);
            }
        }

        // 2. Function overloads [fn-overload] (fn declarations, else
        // signatures).
        // [fn-rename] The overloads that still answer to this name — a
        // renamed one answers only to its new name — and, when the name *is*
        // a rename, exactly the overload it points at.
        let fn_entries: Vec<crate::resolve::FnEntry<'p>> =
            if effect_sel.is_some() { Vec::new() } else { self.overloads_of(name) };
        let candidates: Vec<CallCand<'p>> = fn_entries.into_iter().map(CallCand::Fn).chain(member_cands).collect();
        if self.renamed(name).is_some() {
            if at.is_some() {
                self.error(span, messages::fn_rename_at_on_renamed(&name));
            }
        }
        if candidates.is_empty() {
            // 3. Handler constructor.
            if pre_typed.is_none() {
                for a in args {
                    self.check_expr(a, None);
                }
            }
            if self.scope.handlers.contains_key(name) {
                // [handler-not-value] A handler instance is produced by
                // `use` and lives in the effect environment; it is not a
                // value the program can name, store, or pass. `use` never
                // reaches here (it validates its own constructor), so this
                // is always a handler *value* — which neither backend can
                // render (Rust emits `Name()` for a struct with no such
                // constructor, `E0423`).
                self.error(name_span, messages::handler_not_value_called(&name));
                return Ty::Unknown;
            }
            // Nothing declares this name [call-resolve]. Reaching a target
            // function means declaring it, so an
            // unresolved callee is an error rather than interop
            // pass-through (user decision 2026-09-03).
            self.error_unresolved(name_span, messages::call_resolve_unknown_fn(&name), name);
            return Ty::Unknown;
        }

        let Some((best, arg_tys)) =
            self.select_among(name, &candidates, type_args, args, named, expected, at, pre_typed, span)
        else {
            return Ty::Unknown;
        };
        let best = &best;
        // [effect-member-overload] A member won: the call is a dispatch
        // through its effect's instance.
        if let Some(effect) = best.effect {
            let (member, subst) = (best.decl, best.subst.clone());
            if self.for_site.is_none() {
                self.record_def_ref(name_span, name);
            }
            return self.finish_member_call(
                effect, member, subst, type_args, args, &arg_tys, named, expected, typed_only, span,
            );
        }
        if let Some(key) = best.key {
            self.out.call_fn.insert(self.key(span), key);
            // The callee name resolves to this declaration [fn-ref-table]. An
            // operator names nothing: its call is all there is [op-equality].
            if self.operator_site.is_none() && self.for_site.is_none() {
                self.out.fn_refs.insert(self.key(name_span), key);
            }
        }
        let callee_generics: HashSet<String> =
            best.decl.generics.iter().map(|g| g.name.clone()).collect();
        let subst = best.subst.clone();
        let decl = best.decl;
        let best_key = best.key;
        // [linear-defer] The escape check: in a mixed send member, a
        // reply parameter handed to any callee but the discharge (std's
        // `send`, whose first argument is the token being fulfilled) leaves
        // the activation and must be declared `defer`.
        if self.servant_reply_params.is_some() && !typed_only {
            let is_discharge = decl.name.name == "send" && decl.intrinsic;
            for (i, arg) in args.iter().enumerate() {
                if is_discharge && i == 0 {
                    continue;
                }
                self.reply_escape(arg, "passing it to a function");
            }
        }
        // Record argument coercions against the selected parameter types.
        for (i, pt) in best.pairings.clone().into_iter().filter(|_| !typed_only) {
            let logical = arg_tys[i].clone();
            let repr = self.repr_of(args[i], &logical);
            self.maybe_coerce(args[i].span(), &logical, &repr, &pt);
            // [type-none-unit] A generic slot the call inferred as `None`
            // takes the unit value, not an optional.
            self.note_none_unit(args[i], &pt);
        }
        // [linear-discard] `discard` is the obligation's **terminal**, and
        // it is legal only inside a *discharger* of the value's type — a fn
        // declared in the type's own file that consumes a parameter of it
        // (user decision 2026-09-12; before, discard refused linear values
        // outright and the designated `close` parameter was silently
        // exempt). Anywhere else, dropping a handle is precisely the leak
        // the obligation exists to prevent. Keyed on core's `intrinsic fn
        // discard` rather than on the bare name [platform-intrinsic-std-only].
        if best.decl.name.name == "discard" && best.decl.intrinsic && args.len() == 1 {
            let arg_ty = arg_tys[0].clone();
            if self.ty_own_linear(&arg_ty) {
                let allowed = match arg_ty.strip_quals() {
                    Ty::Named { name, .. } => self.own_discharges.contains(name.as_str()),
                    _ => false,
                };
                if !allowed {
                    let set = self.linear_discharge_hint(&arg_ty);
                    self.error(span, messages::linear_discard_linear(&arg_ty, &set));
                }
            }
        }
        // [iter-mut-param] The callback half of the rule: a callee that
        // **keeps** a fn-typed parameter calls it long after this call returns
        // — a composed pass calls it once per element, for as long as the pass
        // lives — so a lambda carrying mutable state into such a position is
        // the same hazard as a mutable parameter, reached through a capture
        // instead. Rust refuses it structurally (a stored callback arrives as
        // `impl Fn + 'static` [rs-fn-field], so neither a write nor a borrow of
        // outer mutable data compiles) while Kotlin runs it happily,
        // accumulating across passes: a checker-clean program only one backend
        // can build. Owned here rather than left to rustc.
        //
        // The trigger is the *deduction*, not the callee's shape: R5 removed the
        // producer factory, so "held past the call" is exactly "moved into the
        // callee" — which is what a composed combinator's `-> []` says.
        // [runtime-kept-fn] Except a runtime platform fn's kept callback: an
        // actor body *is* a callback with state of its own, called once per
        // activation, and the Rust lowering moves the captures in — so the
        // state is the body's, not shared with the caller.
        let runtime_kept = decl.platform && best_key.is_some_and(|k| self.runtime_files.get(self.resolution.decls.file(k)).copied().unwrap_or(false));
        // [platform-fn-value] Outside the runtime, a platform fn that keeps a
        // fn value (`=> !hook` on a fn-typed parameter) keeps a **named**
        // one: a top-level fn, so capture-free, and effect-free by its type —
        // the identity restriction [cmp-carry] has. The host may call it
        // from any thread, long after this call returns, which a closure's
        // captures could not survive on Rust and would race on Kotlin.
        if decl.platform && !runtime_kept && !typed_only {
            for (i, p) in decl.params.iter().enumerate() {
                if !matches!(p.ty, ast::Type::Fn { .. }) || !crate::check::platform_keeps_param(decl, p) {
                    continue;
                }
                let Some(arg) = args.get(i) else { continue };
                if self.out.fn_refs.contains_key(&self.key(arg.span())) {
                    continue;
                }
                self.error(
                    arg.span(),
                    messages::platform_fn_value_kept_callback(&decl.name.name, &p.name.name),
                );
            }
        }
        if !runtime_kept {
            let facts: Option<Vec<crate::deduce::ParamDeduction>> =
                self.effective_contract(best_key, decl);
            for (i, arg) in args.iter().enumerate() {
                if !matches!(arg, Expr::Lambda { .. }) {
                    continue;
                }
                let stored = decl.params.get(i).is_some_and(|p| {
                    matches!(p.ty, ast::Type::Fn { .. })
                        && facts
                            .as_ref()
                            .is_some_and(|fs| fs.iter().any(|d| d.param == p.name.name && !d.kept))
                });
                if !stored {
                    continue;
                }
                let Some(captures) = self.out.lambda_captures.get(&self.key(arg.span())) else {
                    continue;
                };
                let offenders: Vec<(String, bool)> = captures
                    .iter()
                    .filter(|c| c.mutable || c.mutated)
                    .map(|c| (c.name.clone(), c.mutated))
                    .collect();
                let param_name = decl
                    .params
                    .get(i)
                    .map(|p| p.name.name.clone())
                    .unwrap_or_else(|| format!("#{}", i + 1));
                for (captured, mutated) in offenders {
                    let what = if mutated {
                        "writes through"
                    } else {
                        "reads mutable data through"
                    };
                    self.error(
                        arg.span(),
                        messages::seq_lazy_mutable_capture(
                            &what,
                            &captured,
                            &param_name,
                            &decl.name.name,
                        ),
                    );
                }
            }
        }
        // [implicit-infer] A last round of learning, now that every argument is
        // typed. An implicit whose *result* determines a type variable —
        // `?iter: (c: C) -> [] Mut It`, where nothing but the chosen `iter`
        // says what `It` is — can only teach it once `C` is known, and `C` is
        // known only after the arguments. The rounds inside the loop above run
        // *between* arguments, so without this one a container-shaped
        // combinator could never infer its pass type.
        let mut subst = subst;
        // [implicit-infer] The **expected type** binds the callee's ordinary
        // type parameters before its implicits resolve, not only afterwards in
        // `settle_type_args`: an implicit is resolved against what the call
        // knows, and a *no-argument* constructor knows nothing else.
        // `let s: Mut Set<Str> = Mut Set()` has to learn `T = Str` from the
        // annotation, or `?Hashed<T>`'s members are looked for at
        // `(?, ?) -> Bool` and every `eq` in scope matches — an ambiguity the
        // program cannot fix (found 2026-09-25, giving the keyed containers
        // their capability).
        //
        // **Type parameters only.** A value slot the expectation happens to
        // name is deliberately *not* seeded: `[cmp-binder]` says what filled
        // the binder decides what a structure carries, so an annotation naming
        // a pair does not resolve one — the program passes `hash = …` /
        // `cmp = …`, which is the single way to choose an identity (user
        // decision 2026-09-26, preferring one way over two).
        if let Some(exp) = expected.filter(|e| !e.is_unknown() && **e != Ty::Never) {
            let saved = self.enter_generics(&decl.generics);
            let ret = self.fn_return_ty(decl);
            self.generics = saved;
            let mut from_expected: HashMap<String, Ty> = HashMap::new();
            if unify(&ret, exp, &mut from_expected) {
                for (g, ty) in from_expected {
                    if callee_generics.contains(&g) && !ty.is_unknown() && !subst.contains_key(&g) {
                        subst.insert(g, ty);
                    }
                }
            }
        }
        self.extend_subst_from_implicits(best_key, &callee_generics, &mut subst, named);
        // [proj-type] The pass the spread is filled from decides whether the
        // element is borrowed — before the `next` is looked for at that type.
        self.learn_next_elems(decl, &callee_generics, &mut subst);
        // [implicit-resolve] Fill the callee's implicit parameters, now that
        // its type arguments are known.
        // [fn-param-default] A named argument may fill an ordinary defaulted
        // parameter by name (`f(a, c = 3)`), not only an implicit. Type-check
        // each such value against its parameter here — so `expr_ty` is
        // populated for the IR builder, which reads the AST `named` the way
        // `struct_lit` reads a field's written value. The implicit filler is
        // told these names (`call_fixed_params`) so it does not reject them
        // as unknown implicits.
        let fixed_names: HashSet<String> = decl
            .params
            .iter()
            .filter(|p| !p.variadic && !p.implicit)
            .map(|p| p.name.name.clone())
            .collect();
        for a in named {
            if let Some(p) = decl
                .params
                .iter()
                .find(|p| !p.variadic && !p.implicit && p.name.name == a.name.name)
            {
                if p.default.is_none() {
                    self.error(
                        a.span,
                        messages::fn_param_default_named_without_default(&a.name.name),
                    );
                }
                let saved = self.enter_generics(&decl.generics);
                let expected = substitute_vars(&self.lower_type(&p.ty), &subst, &callee_generics).strip_spread();
                self.generics = saved;
                self.check_expr(&a.value, Some(&expected));
            }
        }
        self.call_fixed_params = fixed_names;
        // [col-key-eligible] The inferred half of the key rule: a call that
        // *builds* a keyed collection without the type being written
        // anywhere (`Set(1.5)`) has its key only in the resolved
        // substitution, so it is checked here rather than in
        // `validate_type`. Before the implicits are resolved, so a key refused
        // here silences its constructor's missing `hash`/`eq` (one mistake).
        if let Some(ret) = decl.return_type.as_ref() {
            if !subst.is_empty() {
                let lowered = self.lower_type_subst(ret, &subst, 0);
                // [col-sorted-list] A constructor's `as Q` lives beside the
                // return type, not in it, so `sort`'s `Sorted` claim would
                // be invisible here — and `sort(List(unorderable))` is
                // exactly the inferred case this block exists for.
                let lowered = match &decl.constructs {
                    Some(cref) => lowered.qualify(vec![crate::types::Qual {
                        effect: false,
                        name: cref.name.name.clone(),
                        args: Vec::new(),
                    }]),
                    None => lowered,
                };
                self.check_key_eligibility_ty(&lowered, span, 0);
            }
        }
        self.resolve_implicits(decl, best_key, &mut subst, &callee_generics, named, span);
        self.call_fixed_params = HashSet::new();
        // [linear-generics] An unconstrained generic parameter cannot be
        // instantiated with a linear type: generic code neither knows
        // nor honors the obligation. `discard` is the one blessed
        // generic (deliberately dropping is its purpose); `copy` refuses
        // with its own message (duplicating an obligation is
        // meaningless).
        let opted: HashSet<&str> = decl
            .generic_canbe
            .iter()
            .filter(|(_, q)| q.name.name == "linear")
            .map(|(id, _)| id.name.as_str())
            .collect();
        // Sorted, so which of several offending type arguments is
        // reported does not depend on hash order.
        let mut instantiations: Vec<(&String, &Ty)> = subst.iter().collect();
        instantiations.sort_by(|a, b| a.0.cmp(b.0));
        for (var_name, ty) in instantiations {
            if !callee_generics.contains(var_name) {
                continue;
            }
            if !self.ty_own_linear(ty) {
                continue;
            }
            // [linear-composite] The callee takes a bare `T` and puts
            // a `T` *inside* a composite — `add(list: Mut List<T>,
            // elem: T)` is the shape — so this call is the store, and
            // the opt-in does not help: no container can carry the
            // obligation yet. A signature that only *reads* a
            // composite of `T` (`size(list: List<T>) -> Int`) stores
            // nothing and stays legal.
            let takes_bare = decl
                .params
                .iter()
                .any(|p| !p.variadic && Self::type_is_bare_var(&p.ty, var_name));
            let stores = if takes_bare {
                decl.params
                    .iter()
                    .map(|p| &p.ty)
                    .chain(decl.return_type.as_ref())
                    .find(|t| self.var_in_composite(t, var_name))
                    .map(|t| format!("{t}"))
            } else {
                None
            };
            if let Some(composite) = stores {
                let linear = format!("{ty}");
                // A type-named constructor shows its readable type
                // (`Mut List`), not its canonical key (`Mut_List`).
                let shown = decl
                    .type_name
                    .as_ref()
                    .map(|t| format!("{t}"))
                    .unwrap_or_else(|| name.to_string());
                self.refuse_linear_composite(
                    span,
                    &linear,
                    format!(
                        "stored in the `{composite}` of `{shown}` (type argument \
                         `{var_name}`)"
                    ),
                );
                break;
            }
            // [linear-generics] `<T canbe linear>` admits linear
            // instantiation: the callee's body honors the obligation
            // (for an `intrinsic fn`, the backend's lowering does).
            if opted.contains(var_name.as_str()) {
                continue;
            }
            if decl.intrinsic && decl.name.name == "copy" {
                self.error(span, messages::linear_generics_copy_linear(&ty));
            } else {
                self.error(span, messages::linear_generics_not_opted(&var_name, &name, &ty));
            }
            break;
        }
        // [deduce-consume] Deduction lists are a contract, enforced
        // flow-sensitively on bare identifier arguments: parameters *not*
        // kept are consumed (moved) — the variable narrows to `Never`
        // and any later use is an error until it is reassigned. Kept
        // parameters shed their removal set — computed from the entry's
        // effect against the qualifiers the argument carries
        // [deduce-syntax] — so e.g.
        // `remove_first(list: NonEmpty Mut List<T>) -> [list: Mut]`
        // leaves the argument un-`NonEmpty` and a second call fails
        // overload resolution. Written lists are enforced directly;
        // unannotated fns are enforced through their signature contracts
        // (`self.inferred`), so `return list` in a callee consumes
        // the caller's argument just like an explicit `[]`.
        let contract: Option<Vec<crate::deduce::ParamDeduction>> = match &decl.deductions {
            // [iter-for] What a `for`'s call does to its subject is the
            // loop's own rule [iter-drive-in-place].
            _ if typed_only => None,
            // Shape errors on written lists are reported by the deduce
            // pass; the mapping here is silent.
            Some(_) => self.effective_contract(best.key, decl),
            None => best.key.and_then(|key| self.inferred.get(&key).cloned()),
        };
        // [fate-elem-distinct] Two mutable element handles of one container in
        // one call — `attack(at(es, i)!, at(es, j)!)`, or two bound
        // handles — are the two-`&mut` shape the Rust rendering cannot
        // express unless the elements are provably different. A pair of
        // bound handles a live `NotSame` claim proves apart is accepted
        // and recorded for the pair lowering [rs-elem-mut]; anything short
        // of the proof is refused here, naming the remedy. (Before this
        // rule the shape passed the checker and died at rustc — a
        // checker/emitter disagreement, closed 2026-09-24.)
        if let Some(contract) = &contract {
            let fixed_count = decl
                .params
                .iter()
                .filter(|p| !p.variadic && !p.implicit)
                .count();
            let mut_kept: Vec<bool> = args
                .iter()
                .enumerate()
                .map(|(i, _)| {
                    i < fixed_count
                        && decl.params.get(i).is_some_and(|param| {
                            contract
                                .iter()
                                .find(|d| d.param == param.name.name)
                                .is_some_and(|d| {
                                    d.kept
                                        && crate::deduce::declared_quals(&param.ty)
                                            .iter()
                                            .any(|q| q == "Mut")
                                })
                        })
                })
                .collect();
            // [ref-anchor] Which parameters are handles anchored at another.
            let anchors: Vec<Option<usize>> = decl
                .params
                .iter()
                .filter(|p| !p.implicit)
                .map(|p| {
                    let c = ref_anchor_of(&p.ty)?;
                    decl.params
                        .iter()
                        .filter(|q| !q.implicit)
                        .position(|q| q.name.name == c.name)
                })
                .collect();
            self.check_elem_handle_pairs(args, &mut_kept, &anchors, span);
        }
        if let Some(contract) = contract {
            let fixed_count = decl
                .params
                .iter()
                .filter(|p| !p.variadic && !p.implicit)
                .count();
            // [deduce-same-call] Arguments are evaluated left to right, and
            // a value an earlier argument of *this* call moved cannot be
            // mentioned by a later one: the IR reads a call's arguments in
            // order, so that is the flow pass's to report
            // [flow-use-after-move], from the moves recorded below.
            for (i, arg) in args.iter().enumerate() {
                if i >= fixed_count {
                    // [linear-generics] Variadic positions are untracked
                    // by the flow analysis, so a linear value passed
                    // there would leave its obligation unresolvable
                    // (physically moved, statically still owed).
                    let ty = self
                        .out
                        .ty_of(self.file_idx, arg.span())
                        .cloned()
                        .unwrap_or(Ty::Unknown);
                    if self.ty_own_linear(&ty) {
                        self.error(arg.span(), messages::linear_generics_variadic());
                    }
                    continue;
                }
                let param = &decl.params[i];
                let Some(d) = contract.iter().find(|d| d.param == param.name.name) else {
                    continue;
                };
                // [proj-anywhere] A constructor lending into a `proj` arm
                // keeps its argument: the caller receives a borrow of it,
                // so nothing is moved here. Only a real constructive
                // qualifier call (`-> T as Q`) lends — anything else keeps
                // its contract and the return check reports.
                let lends = self.lending_ctor == Some(span) && decl.constructs.is_some();
                let d = if lends {
                    &crate::deduce::ParamDeduction {
                        kept: true,
                        ..d.clone()
                    }
                } else {
                    d
                };
                let Expr::Ident(id) = arg else {
                    // A non-identifier argument in a *kept `Mut`* position
                    // lets the callee mutate through the projection: that
                    // is a mutation of the argument's provenance roots
                    // [fate-poison] — otherwise a Kotlin alias would
                    // observe the mutation while Rust's clone does not
                    // (backend-parity principle).
                    if d.kept
                        && crate::deduce::declared_quals(&param.ty)
                            .iter()
                            .any(|q| q == "Mut")
                    {
                        self.fate_mutation_through(arg, span);
                    } else if !d.kept {
                        // A projection in a *moved* position moves data
                        // out of its provenance roots [fate-move-mode];
                        // narrowings of that storage fall
                        // [flow-place-invalidate].
                        self.projection_move(arg, span);
                        if let Some(place) = Place::of_expr(arg) {
                            self.invalidate_place_narrows(&place);
                        }
                    }
                    continue;
                };
                // [fn-once] A `once` fn value escapes when passed as an
                // argument: fn-value ownership is otherwise untracked,
                // so the pass consumes it regardless of the callee's
                // contract (conservative; relaxable with fn-type
                // contracts).
                let arg_once = self
                    .lookup(&id.name)
                    .map(|v| v.narrowed.quals().iter().any(|q| q.name == "once"))
                    .unwrap_or(false);
                // [copy-scalar-free] Moving a Copy scalar is a copy, judged
                // by the argument's own type: std's `add(list, elem: T) =>
                // !elem` called with an `Int` leaves the `Int` usable.
                if !d.kept && !arg_once && self.moves_for_free_var(&id.name) {
                    continue;
                }
                if !d.kept || arg_once {
                    // Moved. A fate-linked (derived) variable cannot be
                    // moved [fate-derived-readonly]; moving a root
                    // poisons the variables derived from it
                    // [fate-poison].
                    let state = self.lookup(&id.name).map(|var| (var.id, var.links.clone()));
                    let Some((var_id, links)) = state else {
                        continue;
                    };
                    if !links.is_empty() {
                        let name = id.name.clone();
                        if !self.note_derived_use(id.span, "move", &name, &links) {
                            continue;
                        }
                    }
                    let name = id.name.clone();
                    // [effect-state-store] A member cannot move a value out
                    // of its handler's storage — the handler still owns it
                    // after the call returns.
                    if self.consume_of_handler_storage(&name, "move", id.span) {
                        continue;
                    }
                    // A lambda cannot consume a capture [fate-lambda].
                    if let Some(frame) = self.frame_of_id(var_id) {
                        if self.capture_move_violation(frame, &name, id.span) {
                            continue;
                        }
                    }
                    // A kept lambda parameter belongs to the caller
                    // [fn-contract].
                    if self.consume_kept_lambda_param(&name, id.span) {
                        continue;
                    }
                    self.note_linear_move(&name, id.span);
                    // [flow-use-after-move] The flow pass takes the move
                    // from here; see `apply_call_contract`.
                    self.out.flow_moves.insert(self.key(id.span));
                    continue;
                }
                // Kept. A parameter declared `Mut` gives the callee
                // mutation permission: mutating a derived variable is an
                // error, mutating a root poisons its derived variables
                // [fate-poison] [fate-derived-readonly], and every
                // narrowing of its parts falls
                // [flow-place-invalidate]. A kept *immutable* parameter
                // cannot mutate, so narrowings survive it (user decision
                // P1b).
                let declared_q = crate::deduce::declared_quals(&param.ty);
                if declared_q.iter().any(|q| q == "Mut") {
                    let name = id.name.clone();
                    // [qual-preserve] What this call keeps alive on other
                    // values depending on the argument: the qualifier
                    // owners' refinements for this (callee, parameter), plus
                    // the callee's own checked entries.
                    let have_now: Vec<String> = self
                        .lookup(&name)
                        .map(|v| v.narrowed.quals().iter().map(|q| q.name.clone()).collect())
                        .unwrap_or_default();
                    // [deduce-field] Which fields this callee says it
                    // mutates (`=> h.tags: Mut`, `=> !h.tags`).
                    // No written entry means mutated anywhere: the field set
                    // is the callee's interface, never read off its body
                    // (PIPELINE.md 4.3, 2026-10-20).
                    let decl_field_paths = Self::declared_mut_paths(decl, &param.name.name);
                    let preserved = self.preserved_claims(
                        best.key,
                        decl,
                        &param.name.name,
                        &have_now,
                    );
                    // [qual-preserve] The enclosing fn's own promise is
                    // checked here: every call passing the promised
                    // parameter at a `Mut` position must itself preserve
                    // the claim — conditional calls included, since the
                    // promise is unconditional.
                    if self.lookup(&name).is_some_and(|v| v.is_param) {
                        if let Some(owed) = self.own_preserve.get(&name).cloned() {
                            for q in owed {
                                if !preserved.contains(&q) {
                                    self.error(
                                        span,
                                        messages::qual_preserve_call_invalidates(&q, &name),
                                    );
                                }
                            }
                        }
                    }
                    // [deduce-field] The callee may have said *which* fields
                    // it mutates; then the event is those paths, not the
                    // whole variable.
                    match decl_field_paths {
                        Some(paths) if paths.iter().all(|(p, _)| !p.is_empty()) => self
                            .fate_mutation_fields_preserving(&name, span, &preserved, &paths),
                        _ => self.fate_mutation_root_preserving(&name, span, &preserved),
                    }
                }
                // [deduce-syntax] Computed against what the argument
                // actually carries: an exhaustive list drops qualifiers
                // this callee never declared.
                let have: Vec<String> = self
                    .lookup(&id.name)
                    .map(|v| v.narrowed.quals().iter().map(|q| q.name.clone()).collect())
                    .unwrap_or_default();
                let removed = d.effect.removal_set(&have, |q| self.survives_calls(q));
                let name = id.name.clone();
                if !removed.is_empty() {
                    if let Some(var) = self.lookup_mut(&name) {
                        var.narrowed = var.narrowed.clone().remove_quals(&removed);
                    }
                }
                // [qual-refn] Refinements have the last word: the callee's
                // own list said what *it* can promise, and a qualifier's
                // refinement says what the call does to *that qualifier's*
                // claim. Applied after the removal set, so `+NonEmpty`
                // re-establishes what `add`'s exhaustive `[list: Mut]`
                // necessarily dropped.
                if let Some(key) = best.key {
                    // [qual-refn-narrow] `have` is the argument's claim *before*
                    // this call, which is what a conditional refinement reads.
                    self.apply_refinements(
                        key,
                        &param.name.name,
                        &name,
                        &have,
                        span,
                    );
                    // [deduce-reapply] …and a claim the callee says it
                    // **establishes** is added here, with this call's type
                    // arguments and identities substituted in: that is what
                    // makes `heapify(list)` answer a `Heap<Int>(by_age)` when
                    // nothing about `list` claimed one before.
                    self.establish_quals(key, &param.name.name, &name, &subst, &callee_generics);
                }
                // [deduce-gained] A plain entry naming a qualifier the
                // parameter does not declare is a *checked* report that the
                // body leaves the value with it (`push` ends with the heap
                // non-empty, because `add` made it so and the sift only swaps).
                // The caller learns it here — the same place `+Q` lands, and
                // after it, so a re-established claim keeps its arguments.
                for q in self.plain_gains(decl, &param.name.name) {
                    let have: Vec<String> = self
                        .lookup(&name)
                        .map(|v| v.narrowed.quals().iter().map(|x| x.name.clone()).collect())
                        .unwrap_or_default();
                    if have.contains(&q) {
                        continue;
                    }
                    if let Some(var) = self.lookup_mut(&name) {
                        var.narrowed = var.narrowed.clone().qualify(vec![Qual {
                            effect: false,
                            name: q,
                            args: Vec::new(),
                        }]);
                    }
                }
            }
        }
        // [proj-readonly-return] Record derived-return calls: the result
        // borrows the annotated argument — the caller links the result
        // to it, and the Rust backend renders the result as a borrow.
        if decl.derived_return.is_some() && !typed_only {
            // Every source of the *first* wholesale `proj` in the return type
            // (`proj(a, b) T`: a projection joined across branches is
            // of both) [proj-anywhere].
            let sources: Vec<usize> = decl
                .return_type
                .as_ref()
                .map(|rt| {
                    proj_refs(rt)
                        .into_iter()
                        .find(|r| !r.from.is_empty())
                        .map(|r| {
                            r.from
                                .iter()
                                .filter_map(|f| {
                                    decl.params.iter().position(|p| p.name.name == f.name)
                                })
                                .collect()
                        })
                        .unwrap_or_default()
                })
                .unwrap_or_default();
            if !sources.is_empty() {
                // Whether a borrowed argument is a *temporary* (a call result
                // or literal, not a place): a view of one dies with the
                // statement, so it may be *used* there (`map(iter(List(1,
                // 2)), f)`) but not bound, returned or stored — those sites
                // consult this table.
                for &idx in &sources {
                    if let Some(arg) = args.get(idx).copied() {
                        if self.is_temporary(arg) {
                            self.out.temp_views.insert(self.key(span));
                        }
                    }
                }
                self.out.derived_calls.insert(self.key(span), sources);
            }
        }
        // [deduce-syntax] Re-pointing entries — `v.items: proj(other)`
        // or `v: proj(other)` — say the call makes the argument at `v`
        // hold a borrow of the argument at `other`: the variable passed as
        // `v` gains a held link to `other`'s roots. (The body is trusted for
        // these today; see ROADMAP.)
        if let Some(list) = decl.deductions.as_ref().filter(|_| !typed_only) {
            let repoints: Vec<(usize, Vec<usize>)> = list
                .iter()
                .filter_map(|d| match (&d.target, &d.kind) {
                    (ast::DeductionTarget::Param { name, .. }, ast::DeductionKind::Proj(srcs)) => {
                        let target = decl.params.iter().position(|p| p.name.name == name.name)?;
                        let sources: Vec<usize> = srcs
                            .iter()
                            .filter_map(|sname| {
                                decl.params.iter().position(|p| p.name.name == sname.name)
                            })
                            .collect();
                        Some((target, sources))
                    }
                    _ => None,
                })
                .collect();
            for (target, sources) in repoints {
                let Some(Expr::Ident(target_id)) = args.get(target).copied() else {
                    continue;
                };
                let mut new_links: Vec<FateLink> = Vec::new();
                for si in sources {
                    let Some(src_arg) = args.get(si).copied() else {
                        continue;
                    };
                    for mut l in self.links_for_value(src_arg, span) {
                        l.borrowed = true;
                        l.held = true;
                        new_links.push(l);
                    }
                }
                let target_name = target_id.name.clone();
                if let Some(var) = self.lookup_mut(&target_name) {
                    for l in new_links {
                        if !var.links.iter().any(|e| e.root_id == l.root_id) {
                            var.links.push(l);
                        }
                    }
                }
            }
        }
        // [proj-infer] A result that *holds* borrows (a struct with `proj`
        // fields) ties itself to the lent arguments; the caller links the
        // result to them, held. A lent temporary is as dangling as a
        // projected one.
        if decl.derived_return.is_none() && !typed_only {
            let mut lent = self.infer_lends(decl);
            // [proj-type] Instantiation can make a result hold borrows the
            // declaration could not see: `keep_all<It, T>(…) -> Mut List<T>`
            // with `T = proj Str` (a `?Next` filled from a borrowing pass)
            // returns a view. With nothing inferable from the body about
            // *which* argument, the result is linked to every kept one —
            // conservative, exact for the one-source case, and nothing for a
            // generator (`T = Int`).
            if lent.is_empty() {
                let ret_sub = decl.return_type.as_ref().map(|rt| {
                    let saved = self.enter_generics(&decl.generics);
                    let lowered = self.lower_type(rt);
                    self.generics = saved;
                    substitute_vars(&lowered, &subst, &callee_generics)
                });
                let generic_ret_holds_proj = ret_sub
                    .as_ref()
                    .is_some_and(|r| strip_all_proj(r) != *r && !r.is_proj());
                if generic_ret_holds_proj {
                    let contract = self.effective_contract(best_key, decl);
                    lent = decl
                        .params
                        .iter()
                        .enumerate()
                        .filter(|(_, p)| !p.implicit)
                        .filter(|(_, p)| {
                            contract
                                .as_ref()
                                .and_then(|c| c.iter().find(|d| d.param == p.name.name))
                                .is_none_or(|d| d.kept)
                        })
                        .map(|(i, _)| i)
                        .collect();
                }
            }
            if !lent.is_empty() {
                let positional: Vec<usize> = lent
                    .iter()
                    .filter_map(|&pi| {
                        // Implicit params are not positional arguments.
                        let before = decl.params[..pi].iter().filter(|p| p.implicit).count();
                        if decl.params[pi].implicit {
                            None
                        } else {
                            Some(pi - before)
                        }
                    })
                    .collect();
                for &i in &positional {
                    if let Some(arg) = args.get(i).copied() {
                        if self.is_temporary(arg) {
                            self.out.temp_views.insert(self.key(span));
                        }
                    }
                }
                self.out.lending_calls.insert(self.key(span), positional);
            }
        }
        // The callee's declared effect dependencies must be satisfiable
        // here: each must match an instance in the caller's effect
        // environment (declared or `use`d).
        self.check_callee_effects(name, decl, &subst, &callee_generics, span);
        let saved = self.enter_generics(&decl.generics);
        let ret = self.fn_return_ty(decl);
        self.generics = saved;
        let subst = self.settle_type_args(name, decl, &ret, subst, expected, &arg_tys, span);
        let result = substitute_vars(&ret, &subst, &callee_generics);
        // [qual-depend] A dependent claim in the result names the callee's
        // parameters; hand the caller the claim about *its* values, bound
        // to their roots.
        // [iter-for] A `for`'s element claim binds the subject's source, which
        // the loop fills itself [qual-depend].
        let result = if Self::ty_has_value_ref(&result) && !typed_only {
            let fixed: Vec<&'p ast::Param> = decl
                .params
                .iter()
                .filter(|p| !p.variadic && !p.implicit)
                .collect();
            let vmap = self.call_value_roots(&fixed, args);
            Self::substitute_value_refs(&result, &vmap)
        } else {
            result
        };
        // [net-wire-format] [net-noremote] `encode(value)` / `decode<T>(bytes)`
        // (std's `net`) need a type with a wire form, decided by the shared
        // predicate the emitters generate codecs from — so a value that
        // passes here has a codec on both backends, and one that does not is
        // refused where the program asked, naming the field or the
        // declaration that stops it. A generic instantiation is refused too
        // (step ②'s cut): `encode` inside a generic body has nothing to
        // dispatch on until a bound exists for it.
        // [intrinsic-std-only] An intrinsic is std's, so the callee is std's
        // `encode` or `decode`.
        if decl.intrinsic && matches!(decl.name.name.as_str(), "encode" | "decode") {
            let subject: Option<Ty> = match decl.name.name.as_str() {
                "encode" => arg_tys.first().cloned(),
                _ => match &result {
                    // `decode<T>` answers `T?`: the payload is the non-`None`
                    // arm.
                    Ty::Union(arms) => arms.iter().find(|a| !a.is_none_ty()).cloned(),
                    other => Some(other.clone()),
                },
            };
            if let Some(subject) = subject {
                let subject = subject.strip_quals().clone();
                if let Some(block) = crate::wire::wire_blocker(self.symbols, &subject) {
                    self.error(
                        span,
                        messages::net_noremote_no_wire_form(
                            &decl.name.name,
                            &subject,
                            &block.describe(),
                        ),
                    );
                }
            }
        }
        // [actor-group] [net-noremote] `protocol<E>()` names the protocol a group
        // is of, and a group's members are reached from every node — so this
        // is a **crossing site** where a protocol with a `noremote` payload
        // is refused (user decision 2026-09-26: at the binding, not the
        // declaration; the protocol stays a legal *local* one). The same
        // predicate the emitters generate codecs from. The other crossing
        // site is where the intrinsic fills an implicit `?protocol` — for
        // `actor_group<Ping>(nodes)` and any fn like it — in
        // `fill_one_implicit`.
        if decl.intrinsic && decl.name.name == "protocol" && args.is_empty() {
            if let Some(ast::Type::Named { base, .. }) = type_args.first() {
                let effect = self.written_key_of(base);
                self.refuse_noremote_protocol(&effect, "protocol", span);
            }
        }
        // [cmp-carry] An ordering is fixed **at construction**, and a keyed
        // container's constructor cannot publish one (its element may be a tuple,
        // which has no `cmp` to resolve — see COMPLETED.md), so the identity flows
        // the other way: from the position the value is going into. The same
        // shape as [struct-lit-infer] and the empty-literal rule — a value whose
        // type the position decides.
        self.adopt_carried_identity(result, expected)
    }

    /// [actor-group] [net-noremote] Refuses naming `effect` as a group's
    /// protocol when any of its `send fn` payloads has no wire form: a group
    /// of it could not span nodes, so there is nothing to name on the wire.
    /// `via` is the call the program wrote (`actor_group`, `protocol`), for
    /// the diagnostic. Silent for a name that is not an effect in scope —
    /// the ordinary type errors cover that.
    fn refuse_noremote_protocol(&mut self, effect: &str, via: &str, span: Span) {
        let Some(effect) = self.symbols.effects.get(effect).copied() else {
            return;
        };
        let empty = std::collections::HashMap::new();
        for f in effect.fns.iter().filter(|f| f.is_send) {
            for p in f.params.iter().filter(|p| !p.implicit) {
                let Some(pty) = crate::wire::approx_ty(&p.ty, &empty, self.symbols) else { continue };
                if let Some(block) = crate::wire::wire_blocker(self.symbols, &pty) {
                    self.error(
                        span,
                        messages::net_noremote_group_across_nodes(
                            &effect.name.name,
                            &f.name.name,
                            &pty,
                            &block.describe(),
                            &via,
                        ),
                    );
                    return;
                }
            }
        }
    }

    /// [cmp-carry] The call's result, wearing the identities its *position* names
    /// when the call itself named none. Only for a keyed container, only when the
    /// element types agree, and only to *add* identities the result lacks — so it
    /// cannot overwrite an ordering a value really carries.
    fn adopt_carried_identity(&mut self, result: Ty, expected: Option<&Ty>) -> Ty {
        let Some(expected) = expected else {
            return result;
        };
        let (Ty::Named { name, args }, Ty::Named { name: en, args: ea }) =
            (result.strip_quals(), expected.strip_quals())
        else {
            return result;
        };
        let Some((arity, _)) = keyed_container(name) else {
            return result;
        };
        if name != en || args.len() > arity || ea.len() <= arity {
            return result;
        }
        if args.len() != arity || args[..] != ea[..arity] {
            return result;
        }
        let quals = result.quals().to_vec();
        Ty::Named {
            name: name.clone(),
            args: ea.clone(),
        }
        .qualify(quals)
    }

    /// [call-type-args] Finishes a generic call's substitution and records
    /// it for the emitters.
    ///
    /// A type argument the *arguments* did not determine is taken from the
    /// **expected type** — the annotation on a `let`, the enclosing fn's
    /// return type, or a concrete parameter the call's result flows into.
    /// If it is still unbound and it reaches the result type, the call is an
    /// error: the checker would hand the backends a `T` it never resolved,
    /// which one target language may infer for itself and another may not
    /// (`mutableListOf()` is not valid Kotlin, while rustc infers `vec![]`
    /// backwards from a later use). Requiring the context here keeps the two
    /// backends on the same programs and makes the type known to the
    /// checker, which is what an intrinsic lowering renders.
    fn settle_type_args(
        &mut self,
        name: &str,
        decl: &'p FnDecl,
        ret: &Ty,
        mut subst: HashMap<String, Ty>,
        expected: Option<&Ty>,
        arg_tys: &[Ty],
        span: Span,
    ) -> HashMap<String, Ty> {
        if decl.generics.is_empty() {
            return subst;
        }
        let callee_generics: HashSet<String> =
            decl.generics.iter().map(|g| g.name.clone()).collect();
        if let Some(exp) = expected.filter(|e| !e.is_unknown() && **e != Ty::Never) {
            let mut from_expected: HashMap<String, Ty> = HashMap::new();
            if unify(ret, exp, &mut from_expected) {
                for (g, ty) in from_expected {
                    if callee_generics.contains(&g) && !ty.is_unknown() && !subst.contains_key(&g) {
                        subst.insert(g, ty);
                    }
                }
            }
        }
        // [implicit-group] [iter-protocol] A `?Next<It, T>` spread teaches `T`
        // from the *declaration* of whatever `It` turned out to be: a pass says
        // what it yields at its `: Next<self, T>` clause, so a combinator's
        // element type never has to be written and a bare lambda can be typed
        // against it. Reaches through an origin mint, whose machine type stands
        // for the origin [iter-fn].
        self.learn_next_elems(decl, &callee_generics, &mut subst);
        // An `Unknown` argument means an earlier diagnostic already fired
        // (or a type the checker could not determine): stay lenient rather
        // than reporting the same mistake twice [type-unknown-lenient].
        let lenient = arg_tys.iter().any(|t| t.is_unknown());
        let missing: Vec<&str> = decl
            .generics
            .iter()
            .filter(|g| !subst.contains_key(&g.name) && ty_mentions_var(ret, &g.name))
            .map(|g| g.name.as_str())
            .collect();
        if !missing.is_empty() && !lenient {
            let list = missing
                .iter()
                .map(|g| format!("`{g}`"))
                .collect::<Vec<_>>()
                .join(", ");
            let plural = if missing.len() == 1 { "" } else { "s" };
            self.error(
                span,
                messages::call_type_args_cannot_infer(
                    &plural,
                    &list,
                    &name,
                    &(if missing.len() == 1 { "it" } else { "them" }),
                ),
            );
        }
        let recorded: Vec<Ty> = decl
            .generics
            .iter()
            .map(|g| subst.get(&g.name).cloned().unwrap_or(Ty::Unknown))
            .collect();
        self.out.call_type_args.insert(self.key(span), recorded);
        subst
    }

    /// Resolves each effect dependency of a called fn against the caller's
    /// effect environment [effect-fn-deps] and records the concrete
    /// instances (in declaration order) for the backend to thread as
    /// handler arguments.
    fn check_callee_effects(
        &mut self,
        name: &str,
        decl: &'p FnDecl,
        subst: &HashMap<String, Ty>,
        callee_generics: &HashSet<String>,
        span: Span,
    ) {
        let mut resolved: Vec<Ty> = Vec::new();
        // [actor-spawn-effect] The `spawn` capability **propagates like any
        // other effect**: `pool` and `watch` declare it, and std's own
        // documentation says declaring it is "what makes creating one a
        // capability the caller must hold" — so a caller that has not been
        // given it cannot reach one through a helper either. Checked here
        // rather than beside `can_spawn`'s other use because this is where a
        // callee's requirements meet the caller's environment; there is
        // nothing to *resolve*, since the capability names no instance.
        if !self.can_spawn
            && decl
                .effects
                .iter()
                .flatten()
                .any(|e| matches!(e, EffectRef::Spawn(_)))
        {
            self.error(span, messages::actor_spawn_effect_callee_needs_spawn(&name));
        }
        // [actor-free-send-fn] A send-kind function is *scheduled*, never called: a
        // call would run it here, on this thread, inside this frame — which is
        // the callback anti-pattern the kind exists to refuse.
        if decl.is_send {
            self.error(span, messages::actor_free_send_fn_called(&name));
        }
        // The callee's *effective* effect list: what it declares, plus what
        // it inherited from its fn-typed parameters [fn-effects] — a caller
        // has to supply those too, since they are how the callee calls the
        // value it was given.
        //
        // [effect-any] Each requirement carries its declared identity
        // strength: bare `[E]` assumes one instance, `[any E]` accepts a
        // binding spread over many. ([effect-handle]: every binding is a
        // handle, so there is no seam strength to check any more.)
        let mut wants: Vec<(Ty, bool)> = Vec::new();
        {
            let saved = self.enter_generics(&decl.generics);
            // Unknown effect names are reported at the callee's own
            // declaration, so the list is expanded quietly. Known *where the
            // callee wrote them* [type-identity]: a caller need not import an
            // effect the callee requires — `read_to_str`'s implied `Streams`
            // [effect-prereq] is `fs`'s to name, not the caller's. [effect-any]
            // `any E` is the weak requirement: any binding does.
            for e in self.expand_effect_refs_quiet(decl.effects.as_deref().unwrap_or(&[]), true) {
                if !wants.iter().any(|(w, _)| *w == e.ty) {
                    wants.push((e.ty, e.any));
                }
            }
            // [effect-any] An inherited requirement carries no strength of
            // its own (a fn type cannot say `any`), so it is the strong one
            // unless the callee's written list weakened it above — the
            // written entry wins the dedupe.
            //
            // **Order**: inherited requirements come *first*, as they do in
            // the callee's own environment (`check_effect_list`) and so in
            // `fn_effects` — the emitters pass one argument per entry, so
            // the two lists must agree position by position.
            let mut inherited: Vec<(Ty, bool)> = Vec::new();
            // [fn-effects] Only a callee with no written list inherits.
            for p in decl.params.iter().filter(|_| decl.effects.is_none()) {
                for ty in self.inherited_fn_effects(&p.ty) {
                    if !inherited.iter().any(|(w, _)| *w == ty) {
                        inherited.push((ty, false));
                    }
                }
            }
            let written = std::mem::take(&mut wants);
            for (ty, any) in &written {
                if let Some(slot) = inherited.iter_mut().find(|(w, _)| w == ty) {
                    slot.1 = *any;
                }
            }
            wants = inherited;
            for (ty, any) in written {
                if !wants.iter().any(|(w, _)| *w == ty) {
                    wants.push((ty, any));
                }
            }
            self.generics = saved;
        }
        // [effect-use-no-dup] Innermost first, shadowed duplicates hidden.
        let visible = self.visible_avail();
        for (lowered, req_any) in wants {
            let want = substitute_vars(&lowered, subst, callee_generics);
            // [throw] A callee that may throw does not need a handler — it
            // needs a delimiter. The call is an *exit* of everything up to
            // it, which `record_throw` accounts for.
            if let Ty::Named { name: eff, args } = &want {
                if eff == THROW_EFFECT {
                    let message = args.first().cloned().unwrap_or(Ty::Unknown);
                    self.record_throw(span, message, false);
                    continue;
                }
            }
            // Exact instance first, then a unique compatible match (the
            // callee's requirement may still contain unresolved parts).
            let found = visible.iter().find(|c| c.ty == want).cloned();
            let found = found.or_else(|| {
                let compatible: Vec<&EffectAvail> = visible
                    .iter()
                    .filter(|c| unify(&want, &c.ty, &mut HashMap::new()))
                    .collect();
                match compatible.len() {
                    1 => Some(compatible[0].clone()),
                    _ => None,
                }
            });
            match found {
                Some(avail) => {
                    // [effect-any] The identity rule (user decision
                    // 2026-09-26): a bare `[E]` assumes one instance and
                    // ordered sends, which a binding spread over many
                    // instances cannot give; `[any E]` accepts either.
                    if !req_any && avail.any {
                        self.error(
                            span,
                            messages::effect_any_single_instance_callee(&name, &want),
                        );
                    }
                    // [fn-effects] Feeds an enclosing lambda's inferred set.
                    self.note_effect_use(&avail.ty);
                    resolved.push(avail.ty);
                }
                None => {
                    self.error(span, messages::effect_available_callee_no_handler(&want, &name));
                    resolved.push(want);
                }
            }
        }
        if !resolved.is_empty() {
            self.out.call_effects.insert(self.key(span), resolved);
        }
    }

    /// [effect-member-overload] [effect-dispatch] Records that the call at
    /// `span` dispatches to `member` of `effect`, and which overload it is
    /// where the effect declares the name more than once — the emitters name
    /// an overloaded member positionally.
    fn record_member_call(&mut self, effect: &'p EffectDecl, member: &'p FnDecl, span: Span) {
        let Some(index) = crate::effect_member_index(effect, member) else { return };
        if crate::effect_members_named(effect, &member.name.name).len() > 1 {
            self.out.effect_member_calls.insert(self.key(span), index);
        }
        let key = self.symbols.key_or(effect, &effect.name.name).to_string();
        self.out.member_calls.insert(self.key(span), MemberCall { effect: key, index });
    }

    /// [effect-member-call] A call whose selection chose an effect's member
    /// (PIPELINE.md B3.5: one candidate set with the fns, so the fit, the
    /// arity with defaults and named arguments [fn-param-default], and the
    /// ranking are the call's). What is left is the member's own: the
    /// instance it dispatches through — available, and disambiguated among
    /// several by the argument types and the expected type
    /// [effect-available] [effect-disambiguation] — its contract, its
    /// implicits, and the result at the instance. `subst` is the winner's.
    #[allow(clippy::too_many_arguments)]
    fn finish_member_call(
        &mut self,
        effect: &'p EffectDecl,
        member: &'p FnDecl,
        subst: HashMap<String, Ty>,
        type_args: &'p [ast::Type],
        args: &[&'p Expr],
        arg_tys: &[Ty],
        named: &'p [ast::NamedArg],
        expected: Option<&Ty>,
        // [iter-for] Typed arguments with no expressions of their own.
        typed_only: bool,
        span: Span,
    ) -> Ty {
        self.record_member_call(effect, member, span);
        // [throw] The throw effect has no handler: the delimiter is `try`.
        if effect.name.name == THROW_EFFECT {
            return self.check_throw_call(member, args, Some(arg_tys), span);
        }
        // The member's signature, lowered with the effect's generics as
        // `Var`s and the member's own [effect-member-generics].
        let saved = self.enter_generics(&effect.generics);
        self.enter_generics(&member.generics);
        let member_params: Vec<Ty> = member.params.iter().map(|p| self.lower_type(&p.ty)).collect();
        let member_ret: Ty = member.return_type.as_ref().map(|t| self.lower_type(t)).unwrap_or_else(Ty::none);
        // [implicit-param] Collected with the generics in scope, so
        // `?fmt: (T) -> Str` lowers to a variable rather than a nominal `T`.
        let member_implicits = self.collect_implicits(member);
        self.generics = saved;
        let generic_set: HashSet<String> =
            effect.generics.iter().chain(&member.generics).map(|g| g.name.clone()).collect();
        let subst_for = |instance: &Ty| -> HashMap<String, Ty> {
            match instance {
                Ty::Named { args, .. } => {
                    effect.generics.iter().map(|g| g.name.clone()).zip(args.iter().cloned()).collect()
                }
                _ => HashMap::new(),
            }
        };
        // The positional parameters, which the arguments line up with.
        let positional: Vec<usize> = member
            .params
            .iter()
            .enumerate()
            .filter(|(_, p)| !p.implicit && !p.variadic)
            .map(|(i, _)| i)
            .collect();
        let effect_key = self.symbols.key_or(effect, &effect.name.name).to_string();
        // Instances of this effect currently available — innermost first,
        // with a shadowed registration hidden by the one that shadows it
        // [effect-use-no-dup], so interception does not read as ambiguity.
        let candidates: Vec<Ty> = self
            .visible_effects()
            .into_iter()
            .filter(|t| matches!(t, Ty::Named { name, .. } if *name == effect_key))
            .collect();
        let resolved: Option<Ty> = if !type_args.is_empty() {
            // Explicit type arguments pin the instance.
            let targs: Vec<Ty> = type_args.iter().map(|t| self.lower_type(t)).collect();
            let want = Ty::Named { name: effect_key.clone(), args: targs };
            if candidates.iter().any(|c| *c == want || unify(c, &want, &mut HashMap::new())) {
                Some(want)
            } else {
                self.error(span, messages::effect_available_no_handler(&want));
                None
            }
        } else if candidates.len() == 1 {
            Some(candidates[0].clone())
        } else if candidates.is_empty() {
            self.report_member_without_instance(effect, member, &effect_key, span);
            None
        } else {
            // Multiple instances in scope: disambiguate by the argument
            // types, then by the expected type.
            let viable: Vec<Ty> = candidates
                .iter()
                .filter(|c| {
                    let mut subst = subst_for(c);
                    positional.iter().zip(arg_tys).all(|(&pi, a)| {
                        let sp = substitute_vars(&member_params[pi], &subst, &generic_set);
                        unify(&sp, a, &mut subst)
                    })
                })
                .cloned()
                .collect();
            let narrowed: Vec<Ty> = match expected {
                Some(exp) if !exp.is_unknown() => {
                    let by_ret: Vec<Ty> = viable
                        .iter()
                        .filter(|c| {
                            let sr = substitute_vars(&member_ret, &subst_for(c), &generic_set);
                            sr.is_unknown() || is_subtype(&sr, exp)
                        })
                        .cloned()
                        .collect();
                    if by_ret.is_empty() {
                        viable.clone()
                    } else {
                        by_ret
                    }
                }
                _ => viable.clone(),
            };
            match narrowed.len() {
                1 => Some(narrowed[0].clone()),
                0 => {
                    self.error(span, messages::effect_available_no_handler_matches(&effect.name.name));
                    None
                }
                _ => {
                    self.error(
                        span,
                        messages::effect_disambiguation_ambiguous(&effect.name.name, &member.name.name),
                    );
                    Some(narrowed[0].clone())
                }
            }
        };
        // The instance binds the effect's generics; what the arguments bound
        // stands for the member's own.
        let mut subst = {
            let mut s = resolved.as_ref().map(&subst_for).unwrap_or_default();
            for (k, v) in subst {
                s.entry(k).or_insert(v);
            }
            s
        };
        for (i, &pi) in positional.iter().enumerate() {
            let Some(a) = arg_tys.get(i) else { break };
            unify(&member_params[pi], a, &mut subst);
        }
        // Coercions against the fully substituted parameter types: the fixed
        // positions, then a variadic tail's elements.
        if !typed_only {
            let tail_elem: Option<Ty> = member.params.iter().position(|p| p.variadic).map(|vi| {
                match substitute_vars(&member_params[vi], &subst, &generic_set) {
                    Ty::Array(e) => *e,
                    other => other,
                }
            });
            for (i, a) in args.iter().enumerate() {
                let Some(logical) = arg_tys.get(i).cloned() else { break };
                if matches!(a, Expr::Spread { .. }) {
                    continue;
                }
                let sp = match positional.get(i) {
                    Some(&pi) => substitute_vars(&member_params[pi], &subst, &generic_set),
                    None => match &tail_elem {
                        Some(t) => t.clone(),
                        None => continue,
                    },
                };
                let repr = self.repr_of(a, &logical);
                self.maybe_coerce(a.span(), &logical, &repr, &sp);
                // [type-none-unit] As for a fn call: a `None`-typed slot
                // takes the unit value.
                self.note_none_unit(a, &sp);
            }
        }
        // [linear-generics] The instantiation ban reaches effect members'
        // *own* generics too: a member `log<T>(x: T)` binding `T` to a linear
        // type would swallow the obligation unless it opts in with
        // `<T canbe linear>`.
        let opted: HashSet<&str> = member
            .generic_canbe
            .iter()
            .filter(|(_, q)| q.name.name == "linear")
            .map(|(id, _)| id.name.as_str())
            .collect();
        let mut names: Vec<&String> = member.generics.iter().map(|g| &g.name).collect();
        names.sort();
        for var_name in names {
            if opted.contains(var_name.as_str()) {
                continue;
            }
            if let Some(bound) = subst.get(var_name) {
                if self.ty_own_linear(bound) {
                    self.error(
                        span,
                        messages::linear_generics_effect_member_not_opted(&var_name, &member.name.name, &bound),
                    );
                    break;
                }
            }
        }
        // [fn-param-default] A named argument filling an ordinary parameter:
        // checked against it, as at a fn call, so the IR reads its type.
        let fixed_names: HashSet<String> =
            positional.iter().map(|&pi| member.params[pi].name.name.clone()).collect();
        for a in named {
            if let Some(&pi) = positional.iter().find(|&&pi| member.params[pi].name.name == a.name.name) {
                if member.params[pi].default.is_none() {
                    self.error(a.span, messages::fn_param_default_named_without_default(&a.name.name));
                }
                let want = substitute_vars(&member_params[pi], &subst, &generic_set).strip_spread();
                self.check_expr(&a.value, Some(&want));
            }
        }
        // [decl-explicit] The member's declared deduction list is a real
        // contract: apply it exactly like a named call's, so a member that
        // takes ownership consumes its argument.
        if let Some(list) = member.deductions.as_ref().filter(|_| !typed_only) {
            let facts = crate::deduce::from_written(member, list, &HashSet::new(), |_, _| {});
            let contract: Vec<FnParamContract> = member
                .params
                .iter()
                .zip(&member_params)
                .map(|(p, pty)| {
                    let entry = facts.iter().find(|d| d.param == p.name.name);
                    FnParamContract {
                        name: Some(p.name.name.clone()),
                        kept: entry.map(|d| d.kept).unwrap_or(true),
                        effect: entry.map(|d| d.effect.clone()).unwrap_or(QualEffect::KeepAll),
                        mutable: pty.quals().iter().any(|q| q.name == "Mut"),
                        lent: entry.is_some_and(|d| d.lent),
                    }
                })
                .collect();
            self.apply_call_contract(args, &member_params, Some(&contract), span);
        }
        // [proj-infer] An effect member has no body: its result holds a
        // borrow of what its list declares (`[p: proj]`), else of every
        // kept parameter.
        if member.derived_return.is_none()
            && !typed_only
            && member.return_type.as_ref().is_some_and(|t| crate::lends::holds_proj(t, &self.scope.structs))
        {
            let lent = crate::lends::declared_lends(member).unwrap_or_else(|| crate::lends::kept_params(member));
            if !lent.is_empty() {
                self.out.lending_calls.insert(self.key(span), lent);
            }
        }
        if let Some(instance) = &resolved {
            // [fn-effects] Feeds an enclosing lambda's inferred set.
            let instance = instance.clone();
            self.note_effect_use(&instance);
            self.out.effect_calls.insert(self.key(span), instance);
        }
        // [implicit-param] An effect member may declare implicit parameters:
        // they resolve at *this* call, with the instance's type arguments
        // substituted in, and the handler receives them as trailing arguments.
        if !member_implicits.is_empty() {
            let mut filled_subst = subst.clone();
            self.call_fixed_params = fixed_names;
            self.fill_implicits(&member_implicits, &member.name.name, &mut filled_subst, &generic_set, named, span);
            self.call_fixed_params = HashSet::new();
        }
        substitute_vars(&member_ret, &subst, &generic_set)
    }

    /// [effect-available] A member call with no instance of its effect in
    /// scope, reported for what it is: inside a handler of that effect,
    /// self-dispatch (whose remedy, for a send member, is `k@self(…)`); in a
    /// façade member, one of the servant's dependencies; otherwise a missing
    /// handler.
    fn report_member_without_instance(&mut self, effect: &'p EffectDecl, member: &'p FnDecl, effect_key: &str, span: Span) {
        let own = self
            .handler_ofs
            .iter()
            .find(|of| matches!(of.strip_quals(), Ty::Named { name, .. } if *name == effect_key))
            .cloned();
        match own {
            Some(of) => {
                let remedy = if member.is_send {
                    format!(
                        "send it to this actor instead: `{}@self(…)`, which runs as its own later \
                         activation",
                        member.name.name
                    )
                } else {
                    "Move the shared logic into a function both members call".to_string()
                };
                self.error(span, messages::effect_available_own_effect(&member.name.name, &of, &remedy))
            }
            None if self.facade_handler.is_some_and(|h| {
                self.out.handler_deps.get(self.symbols.key_or(h, &h.name.name)).is_some_and(|deps| {
                    deps.iter().any(|(t, _)| matches!(t.strip_quals(), Ty::Named { name, .. } if *name == effect_key))
                })
            }) =>
            {
                self.error(
                    span,
                    messages::actor_mixed_handler_sync_member_dependency(&member.name.name, &effect.name.name),
                )
            }
            None => self.error(span, messages::effect_available_no_handler(&effect.name.name)),
        }
    }
}

/// Whether a block always leaves the enclosing construct — every path
/// hits a `return`, `break`, or `continue` — so its state never reaches
/// the code *after* a branching construct [deduce-consume]. Same shape as
/// [fn-must-return]'s walker, with loop exits counted too.
/// The source symbol of a binary operator, for diagnostics [op-no-none].
fn op_symbol(op: BinaryOp) -> &'static str {
    use BinaryOp::*;
    match op {
        Add => "+",
        Sub => "-",
        Mul => "*",
        Div => "/",
        Rem => "%",
        Pow => "**",
        Eq => "==",
        NotEq => "!=",
        Lt => "<",
        Gt => ">",
        LtEq => "<=",
        GtEq => ">=",
        And => "&&",
        Or => "||",
    }
}

/// [op-arith] [op-pow] The function an arithmetic operator names (O1's
/// table): `+` `plus`, `-` `minus`, `*` `times`, `/` `divide`, `**` `pow`.
/// `%` names none (PIPELINE.md §II.10 P16).
fn arith_member(op: BinaryOp) -> &'static str {
    match op {
        BinaryOp::Add => "plus",
        BinaryOp::Sub => "minus",
        BinaryOp::Mul => "times",
        BinaryOp::Div => "divide",
        BinaryOp::Pow => "pow",
        _ => unreachable!("not an arithmetic operator with a name"),
    }
}

/// [op-arith] The operator-numeric types, as (is_float_class, width rank):
/// the integer widths `Int` < `Long` and the float widths `Float` <
/// `Double`, promotion widening within a class only. `Byte` is
/// deliberately **not** operator-numeric: it is an octet rather than a
/// number — unsigned on both backends [type-byte] — and its arithmetic
/// goes through `to_int`/`to_byte`, which is one call and states the
/// wrapping instead of implying it.
fn numeric_class(name: &str) -> Option<(bool, u8)> {
    match name {
        "Int" => Some((false, 0)),
        "Long" => Some((false, 1)),
        "Float" => Some((true, 0)),
        "Double" => Some((true, 1)),
        _ => None,
    }
}

/// The operator-numeric class of a (qualifier-stripped) type.
fn op_numeric(ty: &Ty) -> Option<(bool, u8)> {
    match ty {
        Ty::Named { name, .. } => numeric_class(name),
        _ => None,
    }
}

/// [op-arith] Operands the operator rules stay silent about: a type the
/// checker could not infer [type-unknown-lenient] and a diverging expression.
/// An unconstrained generic parameter is **not** lenient (B3.3e): nothing is
/// knowable about a `T` [implicit-forward], and a `%`, unary `-` or `&&` on
/// one passed the checker and was refused by both target compilers
/// [backend-never-wrong]; `+ - * /` and `**` on a `T` are their calls, which
/// need an enclosing implicit.
fn op_lenient(ty: &Ty) -> bool {
    ty.is_unknown() || matches!(ty, Ty::Never)
}

/// [type-lit-adopt] The numeric type an **unsuffixed** literal adopts from its
/// expected type (user decision 2026-09-14): a plain numeric expectation,
/// reached through qualifiers and through a sole non-`None` union arm
/// (`let x: Long? = 1`). A float literal only adopts within the float
/// class; an integer literal adopts any wider numeric type but never
/// re-adopts `Int` (which would be a no-op).
fn adopted_numeric(expected: Option<&Ty>, suffixed: bool, float_lit: bool) -> Option<&'static str> {
    if suffixed {
        return None;
    }
    let target = numeric_expectation(expected?)?;
    let legal = if float_lit {
        matches!(target, "Float" | "Double")
    } else {
        matches!(target, "Long" | "Float" | "Double")
    };
    legal.then_some(target)
}

/// The single numeric type an expected type names, if it names one.
fn numeric_expectation(expected: &Ty) -> Option<&'static str> {
    match expected.strip_quals() {
        Ty::Named { name, .. } => match name.as_str() {
            "Int" => Some("Int"),
            "Long" => Some("Long"),
            "Float" => Some("Float"),
            "Double" => Some("Double"),
            _ => None,
        },
        Ty::Union(arms) => {
            let mut non_none = arms.iter().filter(|a| !a.is_none_ty());
            match (non_none.next(), non_none.next()) {
                (Some(one), None) => numeric_expectation(one),
                _ => None,
            }
        }
        _ => None,
    }
}

// ================= missing-return analysis [fn-must-return] =================

/// Whether a block always exits the enclosing fn (every path hits a
/// `return`). Conservative: loops never count (they may run zero times),
/// `if` needs an `else`, `when` needs every branch to exit (exhaustiveness
/// over union arms is enforced separately [when-exhaustive]).

/// [iter-protocol] The element type carried by a `next` return type — the
/// `Emitted T` arm of `Emitted T | Finished` — or `None` when the type is not
/// that shape, in which case the function is some other `next` and not a
/// driver.
///
/// Exactly two arms, one tagged `Emitted` and one the fieldless `Finished`:
/// the shape is the protocol, so anything else is deliberately not accepted
/// rather than half-understood.
fn emitted_arm_ty(ret: &Ty) -> Option<(Ty, usize, usize)> {
    let Ty::Union(arms) = ret else { return None };
    if arms.len() != 2 {
        return None;
    }
    let value_arms = ret.value_arms();
    let mut found = None;
    let mut finished = false;
    for (i, arm) in value_arms.iter().enumerate() {
        match arm {
            Ty::Qualified { quals, base } if quals.iter().any(|q| q.name == "Emitted") => {
                // [qual-depend] The element keeps every claim the arm
                // carries beside the protocol tag: `Emitted (+Idx(…) Int)`
                // emits an `Idx(…) Int`, which is how a pass mints a
                // dependent claim per element. Flat lists [qual-group] make
                // "Emitted applied to a claimed Int" and "two qualifiers on
                // an Int" one shape, so this is a filter, not an unwrap.
                let rest: Vec<Qual> = quals
                    .iter()
                    .filter(|q| q.name != "Emitted")
                    .cloned()
                    .collect();
                let elem = if rest.is_empty() {
                    (**base).clone()
                } else {
                    Ty::Qualified {
                        quals: rest,
                        base: base.clone(),
                    }
                };
                found = Some((elem, i));
            }
            Ty::Named { name, args } if name == "Finished" && args.is_empty() => {
                finished = true;
            }
            _ => return None,
        }
    }
    let (elem, arm) = found?;
    if finished {
        Some((elem, arm, value_arms.len()))
    } else {
        None
    }
}

/// [proj-anywhere] [ref-handle] The span of the first `proj`/`ref`
/// qualifier in a type, if any — searching arms, arguments and elements in
/// order.
/// [name-resolve] The qualifiers the compiler declares itself: no
/// declaration to find, their rules `validate_quals`'.
fn is_intrinsic_qualifier(name: &str) -> bool {
    matches!(name, "Mut" | "Linear" | "linear" | "once" | "proj" | "ref")
}

/// [name-resolve] [name-table] Whether a written name, meaning `m` where it
/// is written, is usable as a *type*: a struct, an `intrinsic` or `platform`
/// type, an alias, an effect, or the language-level `None`. Generics are the
/// caller's.
fn names_type(name: &str, m: &crate::names::Meaning<'_>) -> bool {
    name == "None" || m.is_type()
}

/// [name-resolve] [name-table] Whether it is usable as a *qualifier*: a
/// declared one, an intrinsic one, or an effect (a producer's claim is
/// written where a qualifier goes [fn-effects]).
fn names_qualifier(name: &str, m: &crate::names::Meaning<'_>) -> bool {
    is_intrinsic_qualifier(name) || m.is_qualifier() || m.effect.is_some()
}

fn first_proj_span(ty: &ast::Type) -> Option<Span> {
    first_qual_span(ty, crate::types::is_proj_name)
}

/// [ref-handle] The first `ref` qualifier written in a type.
fn first_ref_span(ty: &ast::Type) -> Option<Span> {
    first_qual_span(ty, |n| n == "ref")
}

fn first_qual_span(ty: &ast::Type, want: fn(&str) -> bool) -> Option<Span> {
    let in_ref = |r: &TypeRef| -> Option<Span> {
        if want(&r.name.name) {
            return Some(r.span);
        }
        r.args.iter().find_map(|a| first_qual_span(a, want))
    };
    match ty {
        ast::Type::Named { qualifiers, base } => {
            qualifiers.iter().find_map(in_ref).or_else(|| in_ref(base))
        }
        ast::Type::QualifiedGroup {
            qualifiers, base, ..
        } => qualifiers
            .iter()
            .find_map(in_ref)
            .or_else(|| first_qual_span(base, want)),
        ast::Type::Nullable { inner, .. } | ast::Type::Array { elem: inner, .. } => {
            first_qual_span(inner, want)
        }
        ast::Type::Union { arms, .. } | ast::Type::Tuple { elems: arms, .. } => {
            arms.iter().find_map(|a| first_qual_span(a, want))
        }
        _ => None,
    }
}

/// [proj-anywhere] Every `proj`/`ref` qualifier reference in a type, in
/// order.
/// [proj-infer] The `proj`/`ref` references that sit inside a type
/// *argument* (`List<proj T>`, `Map<K, proj V>`): borrows the value holds,
/// as opposed to wholesale ones on the value itself.
fn proj_refs_in_type_args(ty: &ast::Type) -> Vec<&TypeRef> {
    fn walk<'a>(ty: &'a ast::Type, inside_arg: bool, out: &mut Vec<&'a TypeRef>) {
        fn in_ref<'a>(r: &'a TypeRef, inside_arg: bool, out: &mut Vec<&'a TypeRef>) {
            if crate::types::is_proj_name(&r.name.name) && inside_arg {
                out.push(r);
            }
            for a in &r.args {
                walk(a, true, out);
            }
        }
        match ty {
            ast::Type::Literal { .. } => {}
            ast::Type::Named { qualifiers, base } => {
                for q in qualifiers {
                    in_ref(q, inside_arg, out);
                }
                in_ref(base, inside_arg, out);
            }
            ast::Type::QualifiedGroup {
                qualifiers, base, ..
            } => {
                for q in qualifiers {
                    in_ref(q, inside_arg, out);
                }
                walk(base, inside_arg, out);
            }
            ast::Type::Union { arms, .. } | ast::Type::Tuple { elems: arms, .. } => {
                for a in arms {
                    walk(a, inside_arg, out);
                }
            }
            ast::Type::Nullable { inner, .. } | ast::Type::Array { elem: inner, .. } | ast::Type::Spread { inner, .. } => {
                walk(inner, inside_arg, out)
            }
            ast::Type::Fn { .. } => {}
        }
    }
    let mut out = Vec::new();
    walk(ty, false, &mut out);
    out
}

/// [proj-type] Why a projection alone kept an argument out of a candidate.
#[derive(Clone, Copy, Debug)]
enum ProjBlock {
    /// A top-level projection into a `Mut` position.
    Mutates,
    /// A top-level projection into a consumed position.
    Consumes,
    /// A plain `proj` (not a `ref(c)` handle) into a kept `Mut` position:
    /// read-only, so it fits the kept half but not the mutation permission
    /// [ref-handle].
    NotHandle,
    /// A projection nested inside the type (a union arm, a type argument)
    /// where the position's type has none there.
    Nested,
}

/// [proj-type] The type with every `proj`/`ref` removed, at every depth —
/// the "same type on the JVM" reading, for diagnostics.
fn strip_all_proj(ty: &Ty) -> Ty {
    match ty {
        Ty::Qualified { quals, base } => {
            let inner = strip_all_proj(base);
            let kept: Vec<Qual> = quals.iter().filter(|q| !crate::types::is_proj_name(&q.name)).cloned().collect();
            if kept.is_empty() {
                inner
            } else {
                inner.qualify(kept)
            }
        }
        Ty::Named { name, args } => Ty::Named {
            name: name.clone(),
            args: args.iter().map(strip_all_proj).collect(),
        },
        Ty::Union(arms) => Ty::union_of(arms.iter().map(strip_all_proj).collect()),
        Ty::Tuple(elems) => Ty::Tuple(elems.iter().map(strip_all_proj).collect()),
        Ty::Array(elem) => Ty::Array(Box::new(strip_all_proj(elem))),
        other => other.clone(),
    }
}

/// [proj-readonly] The `Mut` qualifier of a parameter type written with a
/// *top-level* `proj Mut` — the self-contradictory spelling refused at the
/// declaration site. Only the parameter's own qualifier list counts:
/// `proj Mut` nested in a type argument (`Mut List<proj Mut Str>`) is the
/// element type a view really holds, and a nullable/union of the pair
/// (`(proj Mut Str)?`) is not a `Mut` position at the call boundary.
fn top_level_proj_mut(ty: &ast::Type) -> Option<&TypeRef> {
    let quals = match ty {
        ast::Type::Named { qualifiers, .. } => qualifiers,
        ast::Type::QualifiedGroup { qualifiers, .. } => qualifiers,
        _ => return None,
    };
    if quals.iter().any(|q| q.name.name == "proj") {
        quals.iter().find(|q| q.name.name == "Mut")
    } else {
        None
    }
}

fn proj_refs(ty: &ast::Type) -> Vec<&TypeRef> {
    fn walk<'a>(ty: &'a ast::Type, out: &mut Vec<&'a TypeRef>) {
        fn in_ref<'a>(r: &'a TypeRef, out: &mut Vec<&'a TypeRef>) {
            if crate::types::is_proj_name(&r.name.name) {
                out.push(r);
            }
            for a in &r.args {
                walk(a, out);
            }
        }
        match ty {
            ast::Type::Named { qualifiers, base } => {
                for q in qualifiers {
                    in_ref(q, out);
                }
                in_ref(base, out);
            }
            ast::Type::QualifiedGroup {
                qualifiers, base, ..
            } => {
                for q in qualifiers {
                    in_ref(q, out);
                }
                walk(base, out);
            }
            ast::Type::Nullable { inner, .. } | ast::Type::Array { elem: inner, .. } => {
                walk(inner, out)
            }
            ast::Type::Union { arms, .. } | ast::Type::Tuple { elems: arms, .. } => {
                for a in arms {
                    walk(a, out);
                }
            }
            _ => {}
        }
    }
    let mut out = Vec::new();
    walk(ty, &mut out);
    out
}

/// [proj-anywhere] The qualifier names of the union arms that carry a
/// `proj`, for a union return type; empty for a non-union.
fn proj_arm_qualifiers(ty: &ast::Type) -> Vec<String> {
    let ast::Type::Union { arms, .. } = ty else {
        return Vec::new();
    };
    arms.iter()
        .filter(|arm| first_proj_span(arm).is_some())
        .filter_map(|arm| match arm {
            ast::Type::Named { qualifiers, .. } | ast::Type::QualifiedGroup { qualifiers, .. } => {
                qualifiers
                    .iter()
                    .find(|q| !crate::types::is_proj_name(&q.name.name))
                    .map(|q| q.name.name.clone())
            }
            _ => None,
        })
        .collect()
}

/// [proj-anywhere] The indices of a union type's arms that carry `proj`;
/// empty for a non-union.
fn proj_arm_indices(ty: &ast::Type) -> Vec<usize> {
    let ast::Type::Union { arms, .. } = ty else {
        return Vec::new();
    };
    arms.iter()
        .enumerate()
        .filter(|(_, arm)| first_proj_span(arm).is_some())
        .map(|(i, _)| i)
        .collect()
}

/// [iter-yield-proj] Whether a written type mentions a generic parameter by name.
pub(crate) fn type_mentions_generic(ty: &ast::Type, name: &str) -> bool {
    fn in_ref(r: &TypeRef, name: &str) -> bool {
        r.name.name == name || r.args.iter().any(|a| type_mentions_generic(a, name))
    }
    match ty {
        ast::Type::Named { qualifiers, base } => {
            qualifiers.iter().any(|q| in_ref(q, name)) || in_ref(base, name)
        }
        ast::Type::QualifiedGroup {
            qualifiers, base, ..
        } => qualifiers.iter().any(|q| in_ref(q, name)) || type_mentions_generic(base, name),
        ast::Type::Nullable { inner, .. } | ast::Type::Array { elem: inner, .. } => {
            type_mentions_generic(inner, name)
        }
        ast::Type::Union { arms, .. } | ast::Type::Tuple { elems: arms, .. } => {
            arms.iter().any(|a| type_mentions_generic(a, name))
        }
        _ => false,
    }
}

/// [is-bind-once] Whether an expression is a **place** — a name, or a
/// field/tuple/index chain over one — and so free of side effects to read
/// twice. Everything else has to be evaluated once into a temporary.
/// [op-assign] What an **assignment** may write: a variable, a field path, a
/// subscript. Looser than [`is_place_expr`] in one way on purpose — the
/// *index* of a subscript is an ordinary expression (`xs[i + 1] = v` writes a
/// place), where a narrowing needs the index itself to be stable.
fn is_assignable_place(expr: &Expr) -> bool {
    match expr {
        Expr::Ident(_) => true,
        // A tuple element is rejected with its own message, so it is
        // "shaped like" a place here and one mistake stays one diagnostic.
        Expr::Field { base, .. } | Expr::TupleIndex { base, .. } | Expr::Index { base, .. } => {
            is_assignable_place(base)
        }
        _ => false,
    }
}

fn is_place_expr(expr: &Expr) -> bool {
    match expr {
        Expr::Ident(_) => true,
        Expr::Field { base, .. } | Expr::TupleIndex { base, .. } => is_place_expr(base),
        Expr::Index { base, index, .. } => is_place_expr(base) && is_place_expr(index),
        _ => false,
    }
}

/// [is-bind-once] Every `is` **with a binding** inside a condition, with its
/// subject: the shapes whose subject is read twice (once by the test, once by
/// the binding) unless the emitters hoist it.
fn collect_binding_is<'a>(cond: &'a Expr, f: &mut impl FnMut(&'a Expr, Span)) {
    match cond {
        Expr::Is {
            subject,
            binding: Some(_),
            span,
            ..
        } => f(subject, *span),
        Expr::Is { subject, .. } => collect_binding_is(subject, f),
        Expr::Unary { operand, .. } => collect_binding_is(operand, f),
        Expr::Binary { lhs, rhs, .. } => {
            collect_binding_is(lhs, f);
            collect_binding_is(rhs, f);
        }
        _ => {}
    }
}

/// Whether two spans share any position (one written inside the other, as a
/// parameter's name sits inside the parameter).
/// [ir-nodes] The key of `Checked::written_types`: the AST node's address.
/// The program's AST is immutable and shared by the checker and the IR
/// builder, so the address identifies the written type across both.
pub fn written_type_key(ty: &ast::Type) -> usize {
    ty as *const ast::Type as usize
}

fn spans_overlap(a: Span, b: Span) -> bool {
    // [node-origin] Positions compare within one expansion only.
    a.expn == b.expn && a.start <= b.end && b.start <= a.end
}

/// [mod-namespace] A readable list of a union's arm type names, for the
/// leading-dot resolution diagnostics.
fn arm_names(arms: &[Ty]) -> String {
    let mut out: Vec<String> = Vec::new();
    for arm in arms {
        if let Ty::Named { name, .. } = arm.strip_quals() {
            let base = name.split('§').next().unwrap_or(name).to_string();
            out.push(format!("`{base}`"));
        }
    }
    if out.is_empty() {
        "none".to_string()
    } else {
        out.join(", ")
    }
}

/// [mod-namespace] The dotted namespace path of a `Field`/`Ident` expression
/// whose every segment is an uppercase name — `Outer.Inner` from the base of
/// `Outer.Inner.make`. `None` when any segment is lowercase (a value
/// receiver, not a namespace) or the shape is anything but a straight
/// field/ident chain. The caller joins it with the lowercase leaf to form the
/// flat fn key the flattener produced.
fn namespace_path_of(expr: &Expr) -> Option<String> {
    match expr {
        Expr::Ident(id) if id.name.chars().next().is_some_and(|c| c.is_uppercase()) => {
            Some(id.name.clone())
        }
        Expr::Field { base, field, .. }
            if field.name.chars().next().is_some_and(|c| c.is_uppercase()) =>
        {
            let head = namespace_path_of(base)?;
            Some(format!("{head}.{}", field.name))
        }
        _ => None,
    }
}

/// [is-narrowing] A union under `proj` alone — a borrowed element of a
/// `List<P?>` — tests like the union itself: the qualifier says where the
/// value lives, and the runtime shape is the union's.
fn strip_ret_arm_proj(ty: &Ty) -> Ty {
    match ty {
        Ty::Fn { params, ret, contract, effects } => Ty::Fn {
            params: params.clone(),
            ret: Box::new(match ret.as_ref() {
                Ty::Union(arms) => Ty::Union(arms.iter().map(|a| a.strip_top_proj()).collect()),
                other => other.strip_top_proj(),
            }),
            contract: contract.clone(),
            effects: effects.clone(),
        },
        other => other.clone(),
    }
}

fn strip_proj_union(ty: &Ty) -> &Ty {
    match ty {
        Ty::Qualified { quals, base } if matches!(base.as_ref(), Ty::Union(_)) && quals.iter().all(|q| crate::types::is_proj_name(&q.name)) => base,
        other => other,
    }
}

/// [ref-notsame] The handle-identity claim's name: it is about which element
/// a handle is, so a write *through* a handle leaves it standing; only
/// rebinding strips it.
const NOT_SAME: &str = "NotSame";

fn with_identity(preserve: &[String]) -> Vec<String> {
    let mut p = preserve.to_vec();
    p.push(NOT_SAME.to_string());
    p
}

/// [ref-anchor] The container a parameter's `ref(c)` names, when its written
/// type is a top-level `ref(c)` handle (`a: ref(c) Mut T`).
pub fn ref_anchor_of(ty: &ast::Type) -> Option<&Ident> {
    let quals = match ty {
        ast::Type::Named { qualifiers, .. } | ast::Type::QualifiedGroup { qualifiers, .. } => qualifiers,
        _ => return None,
    };
    let r = quals.iter().find(|q| q.name.name == "ref")?;
    match r.from.as_slice() {
        [c] => Some(c),
        _ => None,
    }
}

/// [ref-handle] Whether a type is a `ref` handle at its top level or in any
/// union arm (an optional handle is `ref(c) Mut T?`).
fn has_ref_arm(ty: &Ty) -> bool {
    match ty {
        Ty::Union(arms) => arms.iter().any(has_ref_arm),
        Ty::Qualified { base, .. } => ty.is_ref() || has_ref_arm(base),
        _ => false,
    }
}

impl<'p, 'r> Checker<'p, 'r> {
    /// [ref-handle] The reader a returned value comes from, if any: a call
    /// whose recorded type has no `ref` arm (through `!`), or a local bound
    /// from one. Answers the reader's name, for the diagnostic.
    fn reader_call(&self, e: &Expr) -> Option<String> {
        match e {
            e if e.presence_unwrapped().is_some() => self.reader_call(e.presence_unwrapped().unwrap()),
            Expr::Ident(id) => self.reader_bound.get(&id.name).cloned(),
            Expr::Call { callee, span, .. } => {
                let t = self.out.expr_ty.get(&self.key(*span))?;
                if has_ref_arm(t) {
                    return None;
                }
                Some(match callee.as_ref() {
                    Expr::Ident(id) => id.name.clone(),
                    _ => "the callee".to_string(),
                })
            }
            _ => None,
        }
    }
}

/// [ref-handle] The mint's `proj → ref` promotion: every `proj` qualifier at
/// the top level or in a union arm becomes `ref`.
fn promote_proj_to_ref(ty: Ty) -> Ty {
    match ty {
        Ty::Union(arms) => Ty::Union(arms.into_iter().map(promote_proj_to_ref).collect()),
        Ty::Qualified { quals, base } => Ty::Qualified {
            quals: quals
                .into_iter()
                .map(|mut q| {
                    if q.name == "proj" {
                        q.name = "ref".to_string();
                    }
                    q
                })
                .collect(),
            base: Box::new(promote_proj_to_ref(*base)),
        },
        other => other,
    }
}

/// [implicit-same-name] Whether two implicit positions are one: the same
/// parameter and result types, whatever the parameters are called.
fn same_fn_shape(a: &Ty, b: &Ty) -> bool {
    match (a.strip_quals(), b.strip_quals()) {
        (Ty::Fn { params: pa, ret: ra, .. }, Ty::Fn { params: pb, ret: rb, .. }) => pa == pb && ra == rb,
        _ => a == b,
    }
}

/// [fn-value] What [`Checker::fn_value_at`] makes of a declaration at a fn
/// type: the value's type, the implicits it fills in turn, and how its
/// generics bound.
struct FnValueAt {
    ty: Ty,
    nested: Vec<ImplicitArg>,
    binding: HashMap<String, Ty>,
}

/// [fn-value] [implicit-resolve] A declaration that fits a fn type, before
/// its own implicits are filled: what selection compares.
struct FnFit {
    ty: Ty,
    binding: HashMap<String, Ty>,
    generics: HashSet<String>,
    /// The explicit shape fitted, so the candidate's own implicits are
    /// filled where it is used [implicit-recursive].
    fills: bool,
    /// The full shape fitted: the position passes the implicits itself.
    passes_own: bool,
    /// The fitted shape's declared parameter types, for the ranking
    /// [fn-overload-rank].
    patterns: Vec<Ty>,
    variadic: bool,
}

/// [effect-member-overload] [effect-available] An available effect's member
/// as a candidate for a fn-typed position (R10 D3: effect members fill every
/// position a fn does): the member, and the instance in scope it dispatches
/// through — passed as a value, it carries that instance.
#[derive(Clone)]
struct MemberCand<'p> {
    effect: &'p EffectDecl,
    decl: &'p FnDecl,
    /// The member's index among the effect's `fns` [effect-member-overload].
    index: usize,
    instance: Ty,
}

/// [fn-value-select] A candidate for a fn-typed position: a declared fn, or
/// an available effect's member (R10 D3), ranked as one set.
#[derive(Clone)]
enum ValueCand<'p> {
    Fn(crate::resolve::FnEntry<'p>),
    Member(MemberCand<'p>),
}

impl<'p> ValueCand<'p> {
    fn decl(&self) -> &'p FnDecl {
        match self {
            ValueCand::Fn(e) => e.decl,
            ValueCand::Member(m) => m.decl,
        }
    }

    /// Where it comes from, as a diagnostic and the `name@…` remedy name it:
    /// a fn's module, a member's effect.
    fn origin(&self) -> String {
        match self {
            ValueCand::Fn(e) => e.module.to_string(),
            ValueCand::Member(m) => m.effect.name.name.clone(),
        }
    }

    /// One declaration (through one instance) is one candidate
    /// [fn-overload-scope].
    fn same(&self, other: &ValueCand<'p>) -> bool {
        match (self, other) {
            (ValueCand::Fn(a), ValueCand::Fn(b)) => a.key == b.key,
            (ValueCand::Member(a), ValueCand::Member(b)) => std::ptr::eq(a.decl, b.decl) && a.instance == b.instance,
            _ => false,
        }
    }

    fn is_template(&self) -> bool {
        matches!(self, ValueCand::Fn(e) if e.rung == crate::resolve::Rung::Template)
    }
}

/// [implicit-resolve] What an implicit position resolved to: a declared fn
/// (its key and the identity a type can carry), or an available effect's
/// member with its own implicits filled (R10 D3).
enum Filled<'p> {
    Fn(DeclId, FnId),
    Member(MemberCand<'p>, Vec<ImplicitArg>),
}

/// [implicit-infer] The callee's variables in `pattern` (an implicit's fn type
/// as far as the call knows it) read back off `have`, the instantiated
/// candidate, extending `base`; `None` where the two do not unify. The
/// parameters are relaxed as the fit is: the *argument's* claims are not the
/// candidate's business, and insisting on them threw away everything the
/// return type had to teach — which is where `It` was being lost.
fn infer_read_back(pattern: &Ty, have: &Ty, base: &HashMap<String, Ty>) -> Option<HashMap<String, Ty>> {
    let (Ty::Fn { params: want_params, ret: want_ret, .. }, Ty::Fn { params: have_params, ret: have_ret, .. }) =
        (pattern.strip_quals(), have.strip_quals())
    else {
        return None;
    };
    if want_params.len() != have_params.len() {
        return None;
    }
    let mut extended = base.clone();
    let ok = want_params.iter().zip(have_params).all(|(want, have)| {
        let mut exact = extended.clone();
        if unify(want, have, &mut exact) {
            extended = exact;
            return true;
        }
        let mut relaxed = extended.clone();
        if unify(want.strip_quals(), have, &mut relaxed) {
            extended = relaxed;
            return true;
        }
        false
    }) && unify(want_ret, have_ret, &mut extended);
    ok.then_some(extended)
}
